var tutorialsDataV5={"tutorial":[{"thumb":"VRC_Tutorial_launchVEXcodeV5.png","mov":"V5_VRC_LaunchVEXcodeV5","description":"Launch VEXcode V5","filter":"","placeholder":false,"vimeo":"","proglang":["blocks"],"progtarget":["virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nTo get started with VEXcode V5\nand VRC Virtual Skills,\n\n2\n00:00:04.754 --> 00:00:05.755\njust type\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\ninto a chrome-based web browser\n\n5\n00:00:10.385 --> 00:00:13.972\non your Mac, Chromebook,\nor Windows computer.\n\n6\n00:00:13.972 --> 00:00:17.058\nNow, to open a new Virtual Skills project,\n\n7\n00:00:17.058 --> 00:00:19.310\nopen the file menu and select\n\n8\n00:00:19.310 --> 00:00:22.022\n\"New Virtual Skills Project.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nNow you are ready to\nget started coding.\n\n","ar":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nللبدء مع VEXcode V5\nومهارات VRC الافتراضية،\n\n2\n00:00:04.754 --> 00:00:05.755\nفقط اكتب\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\nفي متصفح ويب قائم على الكروم\n\n5\n00:00:10.385 --> 00:00:13.972\nعلى جهاز الماك، أو كروم بوك، أو\nأو ويندوز الكمبيوتر.\n\n6\n00:00:13.972 --> 00:00:17.058\nالآن، لفتح مشروع مهارات افتراضية جديد،\n\n7\n00:00:17.058 --> 00:00:19.310\nافتح قائمة الملفات وحدد\n\n8\n00:00:19.310 --> 00:00:22.022\n\"مشروع مهارات افتراضية جديد.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nأنت الآن على استعداد\nلبدء البرمجة.\n\n","cs":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nChceš-li začít s VEXcode V5\na VRC Virtuálními dovednostmi,\n\n2\n00:00:04.754 --> 00:00:05.755\njednoduše napiš\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\ndo internetového prohlížeče založeného na Chromu\n\n5\n00:00:10.385 --> 00:00:13.972\nna tvém Macu, Chromebooku,\nnebo počítači Windows.\n\n6\n00:00:13.972 --> 00:00:17.058\nNyní, pro otevření nového projektu Virtuálních dovedností\n\n7\n00:00:17.058 --> 00:00:19.310\notevři menu Soubor a vyber\n\n8\n00:00:19.310 --> 00:00:22.022\nNový projekt Virtuálních dovedností.\n\n9\n00:00:22.022 --> 00:00:25.859\nNyní je vše připraveno pro\nzačátek kódování.\n\n","fi":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nKun aloitat VEXcode V5 -ohjelmoinnin\nja sen VRC virtuaaliset taidot,\n\n2\n00:00:04.754 --> 00:00:05.755\nkirjoita vain\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\nCrome -verkkoselaimeen\n\n5\n00:00:10.385 --> 00:00:13.972\nMac-, Chromebook-,\ntai Windows-tietokoneella.\n\n6\n00:00:13.972 --> 00:00:17.058\nNyt avataksesi uuden Virtual Skills -projektin,\n\n7\n00:00:17.058 --> 00:00:19.310\navaa Tiedosto -menu ja valitse \n\n8\n00:00:19.310 --> 00:00:22.022\n\"Uusi virtuaalitaitojen projekti.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nNyt olet valmis\naloittamaan koodauksen.\n\n","fr":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nPour démarrer avec VEXcode V5\net les Compétences Virtuelles VRC,\n\n2\n00:00:04.754 --> 00:00:05.755\ntapez simplement\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\ndans un navigateur web basé sur Chrome\n\n5\n00:00:10.385 --> 00:00:13.972\nsur votre Mac, Chromebook,\nou ordinateur sous Windows.\n\n6\n00:00:13.972 --> 00:00:17.058\nMaintenant, pour ouvrir un nouveau projet de Compétences Virtuelles,\n\n7\n00:00:17.058 --> 00:00:19.310\nouvrez le menu \"Fichier\" et sélectionnez\n\n8\n00:00:19.310 --> 00:00:22.022\n\"Nouveau projet de Compétences Virtuelles.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nMaintenant vous êtes prêt à\ncommencer à coder.\n\n","ko":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nVEXcode V5와 VRC 버츄얼 스킬을 시작하려면\n\n2\n00:00:04.754 --> 00:00:05.755\nMac, Chromebook 또는 Windows 컴퓨터의\n\n3\n00:00:05.755 --> 00:00:08.258\n크롬 기반 웹 브라우저에\n\n4\n00:00:08.258 --> 00:00:10.385\ncodev5.vex.com을\n\n5\n00:00:10.385 --> 00:00:13.972\n입력하십시오.\n\n6\n00:00:13.972 --> 00:00:17.058\n이제 새로운 버츄얼 스킬 프로젝트를 열기 위해\n\n7\n00:00:17.058 --> 00:00:19.310\n파일 메뉴에서\n\n8\n00:00:19.310 --> 00:00:22.022\n\"새로운 버츄얼 스킬 프로젝트\"를 선택하세요.\n\n9\n00:00:22.022 --> 00:00:25.859\n이제 코딩을 시작할 준비가 되었습니다.\n\n","nl":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nOm aan de slag te gaan met VEXcode V5\nen VRC Virtuele Vaardigheden,\n\n2\n00:00:04.754 --> 00:00:05.755\ntyp gewoon\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\nin een op Chrome gebaseerde webbrowser\n\n5\n00:00:10.385 --> 00:00:13.972\nop uw Mac, Chromebook,\nof Windows-computer.\n\n6\n00:00:13.972 --> 00:00:17.058\nOm nu een nieuw Virtuele Vaardigheid project te openen\n\n7\n00:00:17.058 --> 00:00:19.310\nopen het bestandsmenu en selecteer\n\n8\n00:00:19.310 --> 00:00:22.022\n\"Nieuw project voor virtuele vaardigheden.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nNu bent u klaar om\naan de slag te gaan met coderen.\n\n","ru":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nЧтобы начать работу с VEXcode V5\nи VRC Virtual Skills,\n\n2\n00:00:04.754 --> 00:00:05.755\nпросто введите\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\nв веб-браузер на базе Chrome\n\n5\n00:00:10.385 --> 00:00:13.972\nна вашем Mac, Chromebook,\nили компьютере с Windows.\n\n6\n00:00:13.972 --> 00:00:17.058\nТеперь, чтобы открыть новый проект виртуальных навыков,\n\n7\n00:00:17.058 --> 00:00:19.310\nоткройте файловое меню и выберите\n\n8\n00:00:19.310 --> 00:00:22.022\n«Новый проект виртуальных навыков».\n\n9\n00:00:22.022 --> 00:00:25.859\nТеперь вы готовы\nприступить к программированию.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\nĐể bắt đầu với VEXcode V5\nvà Kỹ năng ảo VRC,\n\n2\n00:00:04.754 --> 00:00:05.755\nchỉ loại\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\nvào một trình duyệt web dựa trên chrome\n\n5\n00:00:10.385 --> 00:00:13.972\ntrên máy Mac, Chromebook,\nhoặc máy tính Windows của bạn.\n\n6\n00:00:13.972 --> 00:00:17.058\nBây giờ, để mở một dự án Kỹ năng ảo mới,\n\n7\n00:00:17.058 --> 00:00:19.310\nmở menu tệp và chọn\n\n8\n00:00:19.310 --> 00:00:22.022\n\"Dự án kỹ năng ảo mới.\"\n\n9\n00:00:22.022 --> 00:00:25.859\nBây giờ bạn đã sẵn sàng để\nbắt đầu viết mã.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\ncrwdns412753:0crwdne412753:0\n\n2\n00:00:04.754 --> 00:00:05.755\ncrwdns412755:0crwdne412755:0\n\n3\n00:00:05.755 --> 00:00:08.258\ncrwdns412757:0crwdne412757:0\n\n4\n00:00:08.258 --> 00:00:10.385\ncrwdns412759:0crwdne412759:0\n\n5\n00:00:10.385 --> 00:00:13.972\ncrwdns412761:0crwdne412761:0\n\n6\n00:00:13.972 --> 00:00:17.058\ncrwdns412763:0crwdne412763:0\n\n7\n00:00:17.058 --> 00:00:19.310\ncrwdns412765:0crwdne412765:0\n\n8\n00:00:19.310 --> 00:00:22.022\ncrwdns412767:0crwdne412767:0\n\n9\n00:00:22.022 --> 00:00:25.859\ncrwdns412769:0crwdne412769:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.754\n要开始使用 VEXcode V5 和 VRC 虚拟技能，\n\n2\n00:00:04.754 --> 00:00:05.755\n输入\n\n3\n00:00:05.755 --> 00:00:08.258\ncodev5.vex.com\n\n4\n00:00:08.258 --> 00:00:10.385\n到一个基于 Chrome 的网页浏览器\n\n5\n00:00:10.385 --> 00:00:13.972\n在你的 Mac，Chromebook，或 Windows 电脑上。\n\n6\n00:00:13.972 --> 00:00:17.058\n现在，要打开一个新的虚拟技能程序，\n\n7\n00:00:17.058 --> 00:00:19.310\n打开“文件”菜单并选择\n\n8\n00:00:19.310 --> 00:00:22.022\n\"新建虚拟技能程序。\"\n\n9\n00:00:22.022 --> 00:00:25.859\n现在你准备好开始编码了。\n\n"}},{"thumb":"VRC_Tutorial_gettingStarted.png","mov":"V5_VRC_GettingStarted","description":"Getting Started","filter":"","placeholder":false,"vimeo":"","proglang":["blocks"],"progtarget":["virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nIn Virtual Skills, you can code\nyour robot to do many things,\n\n2\n00:00:04.045 --> 00:00:06.589\nand getting started is very easy.\n\n3\n00:00:06.589 --> 00:00:10.510\nEvery project begins with\na \"When Started\" block.\n\n4\n00:00:10.510 --> 00:00:14.889\nThere are many different blocks\nthat you can use to code your robot.\n\n5\n00:00:14.889 --> 00:00:17.642\nJust select and drag blocks to\n\n6\n00:00:17.642 --> 00:00:20.270\nadd them to your project.\n\n7\n00:00:20.270 --> 00:00:23.815\nBlocks can easily be stacked together,\n\n8\n00:00:23.815 --> 00:00:26.026\nrearranged,\n\n9\n00:00:26.026 --> 00:00:28.111\nand deleted.\n\n10\n00:00:28.111 --> 00:00:29.654\nNeed help with a block?\n\n11\n00:00:29.654 --> 00:00:31.072\nGetting help is easy,\n\n12\n00:00:31.072 --> 00:00:32.907\njust select the help icon\n\n13\n00:00:32.907 --> 00:00:35.869\nand then select a block\nto learn how it works.\n\n14\n00:00:35.869 --> 00:00:38.204\nAnother great place to learn different blocks\n\n15\n00:00:38.204 --> 00:00:40.999\nand behaviors is from Example Projects.\n\n16\n00:00:40.999 --> 00:00:44.544\nWe've created a few Example\nProjects that can help you.\n\n17\n00:00:44.544 --> 00:00:46.713\nOne of the best features of VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nis the context menu.\n\n19\n00:00:48.131 --> 00:00:51.051\nRight-click on a block or\na stack of blocks\n\n20\n00:00:51.051 --> 00:00:54.846\nto duplicate,\n\n21\n00:00:54.846 --> 00:00:57.265\ndisable,\n\n22\n00:00:57.265 --> 00:00:59.476\nor delete blocks.\n\n23\n00:00:59.476 --> 00:01:01.895\nIf you right-click in the workspace,\n\n24\n00:01:01.895 --> 00:01:03.563\nyou can use other options\n\n25\n00:01:03.563 --> 00:01:05.648\nlike undo\n\n26\n00:01:05.648 --> 00:01:08.068\nand redo.\n\n27\n00:01:08.068 --> 00:01:10.195\nOnce you are ready\nto try your project,\n\n28\n00:01:10.195 --> 00:01:13.239\nyou can select Start\nto run your project.\n\n29\n00:01:13.239 --> 00:01:14.616\nWhen you are done coding,\n\n30\n00:01:14.616 --> 00:01:16.659\nyou can download a\ncopy of your project\n\n31\n00:01:16.659 --> 00:01:19.996\nby selecting \"Save To Your Device.\"\n\n32\n00:01:19.996 --> 00:01:21.664\nLooking for some more information\n\n33\n00:01:21.664 --> 00:01:22.916\nabout Virtual Skills\n\n34\n00:01:22.916 --> 00:01:24.542\nor just about VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nCheck out our Knowledge Base at\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nThanks and have fun coding!\n\n","ar":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nفي المهارات الافتراضية يمكنك برمجة\nالروبوت الخاص بك للقيام بعدة أشياء،\n\n2\n00:00:04.045 --> 00:00:06.589\nوالبدء في العمل أمر سهل جدا.\n\n3\n00:00:06.589 --> 00:00:10.510\nيبدأ كل مشروع بمقطع\"عند البدء\".\n\n4\n00:00:10.510 --> 00:00:14.889\nهناك العديد من البلوكات البرمجية المختلفة\nالتي يمكنك استخدامها لبرمجة الروبوت الخاص بك.\n\n5\n00:00:14.889 --> 00:00:17.642\nفقط حدد وسحب البلوكات البرمجية لكى\n\n6\n00:00:17.642 --> 00:00:20.270\nتضيفهم فى مشروعك.\n\n7\n00:00:20.270 --> 00:00:23.815\nيمكن إضافة الأوامر واعادة ترتيبها بسهولة،\n\n8\n00:00:23.815 --> 00:00:26.026\nاو تعيد ترتيبهم\n\n9\n00:00:26.026 --> 00:00:28.111\nوالحذف.\n\n10\n00:00:28.111 --> 00:00:29.654\nهل تحتاج إلى مساعدة مع أحد الأوامر ؟\n\n11\n00:00:29.654 --> 00:00:31.072\nالحصول على المساعدة أمر سهل,\n\n12\n00:00:31.072 --> 00:00:32.907\nفقط قم باختيار رمز المساعدة\n\n13\n00:00:32.907 --> 00:00:35.869\nثم حدد بلوك\nلمعرفة كيفية عملها.\n\n14\n00:00:35.869 --> 00:00:38.204\nمكان رائع آخر لتعلم بلوكات مختلفة\n\n15\n00:00:38.204 --> 00:00:40.999\nوالسلوكيات هي من أمثلة المشاريع.\n\n16\n00:00:40.999 --> 00:00:44.544\nلقد أنشأنا بعض الأمثلة\nعلى المشاريع التي يمكن أن تساعدك.\n\n17\n00:00:44.544 --> 00:00:46.713\nواحدة من أفضل ميزات VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nهي قائمة السياق.\n\n19\n00:00:48.131 --> 00:00:51.051\nانقر بالزر الأيمن على بلوك أو\nتسلسل من البلوكات\n\n20\n00:00:51.051 --> 00:00:54.846\nلإنشاء نسخة منه\n\n21\n00:00:54.846 --> 00:00:57.265\nاو تعطيله\n\n22\n00:00:57.265 --> 00:00:59.476\nاو حذف بلوكات منه.\n\n23\n00:00:59.476 --> 00:01:01.895\nإذا قمت بالنقر بالزر الأيمن في مساحة العمل،\n\n24\n00:01:01.895 --> 00:01:03.563\nيمكنك استخدام خيارات أخرى\n\n25\n00:01:03.563 --> 00:01:05.648\nمثل التراجع\n\n26\n00:01:05.648 --> 00:01:08.068\nو أعد العمل.\n\n27\n00:01:08.068 --> 00:01:10.195\nبمجرد أن تكون جاهزاً لتجربة مشروعك،\n\n28\n00:01:10.195 --> 00:01:13.239\nيمكنك إختيار بدء\nلتشغيل مشروعك.\n\n29\n00:01:13.239 --> 00:01:14.616\nعند الانتهاء من البرمجة،\n\n30\n00:01:14.616 --> 00:01:16.659\nيمكنك تنزيل نسخة من مشروعك\n\n31\n00:01:16.659 --> 00:01:19.996\nعن طريق تحديد الحفظ على جهازك.\"\n\n32\n00:01:19.996 --> 00:01:21.664\nأتبحث عن معلومات أكثر\n\n33\n00:01:21.664 --> 00:01:22.916\nحول المهارات الافتراضية\n\n34\n00:01:22.916 --> 00:01:24.542\nأم فقط حول VEXcode؟\n\n35\n00:01:24.542 --> 00:01:26.336\nتحقق من قاعدة المعرفة لدينا في\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nشكرا و استمتع بالبرمجة!\n\n","cs":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nVe Virtuálních dovednostech můžeš svého\nrobota naprogramovat, aby dělal spoustu věcí,\n\n2\n00:00:04.045 --> 00:00:06.589\na začít je velmi snadné.\n\n3\n00:00:06.589 --> 00:00:10.510\nKaždý projekt začíná\nblokem Při spuštění.\n\n4\n00:00:10.510 --> 00:00:14.889\nExistuje mnoho různých bloků,\nkteré můžeš použít k programování svého robota.\n\n5\n00:00:14.889 --> 00:00:17.642\nStačí vybrat a přetáhnout bloky\n\n6\n00:00:17.642 --> 00:00:20.270\npro jejich přidání do tvého projektu.\n\n7\n00:00:20.270 --> 00:00:23.815\nBloky mohou být jednoduše spojeny dohromady,\n\n8\n00:00:23.815 --> 00:00:26.026\npřeskupeny\n\n9\n00:00:26.026 --> 00:00:28.111\na smazány.\n\n10\n00:00:28.111 --> 00:00:29.654\nPotřebuješ s nějakým blokem pomoci?\n\n11\n00:00:29.654 --> 00:00:31.072\nZískat pomoc je snadné,\n\n12\n00:00:31.072 --> 00:00:32.907\nstačí vybrat ikonku Nápověda\n\n13\n00:00:32.907 --> 00:00:35.869\na potom vybrat blok\npro vysvětlení jak funguje.\n\n14\n00:00:35.869 --> 00:00:38.204\nDalší skvělé místo k učení různých bloků\n\n15\n00:00:38.204 --> 00:00:40.999\na jejich chování jsou Ukázkové projekty.\n\n16\n00:00:40.999 --> 00:00:44.544\nVytvořili jsme několik Ukázkových\nProjektů, které ti mohou pomoci.\n\n17\n00:00:44.544 --> 00:00:46.713\nJeden z nejlepších prvků VECcode\n\n18\n00:00:46.713 --> 00:00:48.131\nje kontextové menu.\n\n19\n00:00:48.131 --> 00:00:51.051\nPravé kliknutí na blok, nebo\nzásobník bloků, umožní\n\n20\n00:00:51.051 --> 00:00:54.846\nkopírovat,\n\n21\n00:00:54.846 --> 00:00:57.265\nzakázat,\n\n22\n00:00:57.265 --> 00:00:59.476\nnebo vymazat bloky.\n\n23\n00:00:59.476 --> 00:01:01.895\nJestliže klikneš pravým do pracovního prostoru,\n\n24\n00:01:01.895 --> 00:01:03.563\nmůžeš použít další možnosti,\n\n25\n00:01:03.563 --> 00:01:05.648\njako je Vrátit zpět\n\n26\n00:01:05.648 --> 00:01:08.068\na Provést znovu.\n\n27\n00:01:08.068 --> 00:01:10.195\nJakmile je tvůj projekt\npřipravený k vyzkoušení,\n\n28\n00:01:10.195 --> 00:01:13.239\nmůžeš vybrat Spustit\npro spuštění tvého projektu.\n\n29\n00:01:13.239 --> 00:01:14.616\nJakmile s programováním skončíš,\n\n30\n00:01:14.616 --> 00:01:16.659\nmůžeš si stáhnout\nkopii svého projektu\n\n31\n00:01:16.659 --> 00:01:19.996\nvybráním Uložit do vašeho zařízení.\n\n32\n00:01:19.996 --> 00:01:21.664\nHledáš další informace\n\n33\n00:01:21.664 --> 00:01:22.916\no Virtuálních dovednostech,\n\n34\n00:01:22.916 --> 00:01:24.542\nnebo prostě jen o VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nPodívej se na naši Knowledge Base na\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nDíky a užij si kódování!\n\n","de":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nIn virtuellen Fähigkeiten kannst du\ndeinen Roboter programmieren, um viele Dinge zu tun\n\n2\n00:00:04.045 --> 00:00:06.589\nund loszulegen ist sehr einfach.\n\n3\n00:00:06.589 --> 00:00:10.510\nJedes Projekt beginnt mit einem \"wenn gestartet\" Block.\n\n4\n00:00:10.510 --> 00:00:14.889\nEs gibt viele verschiedene Blöcke, die du verwenden kannst, um deinen Roboter zu codieren.\n\n5\n00:00:14.889 --> 00:00:17.642\nEinfach Blöcke auswählen und ziehen um\n\n6\n00:00:17.642 --> 00:00:20.270\ndiese deinem Projekt hinzuzufügen.\n\n7\n00:00:20.270 --> 00:00:23.815\nBlöcke können einfach zusammen gestapelt werden\n\n8\n00:00:23.815 --> 00:00:26.026\nneu angeordnet,\n\n9\n00:00:26.026 --> 00:00:28.111\nund gelöscht werden.\n\n10\n00:00:28.111 --> 00:00:29.654\nBrauchst du Hilfe bei einem Block?\n\n11\n00:00:29.654 --> 00:00:31.072\nHilfe zu erhalten ist einfach,\n\n12\n00:00:31.072 --> 00:00:32.907\nwähle einfach das Hilfe-Symbol\n\n13\n00:00:32.907 --> 00:00:35.869\nund wähle dann einen Block\n, um zu erfahren, wie es funktioniert.\n\n14\n00:00:35.869 --> 00:00:38.204\nEin weiterer großartiger Ort, um verschiedene Blöcke zu lernen\n\n15\n00:00:38.204 --> 00:00:40.999\nist von Beispiel-Projekten.\n\n16\n00:00:40.999 --> 00:00:44.544\nWir haben ein paar Beispiele\nProjekte erstellt, die dir helfen können.\n\n17\n00:00:44.544 --> 00:00:46.713\nEines der besten Funktionen von VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nist das Kontextmenü.\n\n19\n00:00:48.131 --> 00:00:51.051\nRechtsklicke auf einen Block oder\neinen Stapel Blöcke um,\n\n20\n00:00:51.051 --> 00:00:54.846\nzu duplizieren,\n\n21\n00:00:54.846 --> 00:00:57.265\ndeaktivieren,\n\n22\n00:00:57.265 --> 00:00:59.476\noder Blöcke entfernen.\n\n23\n00:00:59.476 --> 00:01:01.895\nWenn du mit der rechten Maustaste im Arbeitsbereich klickst\n\n24\n00:01:01.895 --> 00:01:03.563\nkannst du andere Optionen verwenden\n\n25\n00:01:03.563 --> 00:01:05.648\nwie rückgängig\n\n26\n00:01:05.648 --> 00:01:08.068\nund wieder holen.\n\n27\n00:01:08.068 --> 00:01:10.195\nSobald du bereit bist dein Projekt auszuprobieren\n\n28\n00:01:10.195 --> 00:01:13.239\nkannst du Start\nwählen, um dein Projekt zu starten.\n\n29\n00:01:13.239 --> 00:01:14.616\nWenn du mit dem Codieren fertig bist,\n\n30\n00:01:14.616 --> 00:01:16.659\nkannst du eine Kopie deines Projekts herunterladen\n\n31\n00:01:16.659 --> 00:01:19.996\nindem du es auf deinem Gerät speicherst.\"\n\n32\n00:01:19.996 --> 00:01:21.664\nSuche nach weiteren Informationen\n\n33\n00:01:21.664 --> 00:01:22.916\nzu Virtuelle Fähigkeiten\n\n34\n00:01:22.916 --> 00:01:24.542\noder nur über VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nSchau dir unsere Wissensdatenbank an\n\n36\n00:01:26.336 --> 00:01:29.214\nunter, help.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nVielen Dank und viel Spaß beim Programmieren!\n\n","fi":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nVirtuaalitaidoissa voit koodata\nrobottisi tekemään monia asioita,\n\n2\n00:00:04.045 --> 00:00:06.589\nja aloittaminen on erittäin helppoa.\n\n3\n00:00:06.589 --> 00:00:10.510\nJokaisen ohjelman alussa pitää olla Kun käynnissä -blokki.\n\n4\n00:00:10.510 --> 00:00:14.889\nVoit käyttää monia eri blokkeja, joita voit käyttää robottisi koodaamiseen.\n\n5\n00:00:14.889 --> 00:00:17.642\nValitse ja vedä blokkeja vain\n\n6\n00:00:17.642 --> 00:00:20.270\nosaksi ohjelmaasi.\n\n7\n00:00:20.270 --> 00:00:23.815\nBlokkeja voi helposti pinota päällekkäin,\n\n8\n00:00:23.815 --> 00:00:26.026\njärjestää uudelleen\n\n9\n00:00:26.026 --> 00:00:28.111\nja poistaa.\n\n10\n00:00:28.111 --> 00:00:29.654\nTarvitsetko apua blokkien valintaan?\n\n11\n00:00:29.654 --> 00:00:31.072\nAvun saaminen on helppoa,\n\n12\n00:00:31.072 --> 00:00:32.907\nvalitse vain Kysymysmerkki -kuvake\n\n13\n00:00:32.907 --> 00:00:35.869\nvalitse vain blokki, niin saat tietää, miten se toimii.\n\n14\n00:00:35.869 --> 00:00:38.204\nToinen hyvä tapa oppia eri blokkien käytöstä\n\n15\n00:00:38.204 --> 00:00:40.999\nja käyttäytymistä on tutustua esimerkkiprojekteihin.\n\n16\n00:00:40.999 --> 00:00:44.544\nOlemme luoneet muutamia esimerkkejä, jotkas voivat auttaa sinua.\n\n17\n00:00:44.544 --> 00:00:46.713\nYksi parhaista ominaisuuksista VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\non käytää apuna kontekstivalikkoa.\n\n19\n00:00:48.131 --> 00:00:51.051\nNapsauta blokkia hiiren oikealla painikkeella tai\nblokkipinon pintaa\n\n20\n00:00:51.051 --> 00:00:54.846\nkun haluat kopioida,\n\n21\n00:00:54.846 --> 00:00:57.265\npoistaa käytöstä,\n\n22\n00:00:57.265 --> 00:00:59.476\ntai poistaa pinoja.\n\n23\n00:00:59.476 --> 00:01:01.895\nJos klikkaa hiiren kakkospainikkeella työtilassa,\n\n24\n00:01:01.895 --> 00:01:03.563\nvoit käyttää muita vaihtoehtoja\n\n25\n00:01:03.563 --> 00:01:05.648\nkuten kumota\n\n26\n00:01:05.648 --> 00:01:08.068\nja uudelleen tehdä.\n\n27\n00:01:08.068 --> 00:01:10.195\nKun olet valmis käynnistämään uuden ohjelman,\n\n28\n00:01:10.195 --> 00:01:13.239\nvalitse Alkaa -komento.\n\n29\n00:01:13.239 --> 00:01:14.616\nKun olet tehnyt koodauksen,\n\n30\n00:01:14.616 --> 00:01:16.659\nvoit tallentaa kopion ohjelmastasi\n\n31\n00:01:16.659 --> 00:01:19.996\nvalitsemalla Tallenna omalle laitteelle Tiedosto-valikosta.\n\n32\n00:01:19.996 --> 00:01:21.664\nEtsitkö lisää tietoa\n\n33\n00:01:21.664 --> 00:01:22.916\nvirtuaalitaidoista \n\n34\n00:01:22.916 --> 00:01:24.542\ntai vain VEXcode ohjelmasta?\n\n35\n00:01:24.542 --> 00:01:26.336\nTutustu tietokantaamme osoitteessa\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nKiitos ja nauti ohjelmoinnista!\n\n","fr":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nDans les Compétences Virtuelles, vous pouvez coder votre robot pour faire beaucoup de choses,\n\n2\n00:00:04.045 --> 00:00:06.589\net commencer est très facile.\n\n3\n00:00:06.589 --> 00:00:10.510\nTout projet démarre avec un bloc \"Au démarrage\".\n\n4\n00:00:10.510 --> 00:00:14.889\nIl y a de nombreux blocs différents\nque vous pouvez utiliser pour coder votre robot.\n\n5\n00:00:14.889 --> 00:00:17.642\nIl suffit de sélectionner et de faire glisser les blocs\n\n6\n00:00:17.642 --> 00:00:20.270\npour les ajouter à votre projet.\n\n7\n00:00:20.270 --> 00:00:23.815\nLes blocs peuvent être facilement empilés,\n\n8\n00:00:23.815 --> 00:00:26.026\nréorganisé,\n\n9\n00:00:26.026 --> 00:00:28.111\net supprimés.\n\n10\n00:00:28.111 --> 00:00:29.654\nBesoin d'aide avec un bloc ?\n\n11\n00:00:29.654 --> 00:00:31.072\nIl est facile d'obtenir de l'aide,\n\n12\n00:00:31.072 --> 00:00:32.907\nil suffit de sélectionner l'icône d'aide\n\n13\n00:00:32.907 --> 00:00:35.869\npuis de choisir un bloc pour apprendre comment il fonctionne.\n\n14\n00:00:35.869 --> 00:00:38.204\nUn autre endroit idéal pour apprendre les différents blocs\n\n15\n00:00:38.204 --> 00:00:40.999\net comportements sont les Exemples de Projets.\n\n16\n00:00:40.999 --> 00:00:44.544\nNous avons créé quelques exemples de\nprojets qui peuvent vous aider.\n\n17\n00:00:44.544 --> 00:00:46.713\nUne des meilleures fonctionnalités de VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nest le menu contextuel.\n\n19\n00:00:48.131 --> 00:00:51.051\nFaites un clic droit sur un bloc ou\nune pile de blocs\n\n20\n00:00:51.051 --> 00:00:54.846\npour dupliquer,\n\n21\n00:00:54.846 --> 00:00:57.265\ndésactiver,\n\n22\n00:00:57.265 --> 00:00:59.476\nou supprimer des blocs.\n\n23\n00:00:59.476 --> 00:01:01.895\nSi vous faites un clic droit dans l'espace de travail,\n\n24\n00:01:01.895 --> 00:01:03.563\nvous pouvez utiliser d'autres options\n\n25\n00:01:03.563 --> 00:01:05.648\ncomme annuler\n\n26\n00:01:05.648 --> 00:01:08.068\net refaire.\n\n27\n00:01:08.068 --> 00:01:10.195\nUne fois que vous êtes prêt\nà essayer votre projet,\n\n28\n00:01:10.195 --> 00:01:13.239\nvous pouvez sélectionner Démarrer\npour exécuter votre projet.\n\n29\n00:01:13.239 --> 00:01:14.616\nLorsque vous avez terminé de coder,\n\n30\n00:01:14.616 --> 00:01:16.659\nvous pouvez télécharger une copie de\nde votre projet\n\n31\n00:01:16.659 --> 00:01:19.996\nen sélectionnant \"Enregistrer sur votre appareil.\"\n\n32\n00:01:19.996 --> 00:01:21.664\nVous cherchez plus d’informations\n\n33\n00:01:21.664 --> 00:01:22.916\nà propos des Compétences Virtuelles\n\n34\n00:01:22.916 --> 00:01:24.542\nou simplement sur VEXcode ?\n\n35\n00:01:24.542 --> 00:01:26.336\nConsultez notre base de connaissances sur\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nMerci et amusez-vous à coder !\n\n","ko":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\n버츄얼 스킬에서 로봇을 코딩하여 많은 작업을 수행할 수 있고,\n\n2\n00:00:04.045 --> 00:00:06.589\n시작하는 것은 매우 쉽습니다.\n\n3\n00:00:06.589 --> 00:00:10.510\n모든 프로젝트는 \"시작하기\" 블록으로 시작합니다.\n\n4\n00:00:10.510 --> 00:00:14.889\n로봇을 코딩하는 데 사용할 수 있는 다양한 블록이 있습니다.\n\n5\n00:00:14.889 --> 00:00:17.642\n프로젝트에 추가할 블록을\n\n6\n00:00:17.642 --> 00:00:20.270\n선택하고 끌어오기만 하면 됩니다.\n\n7\n00:00:20.270 --> 00:00:23.815\n블록은 쉽게 연결,\n\n8\n00:00:23.815 --> 00:00:26.026\n재배치,\n\n9\n00:00:26.026 --> 00:00:28.111\n삭제될 수 있습니다.\n\n10\n00:00:28.111 --> 00:00:29.654\n블록에 대해 더 알고 싶은가요?\n\n11\n00:00:29.654 --> 00:00:31.072\n쉽게 도움을 얻을 수 있습니다,\n\n12\n00:00:31.072 --> 00:00:32.907\n도움말 아이콘을 선택하고\n\n13\n00:00:32.907 --> 00:00:35.869\n어떻게 작동하는지 알고 싶은 블록을 선택하세요.\n\n14\n00:00:35.869 --> 00:00:38.204\n여러 블록과 동작을 배울 수 있는 또 다른 좋은 방법은\n\n15\n00:00:38.204 --> 00:00:40.999\n예제 프로젝트를 활용하는 것입니다.\n\n16\n00:00:40.999 --> 00:00:44.544\n도움이 될만한 몇 가지 예제 프로젝트를 만들어 보았습니다.\n\n17\n00:00:44.544 --> 00:00:46.713\nVEXcode의 최고의 기능 중 하나는\n\n18\n00:00:46.713 --> 00:00:48.131\n컨텍스트 메뉴입니다.\n\n19\n00:00:48.131 --> 00:00:51.051\n블록 또는 블록 스택을 선택 후 마우스 우클릭하여\n\n20\n00:00:51.051 --> 00:00:54.846\n블록을 복사,\n\n21\n00:00:54.846 --> 00:00:57.265\n비활성화,\n\n22\n00:00:57.265 --> 00:00:59.476\n삭제할 수 있습니다.\n\n23\n00:00:59.476 --> 00:01:01.895\n작업 공간에서 마우스 우클릭하면\n\n24\n00:01:01.895 --> 00:01:03.563\n실행 취소,\n\n25\n00:01:03.563 --> 00:01:05.648\n재실행 같은\n\n26\n00:01:05.648 --> 00:01:08.068\n다른 옵션을 사용할 수 있습니다.\n\n27\n00:01:08.068 --> 00:01:10.195\n프로젝트를 시도할 준비가 되면\n\n28\n00:01:10.195 --> 00:01:13.239\n시작을 선택하여 프로젝트를 실행할 수 있습니다.\n\n29\n00:01:13.239 --> 00:01:14.616\n코딩이 끝나면,\n\n30\n00:01:14.616 --> 00:01:16.659\n\"기기에 저장\"을 선택하여\n\n31\n00:01:16.659 --> 00:01:19.996\n프로젝트의 사본을 다운로드할 수 있습니다.\n\n32\n00:01:19.996 --> 00:01:21.664\n버츄얼 스킬에 대한\n\n33\n00:01:21.664 --> 00:01:22.916\n자세한 정보가 필요하거나\n\n34\n00:01:22.916 --> 00:01:24.542\nVEXcode에 대해서만 알고 싶으신가요?\n\n35\n00:01:24.542 --> 00:01:26.336\nhelp.vex.com를 방문하셔서\n\n36\n00:01:26.336 --> 00:01:29.214\n도움말을 확인해 보세요.\n\n37\n00:01:29.214 --> 00:01:31.466\n감사합니다. 즐거운 코딩하세요!\n\n","nl":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nIn virtuele vaardigheden kunt u\nrobot programmeren om veel dingen te doen\n\n2\n00:00:04.045 --> 00:00:06.589\nen aan de slag gaan is heel eenvoudig.\n\n3\n00:00:06.589 --> 00:00:10.510\nElk project begint met\neen \"Wanneer gestart\" blok.\n\n4\n00:00:10.510 --> 00:00:14.889\nEr zijn veel verschillende blokken\ndie u kunt gebruiken om uw robot te coderen.\n\n5\n00:00:14.889 --> 00:00:17.642\nSelecteer en sleep blokken om\n\n6\n00:00:17.642 --> 00:00:20.270\nze toe aan uw project toe te voegen.\n\n7\n00:00:20.270 --> 00:00:23.815\nBlokken kunnen eenvoudig op elkaar worden gestapeld,\n\n8\n00:00:23.815 --> 00:00:26.026\nherschikt,\n\n9\n00:00:26.026 --> 00:00:28.111\nen verwijderd.\n\n10\n00:00:28.111 --> 00:00:29.654\nHulp nodig met een blok?\n\n11\n00:00:29.654 --> 00:00:31.072\nHulp krijgen is eenvoudig,\n\n12\n00:00:31.072 --> 00:00:32.907\nselecteer gewoon het helppictogram\n\n13\n00:00:32.907 --> 00:00:35.869\nen selecteer vervolgens een blok\nom te leren hoe het werkt.\n\n14\n00:00:35.869 --> 00:00:38.204\nNog een geweldige plek om verschillende blokken\n\n15\n00:00:38.204 --> 00:00:40.999\nen gedrag te leren is van voorbeeldprojecten.\n\n16\n00:00:40.999 --> 00:00:44.544\nWe hebben een aantal\n-voorbeeldprojecten gemaakt die u kunnen helpen.\n\n17\n00:00:44.544 --> 00:00:46.713\nEen van de beste eigenschappen van VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nis het contextmenu.\n\n19\n00:00:48.131 --> 00:00:51.051\nKlik met de rechtermuisknop op een blok of\neen stapel blokken\n\n20\n00:00:51.051 --> 00:00:54.846\ndupliceren,\n\n21\n00:00:54.846 --> 00:00:57.265\nuitzetten,\n\n22\n00:00:57.265 --> 00:00:59.476\nof verwijder blokken.\n\n23\n00:00:59.476 --> 00:01:01.895\nAls u met de rechtermuisknop in de werkruimte klikt,\n\n24\n00:01:01.895 --> 00:01:03.563\nu kunt andere opties gebruiken\n\n25\n00:01:03.563 --> 00:01:05.648\nzoals ongedaan maken\n\n26\n00:01:05.648 --> 00:01:08.068\nen opnieuw doen.\n\n27\n00:01:08.068 --> 00:01:10.195\nZodra u klaar bent\nom uw project uit te proberen,\n\n28\n00:01:10.195 --> 00:01:13.239\nu kunt Start\nselecteren om uw project uit te voeren.\n\n29\n00:01:13.239 --> 00:01:14.616\nAls u klaar bent met coderen,\n\n30\n00:01:14.616 --> 00:01:16.659\nu kunt een\nkopie van uw project downloaden\n\n31\n00:01:16.659 --> 00:01:19.996\ndoor \"Opslaan op uw apparaat\" te selecteren\n\n32\n00:01:19.996 --> 00:01:21.664\nOp zoek naar wat meer informatie\n\n33\n00:01:21.664 --> 00:01:22.916\nover virtuele vaardigheden\n\n34\n00:01:22.916 --> 00:01:24.542\nof alleen over VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nBekijk onze Kennis Basis op\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nBedankt en veel plezier met coderen!\n\n","ru":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nВ Virtual Skills вы можете запрограммировать\nсвоего робота на выполнение множества действий\n\n2\n00:00:04.045 --> 00:00:06.589\nи легко начать.\n\n3\n00:00:06.589 --> 00:00:10.510\nКаждый проект начинается с\nблока \"Начала программы\".\n\n4\n00:00:10.510 --> 00:00:14.889\nСуществует множество различных блоков,\nкоторые вы можете использовать для программирования\nсвоего робота.\n\n5\n00:00:14.889 --> 00:00:17.642\nПросто выберите и перетащите блоки\nв рабочую область\n\n6\n00:00:17.642 --> 00:00:20.270\nдля добавления в проект.\n\n7\n00:00:20.270 --> 00:00:23.815\nБлоки легко могут быть соединены между собой,\n\n8\n00:00:23.815 --> 00:00:26.026\nпереставлены\n\n9\n00:00:26.026 --> 00:00:28.111\nили удалить.\n\n10\n00:00:28.111 --> 00:00:29.654\nНужна помощь с блоком?\n\n11\n00:00:29.654 --> 00:00:31.072\nЭто легко осуществимо,\n\n12\n00:00:31.072 --> 00:00:32.907\nпросто выберите значок справки,\n\n13\n00:00:32.907 --> 00:00:35.869\nа затем выберите блок,\nчтобы узнать, как он работает.\n\n14\n00:00:35.869 --> 00:00:38.204\nЕще одно отличное место для изучения разных блоков\n\n15\n00:00:38.204 --> 00:00:40.999\nи поведения - это примеров проектов.\n\n16\n00:00:40.999 --> 00:00:44.544\nМы создали несколько примеров проектов,\nкоторые могут вам помочь.\n\n17\n00:00:44.544 --> 00:00:46.713\nОдна из лучших функций VEXcode -\n\n18\n00:00:46.713 --> 00:00:48.131\nэто контекстное меню.\n\n19\n00:00:48.131 --> 00:00:51.051\nЩелкните правой кнопкой мыши блок или\nстопку блоков,\n\n20\n00:00:51.051 --> 00:00:54.846\nчтобы дублировать,\n\n21\n00:00:54.846 --> 00:00:57.265\nотключить\n\n22\n00:00:57.265 --> 00:00:59.476\nили удалить блоки.\n\n23\n00:00:59.476 --> 00:01:01.895\nЕсли щелкнуть правой кнопкой мыши в рабочей области,\n\n24\n00:01:01.895 --> 00:01:03.563\nвы можете использовать другие варианты,\n\n25\n00:01:03.563 --> 00:01:05.648\nнапример, отменить\n\n26\n00:01:05.648 --> 00:01:08.068\nи вернуть.\n\n27\n00:01:08.068 --> 00:01:10.195\nКак только вы будете готовы\nпопробовать свой проект,\n\n28\n00:01:10.195 --> 00:01:13.239\nвы можете выбрать Запуск,\nчтобы запустить проект.\n\n29\n00:01:13.239 --> 00:01:14.616\nКогда вы закончите программировать,\n\n30\n00:01:14.616 --> 00:01:16.659\nвы можете загрузить\nкопию вашего проекта,\n\n31\n00:01:16.659 --> 00:01:19.996\nвыбрав «Сохранить на ваше устройство».\n\n32\n00:01:19.996 --> 00:01:21.664\nИщите дополнительную информацию\n\n33\n00:01:21.664 --> 00:01:22.916\nо виртуальных навыках\n\n34\n00:01:22.916 --> 00:01:24.542\nили VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nОзнакомьтесь с нашей базой знаний на\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nСпасибо и получайте удовольствие от программирования!\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\nTrong Kỹ năng ảo, bạn có thể viết mã\ncho rô bốt của mình để làm nhiều việc,\n\n2\n00:00:04.045 --> 00:00:06.589\nvà bắt đầu rất dễ dàng.\n\n3\n00:00:06.589 --> 00:00:10.510\nMọi dự án đều bắt đầu với\nkhối \"Khi bắt đầu\".\n\n4\n00:00:10.510 --> 00:00:14.889\nCó nhiều khối khác nhau\nmà bạn có thể sử dụng để mã hóa rô bốt của mình.\n\n5\n00:00:14.889 --> 00:00:17.642\nChỉ cần chọn và kéo các khối vào\n\n6\n00:00:17.642 --> 00:00:20.270\nthêm chúng vào dự án của bạn.\n\n7\n00:00:20.270 --> 00:00:23.815\nCác khối có thể dễ dàng được xếp chồng lên nhau,\n\n8\n00:00:23.815 --> 00:00:26.026\nsắp xếp lại,\n\n9\n00:00:26.026 --> 00:00:28.111\nvà bị xóa.\n\n10\n00:00:28.111 --> 00:00:29.654\nCần giúp đỡ với một khối?\n\n11\n00:00:29.654 --> 00:00:31.072\nNhận trợ giúp thật dễ dàng,\n\n12\n00:00:31.072 --> 00:00:32.907\nchỉ cần chọn biểu tượng trợ giúp\n\n13\n00:00:32.907 --> 00:00:35.869\nvà sau đó chọn một khối\nđể tìm hiểu cách hoạt động của nó.\n\n14\n00:00:35.869 --> 00:00:38.204\nMột nơi tuyệt vời khác để học các khối khác nhau\n\n15\n00:00:38.204 --> 00:00:40.999\nvà các hành vi là từ các Dự án mẫu.\n\n16\n00:00:40.999 --> 00:00:44.544\nChúng tôi đã tạo một vài Dự án mẫu\ncó thể giúp bạn.\n\n17\n00:00:44.544 --> 00:00:46.713\nMột trong những tính năng tốt nhất của VEXcode\n\n18\n00:00:46.713 --> 00:00:48.131\nlà menu ngữ cảnh.\n\n19\n00:00:48.131 --> 00:00:51.051\nNhấp chuột phải vào một khối hoặc\nmột chồng khối\n\n20\n00:00:51.051 --> 00:00:54.846\nđể nhân bản,\n\n21\n00:00:54.846 --> 00:00:57.265\nvô hiệu,\n\n22\n00:00:57.265 --> 00:00:59.476\nhoặc xóa các khối.\n\n23\n00:00:59.476 --> 00:01:01.895\nNếu bạn nhấp chuột phải vào không gian làm việc,\n\n24\n00:01:01.895 --> 00:01:03.563\nbạn có thể sử dụng các tùy chọn khác\n\n25\n00:01:03.563 --> 00:01:05.648\nnhư hoàn tác\n\n26\n00:01:05.648 --> 00:01:08.068\nvà làm lại.\n\n27\n00:01:08.068 --> 00:01:10.195\nKhi bạn đã sẵn sàng\nđể thử dự án của mình,\n\n28\n00:01:10.195 --> 00:01:13.239\nbạn có thể chọn Bắt đầu\nđể chạy dự án của mình.\n\n29\n00:01:13.239 --> 00:01:14.616\nKhi bạn viết mã xong,\n\n30\n00:01:14.616 --> 00:01:16.659\nbạn có thể tải xuống\nbản sao của dự án của mình\n\n31\n00:01:16.659 --> 00:01:19.996\nbằng cách chọn \"Lưu vào thiết bị của bạn.\"\n\n32\n00:01:19.996 --> 00:01:21.664\nTìm kiếm thêm một số thông tin\n\n33\n00:01:21.664 --> 00:01:22.916\nvề Kỹ năng ảo\n\n34\n00:01:22.916 --> 00:01:24.542\nhay chỉ về VEXcode?\n\n35\n00:01:24.542 --> 00:01:26.336\nKiểm tra Cơ sở Kiến thức của chúng tôi tại\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\nCảm ơn và chúc bạn viết mã vui vẻ!\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\ncrwdns412679:0crwdne412679:0\n\n2\n00:00:04.045 --> 00:00:06.589\ncrwdns412681:0crwdne412681:0\n\n3\n00:00:06.589 --> 00:00:10.510\ncrwdns412683:0crwdne412683:0\n\n4\n00:00:10.510 --> 00:00:14.889\ncrwdns412685:0crwdne412685:0\n\n5\n00:00:14.889 --> 00:00:17.642\ncrwdns412687:0crwdne412687:0\n\n6\n00:00:17.642 --> 00:00:20.270\ncrwdns412689:0crwdne412689:0\n\n7\n00:00:20.270 --> 00:00:23.815\ncrwdns412691:0crwdne412691:0\n\n8\n00:00:23.815 --> 00:00:26.026\ncrwdns412693:0crwdne412693:0\n\n9\n00:00:26.026 --> 00:00:28.111\ncrwdns412695:0crwdne412695:0\n\n10\n00:00:28.111 --> 00:00:29.654\ncrwdns412697:0crwdne412697:0\n\n11\n00:00:29.654 --> 00:00:31.072\ncrwdns412699:0crwdne412699:0\n\n12\n00:00:31.072 --> 00:00:32.907\ncrwdns412701:0crwdne412701:0\n\n13\n00:00:32.907 --> 00:00:35.869\ncrwdns412703:0crwdne412703:0\n\n14\n00:00:35.869 --> 00:00:38.204\ncrwdns412705:0crwdne412705:0\n\n15\n00:00:38.204 --> 00:00:40.999\ncrwdns412707:0crwdne412707:0\n\n16\n00:00:40.999 --> 00:00:44.544\ncrwdns412709:0crwdne412709:0\n\n17\n00:00:44.544 --> 00:00:46.713\ncrwdns412711:0crwdne412711:0\n\n18\n00:00:46.713 --> 00:00:48.131\ncrwdns412713:0crwdne412713:0\n\n19\n00:00:48.131 --> 00:00:51.051\ncrwdns412715:0crwdne412715:0\n\n20\n00:00:51.051 --> 00:00:54.846\ncrwdns412717:0crwdne412717:0\n\n21\n00:00:54.846 --> 00:00:57.265\ncrwdns412719:0crwdne412719:0\n\n22\n00:00:57.265 --> 00:00:59.476\ncrwdns412721:0crwdne412721:0\n\n23\n00:00:59.476 --> 00:01:01.895\ncrwdns412723:0crwdne412723:0\n\n24\n00:01:01.895 --> 00:01:03.563\ncrwdns412725:0crwdne412725:0\n\n25\n00:01:03.563 --> 00:01:05.648\ncrwdns412727:0crwdne412727:0\n\n26\n00:01:05.648 --> 00:01:08.068\ncrwdns412729:0crwdne412729:0\n\n27\n00:01:08.068 --> 00:01:10.195\ncrwdns412731:0crwdne412731:0\n\n28\n00:01:10.195 --> 00:01:13.239\ncrwdns412733:0crwdne412733:0\n\n29\n00:01:13.239 --> 00:01:14.616\ncrwdns412735:0crwdne412735:0\n\n30\n00:01:14.616 --> 00:01:16.659\ncrwdns412737:0crwdne412737:0\n\n31\n00:01:16.659 --> 00:01:19.996\ncrwdns412739:0crwdne412739:0\n\n32\n00:01:19.996 --> 00:01:21.664\ncrwdns412741:0crwdne412741:0\n\n33\n00:01:21.664 --> 00:01:22.916\ncrwdns412743:0crwdne412743:0\n\n34\n00:01:22.916 --> 00:01:24.542\ncrwdns412745:0crwdne412745:0\n\n35\n00:01:24.542 --> 00:01:26.336\ncrwdns412747:0crwdne412747:0\n\n36\n00:01:26.336 --> 00:01:29.214\ncrwdns412749:0crwdne412749:0\n\n37\n00:01:29.214 --> 00:01:31.466\ncrwdns412751:0crwdne412751:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:04.045\n在虚拟技能中，你可以编码你的机器人做许多事情，\n\n2\n00:00:04.045 --> 00:00:06.589\n并且入门非常容易。\n\n3\n00:00:06.589 --> 00:00:10.510\n每一个程序都以“当开始”指令块开头。\n\n4\n00:00:10.510 --> 00:00:14.889\n有许多不同的指令块可以用来编码你的机器人。\n\n5\n00:00:14.889 --> 00:00:17.642\n只用选择并拖拽指令块来\n\n6\n00:00:17.642 --> 00:00:20.270\n添加它们到你的程序中。\n\n7\n00:00:20.270 --> 00:00:23.815\n指令块可以容易地叠搭在一起，\n\n8\n00:00:23.815 --> 00:00:26.026\n重新排列，\n\n9\n00:00:26.026 --> 00:00:28.111\n和删除。\n\n10\n00:00:28.111 --> 00:00:29.654\n需要关于某个指令块的帮助吗？\n\n11\n00:00:29.654 --> 00:00:31.072\n获取帮助很容易，\n\n12\n00:00:31.072 --> 00:00:32.907\n只用选择‘帮助’图标\n\n13\n00:00:32.907 --> 00:00:35.869\n然后选择一个指令块来学习它如何工作。\n\n14\n00:00:35.869 --> 00:00:38.204\n另一个学习不同指令块\n\n15\n00:00:38.204 --> 00:00:40.999\n和行为的好地方是来自‘样例程序’。\n\n16\n00:00:40.999 --> 00:00:44.544\n我们已经创建了一些可以帮助你的样例程序。\n\n17\n00:00:44.544 --> 00:00:46.713\nVEXcode 的最佳功能之一\n\n18\n00:00:46.713 --> 00:00:48.131\n是上下文菜单。\n\n19\n00:00:48.131 --> 00:00:51.051\n右键点击一个指令块或一个指令段\n\n20\n00:00:51.051 --> 00:00:54.846\n来复制，\n\n21\n00:00:54.846 --> 00:00:57.265\n禁用，\n\n22\n00:00:57.265 --> 00:00:59.476\n或删除指令块。\n\n23\n00:00:59.476 --> 00:01:01.895\n如果你在工作区点击右键，\n\n24\n00:01:01.895 --> 00:01:03.563\n你可以使用其他选项\n\n25\n00:01:03.563 --> 00:01:05.648\n比如撤销\n\n26\n00:01:05.648 --> 00:01:08.068\n和重做。\n\n27\n00:01:08.068 --> 00:01:10.195\n你准备好尝试你的程序后，\n\n28\n00:01:10.195 --> 00:01:13.239\n你可以选择‘开始’来运行你的程序。\n\n29\n00:01:13.239 --> 00:01:14.616\n当你完成编码后，\n\n30\n00:01:14.616 --> 00:01:16.659\n你可以下载一个你的程序副本\n\n31\n00:01:16.659 --> 00:01:19.996\n通过选择“保存到你的设备。”\n\n32\n00:01:19.996 --> 00:01:21.664\n寻找更多\n\n33\n00:01:21.664 --> 00:01:22.916\n有关虚拟技能\n\n34\n00:01:22.916 --> 00:01:24.542\n或只是关于 VEXcode 的更多信息？\n\n35\n00:01:24.542 --> 00:01:26.336\n查看我们的知识库于\n\n36\n00:01:26.336 --> 00:01:29.214\nhelp.vex.com\n\n37\n00:01:29.214 --> 00:01:31.466\n感谢并祝你编码愉快！\n\n"}},{"thumb":"VIQC_Tutorial_nameAndSave.png","mov":"V5_VRC_WebBasedNamingAndSaving","description":"Naming and Saving a Project","filter":"","placeholder":false,"vimeo":"","proglang":["blocks"],"progtarget":["virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nIn VEXcode, all projects begin\n\n2\n00:00:02.877 --> 00:00:06.256\nwith the default name of\n\"VEXcode Project.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nTo give your project a different name,\n\n4\n00:00:08.425 --> 00:00:11.219\nselect the project name\nin the toolbar\n\n5\n00:00:11.219 --> 00:00:13.388\nand then add the project name.\n\n6\n00:00:13.388 --> 00:00:15.056\nWhen saving your project,\n\n7\n00:00:15.056 --> 00:00:16.850\nthe project name is used\n\n8\n00:00:16.850 --> 00:00:19.352\nto name that file that\nis downloaded.\n\n9\n00:00:19.352 --> 00:00:21.354\nTo save a copy of the project,\n\n10\n00:00:21.354 --> 00:00:23.898\nopen the file menu\n\n11\n00:00:23.898 --> 00:00:27.652\nand select \"Save To Your Device.\"\n\n12\n00:00:27.652 --> 00:00:29.279\nYour project will be saved\n\n13\n00:00:29.279 --> 00:00:32.115\nto your browser's default\ndownloads location\n\n14\n00:00:32.115 --> 00:00:34.034\non your device.\n\n","ar":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nفي VEXcode، تبدأ جميع المشاريع\n\n2\n00:00:02.877 --> 00:00:06.256\nمع اسم موضوع مسبقا \"مشروع VEXcode.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nلإعطاء المشروع الخاص بك اسم مختلف،\n\n4\n00:00:08.425 --> 00:00:11.219\nحدد اسم المشروع\nفي شريط الأدوات\n\n5\n00:00:11.219 --> 00:00:13.388\nثم أضف اسم المشروع.\n\n6\n00:00:13.388 --> 00:00:15.056\nعند حفظ مشروعك،\n\n7\n00:00:15.056 --> 00:00:16.850\nيتم استخدام اسم المشروع\n\n8\n00:00:16.850 --> 00:00:19.352\nلتسمية الملف الذي تم تحميله.\n\n9\n00:00:19.352 --> 00:00:21.354\nلحفظ نسخة من المشروع الخاص بك،\n\n10\n00:00:21.354 --> 00:00:23.898\nإفتح القائمة الرئيسية\n\n11\n00:00:23.898 --> 00:00:27.652\nواختر \"حفظ إلى جهازك.\"\n\n12\n00:00:27.652 --> 00:00:29.279\nسيتم حفظ مشروعك\n\n13\n00:00:29.279 --> 00:00:32.115\nإلى موقع التنزيلات في المتصفح على جهازك\n\n14\n00:00:32.115 --> 00:00:34.034\nعلى جهازك.\n\n","cs":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nVšechny projekty ve VEXcode začínají\n\n2\n00:00:02.877 --> 00:00:06.256\ns výchozím názvem\nVEXcode Project.\n\n3\n00:00:06.256 --> 00:00:08.425\nPro pojmenování svého projektu jiným názvem\n\n4\n00:00:08.425 --> 00:00:11.219\nvyber název projektu\nna Panelu nástrojů\n\n5\n00:00:11.219 --> 00:00:13.388\na potom přidej název projektu.\n\n6\n00:00:13.388 --> 00:00:15.056\nPři ukládání tvého projektu\n\n7\n00:00:15.056 --> 00:00:16.850\nje název projektu použit\n\n8\n00:00:16.850 --> 00:00:19.352\npro pojmenování souboru,\nkterý se stáhne.\n\n9\n00:00:19.352 --> 00:00:21.354\nPro uložení kopie projektu\n\n10\n00:00:21.354 --> 00:00:23.898\notevři menu Soubor\n\n11\n00:00:23.898 --> 00:00:27.652\na vyber Uložit do vašeho zařízení.\n\n12\n00:00:27.652 --> 00:00:29.279\nTvůj projekt se uloží\n\n13\n00:00:29.279 --> 00:00:32.115\ndo výchozího umístění\nstahování prohlížeče\n\n14\n00:00:32.115 --> 00:00:34.034\nna tvém zařízení.\n\n","de":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nIn VEXcode beginnen alle Projekte\n\n2\n00:00:02.877 --> 00:00:06.256\nmit dem Standardnamen \"VEXcode-Project\".\n\n3\n00:00:06.256 --> 00:00:08.425\nUm deinem Projekt einen neuen Namen zu geben,\n\n4\n00:00:08.425 --> 00:00:11.219\nwähle den Projektnamen\nin der Symbolleiste\n\n5\n00:00:11.219 --> 00:00:13.388\nund füge dann den Projektnamen hinzu.\n\n6\n00:00:13.388 --> 00:00:15.056\nWenn du dein Projekt speicherst,\n\n7\n00:00:15.056 --> 00:00:16.850\nder Projektname wird verwendet\n\n8\n00:00:16.850 --> 00:00:19.352\num die Datei zu benennen, die\nheruntergeladen wird.\n\n9\n00:00:19.352 --> 00:00:21.354\nUm eine Kopie deines Projekts zu speichern\n\n10\n00:00:21.354 --> 00:00:23.898\nöffne das Dateimenü\n\n11\n00:00:23.898 --> 00:00:27.652\nund wähle speichern auf deinem Gerät.\"\n\n12\n00:00:27.652 --> 00:00:29.279\nDein Projekt wird gespeichert\n\n13\n00:00:29.279 --> 00:00:32.115\nim Standard-Download-Verzeichnis deines Browsers\n\n14\n00:00:32.115 --> 00:00:34.034\nauf deinem Gerät gespeichert wird.\n\n","fi":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nKaikki VEXcode  -ohjelmat alkavat\n\n2\n00:00:02.877 --> 00:00:06.256\noletusnimellä \"VEXcode Project.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nJos haluat muuttaa nimeä\n\n4\n00:00:08.425 --> 00:00:11.219\nkirjoita toinen nimi työkalupalkkiin oletuksen sijaan\n\n5\n00:00:11.219 --> 00:00:13.388\nja lisää sitten projektin nimi.\n\n6\n00:00:13.388 --> 00:00:15.056\nKun tallennat ohjelmasi\n\n7\n00:00:15.056 --> 00:00:16.850\nprojektin uusi nimi on käytössä\n\n8\n00:00:16.850 --> 00:00:19.352\ntallennuksessa ja tallennus menee aina entisen päälle.\n\n9\n00:00:19.352 --> 00:00:21.354\nTallentaaksesi kopion ohjelmastasi\n\n10\n00:00:21.354 --> 00:00:23.898\navaa Tiedosto -valikko\n\n11\n00:00:23.898 --> 00:00:27.652\nja valitse Tallenna omalle laitteelle.\"\n\n12\n00:00:27.652 --> 00:00:29.279\nSinun projektisi tallennetaan\n\n13\n00:00:29.279 --> 00:00:32.115\nselaimen oletuskansioon\n\n14\n00:00:32.115 --> 00:00:34.034\nlaitteellasi.\n\n","fr":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nDans VEXcode, chaque projet commence\n\n2\n00:00:02.877 --> 00:00:06.256\navec le nom par défaut de \"Projet VEXcode.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nPour donner un autre nom à votre projet,\n\n4\n00:00:08.425 --> 00:00:11.219\nsélectionnez le nom du projet\ndans la barre d'outils\n\n5\n00:00:11.219 --> 00:00:13.388\npuis ajoutez le nom du projet.\n\n6\n00:00:13.388 --> 00:00:15.056\nLors de l'enregistrement de votre projet,\n\n7\n00:00:15.056 --> 00:00:16.850\nle nom du projet est utilisé\n\n8\n00:00:16.850 --> 00:00:19.352\npour nommer le fichier qui est téléchargé.\n\n9\n00:00:19.352 --> 00:00:21.354\nPour enregistrer une copie de votre projet,\n\n10\n00:00:21.354 --> 00:00:23.898\nouvrez le menu \"Fichier\",\n\n11\n00:00:23.898 --> 00:00:27.652\net sélectionnez \"Enregistrer sur votre appareil.\"\n\n12\n00:00:27.652 --> 00:00:29.279\nVotre projet sera enregistré\n\n13\n00:00:29.279 --> 00:00:32.115\nà l'emplacement de téléchargement par défaut de votre navigateur\n\n14\n00:00:32.115 --> 00:00:34.034\nsur votre appareil.\n\n","ko":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nVEXcode에서 모든 프로젝트는\n\n2\n00:00:02.877 --> 00:00:06.256\n기본 이름인 \"VEXcode 프로젝트\"로 시작합니다.\n\n3\n00:00:06.256 --> 00:00:08.425\n프로젝트 이름을 다르게 정하려면\n\n4\n00:00:08.425 --> 00:00:11.219\n도구 모음에서 프로젝트 이름을 선택한 후\n\n5\n00:00:11.219 --> 00:00:13.388\n프로젝트 이름을 추가하십시오.\n\n6\n00:00:13.388 --> 00:00:15.056\n프로젝트를 저장할 때,\n\n7\n00:00:15.056 --> 00:00:16.850\n다운로드된 파일의 이름을 정하기 위해\n\n8\n00:00:16.850 --> 00:00:19.352\n프로젝트 이름이 사용됩니다.\n\n9\n00:00:19.352 --> 00:00:21.354\n프로젝트의 사본을 저장하려면\n\n10\n00:00:21.354 --> 00:00:23.898\n파일 메뉴에서\n\n11\n00:00:23.898 --> 00:00:27.652\n\"기기에 저장\"을 선택하세요.\n\n12\n00:00:27.652 --> 00:00:29.279\n프로젝트가 기기상 브라우저의\n\n13\n00:00:29.279 --> 00:00:32.115\n기본 다운로드 위치에\n\n14\n00:00:32.115 --> 00:00:34.034\n저장됩니다.\n\n","nl":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nIn VEXcode beginnen alle projecten\n\n2\n00:00:02.877 --> 00:00:06.256\nmet de standaardnaam\n\"VEXcode Project.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nOm je project een andere naam te geven\n\n4\n00:00:08.425 --> 00:00:11.219\nselecteer de projectnaam\nin de werkbalk\n\n5\n00:00:11.219 --> 00:00:13.388\nen voeg vervolgens de projectnaam toe.\n\n6\n00:00:13.388 --> 00:00:15.056\nWanneer u uw project opslaat,\n\n7\n00:00:15.056 --> 00:00:16.850\nde projectnaam wordt gebruikt\n\n8\n00:00:16.850 --> 00:00:19.352\nom dat bestand een naam te geven dat\nis gedownload.\n\n9\n00:00:19.352 --> 00:00:21.354\nOm een kopie van het project op te slaan,\n\n10\n00:00:21.354 --> 00:00:23.898\nopen het bestandsmenu\n\n11\n00:00:23.898 --> 00:00:27.652\nen selecteer \"Opslaan op uw apparaat\".\n\n12\n00:00:27.652 --> 00:00:29.279\nUw project wordt opgeslagen\n\n13\n00:00:29.279 --> 00:00:32.115\nnaar de standaard\ndownloadlocatie van uw browser\n\n14\n00:00:32.115 --> 00:00:34.034\nop uw apparaat.\n\n","ru":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nВ VEXcode все проекты начинаются\n\n2\n00:00:02.877 --> 00:00:06.256\nс именем по умолчанию\n\"VEXcode Project\".\n\n3\n00:00:06.256 --> 00:00:08.425\nЗадать проекту другое имя можно,\n\n4\n00:00:08.425 --> 00:00:11.219\nвыберите имя проекта\n\n5\n00:00:11.219 --> 00:00:13.388\nи добавьте имя проекта.\n\n6\n00:00:13.388 --> 00:00:15.056\nПри сохранении вашего проекта,\n\n7\n00:00:15.056 --> 00:00:16.850\nскачанный файл будет\n\n8\n00:00:16.850 --> 00:00:19.352\nиметь имя проекта.\n\n9\n00:00:19.352 --> 00:00:21.354\nЧтобы сохранить копию проекта,\n\n10\n00:00:21.354 --> 00:00:23.898\nоткройте меню \"Файл\"\n\n11\n00:00:23.898 --> 00:00:27.652\nи выберите «Сохранить на вашем устройстве».\n\n12\n00:00:27.652 --> 00:00:29.279\nВаш проект будет сохранен\n\n13\n00:00:29.279 --> 00:00:32.115\nв место загрузки по умолчанию\nвашего браузера\n\n14\n00:00:32.115 --> 00:00:34.034\nна вашем устройстве.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\nTrong VEXcode, tất cả các dự án bắt đầu\n\n2\n00:00:02.877 --> 00:00:06.256\nvới tên mặc định là\n\"Dự án VEXcode.\"\n\n3\n00:00:06.256 --> 00:00:08.425\nĐể đặt tên khác cho dự án của bạn,\n\n4\n00:00:08.425 --> 00:00:11.219\nchọn tên dự án\ntrong thanh công cụ\n\n5\n00:00:11.219 --> 00:00:13.388\nvà sau đó thêm tên dự án.\n\n6\n00:00:13.388 --> 00:00:15.056\nKhi lưu dự án của bạn,\n\n7\n00:00:15.056 --> 00:00:16.850\ntên dự án được sử dụng\n\n8\n00:00:16.850 --> 00:00:19.352\nđể đặt tên cho tệp mà\nđược tải xuống.\n\n9\n00:00:19.352 --> 00:00:21.354\nĐể lưu một bản sao của dự án,\n\n10\n00:00:21.354 --> 00:00:23.898\nmở menu tệp\n\n11\n00:00:23.898 --> 00:00:27.652\nvà chọn \"Lưu vào thiết bị của bạn\".\n\n12\n00:00:27.652 --> 00:00:29.279\nDự án của bạn sẽ được lưu\n\n13\n00:00:29.279 --> 00:00:32.115\nđến vị trí tải xuống\nmặc định của trình duyệt của bạn\n\n14\n00:00:32.115 --> 00:00:34.034\ntrên thiết bị của bạn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\ncrwdns412771:0crwdne412771:0\n\n2\n00:00:02.877 --> 00:00:06.256\ncrwdns412773:0crwdne412773:0\n\n3\n00:00:06.256 --> 00:00:08.425\ncrwdns412775:0crwdne412775:0\n\n4\n00:00:08.425 --> 00:00:11.219\ncrwdns412777:0crwdne412777:0\n\n5\n00:00:11.219 --> 00:00:13.388\ncrwdns412779:0crwdne412779:0\n\n6\n00:00:13.388 --> 00:00:15.056\ncrwdns412781:0crwdne412781:0\n\n7\n00:00:15.056 --> 00:00:16.850\ncrwdns412783:0crwdne412783:0\n\n8\n00:00:16.850 --> 00:00:19.352\ncrwdns412785:0crwdne412785:0\n\n9\n00:00:19.352 --> 00:00:21.354\ncrwdns412787:0crwdne412787:0\n\n10\n00:00:21.354 --> 00:00:23.898\ncrwdns412789:0crwdne412789:0\n\n11\n00:00:23.898 --> 00:00:27.652\ncrwdns412791:0crwdne412791:0\n\n12\n00:00:27.652 --> 00:00:29.279\ncrwdns412793:0crwdne412793:0\n\n13\n00:00:29.279 --> 00:00:32.115\ncrwdns412795:0crwdne412795:0\n\n14\n00:00:32.115 --> 00:00:34.034\ncrwdns412797:0crwdne412797:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:02.877\n在 VEXcode 中，所有程序以\n\n2\n00:00:02.877 --> 00:00:06.256\n默认名称“VEXcode Project”开始。\n\n3\n00:00:06.256 --> 00:00:08.425\n要给你的程序一个不同的名称，\n\n4\n00:00:08.425 --> 00:00:11.219\n选择工具栏中的程序名称\n\n5\n00:00:11.219 --> 00:00:13.388\n并随后添加程序名称。\n\n6\n00:00:13.388 --> 00:00:15.056\n当保存你的程序时，\n\n7\n00:00:15.056 --> 00:00:16.850\n程序名称被用于\n\n8\n00:00:16.850 --> 00:00:19.352\n命名已下载的那个文件。\n\n9\n00:00:19.352 --> 00:00:21.354\n要保存程序副本，\n\n10\n00:00:21.354 --> 00:00:23.898\n打开“文件”菜单\n\n11\n00:00:23.898 --> 00:00:27.652\n并选择“保存至你的设备。”\n\n12\n00:00:27.652 --> 00:00:29.279\n你的程序将被保存\n\n13\n00:00:29.279 --> 00:00:32.115\n到你的浏览器默认下载位置\n\n14\n00:00:32.115 --> 00:00:34.034\n下载位置。\n\n"}},{"thumb":"V5_Tutorial_gettingStarted.jpg","mov":"V5_Blocks_GettingStarted_V2","description":"Getting started","filter":"","placeholder":false,"vimeo":"475899623","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>In a V5 blocks project,</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nyou can program your V5 robot to do many things.\n\n3\n00:00:05.790 --> 00:00:09.053\nEvery project begins with a when started block.\n\n4\n00:00:10.030 --> 00:00:11.260\nThere are many different blocks\n\n5\n00:00:11.260 --> 00:00:13.333\nthat you can use to program your robot.\n\n6\n00:00:18.680 --> 00:00:20.923\nLet's add a few blocks to our project.\n\n7\n00:00:25.010 --> 00:00:27.940\nBlocks can easily be stacked together,\n\n8\n00:00:27.940 --> 00:00:31.863\nrearranged, and deleted.\n\n9\n00:00:34.880 --> 00:00:37.980\nAlso use V5 motors and sensors in your project\n\n10\n00:00:37.980 --> 00:00:40.713\nby adding devices in the Devices window.\n\n11\n00:00:48.840 --> 00:00:50.750\nAdding a device will add blocks\n\n12\n00:00:50.750 --> 00:00:53.423\nand categories to your project's toolbox.\n\n13\n00:00:54.820 --> 00:00:56.310\nNeed help with a block?\n\n14\n00:00:56.310 --> 00:00:57.743\nGetting help is easy.\n\n15\n00:00:59.600 --> 00:01:02.093\nSelect a block to learn how it works.\n\n16\n00:01:04.520 --> 00:01:08.233\nAnother great place to learn is with example projects.\n\n17\n00:01:10.610 --> 00:01:13.410\nExploring example projects is a great way to learn\n\n18\n00:01:13.410 --> 00:01:15.983\nhow to use different blocks and behaviors.\n\n19\n00:01:17.060 --> 00:01:18.950\nOnce you're ready to try your project,\n\n20\n00:01:18.950 --> 00:01:22.083\nyou can download and run it on your V5 robot brain.\n\n21\n00:01:25.620 --> 00:01:28.020\nTo learn more about VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\ntake a look at the other tutorial videos.\n\n23\n00:01:30.740 --> 00:01:31.573\nHave fun.\n\n","ar":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>في مشروع V5 للمقاطع،</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nيمكنك برمجة روبوت V5 الخاص بك للقيام بعدة أشياء.\n\n3\n00:00:05.790 --> 00:00:09.053\nيبدأ كل مشروع بمقطع\"عند البدء\".\n\n4\n00:00:10.030 --> 00:00:11.260\nهناك العديد من المقاطع المختلفة\n\n5\n00:00:11.260 --> 00:00:13.333\nالتي يمكنك استخدامها لبرمجة الروبوت الخاص بك.\n\n6\n00:00:18.680 --> 00:00:20.923\nدعونا نضيف بضع المقاطع إلى مشروعنا.\n\n7\n00:00:25.010 --> 00:00:27.940\nيمكن تجميع المقاطع بسهولة معا،\n\n8\n00:00:27.940 --> 00:00:31.863\nإعادة الترتيب والحذف.\n\n9\n00:00:34.880 --> 00:00:37.980\nاستخدم أيضًا محركات وأجهزة استشعار V5 في مشروعك\n\n10\n00:00:37.980 --> 00:00:40.713\nعن طريق إضافة أجهزة في نافذة الأجهزة.\n\n11\n00:00:48.840 --> 00:00:50.750\nإضافة جهاز سيؤدي إلى إضافة مقاطع\n\n12\n00:00:50.750 --> 00:00:53.423\nوفئات إلى قائمة أدوات مشروعك.\n\n13\n00:00:54.820 --> 00:00:56.310\nهل تحتاج إلى مساعدة مع مقطع؟\n\n14\n00:00:56.310 --> 00:00:57.743\nالحصول على المساعدة أمر سهل.\n\n15\n00:00:59.600 --> 00:01:02.093\nحدد مقطع لتعلم كيفية إستخدامه.\n\n16\n00:01:04.520 --> 00:01:08.233\nمكان آخر يمكن التعلم منه و هو أمثلة المشاريع.\n\n17\n00:01:10.610 --> 00:01:13.410\nاستكشاف أمثلة المشاريع هو طريقة رائعة للتعلم\n\n18\n00:01:13.410 --> 00:01:15.983\nكيفية استخدام مقاطع البرمجية والسلوكيات المختلفة.\n\n19\n00:01:17.060 --> 00:01:18.950\nبمجرد أن تكون جاهزاً لتجربة مشروعك،\n\n20\n00:01:18.950 --> 00:01:22.083\nيمكن تنزيله وتشغيله على عقل الروبوت V5 الخاص بك.\n\n21\n00:01:25.620 --> 00:01:28.020\nلمعرفة المزيد حول VEXcode V5،\n\n22\n00:01:28.020 --> 00:01:30.740\nألقي نظرة على مقاطع الفيديو التعليمية الأخرى.\n\n23\n00:01:30.740 --> 00:01:31.573\nإستمتع.\n\n","cs":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>V blokovém projektu V5</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nmůžeš naprogramovat svého V5 robota pro mnoho věcí.\n\n3\n00:00:05.790 --> 00:00:09.053\nKaždý projekt začíná blokem při spuštění.\n\n4\n00:00:10.030 --> 00:00:11.260\nExistuje mnoho různých bloků,\n\n5\n00:00:11.260 --> 00:00:13.333\nkteré můžeš použít k programování svého robota.\n\n6\n00:00:18.680 --> 00:00:20.923\nPojďme k našemu projektu přidat pár bloků.\n\n7\n00:00:25.010 --> 00:00:27.940\nBloky mohou být jednoduše spojeny dohromady,\n\n8\n00:00:27.940 --> 00:00:31.863\npřeskupeny a smazány.\n\n9\n00:00:34.880 --> 00:00:37.980\nVe svém projektu také použij V5 motory a senzory\n\n10\n00:00:37.980 --> 00:00:40.713\npřidáním zařízení v okně Zařízení.\n\n11\n00:00:48.840 --> 00:00:50.750\nPřidání zařízení přidá bloky\n\n12\n00:00:50.750 --> 00:00:53.423\na kategorie do Panelu nástrojů tvého projektu.\n\n13\n00:00:54.820 --> 00:00:56.310\nPotřebuješ s nějakým blokem pomoci?\n\n14\n00:00:56.310 --> 00:00:57.743\nZískat pomoc je snadné.\n\n15\n00:00:59.600 --> 00:01:02.093\nVyber blok, aby ses dozvěděl jak funguje.\n\n16\n00:01:04.520 --> 00:01:08.233\nDalší skvělé místo k učení jsou ukázkové projekty.\n\n17\n00:01:10.610 --> 00:01:13.410\nProzkoumání ukázkových projektů je skvělý způsob, jak se naučit\n\n18\n00:01:13.410 --> 00:01:15.983\npoužívat různé bloky a chování.\n\n19\n00:01:17.060 --> 00:01:18.950\nJakmile bude tvůj projekt připraven k vyzkoušení,\n\n20\n00:01:18.950 --> 00:01:22.083\nmůžeš ho stáhnout a spustit na svém robotickém V5 mozku.\n\n21\n00:01:25.620 --> 00:01:28.020\nPro více informací o VEXcode V5\n\n22\n00:01:28.020 --> 00:01:30.740\nse podívej na ostatní výuková videa.\n\n23\n00:01:30.740 --> 00:01:31.573\nUžij si to.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>En un proyecto de V5 Blocks (bloques),</v>\n\n2\n00:00:02.050 --> 00:00:05.790\npuede programar su robot V5 para hacer muchas cosas.\n\n3\n00:00:05.790 --> 00:00:09.053\nCada proyecto comienza con un bloque al iniciar.\n\n4\n00:00:10.030 --> 00:00:11.260\nHay muchos bloques distintos\n\n5\n00:00:11.260 --> 00:00:13.333\nque usted puede utilizar para programar su robot.\n\n6\n00:00:18.680 --> 00:00:20.923\nVamos a añadir algunos bloques a nuestro proyecto.\n\n7\n00:00:25.010 --> 00:00:27.940\nLos bloques pueden ser apilados fácilmente juntos,\n\n8\n00:00:27.940 --> 00:00:31.863\nreorganizados, y eliminados.\n\n9\n00:00:34.880 --> 00:00:37.980\nTambién puede usar motores y sensores VEX V5 en su proyecto\n\n10\n00:00:37.980 --> 00:00:40.713\nañadiendo su dispositivos en la ventana Dispositivos.\n\n11\n00:00:48.840 --> 00:00:50.750\nAgregar un dispositivo añadirá bloques\n\n12\n00:00:50.750 --> 00:00:53.423\ny categorías en la caja de herramientas de su proyecto.\n\n13\n00:00:54.820 --> 00:00:56.310\n¿Necesitas ayuda con un bloque?\n\n14\n00:00:56.310 --> 00:00:57.743\nObtener ayuda es fácil.\n\n15\n00:00:59.600 --> 00:01:02.093\nSeleccione un bloque para aprender cómo funciona.\n\n16\n00:01:04.520 --> 00:01:08.233\nOtro gran lugar para aprender es con proyectos de ejemplo.\n\n17\n00:01:10.610 --> 00:01:13.410\nExplorar proyectos de ejemplo es una manera excelente\n\n18\n00:01:13.410 --> 00:01:15.983\nde aprender a utilizar diferentes bloques y comportamientos.\n\n19\n00:01:17.060 --> 00:01:18.950\nUna vez que esté listo para probar su proyecto,\n\n20\n00:01:18.950 --> 00:01:22.083\npuede descargarlo y ejecutarlo en su VEX V5 Brain.\n\n21\n00:01:25.620 --> 00:01:28.020\nPara aprender más sobre VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\necha un vistazo a los otros vídeos de tutoriales.\n\n23\n00:01:30.740 --> 00:01:31.573\n¡Diviértese!\n\n","es":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>En un proyecto de V5 Blocks (bloques),</v>\n\n2\n00:00:02.050 --> 00:00:05.790\npuede programar su robot V5 para hacer muchas cosas.\n\n3\n00:00:05.790 --> 00:00:09.053\nCada proyecto comienza con un bloque al iniciar.\n\n4\n00:00:10.030 --> 00:00:11.260\nHay muchos bloques distintos\n\n5\n00:00:11.260 --> 00:00:13.333\nque usted puede utilizar para programar su robot.\n\n6\n00:00:18.680 --> 00:00:20.923\nVamos a añadir algunos bloques a nuestro proyecto.\n\n7\n00:00:25.010 --> 00:00:27.940\nLos bloques pueden ser apilados fácilmente juntos,\n\n8\n00:00:27.940 --> 00:00:31.863\nreorganizados, y eliminados.\n\n9\n00:00:34.880 --> 00:00:37.980\nTambién puede usar motores y sensores VEX V5 en su proyecto\n\n10\n00:00:37.980 --> 00:00:40.713\nañadiendo su dispositivos en la ventana Dispositivos.\n\n11\n00:00:48.840 --> 00:00:50.750\nAgregar un dispositivo añadirá bloques\n\n12\n00:00:50.750 --> 00:00:53.423\ny categorías en la caja de herramientas de su proyecto.\n\n13\n00:00:54.820 --> 00:00:56.310\n¿Necesitas ayuda con un bloque?\n\n14\n00:00:56.310 --> 00:00:57.743\nObtener ayuda es fácil.\n\n15\n00:00:59.600 --> 00:01:02.093\nSeleccione un bloque para aprender cómo funciona.\n\n16\n00:01:04.520 --> 00:01:08.233\nOtro gran lugar para aprender es con proyectos de ejemplo.\n\n17\n00:01:10.610 --> 00:01:13.410\nExplorar proyectos de ejemplo es una manera excelente\n\n18\n00:01:13.410 --> 00:01:15.983\nde aprender a utilizar diferentes bloques y comportamientos.\n\n19\n00:01:17.060 --> 00:01:18.950\nUna vez que esté listo para probar su proyecto,\n\n20\n00:01:18.950 --> 00:01:22.083\npuede descargarlo y ejecutarlo en su VEX V5 Brain.\n\n21\n00:01:25.620 --> 00:01:28.020\nPara aprender más sobre VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\necha un vistazo a los otros vídeos de tutoriales.\n\n23\n00:01:30.740 --> 00:01:31.573\n¡Diviértese!\n\n","fi":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>V5 blocks -ohjelmassa</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nvoit ohjelmoida V5 robottia tekemään monia tehtäviä.\n\n3\n00:00:05.790 --> 00:00:09.053\nJokainen ohjelma alkaa Kun käynnissä -blokki.\n\n4\n00:00:10.030 --> 00:00:11.260\nOn olemassa monia eri ohjelmablokkityyppejä,\n\n5\n00:00:11.260 --> 00:00:13.333\njoilla voit ohjelmoida robottia tekemään asioita.\n\n6\n00:00:18.680 --> 00:00:20.923\nLisätään ohjelmaan muutamia blokkeja.\n\n7\n00:00:25.010 --> 00:00:27.940\nBlokkeja voi helposti pinota päällekkäin,\n\n8\n00:00:27.940 --> 00:00:31.863\njärjestää uudelleen ja poistaa.\n\n9\n00:00:34.880 --> 00:00:37.980\nLisää V5 -moottoreita ja antureita ohjelmaasi\n\n10\n00:00:37.980 --> 00:00:40.713\nlisäämällä ne Laitteet-ikkunassa.\n\n11\n00:00:48.840 --> 00:00:50.750\nLaitteen lisääminen lisää ohjelmablokkeja\n\n12\n00:00:50.750 --> 00:00:53.423\nja tuntoaistiblokkeja laitteiden työkaluihin.\n\n13\n00:00:54.820 --> 00:00:56.310\nTarvitsetko apua blokkien valintaan?\n\n14\n00:00:56.310 --> 00:00:57.743\nApua on helppo saada.\n\n15\n00:00:59.600 --> 00:01:02.093\nValitse vain blokki, niin saat tietää, miten se toimii Help-painikkeella.\n\n16\n00:01:04.520 --> 00:01:08.233\nToinen hyvä tapa oppia on läpikäydä esimerkkiohjelmia.\n\n17\n00:01:10.610 --> 00:01:13.410\nNiiden avulla oppii helposti,\n\n18\n00:01:13.410 --> 00:01:15.983\nmiten käyttää eri blokkeja ja niiden ominaisuuksia.\n\n19\n00:01:17.060 --> 00:01:18.950\nNyt kun olet valmis kokeilemaan ohjelmaasi,\n\n20\n00:01:18.950 --> 00:01:22.083\nvoit ladata ja ajaa se V5 robotissa.\n\n21\n00:01:25.620 --> 00:01:28.020\nVoit oppia lisää myös\n\n22\n00:01:28.020 --> 00:01:30.740\nkun katsot myös opetusohjelmavideoita.\n\n23\n00:01:30.740 --> 00:01:31.573\nPidä hauskaa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>Dans un projet V5 Blocs,</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nvous pouvez programmer votre robot V5 pour faire beaucoup de choses.\n\n3\n00:00:05.790 --> 00:00:09.053\nTout projet démarre avec un bloc \"Au démarrage\".\n\n4\n00:00:10.030 --> 00:00:11.260\nIl y a plein de blocs différents\n\n5\n00:00:11.260 --> 00:00:13.333\nque vous pouvez utiliser pour programmer votre robot.\n\n6\n00:00:18.680 --> 00:00:20.923\nAjoutons quelques blocs à votre projet.\n\n7\n00:00:25.010 --> 00:00:27.940\nLes blocs peuvent être facilement empilés,\n\n8\n00:00:27.940 --> 00:00:31.863\nréarrangés et supprimés.\n\n9\n00:00:34.880 --> 00:00:37.980\nVous pouvez également utiliser les moteurs et capteurs V5 dans votre projet\n\n10\n00:00:37.980 --> 00:00:40.713\nen ajoutant des appareils dans la fenêtre \"Appareils\".\n\n11\n00:00:48.840 --> 00:00:50.750\nAjouter un appareil ajoutera des blocs\n\n12\n00:00:50.750 --> 00:00:53.423\net des catégories à la Boîte à Outils de votre projet.\n\n13\n00:00:54.820 --> 00:00:56.310\nBesoin d'aide avec un bloc ?\n\n14\n00:00:56.310 --> 00:00:57.743\nIl est facile d'obtenir de l'aide.\n\n15\n00:00:59.600 --> 00:01:02.093\nChoisissez un bloc pour apprendre comment il fonctionne.\n\n16\n00:01:04.520 --> 00:01:08.233\nUn autre moyen d'apprendre est d'utiliser les exemples de projets.\n\n17\n00:01:10.610 --> 00:01:13.410\nExplorer des exemples de projets est un excellent moyen d'apprendre\n\n18\n00:01:13.410 --> 00:01:15.983\ncomment utiliser différents blocs et comportements.\n\n19\n00:01:17.060 --> 00:01:18.950\nUne fois que vous êtes prêt à essayer votre projet,\n\n20\n00:01:18.950 --> 00:01:22.083\nvous pouvez le télécharger et l'exécuter sur le Cerveau de votre robot V5.\n\n21\n00:01:25.620 --> 00:01:28.020\nPour en apprendre plus sur VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nconsultez les autres vidéos de tutoriels.\n\n23\n00:01:30.740 --> 00:01:31.573\nAmusez-vous bien.\n\n","ko":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>V5 블록 프로젝트에서</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nV5 로봇을 프로그래밍하여 많은 작업을 수행할 수 있습니다.\n\n3\n00:00:05.790 --> 00:00:09.053\n모든 프로젝트는 '시작하기' 블록으로 시작합니다.\n\n4\n00:00:10.030 --> 00:00:11.260\n다양한 블록을\n\n5\n00:00:11.260 --> 00:00:13.333\n로봇 프로그래밍에 사용할 수 있습니다.\n\n6\n00:00:18.680 --> 00:00:20.923\n몇 개의 블록을 프로젝트에 추가해 봅시다.\n\n7\n00:00:25.010 --> 00:00:27.940\n블록은 쉽게 연결, 재배치,\n\n8\n00:00:27.940 --> 00:00:31.863\n그리고 삭제할 수 있습니다.\n\n9\n00:00:34.880 --> 00:00:37.980\n기기 창에서 기기를 추가하여 프로젝트에서\n\n10\n00:00:37.980 --> 00:00:40.713\nV5 모터 및 센서를 사용할 수 있습니다.\n\n11\n00:00:48.840 --> 00:00:50.750\n기기를 추가하면 프로젝트의 도구 상자에\n\n12\n00:00:50.750 --> 00:00:53.423\n블록과 카테고리가 추가됩니다.\n\n13\n00:00:54.820 --> 00:00:56.310\n블록에 대해 더 알고 싶은가요?\n\n14\n00:00:56.310 --> 00:00:57.743\n쉽게 도움을 얻을 수 있습니다.\n\n15\n00:00:59.600 --> 00:01:02.093\n어떻게 작동하는지 알고 싶은 블록을 선택하세요.\n\n16\n00:01:04.520 --> 00:01:08.233\n블록을 배울 수 있는 또 다른 좋은 방법은 예제 프로젝트를 활용하는 것입니다.\n\n17\n00:01:10.610 --> 00:01:13.410\n예제 프로젝트를 탐구하는 것은\n\n18\n00:01:13.410 --> 00:01:15.983\n다양한 블록과 동작 사용에 대해 배우는 좋은 방법입니다.\n\n19\n00:01:17.060 --> 00:01:18.950\n프로젝트를 시도할 준비가 되면\n\n20\n00:01:18.950 --> 00:01:22.083\nV5 로봇 브레인에서 다운 받아 실행할 수 있습니다.\n\n21\n00:01:25.620 --> 00:01:28.020\nVEXcode V5를 더 배우기 위해\n\n22\n00:01:28.020 --> 00:01:30.740\n다른 사용 지침서 비디오를 보세요.\n\n23\n00:01:30.740 --> 00:01:31.573\n즐거운 시간 보내세요.\n\n","lt":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>\"V5\" blokų projekte</v>\n\n2\n00:00:02.050 --> 00:00:05.790\ngalite užprogramuoti savo \"V5\" robotą daugeliui darbų atlikti.\n\n3\n00:00:05.790 --> 00:00:09.053\nKiekvienas projektas prasideda nuo \"kada pradėti\" bloko.\n\n4\n00:00:10.030 --> 00:00:11.260\nSavo robotą galite programuoti\n\n5\n00:00:11.260 --> 00:00:13.333\ndaugeliu skirtingų blokų.\n\n6\n00:00:18.680 --> 00:00:20.923\nPrie mūsų projekto pridėkime keletą blokų.\n\n7\n00:00:25.010 --> 00:00:27.940\nBlokus galite lengvai uždėti vienas ant kito,\n\n8\n00:00:27.940 --> 00:00:31.863\npertvarkyti ir ištrinti.\n\n9\n00:00:34.880 --> 00:00:37.980\nSavo projekte taip pat galite naudoti \"V5\" variklius ir jutiklius,\n\n10\n00:00:37.980 --> 00:00:40.713\nprietaisų lange pridėdami prietaisus.\n\n11\n00:00:48.840 --> 00:00:50.750\nPridėdami prietaisą, pridėsite ir blokus\n\n12\n00:00:50.750 --> 00:00:53.423\nbei kategorijas į savo projekto parankinę.\n\n13\n00:00:54.820 --> 00:00:56.310\nReikia padėti su bloku?\n\n14\n00:00:56.310 --> 00:00:57.743\nTai lengva padaryti.\n\n15\n00:00:59.600 --> 00:01:02.093\nPasirinkite bloką, kad sužinotumėte kaip jis veikia.\n\n16\n00:01:04.520 --> 00:01:08.233\nKitas geras mokymosi pavyzdys yra mokymasis iš pavyzdinių projektų.\n\n17\n00:01:10.610 --> 00:01:13.410\nPavyzdinių projektų tyrinėjimas yra puikus būdas išmokti\n\n18\n00:01:13.410 --> 00:01:15.983\nkaip naudotis skirtingais blokais ir funkcionavimu.\n\n19\n00:01:17.060 --> 00:01:18.950\nKai būsite pasirengę išbandyti savo projektą,\n\n20\n00:01:18.950 --> 00:01:22.083\njį galite parsisiųsti ir paleisti savo \"V5\" roboto smegenyse.\n\n21\n00:01:25.620 --> 00:01:28.020\nNorėdami sužinoti daugiau apie programą \"VEXcode V5\",\n\n22\n00:01:28.020 --> 00:01:30.740\npasižiūrėkite kitą pavyzdinę vaizdo medžiagą.\n\n23\n00:01:30.740 --> 00:01:31.573\nSmagaus.\n\n","lv":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>V5 bloku projektā</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nvariet programmēt V5 robotu, lai veiktu dažādas lietas.\n\n3\n00:00:05.790 --> 00:00:09.053\nKatrs projekts tiek sākts, izveidojot starta bloku.\n\n4\n00:00:10.030 --> 00:00:11.260\nIr daudz dažādu bloku,\n\n5\n00:00:11.260 --> 00:00:13.333\nko var izmantot robotu programmēšanai.\n\n6\n00:00:18.680 --> 00:00:20.923\nPievienosim dažus blokus mūsu projektam.\n\n7\n00:00:25.010 --> 00:00:27.940\nBlokus var viegli salikt kopā,\n\n8\n00:00:27.940 --> 00:00:31.863\npārkārtot un dzēst.\n\n9\n00:00:34.880 --> 00:00:37.980\nKā arī izmantojiet V5 motorus un sensorus projektā,\n\n10\n00:00:37.980 --> 00:00:40.713\npievienojot ierīces logā “Devices”.\n\n11\n00:00:48.840 --> 00:00:50.750\nPievienojot ierīci, tiks pievienoti bloki\n\n12\n00:00:50.750 --> 00:00:53.423\nun kategorijas jūsu projekta rīklodziņā.\n\n13\n00:00:54.820 --> 00:00:56.310\nVai nepieciešama palīdzība bloka lietošanai?\n\n14\n00:00:56.310 --> 00:00:57.743\nPalīdzības saņemšana ir vienkārša.\n\n15\n00:00:59.600 --> 00:01:02.093\nAtlasiet bloku, lai uzzinātu, kā tas darbojas.\n\n16\n00:01:04.520 --> 00:01:08.233\nVēl viens lielisks veids, kā mācīties, ir ar paraugu projektiem.\n\n17\n00:01:10.610 --> 00:01:13.410\nParaugu projektu pārskatīšana ir lielisks veids, lai uzzinātu,\n\n18\n00:01:13.410 --> 00:01:15.983\nkā izmantot dažādus blokus un to funkcijas.\n\n19\n00:01:17.060 --> 00:01:18.950\nKad būsi gatavs izmēģināt savu projektu,\n\n20\n00:01:18.950 --> 00:01:22.083\nvariet to ielādēt un palaist, izmantojot V5 robota smadzenes.\n\n21\n00:01:25.620 --> 00:01:28.020\nLai uzzinātu vairāk par VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\napskatiet citus mācību video.\n\n23\n00:01:30.740 --> 00:01:31.573\nIzklaidējies!\n\n","nl":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>In een V5 blokken project,</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nkunt u een V5 robot programmeren om veel dingen te doen.\n\n3\n00:00:05.790 --> 00:00:09.053\nElk project begint met een wanneer gestart blok.\n\n4\n00:00:10.030 --> 00:00:11.260\nEr zijn veel verschillende blokken\n\n5\n00:00:11.260 --> 00:00:13.333\ndie je kunt gebruiken om je robot te programmeren.\n\n6\n00:00:18.680 --> 00:00:20.923\nLaten we een paar blokken aan ons project toevoegen.\n\n7\n00:00:25.010 --> 00:00:27.940\nBlokken kunnen eenvoudig op elkaar worden gestapeld,\n\n8\n00:00:27.940 --> 00:00:31.863\nopnieuw worden gerangschikt en verwijderd.\n\n9\n00:00:34.880 --> 00:00:37.980\nU kunt ook V5 motoren en -sensoren in uw project\n\n10\n00:00:37.980 --> 00:00:40.713\ngebruiken door apparaten toe te voegen in het apparatenvenster.\n\n11\n00:00:48.840 --> 00:00:50.750\nDoor een apparaat toe te voegen, worden blokken\n\n12\n00:00:50.750 --> 00:00:53.423\nen categorieën toegevoegd aan de werkbalk van uw project.\n\n13\n00:00:54.820 --> 00:00:56.310\nHulp nodig met een blok?\n\n14\n00:00:56.310 --> 00:00:57.743\nHulp krijgen is eenvoudig.\n\n15\n00:00:59.600 --> 00:01:02.093\nSelecteer een blok om te leren hoe het werkt.\n\n16\n00:01:04.520 --> 00:01:08.233\nEen andere geweldige plek om te leren is van voorbeeldprojecten.\n\n17\n00:01:10.610 --> 00:01:13.410\nHet verkennen van voorbeeldprojecten is een geweldige manier\n\n18\n00:01:13.410 --> 00:01:15.983\nom te leren hoe u verschillende blokken en gedragingen kunt gebruiken.\n\n19\n00:01:17.060 --> 00:01:18.950\nZodra je klaar bent om je project uit te proberen,\n\n20\n00:01:18.950 --> 00:01:22.083\nkunt u het downloaden en uitvoeren op uw V5 robot brein.\n\n21\n00:01:25.620 --> 00:01:28.020\nVoor meer informatie over VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nbekijk de andere instructievideo's.\n\n23\n00:01:30.740 --> 00:01:31.573\nVeel plezier.\n\n","pl":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>W projekcie bloków V5</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nmożesz zaprogramować V5 aby robił wiele rzeczy.\n\n3\n00:00:05.790 --> 00:00:09.053\nKażdy projekt zaczyna się od bloku \"po uruchomieniu\".\n\n4\n00:00:10.030 --> 00:00:11.260\nIstnieje wiele różnych bloków\n\n5\n00:00:11.260 --> 00:00:13.333\nktórych możesz użyć do programowania swojego robota.\n\n6\n00:00:18.680 --> 00:00:20.923\nDodajmy kilka bloków do naszego projektu.\n\n7\n00:00:25.010 --> 00:00:27.940\nBloki można łatwo zestawić razem,\n\n8\n00:00:27.940 --> 00:00:31.863\nzmieniono kolejność i usunięto.\n\n9\n00:00:34.880 --> 00:00:37.980\nMożesz również używać silników i czujników w swoim projekcie\n\n10\n00:00:37.980 --> 00:00:40.713\ndodawając urządzenia w oknie urządzeń.\n\n11\n00:00:48.840 --> 00:00:50.750\nDodanie urządzenia spowoduje dodanie bloków\n\n12\n00:00:50.750 --> 00:00:53.423\noraz kategorie do zestawu narzędzi twojego projektu.\n\n13\n00:00:54.820 --> 00:00:56.310\nPotrzebujesz pomocy z blokiem?\n\n14\n00:00:56.310 --> 00:00:57.743\nUzyskanie pomocy jest łatwe.\n\n15\n00:00:59.600 --> 00:01:02.093\nWybierz blok, aby dowiedzieć się jak działa.\n\n16\n00:01:04.520 --> 00:01:08.233\nInnym wspaniałym miejscem do nauki są przykładowe projekty.\n\n17\n00:01:10.610 --> 00:01:13.410\nEksploracja przykładowych projektów to świetny sposób na naukę\n\n18\n00:01:13.410 --> 00:01:15.983\naby dowiedzieć się, jak używać różnych bloków i zachowań.\n\n19\n00:01:17.060 --> 00:01:18.950\nKiedy już będziesz gotowy wypróbować swój projekt,\n\n20\n00:01:18.950 --> 00:01:22.083\nmożesz pobrać i uruchomić go na swoim V5 Brain.\n\n21\n00:01:25.620 --> 00:01:28.020\nAby dowiedzieć się więcej o VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nspójrz na inne filmy z samouczkiem.\n\n23\n00:01:30.740 --> 00:01:31.573\nMiłej zabawy.\n\n","ru":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>В блоковом проекте</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nвы можете запрограммировать робота V5 на множество действий.\n\n3\n00:00:05.790 --> 00:00:09.053\nКаждый проект начинается с блока начала.\n\n4\n00:00:10.030 --> 00:00:11.260\nСуществует множество блоков\n\n5\n00:00:11.260 --> 00:00:13.333\nдля программирования вашего робота.\n\n6\n00:00:18.680 --> 00:00:20.923\nДавайте добавим новые блоки к нашему проекту.\n\n7\n00:00:25.010 --> 00:00:27.940\nБлоки легко могут быть соединены между собой,\n\n8\n00:00:27.940 --> 00:00:31.863\nреогранизованы или удалены.\n\n9\n00:00:34.880 --> 00:00:37.980\nВы можете использовать приводы и датчики в вашем проекте,\n\n10\n00:00:37.980 --> 00:00:40.713\nдобавив соответствующие устройства в окне добавления устройств.\n\n11\n00:00:48.840 --> 00:00:50.750\nДобавление устройства разблокирует новые блоки\n\n12\n00:00:50.750 --> 00:00:53.423\nи категории в инструментарии.\n\n13\n00:00:54.820 --> 00:00:56.310\nНужна помощь с блоком?\n\n14\n00:00:56.310 --> 00:00:57.743\nЭту информацию легко получить.\n\n15\n00:00:59.600 --> 00:01:02.093\nВыберите блок для получения информации о нём.\n\n16\n00:01:04.520 --> 00:01:08.233\nОдним из способов обучения является изучение примеров проектов.\n\n17\n00:01:10.610 --> 00:01:13.410\nИзучение примеров проектов - это простой путь к изучению\n\n18\n00:01:13.410 --> 00:01:15.983\nповедения блоков.\n\n19\n00:01:17.060 --> 00:01:18.950\nКак только ваш проект будет готов,\n\n20\n00:01:18.950 --> 00:01:22.083\nвы можете загрузить и запустить его на контроллере.\n\n21\n00:01:25.620 --> 00:01:28.020\nДля получения более подробной информации\n\n22\n00:01:28.020 --> 00:01:30.740\nознакомьтесь с другими обучающими видео.\n\n23\n00:01:30.740 --> 00:01:31.573\nПовеселитесь.\n\n","th":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>ใน V5 บล็อกโปรเจ็คนั้น</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nคุณสามารถโปรแกรมหุ่นยนต์ V5 ของคุณ ให้ทำสิ่งต่างๆได้มากมาย\n\n3\n00:00:05.790 --> 00:00:09.053\nในแต่ล่ะโปรเจ็คจะเริ่มต้นด้วย started block\n\n4\n00:00:10.030 --> 00:00:11.260\nมีบล็อกต่างๆมากมายหลายแบบ\n\n5\n00:00:11.260 --> 00:00:13.333\nที่คุณสามารถใช้โปรแกรมหุ่นยนต์ของคุณ\n\n6\n00:00:18.680 --> 00:00:20.923\nมาเพิ่ม blocks สักสองสามอันในโปรเจ็คของเรากันดีกว่า\n\n7\n00:00:25.010 --> 00:00:27.940\nบล็อกสามารถเชื่อมติดกันได้อย่างง่ายดาย\n\n8\n00:00:27.940 --> 00:00:31.863\nนอกจากนี้ยังสามารถเรียงลำดับใหม่ หรือลบบล็อกได้เช่นกัน\n\n9\n00:00:34.880 --> 00:00:37.980\nนอกจากนี้คุณยังสามารถใช้ V5 มอเตอร์และเซ็นเซอร์ในโปรเจ็คของคุณ\n\n10\n00:00:37.980 --> 00:00:40.713\nโดยการเพิ่มอุปกรณ์ในหน้าต่างอุปกรณ์ Devices window\n\n11\n00:00:48.840 --> 00:00:50.750\nการเพิ่มอุปกรณ์จะเพิ่มบล็อกและ categories ไปที่แท็บอุปกรณ์ (toolbox) ของโปรเจ็คของคุณ\n\n12\n00:00:50.750 --> 00:00:53.423\nและ categories ไปที่แท็บอุปกรณ์ (toolbox) ของโปรเจ็คของคุณ\n\n13\n00:00:54.820 --> 00:00:56.310\nหากต้องการความช่วยเหลือเกี่ยวกับบล็อก?\n\n14\n00:00:56.310 --> 00:00:57.743\nการขอความช่วยเหลือนั้นง่ายมาก.\n\n15\n00:00:59.600 --> 00:01:02.093\nโดยการเลือกบล็อกที่คุณต้องการ เพื่อเรียนรู้การใช้งาน\n\n16\n00:01:04.520 --> 00:01:08.233\nนอกจากนี้คุณยังสามารถเรียนรู้เพิ่มเติมได้จากโปรเจ็คตัวอย่าง\n\n17\n00:01:10.610 --> 00:01:13.410\nการทดลองใช้โปรเจ็คตัวอย่างเพื่อการเรียนรู้เป็นวิธีการที่ยอดเยี่ยมที่จะ\n\n18\n00:01:13.410 --> 00:01:15.983\nในการศึกษาการใช้บล็อกที่แตกต่างกันและพฤติกรรมที่แตกต่างกัน\n\n19\n00:01:17.060 --> 00:01:18.950\nเมื่อคุณพร้อมที่จะเริ่มทดลองใช้งานโปรเจ็คของคุณ\n\n20\n00:01:18.950 --> 00:01:22.083\nคุณสามารถดาวน์โหลดและเรียกใช้บนสมองหุ่นยนต์ V5 brain ของคุณ\n\n21\n00:01:25.620 --> 00:01:28.020\nนอกจากนี้หากต้องการเรียนรู้เพิ่มเติมเกี่ยวกับ VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nคุณสามารถเรียนรู้ได้จากวิดีโอการสอน (tutorial videos)\n\n23\n00:01:30.740 --> 00:01:31.573\nขอให้สนุก\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>У блоковому проєкті V5</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nви можете запрограмувати робота V5 робити різні речі.\n\n3\n00:00:05.790 --> 00:00:09.053\nКожен проєкт починається з блока \"коли почнемо\".\n\n4\n00:00:10.030 --> 00:00:11.260\nЄ багато різних блоків,\n\n5\n00:00:11.260 --> 00:00:13.333\nякі ви можете використати для програмування робота.\n\n6\n00:00:18.680 --> 00:00:20.923\nНумо додамо кілька блоків до нашого проєкту.\n\n7\n00:00:25.010 --> 00:00:27.940\nБлоки можна легко об'єднувати,\n\n8\n00:00:27.940 --> 00:00:31.863\nпереставляти і видаляти.\n\n9\n00:00:34.880 --> 00:00:37.980\nВи також можете використовувати V5 мотори і датчики у проєкті,\n\n10\n00:00:37.980 --> 00:00:40.713\nдодавши ці пристрої у вікні пристроїв.\n\n11\n00:00:48.840 --> 00:00:50.750\nПісля додавання пристроїв нові блоки\n\n12\n00:00:50.750 --> 00:00:53.423\nі категорії з'являться у наборі блоків.\n\n13\n00:00:54.820 --> 00:00:56.310\nПотрібна допомога з блоками?\n\n14\n00:00:56.310 --> 00:00:57.743\nОтримати допомогу легко.\n\n15\n00:00:59.600 --> 00:01:02.093\nВиберіть блок, щоб дізнатись, як він працює.\n\n16\n00:01:04.520 --> 00:01:08.233\nІнше чудове місце для навчання - приклади проєктів.\n\n17\n00:01:10.610 --> 00:01:13.410\nДослідження прикладів проєктів - чудовий спосіб навчитися\n\n18\n00:01:13.410 --> 00:01:15.983\nвикористовувати різні блоки і принцип їхньої роботи.\n\n19\n00:01:17.060 --> 00:01:18.950\nЩойно проєкт буде готовий до використання,\n\n20\n00:01:18.950 --> 00:01:22.083\nви можете завантажити і запустити його у V5 Brain.\n\n21\n00:01:25.620 --> 00:01:28.020\nЩоб дізнатися більше про VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nперегляньте відео з інших посібників.\n\n23\n00:01:30.740 --> 00:01:31.573\nХай щастить.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>Trong dự án khối V5,</v>\n\n2\n00:00:02.050 --> 00:00:05.790\nbạn có thể lập trình rô bốt V5 của mình để làm nhiều việc.\n\n3\n00:00:05.790 --> 00:00:09.053\nMọi dự án đều bắt đầu với một khối khi bắt đầu.\n\n4\n00:00:10.030 --> 00:00:11.260\nCó nhiều khối khác nhau\n\n5\n00:00:11.260 --> 00:00:13.333\nmà bạn có thể sử dụng để lập trình rô bốt của mình.\n\n6\n00:00:18.680 --> 00:00:20.923\nHãy thêm một vài khối vào dự án của chúng tôi.\n\n7\n00:00:25.010 --> 00:00:27.940\nCác khối có thể dễ dàng được xếp chồng lên nhau,\n\n8\n00:00:27.940 --> 00:00:31.863\nsắp xếp lại và xóa.\n\n9\n00:00:34.880 --> 00:00:37.980\nĐồng thời sử dụng động cơ và cảm biến V5 trong dự án của bạn\n\n10\n00:00:37.980 --> 00:00:40.713\nbằng cách thêm thiết bị trong cửa sổ Thiết bị.\n\n11\n00:00:48.840 --> 00:00:50.750\nThêm thiết bị sẽ thêm khối\n\n12\n00:00:50.750 --> 00:00:53.423\nvà các danh mục cho hộp công cụ của dự án của bạn.\n\n13\n00:00:54.820 --> 00:00:56.310\nCần giúp đỡ với một khối?\n\n14\n00:00:56.310 --> 00:00:57.743\nNhận trợ giúp rất dễ dàng.\n\n15\n00:00:59.600 --> 00:01:02.093\nChọn một khối để tìm hiểu cách thức hoạt động của nó.\n\n16\n00:01:04.520 --> 00:01:08.233\nMột nơi tuyệt vời khác để học là với các dự án mẫu.\n\n17\n00:01:10.610 --> 00:01:13.410\nKhám phá các dự án ví dụ là một cách tuyệt vời để học\n\n18\n00:01:13.410 --> 00:01:15.983\ncách sử dụng các khối và hành vi khác nhau.\n\n19\n00:01:17.060 --> 00:01:18.950\nKhi bạn đã sẵn sàng để thử dự án của mình,\n\n20\n00:01:18.950 --> 00:01:22.083\nbạn có thể tải xuống và chạy nó trên bộ não robot V5 của mình.\n\n21\n00:01:25.620 --> 00:01:28.020\nĐể tìm hiểu thêm về VEXcode V5,\n\n22\n00:01:28.020 --> 00:01:30.740\nhãy xem các video hướng dẫn khác.\n\n23\n00:01:30.740 --> 00:01:31.573\nChúc vui vẻ.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\ncrwdns96150:0crwdne96150:0\n\n2\n00:00:02.050 --> 00:00:05.790\ncrwdns96152:0crwdne96152:0\n\n3\n00:00:05.790 --> 00:00:09.053\ncrwdns96154:0crwdne96154:0\n\n4\n00:00:10.030 --> 00:00:11.260\ncrwdns96156:0crwdne96156:0\n\n5\n00:00:11.260 --> 00:00:13.333\ncrwdns96158:0crwdne96158:0\n\n6\n00:00:18.680 --> 00:00:20.923\ncrwdns96160:0crwdne96160:0\n\n7\n00:00:25.010 --> 00:00:27.940\ncrwdns96162:0crwdne96162:0\n\n8\n00:00:27.940 --> 00:00:31.863\ncrwdns96164:0crwdne96164:0\n\n9\n00:00:34.880 --> 00:00:37.980\ncrwdns96166:0crwdne96166:0\n\n10\n00:00:37.980 --> 00:00:40.713\ncrwdns96168:0crwdne96168:0\n\n11\n00:00:48.840 --> 00:00:50.750\ncrwdns96170:0crwdne96170:0\n\n12\n00:00:50.750 --> 00:00:53.423\ncrwdns96172:0crwdne96172:0\n\n13\n00:00:54.820 --> 00:00:56.310\ncrwdns96174:0crwdne96174:0\n\n14\n00:00:56.310 --> 00:00:57.743\ncrwdns96176:0crwdne96176:0\n\n15\n00:00:59.600 --> 00:01:02.093\ncrwdns96178:0crwdne96178:0\n\n16\n00:01:04.520 --> 00:01:08.233\ncrwdns96180:0crwdne96180:0\n\n17\n00:01:10.610 --> 00:01:13.410\ncrwdns96182:0crwdne96182:0\n\n18\n00:01:13.410 --> 00:01:15.983\ncrwdns96184:0crwdne96184:0\n\n19\n00:01:17.060 --> 00:01:18.950\ncrwdns96186:0crwdne96186:0\n\n20\n00:01:18.950 --> 00:01:22.083\ncrwdns96188:0crwdne96188:0\n\n21\n00:01:25.620 --> 00:01:28.020\ncrwdns96190:0crwdne96190:0\n\n22\n00:01:28.020 --> 00:01:30.740\ncrwdns96192:0crwdne96192:0\n\n23\n00:01:30.740 --> 00:01:31.573\ncrwdns96194:0crwdne96194:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.210 --> 00:00:02.050\n<v Announcer>在V5指令块程序中，</v>\n\n2\n00:00:02.050 --> 00:00:05.790\n您可以编程V5机器人去做许多事情。\n\n3\n00:00:05.790 --> 00:00:09.053\n每一个程序都以“当开始”指令块开头。\n\n4\n00:00:10.030 --> 00:00:11.260\n你可以使用许多不同的指令块\n\n5\n00:00:11.260 --> 00:00:13.333\n来为你的机器人编程。\n\n6\n00:00:18.680 --> 00:00:20.923\n让我们添加几个指令块到程序里。\n\n7\n00:00:25.010 --> 00:00:27.940\n指令块可以容易地叠搭在一起，\n\n8\n00:00:27.940 --> 00:00:31.863\n重新排列，以及删除。\n\n9\n00:00:34.880 --> 00:00:37.980\n在程序中也使用V5电机和传感器\n\n10\n00:00:37.980 --> 00:00:40.713\n通过“设备”窗口添加设备。\n\n11\n00:00:48.840 --> 00:00:50.750\n添加设备也将增加指令块\n\n12\n00:00:50.750 --> 00:00:53.423\n和类别到您的程序工具栏。\n\n13\n00:00:54.820 --> 00:00:56.310\n需要关于某个指令块的帮助吗？\n\n14\n00:00:56.310 --> 00:00:57.743\n获取帮助也很容易。\n\n15\n00:00:59.600 --> 00:01:02.093\n选中一个指令块来学习它如何应用。\n\n16\n00:01:04.520 --> 00:01:08.233\n另外一个学习的好地方是样例程序。\n\n17\n00:01:10.610 --> 00:01:13.410\n探究样例程序是一个很好的学习如何应用\n\n18\n00:01:13.410 --> 00:01:15.983\n不同指令块和动作的方式。\n\n19\n00:01:17.060 --> 00:01:18.950\n一旦您准备好测试程序，\n\n20\n00:01:18.950 --> 00:01:22.083\n您可以下载并在V5主控器上运行它。\n\n21\n00:01:25.620 --> 00:01:28.020\n欲了解更多关于 VEXcode V5，\n\n22\n00:01:28.020 --> 00:01:30.740\n看看其他的辅导视频。\n\n23\n00:01:30.740 --> 00:01:31.573\n玩得开心。\n\n"}},{"thumb":"V5_Tutorial_deviceSetup_drivetrain.jpg","mov":"V5_Blocks_DeviceSetup_Drivetrain_V2_V2","description":"Device Setup - Drivetrain","filter":"","placeholder":false,"vimeo":"475898726","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Drivetrains allow your V5 robot</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nto drive and turn precise distances with a single block.\n\n3\n00:00:06.460 --> 00:00:08.370\nYou can add a drivetrain to your project\n\n4\n00:00:08.370 --> 00:00:10.370\nwith the devices window.\n\n5\n00:00:10.370 --> 00:00:11.880\nOpen the devices window\n\n6\n00:00:14.350 --> 00:00:16.363\nand select Add a device.\n\n7\n00:00:17.460 --> 00:00:19.707\nNext, select Drivetrain.\n\n8\n00:00:22.120 --> 00:00:24.491\nFirst, select the ports for your left\n\n9\n00:00:24.491 --> 00:00:28.600\nand right V5 smart motors in your drivetrain.\n\n10\n00:00:28.600 --> 00:00:32.341\nNext, select if your drive train has a gyro sensor.\n\n11\n00:00:32.341 --> 00:00:34.960\nIf your drivetrain does have an inertial sensor,\n\n12\n00:00:34.960 --> 00:00:37.850\nselect the inertial sensor option\n\n13\n00:00:37.850 --> 00:00:40.713\nand the smart port the inertial is connected to.\n\n14\n00:00:43.180 --> 00:00:45.950\nIf your drivetrain does have a three-wire gyro,\n\n15\n00:00:45.950 --> 00:00:48.380\nselect the three-wire gyro option\n\n16\n00:00:49.740 --> 00:00:52.603\nand the port the three-wire gyro is connected to.\n\n17\n00:00:54.750 --> 00:00:57.820\nIf your drivetrain does not have a three-wire gyro,\n\n18\n00:00:57.820 --> 00:01:00.053\nselect the No Gyro option.\n\n19\n00:01:01.430 --> 00:01:04.160\nNow, let's configure the drivetrain.\n\n20\n00:01:04.160 --> 00:01:06.520\nFirst, look at the wheels on your drivetrain\n\n21\n00:01:06.520 --> 00:01:09.413\nand select the wheel size from the dropdown.\n\n22\n00:01:12.860 --> 00:01:16.030\nNext, take a look at the gears and the drivetrain\n\n23\n00:01:16.030 --> 00:01:18.940\nand enter the input and output gear ratio.\n\n24\n00:01:18.940 --> 00:01:20.940\nIf you did not have a gyro sensor,\n\n25\n00:01:20.940 --> 00:01:22.270\nyou will see two settings\n\n26\n00:01:22.270 --> 00:01:25.370\nfor the track width and wheel base.\n\n27\n00:01:25.370 --> 00:01:27.880\nTrack width is the width of the drivetrain.\n\n28\n00:01:27.880 --> 00:01:29.480\nMeasure the width of your drivetrain\n\n29\n00:01:29.480 --> 00:01:30.943\nand update this setting.\n\n30\n00:01:33.200 --> 00:01:36.390\nWheel base is the distance between the center of the front\n\n31\n00:01:36.390 --> 00:01:38.360\nand back wheels.\n\n32\n00:01:38.360 --> 00:01:40.450\nMeasure the distance between the two wheels\n\n33\n00:01:40.450 --> 00:01:42.043\nand update this setting.\n\n34\n00:01:43.310 --> 00:01:46.330\nNext, select which gear cartridge is installed\n\n35\n00:01:46.330 --> 00:01:48.253\nin your V5 smart motors.\n\n36\n00:01:50.730 --> 00:01:53.680\nLastly, if your drivetrain drives in reverse,\n\n37\n00:01:53.680 --> 00:01:55.520\nwhen programmed to drive forward,\n\n38\n00:01:55.520 --> 00:01:58.220\nchange the direction arrow to reverse your drivetrain.\n\n39\n00:01:59.850 --> 00:02:01.170\nSelect the Done button\n\n40\n00:02:03.180 --> 00:02:06.343\nand the drivetrain blocks will now appear in the toolbox.\n\n41\n00:02:07.180 --> 00:02:10.173\nYour drivetrain is now configured and ready to use.\n\n","ar":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v -> نظام الدفع يسمح للروبوت الخاص بك</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nبالقيادة ودوران مسافات دقيقة بإستخدام مقطع برمجة واحد.\n\n3\n00:00:06.460 --> 00:00:08.370\nيمكنك إضافة نظام دفع إلى مشروعك\n\n4\n00:00:08.370 --> 00:00:10.370\nمن نافذة الأجهزة.\n\n5\n00:00:10.370 --> 00:00:11.880\nافتح نافذة الأجهزة\n\n6\n00:00:14.350 --> 00:00:16.363\nواختر إضافة جهاز.\n\n7\n00:00:17.460 --> 00:00:19.707\nبعد ذلك، إختر نظام دفع.\n\n8\n00:00:22.120 --> 00:00:24.491\nأولاً، حدد المنافذ للجانب الأيسر\n\n9\n00:00:24.491 --> 00:00:28.600\nوالجانب الأيمن المحتوية على محركات V5 الذكية في نظام الدفع.\n\n10\n00:00:28.600 --> 00:00:32.341\nبعد ذلك، حدد إذا يحتوي نظام الدفع على gyro.\n\n11\n00:00:32.341 --> 00:00:34.960\nإذا يحتوي نظام الدفع على gyro\n\n12\n00:00:34.960 --> 00:00:37.850\nحدد خيارات gyro\n\n13\n00:00:37.850 --> 00:00:40.713\nوالمنفذ المرتبط ب gyro.\n\n14\n00:00:43.180 --> 00:00:45.950\nإذا يحتوي نظام الدفع على gyro ذا ثلاثة أسلاك\n\n15\n00:00:45.950 --> 00:00:48.380\nحدد خيار gyro ذا ثلاثة أسلاك\n\n16\n00:00:49.740 --> 00:00:52.603\nوالمنفذ المرتبط ب-gyro ذا ثلاتة أسلاك.\n\n17\n00:00:54.750 --> 00:00:57.820\nإذا لا يحتوي نظام الدفع على gyro ذا ثلاثة أسلاك\n\n18\n00:00:57.820 --> 00:01:00.053\nحدد خيار \" Gyro غير متوفر\".\n\n19\n00:01:01.430 --> 00:01:04.160\nالآن، دعونا نحدد إعدادات نظام الدفع.\n\n20\n00:01:04.160 --> 00:01:06.520\nأولاً، انظر إلى العجلات على نظام الدفع الخاص بك\n\n21\n00:01:06.520 --> 00:01:09.413\nوحدد حجم العجلة من القائمة.\n\n22\n00:01:12.860 --> 00:01:16.030\nبعد ذلك، ألقي نظرة على نظام دفع و العجلات المسننة\n\n23\n00:01:16.030 --> 00:01:18.940\nو أدخل نسبة إدخال و الإخراج العجلات المسننة.\n\n24\n00:01:18.940 --> 00:01:20.940\nإذا لم يكن لديك مستشعر جيروسكوب\n\n25\n00:01:20.940 --> 00:01:22.270\nسوف ترى إعدادان\n\n26\n00:01:22.270 --> 00:01:25.370\nلعرض المسار وقاعدة العجلات.\n\n27\n00:01:25.370 --> 00:01:27.880\nعرض المسار هو عرض نظام الدفع.\n\n28\n00:01:27.880 --> 00:01:29.480\nقس عرض نظام الدفع الخاص بك\n\n29\n00:01:29.480 --> 00:01:30.943\nوقم بتحديث هذه الإعدادات.\n\n30\n00:01:33.200 --> 00:01:36.390\nقاعدة العجلة هي المسافة بين وسط العجلات الأمامية\n\n31\n00:01:36.390 --> 00:01:38.360\nوالعجلات الخلفية.\n\n32\n00:01:38.360 --> 00:01:40.450\nقس المسافة بين العجلتين\n\n33\n00:01:40.450 --> 00:01:42.043\nوقم بتحديث هذه الإعدادات.\n\n34\n00:01:43.310 --> 00:01:46.330\nثم، إختر معدات المسننة المركبة\n\n35\n00:01:46.330 --> 00:01:48.253\nفي محركات V5 الذكية.\n\n36\n00:01:50.730 --> 00:01:53.680\nأخيرا، إذا كان نظام الدفع في اتجاه عكسي،\n\n37\n00:01:53.680 --> 00:01:55.520\nعند برمجته للدفع إلى الأمام,\n\n38\n00:01:55.520 --> 00:01:58.220\nغير اتجاه السهم لعكس مسارنظام الدفع الخاص بك.\n\n39\n00:01:59.850 --> 00:02:01.170\nحدد زر الانتهاء\n\n40\n00:02:03.180 --> 00:02:06.343\nوستظهر الآن مقاطع المحركات في صندوق الإعدادات.\n\n41\n00:02:07.180 --> 00:02:10.173\nنظام الدفع الخاص بك الآن مهيئ و جاهز للاستخدام.\n\n","cs":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Podvozky umožňují tvému V5 robotovi</v>\n\n2\n00:00:02.480 --> 00:00:06.460\njet a zatáčet o přesné vzdálenosti, pomocí jednoho bloku.\n\n3\n00:00:06.460 --> 00:00:08.370\nPodvozek můžeš přidat do svého projektu\n\n4\n00:00:08.370 --> 00:00:10.370\npomocí okna Zařízení.\n\n5\n00:00:10.370 --> 00:00:11.880\nOtevři okno Zařízení\n\n6\n00:00:14.350 --> 00:00:16.363\na vyber Přidat zařízení.\n\n7\n00:00:17.460 --> 00:00:19.707\nDále vyber Podvozek.\n\n8\n00:00:22.120 --> 00:00:24.491\nNejprve vyber porty pro tvůj levý\n\n9\n00:00:24.491 --> 00:00:28.600\na pravý chytrý V5 motor na tvém podvozku.\n\n10\n00:00:28.600 --> 00:00:32.341\nDále vyber, jestli má tvůj podvozek gyroskopický senzor.\n\n11\n00:00:32.341 --> 00:00:34.960\nJestliže má tvůj podvozek setrvačníkový senzor,\n\n12\n00:00:34.960 --> 00:00:37.850\nvyber možnost Setrvačníkový senzor\n\n13\n00:00:37.850 --> 00:00:40.713\na k jakému chytrému portu je setrvačník připojen.\n\n14\n00:00:43.180 --> 00:00:45.950\nJestliže má tvůj podvozek třídrátový gyroskop,\n\n15\n00:00:45.950 --> 00:00:48.380\nvyber možnost Třídrátový gyroskop\n\n16\n00:00:49.740 --> 00:00:52.603\na k jakému portu je třídrátový gyroskop připojen.\n\n17\n00:00:54.750 --> 00:00:57.820\nJestliže tvůj podvozek nemá třídrátový gyroskop,\n\n18\n00:00:57.820 --> 00:01:00.053\nvyber možnost Bez gyroskopu.\n\n19\n00:01:01.430 --> 00:01:04.160\nNyní pojďme nastavit podvozek.\n\n20\n00:01:04.160 --> 00:01:06.520\nNejprve se podívej na kola svého podvozku\n\n21\n00:01:06.520 --> 00:01:09.413\na vyber velikost kola z rozbalovacího seznamu.\n\n22\n00:01:12.860 --> 00:01:16.030\nDále se podívej na ozubená kola tvého podvozku\n\n23\n00:01:16.030 --> 00:01:18.940\na zadej vstupní a výstupní převodový poměr.\n\n24\n00:01:18.940 --> 00:01:20.940\nJestliže nemáš gyroskopický senzor,\n\n25\n00:01:20.940 --> 00:01:22.270\nuvidíš dvě nastavení\n\n26\n00:01:22.270 --> 00:01:25.370\npro šířku rozchodu kol a rozvor.\n\n27\n00:01:25.370 --> 00:01:27.880\nŠířka rozchodu kol je šířka podvozku.\n\n28\n00:01:27.880 --> 00:01:29.480\nZměř šířku svého podvozku\n\n29\n00:01:29.480 --> 00:01:30.943\na aktualizuj toto nastavení.\n\n30\n00:01:33.200 --> 00:01:36.390\nRozvor je vzdálenost mezi středem předních\n\n31\n00:01:36.390 --> 00:01:38.360\na zadních kol.\n\n32\n00:01:38.360 --> 00:01:40.450\nZměř vzdálenost mezi těmito dvěma koly\n\n33\n00:01:40.450 --> 00:01:42.043\na aktualizuj toto nastavení.\n\n34\n00:01:43.310 --> 00:01:46.330\nDále vyber jaká převodová vložka je namontována\n\n35\n00:01:46.330 --> 00:01:48.253\nna tvém chytrém V5 motoru.\n\n36\n00:01:50.730 --> 00:01:53.680\nA nakonec, jestliže tvůj podvozek jede dozadu,\n\n37\n00:01:53.680 --> 00:01:55.520\nkdyž je naprogramovaná jet dopředu,\n\n38\n00:01:55.520 --> 00:01:58.220\nzměň směrovou šipku k obrácení tvého podvozku.\n\n39\n00:01:59.850 --> 00:02:01.170\nVyber tlačítko Hotovo\n\n40\n00:02:03.180 --> 00:02:06.343\na bloky Podvozku se nyní objeví na panelu nástrojů.\n\n41\n00:02:07.180 --> 00:02:10.173\nTvůj podvozek je nyní nastaven a připraven k použití.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Las sistemas de Tren Motriz permiten que su robot V5</v>\n\n2\n00:00:02.480 --> 00:00:06.460\npara conducir y girar distancias precisas con un solo bloque.\n\n3\n00:00:06.460 --> 00:00:08.370\nPuede añadir un tren motriz a su proyecto\n\n4\n00:00:08.370 --> 00:00:10.370\ncon la ventana de dispositivos.\n\n5\n00:00:10.370 --> 00:00:11.880\nAbra la ventana de Dispositivos\n\n6\n00:00:14.350 --> 00:00:16.363\ny seleccione Agregar un Dispositivo.\n\n7\n00:00:17.460 --> 00:00:19.707\nA continuación, seleccione Tren Motriz.\n\n8\n00:00:22.120 --> 00:00:24.491\nPrimero, selecciona los puertos para sus V5 Smart Motors izquierdo y\n\n9\n00:00:24.491 --> 00:00:28.600\nderecho en su Tren Motriz.\n\n10\n00:00:28.600 --> 00:00:32.341\nA continuación, seleccione si su Tren Motriz tiene un sensor de gyro.\n\n11\n00:00:32.341 --> 00:00:34.960\nSi el Tren Motriz tiene un sensor inercial,\n\n12\n00:00:34.960 --> 00:00:37.850\nseleccione la opción del sensor inercial\n\n13\n00:00:37.850 --> 00:00:40.713\ny el puerto inteligente al que está conectado la inercial.\n\n14\n00:00:43.180 --> 00:00:45.950\nSi el Tren Motriz tiene un gyro de tres hilos,\n\n15\n00:00:45.950 --> 00:00:48.380\nselecciona la opción de giro de tres hilos\n\n16\n00:00:49.740 --> 00:00:52.603\ny el puerto al que está conectado el giro de tres hilos.\n\n17\n00:00:54.750 --> 00:00:57.820\nSi el Tren Motriz no tiene un gyro de tres hilos,\n\n18\n00:00:57.820 --> 00:01:00.053\nseleccione la opción Sin Giro (No Gyro).\n\n19\n00:01:01.430 --> 00:01:04.160\nAhora vamos a configurar el Tren Motriz.\n\n20\n00:01:04.160 --> 00:01:06.520\nPrimero, mire las ruedas en su Tren Motriz\n\n21\n00:01:06.520 --> 00:01:09.413\ny seleccione el tamaño de la rueda en el menú desplegable.\n\n22\n00:01:12.860 --> 00:01:16.030\nA continuación, eche un vistazo a los engranajes y el Tren Motriz\n\n23\n00:01:16.030 --> 00:01:18.940\ne introduzca la proporción de engranajes de entrada y salida.\n\n24\n00:01:18.940 --> 00:01:20.940\nSi no tienes un gyro,\n\n25\n00:01:20.940 --> 00:01:22.270\nverá dos ajustes\n\n26\n00:01:22.270 --> 00:01:25.370\npara la anchura de chasis y la base de la rueda.\n\n27\n00:01:25.370 --> 00:01:27.880\nLa anchura del Chasis es el ancho del Tren Motriz.\n\n28\n00:01:27.880 --> 00:01:29.480\nMida el ancho de su Tren Motriz\n\n29\n00:01:29.480 --> 00:01:30.943\ny actualiza esta configuración.\n\n30\n00:01:33.200 --> 00:01:36.390\nLa base de la rueda es la distancia entre el centro del frente\n\n31\n00:01:36.390 --> 00:01:38.360\ny ruedas traseras.\n\n32\n00:01:38.360 --> 00:01:40.450\nMida la distancia entre las dos ruedas\n\n33\n00:01:40.450 --> 00:01:42.043\ny actualiza esta configuración.\n\n34\n00:01:43.310 --> 00:01:46.330\nA continuación, seleccione qué cartucho de engranajes está instalado\n\n35\n00:01:46.330 --> 00:01:48.253\nen sus V5 Smart Motors.\n\n36\n00:01:50.730 --> 00:01:53.680\nPor último, si su Tren Motriz conduce al revés,\n\n37\n00:01:53.680 --> 00:01:55.520\ncuando se programe para avanzar,\n\n38\n00:01:55.520 --> 00:01:58.220\ncambia la flecha de dirección para cambiar al revés el Tren Motriz.\n\n39\n00:01:59.850 --> 00:02:01.170\nSeleccione el botón Hecho\n\n40\n00:02:03.180 --> 00:02:06.343\ny los bloques de Tren Motriz ahora aparecerán en la caja de herramientas.\n\n41\n00:02:07.180 --> 00:02:10.173\nSu Tren Motriz ahora está configurado y listo para usar.\n\n","es":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Las sistemas de Tren Motriz permiten que su robot V5</v>\n\n2\n00:00:02.480 --> 00:00:06.460\npara conducir y girar distancias precisas con un solo bloque.\n\n3\n00:00:06.460 --> 00:00:08.370\nPuede añadir un Tren Motriz a su proyecto\n\n4\n00:00:08.370 --> 00:00:10.370\ncon la ventana de dispositivos.\n\n5\n00:00:10.370 --> 00:00:11.880\nAbra la ventana de Dispositivos\n\n6\n00:00:14.350 --> 00:00:16.363\ny seleccione Agregar un Dispositivo.\n\n7\n00:00:17.460 --> 00:00:19.707\nA continuación, seleccione Tren Motriz.\n\n8\n00:00:22.120 --> 00:00:24.491\nPrimero, selecciona los puertos para sus V5 Smart Motors izquierdo y\n\n9\n00:00:24.491 --> 00:00:28.600\nderecho en su Tren Motriz.\n\n10\n00:00:28.600 --> 00:00:32.341\nA continuación, seleccione si su Tren Motriz tiene un sensor de gyro.\n\n11\n00:00:32.341 --> 00:00:34.960\nSi el Tren Motriz tiene un sensor inercial,\n\n12\n00:00:34.960 --> 00:00:37.850\nseleccione la opción del sensor inercial\n\n13\n00:00:37.850 --> 00:00:40.713\ny el puerto inteligente al que está conectado la inercial.\n\n14\n00:00:43.180 --> 00:00:45.950\nSi el Tren Motriz tiene un gyro de tres hilos,\n\n15\n00:00:45.950 --> 00:00:48.380\nselecciona la opción de giro de tres hilos\n\n16\n00:00:49.740 --> 00:00:52.603\ny el puerto al que está conectado el giro de tres hilos.\n\n17\n00:00:54.750 --> 00:00:57.820\nSi el Tren Motriz no tiene un gyro de tres hilos,\n\n18\n00:00:57.820 --> 00:01:00.053\nseleccione la opción Sin Giro (No Gyro).\n\n19\n00:01:01.430 --> 00:01:04.160\nAhora vamos a configurar el Tren Motriz.\n\n20\n00:01:04.160 --> 00:01:06.520\nPrimero, mire las ruedas en su Tren Motriz\n\n21\n00:01:06.520 --> 00:01:09.413\ny seleccione el tamaño de la rueda en el menú desplegable.\n\n22\n00:01:12.860 --> 00:01:16.030\nA continuación, eche un vistazo a los engranajes y el Tren Motriz\n\n23\n00:01:16.030 --> 00:01:18.940\ne introduzca la proporción de engranajes de entrada y salida.\n\n24\n00:01:18.940 --> 00:01:20.940\nSi no tienes un gyro,\n\n25\n00:01:20.940 --> 00:01:22.270\nverá dos ajustes\n\n26\n00:01:22.270 --> 00:01:25.370\npara la anchura de chasis y la base de la rueda.\n\n27\n00:01:25.370 --> 00:01:27.880\nLa anchura del Chasis es el ancho del Tren Motriz.\n\n28\n00:01:27.880 --> 00:01:29.480\nMida el ancho de su Tren Motriz\n\n29\n00:01:29.480 --> 00:01:30.943\ny actualiza esta configuración.\n\n30\n00:01:33.200 --> 00:01:36.390\nLa base de la rueda es la distancia entre el centro del frente\n\n31\n00:01:36.390 --> 00:01:38.360\ny ruedas traseras.\n\n32\n00:01:38.360 --> 00:01:40.450\nMida la distancia entre las dos ruedas\n\n33\n00:01:40.450 --> 00:01:42.043\ny actualiza esta configuración.\n\n34\n00:01:43.310 --> 00:01:46.330\nA continuación, seleccione qué cartucho de engranajes está instalado\n\n35\n00:01:46.330 --> 00:01:48.253\nen sus V5 Smart Motors.\n\n36\n00:01:50.730 --> 00:01:53.680\nPor último, si su Tren Motriz conduce al revés,\n\n37\n00:01:53.680 --> 00:01:55.520\ncuando se programe para avanzar,\n\n38\n00:01:55.520 --> 00:01:58.220\ncambia la flecha de dirección para revertir el Tren Motriz.\n\n39\n00:01:59.850 --> 00:02:01.170\nSeleccione el botón Hecho\n\n40\n00:02:03.180 --> 00:02:06.343\ny los bloques de Tren Motriz ahora aparecerán en la caja de herramientas.\n\n41\n00:02:07.180 --> 00:02:10.173\nSu Tren Motriz ahora está configurado y listo para usar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Drivetrain Ajopeli -määrityksen avulla V5 robottia</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nvoi ajaa ja kääntää yhdellä ajoblokilla.\n\n3\n00:00:06.460 --> 00:00:08.370\nVoit lisätä Ajopelin ohjelmaasi\n\n4\n00:00:08.370 --> 00:00:10.370\nLaitteet -ikkunasta.\n\n5\n00:00:10.370 --> 00:00:11.880\nAvaa Latteet-ikkuna\n\n6\n00:00:14.350 --> 00:00:16.363\nja valitse Lisää laite -valinta.\n\n7\n00:00:17.460 --> 00:00:19.707\nSeuraavaksi valitse ajopelin kuvake Drivetrain.\n\n8\n00:00:22.120 --> 00:00:24.491\nEnsiksi valitse vasemman moottorin portti\n\n9\n00:00:24.491 --> 00:00:28.600\nja sitten oikean moottorin portti ajopelissä.\n\n10\n00:00:28.600 --> 00:00:32.341\nValitse jos ajopelissä on Gyro-laite.\n\n11\n00:00:32.341 --> 00:00:34.960\nJos robotissa on kääntymiskulmaa mittaava Inertial -sensori\n\n12\n00:00:34.960 --> 00:00:37.850\nvalitse se tarjolla olevista kiertokulmaa mittaavista laitteista\n\n13\n00:00:37.850 --> 00:00:40.713\nja merkitse sen älyportti robotin aivoissa.\n\n14\n00:00:43.180 --> 00:00:45.950\nJos ajopelissä on 3-johtoinen kiertokulmalaite\n\n15\n00:00:45.950 --> 00:00:48.380\nvalise sen valintakuva\n\n16\n00:00:49.740 --> 00:00:52.603\nja mihin kolmijohtoporttiin se on liitetty.\n\n17\n00:00:54.750 --> 00:00:57.820\nJos mitään kiertokulmalaitetta ei ole liitetty\n\n18\n00:00:57.820 --> 00:01:00.053\nValitse Ei gyro -vaihtoehto.\n\n19\n00:01:01.430 --> 00:01:04.160\nMääritellään Ajopelin asetukset.\n\n20\n00:01:04.160 --> 00:01:06.520\nTarkista rengaskoko ajopelistä\n\n21\n00:01:06.520 --> 00:01:09.413\nja valitse oikea koko pudotusvalikosta.\n\n22\n00:01:12.860 --> 00:01:16.030\nTarkista onko vetomoottoreissa käytetty hammaspyörävaihteita\n\n23\n00:01:16.030 --> 00:01:18.940\nja aseta oikea moottorin ja vetorenkaan välinen vaihteen suhde.\n\n24\n00:01:18.940 --> 00:01:20.940\nJos sinulla ei ole mitään kiertokulmalaitetta\n\n25\n00:01:20.940 --> 00:01:22.270\najopeliin pitää määritellä kaksi lisätekijää\n\n26\n00:01:22.270 --> 00:01:25.370\nakselin leveys ja akseliväli.\n\n27\n00:01:25.370 --> 00:01:27.880\nAkselin leveys on ajopelin leveys.\n\n28\n00:01:27.880 --> 00:01:29.480\nMittaa ajopelin leveys\n\n29\n00:01:29.480 --> 00:01:30.943\nja päivitä tämä asetus.\n\n30\n00:01:33.200 --> 00:01:36.390\nAkseliväli on etu- ja taka-akselin välin\n\n31\n00:01:36.390 --> 00:01:38.360\nmitta valitulla mittayksiköllä.\n\n32\n00:01:38.360 --> 00:01:40.450\nMittaa väli ja\n\n33\n00:01:40.450 --> 00:01:42.043\nja päivitä tämä asetus.\n\n34\n00:01:43.310 --> 00:01:46.330\nSeuraavaksi valitse moottorien käytössäaalova vaihdepakkaus\n\n35\n00:01:46.330 --> 00:01:48.253\nV5 ajomoottoreissa.\n\n36\n00:01:50.730 --> 00:01:53.680\nJos ajopeli liikkuu takaperin ajettaessa,\n\n37\n00:01:53.680 --> 00:01:55.520\nkun on ohjelmoitu ajamaan eteenpäin,\n\n38\n00:01:55.520 --> 00:01:58.220\nmuuta suunta isosta suuntanuolesta robottikuvassa oikealla.\n\n39\n00:01:59.850 --> 00:02:01.170\nValitse sitten Tehty-painike\n\n40\n00:02:03.180 --> 00:02:06.343\nja saat työkaluihin näkyviin Ajopelin ohjelmointiblokit. \n\n41\n00:02:07.180 --> 00:02:10.173\nNyt ajopeli on määritelty ja valmis käyttöön.\n\n","fr":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Les transmissions permettent à votre robot V5</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nde se déplacer dans des directions bien précises, à l'aide d'un seul bloc.\n\n3\n00:00:06.460 --> 00:00:08.370\nVous pouvez ajouter une transmission à votre projet\n\n4\n00:00:08.370 --> 00:00:10.370\ndepuis la fenêtre des appareils.\n\n5\n00:00:10.370 --> 00:00:11.880\nOuvrez la fenêtre Appareils\n\n6\n00:00:14.350 --> 00:00:16.363\net sélectionnez \"Ajouter un appareil\".\n\n7\n00:00:17.460 --> 00:00:19.707\nEnsuite, sélectionnez \"Transmission\".\n\n8\n00:00:22.120 --> 00:00:24.491\nTout d'abord, sélectionnez les ports pour les moteurs intelligents V5\n\n9\n00:00:24.491 --> 00:00:28.600\ngauches et droits et votre transmission.\n\n10\n00:00:28.600 --> 00:00:32.341\nEnsuite, sélectionnez si votre transmission a un capteur Gyro.\n\n11\n00:00:32.341 --> 00:00:34.960\nSi votre transmission a un Capteur Inertiel,\n\n12\n00:00:34.960 --> 00:00:37.850\nsélectionnez l'option du Capteur Inertiel\n\n13\n00:00:37.850 --> 00:00:40.713\net le port intelligent auquel le Capteur Inertiel est connecté.\n\n14\n00:00:43.180 --> 00:00:45.950\nSi votre transmission dispose d'un gyro à 3 fils,\n\n15\n00:00:45.950 --> 00:00:48.380\nsélectionnez l'option Gyro à 3 fils\n\n16\n00:00:49.740 --> 00:00:52.603\net le port auquel le Gyro 3 fils est connecté.\n\n17\n00:00:54.750 --> 00:00:57.820\nSi votre transmission ne dispose pas d'un Gyro à 3 fils,\n\n18\n00:00:57.820 --> 00:01:00.053\nsélectionnez l'option \"Pas de Gyro\".\n\n19\n00:01:01.430 --> 00:01:04.160\nMaintenant, configurons la transmission.\n\n20\n00:01:04.160 --> 00:01:06.520\nTout d'abord, regardez les roues sur votre transmission\n\n21\n00:01:06.520 --> 00:01:09.413\net sélectionnez la taille de roue dans la liste déroulante.\n\n22\n00:01:12.860 --> 00:01:16.030\nEnsuite, jetez un œil aux engrenages de la transmission\n\n23\n00:01:16.030 --> 00:01:18.940\net entrez le rapport entre les engrenages d'entrée et de sortie.\n\n24\n00:01:18.940 --> 00:01:20.940\nSi vous n'avez pas de capteur gyroscopique,\n\n25\n00:01:20.940 --> 00:01:22.270\nvous verrez deux paramètres\n\n26\n00:01:22.270 --> 00:01:25.370\npour la largeur de la piste et la base des roues.\n\n27\n00:01:25.370 --> 00:01:27.880\nLa largeur de la piste correspond à la largeur de la transmission.\n\n28\n00:01:27.880 --> 00:01:29.480\nMesurez la largeur de votre transmission\n\n29\n00:01:29.480 --> 00:01:30.943\net mettez à jour ce paramètre.\n\n30\n00:01:33.200 --> 00:01:36.390\nLa base de la roue est la distance entre le centre\n\n31\n00:01:36.390 --> 00:01:38.360\ndes roues avant et arrière.\n\n32\n00:01:38.360 --> 00:01:40.450\nMesurer la distance entre les deux roues\n\n33\n00:01:40.450 --> 00:01:42.043\net mettez à jour ce paramètre.\n\n34\n00:01:43.310 --> 00:01:46.330\nEnsuite, sélectionnez quelle cartouche d'engrenages est installée\n\n35\n00:01:46.330 --> 00:01:48.253\ndans vos moteurs intelligents V5.\n\n36\n00:01:50.730 --> 00:01:53.680\nEnfin, si votre transmission recule,\n\n37\n00:01:53.680 --> 00:01:55.520\nquand elle est programmée pour avancer,\n\n38\n00:01:55.520 --> 00:01:58.220\nchangez la flèche de direction pour inverser votre transmission.\n\n39\n00:01:59.850 --> 00:02:01.170\nSélectionnez le bouton \"Terminé\"\n\n40\n00:02:03.180 --> 00:02:06.343\net les blocs de la transmission apparaîtront maintenant dans la boîte à outils.\n\n41\n00:02:07.180 --> 00:02:10.173\nVotre transmission est maintenant configurée et prête à l'emploi.\n\n","ko":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->드라이브트레인을 사용하면 V5 로봇은</v>\n\n2\n00:00:02.480 --> 00:00:06.460\n단 하나의 블록으로 정확한 거리를 이동하고 돌 수 있습니다.\n\n3\n00:00:06.460 --> 00:00:08.370\n기기 창에서 프로젝트에\n\n4\n00:00:08.370 --> 00:00:10.370\n드라이브트레인을 추가할 수 있습니다.\n\n5\n00:00:10.370 --> 00:00:11.880\n기기 창을 열고\n\n6\n00:00:14.350 --> 00:00:16.363\n기기 추가를 선택합니다.\n\n7\n00:00:17.460 --> 00:00:19.707\n다음은 드라이브트레인을 선택하세요.\n\n8\n00:00:22.120 --> 00:00:24.491\n먼저 드라이브트레인의 왼쪽 및 오른쪽의\n\n9\n00:00:24.491 --> 00:00:28.600\nV5 스마트 모터용 포트를 선택하세요.\n\n10\n00:00:28.600 --> 00:00:32.341\n다음은 드라이브트레인에 자이로 센서가 있다면 선택합니다.\n\n11\n00:00:32.341 --> 00:00:34.960\n드라이브트레인에 관성 센서가 있다면\n\n12\n00:00:34.960 --> 00:00:37.850\n관성 센서 옵션과\n\n13\n00:00:37.850 --> 00:00:40.713\n관성 센서가 연결된 스마트 포트를 선택합니다.\n\n14\n00:00:43.180 --> 00:00:45.950\n드라이브트레인에 3-Wire 자이로 센서가 있으면\n\n15\n00:00:45.950 --> 00:00:48.380\n3-Wire 자이로 센서 옵션과\n\n16\n00:00:49.740 --> 00:00:52.603\n3-Wire 자이로 센서가 연결된 포트를 선택합니다.\n\n17\n00:00:54.750 --> 00:00:57.820\n드라이브트레인에 3-Wire 자이로 센서가 없으면\n\n18\n00:00:57.820 --> 00:01:00.053\n자이로 센서 없음을 선택합니다.\n\n19\n00:01:01.430 --> 00:01:04.160\n이제 드라이브트레인을 구성해 봅시다.\n\n20\n00:01:04.160 --> 00:01:06.520\n먼저 드라이브트레인의 휠을 보고\n\n21\n00:01:06.520 --> 00:01:09.413\n드롭다운 메뉴에서 휠의 크기를 선택합니다.\n\n22\n00:01:12.860 --> 00:01:16.030\n그리고 기어와 드라이브트레인을 살펴 보고\n\n23\n00:01:16.030 --> 00:01:18.940\n입력 및 출력 기어 비율을 입력하세요.\n\n24\n00:01:18.940 --> 00:01:20.940\n자이로 센서가 없는 경우,\n\n25\n00:01:20.940 --> 00:01:22.270\n트랙 너비와 휠베이스에 대한\n\n26\n00:01:22.270 --> 00:01:25.370\n설정이 표시됩니다.\n\n27\n00:01:25.370 --> 00:01:27.880\n트랙 너비는 드라이브트레인의 너비입니다.\n\n28\n00:01:27.880 --> 00:01:29.480\n드라이브트레인의 너비를 측정하고\n\n29\n00:01:29.480 --> 00:01:30.943\n이 설정을 업데이트하세요.\n\n30\n00:01:33.200 --> 00:01:36.390\n휠베이스는 앞 휠과 뒤 휠의\n\n31\n00:01:36.390 --> 00:01:38.360\n각각 중심 사이의 거리를 말합니다.\n\n32\n00:01:38.360 --> 00:01:40.450\n두 휠 사이의 거리를 측정하고\n\n33\n00:01:40.450 --> 00:01:42.043\n이 설정을 업데이트하세요.\n\n34\n00:01:43.310 --> 00:01:46.330\n다음은 V5 스마트 모터에 설치된\n\n35\n00:01:46.330 --> 00:01:48.253\n기어 카트리지를 선택합니다.\n\n36\n00:01:50.730 --> 00:01:53.680\n마지막으로, 전진하도록 프로그래밍된 드라이브트레인이\n\n37\n00:01:53.680 --> 00:01:55.520\n후진으로 주행하는 경우,\n\n38\n00:01:55.520 --> 00:01:58.220\n방향 화살표를 변경하여 드라이브트레인을 진로 방향을 복구시키세요.\n\n39\n00:01:59.850 --> 00:02:01.170\n완료 버튼을 선택하면\n\n40\n00:02:03.180 --> 00:02:06.343\n드라이브트레인 블록이 도구 상자에 나타납니다.\n\n41\n00:02:07.180 --> 00:02:10.173\n이제 드라이브트레인은 구성이 완료되고 사용할 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Pavaros mechanizmai leidžia Jūsų \"V5\" robotui</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nvažiuoti ir pasukti tikslius atstumus, naudojant vieną bloką.\n\n3\n00:00:06.460 --> 00:00:08.370\nPrietaisų lange\n\n4\n00:00:08.370 --> 00:00:10.370\nprie savo projekto pridėkite pavaros mechanizmą.\n\n5\n00:00:10.370 --> 00:00:11.880\nAtidarykite prietaisų langą\n\n6\n00:00:14.350 --> 00:00:16.363\nir pasirinkite pridėti prietaisą.\n\n7\n00:00:17.460 --> 00:00:19.707\nPo to, pasirinkite pavaros mechanizmą.\n\n8\n00:00:22.120 --> 00:00:24.491\nPirmiausia, pasirinkite kairės\n\n9\n00:00:24.491 --> 00:00:28.600\nir dešinės pavaros mechanizmo išmaniųjų \"V5\" variklių prievadus.\n\n10\n00:00:28.600 --> 00:00:32.341\nPažymėkite, jei Jūsų pavaros mechanizmas turi giro jutiklį.\n\n11\n00:00:32.341 --> 00:00:34.960\nJeigu Jūsų pavaros mechanizmas neturi vidinio jutiklio,\n\n12\n00:00:34.960 --> 00:00:37.850\npasirinkite inercinio jutiklio parinktį\n\n13\n00:00:37.850 --> 00:00:40.713\nir išmanųjį prievadą, prie kurio yra prijungtas inercinis jutiklis.\n\n14\n00:00:43.180 --> 00:00:45.950\nJeigu Jūsų pavaros mechanizmas turi trijų laidų giroskopą,\n\n15\n00:00:45.950 --> 00:00:48.380\npasirinkite trijų laidų giroskopo parinktį\n\n16\n00:00:49.740 --> 00:00:52.603\nir prievadą, prie kurio prijungtas trijų laidų giroskopas.\n\n17\n00:00:54.750 --> 00:00:57.820\nJeigu Jūsų pavaros mechanizmas neturi trijų laidų giroskopo,\n\n18\n00:00:57.820 --> 00:01:00.053\npasirinkite parinktį \"Nėra giroskopo\".\n\n19\n00:01:01.430 --> 00:01:04.160\nSukonfigūruokime pavaros mechanizmą.\n\n20\n00:01:04.160 --> 00:01:06.520\nPirmiausia, pažvelkite į savo pavaros mechanizmo ratus\n\n21\n00:01:06.520 --> 00:01:09.413\nir išplėstiniame sąraše pasirinkite ratų dydį.\n\n22\n00:01:12.860 --> 00:01:16.030\nPo to, pasižiūrėkite į pavaras ir pavaros mechanizmą\n\n23\n00:01:16.030 --> 00:01:18.940\nir įveskite įvestinį ir išvestinį pavarų santykį.\n\n24\n00:01:18.940 --> 00:01:20.940\nJeigu neturite girojutiklio,\n\n25\n00:01:20.940 --> 00:01:22.270\nmatysite du nustatymus\n\n26\n00:01:22.270 --> 00:01:25.370\ntarpvežės pločiui ir ratų bazei.\n\n27\n00:01:25.370 --> 00:01:27.880\nTarpvėžės plotis yra pavaros mechanizmo plotis.\n\n28\n00:01:27.880 --> 00:01:29.480\nIšmatuokite savo pavaros mechanizmo plotį\n\n29\n00:01:29.480 --> 00:01:30.943\nir atnaujinkite šiuos nustatymus.\n\n30\n00:01:33.200 --> 00:01:36.390\nRatų bazė yra atstumas tarp priekinių ir galinių ratų\n\n31\n00:01:36.390 --> 00:01:38.360\ncentro.\n\n32\n00:01:38.360 --> 00:01:40.450\nIšmatuokite atstumą tarp dviejų ratų\n\n33\n00:01:40.450 --> 00:01:42.043\nir atnaujinkite šiuos nustatymus.\n\n34\n00:01:43.310 --> 00:01:46.330\nPo to, pasirinkite kokia pavarų kasetė sumontuota\n\n35\n00:01:46.330 --> 00:01:48.253\nJūsų išmaniuosiuose \"V5\" varikliuose.\n\n36\n00:01:50.730 --> 00:01:53.680\nGaliausiai, jeigu Jūsų pavaros mechanizmas važiuoja atbulai,\n\n37\n00:01:53.680 --> 00:01:55.520\nkai yra užprogramuotas važiuoti į priekį,\n\n38\n00:01:55.520 --> 00:01:58.220\npakeiskite krypties rodyklę, kad pavaros mechanizmas važiuotų atbulai.\n\n39\n00:01:59.850 --> 00:02:01.170\nSpustelėkite mygtuką \"Atlikti\"\n\n40\n00:02:03.180 --> 00:02:06.343\nir parankinėje atsiras pavaros mechanizmo blokai.\n\n41\n00:02:07.180 --> 00:02:10.173\nJūsų pavaros mechanizmas yra sukonfigūruotas ir parengtas naudoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Piedziņas sistēmas nodrošina V5 robota</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nkustību un precīzu griešanos ar vienu bloku.\n\n3\n00:00:06.460 --> 00:00:08.370\nJūs variet pievienot piedziņas sistēmu savam projektam,\n\n4\n00:00:08.370 --> 00:00:10.370\nizmantojot ierīču logu.\n\n5\n00:00:10.370 --> 00:00:11.880\nAtveriet ierīču logu\n\n6\n00:00:14.350 --> 00:00:16.363\nun atlasiet “Add a device” (pievienot ierīci).\n\n7\n00:00:17.460 --> 00:00:19.707\nPēc tam atlasiet “Drivetrain” (piedziņa).\n\n8\n00:00:22.120 --> 00:00:24.491\nVispirms atlasiet portus kreisajiem\n\n9\n00:00:24.491 --> 00:00:28.600\nun labajiem V5 viedajiem motoriem piedziņas sistēmā.\n\n10\n00:00:28.600 --> 00:00:32.341\nPēc tam izvēlieties, vai piedziņas sistēmai ir žiroskops.\n\n11\n00:00:32.341 --> 00:00:34.960\nJa jūsu piedziņas sistēmai ir inerces sensors,\n\n12\n00:00:34.960 --> 00:00:37.850\nizvēlieties inerces sensora opciju\n\n13\n00:00:37.850 --> 00:00:40.713\nun viedo portu, pie kura ir pieslēgts inerces sensors.\n\n14\n00:00:43.180 --> 00:00:45.950\nJa jūsu piedziņas sistēmai ir trīs vadu savienojuma žiroskops,\n\n15\n00:00:45.950 --> 00:00:48.380\nizvēlieties trīs vadu savienojuma žiroskopa opciju\n\n16\n00:00:49.740 --> 00:00:52.603\nun portu, pie kura ir savienots trīs vadu savienojuma žiroskops.\n\n17\n00:00:54.750 --> 00:00:57.820\nJa jūsu piedziņas sistēmai nav trīs vadu savienojuma žiroskops,\n\n18\n00:00:57.820 --> 00:01:00.053\natlasiet opciju “No Gyro” (nav žiriskopa).\n\n19\n00:01:01.430 --> 00:01:04.160\nTagad konfigurēsim piedziņas sistēmu.\n\n20\n00:01:04.160 --> 00:01:06.520\nVispirms skatiet piedziņas sistēmas riteņus\n\n21\n00:01:06.520 --> 00:01:09.413\nun nolaižamajā sarakstā, atlasiet riteņu izmēru.\n\n22\n00:01:12.860 --> 00:01:16.030\nPēc tam aplūkojiet piedziņas sistēmas pārnesumus\n\n23\n00:01:16.030 --> 00:01:18.940\nun ievadiet ieejas un izejas pārnesuma attiecību.\n\n24\n00:01:18.940 --> 00:01:20.940\nJa jums nav žiroskopa sensora,\n\n25\n00:01:20.940 --> 00:01:22.270\ntiks parādīti divi iestatījumi\n\n26\n00:01:22.270 --> 00:01:25.370\nceļa platumam un riteņu bāzei.\n\n27\n00:01:25.370 --> 00:01:27.880\nCeļa platums atbilst piedziņas sistēmas platumam.\n\n28\n00:01:27.880 --> 00:01:29.480\nIzmēriet jūsu piedziņas sistēmas platumu\n\n29\n00:01:29.480 --> 00:01:30.943\nun atjauniniet šo iestatījumu.\n\n30\n00:01:33.200 --> 00:01:36.390\nRiteņu bāze ir attālums starp priekšējā un aizmugurējā\n\n31\n00:01:36.390 --> 00:01:38.360\nriteņa centra daļu.\n\n32\n00:01:38.360 --> 00:01:40.450\nIzmēriet attālumu starp abiem riteņiem\n\n33\n00:01:40.450 --> 00:01:42.043\nun atjauniniet šo iestatījumu.\n\n34\n00:01:43.310 --> 00:01:46.330\nIzvēlieties, kurš pārnesuma bloks ir uzstādīts\n\n35\n00:01:46.330 --> 00:01:48.253\njūsu V5 viedajā motorā.\n\n36\n00:01:50.730 --> 00:01:53.680\nJa jūsu piedziņas sistēma veic kustību atpakaļgaitā,\n\n37\n00:01:53.680 --> 00:01:55.520\nkad tā ir programmēta, lai virzītos uz priekšu,\n\n38\n00:01:55.520 --> 00:01:58.220\nmainiet piedziņas sistēmas bultiņu pretējā virzienā.\n\n39\n00:01:59.850 --> 00:02:01.170\nAtlasiet pogu “Done” (gatavs),\n\n40\n00:02:03.180 --> 00:02:06.343\nun rīklodziņā parādīsies piedziņas sistēmas bloki.\n\n41\n00:02:07.180 --> 00:02:10.173\nJūsu piedziņas sistēma tagad ir konfigurēta un gatava lietošanai.\n\n","nl":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Met aandrijflijnen kan uw V5-robot </v>\n\n2\n00:00:02.480 --> 00:00:06.460\nmet een enkel blok nauwkeurige afstanden rijden en draaien.\n\n3\n00:00:06.460 --> 00:00:08.370\nU kunt een aandrijflijn aan uw project toevoegen\n\n4\n00:00:08.370 --> 00:00:10.370\nmet het venster van apparaten.\n\n5\n00:00:10.370 --> 00:00:11.880\nOpen het venster van apparaten\n\n6\n00:00:14.350 --> 00:00:16.363\nselecteer Voeg een apparaat toe.\n\n7\n00:00:17.460 --> 00:00:19.707\nVervolgens selecteer Aandrijflijn.\n\n8\n00:00:22.120 --> 00:00:24.491\nSelecteer eerst de poorten voor uw linker\n\n9\n00:00:24.491 --> 00:00:28.600\nen rechter V5 slimme motoren in uw aandrijflijn.\n\n10\n00:00:28.600 --> 00:00:32.341\nSelecteer nu of de aandrijflijn een gyrosensor heeft.\n\n11\n00:00:32.341 --> 00:00:34.960\nAls uw aandrijflijn een traagheidssensor heeft,\n\n12\n00:00:34.960 --> 00:00:37.850\nselecteer de inertiële sensor optie\n\n13\n00:00:37.850 --> 00:00:40.713\nen de slimme poort waarop de inertiële sensor is aangesloten.\n\n14\n00:00:43.180 --> 00:00:45.950\nAls uw aandrijflijn een driedraads gyro heeft,\n\n15\n00:00:45.950 --> 00:00:48.380\nselecteert u de optie driedraads gyro\n\n16\n00:00:49.740 --> 00:00:52.603\nen de poort waarop de driedraads gyro is aangesloten.\n\n17\n00:00:54.750 --> 00:00:57.820\nAls uw aandrijflijn geen driedraads gyro heeft,\n\n18\n00:00:57.820 --> 00:01:00.053\nselecteert u de optie Geen gyro.\n\n19\n00:01:01.430 --> 00:01:04.160\nLaten we nu de aandrijflijn configureren.\n\n20\n00:01:04.160 --> 00:01:06.520\nKijk eerst naar de wielen van uw aandrijflijn\n\n21\n00:01:06.520 --> 00:01:09.413\nen selecteer de wielmaat in de vervolgkeuzelijst.\n\n22\n00:01:12.860 --> 00:01:16.030\nBekijk vervolgens de versnellingen en de aandrijflijn\n\n23\n00:01:16.030 --> 00:01:18.940\nen voer de in- en uitgaande overbrengingsverhouding in.\n\n24\n00:01:18.940 --> 00:01:20.940\nAls u geen gyro sensor had,\n\n25\n00:01:20.940 --> 00:01:22.270\nzie je twee instellingen\n\n26\n00:01:22.270 --> 00:01:25.370\nvoor de track breedte en wielbasis.\n\n27\n00:01:25.370 --> 00:01:27.880\nTrack breedte is de breedte van de aandrijflijn.\n\n28\n00:01:27.880 --> 00:01:29.480\nMeet de breedte van uw aandrijflijn\n\n29\n00:01:29.480 --> 00:01:30.943\nen werk deze instelling bij.\n\n30\n00:01:33.200 --> 00:01:36.390\nWielbasis is de afstand tussen het midden van de voorkant\n\n31\n00:01:36.390 --> 00:01:38.360\nen achter wielen.\n\n32\n00:01:38.360 --> 00:01:40.450\nMeet de afstand tussen de twee wielen\n\n33\n00:01:40.450 --> 00:01:42.043\nen werk deze instelling bij.\n\n34\n00:01:43.310 --> 00:01:46.330\nVervolgens selecteer welke tandwielcartridge is geïnstalleerd\n\n35\n00:01:46.330 --> 00:01:48.253\nin uw V5 slimme motoren.\n\n36\n00:01:50.730 --> 00:01:53.680\nTot slot, als je aandrijflijn achterwaarts rijdt,\n\n37\n00:01:53.680 --> 00:01:55.520\nverander dan de richtingpijl om je aandrijflijn,\n\n38\n00:01:55.520 --> 00:01:58.220\nom te keren als hij geprogrammeerd is om voorwaarts te rijden.\n\n39\n00:01:59.850 --> 00:02:01.170\nSelecteert u de knop Gereed\n\n40\n00:02:03.180 --> 00:02:06.343\nen de aandrijflijnblokken zullen nu in de werkbalk verschijnen.\n\n41\n00:02:07.180 --> 00:02:10.173\nUw aandrijflijn is nu geconfigureerd en klaar voor gebruik.\n\n","pl":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Silniki pozwalają Twojemu robotowi V5</v>\n\n2\n00:00:02.480 --> 00:00:06.460\njeździć i pokonywać dokładną odległość za pomocą pojedynczego bloku.\n\n3\n00:00:06.460 --> 00:00:08.370\nMożesz dodać układ napędowy do swojego projektu\n\n4\n00:00:08.370 --> 00:00:10.370\nz oknem urządzenia.\n\n5\n00:00:10.370 --> 00:00:11.880\nOtwórz okno urządzenia\n\n6\n00:00:14.350 --> 00:00:16.363\ni wybierz Dodaj urządzenie.\n\n7\n00:00:17.460 --> 00:00:19.707\nNastępnie, wybierz Napęd.\n\n8\n00:00:22.120 --> 00:00:24.491\nNajpierw wybierz porty po lewej stronie\n\n9\n00:00:24.491 --> 00:00:28.600\ni prawe silniki V5 Twojego napędu.\n\n10\n00:00:28.600 --> 00:00:32.341\nNastępnie zaznacz czy Twój układ posiada żyroskop.\n\n11\n00:00:32.341 --> 00:00:34.960\nJeśli posiada on żyroskop,\n\n12\n00:00:34.960 --> 00:00:37.850\nwybierz opcję czujnika bezwładności\n\n13\n00:00:37.850 --> 00:00:40.713\noraz inteligentny port, do którego jest podłączony.\n\n14\n00:00:43.180 --> 00:00:45.950\nJeśli posiada on żyroskop 3-przewodowy,\n\n15\n00:00:45.950 --> 00:00:48.380\nwybierz opcję 3-przewodowego żyroskopu\n\n16\n00:00:49.740 --> 00:00:52.603\ni port do którego jest podłączony.\n\n17\n00:00:54.750 --> 00:00:57.820\nJeśli nie posiada on żyroskopu 3-przewodowego,\n\n18\n00:00:57.820 --> 00:01:00.053\nwybierz opcję bez Żyroskopu.\n\n19\n00:01:01.430 --> 00:01:04.160\nTeraz, skonfigurujmy napęd.\n\n20\n00:01:04.160 --> 00:01:06.520\nNajpierw spójrz na koła napędu\n\n21\n00:01:06.520 --> 00:01:09.413\ni wybierz rozmiar koła z listy rozwijanej.\n\n22\n00:01:12.860 --> 00:01:16.030\nNastępnie zajrzyj na biegi w układzie napędowym\n\n23\n00:01:16.030 --> 00:01:18.940\ni wprowadzić przełożenie wejściowe i wyjściowe.\n\n24\n00:01:18.940 --> 00:01:20.940\nJeśli nie masz czujnika żyroskopowego,\n\n25\n00:01:20.940 --> 00:01:22.270\nzobaczysz dwa ustawienia\n\n26\n00:01:22.270 --> 00:01:25.370\ndla szerokości toru i rozstawu kół.\n\n27\n00:01:25.370 --> 00:01:27.880\nSzerokość toru to szerokość układu silników.\n\n28\n00:01:27.880 --> 00:01:29.480\nZmierz szerokość swojego napędu\n\n29\n00:01:29.480 --> 00:01:30.943\ni uaktualnij to ustawienie.\n\n30\n00:01:33.200 --> 00:01:36.390\nRozstaw kół to odległość między środkiem przodnich\n\n31\n00:01:36.390 --> 00:01:38.360\ni kół tylnych.\n\n32\n00:01:38.360 --> 00:01:40.450\nZmierz odległość między kołami\n\n33\n00:01:40.450 --> 00:01:42.043\ni uaktualnij to ustawienie.\n\n34\n00:01:43.310 --> 00:01:46.330\nZaznacz, która zębatka została zainstalowana\n\n35\n00:01:46.330 --> 00:01:48.253\nw silniku V5.\n\n36\n00:01:50.730 --> 00:01:53.680\nNa koniec, jeśli Twój układ napędowy jedzie wstecz,\n\n37\n00:01:53.680 --> 00:01:55.520\nkiedy zaprogramowano go do jazdy do przodu,\n\n38\n00:01:55.520 --> 00:01:58.220\nzmień strzałkę kierunku na do tyłu.\n\n39\n00:01:59.850 --> 00:02:01.170\nWybierz przycisk Gotowe\n\n40\n00:02:03.180 --> 00:02:06.343\na dodatkowe bloki pojawią się teraz w przyborniku.\n\n41\n00:02:07.180 --> 00:02:10.173\nTwój napęd jest teraz skonfigurowany i gotowy do użycia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Трансмиссия позволяет роботу</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nповорачивать и двигаться на определённое расстояние с помощью одного блока.\n\n3\n00:00:06.460 --> 00:00:08.370\nВы можете добавить трансмиссию к проекту\n\n4\n00:00:08.370 --> 00:00:10.370\nс помощью окна добавления устройств.\n\n5\n00:00:10.370 --> 00:00:11.880\nОткройте окно настройки\n\n6\n00:00:14.350 --> 00:00:16.363\nи выберите \"Добавить\" устройство.\n\n7\n00:00:17.460 --> 00:00:19.707\nДалее, выберите трансмиссию.\n\n8\n00:00:22.120 --> 00:00:24.491\nПервым делом, определите порты левого\n\n9\n00:00:24.491 --> 00:00:28.600\nи правого приводов трансмиссии.\n\n10\n00:00:28.600 --> 00:00:32.341\nДалее, определите наличие или отсутствие гироскопа.\n\n11\n00:00:32.341 --> 00:00:34.960\nЕсли трансмиссия обладает инерционным датчиком,\n\n12\n00:00:34.960 --> 00:00:37.850\nвыберите инерционный датчик\n\n13\n00:00:37.850 --> 00:00:40.713\nи порт его подключения.\n\n14\n00:00:43.180 --> 00:00:45.950\nЕсли на трансмиссию установлен трёхпроводной гироскоп,\n\n15\n00:00:45.950 --> 00:00:48.380\nто выберите трёхпроводной гироскоп\n\n16\n00:00:49.740 --> 00:00:52.603\nи порт его подключения.\n\n17\n00:00:54.750 --> 00:00:57.820\nЕсли гироскоп не подключён к трансмиссии,\n\n18\n00:00:57.820 --> 00:01:00.053\nто поставьте галочку в соответствующем поле.\n\n19\n00:01:01.430 --> 00:01:04.160\nИтак, приступим к настройке трансмиссии.\n\n20\n00:01:04.160 --> 00:01:06.520\nДля начала, обратите внимание на оси трансмиссии\n\n21\n00:01:06.520 --> 00:01:09.413\nи выберите размер колёс из списка.\n\n22\n00:01:12.860 --> 00:01:16.030\nДалее, обратите внимание на шестерни трансмиссии\n\n23\n00:01:16.030 --> 00:01:18.940\nи введите входное и выходное передаточные числа.\n\n24\n00:01:18.940 --> 00:01:20.940\nЕсли у вас нет гироскопа,\n\n25\n00:01:20.940 --> 00:01:22.270\nвы увидите две опции\n\n26\n00:01:22.270 --> 00:01:25.370\nдля ширины колеи и колёсной основы.\n\n27\n00:01:25.370 --> 00:01:27.880\nШирина колеи - ширина трансмиссии.\n\n28\n00:01:27.880 --> 00:01:29.480\nИзмерьте ширину трансмиссии\n\n29\n00:01:29.480 --> 00:01:30.943\nи обновите настройки.\n\n30\n00:01:33.200 --> 00:01:36.390\nШирина колёсной основы - это расстояние между центрами передних\n\n31\n00:01:36.390 --> 00:01:38.360\nи задних колёс.\n\n32\n00:01:38.360 --> 00:01:40.450\nИзмерьте ширину колёсной базы\n\n33\n00:01:40.450 --> 00:01:42.043\nи обновите настройки.\n\n34\n00:01:43.310 --> 00:01:46.330\nЗатем необходимо выбрать тип установленного картриджа\n\n35\n00:01:46.330 --> 00:01:48.253\nна приводах.\n\n36\n00:01:50.730 --> 00:01:53.680\nНаконец, если трансмиссия движется в обратном направлении,\n\n37\n00:01:53.680 --> 00:01:55.520\nпри программировании движения вперёд,\n\n38\n00:01:55.520 --> 00:01:58.220\nвыберите соответствующую стрелку для изменения направления движения.\n\n39\n00:01:59.850 --> 00:02:01.170\nНажмите кнопку \"Готово\"\n\n40\n00:02:03.180 --> 00:02:06.343\nи блоки управления трансмиссией появятся в инструментарии.\n\n41\n00:02:07.180 --> 00:02:10.173\nТрансмиссия настроена и готова к работе.\n\n","th":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v -> ระบบขับเคลื่อน Drivetrains ช่วยให้หุ่นยนต์ V5 ของคุณ </v>\n\n2\n00:00:02.480 --> 00:00:06.460\nสามารถขับเคลื่อนและเลี้ยวระยะทางที่แม่นยำได้ด้วยการใช้บล็อกเดียว\n\n3\n00:00:06.460 --> 00:00:08.370\nคุณสามารถเพิ่มระบบขับเคลื่อนลงไปในโปรเจ็คของคุณ\n\n4\n00:00:08.370 --> 00:00:10.370\nในหน้าต่างอุปกรณ์\n\n5\n00:00:10.370 --> 00:00:11.880\nเปิดหน้าต่างอุปกรณ์\n\n6\n00:00:14.350 --> 00:00:16.363\nแล้วเลือกเพิ่มอุปกรณ์ Add a device\n\n7\n00:00:17.460 --> 00:00:19.707\nจากนั้นเลือก Drivetrain\n\n8\n00:00:22.120 --> 00:00:24.491\nขั้นแรกเลือกพอร์ตทางซ้ายและข้างขวา\n\n9\n00:00:24.491 --> 00:00:28.600\nของมอเตอร์อัจฉริยะ V5 ที่เหมาะสมในระบบขับเคลื่อนของคุณ\n\n10\n00:00:28.600 --> 00:00:32.341\nจากนั้นเลือกว่ารางขับเคลื่อนของคุณมีเซ็นเซอร์ไจโรหรือไม่\n\n11\n00:00:32.341 --> 00:00:34.960\nหากระบบขับเคลื่อนของคุณมีเซ็นเซอร์เฉื่อย\n\n12\n00:00:34.960 --> 00:00:37.850\nเลือกตัวเลือกเซ็นเซอร์เฉื่อย\n\n13\n00:00:37.850 --> 00:00:40.713\nและพอร์ตอัจฉริยะที่เซ็นเซอร์เฉื่อยต่ออยู่\n\n14\n00:00:43.180 --> 00:00:45.950\nหากระบบขับเคลื่อนของคุณมีไจโรสามสาย\n\n15\n00:00:45.950 --> 00:00:48.380\nเลือกตัวเลือกไจโรสามสาย\n\n16\n00:00:49.740 --> 00:00:52.603\nและพอร์ตที่ไจโรสามสายเชื่อมต่ออยู่\n\n17\n00:00:54.750 --> 00:00:57.820\nหากระบบขับเคลื่อนของคุณไม่มีไจโรสามสาย\n\n18\n00:00:57.820 --> 00:01:00.053\nเลือกตัวเลือก No Gyro\n\n19\n00:01:01.430 --> 00:01:04.160\nตอนนี้สามารถกำหนดค่าระบบขับเคลื่อน\n\n20\n00:01:04.160 --> 00:01:06.520\nขั้นแรกให้ดูที่ล้อบนระบบขับเคลื่อนของคุณ\n\n21\n00:01:06.520 --> 00:01:09.413\nและเลือกขนาดล้อจากเมนูแบบเลื่อนลง\n\n22\n00:01:12.860 --> 00:01:16.030\nจากนั้นดูที่เกียร์และระบบขับเคลื่อน\n\n23\n00:01:16.030 --> 00:01:18.940\nและป้อนค่า input และ output ของอัตราทดเกียร์ gear ratio\n\n24\n00:01:18.940 --> 00:01:20.940\nหากคุณไม่มีเซ็นเซอร์ไจโร\n\n25\n00:01:20.940 --> 00:01:22.270\nคุณจะเห็นการตั้งค่าสองแบบ\n\n26\n00:01:22.270 --> 00:01:25.370\nfor the track width and wheel base.\n\n27\n00:01:25.370 --> 00:01:27.880\nความกว้างแทร็กคือความกว้างของระบบขับเคลื่อน\n\n28\n00:01:27.880 --> 00:01:29.480\nวัดความกว้างของระบบขับเคลื่อนของคุณ\n\n29\n00:01:29.480 --> 00:01:30.943\nและอัปเดตการตั้งค่านี้\n\n30\n00:01:33.200 --> 00:01:36.390\nฐานล้อคือระยะห่างระหว่างจุดศูนย์กลางของด้านหน้า\n\n31\n00:01:36.390 --> 00:01:38.360\nและด้านหลังของล้อ\n\n32\n00:01:38.360 --> 00:01:40.450\nวัดระยะห่างระหว่างสองล้อ\n\n33\n00:01:40.450 --> 00:01:42.043\nและอัปเดตการตั้งค่านี้\n\n34\n00:01:43.310 --> 00:01:46.330\nจากนั้นเลือกตลับเกียร์ที่ติดตั้งไว้\n\n35\n00:01:46.330 --> 00:01:48.253\nในมอเตอร์อัจฉริยะ V5 ของคุณ\n\n36\n00:01:50.730 --> 00:01:53.680\nสุดท้ายนี้หากระบบขับเคลื่อนของคุณขับถอยหลัง\n\n37\n00:01:53.680 --> 00:01:55.520\nเมื่อถูกตั้งโปรแกรมให้ขับเคลื่อนไปข้างหน้า\n\n38\n00:01:55.520 --> 00:01:58.220\nให้เปลี่ยนลูกศรทิศทางเพื่อย้อนกลับระบบขับเคลื่อนของคุณ\n\n39\n00:01:59.850 --> 00:02:01.170\nจากนั้นเลือกปุ่ม Done\n\n40\n00:02:03.180 --> 00:02:06.343\nและบล็อกระบบขับเคลื่อนจะปรากฏในกล่องเครื่องมือ\n\n41\n00:02:07.180 --> 00:02:10.173\nตอนนี้ระบบขับเคลื่อนของคุณได้รับการตั้งค่าและพร้อมใช้งานแล้ว\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Трансмісія дає змогу роботу V5</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nпроїжджати і повертати на точну відстань лише з одним блоком.\n\n3\n00:00:06.460 --> 00:00:08.370\nВи можете додати трансмісію до проєкту\n\n4\n00:00:08.370 --> 00:00:10.370\nчерез вікно пристроїв.\n\n5\n00:00:10.370 --> 00:00:11.880\nВідкрийте вікно пристроїв\n\n6\n00:00:14.350 --> 00:00:16.363\nі натисніть \"Додати пристрій\".\n\n7\n00:00:17.460 --> 00:00:19.707\nДалі, виберіть \"Трансмісія\".\n\n8\n00:00:22.120 --> 00:00:24.491\nСпочатку, виберіть порти для лівого\n\n9\n00:00:24.491 --> 00:00:28.600\nта правого моторів трансмісії.\n\n10\n00:00:28.600 --> 00:00:32.341\nПотім виберіть порти гіроскопа.\n\n11\n00:00:32.341 --> 00:00:34.960\nЯкщо ваша трансмісія має інерційний датчик,\n\n12\n00:00:34.960 --> 00:00:37.850\nвиберіть інерційний датчик\n\n13\n00:00:37.850 --> 00:00:40.713\nі розумний порт, до якого під'єднано датчик.\n\n14\n00:00:43.180 --> 00:00:45.950\nЯкщо ваша трансмісія має тридротовий гіроскоп,\n\n15\n00:00:45.950 --> 00:00:48.380\nвиберіть тридротовий гіроскоп\n\n16\n00:00:49.740 --> 00:00:52.603\nі порт, до якого під'єднано тридротовий гіроскоп.\n\n17\n00:00:54.750 --> 00:00:57.820\nЯкщо ваша трансмісія не має тридротового гіроскопа,\n\n18\n00:00:57.820 --> 00:01:00.053\nвиберіть \"Немає гіроскопа\".\n\n19\n00:01:01.430 --> 00:01:04.160\nТепер налаштуймо трансмісію.\n\n20\n00:01:04.160 --> 00:01:06.520\nДля початку, подивіться на колеса вашої трансмісії\n\n21\n00:01:06.520 --> 00:01:09.413\nі виберіть розмір коліс у спадному меню.\n\n22\n00:01:12.860 --> 00:01:16.030\nДалі, погляньте на зубчату передачу трансмісії\n\n23\n00:01:16.030 --> 00:01:18.940\nі введіть вхідне та вихідне число передатного відношення.\n\n24\n00:01:18.940 --> 00:01:20.940\nЯкщо ви не маєте гіроскопа,\n\n25\n00:01:20.940 --> 00:01:22.270\nви побачите два налаштування\n\n26\n00:01:22.270 --> 00:01:25.370\nдля ширини колії і колісної бази.\n\n27\n00:01:25.370 --> 00:01:27.880\nШирина колії - це ширина трансмісії.\n\n28\n00:01:27.880 --> 00:01:29.480\nВиміряйте ширину вашої трансмісії\n\n29\n00:01:29.480 --> 00:01:30.943\nі введіть ці дані.\n\n30\n00:01:33.200 --> 00:01:36.390\nКолісна база - це відстань між центром передніх\n\n31\n00:01:36.390 --> 00:01:38.360\nі задніх коліс.\n\n32\n00:01:38.360 --> 00:01:40.450\nВиміряйте відстань між двома колесами\n\n33\n00:01:40.450 --> 00:01:42.043\nі введіть ці дані.\n\n34\n00:01:43.310 --> 00:01:46.330\nДалі, виберіть, який редукторний картридж встановлено\n\n35\n00:01:46.330 --> 00:01:48.253\nу ваш мотор V5.\n\n36\n00:01:50.730 --> 00:01:53.680\nНаостанок, якщо ваша трансмісія перевернута,\n\n37\n00:01:53.680 --> 00:01:55.520\nто для програмування руху вперед\n\n38\n00:01:55.520 --> 00:01:58.220\nзмініть стрілку напряму для зворотного напряму руху шасі.\n\n39\n00:01:59.850 --> 00:02:01.170\nНатисніть \"Готово\"\n\n40\n00:02:03.180 --> 00:02:06.343\nі блоки трансмісії з'являться в наборі блоків.\n\n41\n00:02:07.180 --> 00:02:10.173\nВаша трансмісія налаштована і готова до використання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->Hệ thống truyền lực cho phép rô bốt V5 của bạn</v>\n\n2\n00:00:02.480 --> 00:00:06.460\nđể lái xe và rẽ những khoảng cách chính xác chỉ với một khối duy nhất.\n\n3\n00:00:06.460 --> 00:00:08.370\nBạn có thể thêm hệ thống truyền lực vào dự án của mình\n\n4\n00:00:08.370 --> 00:00:10.370\nvới cửa sổ thiết bị.\n\n5\n00:00:10.370 --> 00:00:11.880\nMở cửa sổ thiết bị\n\n6\n00:00:14.350 --> 00:00:16.363\nvà chọn Thêm thiết bị.\n\n7\n00:00:17.460 --> 00:00:19.707\nTiếp theo, chọn Hệ thống truyền lực.\n\n8\n00:00:22.120 --> 00:00:24.491\nĐầu tiên, chọn các cổng cho bên trái của bạn\n\n9\n00:00:24.491 --> 00:00:28.600\nvà động cơ thông minh V5 phù hợp trong hệ thống truyền động của bạn.\n\n10\n00:00:28.600 --> 00:00:32.341\nTiếp theo, chọn xem xe lửa của bạn có cảm biến con quay hồi chuyển hay không.\n\n11\n00:00:32.341 --> 00:00:34.960\nNếu hệ thống truyền động của bạn có cảm biến quán tính,\n\n12\n00:00:34.960 --> 00:00:37.850\nchọn tùy chọn cảm biến quán tính\n\n13\n00:00:37.850 --> 00:00:40.713\nvà cổng thông minh mà quán tính được kết nối.\n\n14\n00:00:43.180 --> 00:00:45.950\nNếu hệ thống truyền động của bạn có một con quay hồi chuyển ba dây,\n\n15\n00:00:45.950 --> 00:00:48.380\nchọn tùy chọn con quay hồi chuyển ba dây\n\n16\n00:00:49.740 --> 00:00:52.603\nvà cổng mà con quay hồi chuyển ba dây được kết nối với.\n\n17\n00:00:54.750 --> 00:00:57.820\nNếu hệ thống truyền lực của bạn không có con quay hồi chuyển ba dây,\n\n18\n00:00:57.820 --> 00:01:00.053\nchọn tùy chọn No Gyro.\n\n19\n00:01:01.430 --> 00:01:04.160\nBây giờ, hãy cấu hình hệ thống truyền lực.\n\n20\n00:01:04.160 --> 00:01:06.520\nĐầu tiên, hãy nhìn vào các bánh xe trên hệ thống truyền động của bạn\n\n21\n00:01:06.520 --> 00:01:09.413\nvà chọn kích thước bánh xe từ menu thả xuống.\n\n22\n00:01:12.860 --> 00:01:16.030\nTiếp theo, hãy xem các bánh răng và hệ thống truyền lực\n\n23\n00:01:16.030 --> 00:01:18.940\nvà nhập tỷ số truyền đầu vào và đầu ra.\n\n24\n00:01:18.940 --> 00:01:20.940\nNếu bạn không có cảm biến con quay hồi chuyển,\n\n25\n00:01:20.940 --> 00:01:22.270\nbạn sẽ thấy hai cài đặt\n\n26\n00:01:22.270 --> 00:01:25.370\ncho chiều rộng rãnh và đế bánh xe.\n\n27\n00:01:25.370 --> 00:01:27.880\nChiều rộng đường ray là chiều rộng của hệ thống truyền lực.\n\n28\n00:01:27.880 --> 00:01:29.480\nĐo chiều rộng của hệ thống truyền lực của bạn\n\n29\n00:01:29.480 --> 00:01:30.943\nvà cập nhật cài đặt này.\n\n30\n00:01:33.200 --> 00:01:36.390\nCơ sở bánh xe là khoảng cách giữa tâm của mặt trước\n\n31\n00:01:36.390 --> 00:01:38.360\nvà bánh sau.\n\n32\n00:01:38.360 --> 00:01:40.450\nĐo khoảng cách giữa hai bánh xe\n\n33\n00:01:40.450 --> 00:01:42.043\nvà cập nhật cài đặt này.\n\n34\n00:01:43.310 --> 00:01:46.330\nTiếp theo, chọn hộp bánh răng nào được lắp đặt\n\n35\n00:01:46.330 --> 00:01:48.253\ntrong động cơ thông minh V5 của bạn.\n\n36\n00:01:50.730 --> 00:01:53.680\nCuối cùng, nếu hệ thống truyền động của bạn dẫn động ngược lại,\n\n37\n00:01:53.680 --> 00:01:55.520\nkhi được lập trình để hướng về phía trước,\n\n38\n00:01:55.520 --> 00:01:58.220\nthay đổi mũi tên hướng để đảo ngược hệ thống truyền lực của bạn.\n\n39\n00:01:59.850 --> 00:02:01.170\nChọn nút Xong\n\n40\n00:02:03.180 --> 00:02:06.343\nvà các khối hệ thống truyền lực bây giờ sẽ xuất hiện trong hộp công cụ.\n\n41\n00:02:07.180 --> 00:02:10.173\nHệ thống truyền động của bạn hiện đã được định cấu hình và sẵn sàng sử dụng.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\ncrwdns95934:0crwdne95934:0\n\n2\n00:00:02.480 --> 00:00:06.460\ncrwdns95936:0crwdne95936:0\n\n3\n00:00:06.460 --> 00:00:08.370\ncrwdns95938:0crwdne95938:0\n\n4\n00:00:08.370 --> 00:00:10.370\ncrwdns95940:0crwdne95940:0\n\n5\n00:00:10.370 --> 00:00:11.880\ncrwdns95942:0crwdne95942:0\n\n6\n00:00:14.350 --> 00:00:16.363\ncrwdns95944:0crwdne95944:0\n\n7\n00:00:17.460 --> 00:00:19.707\ncrwdns95946:0crwdne95946:0\n\n8\n00:00:22.120 --> 00:00:24.491\ncrwdns95948:0crwdne95948:0\n\n9\n00:00:24.491 --> 00:00:28.600\ncrwdns95950:0crwdne95950:0\n\n10\n00:00:28.600 --> 00:00:32.341\ncrwdns95952:0crwdne95952:0\n\n11\n00:00:32.341 --> 00:00:34.960\ncrwdns95954:0crwdne95954:0\n\n12\n00:00:34.960 --> 00:00:37.850\ncrwdns95956:0crwdne95956:0\n\n13\n00:00:37.850 --> 00:00:40.713\ncrwdns95958:0crwdne95958:0\n\n14\n00:00:43.180 --> 00:00:45.950\ncrwdns95960:0crwdne95960:0\n\n15\n00:00:45.950 --> 00:00:48.380\ncrwdns95962:0crwdne95962:0\n\n16\n00:00:49.740 --> 00:00:52.603\ncrwdns95964:0crwdne95964:0\n\n17\n00:00:54.750 --> 00:00:57.820\ncrwdns95966:0crwdne95966:0\n\n18\n00:00:57.820 --> 00:01:00.053\ncrwdns95968:0crwdne95968:0\n\n19\n00:01:01.430 --> 00:01:04.160\ncrwdns95970:0crwdne95970:0\n\n20\n00:01:04.160 --> 00:01:06.520\ncrwdns95972:0crwdne95972:0\n\n21\n00:01:06.520 --> 00:01:09.413\ncrwdns95974:0crwdne95974:0\n\n22\n00:01:12.860 --> 00:01:16.030\ncrwdns95976:0crwdne95976:0\n\n23\n00:01:16.030 --> 00:01:18.940\ncrwdns95978:0crwdne95978:0\n\n24\n00:01:18.940 --> 00:01:20.940\ncrwdns95980:0crwdne95980:0\n\n25\n00:01:20.940 --> 00:01:22.270\ncrwdns95982:0crwdne95982:0\n\n26\n00:01:22.270 --> 00:01:25.370\ncrwdns95984:0crwdne95984:0\n\n27\n00:01:25.370 --> 00:01:27.880\ncrwdns95986:0crwdne95986:0\n\n28\n00:01:27.880 --> 00:01:29.480\ncrwdns95988:0crwdne95988:0\n\n29\n00:01:29.480 --> 00:01:30.943\ncrwdns95990:0crwdne95990:0\n\n30\n00:01:33.200 --> 00:01:36.390\ncrwdns95992:0crwdne95992:0\n\n31\n00:01:36.390 --> 00:01:38.360\ncrwdns95994:0crwdne95994:0\n\n32\n00:01:38.360 --> 00:01:40.450\ncrwdns95996:0crwdne95996:0\n\n33\n00:01:40.450 --> 00:01:42.043\ncrwdns95998:0crwdne95998:0\n\n34\n00:01:43.310 --> 00:01:46.330\ncrwdns96000:0crwdne96000:0\n\n35\n00:01:46.330 --> 00:01:48.253\ncrwdns96002:0crwdne96002:0\n\n36\n00:01:50.730 --> 00:01:53.680\ncrwdns96004:0crwdne96004:0\n\n37\n00:01:53.680 --> 00:01:55.520\ncrwdns96006:0crwdne96006:0\n\n38\n00:01:55.520 --> 00:01:58.220\ncrwdns96008:0crwdne96008:0\n\n39\n00:01:59.850 --> 00:02:01.170\ncrwdns96010:0crwdne96010:0\n\n40\n00:02:03.180 --> 00:02:06.343\ncrwdns96012:0crwdne96012:0\n\n41\n00:02:07.180 --> 00:02:10.173\ncrwdns96014:0crwdne96014:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.429 --> 00:00:02.480\n<v ->底盘将允许您的V5机器人</v>\n\n2\n00:00:02.480 --> 00:00:06.460\n通过单个指令块来驱动和转向精确的距离。\n\n3\n00:00:06.460 --> 00:00:08.370\n你可以通过设备窗口\n\n4\n00:00:08.370 --> 00:00:10.370\n添加一个遥控器到程序中。\n\n5\n00:00:10.370 --> 00:00:11.880\n打开“设备”窗口\n\n6\n00:00:14.350 --> 00:00:16.363\n并选择“添加设备”。\n\n7\n00:00:17.460 --> 00:00:19.707\n下一步，选择底盘。\n\n8\n00:00:22.120 --> 00:00:24.491\n首先，选择底盘上左侧和右侧\n\n9\n00:00:24.491 --> 00:00:28.600\n的V5智能电机端口号。\n\n10\n00:00:28.600 --> 00:00:32.341\n接下来，选择您的底盘是否有一个陀螺仪。\n\n11\n00:00:32.341 --> 00:00:34.960\n如果您的底盘确实有一个惯性传感器，\n\n12\n00:00:34.960 --> 00:00:37.850\n选择惯性传感器选项\n\n13\n00:00:37.850 --> 00:00:40.713\n以及惯性传感器已连接的智能端口号。\n\n14\n00:00:43.180 --> 00:00:45.950\n如果您的底盘确实有一个三线陀螺仪，\n\n15\n00:00:45.950 --> 00:00:48.380\n选择三线陀螺仪选项\n\n16\n00:00:49.740 --> 00:00:52.603\n以及三线陀螺仪已连接的端口号。\n\n17\n00:00:54.750 --> 00:00:57.820\n如果您的底盘确实没有三线陀螺仪，\n\n18\n00:00:57.820 --> 00:01:00.053\n选择“无陀螺仪”选项。\n\n19\n00:01:01.430 --> 00:01:04.160\n现在，设置底盘。\n\n20\n00:01:04.160 --> 00:01:06.520\n首先，看看底盘上的车轮\n\n21\n00:01:06.520 --> 00:01:09.413\n并从下拉菜单选择对应车轮的尺寸。\n\n22\n00:01:12.860 --> 00:01:16.030\n接下来，看看底盘的齿轮\n\n23\n00:01:16.030 --> 00:01:18.940\n并键入输入和输出齿轮比。\n\n24\n00:01:18.940 --> 00:01:20.940\n如果您没有使用陀螺仪，\n\n25\n00:01:20.940 --> 00:01:22.270\n您将看到两个关于\n\n26\n00:01:22.270 --> 00:01:25.370\n轴距和轮距的设置。\n\n27\n00:01:25.370 --> 00:01:27.880\n轮距是底盘的宽度。\n\n28\n00:01:27.880 --> 00:01:29.480\n测量底盘的宽度\n\n29\n00:01:29.480 --> 00:01:30.943\n并更新设置。\n\n30\n00:01:33.200 --> 00:01:36.390\n轮距是底盘前轮和后轮\n\n31\n00:01:36.390 --> 00:01:38.360\n中心点之间的距离。\n\n32\n00:01:38.360 --> 00:01:40.450\n测量两个车轮之间的距离\n\n33\n00:01:40.450 --> 00:01:42.043\n并更新设置。\n\n34\n00:01:43.310 --> 00:01:46.330\n接下来，选择V5智能电机\n\n35\n00:01:46.330 --> 00:01:48.253\n安装的齿轮组。\n\n36\n00:01:50.730 --> 00:01:53.680\n最后，如果您的底盘反向驱动，\n\n37\n00:01:53.680 --> 00:01:55.520\n你的底盘是后退，\n\n38\n00:01:55.520 --> 00:01:58.220\n更改方向箭头来让您的底盘反向。\n\n39\n00:01:59.850 --> 00:02:01.170\n选择“完成”按钮\n\n40\n00:02:03.180 --> 00:02:06.343\n然后底盘指令块现在将会出现在工具箱中。\n\n41\n00:02:07.180 --> 00:02:10.173\n您的底盘现在已设置完成并待用。\n\n"}},{"thumb":"V5_Tutorial_deviceSetup_motors.jpg","mov":"V5_Blocks_DeviceSetupMotors_V2","description":"Device Setup - Motors","filter":"","placeholder":false,"vimeo":"475899001","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>You can configure motors</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nfor your V5 robot with the devices window.\n\n3\n00:00:05.220 --> 00:00:07.773\nFirst, open the devices window.\n\n4\n00:00:09.500 --> 00:00:11.260\nSelect add a device\n\n5\n00:00:12.700 --> 00:00:14.273\nand choose motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nNext, select which port the smart motor is connected to\n\n7\n00:00:19.890 --> 00:00:21.453\non the V5 brain.\n\n8\n00:00:23.630 --> 00:00:27.080\nThe motor configuration screen now appears.\n\n9\n00:00:27.080 --> 00:00:30.203\nFrom here, you can change the name of the arm motor.\n\n10\n00:00:32.590 --> 00:00:35.230\nNext, you can also change the name of the motor's\n\n11\n00:00:35.230 --> 00:00:37.460\nforward and reverse directions.\n\n12\n00:00:37.460 --> 00:00:38.590\nFor this tutorial,\n\n13\n00:00:38.590 --> 00:00:41.650\nwe will configure a robotic arm on our robot\n\n14\n00:00:41.650 --> 00:00:44.630\nso you can set the directions from forward and reverse\n\n15\n00:00:45.750 --> 00:00:46.583\nto up\n\n16\n00:00:48.370 --> 00:00:49.203\nand down.\n\n17\n00:00:50.620 --> 00:00:53.400\nYou can also choose to reverse the motor.\n\n18\n00:00:53.400 --> 00:00:56.440\nThis setting will change the direction the motor rotates\n\n19\n00:00:56.440 --> 00:00:58.880\nwhen moving in either direction.\n\n20\n00:00:58.880 --> 00:01:02.090\nLastly, select which gear cartridge is installed\n\n21\n00:01:02.090 --> 00:01:04.800\nin your V5 smart motor.\n\n22\n00:01:04.800 --> 00:01:09.280\nOnce you are done configuring your smart motor, select done.\n\n23\n00:01:09.280 --> 00:01:12.163\nThe motor blocks will now appear in the toolbox.\n\n24\n00:01:13.010 --> 00:01:16.293\nYour smart motor is now configured and ready to use.\n\n","ar":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>يمكنك تكوين المحركات</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nللروبوت V5 الخاص بك باستعمال نافذة الأجهزة.\n\n3\n00:00:05.220 --> 00:00:07.773\nأولا، افتح نافذة الأجهزة.\n\n4\n00:00:09.500 --> 00:00:11.260\nحدد إضافة جهاز\n\n5\n00:00:12.700 --> 00:00:14.273\nواختر المحرك.\n\n6\n00:00:16.090 --> 00:00:19.890\nأخيرا اختر المنفذ الذي يرتبط به المحرك\n\n7\n00:00:19.890 --> 00:00:21.453\nعلى عقل V5.\n\n8\n00:00:23.630 --> 00:00:27.080\nستظهر الآن شاشة ضبط المحرك.\n\n9\n00:00:27.080 --> 00:00:30.203\nمن هنا، يمكنك تغيير اسم محرك الذراع.\n\n10\n00:00:32.590 --> 00:00:35.230\nبعد ذلك، يمكنك أيضا تغيير اسم\n\n11\n00:00:35.230 --> 00:00:37.460\nالإتجاهات الأمامية والخلفية للمحرك.\n\n12\n00:00:37.460 --> 00:00:38.590\nلهذا البرنامج التعليمي،\n\n13\n00:00:38.590 --> 00:00:41.650\nسنقوم ضبط إعدادات ذراع آلي على روبوتنا،\n\n14\n00:00:41.650 --> 00:00:44.630\nيمكنك تغيير الاتجاهات من الأمام والخلف\n\n15\n00:00:45.750 --> 00:00:46.583\nإلى الأعلى\n\n16\n00:00:48.370 --> 00:00:49.203\nوالأسفل.\n\n17\n00:00:50.620 --> 00:00:53.400\nيمكنك أيضاً اختيار عكس المحرك.\n\n18\n00:00:53.400 --> 00:00:56.440\nهذا الإعداد سيغير الاتجاه الذي يدور فيه المحرك\n\n19\n00:00:56.440 --> 00:00:58.880\nعند التحرك في أي من الاتجاهين.\n\n20\n00:00:58.880 --> 00:01:02.090\nأخيراً، إختر معدات المسننة المركبة\n\n21\n00:01:02.090 --> 00:01:04.800\nفي محرك V5 الذكية.\n\n22\n00:01:04.800 --> 00:01:09.280\nبمجرد الانتهاء من تكوين المحرك الذكي الخاص بك، حدد إنتهاء.\n\n23\n00:01:09.280 --> 00:01:12.163\nستظهر الآن مقاطع المحركات في صندوق الإعدادات.\n\n24\n00:01:13.010 --> 00:01:16.293\nالمحرك الذكي الخاص بك الآن مهيئ و جاهز للاستخدام.\n\n","cs":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Motory můžeš nastavit</v>\n\n2\n00:00:01.870 --> 00:00:05.220\npro tvého V5 robota v okně Zařízení.\n\n3\n00:00:05.220 --> 00:00:07.773\nNejprve otevři okno Zařízení.\n\n4\n00:00:09.500 --> 00:00:11.260\nVyber Přidat zařízení\n\n5\n00:00:12.700 --> 00:00:14.273\na zvol Motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nDále vyber do jakého portu je motor ramene připojený\n\n7\n00:00:19.890 --> 00:00:21.453\nna tvém V5 Mozku.\n\n8\n00:00:23.630 --> 00:00:27.080\nObjeví se obrazovka nastavení motoru.\n\n9\n00:00:27.080 --> 00:00:30.203\nOdtud můžeš změnit název motoru ramene.\n\n10\n00:00:32.590 --> 00:00:35.230\nDále můžeš také změnit název pro\n\n11\n00:00:35.230 --> 00:00:37.460\npřední a zadní směr otáčení motoru.\n\n12\n00:00:37.460 --> 00:00:38.590\nV tomto výukovém videu\n\n13\n00:00:38.590 --> 00:00:41.650\nnastavíme robotické rameno našeho robota tak,\n\n14\n00:00:41.650 --> 00:00:44.630\nabyste mohli upravit směry z dopředu a dozadu\n\n15\n00:00:45.750 --> 00:00:46.583\nna nahoru\n\n16\n00:00:48.370 --> 00:00:49.203\na dolů.\n\n17\n00:00:50.620 --> 00:00:53.400\nMůžeš také vybrat převrácení motoru.\n\n18\n00:00:53.400 --> 00:00:56.440\nToto nastavení změní směr, kterým se motor otáčí,\n\n19\n00:00:56.440 --> 00:00:58.880\nkdyž se pohybuje v obou směrech.\n\n20\n00:00:58.880 --> 00:01:02.090\nNakonec vyber jaká převodová vložka je namontována\n\n21\n00:01:02.090 --> 00:01:04.800\nna tvém chytrém V5 motoru.\n\n22\n00:01:04.800 --> 00:01:09.280\nJakmile dokončíš nastavování svého motoru, vyber Hotovo.\n\n23\n00:01:09.280 --> 00:01:12.163\nBloky motoru se nyní objeví na panelu nástrojů.\n\n24\n00:01:13.010 --> 00:01:16.293\nTvůj chytrý motor je nyní nastavený a připravený k použití.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Puede configurar los motores</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nde su robot V5 con la ventana de dispositivos.\n\n3\n00:00:05.220 --> 00:00:07.773\nPrimero, abra la ventana de dispositivos.\n\n4\n00:00:09.500 --> 00:00:11.260\nSeleccione Agregar un Dispositivo\n\n5\n00:00:12.700 --> 00:00:14.273\ny elija motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nPor último, seleccione el puerto al que está conectado el motor\n\n7\n00:00:19.890 --> 00:00:21.453\nen el V5 Brain.\n\n8\n00:00:23.630 --> 00:00:27.080\nAhora aparece la pantalla de ajustes del motor.\n\n9\n00:00:27.080 --> 00:00:30.203\nDesde aquí, puede cambiar el nombre del motor del brazo.\n\n10\n00:00:32.590 --> 00:00:35.230\nA continuación, también puede cambiar el nombre de la dirección del motor,\n\n11\n00:00:35.230 --> 00:00:37.460\nhacia adelante y reversa.\n\n12\n00:00:37.460 --> 00:00:38.590\nPara este tutorial\n\n13\n00:00:38.590 --> 00:00:41.650\nconfiguraremos un brazo robótico en nuestro robot\n\n14\n00:00:41.650 --> 00:00:44.630\npara que puedas establecer las direcciones de hacia adelante y reversa\n\n15\n00:00:45.750 --> 00:00:46.583\na arriba\n\n16\n00:00:48.370 --> 00:00:49.203\ny abajo.\n\n17\n00:00:50.620 --> 00:00:53.400\nTambién se puede optar por invertir el motor.\n\n18\n00:00:53.400 --> 00:00:56.440\nEste ajuste cambiará la dirección de la rotación del motor\n\n19\n00:00:56.440 --> 00:00:58.880\ncuando se mueve en cualquier dirección.\n\n20\n00:00:58.880 --> 00:01:02.090\nPor último, seleccione qué cartucho de engranajes está instalado\n\n21\n00:01:02.090 --> 00:01:04.800\nen sus V5 Smart Motors.\n\n22\n00:01:04.800 --> 00:01:09.280\nUna vez que haya terminado de configurar su motor, seleccione Hecho.\n\n23\n00:01:09.280 --> 00:01:12.163\nLos bloques de motor ahora aparecerán en la caja de herramientas.\n\n24\n00:01:13.010 --> 00:01:16.293\nSu motor ahora está configurado y listo para usar.\n\n","es":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Puede configurar los motores</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nde su robot V5 con la ventana de dispositivos.\n\n3\n00:00:05.220 --> 00:00:07.773\nPrimero, abra la ventana de dispositivos.\n\n4\n00:00:09.500 --> 00:00:11.260\nSeleccione Agregar un Dispositivo\n\n5\n00:00:12.700 --> 00:00:14.273\ny elija motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nPor último, seleccione el puerto al que está conectado el motor\n\n7\n00:00:19.890 --> 00:00:21.453\nen el V5 Brain.\n\n8\n00:00:23.630 --> 00:00:27.080\nAhora aparece la pantalla de ajustes del motor.\n\n9\n00:00:27.080 --> 00:00:30.203\nDesde aquí, puede cambiar el nombre del motor del brazo.\n\n10\n00:00:32.590 --> 00:00:35.230\nA continuación, también puede cambiar el nombre de la dirección del motor,\n\n11\n00:00:35.230 --> 00:00:37.460\nhacia adelante y reversa.\n\n12\n00:00:37.460 --> 00:00:38.590\nPara este tutorial\n\n13\n00:00:38.590 --> 00:00:41.650\nconfiguraremos un brazo robótico en nuestro robot\n\n14\n00:00:41.650 --> 00:00:44.630\npara que puedas establecer las direcciones de hacia adelante y reversa\n\n15\n00:00:45.750 --> 00:00:46.583\na arriba\n\n16\n00:00:48.370 --> 00:00:49.203\ny abajo.\n\n17\n00:00:50.620 --> 00:00:53.400\nTambién se puede optar por invertir el motor.\n\n18\n00:00:53.400 --> 00:00:56.440\nEste ajuste cambiará la dirección de la rotación del motor\n\n19\n00:00:56.440 --> 00:00:58.880\ncuando se mueve en cualquier dirección.\n\n20\n00:00:58.880 --> 00:01:02.090\nPor último, seleccione qué cartucho de engranajes está instalado\n\n21\n00:01:02.090 --> 00:01:04.800\nen sus V5 Smart Motors.\n\n22\n00:01:04.800 --> 00:01:09.280\nUna vez que haya terminado de configurar su motor, seleccione Hecho.\n\n23\n00:01:09.280 --> 00:01:12.163\nLos bloques de motor ahora aparecerán en la caja de herramientas.\n\n24\n00:01:13.010 --> 00:01:16.293\nSu motor ahora está configurado y listo para usar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Voit määritellä moottorit</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nV5 robottiin Laitteet -ikkunassa.\n\n3\n00:00:05.220 --> 00:00:07.773\nAvaa ensin Laitteet -ikkuna.\n\n4\n00:00:09.500 --> 00:00:11.260\nValitse laitteista\n\n5\n00:00:12.700 --> 00:00:14.273\nmoottorilaite Motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nValitse älymoottorin käyttämä portti\n\n7\n00:00:19.890 --> 00:00:21.453\nV5 -aivoissa.\n\n8\n00:00:23.630 --> 00:00:27.080\nSeuraavaksi avautuu moottorin tarkempi määritysikkuna.\n\n9\n00:00:27.080 --> 00:00:30.203\nIkkunassa voit nimetä käsimoottorin.\n\n10\n00:00:32.590 --> 00:00:35.230\nVoit muuttaa moottorin pyörimissuunnan\n\n11\n00:00:35.230 --> 00:00:37.460\njoko eteenpäin tai taaksepäin valinnasta Normaali tai Vastakkainen.\n\n12\n00:00:37.460 --> 00:00:38.590\nTässä esimerkissä\n\n13\n00:00:38.590 --> 00:00:41.650\nmäärittelet robotin käsivarsimoottorin\n\n14\n00:00:41.650 --> 00:00:44.630\npyörimisuuntavalinasta\n\n15\n00:00:45.750 --> 00:00:46.583\nvastaamaan arvoa Normaali, ylös vasemmalle\n\n16\n00:00:48.370 --> 00:00:49.203\nja alas oikealle.\n\n17\n00:00:50.620 --> 00:00:53.400\nVoit myös vaihtaa moottorin pyörimissuunnan arvoon Vastakkainen.\n\n18\n00:00:53.400 --> 00:00:56.440\nTämä määritys muuttaa moottorin pyörimissuunnan\n\n19\n00:00:56.440 --> 00:00:58.880\nniin moottori pyörii vastakkaiseen suuntaan.\n\n20\n00:00:58.880 --> 00:01:02.090\nLopuksi valitse se Vaihdepakkaus,\n\n21\n00:01:02.090 --> 00:01:04.800\njoka on asennettu V5 älymoottoriin.\n\n22\n00:01:04.800 --> 00:01:09.280\nKun määritykset on kunnossa valitse Tehty -painike.\n\n23\n00:01:09.280 --> 00:01:12.163\nMoottori phjelmointiblokit ilmestyvät Liike -valinnan alle työkaluihin.\n\n24\n00:01:13.010 --> 00:01:16.293\nÄlymoottorisi on nyt määritelty ja valmis käyttöön.\n\n","fr":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Vous pouvez configurer les moteurs</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nde votre robot depuis la fenêtre des appareils.\n\n3\n00:00:05.220 --> 00:00:07.773\nTout d'abord, ouvrez la fenêtre des appareils.\n\n4\n00:00:09.500 --> 00:00:11.260\nSélectionnez \"Ajouter un périphérique\"\n\n5\n00:00:12.700 --> 00:00:14.273\net choisissez le moteur.\n\n6\n00:00:16.090 --> 00:00:19.890\nEnsuite, sélectionnez le port auquel le moteur intelligent est connecté\n\n7\n00:00:19.890 --> 00:00:21.453\nsur le cerveau V5.\n\n8\n00:00:23.630 --> 00:00:27.080\nL'écran de configuration du moteur s'affiche.\n\n9\n00:00:27.080 --> 00:00:30.203\nA partir de là, vous pouvez changer le nom du moteur de bras.\n\n10\n00:00:32.590 --> 00:00:35.230\nEnsuite, vous pouvez aussi changer le nom des directions\n\n11\n00:00:35.230 --> 00:00:37.460\navant et arrière du moteur.\n\n12\n00:00:37.460 --> 00:00:38.590\nPour ce tutoriel,\n\n13\n00:00:38.590 --> 00:00:41.650\nnous allons configurer un bras robotique sur notre robot\n\n14\n00:00:41.650 --> 00:00:44.630\npour que vous puissiez changer les directions \"Avant\" et \"Arrière\n\n15\n00:00:45.750 --> 00:00:46.583\npour \"Haut\"\n\n16\n00:00:48.370 --> 00:00:49.203\net \"Bas\".\n\n17\n00:00:50.620 --> 00:00:53.400\nVous pouvez également choisir d'inverser le sens du moteur.\n\n18\n00:00:53.400 --> 00:00:56.440\nCe paramètre va changer le sens de rotation du moteur\n\n19\n00:00:56.440 --> 00:00:58.880\nlorsqu'il se déplace dans un sens ou dans l'autre.\n\n20\n00:00:58.880 --> 00:01:02.090\nEnfin, sélectionnez quelle cartouche d'engrenages est installée\n\n21\n00:01:02.090 --> 00:01:04.800\ndans votre moteur intelligent V5.\n\n22\n00:01:04.800 --> 00:01:09.280\nUne fois que vous avez terminé la configuration de votre moteur intelligent, sélectionnez \"Terminé\".\n\n23\n00:01:09.280 --> 00:01:12.163\nLes blocs moteurs apparaîtront maintenant dans la boîte à outils.\n\n24\n00:01:13.010 --> 00:01:16.293\nVotre moteur intelligent est maintenant configuré et prêt à l'emploi.\n\n","ko":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>기기 창에서</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nV5 로봇의 모터를 구성할 수 있습니다.\n\n3\n00:00:05.220 --> 00:00:07.773\n먼저 기기 창을 엽니다.\n\n4\n00:00:09.500 --> 00:00:11.260\n기기 추가에서\n\n5\n00:00:12.700 --> 00:00:14.273\n모터를 선택합니다.\n\n6\n00:00:16.090 --> 00:00:19.890\n먼저 V5 브레인에서 팔 모터가\n\n7\n00:00:19.890 --> 00:00:21.453\n연결된 포트를 선택합니다.\n\n8\n00:00:23.630 --> 00:00:27.080\n이제 모터 구성 화면이 나타납니다.\n\n9\n00:00:27.080 --> 00:00:30.203\n여기에서 팔 모터의 이름을 변경할 수 있습니다.\n\n10\n00:00:32.590 --> 00:00:35.230\n모터의 전진 및 후진 방향의 이름도\n\n11\n00:00:35.230 --> 00:00:37.460\n변경할 수 있습니다.\n\n12\n00:00:37.460 --> 00:00:38.590\n이 사용 지침서를 보면\n\n13\n00:00:38.590 --> 00:00:41.650\n로봇 팔을 구성하여\n\n14\n00:00:41.650 --> 00:00:44.630\n앞 & 뒤 흔들기부터\n\n15\n00:00:45.750 --> 00:00:46.583\n위 & 아래 흔들기까지\n\n16\n00:00:48.370 --> 00:00:49.203\n세팅할 수 있습니다.\n\n17\n00:00:50.620 --> 00:00:53.400\n모터의 역회전도 선택할 수 있습니다.\n\n18\n00:00:53.400 --> 00:00:56.440\n이 설정은 어느 방향으로든 이동할 때\n\n19\n00:00:56.440 --> 00:00:58.880\n모터가 회전하는 방향을 변경합니다.\n\n20\n00:00:58.880 --> 00:01:02.090\n마지막으로 V5 스마트 모터에 설치된\n\n21\n00:01:02.090 --> 00:01:04.800\n기어 카트리지를 선택합니다.\n\n22\n00:01:04.800 --> 00:01:09.280\n스마트 모터 구성이 끝나면 완료 버튼을 선택하세요.\n\n23\n00:01:09.280 --> 00:01:12.163\n이제 모터 블록이 도구 상자에 나타납니다.\n\n24\n00:01:13.010 --> 00:01:16.293\n이제 스마트 모터는 구성 완료되고 사용할 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Prietaisų lange</v>\n\n2\n00:00:01.870 --> 00:00:05.220\ngalite sukonfigūruoti variklius savo \"V5\" robotui.\n\n3\n00:00:05.220 --> 00:00:07.773\nPirmiausia, atverkite prietaisų langą.\n\n4\n00:00:09.500 --> 00:00:11.260\nPasirinkite pridėti prietaisą\n\n5\n00:00:12.700 --> 00:00:14.273\nir pasirinkite variklį.\n\n6\n00:00:16.090 --> 00:00:19.890\nPasirinkite prie kokio \"V5\" smegenų prievado prijungtas\n\n7\n00:00:19.890 --> 00:00:21.453\nišmanusis variklis.\n\n8\n00:00:23.630 --> 00:00:27.080\nPasirodo variklio konfigūravimo langas.\n\n9\n00:00:27.080 --> 00:00:30.203\nČia galite keisti savo peties variklio pavadinimą.\n\n10\n00:00:32.590 --> 00:00:35.230\nTaip pat galite keisti variklio važiavimo į priekį ir atbulai\n\n11\n00:00:35.230 --> 00:00:37.460\nkrypčių pavadinimus.\n\n12\n00:00:37.460 --> 00:00:38.590\nŠiame pavyzdyje,\n\n13\n00:00:38.590 --> 00:00:41.650\nsukonfigūruosime mūsų roboto petį,\n\n14\n00:00:41.650 --> 00:00:44.630\nkad galėtumėte pakeisti važiavimo į priekį ir atgal kryptis\n\n15\n00:00:45.750 --> 00:00:46.583\nį \"viršus\"\n\n16\n00:00:48.370 --> 00:00:49.203\nir \"apačia\".\n\n17\n00:00:50.620 --> 00:00:53.400\nGaliausiai, taip pat galite apgręžti variklį.\n\n18\n00:00:53.400 --> 00:00:56.440\nŠis nustatymas pakeis variklio sukimosi kryptį\n\n19\n00:00:56.440 --> 00:00:58.880\njudant bet kuria kryptimi.\n\n20\n00:00:58.880 --> 00:01:02.090\nPo to, pasirinkite kokia pavarų kasetė sumontuota\n\n21\n00:01:02.090 --> 00:01:04.800\nJūsų išmaniajame \"V5\" variklyje.\n\n22\n00:01:04.800 --> 00:01:09.280\nBaigę konfigūruoti savo išmanųjį variklį, pasirinkite mygtuką \"Atlikti\".\n\n23\n00:01:09.280 --> 00:01:12.163\nParankinėje atsiras vaizdo variklio blokai.\n\n24\n00:01:13.010 --> 00:01:16.293\nJūsų išmanusis variklis yra sukonfigūruotas ir parengtas naudoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor> Jūs varat konfigurēt motoru</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nsavam V5 robotam, izmantojot ierīču logu.\n\n3\n00:00:05.220 --> 00:00:07.773\nVispirms atveriet ierīču logu.\n\n4\n00:00:09.500 --> 00:00:11.260\nAtlasiet “Add a device” (pievienot ierīci)\n\n5\n00:00:12.700 --> 00:00:14.273\nun atlasiet motoru.\n\n6\n00:00:16.090 --> 00:00:19.890\nIzvēlieties, pie kura porta ir pievienots viedais motors\n\n7\n00:00:19.890 --> 00:00:21.453\nV5 smadzenēs.\n\n8\n00:00:23.630 --> 00:00:27.080\nTagad tiek parādīts motora konfigurācijas ekrāns.\n\n9\n00:00:27.080 --> 00:00:30.203\nŠeit variet mainīt rokas motora nosaukumu.\n\n10\n00:00:32.590 --> 00:00:35.230\nPēc tam var mainīt arī nosaukumu motoriem, kas virza\n\n11\n00:00:35.230 --> 00:00:37.460\nkustības virzienā uz priekšu un atpakaļ.\n\n12\n00:00:37.460 --> 00:00:38.590\nŠajā apmācībā\n\n13\n00:00:38.590 --> 00:00:41.650\nmēs konfigurēsim robota mehānisko roku,\n\n14\n00:00:41.650 --> 00:00:44.630\nlai varētu iestatīt kustības virzību uz priekšu un atpakaļ,\n\n15\n00:00:45.750 --> 00:00:46.583\nuz augšu\n\n16\n00:00:48.370 --> 00:00:49.203\nun uz leju.\n\n17\n00:00:50.620 --> 00:00:53.400\nVariet arī iestatīt motoram pretējas ksutības virzienu.\n\n18\n00:00:53.400 --> 00:00:56.440\nŠis iestatījums mainīs motora rotācijas virzienu,\n\n19\n00:00:56.440 --> 00:00:58.880\npārvietojoties jebkurā virzienā.\n\n20\n00:00:58.880 --> 00:01:02.090\nIzvēlieties, kurš pārnesuma bloks ir uzstādīts\n\n21\n00:01:02.090 --> 00:01:04.800\njūsu V5 viedajā motorā.\n\n22\n00:01:04.800 --> 00:01:09.280\nKad ir pabeigta viedā motora konfigurēšana, atlasiet “Done” (gatavs).\n\n23\n00:01:09.280 --> 00:01:12.163\nRīklodziņā parādīsies motora bloki.\n\n24\n00:01:13.010 --> 00:01:16.293\nJūsu viedais motors ir uzstādīts un gatavs lietošanai.\n\n","nl":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>U kunt motoren</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nvoor uw V5 robot configureren met het venster Apparaten.\n\n3\n00:00:05.220 --> 00:00:07.773\nOpen eerst het venster Apparaten.\n\n4\n00:00:09.500 --> 00:00:11.260\nSelecteer Voeg een apparaat toe\n\n5\n00:00:12.700 --> 00:00:14.273\nen kies motor.\n\n6\n00:00:16.090 --> 00:00:19.890\nSelecteer nu op welke poort uw slimme motor is aangesloten\n\n7\n00:00:19.890 --> 00:00:21.453\nop de V5 Brein.\n\n8\n00:00:23.630 --> 00:00:27.080\nHet motor configuratiescherm wordt nu weergegeven.\n\n9\n00:00:27.080 --> 00:00:30.203\nHier kunt u de naam van de arm motor veranderen.\n\n10\n00:00:32.590 --> 00:00:35.230\nVervolgens kunt u ook de naam van de voorwaartse\n\n11\n00:00:35.230 --> 00:00:37.460\nen achterwaartse richting van de motor wijzigen.\n\n12\n00:00:37.460 --> 00:00:38.590\nVoor deze tutorial\n\n13\n00:00:38.590 --> 00:00:41.650\nzullen we een robotarm op onze robot configureren\n\n14\n00:00:41.650 --> 00:00:44.630\nzodat u de richtingen van voorwaarts en achterwaarts\n\n15\n00:00:45.750 --> 00:00:46.583\nnaar omhoog\n\n16\n00:00:48.370 --> 00:00:49.203\nen omlaag.\n\n17\n00:00:50.620 --> 00:00:53.400\nU kunt er ook voor kiezen om de motor om te keren.\n\n18\n00:00:53.400 --> 00:00:56.440\nDeze instelling verandert de richting waarin de motor draait\n\n19\n00:00:56.440 --> 00:00:58.880\nwanneer hij in beide richtingen beweegt.\n\n20\n00:00:58.880 --> 00:01:02.090\nSelecteer tot slot welke tandwielcartridge\n\n21\n00:01:02.090 --> 00:01:04.800\nin uw V5 slimme motor is geïnstalleerd.\n\n22\n00:01:04.800 --> 00:01:09.280\nAls u klaar bent met het configureren van uw slimme motor, selecteert u Gereed.\n\n23\n00:01:09.280 --> 00:01:12.163\nDe motorblokken zullen nu in de werkbalk verschijnen.\n\n24\n00:01:13.010 --> 00:01:16.293\nUw slimme motor is nu geconfigureerd en klaar voor gebruik.\n\n","pl":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Możesz skonfigurować silniki</v>\n\n2\n00:00:01.870 --> 00:00:05.220\ndla robota w oknie urządzenia.\n\n3\n00:00:05.220 --> 00:00:07.773\nNajpierw otwórz okno urządzenia.\n\n4\n00:00:09.500 --> 00:00:11.260\nWybierz Dodaj urządzenie\n\n5\n00:00:12.700 --> 00:00:14.273\ni wybierz silnik.\n\n6\n00:00:16.090 --> 00:00:19.890\nNastępnie wybierz port do którego silnik jest podłączony\n\n7\n00:00:19.890 --> 00:00:21.453\nna mózgu V5.\n\n8\n00:00:23.630 --> 00:00:27.080\nEkran ustawień silnika teraz się pojawi.\n\n9\n00:00:27.080 --> 00:00:30.203\nTutaj możesz zmienić nazwę silnika ramion.\n\n10\n00:00:32.590 --> 00:00:35.230\nNastępnie możesz również zmienić nazwę silnika\n\n11\n00:00:35.230 --> 00:00:37.460\nkierunki do przodu i do tyłu.\n\n12\n00:00:37.460 --> 00:00:38.590\nW tym samouczku,\n\n13\n00:00:38.590 --> 00:00:41.650\nskonfigurujemy robotyczne ramię w naszym robocie\n\n14\n00:00:41.650 --> 00:00:44.630\nwięc możesz ustawić kierunki z przodu i z tyłu\n\n15\n00:00:45.750 --> 00:00:46.583\ndo góry\n\n16\n00:00:48.370 --> 00:00:49.203\ni w dół.\n\n17\n00:00:50.620 --> 00:00:53.400\nNa koniec można również wybrać odwrócenie silnika.\n\n18\n00:00:53.400 --> 00:00:56.440\nTo ustawienie zmieni kierunek, w którym silnik obraca się\n\n19\n00:00:56.440 --> 00:00:58.880\npodczas poruszania się w dowolnym kierunku.\n\n20\n00:00:58.880 --> 00:01:02.090\nZaznacz, która zębatka została zainstalowana\n\n21\n00:01:02.090 --> 00:01:04.800\nw silniku V5.\n\n22\n00:01:04.800 --> 00:01:09.280\nPo zakończeniu konfigurowania silnika, wybierz gotowe.\n\n23\n00:01:09.280 --> 00:01:12.163\nBloki silnika pojawią się teraz w przyborniku.\n\n24\n00:01:13.010 --> 00:01:16.293\nTwój silnik jest teraz skonfigurowany i gotowy do użycia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Настройка приводов робота</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nпроизводится с помощью окна настройки устройств.\n\n3\n00:00:05.220 --> 00:00:07.773\nДля начала, откройте окно настройки.\n\n4\n00:00:09.500 --> 00:00:11.260\nНажмите \"Добавить\"\n\n5\n00:00:12.700 --> 00:00:14.273\nи выберите привод.\n\n6\n00:00:16.090 --> 00:00:19.890\nДалее, выберите порт подключения привода\n\n7\n00:00:19.890 --> 00:00:21.453\nна контроллере.\n\n8\n00:00:23.630 --> 00:00:27.080\nПоявится окно настройки привода.\n\n9\n00:00:27.080 --> 00:00:30.203\nЗдесь вы можете изменить имя привода.\n\n10\n00:00:32.590 --> 00:00:35.230\nДалее, вы можете изменить названия направлений:\n\n11\n00:00:35.230 --> 00:00:37.460\nвперёд или назад.\n\n12\n00:00:37.460 --> 00:00:38.590\nВ рамках данного видео\n\n13\n00:00:38.590 --> 00:00:41.650\nмы настроим руку робота,\n\n14\n00:00:41.650 --> 00:00:44.630\nпоэтому вы можете изменить названия на\n\n15\n00:00:45.750 --> 00:00:46.583\nвверх\n\n16\n00:00:48.370 --> 00:00:49.203\nи вниз.\n\n17\n00:00:50.620 --> 00:00:53.400\nТакже, вы можете выбрать реверс привода.\n\n18\n00:00:53.400 --> 00:00:56.440\nДанная настройка изменит направление вращения привода\n\n19\n00:00:56.440 --> 00:00:58.880\nв любом направлении.\n\n20\n00:00:58.880 --> 00:01:02.090\nНаконец, выберите тип установленного картриджа\n\n21\n00:01:02.090 --> 00:01:04.800\nна вашем приводе.\n\n22\n00:01:04.800 --> 00:01:09.280\nПосле настройки привода, выберите \"Готово\".\n\n23\n00:01:09.280 --> 00:01:12.163\nБлоки приводов появились в инструментарии.\n\n24\n00:01:13.010 --> 00:01:16.293\nПриводы настроены и готовы к использованию.\n\n","th":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor> คุณสามารถกำหนดค่ามอเตอร์ </v>\n\n2\n00:00:01.870 --> 00:00:05.220\nสำหรับหุ่นยนต์ V5 ของคุณด้วยหน้าต่างอุปกรณ์\n\n3\n00:00:05.220 --> 00:00:07.773\nขั้นแรกเปิดหน้าต่างอุปกรณ์ devices window\n\n4\n00:00:09.500 --> 00:00:11.260\nจากนั้นเลือกเพิ่มอุปกรณ์\n\n5\n00:00:12.700 --> 00:00:14.273\nและเลือกมอเตอร์\n\n6\n00:00:16.090 --> 00:00:19.890\nจากนั้นเลือกพอร์ตที่สมาร์ทมอเตอร์เชื่อมต่ออยู่\n\n7\n00:00:19.890 --> 00:00:21.453\nบนสมองกล V5\n\n8\n00:00:23.630 --> 00:00:27.080\nหน้าจอการกำหนดค่ามอเตอร์จะปรากฏขึ้น\n\n9\n00:00:27.080 --> 00:00:30.203\nจากที่นี่คุณสามารถเปลี่ยนชื่อมอเตอร์แขนได้\n\n10\n00:00:32.590 --> 00:00:35.230\nถัดไปคุณสามารถเปลี่ยนชื่อ\n\n11\n00:00:35.230 --> 00:00:37.460\nทิศทางเดินหน้าถอยหลังมอเตอร์ได้\n\n12\n00:00:37.460 --> 00:00:38.590\nในบทเรียนนี้\n\n13\n00:00:38.590 --> 00:00:41.650\nเราจะกำหนดค่าแขนหุ่นยนต์ให้กับหุ่นยนต์ของเรา\n\n14\n00:00:41.650 --> 00:00:44.630\nเพื่อให้คุณสามารถกำหนดทิศทางจากเดินหน้าและถอยหลัง\n\n15\n00:00:45.750 --> 00:00:46.583\nขึ้น\n\n16\n00:00:48.370 --> 00:00:49.203\nและลงได้\n\n17\n00:00:50.620 --> 00:00:53.400\nนอกจากนี้คุณยังสามารถเลือกให้มอเตอร์ถอยหลังได้\n\n18\n00:00:53.400 --> 00:00:56.440\nการตั้งค่านี้จะเปลี่ยนทิศทางที่มอเตอร์หมุน\n\n19\n00:00:56.440 --> 00:00:58.880\nเมื่อเคลื่อนที่ไปในทิศทางใดทิศทางหนึ่ง\n\n20\n00:00:58.880 --> 00:01:02.090\nสุดท้ายเลือกตลับเกียร์ที่จะติดตั้ง\n\n21\n00:01:02.090 --> 00:01:04.800\nในมอเตอร์อัจฉริยะ V5 ของคุณ\n\n22\n00:01:04.800 --> 00:01:09.280\nเมื่อคุณกำหนดค่ามอเตอร์อัจฉริยะของคุณเสร็จแล้วให้เลือกเสร็จสิ้น\n\n23\n00:01:09.280 --> 00:01:12.163\nตอนนี้บล็อกมอเตอร์จะปรากฏในกล่องเครื่องมือ\n\n24\n00:01:13.010 --> 00:01:16.293\nสมาร์ทมอเตอร์ของคุณได้รับการกำหนดค่าและพร้อมใช้งานแล้ว\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Ви можете налаштувати мотори</v>\n\n2\n00:00:01.870 --> 00:00:05.220\nдля робота V5 через вікно пристроїв.\n\n3\n00:00:05.220 --> 00:00:07.773\nСпочатку відкрийте вікно пристроїв.\n\n4\n00:00:09.500 --> 00:00:11.260\nНатисніть \"Додати пристрій\"\n\n5\n00:00:12.700 --> 00:00:14.273\nі виберіть мотор.\n\n6\n00:00:16.090 --> 00:00:19.890\nТепер виберіть порт, у який ви приєднали розумний мотор\n\n7\n00:00:19.890 --> 00:00:21.453\nдо V5 Brain.\n\n8\n00:00:23.630 --> 00:00:27.080\nЗ'явиться вікно налаштувань мотора.\n\n9\n00:00:27.080 --> 00:00:30.203\nЗвідси ви можете змінити ім'я мотора руки.\n\n10\n00:00:32.590 --> 00:00:35.230\nДалі, ви можете змінити назву руху мотора\n\n11\n00:00:35.230 --> 00:00:37.460\nв прямому і у зворотному напрямку.\n\n12\n00:00:37.460 --> 00:00:38.590\nДля цього посібника\n\n13\n00:00:38.590 --> 00:00:41.650\nми налаштуємо роборуку нашого робота\n\n14\n00:00:41.650 --> 00:00:44.630\nтож ви можете встановити назву прямого і зворотного руху\n\n15\n00:00:45.750 --> 00:00:46.583\nяк up\n\n16\n00:00:48.370 --> 00:00:49.203\nі down.\n\n17\n00:00:50.620 --> 00:00:53.400\nВи також можете змінити напрямок руху мотора.\n\n18\n00:00:53.400 --> 00:00:56.440\nЦі налаштування змінять напрямок обертання мотора\n\n19\n00:00:56.440 --> 00:00:58.880\nв інший бік.\n\n20\n00:00:58.880 --> 00:01:02.090\nНасамкінець, виберіть, який редукторний картридж встановлено\n\n21\n00:01:02.090 --> 00:01:04.800\nу ваш розумний мотор V5.\n\n22\n00:01:04.800 --> 00:01:09.280\nКоли ви налаштуєте розумний мотор, натисніть \"Готово\".\n\n23\n00:01:09.280 --> 00:01:12.163\nБлоки мотору з'являться в наборі блоків.\n\n24\n00:01:13.010 --> 00:01:16.293\nВаш розумний мотор налаштований і готовий до використання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>Bạn có thể định cấu hình động cơ</v>\n\n2\n00:00:01.870 --> 00:00:05.220\ncho rô bốt V5 của bạn với cửa sổ thiết bị.\n\n3\n00:00:05.220 --> 00:00:07.773\nĐầu tiên, hãy mở cửa sổ thiết bị.\n\n4\n00:00:09.500 --> 00:00:11.260\nChọn thêm thiết bị\n\n5\n00:00:12.700 --> 00:00:14.273\nvà chọn động cơ.\n\n6\n00:00:16.090 --> 00:00:19.890\nTiếp theo, chọn cổng mà động cơ thông minh được kết nối với\n\n7\n00:00:19.890 --> 00:00:21.453\ntrên não V5.\n\n8\n00:00:23.630 --> 00:00:27.080\nMàn hình cấu hình động cơ bây giờ xuất hiện.\n\n9\n00:00:27.080 --> 00:00:30.203\nTừ đây, bạn có thể thay đổi tên của động cơ cánh tay.\n\n10\n00:00:32.590 --> 00:00:35.230\nTiếp theo, bạn cũng có thể thay đổi tên của động cơ\n\n11\n00:00:35.230 --> 00:00:37.460\nchiều thuận và chiều ngược lại.\n\n12\n00:00:37.460 --> 00:00:38.590\nĐối với hướng dẫn này,\n\n13\n00:00:38.590 --> 00:00:41.650\nchúng tôi sẽ định cấu hình một cánh tay rô bốt trên rô bốt của chúng tôi\n\n14\n00:00:41.650 --> 00:00:44.630\nvì vậy bạn có thể đặt các hướng từ phía trước và ngược lại\n\n15\n00:00:45.750 --> 00:00:46.583\nlên\n\n16\n00:00:48.370 --> 00:00:49.203\nvà xuống.\n\n17\n00:00:50.620 --> 00:00:53.400\nBạn cũng có thể chọn đảo ngược động cơ.\n\n18\n00:00:53.400 --> 00:00:56.440\nCài đặt này sẽ thay đổi hướng quay của động cơ\n\n19\n00:00:56.440 --> 00:00:58.880\nkhi di chuyển theo một trong hai hướng.\n\n20\n00:00:58.880 --> 00:01:02.090\nCuối cùng, chọn hộp bánh răng nào được lắp đặt\n\n21\n00:01:02.090 --> 00:01:04.800\ntrong động cơ thông minh V5 của bạn.\n\n22\n00:01:04.800 --> 00:01:09.280\nKhi bạn đã hoàn tất việc định cấu hình động cơ thông minh của mình, hãy chọn hoàn tất.\n\n23\n00:01:09.280 --> 00:01:12.163\nBây giờ các khối động cơ sẽ xuất hiện trong hộp công cụ.\n\n24\n00:01:13.010 --> 00:01:16.293\nĐộng cơ thông minh của bạn hiện đã được định cấu hình và sẵn sàng sử dụng.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\ncrwdns95858:0crwdne95858:0\n\n2\n00:00:01.870 --> 00:00:05.220\ncrwdns95860:0crwdne95860:0\n\n3\n00:00:05.220 --> 00:00:07.773\ncrwdns95862:0crwdne95862:0\n\n4\n00:00:09.500 --> 00:00:11.260\ncrwdns95864:0crwdne95864:0\n\n5\n00:00:12.700 --> 00:00:14.273\ncrwdns95866:0crwdne95866:0\n\n6\n00:00:16.090 --> 00:00:19.890\ncrwdns95868:0crwdne95868:0\n\n7\n00:00:19.890 --> 00:00:21.453\ncrwdns95870:0crwdne95870:0\n\n8\n00:00:23.630 --> 00:00:27.080\ncrwdns95872:0crwdne95872:0\n\n9\n00:00:27.080 --> 00:00:30.203\ncrwdns95874:0crwdne95874:0\n\n10\n00:00:32.590 --> 00:00:35.230\ncrwdns95876:0crwdne95876:0\n\n11\n00:00:35.230 --> 00:00:37.460\ncrwdns95878:0crwdne95878:0\n\n12\n00:00:37.460 --> 00:00:38.590\ncrwdns95880:0crwdne95880:0\n\n13\n00:00:38.590 --> 00:00:41.650\ncrwdns95882:0crwdne95882:0\n\n14\n00:00:41.650 --> 00:00:44.630\ncrwdns95884:0crwdne95884:0\n\n15\n00:00:45.750 --> 00:00:46.583\ncrwdns95886:0crwdne95886:0\n\n16\n00:00:48.370 --> 00:00:49.203\ncrwdns95888:0crwdne95888:0\n\n17\n00:00:50.620 --> 00:00:53.400\ncrwdns95890:0crwdne95890:0\n\n18\n00:00:53.400 --> 00:00:56.440\ncrwdns95892:0crwdne95892:0\n\n19\n00:00:56.440 --> 00:00:58.880\ncrwdns95894:0crwdne95894:0\n\n20\n00:00:58.880 --> 00:01:02.090\ncrwdns95896:0crwdne95896:0\n\n21\n00:01:02.090 --> 00:01:04.800\ncrwdns95898:0crwdne95898:0\n\n22\n00:01:04.800 --> 00:01:09.280\ncrwdns95900:0crwdne95900:0\n\n23\n00:01:09.280 --> 00:01:12.163\ncrwdns95902:0crwdne95902:0\n\n24\n00:01:13.010 --> 00:01:16.293\ncrwdns95904:0crwdne95904:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:01.870\n<v Instructor>您可以配置电机</v>\n\n2\n00:00:01.870 --> 00:00:05.220\n配置您的V5机器人电机。\n\n3\n00:00:05.220 --> 00:00:07.773\n首先，打开设备窗口，\n\n4\n00:00:09.500 --> 00:00:11.260\n选择“添加设备”\n\n5\n00:00:12.700 --> 00:00:14.273\n并选中电机。\n\n6\n00:00:16.090 --> 00:00:19.890\n接下来，选择电机连接至V5主控器的\n\n7\n00:00:19.890 --> 00:00:21.453\n端口号。\n\n8\n00:00:23.630 --> 00:00:27.080\n电机设置屏幕现在显现。\n\n9\n00:00:27.080 --> 00:00:30.203\n从这里，您可以重命名机械臂电机。\n\n10\n00:00:32.590 --> 00:00:35.230\n接下来，您也可以重命名电机\n\n11\n00:00:35.230 --> 00:00:37.460\n“正”和“反”方向的名称。\n\n12\n00:00:37.460 --> 00:00:38.590\n在本辅导视频里，\n\n13\n00:00:38.590 --> 00:00:41.650\n我们将设置机器人上的一个机械臂\n\n14\n00:00:41.650 --> 00:00:44.630\n这样您可以设定电机的方向从“正”和“反”\n\n15\n00:00:45.750 --> 00:00:46.583\n变为“上”\n\n16\n00:00:48.370 --> 00:00:49.203\n和“下”。\n\n17\n00:00:50.620 --> 00:00:53.400\n您也可以选择让电机反转。\n\n18\n00:00:53.400 --> 00:00:56.440\n当在任意方向运动时\n\n19\n00:00:56.440 --> 00:00:58.880\n这个设置将改变电机的转向。\n\n20\n00:00:58.880 --> 00:01:02.090\n最后，选择V5电机安装的\n\n21\n00:01:02.090 --> 00:01:04.800\n齿轮组。\n\n22\n00:01:04.800 --> 00:01:09.280\n一旦完成您的电机设置，选择“完成”。\n\n23\n00:01:09.280 --> 00:01:12.163\n电机指令块现在将会出现在工具箱中。\n\n24\n00:01:13.010 --> 00:01:16.293\n您的电机现在已设置完成并待用。\n\n"}},{"thumb":"V5_Tutorial_deviceSetup_sensors.jpg","mov":"V5_Blocks_DeviceSetupSensors_V2","description":"Device Setup - Sensors","filter":"","placeholder":false,"vimeo":"475899165","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>You can configure sensors for your V5 Robot</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nwith the devices window.\n\n3\n00:00:05.160 --> 00:00:08.010\nFirst open the devices window.\n\n4\n00:00:08.010 --> 00:00:13.010\nSelect Add a device and then select three wire devices.\n\n5\n00:00:14.200 --> 00:00:17.543\nNext select which sensor device you want to use.\n\n6\n00:00:18.950 --> 00:00:22.830\nNow select which three wire port your sensor is connected to\n\n7\n00:00:22.830 --> 00:00:24.283\non V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nPlease note that some three wire devices\n\n9\n00:00:29.180 --> 00:00:31.743\nwill require you to select two ports.\n\n10\n00:00:32.760 --> 00:00:34.380\nOnce a port has been selected.\n\n11\n00:00:34.380 --> 00:00:36.280\nYou can change the name of the sensor.\n\n12\n00:00:39.110 --> 00:00:42.970\nOnce you are done configuring your sensor, select Done.\n\n13\n00:00:42.970 --> 00:00:45.653\nThe Sensor Blocks will now appear in the toolbox.\n\n14\n00:00:47.020 --> 00:00:49.733\nYour sensor is now configured and ready to use.\n\n","ar":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>يمكنك ضبط أجهزة استشعار للروبوت الخاص بك،</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nمن نافذة الأجهزة.\n\n3\n00:00:05.160 --> 00:00:08.010\nأولا، افتح نافذة الأجهزة.\n\n4\n00:00:08.010 --> 00:00:13.010\nإختر إضافة جهاز ثم إختر أجهزة ذات ثلاثة أسلاك.\n\n5\n00:00:14.200 --> 00:00:17.543\nبعد ذلك، حدد جهاز الاستشعار الذي تريد استخدامه.\n\n6\n00:00:18.950 --> 00:00:22.830\nالآن، حدد المنفذ ذا ثلاثة أسلاك المرتبط به مستشعرك،\n\n7\n00:00:22.830 --> 00:00:24.283\nعلى عقل V5.\n\n8\n00:00:26.950 --> 00:00:29.180\nيرجى ملاحظة أن هناك أجهزة ذا ثلاثة أسلاك\n\n9\n00:00:29.180 --> 00:00:31.743\nسوف يتطلب منك تحديد منفذين.\n\n10\n00:00:32.760 --> 00:00:34.380\nبمجرد إختيار المنفذ.\n\n11\n00:00:34.380 --> 00:00:36.280\nيمكنك تغيير اسم المستشعر.\n\n12\n00:00:39.110 --> 00:00:42.970\nبمجرد الانتهاء من تكوين المحرك الذكي الخاص بك، حدد إنتهاء.\n\n13\n00:00:42.970 --> 00:00:45.653\nستظهر الآن مقاطع الاستشعار في صندوق إعدادات.\n\n14\n00:00:47.020 --> 00:00:49.733\nالمستشعر الخاص بك الآن مهيأ وجاهز للاستخدام.\n\n","cs":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Senzory svého V5 robota můžeš nastavit</v>\n\n2\n00:00:03.310 --> 00:00:05.160\npomocí okna Zařízení.\n\n3\n00:00:05.160 --> 00:00:08.010\nNejprve otevři okno Zařízení.\n\n4\n00:00:08.010 --> 00:00:13.010\nVyber Přidat zařízení a potom vyber třídrátová zařízení.\n\n5\n00:00:14.200 --> 00:00:17.543\nDále vyber jaké senzorické zařízení chceš použít.\n\n6\n00:00:18.950 --> 00:00:22.830\nNyní vyber k jakému třídrátovému portu je tvůj senzor připojen\n\n7\n00:00:22.830 --> 00:00:24.283\nna V5 Mozku.\n\n8\n00:00:26.950 --> 00:00:29.180\nVšimni si prosím, že některá třídrátová zařízení\n\n9\n00:00:29.180 --> 00:00:31.743\nbudou požadovat výběr dvou portů.\n\n10\n00:00:32.760 --> 00:00:34.380\nJakmile je port vybrán,\n\n11\n00:00:34.380 --> 00:00:36.280\nmůžeš změnit název senzoru.\n\n12\n00:00:39.110 --> 00:00:42.970\nJakmile dokončíš nastavení svého senzoru, vyber Hotovo.\n\n13\n00:00:42.970 --> 00:00:45.653\nBloky senzoru se nyní objeví na panelu nástrojů.\n\n14\n00:00:47.020 --> 00:00:49.733\nTvůj senzor je nyní nastavený a připravený k použití.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Puede configurar los sensores para su V5 Robot</v>\n\n2\n00:00:03.310 --> 00:00:05.160\ncon la ventana de dispositivos.\n\n3\n00:00:05.160 --> 00:00:08.010\nPrimero, abra la ventana de dispositivos.\n\n4\n00:00:08.010 --> 00:00:13.010\nSeleccione Añadir un Dispositivo y luego seleccione dispositivos de tres hilos (3-wire).\n\n5\n00:00:14.200 --> 00:00:17.543\nA continuación, seleccione qué dispositivo de sensor desea utilizar.\n\n6\n00:00:18.950 --> 00:00:22.830\nAhora, seleccione el puerto de 3-hilos (3-wire) al que está conectado su sensor\n\n7\n00:00:22.830 --> 00:00:24.283\nen el V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nTen en cuenta que algunos dispositivos de tres-hilos (3-wire)\n\n9\n00:00:29.180 --> 00:00:31.743\nrequerirá seleccionar dos puertos.\n\n10\n00:00:32.760 --> 00:00:34.380\nUna vez que un puerto ha sido seleccionado.\n\n11\n00:00:34.380 --> 00:00:36.280\nSe puede cambiar el nombre del Sensor.\n\n12\n00:00:39.110 --> 00:00:42.970\nUna vez que haya terminado de configurar su sensor, seleccione Hecho.\n\n13\n00:00:42.970 --> 00:00:45.653\nLos bloques de sensors ahora aparecerán en la caja de herramientas.\n\n14\n00:00:47.020 --> 00:00:49.733\nSu sensor ahora está configurado y listo para usar.\n\n","es":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Puede configurar los sensores para su V5 Robot</v>\n\n2\n00:00:03.310 --> 00:00:05.160\ncon la ventana de dispositivos.\n\n3\n00:00:05.160 --> 00:00:08.010\nPrimero, abra la ventana de dispositivos.\n\n4\n00:00:08.010 --> 00:00:13.010\nSeleccione Añadir un Dispositivo y luego seleccione dispositivos de tres hilos (3-wire).\n\n5\n00:00:14.200 --> 00:00:17.543\nA continuación, seleccione qué dispositivo de sensor desea utilizar.\n\n6\n00:00:18.950 --> 00:00:22.830\nAhora, seleccione el puerto de 3-hilos (3-wire) al que está conectado su sensor\n\n7\n00:00:22.830 --> 00:00:24.283\nen el V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nTen en cuenta que algunos dispositivos de tres-hilos (3-wire)\n\n9\n00:00:29.180 --> 00:00:31.743\nrequerirá seleccionar dos puertos.\n\n10\n00:00:32.760 --> 00:00:34.380\nUna vez que un puerto ha sido seleccionado.\n\n11\n00:00:34.380 --> 00:00:36.280\nSe puede cambiar el nombre del Sensor.\n\n12\n00:00:39.110 --> 00:00:42.970\nUna vez que haya terminado de configurar su sensor, seleccione Hecho.\n\n13\n00:00:42.970 --> 00:00:45.653\nLos bloques de sensors ahora aparecerán en la caja de herramientas.\n\n14\n00:00:47.020 --> 00:00:49.733\nSu sensor ahora está configurado y listo para usar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Voit määritellä anturit V5 robottiin</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nLaitteet -ikkunasta.\n\n3\n00:00:05.160 --> 00:00:08.010\nAvaa Laitteet-ikkuna.\n\n4\n00:00:08.010 --> 00:00:13.010\nValitse Lisää laite -valinta ja valitse 3 -johto laitteet.\n\n5\n00:00:14.200 --> 00:00:17.543\nValise sitten se anturi, jota haluat käyttää.\n\n6\n00:00:18.950 --> 00:00:22.830\nValise portti, johon anturi on yhdistetty\n\n7\n00:00:22.830 --> 00:00:24.283\nV5 aivoissa.\n\n8\n00:00:26.950 --> 00:00:29.180\nJoillekkin 3-johto laitteille\n\n9\n00:00:29.180 --> 00:00:31.743\ntarvitaan kaksi porttia kuten anturityypeillä RangeFinder ja Encoder.\n\n10\n00:00:32.760 --> 00:00:34.380\nKun portti on valittu.\n\n11\n00:00:34.380 --> 00:00:36.280\nvoit vaihtaa laitteen nimen.\n\n12\n00:00:39.110 --> 00:00:42.970\nKun laitteen määritys on kunnossa, valitse Tehty-painike.\n\n13\n00:00:42.970 --> 00:00:45.653\nAnturin käyttöön tarvittavat blokit näkyvät nyt työkaluissa.\n\n14\n00:00:47.020 --> 00:00:49.733\nAnturisi määritys on valmis käyttöön.\n\n","fr":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Vous pouvez configurer des capteurs pour votre robot V5</v>\n\n2\n00:00:03.310 --> 00:00:05.160\ndepuis la fenêtre des appareils.\n\n3\n00:00:05.160 --> 00:00:08.010\nTout d'abord, ouvrez la fenêtre des appareils.\n\n4\n00:00:08.010 --> 00:00:13.010\nSélectionnez \"Ajouter un appareil\" puis sélectionnez l'appareil à trois fils.\n\n5\n00:00:14.200 --> 00:00:17.543\nEnsuite, sélectionnez le capteur que vous souhaitez utiliser.\n\n6\n00:00:18.950 --> 00:00:22.830\nSélectionnez maintenant le port trois fils auquel votre capteur est connecté\n\n7\n00:00:22.830 --> 00:00:24.283\nsur le Cerveau V5.\n\n8\n00:00:26.950 --> 00:00:29.180\nVeuillez noter que certains des appareils à trois fils\n\n9\n00:00:29.180 --> 00:00:31.743\nvous demanderont de sélectionner deux ports.\n\n10\n00:00:32.760 --> 00:00:34.380\nUne fois qu'un port a été sélectionné.\n\n11\n00:00:34.380 --> 00:00:36.280\nVous pouvez changer le nom du capteur.\n\n12\n00:00:39.110 --> 00:00:42.970\nUne fois que vous avez terminé la configuration de votre capteur, sélectionnez \"Terminé\".\n\n13\n00:00:42.970 --> 00:00:45.653\nLes blocs du capteur apparaîtront maintenant dans la boîte à outils.\n\n14\n00:00:47.020 --> 00:00:49.733\nVotre capteur est maintenant configuré et prêt à l'emploi.\n\n","ko":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>기기 창에서</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nV5 로봇 센서를 구성할 수 있습니다.\n\n3\n00:00:05.160 --> 00:00:08.010\n먼저 기기 창을 엽니다.\n\n4\n00:00:08.010 --> 00:00:13.010\n\"기기 추가\"에서 3-Wire 기기를 선택합니다.\n\n5\n00:00:14.200 --> 00:00:17.543\n다음은 사용할 센서를 선택하세요.\n\n6\n00:00:18.950 --> 00:00:22.830\n이제 센서가 연결된 3-Wire 포트를\n\n7\n00:00:22.830 --> 00:00:24.283\nV5 브레인에서 선택하세요.\n\n8\n00:00:26.950 --> 00:00:29.180\n일부 3-Wire 기기는\n\n9\n00:00:29.180 --> 00:00:31.743\n2개의 포트를 선택해야 합니다.\n\n10\n00:00:32.760 --> 00:00:34.380\n포트가 선택되면\n\n11\n00:00:34.380 --> 00:00:36.280\n센서의 이름을 변경할 수 있습니다.\n\n12\n00:00:39.110 --> 00:00:42.970\n센서 구성이 끝나면 \"완료\"를 선택하세요.\n\n13\n00:00:42.970 --> 00:00:45.653\n이제 센서 블록이 도구 상자에 나타납니다.\n\n14\n00:00:47.020 --> 00:00:49.733\n이제 센서 구성이 완료되고 사용할 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Prietaisų lange galite sukonfigūruoti</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nprietaisų lange.\n\n3\n00:00:05.160 --> 00:00:08.010\nPirmiausia, atverkite prietaisų langą.\n\n4\n00:00:08.010 --> 00:00:13.010\nPasirinkite pridėti prietaisą ir trijų laidų prietaisus.\n\n5\n00:00:14.200 --> 00:00:17.543\nPo to, pasirinkite kokį jutiklio prietaisą norite naudoti.\n\n6\n00:00:18.950 --> 00:00:22.830\nDabar, pasirinkite prie kokio \"V5 Brain\" prievado prijungtas\n\n7\n00:00:22.830 --> 00:00:24.283\ntrijų laidų prietaisas.\n\n8\n00:00:26.950 --> 00:00:29.180\nĮsidėmėkite, kad kai kuriems trijų laidų prietaisams\n\n9\n00:00:29.180 --> 00:00:31.743\nreikės pasirinkti du prievadus.\n\n10\n00:00:32.760 --> 00:00:34.380\nPasirinkę prievadą.\n\n11\n00:00:34.380 --> 00:00:36.280\nGalite keisti jutiklio pavadinimą.\n\n12\n00:00:39.110 --> 00:00:42.970\nBaigę konfigūruoti savo jutiklį, pasirinkite mygtuką \"Atlikti\".\n\n13\n00:00:42.970 --> 00:00:45.653\nParankinėje atsiras jutiklio blokai.\n\n14\n00:00:47.020 --> 00:00:49.733\nJūsų jutiklis yra sukonfigūruotas ir parengtas naudoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Variet konfigurēt V5 Robot sensorus,</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nizmantojot ierīču logu.\n\n3\n00:00:05.160 --> 00:00:08.010\nVispirms atveriet ierīču logu.\n\n4\n00:00:08.010 --> 00:00:13.010\nIzvēlieties “Add a device” (Pievienot ierīci) un pēc tam izvēlieties trīs vadu savienojumu ierīces.\n\n5\n00:00:14.200 --> 00:00:17.543\nPēc tam atlasiet sensora ierīci, kuru vēlaties lietot.\n\n6\n00:00:18.950 --> 00:00:22.830\nTagad izvēlieties, pie kura trīs vadu savienojuma porta jūsu sensors ir pievienots\n\n7\n00:00:22.830 --> 00:00:24.283\npie V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nLūdzu, ņemiet vērā, ka dažām trīs vadu savienojuma ierīcēm\n\n9\n00:00:29.180 --> 00:00:31.743\nbūs jāatlasa divi porti.\n\n10\n00:00:32.760 --> 00:00:34.380\nKad ir atlasīts ports,\n\n11\n00:00:34.380 --> 00:00:36.280\nvariet mainīt sensora nosaukumu.\n\n12\n00:00:39.110 --> 00:00:42.970\nKad ir pabeigta sensora konfigurēšana, atlasiet “Done” (gatavs).\n\n13\n00:00:42.970 --> 00:00:45.653\nRīklodziņā parādīsies sensora bloki.\n\n14\n00:00:47.020 --> 00:00:49.733\nJūsu sensors ir uzstādīts un gatavs lietošanai.\n\n","nl":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>U kunt sensoren voor uw V5 robot configureren,</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nmet het venster van apparaten.\n\n3\n00:00:05.160 --> 00:00:08.010\nOpen eerst het venster Apparaten.\n\n4\n00:00:08.010 --> 00:00:13.010\nSelecteer Een apparaat toevoegen en selecteer vervolgens driedraadse apparaten.\n\n5\n00:00:14.200 --> 00:00:17.543\nSelecteer vervolgens welk sensor apparaat u wilt gebruiken.\n\n6\n00:00:18.950 --> 00:00:22.830\nSelecteer nu op welke driedraadse poort uw sensor is aangesloten\n\n7\n00:00:22.830 --> 00:00:24.283\nop V5 Brein.\n\n8\n00:00:26.950 --> 00:00:29.180\nHoud er rekening mee dat u bij sommige driedraadse apparaten\n\n9\n00:00:29.180 --> 00:00:31.743\ntwee poorten moet selecteren.\n\n10\n00:00:32.760 --> 00:00:34.380\nWanneer een poort is geselecteerd.\n\n11\n00:00:34.380 --> 00:00:36.280\nU kunt de naam van de sensor veranderen.\n\n12\n00:00:39.110 --> 00:00:42.970\nAls u klaar bent met het configureren van uw sensor, selecteert u Gereed.\n\n13\n00:00:42.970 --> 00:00:45.653\nDe Sensorblokken zullen nu in de werkbalk verschijnen.\n\n14\n00:00:47.020 --> 00:00:49.733\nUw sensor is nu geconfigureerd en klaar voor gebruik.\n\n","pl":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Możesz skonfigurować czujniki dla robota V5</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nz oknem urządzenia.\n\n3\n00:00:05.160 --> 00:00:08.010\nNajpierw otwórz okno urządzenia.\n\n4\n00:00:08.010 --> 00:00:13.010\nWybierz \"Dodaj urządzenie\", a następnie wybierz urządzenia 3-przewodowe.\n\n5\n00:00:14.200 --> 00:00:17.543\nNastępnie wybierz czujnik, z którego chcesz skorzystać.\n\n6\n00:00:18.950 --> 00:00:22.830\nTeraz wybierz port z podłączonym czujnikiem\n\n7\n00:00:22.830 --> 00:00:24.283\nna mózgu V5.\n\n8\n00:00:26.950 --> 00:00:29.180\nPamiętaj, że niektóre 3-przewodowe użądzenia\n\n9\n00:00:29.180 --> 00:00:31.743\nbędą wymagały wybrania dwóch portów.\n\n10\n00:00:32.760 --> 00:00:34.380\nGdy port zostanie wybrany.\n\n11\n00:00:34.380 --> 00:00:36.280\nMożesz zmienić nazwę czujnika.\n\n12\n00:00:39.110 --> 00:00:42.970\nPo zakończeniu konfigurowania czujnika wybierz Gotowe.\n\n13\n00:00:42.970 --> 00:00:45.653\nBloki czujników pojawią się teraz w przyborniku.\n\n14\n00:00:47.020 --> 00:00:49.733\nTwój czujnik jest teraz skonfigurowany i gotowy do użycia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Вы можете настроить датчик вашего робота</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nс помощью окна добавления устройств.\n\n3\n00:00:05.160 --> 00:00:08.010\nДля начала, откройте окно настройки устройств.\n\n4\n00:00:08.010 --> 00:00:13.010\nВыберите \"Добавить\" и затем выберите трёхпроводные устройства.\n\n5\n00:00:14.200 --> 00:00:17.543\nДалее, выберите датчик.\n\n6\n00:00:18.950 --> 00:00:22.830\nВыберите порт подключения устройства\n\n7\n00:00:22.830 --> 00:00:24.283\nна контроллере.\n\n8\n00:00:26.950 --> 00:00:29.180\nПожалуйста, обратите внимание, что некоторые устройства\n\n9\n00:00:29.180 --> 00:00:31.743\nтребуют два порта подключения.\n\n10\n00:00:32.760 --> 00:00:34.380\nПосле выбора порта подключения,\n\n11\n00:00:34.380 --> 00:00:36.280\nВы можете изменить имя устройства.\n\n12\n00:00:39.110 --> 00:00:42.970\nПосле настройки датчика нажмите \"Готово\".\n\n13\n00:00:42.970 --> 00:00:45.653\nБлоки для устройства появятся в инструментарии.\n\n14\n00:00:47.020 --> 00:00:49.733\nДатчик настроен и готов к использованию.\n\n","th":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor> คุณสามารถกำหนดค่าเซ็นเซอร์สำหรับ V5 Robot ของคุณได้ </v>\n\n2\n00:00:03.310 --> 00:00:05.160\nด้วยหน้าต่างอุปกรณ์\n\n3\n00:00:05.160 --> 00:00:08.010\nขั้นแรกเปิดหน้าต่างอุปกรณ์ devices window\n\n4\n00:00:08.010 --> 00:00:13.010\nเลือก Add อุปกรณ์จากนั้นเลือก three wire devices\n\n5\n00:00:14.200 --> 00:00:17.543\nจากนั้นเลือกอุปกรณ์เซ็นเซอร์ที่คุณต้องการใช้งาน\n\n6\n00:00:18.950 --> 00:00:22.830\nตอนนี้เลือกพอร์ตสามสายที่เซ็นเซอร์ของคุณเชื่อมต่ออยู่\n\n7\n00:00:22.830 --> 00:00:24.283\nบนสมองกล V5 Brain\n\n8\n00:00:26.950 --> 00:00:29.180\nโปรดทราบว่าอุปกรณ์สายไฟสามสาย\n\n9\n00:00:29.180 --> 00:00:31.743\nจะทำให้คุณต้องเลือกสองพอร์ต\n\n10\n00:00:32.760 --> 00:00:34.380\nเมื่อเลือกพอร์ตแล้ว\n\n11\n00:00:34.380 --> 00:00:36.280\nคุณสามารถเปลี่ยนชื่อของเซ็นเซอร์ได้\n\n12\n00:00:39.110 --> 00:00:42.970\nเมื่อคุณกำหนดค่าเซ็นเซอร์ของคุณเสร็จแล้วให้เลือกเสร็จสิ้น Done\n\n13\n00:00:42.970 --> 00:00:45.653\nตอนนี้ Sensor Blocks จะปรากฏในกล่องเครื่องมือ\n\n14\n00:00:47.020 --> 00:00:49.733\nขณะนี้เซ็นเซอร์ของคุณได้รับการกำหนดค่าและพร้อมใช้งานแล้ว\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Ви можете налаштувати датчики робота V5</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nчерез вікно пристроїв.\n\n3\n00:00:05.160 --> 00:00:08.010\nСпочатку, відкрийте вікно пристроїв.\n\n4\n00:00:08.010 --> 00:00:13.010\nНатисніть \"Додати пристрій\" і виберіть тридротові пристрої.\n\n5\n00:00:14.200 --> 00:00:17.543\nДалі, оберіть датчик, який ви хочете використати.\n\n6\n00:00:18.950 --> 00:00:22.830\nТепер виберіть тридротовий порт, у який ви приєднали датчик\n\n7\n00:00:22.830 --> 00:00:24.283\nдо V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nЗверніть увагу, що деякі тридротові датчики\n\n9\n00:00:29.180 --> 00:00:31.743\nпотребують два порта.\n\n10\n00:00:32.760 --> 00:00:34.380\nКоли порт буде вибрано.\n\n11\n00:00:34.380 --> 00:00:36.280\nВи зможете змінити ім'я датчика.\n\n12\n00:00:39.110 --> 00:00:42.970\nЩойно ви закінчите налаштовувати датчик, натисніть \"Готово\".\n\n13\n00:00:42.970 --> 00:00:45.653\nБлоки датчика з'являться в наборі блоків.\n\n14\n00:00:47.020 --> 00:00:49.733\nТепер ваш датчик налаштований і готовий до використання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>Bạn có thể định cấu hình cảm biến cho Robot V5 của mình</v>\n\n2\n00:00:03.310 --> 00:00:05.160\nvới cửa sổ thiết bị.\n\n3\n00:00:05.160 --> 00:00:08.010\nĐầu tiên hãy mở cửa sổ thiết bị.\n\n4\n00:00:08.010 --> 00:00:13.010\nChọn Thêm thiết bị, sau đó chọn ba thiết bị dây.\n\n5\n00:00:14.200 --> 00:00:17.543\nTiếp theo chọn thiết bị cảm biến mà bạn muốn sử dụng.\n\n6\n00:00:18.950 --> 00:00:22.830\nBây giờ hãy chọn cổng ba dây mà cảm biến của bạn được kết nối với\n\n7\n00:00:22.830 --> 00:00:24.283\ntrên V5 Brain.\n\n8\n00:00:26.950 --> 00:00:29.180\nXin lưu ý rằng một số thiết bị ba dây\n\n9\n00:00:29.180 --> 00:00:31.743\nsẽ yêu cầu bạn chọn hai cổng.\n\n10\n00:00:32.760 --> 00:00:34.380\nKhi một cổng đã được chọn.\n\n11\n00:00:34.380 --> 00:00:36.280\nBạn có thể thay đổi tên của cảm biến.\n\n12\n00:00:39.110 --> 00:00:42.970\nKhi bạn đã hoàn tất việc định cấu hình cảm biến của mình, hãy chọn Xong.\n\n13\n00:00:42.970 --> 00:00:45.653\nBây giờ các Khối cảm biến sẽ xuất hiện trong hộp công cụ.\n\n14\n00:00:47.020 --> 00:00:49.733\nCảm biến của bạn hiện đã được định cấu hình và sẵn sàng sử dụng.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\ncrwdns95906:0crwdne95906:0\n\n2\n00:00:03.310 --> 00:00:05.160\ncrwdns95908:0crwdne95908:0\n\n3\n00:00:05.160 --> 00:00:08.010\ncrwdns95910:0crwdne95910:0\n\n4\n00:00:08.010 --> 00:00:13.010\ncrwdns95912:0crwdne95912:0\n\n5\n00:00:14.200 --> 00:00:17.543\ncrwdns95914:0crwdne95914:0\n\n6\n00:00:18.950 --> 00:00:22.830\ncrwdns95916:0crwdne95916:0\n\n7\n00:00:22.830 --> 00:00:24.283\ncrwdns95918:0crwdne95918:0\n\n8\n00:00:26.950 --> 00:00:29.180\ncrwdns95920:0crwdne95920:0\n\n9\n00:00:29.180 --> 00:00:31.743\ncrwdns95922:0crwdne95922:0\n\n10\n00:00:32.760 --> 00:00:34.380\ncrwdns170820:0crwdne170820:0\n\n11\n00:00:34.380 --> 00:00:36.280\ncrwdns95926:0crwdne95926:0\n\n12\n00:00:39.110 --> 00:00:42.970\ncrwdns95928:0crwdne95928:0\n\n13\n00:00:42.970 --> 00:00:45.653\ncrwdns95930:0crwdne95930:0\n\n14\n00:00:47.020 --> 00:00:49.733\ncrwdns95932:0crwdne95932:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.000 --> 00:00:03.310\n<v Instructor>您可以为V5机器人设置传感器</v>\n\n2\n00:00:03.310 --> 00:00:05.160\n添加一个遥控器到程序中。\n\n3\n00:00:05.160 --> 00:00:08.010\n首先，打开“设备”窗口，\n\n4\n00:00:08.010 --> 00:00:13.010\n选择“添加设备”然后选择三线设备。\n\n5\n00:00:14.200 --> 00:00:17.543\n接下来，选择您想要使用的传感器。\n\n6\n00:00:18.950 --> 00:00:22.830\n现在选择您的传感器连接到\n\n7\n00:00:22.830 --> 00:00:24.283\nv5主控器的端口号。\n\n8\n00:00:26.950 --> 00:00:29.180\n请注意某些三线设备\n\n9\n00:00:29.180 --> 00:00:31.743\n须要您选择两个端口。\n\n10\n00:00:32.760 --> 00:00:34.380\n端口选好以后，\n\n11\n00:00:34.380 --> 00:00:36.280\n您可以重命名传感器。\n\n12\n00:00:39.110 --> 00:00:42.970\n一旦您完成传感器设置，选择“完成”。\n\n13\n00:00:42.970 --> 00:00:45.653\n传感器指令块现在将会出现在工具栏。\n\n14\n00:00:47.020 --> 00:00:49.733\n你的传感器现在已设置完成并待用。\n\n"}},{"thumb":"V5_Tutorial_deviceSetup_controller.jpg","mov":"V5_Blocks_DeviceSetupController_V2","description":"Device Setup - Controller","filter":"","placeholder":false,"vimeo":"475898637","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>A controller can be used</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nto drive your V5 robot remotely\n\n3\n00:00:04.080 --> 00:00:06.593\nwithout having to add any programming blocks.\n\n4\n00:00:07.450 --> 00:00:09.430\nBefore you configure the controller,\n\n5\n00:00:09.430 --> 00:00:11.340\nthe drive train and any motors\n\n6\n00:00:11.340 --> 00:00:13.533\nmust be added to your project first.\n\n7\n00:00:14.510 --> 00:00:16.410\nTo quickly configure the controller,\n\n8\n00:00:16.410 --> 00:00:18.370\nyou can use an example template\n\n9\n00:00:18.370 --> 00:00:21.203\nthat has a preconfigured drive train and motors.\n\n10\n00:00:22.890 --> 00:00:25.160\nNow add a controller to your project\n\n11\n00:00:25.160 --> 00:00:27.240\nwith the devices window.\n\n12\n00:00:27.240 --> 00:00:31.053\nOpen the devices window and select add a device.\n\n13\n00:00:32.130 --> 00:00:34.800\nNext, select controller.\n\n14\n00:00:34.800 --> 00:00:37.460\nYou can assign motors to buttons on the controller\n\n15\n00:00:37.460 --> 00:00:39.373\nby selecting the buttons to use.\n\n16\n00:00:40.600 --> 00:00:42.560\nContinue selecting the same buttons\n\n17\n00:00:42.560 --> 00:00:45.410\nto cycle through all available motors.\n\n18\n00:00:45.410 --> 00:00:48.163\nUse the blue arrow to flip motor directions.\n\n19\n00:00:51.390 --> 00:00:54.790\nNext, you can set the drive mode of the robot's drive train\n\n20\n00:00:54.790 --> 00:00:56.930\nby selecting the joysticks.\n\n21\n00:00:56.930 --> 00:00:59.310\nThere are four drive modes available,\n\n22\n00:00:59.310 --> 00:01:04.310\nleft arcade, right arcade, split arcade, tank.\n\n23\n00:01:04.320 --> 00:01:06.000\nContinue selecting the joysticks\n\n24\n00:01:06.000 --> 00:01:09.050\nto cycle through all available drive modes.\n\n25\n00:01:09.050 --> 00:01:11.330\nOnce your controller configuration is set,\n\n26\n00:01:11.330 --> 00:01:12.883\nselect the done button.\n\n27\n00:01:15.820 --> 00:01:18.320\nNo blocks need to be added to your project.\n\n28\n00:01:18.320 --> 00:01:19.800\nSimply download your project\n\n29\n00:01:19.800 --> 00:01:21.500\nand have fun with your controller.\n\n","ar":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>يمكن استخدام وحدة تحكم</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nلقيادة روبوت V5 الخاص بك عن بعد\n\n3\n00:00:04.080 --> 00:00:06.593\nدون الحاجة إلى إضافة أي قطع برمجية.\n\n4\n00:00:07.450 --> 00:00:09.430\nقبل ضبط إعدادات وحدة التحكم،\n\n5\n00:00:09.430 --> 00:00:11.340\nنظام الدفع وأي محركات\n\n6\n00:00:11.340 --> 00:00:13.533\nيجب أن تضاف إلى مشروعك أولاً.\n\n7\n00:00:14.510 --> 00:00:16.410\nلضبط إعدادات وحدة التحكم بسرعة،\n\n8\n00:00:16.410 --> 00:00:18.370\nيمكنك استخدام نموذج\n\n9\n00:00:18.370 --> 00:00:21.203\nيحتوي على نظام دفع و محركات مضبطة مسبقا.\n\n10\n00:00:22.890 --> 00:00:25.160\nالآن أضف وحدة تحكم إلى مشروعك\n\n11\n00:00:25.160 --> 00:00:27.240\nمن نافذة الأجهزة.\n\n12\n00:00:27.240 --> 00:00:31.053\nافتح نافذة الأجهزة وحدد إضافة جهاز.\n\n13\n00:00:32.130 --> 00:00:34.800\nبعد ذلك، حدد وحدة التحكم.\n\n14\n00:00:34.800 --> 00:00:37.460\nيمكنك تعيين المحركات للأزرار على وحدة التحكم\n\n15\n00:00:37.460 --> 00:00:39.373\nبإختيار الأزرار المستعملة.\n\n16\n00:00:40.600 --> 00:00:42.560\nإستمر في اختيار نفس الأزرار\n\n17\n00:00:42.560 --> 00:00:45.410\nللتنقل حول المحركات المتوفرة.\n\n18\n00:00:45.410 --> 00:00:48.163\nاستخدم السهم الأزرق لقلب اتجاهات المحرك.\n\n19\n00:00:51.390 --> 00:00:54.790\nبعد ذلك، يمكنك تعيين وضع قيادة نظام الدفع\n\n20\n00:00:54.790 --> 00:00:56.930\nعن طريق عصا التحكم.\n\n21\n00:00:56.930 --> 00:00:59.310\nهناك أربعة أوضاع قيادة متوفرة\n\n22\n00:00:59.310 --> 00:01:04.310\nبإستعمال العصا اليسرى، باستعمال العصا اليمنى، بإستعمال الاثنين أو الدبابة.\n\n23\n00:01:04.320 --> 00:01:06.000\nإستمر في إستعمال عصا التحكم\n\n24\n00:01:06.000 --> 00:01:09.050\nللتنقل حول أوضاع القيادة المتوفرة.\n\n25\n00:01:09.050 --> 00:01:11.330\nبمجرد ضبط إعدادات وحدة التحكم الخاصة بك،\n\n26\n00:01:11.330 --> 00:01:12.883\nحدد زر الانتهاء.\n\n27\n00:01:15.820 --> 00:01:18.320\nلا حاجة إلى إضافة مقاطع برمجة.\n\n28\n00:01:18.320 --> 00:01:19.800\nفقط قم بتحميل مشروعك\n\n29\n00:01:19.800 --> 00:01:21.500\nواستمتع بوحدة التحكم الخاصة بك.\n\n","cs":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Ovladač může být použit</v>\n\n2\n00:00:01.800 --> 00:00:04.080\npro dálkové řízení tvého V5 robota\n\n3\n00:00:04.080 --> 00:00:06.593\nbez nutnosti přidávat programovací bloky.\n\n4\n00:00:07.450 --> 00:00:09.430\nPředtím, než nastavíš ovladač,\n\n5\n00:00:09.430 --> 00:00:11.340\npodvozek a všechny motory\n\n6\n00:00:11.340 --> 00:00:13.533\nmusí být nejprve přidány do tvého projektu.\n\n7\n00:00:14.510 --> 00:00:16.410\nPro rychlé nastavení ovladače\n\n8\n00:00:16.410 --> 00:00:18.370\nmůžeš použít ukázkovou šablonu,\n\n9\n00:00:18.370 --> 00:00:21.203\nkterá má přednastavený podvozek a motory.\n\n10\n00:00:22.890 --> 00:00:25.160\nNyní přidej ovladač do svého projektu\n\n11\n00:00:25.160 --> 00:00:27.240\npomocí okna Zařízení.\n\n12\n00:00:27.240 --> 00:00:31.053\nOtevři okno Zařízení a vyber Přidat zařízení.\n\n13\n00:00:32.130 --> 00:00:34.800\nDále vyber Ovladač.\n\n14\n00:00:34.800 --> 00:00:37.460\nMůžeš přiřadit motory k tlačítkům na ovladači\n\n15\n00:00:37.460 --> 00:00:39.373\nvybráním tlačítek, které se mají použít.\n\n16\n00:00:40.600 --> 00:00:42.560\nPokračuj vybíráním stejných tlačítek\n\n17\n00:00:42.560 --> 00:00:45.410\npro proběhnutí všech dostupných motorů.\n\n18\n00:00:45.410 --> 00:00:48.163\nPoužij modrou šipku k převrácení směru motoru.\n\n19\n00:00:51.390 --> 00:00:54.790\nPotom můžeš nastavit režim pohonu robotova podvozku\n\n20\n00:00:54.790 --> 00:00:56.930\nvýběrem joysticků.\n\n21\n00:00:56.930 --> 00:00:59.310\nJsou k dispozici čtyři Režimy pohonu,\n\n22\n00:00:59.310 --> 00:01:04.310\nlevé ovládání, pravé ovládání, rozdělené ovládání, a pásový pohon.\n\n23\n00:01:04.320 --> 00:01:06.000\nPokračuj výběrem joysticků\n\n24\n00:01:06.000 --> 00:01:09.050\npro proběhnutí všech dostupných režimů.\n\n25\n00:01:09.050 --> 00:01:11.330\nJakmile je tvůj ovladač nastaven,\n\n26\n00:01:11.330 --> 00:01:12.883\nklikni na tlačítko Hotovo.\n\n27\n00:01:15.820 --> 00:01:18.320\nKe tvému projektu není potřeba přidávat žádné bloky.\n\n28\n00:01:18.320 --> 00:01:19.800\nJednoduše svůj projekt stáhni\n\n29\n00:01:19.800 --> 00:01:21.500\na příjemnou zábavu s tvým ovladačem.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Se puede utilizar un controlador</v>\n\n2\n00:00:01.800 --> 00:00:04.080\npara conducir su robot de forma remota\n\n3\n00:00:04.080 --> 00:00:06.593\nsin tener que agregar ningún bloque de programación.\n\n4\n00:00:07.450 --> 00:00:09.430\nAntes de configurar el controlador,\n\n5\n00:00:09.430 --> 00:00:11.340\nel tren motriz y motores\n\n6\n00:00:11.340 --> 00:00:13.533\ndeben ser añadido a su proyecto primero.\n\n7\n00:00:14.510 --> 00:00:16.410\nPara configurar el controlador rápidamente,\n\n8\n00:00:16.410 --> 00:00:18.370\npuede utilizar una plantilla de ejemplo\n\n9\n00:00:18.370 --> 00:00:21.203\nque tiene un Tren Motriz y motores preconfigurados.\n\n10\n00:00:22.890 --> 00:00:25.160\nAhora, agregue un controlador a su proyecto\n\n11\n00:00:25.160 --> 00:00:27.240\ncon la ventana de dispositivos.\n\n12\n00:00:27.240 --> 00:00:31.053\nAbre la ventana del dispositivo y selecciona Agregar un dispositivo.\n\n13\n00:00:32.130 --> 00:00:34.800\nA continuación, seleccione controlador.\n\n14\n00:00:34.800 --> 00:00:37.460\nPuede asignar motores a los botones del controlador\n\n15\n00:00:37.460 --> 00:00:39.373\nseleccionando los botones a utilizar.\n\n16\n00:00:40.600 --> 00:00:42.560\nContinúa seleccionando los mismos botones\n\n17\n00:00:42.560 --> 00:00:45.410\npara ciclear a través de todos los motores disponibles.\n\n18\n00:00:45.410 --> 00:00:48.163\nUsa la flecha azul para voltear las direcciones del motor.\n\n19\n00:00:51.390 --> 00:00:54.790\nA continuación, puede establecer el modo del Tren Motriz del robot\n\n20\n00:00:54.790 --> 00:00:56.930\nseleccionando los joysticks.\n\n21\n00:00:56.930 --> 00:00:59.310\nHay cuatro modos de conducción disponibles\n\n22\n00:00:59.310 --> 00:01:04.310\npalanca izquierda, palanca derecha, palanca dividida, y tanque.\n\n23\n00:01:04.320 --> 00:01:06.000\nContinuar seleccionando las palancas\n\n24\n00:01:06.000 --> 00:01:09.050\npara ciclear a través de todos los modos de conducción disponibles.\n\n25\n00:01:09.050 --> 00:01:11.330\nUna vez que la configuración del controlador está definida\n\n26\n00:01:11.330 --> 00:01:12.883\nseleccione el botón Hecho.\n\n27\n00:01:15.820 --> 00:01:18.320\nNo es necesario agregar bloques a su proyecto.\n\n28\n00:01:18.320 --> 00:01:19.800\nSimplemente descargue su proyecto\n\n29\n00:01:19.800 --> 00:01:21.500\ny diviértase con su controlador.\n\n","es":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Se puede utilizar un controlador</v>\n\n2\n00:00:01.800 --> 00:00:04.080\npara conducir su robot de forma remota\n\n3\n00:00:04.080 --> 00:00:06.593\nsin tener que agregar ningún bloque de programación.\n\n4\n00:00:07.450 --> 00:00:09.430\nAntes de configurar el controlador,\n\n5\n00:00:09.430 --> 00:00:11.340\nel tren motriz y motores\n\n6\n00:00:11.340 --> 00:00:13.533\ndeben ser añadido a su proyecto primero.\n\n7\n00:00:14.510 --> 00:00:16.410\nPara configurar el controlador rápidamente,\n\n8\n00:00:16.410 --> 00:00:18.370\npuede utilizar una plantilla de ejemplo\n\n9\n00:00:18.370 --> 00:00:21.203\nque tiene un Tren Motriz y motores preconfigurados.\n\n10\n00:00:22.890 --> 00:00:25.160\nAhora, agregue un controlador a su proyecto\n\n11\n00:00:25.160 --> 00:00:27.240\ncon la ventana de dispositivos.\n\n12\n00:00:27.240 --> 00:00:31.053\nAbre la ventana del dispositivo y selecciona Agregar un dispositivo.\n\n13\n00:00:32.130 --> 00:00:34.800\nA continuación, seleccione controlador.\n\n14\n00:00:34.800 --> 00:00:37.460\nPuede asignar motores a los botones del controlador\n\n15\n00:00:37.460 --> 00:00:39.373\nseleccionando los botones a utilizar.\n\n16\n00:00:40.600 --> 00:00:42.560\nContinúa seleccionando los mismos botones\n\n17\n00:00:42.560 --> 00:00:45.410\npara ciclear a través de todos los motores disponibles.\n\n18\n00:00:45.410 --> 00:00:48.163\nUsa la flecha azul para voltear las direcciones del motor.\n\n19\n00:00:51.390 --> 00:00:54.790\nA continuación, puede establecer el modo del Tren Motriz del robot\n\n20\n00:00:54.790 --> 00:00:56.930\nseleccionando los joysticks.\n\n21\n00:00:56.930 --> 00:00:59.310\nHay cuatro modos de conducción disponibles\n\n22\n00:00:59.310 --> 00:01:04.310\npalanca izquierda, palanca derecha, palanca dividida, y tanque.\n\n23\n00:01:04.320 --> 00:01:06.000\nContinuar seleccionando las palancas\n\n24\n00:01:06.000 --> 00:01:09.050\npara ciclear a través de todos los modos de conducción disponibles.\n\n25\n00:01:09.050 --> 00:01:11.330\nUna vez que la configuración del controlador está definida\n\n26\n00:01:11.330 --> 00:01:12.883\nseleccione el botón Hecho.\n\n27\n00:01:15.820 --> 00:01:18.320\nNo es necesario agregar bloques a su proyecto.\n\n28\n00:01:18.320 --> 00:01:19.800\nSimplemente descargue su proyecto\n\n29\n00:01:19.800 --> 00:01:21.500\ny diviértase con su controlador.\n\n","fi":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Ohjainta voi käyttää</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nkun haluaa ajaa V5 robottia ohjaimella\n\n3\n00:00:04.080 --> 00:00:06.593\nilman erillistä blokkiohjelmaa.\n\n4\n00:00:07.450 --> 00:00:09.430\nEnnenkuin määrittelet ohjaimen,\n\n5\n00:00:09.430 --> 00:00:11.340\najopelin ja moottorit\n\n6\n00:00:11.340 --> 00:00:13.533\nohjain pitää lisätä laitteena ohjelmaasi.\n\n7\n00:00:14.510 --> 00:00:16.410\nNopein tapa määrittellä ohjain on,\n\n8\n00:00:16.410 --> 00:00:18.370\nkun käytät ohjaimen esimerkkiohjelmaa,\n\n9\n00:00:18.370 --> 00:00:21.203\njossa on esimääritelty ajopeli ja muut moottorit jo valmiiksi.\n\n10\n00:00:22.890 --> 00:00:25.160\nLisää ohjain -laite ohjelmaasi\n\n11\n00:00:25.160 --> 00:00:27.240\nLaitteet -ikkunasta.\n\n12\n00:00:27.240 --> 00:00:31.053\nAvaa Laitteet -ikkuna ja lisää Controller-laite.\n\n13\n00:00:32.130 --> 00:00:34.800\nValitse Controller -ohjaimen kuva.\n\n14\n00:00:34.800 --> 00:00:37.460\nVoit kiinnittää moottorit ohjaimen eri nappeihin\n\n15\n00:00:37.460 --> 00:00:39.373\njoita haluat käyttää.\n\n16\n00:00:40.600 --> 00:00:42.560\nValitse napit\n\n17\n00:00:42.560 --> 00:00:45.410\nkaikille käytössä oleville moottoreille.\n\n18\n00:00:45.410 --> 00:00:48.163\nValitse sininen kaksoisnuoli muuttaaksesi moottorin pyörimissuuntaa.\n\n19\n00:00:51.390 --> 00:00:54.790\nItse Ajopelin ohjaustapa voidaan asettaa\n\n20\n00:00:54.790 --> 00:00:56.930\nvalitsemalla ohjaustateista sopiva valinta.\n\n21\n00:00:56.930 --> 00:00:59.310\nKäytössä on neljä eri vaihtoehtoa\n\n22\n00:00:59.310 --> 00:01:04.310\nvasemmalla tatinohjaus, oikeanohjaus, jaettu tattiohjaus ja tankkiajo.\n\n23\n00:01:04.320 --> 00:01:06.000\nValitse haluttu ajotapa\n\n24\n00:01:06.000 --> 00:01:09.050\nkäymällä läpi kaikki ajomoodit.\n\n25\n00:01:09.050 --> 00:01:11.330\nKun kaikki painikkeet ja tatit on asetettu,\n\n26\n00:01:11.330 --> 00:01:12.883\nvalitse Tehty -painike.\n\n27\n00:01:15.820 --> 00:01:18.320\nMitään blokkeja ei tarvitse lisätä ohjelmaasi.\n\n28\n00:01:18.320 --> 00:01:19.800\nLataa vain ohjelma\n\n29\n00:01:19.800 --> 00:01:21.500\nja ohjain on valmis ajoon.\n\n","fr":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Une manette peut être utilisée</v>\n\n2\n00:00:01.800 --> 00:00:04.080\npour piloter votre robot V5 à distance\n\n3\n00:00:04.080 --> 00:00:06.593\nsans avoir à ajouter de blocs de programmation.\n\n4\n00:00:07.450 --> 00:00:09.430\nAvant de configurer la manette,\n\n5\n00:00:09.430 --> 00:00:11.340\nla transmission et tous les moteurs\n\n6\n00:00:11.340 --> 00:00:13.533\ndoivent d'abord être ajoutés à votre projet.\n\n7\n00:00:14.510 --> 00:00:16.410\nPour configurer rapidement la manette,\n\n8\n00:00:16.410 --> 00:00:18.370\nvous pouvez utiliser un modèle d'exemple\n\n9\n00:00:18.370 --> 00:00:21.203\nqui a une transmission et des moteurs pré-configurés.\n\n10\n00:00:22.890 --> 00:00:25.160\nMaintenant, ajoutez une manette à votre projet\n\n11\n00:00:25.160 --> 00:00:27.240\ndepuis la fenêtre des appareils.\n\n12\n00:00:27.240 --> 00:00:31.053\nOuvrez la fenêtre des appareils et sélectionnez \"Ajouter un appareil\".\n\n13\n00:00:32.130 --> 00:00:34.800\nEnsuite, sélectionnez la manette.\n\n14\n00:00:34.800 --> 00:00:37.460\nVous pouvez assigner des moteurs aux boutons de la manette\n\n15\n00:00:37.460 --> 00:00:39.373\nen sélectionnant les boutons à utiliser.\n\n16\n00:00:40.600 --> 00:00:42.560\nContinuer à sélectionner les mêmes boutons\n\n17\n00:00:42.560 --> 00:00:45.410\npour parcourir tous les moteurs disponibles.\n\n18\n00:00:45.410 --> 00:00:48.163\nUtilisez la flèche bleue pour retourner la direction du moteur.\n\n19\n00:00:51.390 --> 00:00:54.790\nEnsuite, vous pouvez définir le mode de conduite de la transmission du robot\n\n20\n00:00:54.790 --> 00:00:56.930\nen sélectionnant les joysticks.\n\n21\n00:00:56.930 --> 00:00:59.310\nIl y a quatre modes de conduite disponibles,\n\n22\n00:00:59.310 --> 00:01:04.310\narcade gauche, arcade droite, arcade divisée, tank.\n\n23\n00:01:04.320 --> 00:01:06.000\nContinuez à sélectionner les joysticks\n\n24\n00:01:06.000 --> 00:01:09.050\npour parcourir tous les modes de conduite disponibles.\n\n25\n00:01:09.050 --> 00:01:11.330\nUne fois la configuration de votre manette terminée,\n\n26\n00:01:11.330 --> 00:01:12.883\nsélectionnez le bouton \"Terminé\".\n\n27\n00:01:15.820 --> 00:01:18.320\nAucun bloc n'a besoin d'être ajouté à votre projet.\n\n28\n00:01:18.320 --> 00:01:19.800\nTéléchargez simplement votre projet\n\n29\n00:01:19.800 --> 00:01:21.500\net amusez-vous avec votre manette.\n\n","ko":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>컨트롤러를 사용하면</v>\n\n2\n00:00:01.800 --> 00:00:04.080\n프로그래밍 블록을 추가하지 않고도\n\n3\n00:00:04.080 --> 00:00:06.593\n원격으로 V5 로봇을 드라이브할 수 있습니다.\n\n4\n00:00:07.450 --> 00:00:09.430\n컨트롤러를 구성하기 전에\n\n5\n00:00:09.430 --> 00:00:11.340\n먼저 드라이브트레인과 모터를\n\n6\n00:00:11.340 --> 00:00:13.533\n프로젝트에 추가해야 합니다.\n\n7\n00:00:14.510 --> 00:00:16.410\n컨트롤러를 빠르게 구성하기 위해\n\n8\n00:00:16.410 --> 00:00:18.370\n드라이브트레인과 모터를 미리 구성해 둔\n\n9\n00:00:18.370 --> 00:00:21.203\n예제 템플릿을 사용할 수 있습니다.\n\n10\n00:00:22.890 --> 00:00:25.160\n기기 창에서\n\n11\n00:00:25.160 --> 00:00:27.240\n프로젝트에 컨트롤러를 추가하십시오.\n\n12\n00:00:27.240 --> 00:00:31.053\n기기 창에서 \"기기 추가\"를 선택합니다.\n\n13\n00:00:32.130 --> 00:00:34.800\n다음은 컨트롤러를 선택하세요.\n\n14\n00:00:34.800 --> 00:00:37.460\n사용할 버튼을 선택함으로써 컨트롤러의 버튼에\n\n15\n00:00:37.460 --> 00:00:39.373\n모터를 할당할 수 있습니다.\n\n16\n00:00:40.600 --> 00:00:42.560\n사용 가능한 모든 모터를 순환하려면\n\n17\n00:00:42.560 --> 00:00:45.410\n동일한 버튼을 계속 선택하세요.\n\n18\n00:00:45.410 --> 00:00:48.163\n파란색 화살표를 사용하여 모터 방향을 전환합니다.\n\n19\n00:00:51.390 --> 00:00:54.790\n다음으로 조이스틱을 선택함으로써\n\n20\n00:00:54.790 --> 00:00:56.930\n로봇 드라이브트레인의 드라이브 모드를 설정할 수 있습니다.\n\n21\n00:00:56.930 --> 00:00:59.310\n네 가지 드라이브 모드, 즉\n\n22\n00:00:59.310 --> 00:01:04.310\n왼쪽 아케이드, 오른쪽 아케이드, 분할 아케이드, 탱크 모드를 사용할 수 있습니다.\n\n23\n00:01:04.320 --> 00:01:06.000\n조이스틱을 계속 사용하여\n\n24\n00:01:06.000 --> 00:01:09.050\n모든 드라이브 모드를 시도해 보세요.\n\n25\n00:01:09.050 --> 00:01:11.330\n컨트롤러 구성이 설정되었으면\n\n26\n00:01:11.330 --> 00:01:12.883\n\"완료\" 버튼을 선택하세요.\n\n27\n00:01:15.820 --> 00:01:18.320\n프로젝트에 블록을 추가할 필요 없습니다.\n\n28\n00:01:18.320 --> 00:01:19.800\n프로젝트를 다운로드하기만 하면\n\n29\n00:01:19.800 --> 00:01:21.500\n컨트롤러로 즐거운 시간을 보낼 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Galite naudoti valdiklį</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nsavo V5 robotui valdyti nuotoliniu būdu\n\n3\n00:00:04.080 --> 00:00:06.593\nnepridedant jokių programavimo blokų.\n\n4\n00:00:07.450 --> 00:00:09.430\nPrieš sukonfigūruodami valdiklį,\n\n5\n00:00:09.430 --> 00:00:11.340\npavaros mechanizmą ir bet kokius variklius\n\n6\n00:00:11.340 --> 00:00:13.533\nbūtina pridėti prie projekto.\n\n7\n00:00:14.510 --> 00:00:16.410\nNorėdami greitai sukonfigūruoti valdiklį,\n\n8\n00:00:16.410 --> 00:00:18.370\ngalite naudoti pavyzdinį šabloną,\n\n9\n00:00:18.370 --> 00:00:21.203\nkuriame yra iš anksto sukonfigūruoti pavaros mechanizmas ir varikliai.\n\n10\n00:00:22.890 --> 00:00:25.160\nDabar, prietaisų lange,\n\n11\n00:00:25.160 --> 00:00:27.240\nprie savo projekto pridėkite valdiklį.\n\n12\n00:00:27.240 --> 00:00:31.053\nAtverkite prietaisų langą ir pasirinkite pridėti prietaisą.\n\n13\n00:00:32.130 --> 00:00:34.800\nPasirinkite valdiklį.\n\n14\n00:00:34.800 --> 00:00:37.460\nValdiklio mygtukams galite priskirti variklius,\n\n15\n00:00:37.460 --> 00:00:39.373\nspustelėdami atitinkamą mygtuką, kuriuo varikliai bus valdomi.\n\n16\n00:00:40.600 --> 00:00:42.560\nIr toliau mygtuku\n\n17\n00:00:42.560 --> 00:00:45.410\ntikrinkite galimus variklius.\n\n18\n00:00:45.410 --> 00:00:48.163\nSukeiskite variklio kryptį mėlyna rodykle.\n\n19\n00:00:51.390 --> 00:00:54.790\nGalite pasirinkti roboto pavaros mechanizmo važiavimo režimą\n\n20\n00:00:54.790 --> 00:00:56.930\nrinkdamiesi vairalazdes.\n\n21\n00:00:56.930 --> 00:00:59.310\nYra keturi važiavimo režimai,\n\n22\n00:00:59.310 --> 00:01:04.310\nkairysis arkadinis, dešinysis arkadinis, pusiau arkadinis ir tankas.\n\n23\n00:01:04.320 --> 00:01:06.000\nIr toliau rinkitės vairalazdes,\n\n24\n00:01:06.000 --> 00:01:09.050\nkad tikrintumėte galimus važiavimo režimus.\n\n25\n00:01:09.050 --> 00:01:11.330\nSukonfigūravę valdiklį,\n\n26\n00:01:11.330 --> 00:01:12.883\nspustelėkite mygtuką \"Atlikti\".\n\n27\n00:01:15.820 --> 00:01:18.320\nĮ savo projektą nedėkite blokų.\n\n28\n00:01:18.320 --> 00:01:19.800\nPaprasčiausiai parsisiųskite savo projektą\n\n29\n00:01:19.800 --> 00:01:21.500\nir smagaus darbo su savo valdikliu.\n\n","lv":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator> Var izmantot vadāmierīci,</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nlai vadītu robotu attālināti,\n\n3\n00:00:04.080 --> 00:00:06.593\nneizmantojot nevienu programmēšanas bloku.\n\n4\n00:00:07.450 --> 00:00:09.430\nPirms vadāmierīces konfigurēšanas,\n\n5\n00:00:09.430 --> 00:00:11.340\npiedziņas sistēmu un motorus\n\n6\n00:00:11.340 --> 00:00:13.533\njāpievieno jūsu projektam.\n\n7\n00:00:14.510 --> 00:00:16.410\nLai ātrāk konfigurētu vadāmierīci,\n\n8\n00:00:16.410 --> 00:00:18.370\nvar izmantot parauga veidni,\n\n9\n00:00:18.370 --> 00:00:21.203\nkurā iepriekš konfigurēta piedziņas sistēma un motori.\n\n10\n00:00:22.890 --> 00:00:25.160\nTagad pievienojiet projektam vadāmierīci,\n\n11\n00:00:25.160 --> 00:00:27.240\nizmantojot ierīču logu.\n\n12\n00:00:27.240 --> 00:00:31.053\nAtveriet ierīču logu un izvēlieties ierīces pievienošanu.\n\n13\n00:00:32.130 --> 00:00:34.800\nPēc tam izvēlieties vadāmierīci.\n\n14\n00:00:34.800 --> 00:00:37.460\nVadāmierīces pogām var piešķirt motoru funkciju,\n\n15\n00:00:37.460 --> 00:00:39.373\natlasot lietojamās pogas.\n\n16\n00:00:40.600 --> 00:00:42.560\nTurpinot atlasīt vienu un to pašu pogu,\n\n17\n00:00:42.560 --> 00:00:45.410\ntiks izskatīti visi pieejamie motori.\n\n18\n00:00:45.410 --> 00:00:48.163\nIzmantojiet zilo bultiņu, lai mainītu motora virzienus.\n\n19\n00:00:51.390 --> 00:00:54.790\nPēc tam var iestatīt robota piedziņas sistēmas vadīšanas režīmu,\n\n20\n00:00:54.790 --> 00:00:56.930\nizvēloties kursorsviras.\n\n21\n00:00:56.930 --> 00:00:59.310\nIr pieejami četri vadīšanas režīmi,\n\n22\n00:00:59.310 --> 00:01:04.310\nkreisās puses pogas, labās puses pogas, abu pušu pogas un tanks.\n\n23\n00:01:04.320 --> 00:01:06.000\nTurpiniet, izvēloties kursorsviras,\n\n24\n00:01:06.000 --> 00:01:09.050\nlai izskatītu visus pieejamos vadīšanas režīmus.\n\n25\n00:01:09.050 --> 00:01:11.330\nKad ir iestatīta vadāmierīces konfigurācija,\n\n26\n00:01:11.330 --> 00:01:12.883\natlasiet pogu “Done” (gatavs).\n\n27\n00:01:15.820 --> 00:01:18.320\nJūsu projektam nav jāpievieno nekādi bloki.\n\n28\n00:01:18.320 --> 00:01:19.800\nVienkārši lejupielādējiet savu projektu\n\n29\n00:01:19.800 --> 00:01:21.500\nun baudiet vadāmierīces lietošanu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator> Een controller kan worden gebruikt </v>\n\n2\n00:00:01.800 --> 00:00:04.080\nom uw V5 robot op afstand te besturen\n\n3\n00:00:04.080 --> 00:00:06.593\nzonder dat u programmeerblokken hoeft toe te voegen.\n\n4\n00:00:07.450 --> 00:00:09.430\nVoordat u de controller configureert,\n\n5\n00:00:09.430 --> 00:00:11.340\nmoeten eerst de aandrijflijn en eventuele motoren\n\n6\n00:00:11.340 --> 00:00:13.533\naan uw project worden toegevoegd.\n\n7\n00:00:14.510 --> 00:00:16.410\nOm de controller snel te configureren,\n\n8\n00:00:16.410 --> 00:00:18.370\nkunt u een voorbeeldsjabloon gebruiken\n\n9\n00:00:18.370 --> 00:00:21.203\nmet een vooraf geconfigureerde aandrijflijn en motoren.\n\n10\n00:00:22.890 --> 00:00:25.160\nVoeg nu een controller aan uw project toe\n\n11\n00:00:25.160 --> 00:00:27.240\nmet het venster van apparaten.\n\n12\n00:00:27.240 --> 00:00:31.053\nOpen het apparatenvenster en selecteer een apparaat toevoegen.\n\n13\n00:00:32.130 --> 00:00:34.800\nVervolgens selecteer Controller.\n\n14\n00:00:34.800 --> 00:00:37.460\nU kunt motoren aan knoppen op de controller toewijzen\n\n15\n00:00:37.460 --> 00:00:39.373\ndoor de knoppen te selecteren die u wilt gebruiken.\n\n16\n00:00:40.600 --> 00:00:42.560\nGa door met het selecteren van dezelfde knoppen\n\n17\n00:00:42.560 --> 00:00:45.410\ndoor alle beschikbare motoren te bladeren.\n\n18\n00:00:45.410 --> 00:00:48.163\nGebruik de blauwe pijl om motorrichtingen om te draaien.\n\n19\n00:00:51.390 --> 00:00:54.790\nVervolgens kunt u de rijmodus van de aandrijflijn van de robot instellen\n\n20\n00:00:54.790 --> 00:00:56.930\ndoor de joysticks te selecteren.\n\n21\n00:00:56.930 --> 00:00:59.310\nEr zijn vier rij modi beschikbaar:\n\n22\n00:00:59.310 --> 00:01:04.310\nlinker arcade, rechter arcade, split arcade, tank.\n\n23\n00:01:04.320 --> 00:01:06.000\nGa door met het selecteren van de joysticks\n\n24\n00:01:06.000 --> 00:01:09.050\nom door alle beschikbare rij modi te bladeren.\n\n25\n00:01:09.050 --> 00:01:11.330\nZodra uw controllerconfiguratie is ingesteld,\n\n26\n00:01:11.330 --> 00:01:12.883\nselecteer de knop Gereed.\n\n27\n00:01:15.820 --> 00:01:18.320\nEr hoeven geen blokken aan uw project te worden toegevoegd.\n\n28\n00:01:18.320 --> 00:01:19.800\nDownload gewoon uw project\n\n29\n00:01:19.800 --> 00:01:21.500\nen veel plezier met uw controller.\n\n","pl":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Można użyć kontrolera</v>\n\n2\n00:00:01.800 --> 00:00:04.080\naby zdalnie kierować robotem\n\n3\n00:00:04.080 --> 00:00:06.593\nbez konieczności dodawania bloków programowania.\n\n4\n00:00:07.450 --> 00:00:09.430\nZanim skonfigurujesz kontroler,\n\n5\n00:00:09.430 --> 00:00:11.340\nukładem napędowy i wszelkimi silnikami\n\n6\n00:00:11.340 --> 00:00:13.533\nnajpierw należy dodać projekt.\n\n7\n00:00:14.510 --> 00:00:16.410\nAby szybko skonfigurować kontroler,\n\n8\n00:00:16.410 --> 00:00:18.370\nmożesz użyć przykładowego szablonu\n\n9\n00:00:18.370 --> 00:00:21.203\nktóry posiada wstępnie skonfigurowany układ napędowy i silniki.\n\n10\n00:00:22.890 --> 00:00:25.160\nTeraz dodaj kontroler do swojego projektu\n\n11\n00:00:25.160 --> 00:00:27.240\nz oknem urządzenia.\n\n12\n00:00:27.240 --> 00:00:31.053\nOtwórz okno urządzenia i wybierz Dodaj urządzenie.\n\n13\n00:00:32.130 --> 00:00:34.800\nNastępnie wybierz kontroler.\n\n14\n00:00:34.800 --> 00:00:37.460\nMożesz przypisać silniki do przycisków na kontrolerze\n\n15\n00:00:37.460 --> 00:00:39.373\nwybierając przyciski do użycia.\n\n16\n00:00:40.600 --> 00:00:42.560\nKontynuuj wybieranie tych samych przycisków\n\n17\n00:00:42.560 --> 00:00:45.410\nby przejść przez wszystkie dostępne silniki.\n\n18\n00:00:45.410 --> 00:00:48.163\nUżyj niebieskiej strzałki, aby obracać kierunkami silnika.\n\n19\n00:00:51.390 --> 00:00:54.790\nNastępnie możesz ustawić tryb jazdy układu napędowego robota\n\n20\n00:00:54.790 --> 00:00:56.930\nwybierając go joystickiem.\n\n21\n00:00:56.930 --> 00:00:59.310\nDostępne są cztery tryby jazdy,\n\n22\n00:00:59.310 --> 00:01:04.310\nlewa gałka, prawa gałka, dzielone gałki, czołg.\n\n23\n00:01:04.320 --> 00:01:06.000\nKontynuuj wybieranie joystickiem\n\n24\n00:01:06.000 --> 00:01:09.050\nby przejść przez wszystkie dostępne tryby jazdy.\n\n25\n00:01:09.050 --> 00:01:11.330\nPo ustawieniu konfiguracji kontrolera\n\n26\n00:01:11.330 --> 00:01:12.883\nwybierz przycisk Gotowe.\n\n27\n00:01:15.820 --> 00:01:18.320\nŻadne bloki nie muszą być dodane do twojego projektu.\n\n28\n00:01:18.320 --> 00:01:19.800\nPo prostu pobierz swój projekt\n\n29\n00:01:19.800 --> 00:01:21.500\ni baw się z kontrolerem.\n\n","ru":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Пульт может быть использован</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nдля удалённого управления роботом\n\n3\n00:00:04.080 --> 00:00:06.593\nбез необходимости добавления программируемых блоков.\n\n4\n00:00:07.450 --> 00:00:09.430\nПеред настройкой пульта управления\n\n5\n00:00:09.430 --> 00:00:11.340\nв проект должны быть добавлены трансмиссия\n\n6\n00:00:11.340 --> 00:00:13.533\nи все приводы.\n\n7\n00:00:14.510 --> 00:00:16.410\nДля быстрой настройки пульта\n\n8\n00:00:16.410 --> 00:00:18.370\nвы можете использовать шаблоны проектов,\n\n9\n00:00:18.370 --> 00:00:21.203\nкоторые предустановят трансмиссию и приводы.\n\n10\n00:00:22.890 --> 00:00:25.160\nДобавьте пульт к вашему проекту\n\n11\n00:00:25.160 --> 00:00:27.240\nс помощью окна добавления устройств.\n\n12\n00:00:27.240 --> 00:00:31.053\nОткройте окно устройств и добавьте устройство.\n\n13\n00:00:32.130 --> 00:00:34.800\nДалее, выберите пульт.\n\n14\n00:00:34.800 --> 00:00:37.460\nВы можете привязать приводы к определенным кнопкам пульта,\n\n15\n00:00:37.460 --> 00:00:39.373\nвыбрав кнопки.\n\n16\n00:00:40.600 --> 00:00:42.560\nПродолжайте назначать кнопки для всех\n\n17\n00:00:42.560 --> 00:00:45.410\nдоступных приводов.\n\n18\n00:00:45.410 --> 00:00:48.163\nИспользуйте голубую стрелку для изменения направления приводов.\n\n19\n00:00:51.390 --> 00:00:54.790\nДалее, вы можете установить режим работы трансмиссии,\n\n20\n00:00:54.790 --> 00:00:56.930\nвыбрав джойстики.\n\n21\n00:00:56.930 --> 00:00:59.310\nДоступны четыре режима работы робота:\n\n22\n00:00:59.310 --> 00:01:04.310\nправым или левым джойстиками, раздельное управление и танковое.\n\n23\n00:01:04.320 --> 00:01:06.000\nПерелистывайте с помощью джойстиков\n\n24\n00:01:06.000 --> 00:01:09.050\nдля просмотра всех режимов.\n\n25\n00:01:09.050 --> 00:01:11.330\nКак только пульт будет настроен,\n\n26\n00:01:11.330 --> 00:01:12.883\nвыберите кнопку «Готово».\n\n27\n00:01:15.820 --> 00:01:18.320\nВ данном случае, в проект не нужно добавлять блоки.\n\n28\n00:01:18.320 --> 00:01:19.800\nЗагрузите ваш проект на робота\n\n29\n00:01:19.800 --> 00:01:21.500\nи начните работу с пультом.\n\n","th":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator> สามารถใช้คอนโทรลเลอร์ </v>\n\n2\n00:00:01.800 --> 00:00:04.080\nเพื่อควบคุมหุ่นยนต์ V5 ของคุณจากระยะไกลได้\n\n3\n00:00:04.080 --> 00:00:06.593\nโดยไม่ต้องเพิ่มบล็อกการเขียนโปรแกรมใด ๆ\n\n4\n00:00:07.450 --> 00:00:09.430\nก่อนคุณจะตั้งค่าคอนโทรลเลอร์\n\n5\n00:00:09.430 --> 00:00:11.340\ndrive train และมอเตอร์ต่างๆ\n\n6\n00:00:11.340 --> 00:00:13.533\nต้องถูกเพิ่มไปยังโปรเจ็คของคุณแล้ว\n\n7\n00:00:14.510 --> 00:00:16.410\nในการกำหนดค่าคอนโทรลเลอร์อย่างรวดเร็ว\n\n8\n00:00:16.410 --> 00:00:18.370\nคุณสามารถใช้เทมเพลตตัวอย่าง\n\n9\n00:00:18.370 --> 00:00:21.203\nที่มีชุดการตั้งค่าระบบขับเคลื่อนและมอเตอร์ที่ที่ถูกตั้งค่าไว้แล้ว\n\n10\n00:00:22.890 --> 00:00:25.160\nตอนนี้เพิ่มตัวคอนโทรเลอร์ลงในโปรเจ็คของคุณ\n\n11\n00:00:25.160 --> 00:00:27.240\nในหน้าต่างอุปกรณ์\n\n12\n00:00:27.240 --> 00:00:31.053\nเปิดหน้าต่างอุปกรณ์และเลือกเพิ่มอุปกรณ์\n\n13\n00:00:32.130 --> 00:00:34.800\nจากนั้นเลือกคอนโทรเลอร์ controller\n\n14\n00:00:34.800 --> 00:00:37.460\nคุณสามารถกำหนดมอเตอร์ให้กับปุ่มต่างๆบนคอนโทรลเลอร์ได้\n\n15\n00:00:37.460 --> 00:00:39.373\nโดยเลือกปุ่มที่ต้องการใช้\n\n16\n00:00:40.600 --> 00:00:42.560\nจากนั้นเลือกปุ่มเดิมอีกครั้ง\n\n17\n00:00:42.560 --> 00:00:45.410\nเพื่อให้ครบการตั้งค่าของทุกมอเตอร์\n\n18\n00:00:45.410 --> 00:00:48.163\nใช้ลูกศรสีน้ำเงินเพื่อพลิกทิศทางของมอเตอร์\n\n19\n00:00:51.390 --> 00:00:54.790\nถัดไปคุณสามารถตั้งค่าโหมดการขับเคลื่อนของรถไฟขับเคลื่อนของหุ่นยนต์\n\n20\n00:00:54.790 --> 00:00:56.930\nโดยการเลือกจอยสติ๊ก\n\n21\n00:00:56.930 --> 00:00:59.310\nมีโหมดขับเคลื่อนสี่โหมด\n\n22\n00:00:59.310 --> 00:01:04.310\nอาร์เคดซ้าย, อาร์เคดขวา, แยกอาเขต และ รถถัง\n\n23\n00:01:04.320 --> 00:01:06.000\nจากนั้นเลือกจอยสติ๊กอีกครั้ง\n\n24\n00:01:06.000 --> 00:01:09.050\nเพื่อให้ครบการตั้งค่าของทุกมอเตอร์\n\n25\n00:01:09.050 --> 00:01:11.330\nเมื่อตั้งค่าคอนฟิกคอนโทรลเลอร์ของคุณแล้ว\n\n26\n00:01:11.330 --> 00:01:12.883\nจากนั้นเลือกปุ่ม Done.\n\n27\n00:01:15.820 --> 00:01:18.320\nหากโปรเจ็คของคุณไม่จำเป็นต้องเพิ่มบล็อกแล้ว\n\n28\n00:01:18.320 --> 00:01:19.800\nคุณสามารถดาว์โหลดโปรเจ็คของคุณ\n\n29\n00:01:19.800 --> 00:01:21.500\nและขอให้สนุกกับคอนโทรเลอร์\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Контролер використовують</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nдля віддаленого керування роботом V5\n\n3\n00:00:04.080 --> 00:00:06.593\nбез додавання блоків програмування.\n\n4\n00:00:07.450 --> 00:00:09.430\nПеред тим, як налаштовувати контролер,\n\n5\n00:00:09.430 --> 00:00:11.340\nтреба додати трансмісію і мотори\n\n6\n00:00:11.340 --> 00:00:13.533\nдо вашого проєкту.\n\n7\n00:00:14.510 --> 00:00:16.410\nДля швидкого налаштування контролера\n\n8\n00:00:16.410 --> 00:00:18.370\nвикористайте шаблон із прикладів,\n\n9\n00:00:18.370 --> 00:00:21.203\nякий має попередньо налаштовану трансмісію і мотори.\n\n10\n00:00:22.890 --> 00:00:25.160\nТепер додайте до проєкту контролер\n\n11\n00:00:25.160 --> 00:00:27.240\nчерез вікно пристроїв.\n\n12\n00:00:27.240 --> 00:00:31.053\nВідкрийте вікно пристроїв і натисніть \"Додати пристрій\".\n\n13\n00:00:32.130 --> 00:00:34.800\nДалі, виберіть контролер.\n\n14\n00:00:34.800 --> 00:00:37.460\nВи можете призначити мотори для кнопок контролера,\n\n15\n00:00:37.460 --> 00:00:39.373\nобравши кнопки для використання.\n\n16\n00:00:40.600 --> 00:00:42.560\nНатискайте ті ж самі кнопки,\n\n17\n00:00:42.560 --> 00:00:45.410\nщоби пройтися через усі доступні мотори.\n\n18\n00:00:45.410 --> 00:00:48.163\nВикористайте синю стрілку для зміни напрямку мотора.\n\n19\n00:00:51.390 --> 00:00:54.790\nДалі, можете встановити режим керування трансмісією робота,\n\n20\n00:00:54.790 --> 00:00:56.930\nвибравши джойстики.\n\n21\n00:00:56.930 --> 00:00:59.310\nЄ чотири режими керування:\n\n22\n00:00:59.310 --> 00:01:04.310\nлівий джойстик, правий джойстик, незалежні джойстики і танкове керування.\n\n23\n00:01:04.320 --> 00:01:06.000\nНатискайте на джойстики,\n\n24\n00:01:06.000 --> 00:01:09.050\nщоби пройтися через усі режими керування.\n\n25\n00:01:09.050 --> 00:01:11.330\nЩойно ви налаштуєте контролер,\n\n26\n00:01:11.330 --> 00:01:12.883\nнатисніть \"Готово\".\n\n27\n00:01:15.820 --> 00:01:18.320\nДодавати блоки у проєкт не потрібно.\n\n28\n00:01:18.320 --> 00:01:19.800\nПросто завантажте проєкт\n\n29\n00:01:19.800 --> 00:01:21.500\nі розважайтеся з контролером.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>Có thể sử dụng bộ điều khiển</v>\n\n2\n00:00:01.800 --> 00:00:04.080\nđể điều khiển rô bốt V5 của bạn từ xa\n\n3\n00:00:04.080 --> 00:00:06.593\nmà không cần phải thêm bất kỳ khối lập trình nào.\n\n4\n00:00:07.450 --> 00:00:09.430\nTrước khi bạn định cấu hình bộ điều khiển,\n\n5\n00:00:09.430 --> 00:00:11.340\nxe lửa và bất kỳ động cơ nào\n\n6\n00:00:11.340 --> 00:00:13.533\nphải được thêm vào dự án của bạn trước.\n\n7\n00:00:14.510 --> 00:00:16.410\nĐể nhanh chóng cấu hình bộ điều khiển,\n\n8\n00:00:16.410 --> 00:00:18.370\nbạn có thể sử dụng một mẫu ví dụ\n\n9\n00:00:18.370 --> 00:00:21.203\ncó một đầu tàu và động cơ được cấu hình sẵn.\n\n10\n00:00:22.890 --> 00:00:25.160\nBây giờ hãy thêm bộ điều khiển vào dự án của bạn\n\n11\n00:00:25.160 --> 00:00:27.240\nvới cửa sổ thiết bị.\n\n12\n00:00:27.240 --> 00:00:31.053\nMở cửa sổ thiết bị và chọn thêm thiết bị.\n\n13\n00:00:32.130 --> 00:00:34.800\nTiếp theo, chọn bộ điều khiển.\n\n14\n00:00:34.800 --> 00:00:37.460\nBạn có thể gán động cơ cho các nút trên bộ điều khiển\n\n15\n00:00:37.460 --> 00:00:39.373\nbằng cách chọn các nút để sử dụng.\n\n16\n00:00:40.600 --> 00:00:42.560\nTiếp tục chọn các nút tương tự\n\n17\n00:00:42.560 --> 00:00:45.410\nđể quay vòng qua tất cả các động cơ có sẵn.\n\n18\n00:00:45.410 --> 00:00:48.163\nSử dụng mũi tên màu xanh lam để lật hướng động cơ.\n\n19\n00:00:51.390 --> 00:00:54.790\nTiếp theo, bạn có thể đặt chế độ lái xe của robot lái xe\n\n20\n00:00:54.790 --> 00:00:56.930\nbằng cách chọn các cần điều khiển.\n\n21\n00:00:56.930 --> 00:00:59.310\nCó bốn chế độ truyền động có sẵn,\n\n22\n00:00:59.310 --> 00:01:04.310\narcade trái, arcade phải, chia arcade, xe tăng.\n\n23\n00:01:04.320 --> 00:01:06.000\nTiếp tục chọn các cần điều khiển\n\n24\n00:01:06.000 --> 00:01:09.050\nđể chuyển qua tất cả các chế độ ổ đĩa có sẵn.\n\n25\n00:01:09.050 --> 00:01:11.330\nSau khi cấu hình bộ điều khiển của bạn được thiết lập,\n\n26\n00:01:11.330 --> 00:01:12.883\nchọn nút hoàn tất.\n\n27\n00:01:15.820 --> 00:01:18.320\nKhông cần thêm khối vào dự án của bạn.\n\n28\n00:01:18.320 --> 00:01:19.800\nChỉ cần tải xuống dự án của bạn\n\n29\n00:01:19.800 --> 00:01:21.500\nvà vui chơi với bộ điều khiển của bạn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\ncrwdns95800:0crwdne95800:0\n\n2\n00:00:01.800 --> 00:00:04.080\ncrwdns95802:0crwdne95802:0\n\n3\n00:00:04.080 --> 00:00:06.593\ncrwdns95804:0crwdne95804:0\n\n4\n00:00:07.450 --> 00:00:09.430\ncrwdns95806:0crwdne95806:0\n\n5\n00:00:09.430 --> 00:00:11.340\ncrwdns95808:0crwdne95808:0\n\n6\n00:00:11.340 --> 00:00:13.533\ncrwdns95810:0crwdne95810:0\n\n7\n00:00:14.510 --> 00:00:16.410\ncrwdns95812:0crwdne95812:0\n\n8\n00:00:16.410 --> 00:00:18.370\ncrwdns95814:0crwdne95814:0\n\n9\n00:00:18.370 --> 00:00:21.203\ncrwdns95816:0crwdne95816:0\n\n10\n00:00:22.890 --> 00:00:25.160\ncrwdns95818:0crwdne95818:0\n\n11\n00:00:25.160 --> 00:00:27.240\ncrwdns95820:0crwdne95820:0\n\n12\n00:00:27.240 --> 00:00:31.053\ncrwdns95822:0crwdne95822:0\n\n13\n00:00:32.130 --> 00:00:34.800\ncrwdns95824:0crwdne95824:0\n\n14\n00:00:34.800 --> 00:00:37.460\ncrwdns95826:0crwdne95826:0\n\n15\n00:00:37.460 --> 00:00:39.373\ncrwdns95828:0crwdne95828:0\n\n16\n00:00:40.600 --> 00:00:42.560\ncrwdns95830:0crwdne95830:0\n\n17\n00:00:42.560 --> 00:00:45.410\ncrwdns95832:0crwdne95832:0\n\n18\n00:00:45.410 --> 00:00:48.163\ncrwdns95834:0crwdne95834:0\n\n19\n00:00:51.390 --> 00:00:54.790\ncrwdns95836:0crwdne95836:0\n\n20\n00:00:54.790 --> 00:00:56.930\ncrwdns95838:0crwdne95838:0\n\n21\n00:00:56.930 --> 00:00:59.310\ncrwdns95840:0crwdne95840:0\n\n22\n00:00:59.310 --> 00:01:04.310\ncrwdns95842:0crwdne95842:0\n\n23\n00:01:04.320 --> 00:01:06.000\ncrwdns95844:0crwdne95844:0\n\n24\n00:01:06.000 --> 00:01:09.050\ncrwdns95846:0crwdne95846:0\n\n25\n00:01:09.050 --> 00:01:11.330\ncrwdns95848:0crwdne95848:0\n\n26\n00:01:11.330 --> 00:01:12.883\ncrwdns95850:0crwdne95850:0\n\n27\n00:01:15.820 --> 00:01:18.320\ncrwdns95852:0crwdne95852:0\n\n28\n00:01:18.320 --> 00:01:19.800\ncrwdns95854:0crwdne95854:0\n\n29\n00:01:19.800 --> 00:01:21.500\ncrwdns95856:0crwdne95856:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.520 --> 00:00:01.800\n<v Narrator>遥控器可用于</v>\n\n2\n00:00:01.800 --> 00:00:04.080\n远程驱动您的V5机器人\n\n3\n00:00:04.080 --> 00:00:06.593\n无需添加任何编程指令块。\n\n4\n00:00:07.450 --> 00:00:09.430\n设置遥控器前，\n\n5\n00:00:09.430 --> 00:00:11.340\n底盘和任何电机\n\n6\n00:00:11.340 --> 00:00:13.533\n必须首先添加到程序中去。\n\n7\n00:00:14.510 --> 00:00:16.410\n欲快速设置遥控器，\n\n8\n00:00:16.410 --> 00:00:18.370\n你可以用带有预置\n\n9\n00:00:18.370 --> 00:00:21.203\n有一个预配置的底盘和电机。\n\n10\n00:00:22.890 --> 00:00:25.160\n现在添加一个遥控器到程序中\n\n11\n00:00:25.160 --> 00:00:27.240\n添加一个遥控器到程序中。\n\n12\n00:00:27.240 --> 00:00:31.053\n打开“设备”窗口并选择“添加设备”。\n\n13\n00:00:32.130 --> 00:00:34.800\n下一步，选择遥控器。\n\n14\n00:00:34.800 --> 00:00:37.460\n你可以把电机指配给遥控器上对应的按钮。\n\n15\n00:00:37.460 --> 00:00:39.373\n只要选择合适的按钮即可。\n\n16\n00:00:40.600 --> 00:00:42.560\n继续点击同一按钮\n\n17\n00:00:42.560 --> 00:00:45.410\n来翻选所有待选的电机。\n\n18\n00:00:45.410 --> 00:00:48.163\n用蓝色箭头反转电机转向。\n\n19\n00:00:51.390 --> 00:00:54.790\n接下来，您可以设定机器人底盘的驱动模式\n\n20\n00:00:54.790 --> 00:00:56.930\n你可以改变机器人操控模式。\n\n21\n00:00:56.930 --> 00:00:59.310\n操控模式有四种，\n\n22\n00:00:59.310 --> 00:01:04.310\n左单杆，右单杆，分离单杆，双杆。\n\n23\n00:01:04.320 --> 00:01:06.000\n连续点击操纵杆图标\n\n24\n00:01:06.000 --> 00:01:09.050\n可以翻选全部操控模式。\n\n25\n00:01:09.050 --> 00:01:11.330\n完成遥控器设置后，\n\n26\n00:01:11.330 --> 00:01:12.883\n选择完成按钮。\n\n27\n00:01:15.820 --> 00:01:18.320\n无需往程序中加入任何指令块，\n\n28\n00:01:18.320 --> 00:01:19.800\n简单地下载您的程序\n\n29\n00:01:19.800 --> 00:01:21.500\n就可以开始玩遥控了。\n\n"}},{"thumb":"V5_Tutorial_configureVision.jpg","mov":"V5_Blocks_ConfigVisionSensor_V2","description":"Configuring a Vision Sensor","filter":"","placeholder":false,"vimeo":"475898354","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->In a V5 blocks project,</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nyou can configure your vision sensor\n\n3\n00:00:03.820 --> 00:00:06.440\nto detect objects of different colors.\n\n4\n00:00:06.440 --> 00:00:10.300\nFirst, connect the micro-USB cable from your computer\n\n5\n00:00:10.300 --> 00:00:12.113\nto the bottom of the vision sensor.\n\n6\n00:00:13.300 --> 00:00:17.353\nNext, back in VEXcode V5, open the Devices window.\n\n7\n00:00:19.840 --> 00:00:24.840\nNow, select Add a device and choose Vision.\n\n8\n00:00:27.360 --> 00:00:29.940\nLastly, select which port the vision sensor\n\n9\n00:00:29.940 --> 00:00:33.170\nis connected to on the VEX V5 brain.\n\n10\n00:00:33.170 --> 00:00:35.480\nThe vision device screen appears.\n\n11\n00:00:35.480 --> 00:00:39.460\nFrom here, you change the name of your vision sensor.\n\n12\n00:00:39.460 --> 00:00:42.090\nYou can also configure your vision sensor.\n\n13\n00:00:42.090 --> 00:00:45.273\nSelect the configure button to open the vision utility.\n\n14\n00:00:48.580 --> 00:00:50.330\nInside of the vision utility,\n\n15\n00:00:50.330 --> 00:00:53.400\nyou will see a live feed from the vision sensor.\n\n16\n00:00:53.400 --> 00:00:55.090\nThe live feed is used to allow you\n\n17\n00:00:55.090 --> 00:00:59.460\nto configure the vision sensor to detect different colors.\n\n18\n00:00:59.460 --> 00:01:01.820\nTo configure a color to be detected,\n\n19\n00:01:01.820 --> 00:01:06.020\nfirst place or hold an object in front of the vision sensor,\n\n20\n00:01:06.020 --> 00:01:07.870\nthen select the Freeze button\n\n21\n00:01:07.870 --> 00:01:09.523\nto keep the image captured.\n\n22\n00:01:12.270 --> 00:01:15.060\nNext, select and drag the box around the color\n\n23\n00:01:15.060 --> 00:01:18.620\nyou wish to configure the vision sensor to detect.\n\n24\n00:01:18.620 --> 00:01:20.970\nNow, select one of the Set bar\n\n25\n00:01:20.970 --> 00:01:23.050\non the right of the vision utility\n\n26\n00:01:23.050 --> 00:01:25.400\nto store this color in a signature.\n\n27\n00:01:25.400 --> 00:01:27.910\nWhenever the vision sensor captures a color,\n\n28\n00:01:27.910 --> 00:01:31.490\nall of the color's properties are stored as a signature.\n\n29\n00:01:31.490 --> 00:01:33.180\nThe vision sensor is able to store\n\n30\n00:01:33.180 --> 00:01:35.550\nup to seven different signatures.\n\n31\n00:01:35.550 --> 00:01:37.700\nLastly, you can rename your signature\n\n32\n00:01:37.700 --> 00:01:40.823\nin order to identify each signature in your project.\n\n33\n00:01:45.020 --> 00:01:47.630\nOnce you are done configuring the vision sensor,\n\n34\n00:01:47.630 --> 00:01:49.603\nyou can close the vision utility.\n\n35\n00:01:50.690 --> 00:01:52.440\nAlso, remember to select Done,\n\n36\n00:01:52.440 --> 00:01:53.843\nin the devices window.\n\n37\n00:01:57.640 --> 00:02:00.733\nVision sensor blocks will now appear in the tool box.\n\n38\n00:02:02.120 --> 00:02:05.263\nYour vision sensor is now configured and ready to use.\n\n","ar":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->في مشروع V5 للبرمجة،</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nيمكنك ضبط إعدادات مستشعر الرؤية\n\n3\n00:00:03.820 --> 00:00:06.440\nللكشف عن أجسام لها ألوان مختلفة.\n\n4\n00:00:06.440 --> 00:00:10.300\nأولاً، قم بتوصيل سلك التوصيل micro-USB من جهاز الحاسوب الخاص بك\n\n5\n00:00:10.300 --> 00:00:12.113\nإلى أسفل مستشعر الرؤية.\n\n6\n00:00:13.300 --> 00:00:17.353\nبعد ذلك في VEXcode V5، قم بفتح نافذة الأجهزة.\n\n7\n00:00:19.840 --> 00:00:24.840\nالآن حدد ''إضافة جهاز'' واختر الرؤية.\n\n8\n00:00:27.360 --> 00:00:29.940\nأخيرا اختر المنفذ الذي المتصل بمستشعر الرؤية\n\n9\n00:00:29.940 --> 00:00:33.170\nإلى عقل VEX V5.\n\n10\n00:00:33.170 --> 00:00:35.480\nظهور شاشة جهاز الرؤية.\n\n11\n00:00:35.480 --> 00:00:39.460\nمن هنا، يمكنك تغيير اسم مستشعر الرؤية الخاص بك.\n\n12\n00:00:39.460 --> 00:00:42.090\nيمكنك أيضاً ضبط إعدادات مستشعر الرؤية الخاص بك.\n\n13\n00:00:42.090 --> 00:00:45.273\nإضغط زر الاعدادات لفتح أداة خدمات الرؤية.\n\n14\n00:00:48.580 --> 00:00:50.330\nداخل نطاق خدمات الرؤية\n\n15\n00:00:50.330 --> 00:00:53.400\nسوف تشاهد بث مباشر من مستشعر الرؤية.\n\n16\n00:00:53.400 --> 00:00:55.090\nيتم استخدام البث المباشر للسماح لك\n\n17\n00:00:55.090 --> 00:00:59.460\nلتحديد مستشعر الرؤية لاكتشاف ألوان مختلفة.\n\n18\n00:00:59.460 --> 00:01:01.820\nلضبط لون ليتم تحديده\n\n19\n00:01:01.820 --> 00:01:06.020\nضع أو أمسك جسم أمام مستشعر الرؤية\n\n20\n00:01:06.020 --> 00:01:07.870\nثم إضغط زر التجميد\n\n21\n00:01:07.870 --> 00:01:09.523\nلإبقاء الصورة ملتقطة.\n\n22\n00:01:12.270 --> 00:01:15.060\nبعد ذلك, إسحب مربع حول اللون\n\n23\n00:01:15.060 --> 00:01:18.620\nترغب في ضبط مستشعر الرؤية للكشف.\n\n24\n00:01:18.620 --> 00:01:20.970\nالأن إختر أحد أزرار الضبط\n\n25\n00:01:20.970 --> 00:01:23.050\nعلى الجانب الأيمن من خدمات الرؤية\n\n26\n00:01:23.050 --> 00:01:25.400\nلتخزين هذا اللون إلى عينات.\n\n27\n00:01:25.400 --> 00:01:27.910\nكلما رصد مستشعر الرؤية لونًا،\n\n28\n00:01:27.910 --> 00:01:31.490\nجميع خصائص الألوان تخزن كعينات.\n\n29\n00:01:31.490 --> 00:01:33.180\nمستشعر الرؤية قادر على تخزين\n\n30\n00:01:33.180 --> 00:01:35.550\nما يصل إلى سبعة عينات مختلفة.\n\n31\n00:01:35.550 --> 00:01:37.700\nأخيرا، يمكنك إعادة تسمية العينة الخاصة بك\n\n32\n00:01:37.700 --> 00:01:40.823\nمن أجل التعرف على كل عينة في مشروعك.\n\n33\n00:01:45.020 --> 00:01:47.630\nبمجرد الانتهاء من إعداد مستشعر الرؤية،\n\n34\n00:01:47.630 --> 00:01:49.603\nيمكنك إغلاق أداة الرؤية.\n\n35\n00:01:50.690 --> 00:01:52.440\nأيضاً لا تنسى أن تضغط على إنهاء\n\n36\n00:01:52.440 --> 00:01:53.843\nفي نافذة الأجهزة.\n\n37\n00:01:57.640 --> 00:02:00.733\nستظهر الآن مقاطع استشعار الرؤية في صندوق إعدادات.\n\n38\n00:02:02.120 --> 00:02:05.263\nمستشعر الرؤية الخاص بك مهيأ و جاهز للاستخدام.\n\n","cs":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->V blokovém projektu V5</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nmůžeš nastavit svoji kameru tak,\n\n3\n00:00:03.820 --> 00:00:06.440\naby vnímala objekty různých barev.\n\n4\n00:00:06.440 --> 00:00:10.300\nNejprve připoj micro USB kabel ze tvého počítače\n\n5\n00:00:10.300 --> 00:00:12.113\nke spodku své kamery.\n\n6\n00:00:13.300 --> 00:00:17.353\nPotom zpátky ve VEXcode V5 otevři okno Zařízení.\n\n7\n00:00:19.840 --> 00:00:24.840\nNyní vyber Přidat zařízení a zvol Kamera.\n\n8\n00:00:27.360 --> 00:00:29.940\nNakonec vyber, k jakému portu je kamera\n\n9\n00:00:29.940 --> 00:00:33.170\npřipojená na VEX V5 Mozku.\n\n10\n00:00:33.170 --> 00:00:35.480\nObjeví se obrazovka kamery.\n\n11\n00:00:35.480 --> 00:00:39.460\nOdtud můžeš změnit název své kamery.\n\n12\n00:00:39.460 --> 00:00:42.090\nSvou kameru můžeš také nastavit.\n\n13\n00:00:42.090 --> 00:00:45.273\nVyber tlačítko Nastavit pro otevření Nastavení kamery.\n\n14\n00:00:48.580 --> 00:00:50.330\nUvnitř nastavení kamery\n\n15\n00:00:50.330 --> 00:00:53.400\nuvidíš živý přenos ze své kamery.\n\n16\n00:00:53.400 --> 00:00:55.090\nŽivý přenos se používá k umožnění\n\n17\n00:00:55.090 --> 00:00:59.460\nnastavení kamery pro detekci různých barev.\n\n18\n00:00:59.460 --> 00:01:01.820\nPro nastavení barvy, která má být detekována,\n\n19\n00:01:01.820 --> 00:01:06.020\nnejprve polož, nebo podrž objekt před kamerou,\n\n20\n00:01:06.020 --> 00:01:07.870\npotom vyber tlačítko Zmrazit\n\n21\n00:01:07.870 --> 00:01:09.523\npro uchování zachyceného obrázku.\n\n22\n00:01:12.270 --> 00:01:15.060\nDále vyber a přetáhni pole okolo barvy,\n\n23\n00:01:15.060 --> 00:01:18.620\nkterou chceš nastavit, aby kamera detekovala.\n\n24\n00:01:18.620 --> 00:01:20.970\nNyní vyber jednu z nastavovacích lišt\n\n25\n00:01:20.970 --> 00:01:23.050\nna pravé straně Nastavení kamery\n\n26\n00:01:23.050 --> 00:01:25.400\npro uložení této barvy v signatuře.\n\n27\n00:01:25.400 --> 00:01:27.910\nKdykoliv kamera zachytí nějakou barvu,\n\n28\n00:01:27.910 --> 00:01:31.490\njsou všechny její vlastnosti uloženy jako signatura.\n\n29\n00:01:31.490 --> 00:01:33.180\nKamera je schopná uchovat\n\n30\n00:01:33.180 --> 00:01:35.550\naž sedm různých signatur.\n\n31\n00:01:35.550 --> 00:01:37.700\nNakonec můžeš svou signaturu přejmenovat,\n\n32\n00:01:37.700 --> 00:01:40.823\npro identifikaci každé signatury ve tvém projektu.\n\n33\n00:01:45.020 --> 00:01:47.630\nJakmile dokončíš nastavení kamery,\n\n34\n00:01:47.630 --> 00:01:49.603\nmůžeš zavřít okno Nastavení kamery.\n\n35\n00:01:50.690 --> 00:01:52.440\nTaké nezapomeň vybrat Hotovo\n\n36\n00:01:52.440 --> 00:01:53.843\nv okně Zařízení.\n\n37\n00:01:57.640 --> 00:02:00.733\nBloky kamery se nyní objeví na panelu nástrojů.\n\n38\n00:02:02.120 --> 00:02:05.263\nTvá kamera je nyní nastavená a připravená k použití.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->En un proyecto de V5 Blocks (bloques),</v>\n\n2\n00:00:02.060 --> 00:00:03.820\npuede configurar su sensor de visión\n\n3\n00:00:03.820 --> 00:00:06.440\na detectar objetos de diferentes colores.\n\n4\n00:00:06.440 --> 00:00:10.300\nPrimero, conecte el cable MicroUSB desde su computadora\n\n5\n00:00:10.300 --> 00:00:12.113\na la parte inferior del sensor de visión.\n\n6\n00:00:13.300 --> 00:00:17.353\nA continuación en VEXcode Control por Conductor5, abra la ventana Dispositivos.\n\n7\n00:00:19.840 --> 00:00:24.840\nAhora seleccione Agregar un dispositivo y elege Visión.\n\n8\n00:00:27.360 --> 00:00:29.940\nPor último, seleccione el puerto al que está conectado el sensor de visión\n\n9\n00:00:29.940 --> 00:00:33.170\nen el VEX V5 Brain.\n\n10\n00:00:33.170 --> 00:00:35.480\nAparece la pantalla del dispositivo visión.\n\n11\n00:00:35.480 --> 00:00:39.460\nDesde aquí, puede cambiar el nombre de su Vision Sensor.\n\n12\n00:00:39.460 --> 00:00:42.090\nTambién puede configurar su Vision Sensor.\n\n13\n00:00:42.090 --> 00:00:45.273\nSeleccione el botón \"Configurar\" para abrir la Utilidad de Visión.\n\n14\n00:00:48.580 --> 00:00:50.330\nDentro de la Utilidad de Visión,\n\n15\n00:00:50.330 --> 00:00:53.400\nverás una transmisión en vivo del sensor de visión.\n\n16\n00:00:53.400 --> 00:00:55.090\nLa transmisión en vivo se utiliza para permitirle\n\n17\n00:00:55.090 --> 00:00:59.460\nconfigurar el sensor de visión para detectar diferentes colores.\n\n18\n00:00:59.460 --> 00:01:01.820\nPara configurar un color a ser detectado,\n\n19\n00:01:01.820 --> 00:01:06.020\nprimero coloca o mantiene un objeto delante del Vision Sensor,\n\n20\n00:01:06.020 --> 00:01:07.870\nluego seleccione el botón congelar\n\n21\n00:01:07.870 --> 00:01:09.523\npara mantener la imagen capturada.\n\n22\n00:01:12.270 --> 00:01:15.060\nA continuación, selecciona y arrastra un recuadro alrededor del color\n\n23\n00:01:15.060 --> 00:01:18.620\nque desea configurar el sensor de visión para detectar.\n\n24\n00:01:18.620 --> 00:01:20.970\nAhora, selecciona uno de los botones \"Set\"\n\n25\n00:01:20.970 --> 00:01:23.050\nen el lado derecho de la Utilidad de Visión\n\n26\n00:01:23.050 --> 00:01:25.400\npara guardar este color en una firma.\n\n27\n00:01:25.400 --> 00:01:27.910\nSiempre que el Vision Sensor capture un color,\n\n28\n00:01:27.910 --> 00:01:31.490\ntodas las propiedades de colores se almacenan como una firma.\n\n29\n00:01:31.490 --> 00:01:33.180\nEl sensor de visión puede almacenar hasta\n\n30\n00:01:33.180 --> 00:01:35.550\nsiete firmas diferentes.\n\n31\n00:01:35.550 --> 00:01:37.700\nPor último, puede renombrar su firma\n\n32\n00:01:37.700 --> 00:01:40.823\npara identificar cada firma en su proyecto.\n\n33\n00:01:45.020 --> 00:01:47.630\nUna vez que haya configurado el Vision Sensor,\n\n34\n00:01:47.630 --> 00:01:49.603\npuede cerrar la Utilidad de Vision.\n\n35\n00:01:50.690 --> 00:01:52.440\nTambién, recuerde seleccionar Hecho,\n\n36\n00:01:52.440 --> 00:01:53.843\nen la ventana de dispositivos.\n\n37\n00:01:57.640 --> 00:02:00.733\nLos bloques del Vision Sensor ahora aparecerán en la caja de herramientas.\n\n38\n00:02:02.120 --> 00:02:05.263\nSu Vision Sensor ahora está configurado y listo para usar.\n\n","es":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->En un proyecto de V5 Blocks (bloques),</v>\n\n2\n00:00:02.060 --> 00:00:03.820\npuede configurar su sensor de visión\n\n3\n00:00:03.820 --> 00:00:06.440\na detectar objetos de diferentes colores.\n\n4\n00:00:06.440 --> 00:00:10.300\nPrimero, conecte el cable MicroUSB desde su computadora\n\n5\n00:00:10.300 --> 00:00:12.113\na la parte inferior del sensor de visión.\n\n6\n00:00:13.300 --> 00:00:17.353\nA continuación en VEXcode Control por Conductor5, abra la ventana Dispositivos.\n\n7\n00:00:19.840 --> 00:00:24.840\nAhora seleccione Agregar un dispositivo y elege Visión.\n\n8\n00:00:27.360 --> 00:00:29.940\nPor último, seleccione el puerto al que está conectado el sensor de visión\n\n9\n00:00:29.940 --> 00:00:33.170\nen el VEX V5 Brain.\n\n10\n00:00:33.170 --> 00:00:35.480\nAparece la pantalla del dispositivo visión.\n\n11\n00:00:35.480 --> 00:00:39.460\nDesde aquí, puede cambiar el nombre de su Vision Sensor.\n\n12\n00:00:39.460 --> 00:00:42.090\nTambién puede configurar su Vision Sensor.\n\n13\n00:00:42.090 --> 00:00:45.273\nSeleccione el botón \"Configurar\" para abrir la Utilidad de Visión.\n\n14\n00:00:48.580 --> 00:00:50.330\nDentro de la Utilidad de Visión,\n\n15\n00:00:50.330 --> 00:00:53.400\nverás una transmisión en vivo del sensor de visión.\n\n16\n00:00:53.400 --> 00:00:55.090\nLa transmisión en vivo se utiliza para permitirle\n\n17\n00:00:55.090 --> 00:00:59.460\nconfigurar el sensor de visión para detectar diferentes colores.\n\n18\n00:00:59.460 --> 00:01:01.820\nPara configurar un color a ser detectado,\n\n19\n00:01:01.820 --> 00:01:06.020\nprimero coloca o mantiene un objeto delante del Vision Sensor,\n\n20\n00:01:06.020 --> 00:01:07.870\nluego seleccione el botón congelar\n\n21\n00:01:07.870 --> 00:01:09.523\npara mantener la imagen capturada.\n\n22\n00:01:12.270 --> 00:01:15.060\nA continuación, selecciona y arrastra un recuadro alrededor del color\n\n23\n00:01:15.060 --> 00:01:18.620\nque desea configurar el sensor de visión para detectar.\n\n24\n00:01:18.620 --> 00:01:20.970\nAhora, selecciona uno de los botones \"Set\"\n\n25\n00:01:20.970 --> 00:01:23.050\nen el lado derecho de la Utilidad de Visión\n\n26\n00:01:23.050 --> 00:01:25.400\npara guardar este color en una firma.\n\n27\n00:01:25.400 --> 00:01:27.910\nSiempre que el Vision Sensor capture un color,\n\n28\n00:01:27.910 --> 00:01:31.490\ntodas las propiedades de colores se almacenan como una firma.\n\n29\n00:01:31.490 --> 00:01:33.180\nEl sensor de visión puede almacenar hasta\n\n30\n00:01:33.180 --> 00:01:35.550\nsiete firmas diferentes.\n\n31\n00:01:35.550 --> 00:01:37.700\nPor último, puede renombrar su firma\n\n32\n00:01:37.700 --> 00:01:40.823\npara identificar cada firma en su proyecto.\n\n33\n00:01:45.020 --> 00:01:47.630\nUna vez que haya configurado el Vision Sensor,\n\n34\n00:01:47.630 --> 00:01:49.603\npuede cerrar la Utilidad de Vision.\n\n35\n00:01:50.690 --> 00:01:52.440\nTambién, recuerde seleccionar Hecho,\n\n36\n00:01:52.440 --> 00:01:53.843\nen la ventana de dispositivos.\n\n37\n00:01:57.640 --> 00:02:00.733\nLos bloques del Vision Sensor ahora aparecerán en la caja de herramientas.\n\n38\n00:02:02.120 --> 00:02:05.263\nSu Vision Sensor ahora está configurado y listo para usar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->V5 blokki-ohjelmassa</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nvoit määritellä Vision -kameran niin\n\n3\n00:00:03.820 --> 00:00:06.440\nettä tunnistat eri väriset esineet.\n\n4\n00:00:06.440 --> 00:00:10.300\nEnsiksi yhdistä MicroUSB -kaapeli tietokoneesta\n\n5\n00:00:10.300 --> 00:00:12.113\nVision -kameran pohjaan.\n\n6\n00:00:13.300 --> 00:00:17.353\nSeuraavaksi palaa VEXcode IQ Blocks -ohjelmaan ja avaa Laitteet -ikkuna.\n\n7\n00:00:19.840 --> 00:00:24.840\nValitse Lisää laite-painonappi ja valitse Vision -kamera.\n\n8\n00:00:27.360 --> 00:00:29.940\nLopuksi valitse Vision -kameran\n\n9\n00:00:29.940 --> 00:00:33.170\nportti VEX V5 -aivoissa.\n\n10\n00:00:33.170 --> 00:00:35.480\nVision -kameran Asetukset-ikkuna tulee näkyviin.\n\n11\n00:00:35.480 --> 00:00:39.460\nIkkunasta voit määritellä Vision -kameran nimen.\n\n12\n00:00:39.460 --> 00:00:42.090\nVoit myös määritellä Vision Kameran käyttöä.\n\n13\n00:00:42.090 --> 00:00:45.273\nValitse Määritä-painike Vision -kameran asetukset -ikkunasta.\n\n14\n00:00:48.580 --> 00:00:50.330\nVision Utility -ikkunassa\n\n15\n00:00:50.330 --> 00:00:53.400\nnäet kameran kuvaaman livestream-kuvan.\n\n16\n00:00:53.400 --> 00:00:55.090\nLivestream kuvasta voit\n\n17\n00:00:55.090 --> 00:00:59.460\nmäärittää Vision -kameran tunnistamaan erivärisiä esineitä.\n\n18\n00:00:59.460 --> 00:01:01.820\nJotta voit määritellä värit joita havaitaan,\n\n19\n00:01:01.820 --> 00:01:06.020\naseta esine kameran eteen\n\n20\n00:01:06.020 --> 00:01:07.870\nja valitse kuvan jäädytys Freeze-painikeella\n\n21\n00:01:07.870 --> 00:01:09.523\nettä esineen väri voidaan helposti kaapata.\n\n22\n00:01:12.270 --> 00:01:15.060\nSeuraavaksi vedä/maalaa hiiren vasemmalla laatikko halutun esineen värialueen ympärille\n\n23\n00:01:15.060 --> 00:01:18.620\njonka haluat Vision -kameran havaitsevan.\n\n24\n00:01:18.620 --> 00:01:20.970\nValitse nyt yksi valintaruutu Set-palkista\n\n25\n00:01:20.970 --> 00:01:23.050\nVision Utility-ikkunan oikealla puolella\n\n26\n00:01:23.050 --> 00:01:25.400\ntallentaaksesi halutun esineen värin nimetyksi merkiksi.\n\n27\n00:01:25.400 --> 00:01:27.910\nKun Vision -kameraan asettaa SET -ruudun valinnalla värin,\n\n28\n00:01:27.910 --> 00:01:31.490\nkaikki värin eri ominaisuudet tallennetaan nimettyyn merkkiin.\n\n29\n00:01:31.490 --> 00:01:33.180\nVision -kamerassa voi kiinnittää\n\n30\n00:01:33.180 --> 00:01:35.550\nseitsemän eri merkattua väriä.\n\n31\n00:01:35.550 --> 00:01:37.700\nLopuksi voit uudelleen nimetä merkin\n\n32\n00:01:37.700 --> 00:01:40.823\njotta ohjelmassasi voit erottaa merkit toisistaan.\n\n33\n00:01:45.020 --> 00:01:47.630\nKun olet määrittänyt Vision -kameran havaitsemat värit loppuun\n\n34\n00:01:47.630 --> 00:01:49.603\nvoit sulkea Vision Utility -ikkunan.\n\n35\n00:01:50.690 --> 00:01:52.440\nJa valitse Tehty-painike tallentamaan esinemääritykset\n\n36\n00:01:52.440 --> 00:01:53.843\nVision kameran asetukset -ikkunasta.\n\n37\n00:01:57.640 --> 00:02:00.733\nSaat Vision -kameran blokit näkyviin ohjemoinnin työkaluihin.\n\n38\n00:02:02.120 --> 00:02:05.263\nVision -kamera on nyt määritelty ja valmis käyttöön.\n\n","fr":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->Dans un projet V5 Blocs,</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nvous pouvez configurer votre Capteur de Vision\n\n3\n00:00:03.820 --> 00:00:06.440\npour détecter des objets de différentes couleurs.\n\n4\n00:00:06.440 --> 00:00:10.300\nTout d'abord, connectez le câble MicroUSB depuis votre ordinateur\n\n5\n00:00:10.300 --> 00:00:12.113\nvers le bas du Capteur de Vision.\n\n6\n00:00:13.300 --> 00:00:17.353\nEnsuite, de retour dans VEXcode V5, ouvrez la fenêtre Appareils.\n\n7\n00:00:19.840 --> 00:00:24.840\nMaintenant, sélectionnez \"Ajouter un appareil\" et choisissez \"Vision\".\n\n8\n00:00:27.360 --> 00:00:29.940\nEnfin, sélectionnez le port sur lequel le capteur de vision\n\n9\n00:00:29.940 --> 00:00:33.170\nest connecté au Cerveau VEX V5.\n\n10\n00:00:33.170 --> 00:00:35.480\nL'écran de l'appareil Vision s'affiche.\n\n11\n00:00:35.480 --> 00:00:39.460\nÀ partir d'ici, vous pouvez changer le nom de votre Capteur de Vision.\n\n12\n00:00:39.460 --> 00:00:42.090\nVous pouvez également configurer votre Capteur de Vision.\n\n13\n00:00:42.090 --> 00:00:45.273\nSélectionnez le bouton \"Configurer\" pour ouvrir l'Utilitaire Vision.\n\n14\n00:00:48.580 --> 00:00:50.330\nÀ partir de l'Utilitaire Vision,\n\n15\n00:00:50.330 --> 00:00:53.400\nvous verrez un flux en direct du Capteur de Vision.\n\n16\n00:00:53.400 --> 00:00:55.090\nLe flux en direct est utilisé pour vous permettre\n\n17\n00:00:55.090 --> 00:00:59.460\nafin de configurer le capteur de vision pour détecter différentes couleurs.\n\n18\n00:00:59.460 --> 00:01:01.820\nPour configurer une couleur à détecter,\n\n19\n00:01:01.820 --> 00:01:06.020\nplacez ou maintenez tout d'abord un objet devant le Capteur de Vision,\n\n20\n00:01:06.020 --> 00:01:07.870\npuis sélectionnez le bouton \"Geler\"\n\n21\n00:01:07.870 --> 00:01:09.523\npour fixer l'image capturée.\n\n22\n00:01:12.270 --> 00:01:15.060\nEnsuite, sélectionnez et faites glisser une boîte autour de la couleur\n\n23\n00:01:15.060 --> 00:01:18.620\nque vous voulez faire détecter par le Capteur de Vision.\n\n24\n00:01:18.620 --> 00:01:20.970\nMaintenant, sélectionnez l'un des boutons \"Définir\"\n\n25\n00:01:20.970 --> 00:01:23.050\nsur le côté droit de l'Utilitaire Vision\n\n26\n00:01:23.050 --> 00:01:25.400\npour stocker cette couleur dans une signature.\n\n27\n00:01:25.400 --> 00:01:27.910\nÀ chaque fois que le Capteur de Vision capture une couleur,\n\n28\n00:01:27.910 --> 00:01:31.490\ntoutes les propriétés de la couleur sont stockées en tant que signature.\n\n29\n00:01:31.490 --> 00:01:33.180\nLe Capteur de Vision est capable de stocker\n\n30\n00:01:33.180 --> 00:01:35.550\njusqu'à 7 signatures différentes.\n\n31\n00:01:35.550 --> 00:01:37.700\nEnfin, vous pouvez renommer votre signature\n\n32\n00:01:37.700 --> 00:01:40.823\nafin d'identifier chaque signature de votre projet.\n\n33\n00:01:45.020 --> 00:01:47.630\nUne fois que vous avez terminé la configuration du Capteur de Vision,\n\n34\n00:01:47.630 --> 00:01:49.603\nvous pouvez fermer l'Utilitaire Vision.\n\n35\n00:01:50.690 --> 00:01:52.440\nDe plus, n'oubliez pas de sélectionner \"Terminé\",\n\n36\n00:01:52.440 --> 00:01:53.843\ndepuis la fenêtre des appareils.\n\n37\n00:01:57.640 --> 00:02:00.733\nLes blocs du Capteur de Vision apparaîtront maintenant dans la boîte à outils.\n\n38\n00:02:02.120 --> 00:02:05.263\nVotre Capteur de Vision est maintenant configuré et prêt à l'emploi.\n\n","ko":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->V5 블록 프로젝트에서는</v>\n\n2\n00:00:02.060 --> 00:00:03.820\n다양한 색상의 물체를 감지하도록\n\n3\n00:00:03.820 --> 00:00:06.440\n비전 센서를 구성할 수 있습니다.\n\n4\n00:00:06.440 --> 00:00:10.300\n먼저 컴퓨터의 마이크로 USB 케이블을\n\n5\n00:00:10.300 --> 00:00:12.113\n비전 센서 하단에 연결합니다.\n\n6\n00:00:13.300 --> 00:00:17.353\n그리고 다시 VEXcode V5에서 기기 창을 엽니다.\n\n7\n00:00:19.840 --> 00:00:24.840\n이제 \"기기 추가\"에서 비전 센서를 선택합니다.\n\n8\n00:00:27.360 --> 00:00:29.940\n마지막으로 비전 센서가 연결된 포트를\n\n9\n00:00:29.940 --> 00:00:33.170\nVEX V5 브레인에서 선택하세요.\n\n10\n00:00:33.170 --> 00:00:35.480\n비전 센서 기기 화면이 나타납니다.\n\n11\n00:00:35.480 --> 00:00:39.460\n여기서 비전 센서의 이름을 바꿉니다.\n\n12\n00:00:39.460 --> 00:00:42.090\n비전 센서를 구성할 수도 있습니다.\n\n13\n00:00:42.090 --> 00:00:45.273\n\"구성 버튼을 선택하고 비전 센서 유틸리티를 여십시오.\n\n14\n00:00:48.580 --> 00:00:50.330\n비전 센서 유틸리티에서는\n\n15\n00:00:50.330 --> 00:00:53.400\n비전 센서의 실시간 피드를 볼 수 있습니다.\n\n16\n00:00:53.400 --> 00:00:55.090\n실시간 피드는\n\n17\n00:00:55.090 --> 00:00:59.460\n다양한 색상을 감지하도록 비전 센서를 구성하는 데 사용됩니다.\n\n18\n00:00:59.460 --> 00:01:01.820\n감지할 색상을 구성하기 위해\n\n19\n00:01:01.820 --> 00:01:06.020\n먼저 물체를 비전 센서 앞에 놓고\n\n20\n00:01:06.020 --> 00:01:07.870\n정지 버튼을 눌러\n\n21\n00:01:07.870 --> 00:01:09.523\n이미지를 캡처하세요.\n\n22\n00:01:12.270 --> 00:01:15.060\n그런 다음 상자를 선택하여 비전 센서가 감지하게 구성하고 싶은\n\n23\n00:01:15.060 --> 00:01:18.620\n색상으로 끌어다 놓으세요.\n\n24\n00:01:18.620 --> 00:01:20.970\n이제 비전 센서 유틸리티의\n\n25\n00:01:20.970 --> 00:01:23.050\n오른쪽에 있는 설정 버튼 중 하나를 선택하여\n\n26\n00:01:23.050 --> 00:01:25.400\n이 색상을 대표 색상으로 저장하세요.\n\n27\n00:01:25.400 --> 00:01:27.910\n비전 센서가 색상을 캡처할 때마다\n\n28\n00:01:27.910 --> 00:01:31.490\n모든 색상 특성이 대표 색상으로 저장됩니다.\n\n29\n00:01:31.490 --> 00:01:33.180\n비전 센서는 최대\n\n30\n00:01:33.180 --> 00:01:35.550\n7개의 대표 색상을 저장할 수 있습니다.\n\n31\n00:01:35.550 --> 00:01:37.700\n마지막으로 프로젝트의 각 대표 색상을\n\n32\n00:01:37.700 --> 00:01:40.823\n구분하기 위해 이름을 변경할 수 있습니다.\n\n33\n00:01:45.020 --> 00:01:47.630\n비전 센서 구성을 마쳤으면\n\n34\n00:01:47.630 --> 00:01:49.603\n비전 센서 유틸리티를 닫으세요.\n\n35\n00:01:50.690 --> 00:01:52.440\n그리고 기기 창에서\n\n36\n00:01:52.440 --> 00:01:53.843\n완료를 선택하세요.\n\n37\n00:01:57.640 --> 00:02:00.733\n이제 비전 센서 블록이 도구 상자에 나타납니다.\n\n38\n00:02:02.120 --> 00:02:05.263\n비전 센서 구성이 완료되고 사용할 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->\"V5\" blokų projekte</v>\n\n2\n00:00:02.060 --> 00:00:03.820\ngalite sukonfigūruoti savo vaizdo jutiklį\n\n3\n00:00:03.820 --> 00:00:06.440\nskirtingų spalvų objektams rasti.\n\n4\n00:00:06.440 --> 00:00:10.300\nPirmiausia, prijunkite mikro USB laidą iš savo kompiuterio\n\n5\n00:00:10.300 --> 00:00:12.113\nprie vaizdo jutiklio apačios.\n\n6\n00:00:13.300 --> 00:00:17.353\nPo to, programoje \"VEXcode V5\" atverkite prietaisų langą.\n\n7\n00:00:19.840 --> 00:00:24.840\nDabar, pasirinkite kokį prietaisą pridėti ir pasirinkite vaizdą.\n\n8\n00:00:27.360 --> 00:00:29.940\nGaliausiai, pasirinkite prie kokio \"VEX V5\" prievado prijungtas\n\n9\n00:00:29.940 --> 00:00:33.170\nvaizdo jutiklis.\n\n10\n00:00:33.170 --> 00:00:35.480\nPasirodo vaizdo prietaiso ekranas.\n\n11\n00:00:35.480 --> 00:00:39.460\nČia galite keisti savo vaizdo jutiklio pavadinimą.\n\n12\n00:00:39.460 --> 00:00:42.090\nTaip pat galite sukonfigūruoti savo vaizdo jutiklį.\n\n13\n00:00:42.090 --> 00:00:45.273\nVaizdo programai atverti spustelėkite mygtuką \"Konfigūruoti\".\n\n14\n00:00:48.580 --> 00:00:50.330\nVaizdo programoje\n\n15\n00:00:50.330 --> 00:00:53.400\nmatysite tiesioginį vaizdo jutiklio matomą vaizdą.\n\n16\n00:00:53.400 --> 00:00:55.090\nTiesioginiu vaizdu galite\n\n17\n00:00:55.090 --> 00:00:59.460\nkonfigūruoti vaizdo jutiklį skirtingoms spalvoms aptikti.\n\n18\n00:00:59.460 --> 00:01:01.820\nNorėdami sukonfigūruoti spalvą, kurią reikia aptikti,\n\n19\n00:01:01.820 --> 00:01:06.020\npirmiausia, padėkite arba laikykite objektą priešais vaizdo jutiklį,\n\n20\n00:01:06.020 --> 00:01:07.870\npo to, spustelėkite mygtuką \"Fiksuoti\"\n\n21\n00:01:07.870 --> 00:01:09.523\nvaizdui užfiksuoti.\n\n22\n00:01:12.270 --> 00:01:15.060\nPasirinkite ir vilkite laukelį aplink tą spalvą,\n\n23\n00:01:15.060 --> 00:01:18.620\nkurią norite sukonfigūruoti, kad galėtų aptikti vaizdo jutiklis.\n\n24\n00:01:18.620 --> 00:01:20.970\nDabar, dešinėje vaizdo programos pusėje,\n\n25\n00:01:20.970 --> 00:01:23.050\nspustelėkite vieną iš nustatymo juostų\n\n26\n00:01:23.050 --> 00:01:25.400\nšiai spalvai signatūroje išsaugoti.\n\n27\n00:01:25.400 --> 00:01:27.910\nKai vaizdo jutiklis užfiksuoja spalvą,\n\n28\n00:01:27.910 --> 00:01:31.490\nvisos spalvos ypatybės saugomos kaip signatūra.\n\n29\n00:01:31.490 --> 00:01:33.180\nVaizdo jutiklyje galima saugoti\n\n30\n00:01:33.180 --> 00:01:35.550\niki septynių skirtingų signatūrų.\n\n31\n00:01:35.550 --> 00:01:37.700\nGaliausiai, galite pervadinti savo signatūrą\n\n32\n00:01:37.700 --> 00:01:40.823\nprojekte kiekvienai signatūrai identifikuoti.\n\n33\n00:01:45.020 --> 00:01:47.630\nBaigę konfigūruoti vaizdo jutiklį,\n\n34\n00:01:47.630 --> 00:01:49.603\ngalite uždaryti vaizdo programą.\n\n35\n00:01:50.690 --> 00:01:52.440\nNepamirškite prietaisų lange\n\n36\n00:01:52.440 --> 00:01:53.843\npasirinkti \"Baigti\".\n\n37\n00:01:57.640 --> 00:02:00.733\nParankinėje atsiras vaizdo jutiklio blokai.\n\n38\n00:02:02.120 --> 00:02:05.263\nJūsų vaizdo jutiklis sukonfigūruotas ir parengtas naudoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v -> V5 bloku projektā, </v>\n\n2\n00:00:02.060 --> 00:00:03.820\nvariet konfigurēt savu attēla sensoru,\n\n3\n00:00:03.820 --> 00:00:06.440\nlai noteiktu dažādu krāsu objektus.\n\n4\n00:00:06.440 --> 00:00:10.300\nVispirms savienojiet mikro USB kabeli ar datoru\n\n5\n00:00:10.300 --> 00:00:12.113\nun attēla sensora ligzdu apakšdaļā.\n\n6\n00:00:13.300 --> 00:00:17.353\nPēc tam VEXcode V5 atveriet logu “Devices” (ierīces).\n\n7\n00:00:19.840 --> 00:00:24.840\nAtlasiet “Add a device” un izvēlieties “Vision”.\n\n8\n00:00:27.360 --> 00:00:29.940\nIzvēlieties, pie kura porta attēla sensors\n\n9\n00:00:29.940 --> 00:00:33.170\nir savienots ar VEX V5 smadzenēm.\n\n10\n00:00:33.170 --> 00:00:35.480\nTiek parādīts attēla ierīces ekrāns.\n\n11\n00:00:35.480 --> 00:00:39.460\nŠeit variet mainīt attēla sensora nosaukumu.\n\n12\n00:00:39.460 --> 00:00:42.090\nVariet arī konfigurēt savu attēla sensoru.\n\n13\n00:00:42.090 --> 00:00:45.273\nIzvēlieties pogu “Configure” (konfigurēt),\nlai atvērtu “Vision Utility” (attēla utilīta).\n\n14\n00:00:48.580 --> 00:00:50.330\nProgrammā “Vision Utility” (attēla utilīta)\n\n15\n00:00:50.330 --> 00:00:53.400\nredzēsiet tiešo plūsmu no “Vision Sensor”.\n\n16\n00:00:53.400 --> 00:00:55.090\nTiešā plūsma tiek izmantota, lai jūs\n\n17\n00:00:55.090 --> 00:00:59.460\nvarētu konfigurēt attēla sensoru, lai uztvertu dažādas krāsas.\n\n18\n00:00:59.460 --> 00:01:01.820\nLai konfigurētu, kādu krāsu uztvert,\n\n19\n00:01:01.820 --> 00:01:06.020\nvispirms novietojiet vai turiet objektu attēla sensora priekšpusē,\n\n20\n00:01:06.020 --> 00:01:07.870\npēc tam atlasiet pogu “Freeze”,\n\n21\n00:01:07.870 --> 00:01:09.523\nlai uztvertu attēlu.\n\n22\n00:01:12.270 --> 00:01:15.060\nPēc tam atlasiet un velciet lodziņu ap krāsu,\n\n23\n00:01:15.060 --> 00:01:18.620\nkuru vēlaties uzstādīt attēla sensora uztveršanai.\n\n24\n00:01:18.620 --> 00:01:20.970\nTagad izvēlieties vienu no iestatījuma joslām\n\n25\n00:01:20.970 --> 00:01:23.050\nprogrammas “Vision Utility” labajā pusē,\n\n26\n00:01:23.050 --> 00:01:25.400\nlai šo krāsu saglabātu spiedogā.\n\n27\n00:01:25.400 --> 00:01:27.910\nIkreiz, kad attēla sensors uztvers krāsu,\n\n28\n00:01:27.910 --> 00:01:31.490\nvisas krāsas ievadītās īpašības tiks saglabātas spiedogā.\n\n29\n00:01:31.490 --> 00:01:33.180\nAttēla sensorā var saglabāt\n\n30\n00:01:33.180 --> 00:01:35.550\nlīdz septiņiem dažādiem spiedogiem.\n\n31\n00:01:35.550 --> 00:01:37.700\nKā arī spiedogu var pārdēvēt,\n\n32\n00:01:37.700 --> 00:01:40.823\nlai identificētu katru jūsu projekta spiedogu.\n\n33\n00:01:45.020 --> 00:01:47.630\nKad esat pabeidzis attēla sensora konfigurēšanu,\n\n34\n00:01:47.630 --> 00:01:49.603\nvariet aizvērt “Vision Utility”.\n\n35\n00:01:50.690 --> 00:01:52.440\nNeaizmirstiet arī izvēlēties “Done”\n\n36\n00:01:52.440 --> 00:01:53.843\n(gatavs) ierīču logā.\n\n37\n00:01:57.640 --> 00:02:00.733\nAttēla sensora bloki tagad parādīsies rīku lodziņā.\n\n38\n00:02:02.120 --> 00:02:05.263\nJūsu attēla sensors tagad ir konfigurēts un gatavs lietošanai.\n\n","nl":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->In een V5 blokken project,</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nkunt u uw Beeldsensor configureren\n\n3\n00:00:03.820 --> 00:00:06.440\nom objecten met verschillende kleuren te detecteren.\n\n4\n00:00:06.440 --> 00:00:10.300\nSluit eerst de micro-USB-kabel van uw computer aan\n\n5\n00:00:10.300 --> 00:00:12.113\nop de onderkant van de Beeldsensor.\n\n6\n00:00:13.300 --> 00:00:17.353\nOpen vervolgens, terug in VEXcode V5, het venster Apparaten.\n\n7\n00:00:19.840 --> 00:00:24.840\nSelecteer nu een Apparaat toevoegen en kies Beeld.\n\n8\n00:00:27.360 --> 00:00:29.940\nSelecteer tot slot op welke poort de Beeldsensor\n\n9\n00:00:29.940 --> 00:00:33.170\nis aangesloten op de VEX V5 brein.\n\n10\n00:00:33.170 --> 00:00:35.480\nHet beeld-apparaatscherm wordt weergegeven.\n\n11\n00:00:35.480 --> 00:00:39.460\nVanaf hier verander je de naam van je Beeldsensor.\n\n12\n00:00:39.460 --> 00:00:42.090\nU kunt ook de beeldsensor configureren.\n\n13\n00:00:42.090 --> 00:00:45.273\nSelecteer de configuratie-knop om het beeld-hulpmiddel te openen.\n\n14\n00:00:48.580 --> 00:00:50.330\nBinnen het beeldgebruik,\n\n15\n00:00:50.330 --> 00:00:53.400\nje zal een live feed van de beeldsensor zien.\n\n16\n00:00:53.400 --> 00:00:55.090\nDe live feed wordt gebruikt\n\n17\n00:00:55.090 --> 00:00:59.460\nom de beeldsensor te configureren om verschillende kleuren te detecteren.\n\n18\n00:00:59.460 --> 00:01:01.820\nOm een te detecteren kleur te configureren,\n\n19\n00:01:01.820 --> 00:01:06.020\neerst plaats of houd een object vast voor de Beeldsensor,\n\n20\n00:01:06.020 --> 00:01:07.870\ndan selecteer de bevriezing knop\n\n21\n00:01:07.870 --> 00:01:09.523\nom de afbeelding te behouden.\n\n22\n00:01:12.270 --> 00:01:15.060\nSelecteer en sleep vervolgens het vak rond de kleur\n\n23\n00:01:15.060 --> 00:01:18.620\ndie u wilt configureren voor de beeldsensor om te detecteren.\n\n24\n00:01:18.620 --> 00:01:20.970\nSelecteer nu een van de Zet-balken\n\n25\n00:01:20.970 --> 00:01:23.050\naan de rechterkant van het beeld-hulpprogramma\n\n26\n00:01:23.050 --> 00:01:25.400\nom deze kleur in een signatuur op te slaan.\n\n27\n00:01:25.400 --> 00:01:27.910\nTelkens wanneer de beeldsensor een kleur vastlegt,\n\n28\n00:01:27.910 --> 00:01:31.490\nworden alle kleureigenschappen als een signatuur opgeslagen.\n\n29\n00:01:31.490 --> 00:01:33.180\nDe beeldsensor kan\n\n30\n00:01:33.180 --> 00:01:35.550\ntot zeven verschillende signaturen opslaan.\n\n31\n00:01:35.550 --> 00:01:37.700\nTot slot kunt u uw signatuur\n\n32\n00:01:37.700 --> 00:01:40.823\nhernoemen om elke signatuur in uw project te identificeren.\n\n33\n00:01:45.020 --> 00:01:47.630\nAls u klaar bent met het configureren van de beeldsensor,\n\n34\n00:01:47.630 --> 00:01:49.603\nkunt u het beeld-hulpprogramma sluiten.\n\n35\n00:01:50.690 --> 00:01:52.440\nVergeet ook niet om Gereed te selecteren\n\n36\n00:01:52.440 --> 00:01:53.843\nin het venster van apparaten.\n\n37\n00:01:57.640 --> 00:02:00.733\nBeeldsensor blokken worden nu weergegeven in de werkbalk.\n\n38\n00:02:02.120 --> 00:02:05.263\nUw beeldsensor is nu geconfigureerd en klaar voor gebruik.\n\n","pl":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->W projekcie blokowym V5</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nmożesz skonfigurować swój Czujnik Wizji\n\n3\n00:00:03.820 --> 00:00:06.440\nby wykrywać obiekty różnych kolorów.\n\n4\n00:00:06.440 --> 00:00:10.300\nNajpierw podłącz kabel MicroUSB ze swoim komputerem\n\n5\n00:00:10.300 --> 00:00:12.113\nz dolną częścią czujnika wizji.\n\n6\n00:00:13.300 --> 00:00:17.353\nNastępnie, ponownie w kodzie VEXcode V5, otwórz okno urządzenia.\n\n7\n00:00:19.840 --> 00:00:24.840\nWybierz Dodaj urządzenie i wybierz czujnik wizji.\n\n8\n00:00:27.360 --> 00:00:29.940\nNa koniec wybierz do którego portu\n\n9\n00:00:29.940 --> 00:00:33.170\njest połączony z mózgiem VEX V5.\n\n10\n00:00:33.170 --> 00:00:35.480\nWyświetla się ekran czujnika wizyjnego.\n\n11\n00:00:35.480 --> 00:00:39.460\nTutaj możesz zmienić nazwę czujnika.\n\n12\n00:00:39.460 --> 00:00:42.090\nMożesz skonfigurować swój Czujnik Wizji.\n\n13\n00:00:42.090 --> 00:00:45.273\nWybierz przycisk konfiguracyjny, aby otworzyć narzędzie ustawień.\n\n14\n00:00:48.580 --> 00:00:50.330\nWewnątrz narzędzia,\n\n15\n00:00:50.330 --> 00:00:53.400\nzobaczysz podgląd na żywo z czujnika.\n\n16\n00:00:53.400 --> 00:00:55.090\nPodgląd na żywo może Ci pozwolić\n\n17\n00:00:55.090 --> 00:00:59.460\naby skonfigurować czujnik widzenia w celu wykrycia różnych kolorów.\n\n18\n00:00:59.460 --> 00:01:01.820\nAby skonfigurować kolor do wykrycia,\n\n19\n00:01:01.820 --> 00:01:06.020\npo pierwsze umieść lub przytrzymaj obiekt przed czujnikiem,\n\n20\n00:01:06.020 --> 00:01:07.870\nnastępnie wybierz przycisk Zamrażania\n\n21\n00:01:07.870 --> 00:01:09.523\naby zachować wykonany obraz.\n\n22\n00:01:12.270 --> 00:01:15.060\nNastępnie wybierz i przeciągnij pole wokół koloru\n\n23\n00:01:15.060 --> 00:01:18.620\nktóry chcesz by był wykrywany przez czujnik.\n\n24\n00:01:18.620 --> 00:01:20.970\nTeraz wybierz jeden z przycisków \"Ustawienia\"\n\n25\n00:01:20.970 --> 00:01:23.050\npo prawej stronie narzędzia\n\n26\n00:01:23.050 --> 00:01:25.400\naby przechowywać ten kolor w podpisie.\n\n27\n00:01:25.400 --> 00:01:27.910\nZa każdym razem, gdy czujnik uchwyci kolor,\n\n28\n00:01:27.910 --> 00:01:31.490\nwszystkie właściwości koloru są przechowywane jako podpis.\n\n29\n00:01:31.490 --> 00:01:33.180\nCzujnik jest w stanie przechowywać\n\n30\n00:01:33.180 --> 00:01:35.550\ndo 7 różnych podpisów.\n\n31\n00:01:35.550 --> 00:01:37.700\nNa koniec możesz zmienić nazwę swojego podpisu\n\n32\n00:01:37.700 --> 00:01:40.823\nw celu identyfikacji każdego podpisu w Twoim projekcie.\n\n33\n00:01:45.020 --> 00:01:47.630\nPo zakończeniu konfigurowania Czujnika Wizji,\n\n34\n00:01:47.630 --> 00:01:49.603\nmożesz zamknąć Narzędzie ustawień.\n\n35\n00:01:50.690 --> 00:01:52.440\nPamiętaj, aby wybrać gotowe,\n\n36\n00:01:52.440 --> 00:01:53.843\nw oknie urządzenia.\n\n37\n00:01:57.640 --> 00:02:00.733\nBloki czujnika pojawią się teraz w przyborniku.\n\n38\n00:02:02.120 --> 00:02:05.263\nTwój czujnik jest teraz skonfigurowany i gotowy do użycia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->В блоковом проекте V5</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nвы можете настраивать камеру\n\n3\n00:00:03.820 --> 00:00:06.440\nдля обнаружения объектов разных цветов.\n\n4\n00:00:06.440 --> 00:00:10.300\nПодключите, в первую очередь, USB провод от ПК\n\n5\n00:00:10.300 --> 00:00:12.113\nк разъёму на камере.\n\n6\n00:00:13.300 --> 00:00:17.353\nДалее, вернитесь в VEXcode V5 и откройте окно устройств.\n\n7\n00:00:19.840 --> 00:00:24.840\nВыберите из списка устройств камеру.\n\n8\n00:00:27.360 --> 00:00:29.940\nВыберите порт подключения на контроллере,\n\n9\n00:00:29.940 --> 00:00:33.170\nк которому подключена камера.\n\n10\n00:00:33.170 --> 00:00:35.480\nПоявится экран камеры.\n\n11\n00:00:35.480 --> 00:00:39.460\nЗдесь вы можете изменить имя устройства.\n\n12\n00:00:39.460 --> 00:00:42.090\nКроме того, вы можете настроить камеру.\n\n13\n00:00:42.090 --> 00:00:45.273\nНажмите кнопку настройки для открытия настроек камеры.\n\n14\n00:00:48.580 --> 00:00:50.330\nВнутри интерфейса настройки\n\n15\n00:00:50.330 --> 00:00:53.400\nвы увидите прямую трансляцию с камеры.\n\n16\n00:00:53.400 --> 00:00:55.090\nПрямая трансляция позволяет\n\n17\n00:00:55.090 --> 00:00:59.460\nнастроить камеру для обнаружения объектов разных цветов.\n\n18\n00:00:59.460 --> 00:01:01.820\nДля настройки обнаружения цветов,\n\n19\n00:01:01.820 --> 00:01:06.020\nпоместите объект перед камерой,\n\n20\n00:01:06.020 --> 00:01:07.870\nзатем, нажмите кнопку \"Заморозить\"\n\n21\n00:01:07.870 --> 00:01:09.523\nдля захвата изображения.\n\n22\n00:01:12.270 --> 00:01:15.060\nЗатем, создайте прямоугольник вокруг цвета объекта,\n\n23\n00:01:15.060 --> 00:01:18.620\nкоторый вы бы хотели обнаружить.\n\n24\n00:01:18.620 --> 00:01:20.970\nВыберите одну из кнопок \"Set\" в списке\n\n25\n00:01:20.970 --> 00:01:23.050\nна правой панели окна настройки камеры\n\n26\n00:01:23.050 --> 00:01:25.400\nдля сохранения параметров цвета.\n\n27\n00:01:25.400 --> 00:01:27.910\nКаждый раз, когда камера захватывает цвет,\n\n28\n00:01:27.910 --> 00:01:31.490\nвсе значения цвета сохраняются в виде \"подписи\".\n\n29\n00:01:31.490 --> 00:01:33.180\nКамера позволяет хранить\n\n30\n00:01:33.180 --> 00:01:35.550\nдо семи различных цветов.\n\n31\n00:01:35.550 --> 00:01:37.700\nНаконец, вы можете переименовать сохраненный цвет\n\n32\n00:01:37.700 --> 00:01:40.823\nдля удобства его использования в дальнейшем.\n\n33\n00:01:45.020 --> 00:01:47.630\nПосле настройки камеры,\n\n34\n00:01:47.630 --> 00:01:49.603\nвы можете закрыть окно настройки.\n\n35\n00:01:50.690 --> 00:01:52.440\nКроме того, не забудьте выбрать \"Готово\"\n\n36\n00:01:52.440 --> 00:01:53.843\nв окне настройки.\n\n37\n00:01:57.640 --> 00:02:00.733\nБлоки камеры появятся в инструментарии.\n\n38\n00:02:02.120 --> 00:02:05.263\nКамера настроена и готова к использованию.\n\n","th":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v -> ใน V5 บล็อกโปรเจ็ค </v>\n\n2\n00:00:02.060 --> 00:00:03.820\nคุณสามารถกำหนดค่าเซ็นเซอร์การมองเห็นของคุณ\n\n3\n00:00:03.820 --> 00:00:06.440\nเพื่อตรวจจับวัตถุที่มีสีต่างกัน\n\n4\n00:00:06.440 --> 00:00:10.300\nขั้นแรกให้เชื่อมต่อสายไมโคร USB จากคอมพิวเตอร์ของคุณ\n\n5\n00:00:10.300 --> 00:00:12.113\nไปที่ด้านล่างของเซ็นเซอร์การมองเห็น\n\n6\n00:00:13.300 --> 00:00:17.353\nจากนั้นกลับไปที่ VEXcode V5 แล้วเปิดหน้าต่างอุปกรณ์\n\n7\n00:00:19.840 --> 00:00:24.840\nตอนนี้เลือก Add a device และเลือก Vision\n\n8\n00:00:27.360 --> 00:00:29.940\nสุดท้ายเลือกพอร์ตที่เซ็นเซอร์การมองเห็น\n\n9\n00:00:29.940 --> 00:00:33.170\nเชื่อมต่อกับสมอง VEX V5\n\n10\n00:00:33.170 --> 00:00:35.480\nหน้าจออุปกรณ์การมองเห็นจะปรากฏขึ้น\n\n11\n00:00:35.480 --> 00:00:39.460\nจากที่นี่คุณสามารถเปลี่ยนชื่อเซ็นเซอร์การมองเห็นของคุณ\n\n12\n00:00:39.460 --> 00:00:42.090\nและคุณยังสามารถกำหนดค่าเซ็นเซอร์การมองเห็นของคุณ\n\n13\n00:00:42.090 --> 00:00:45.273\nเลือกปุ่มกำหนดค่าเพื่อเปิด vision utility\n\n14\n00:00:48.580 --> 00:00:50.330\nภายใน vision utility\n\n15\n00:00:50.330 --> 00:00:53.400\nคุณจะเห็นไลฟ์ฟีดจากศูนย์การมองเห็น\n\n16\n00:00:53.400 --> 00:00:55.090\nไลฟ์ฟีดจะช่วยให้คุณ\n\n17\n00:00:55.090 --> 00:00:59.460\nสามารถต้องค่าเซ็นเซอร์การมองเห็นเพื่อตรวจจับสีต่างๆได้\n\n18\n00:00:59.460 --> 00:01:01.820\nในการกำหนดค่าสีที่จะตรวจจับ\n\n19\n00:01:01.820 --> 00:01:06.020\nอันดับแรกหรือถือวัตถุไว้ด้านหน้าเซ็นเซอร์การมองเห็น\n\n20\n00:01:06.020 --> 00:01:07.870\nจากนั้นเลือกปุ่ม Freeze\n\n21\n00:01:07.870 --> 00:01:09.523\nเพื่อทำการบันทึกภาพ\n\n22\n00:01:12.270 --> 00:01:15.060\nจากนั้นเลือกและลากกล่องรอบๆ สี\n\n23\n00:01:15.060 --> 00:01:18.620\nที่คุณต้องการกำหนดค่าเซ็นเซอร์การมองเห็นเพื่อตรวจจับ\n\n24\n00:01:18.620 --> 00:01:20.970\nตอนนี้เลือกหนึ่งตัวเลือกจาก Set bar ในแถบตั้งค่า\n\n25\n00:01:20.970 --> 00:01:23.050\nซึ่งอยู่ทางด้านขวาของ vision utility\n\n26\n00:01:23.050 --> 00:01:25.400\nเพื่อเก็บสีนี้ไว้ในค่าสีที่แตกต่างกัน signature\n\n27\n00:01:25.400 --> 00:01:27.910\nเมื่อใดก็ตามที่เซ็นเซอร์การมองเห็นจับภาพสี\n\n28\n00:01:27.910 --> 00:01:31.490\nคุณสมบัติของสีทั้งหมดจะถูกเก็บบันทึกไว้\n\n29\n00:01:31.490 --> 00:01:33.180\nเซ็นเซอร์การมองเห็นสามารถจัดเก็บสีได้\n\n30\n00:01:33.180 --> 00:01:35.550\nที่แตกต่างกันมากถึงเจ็ดสี\n\n31\n00:01:35.550 --> 00:01:37.700\nสุดท้ายคุณสามารถเปลี่ยนชื่อค่าสี signature ของคุณ\n\n32\n00:01:37.700 --> 00:01:40.823\nเพื่อระบุค่าสีแต่ละเพื่อใช้ในโปรเจ็คของคุณ\n\n33\n00:01:45.020 --> 00:01:47.630\nเมื่อคุณกำหนดค่าเซ็นเซอร์การมองเห็นเสร็จแล้ว\n\n34\n00:01:47.630 --> 00:01:49.603\nคุณสามารถปิด vision utility ได้\n\n35\n00:01:50.690 --> 00:01:52.440\nนอกจากนี้อย่าลืมเลือกปุ่ม Done\n\n36\n00:01:52.440 --> 00:01:53.843\nในหน้าต่างอุปกรณ์\n\n37\n00:01:57.640 --> 00:02:00.733\nตอนนี้บล็อกเซ็นเซอร์วิสัยทัศน์จะปรากฏในกล่องเครื่องมือ\n\n38\n00:02:02.120 --> 00:02:05.263\nขณะนี้เซ็นเซอร์การมองเห็นของคุณได้รับการกำหนดค่าและพร้อมใช้งานแล้ว\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->У блоковому проєкті V5</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nви можете налаштувати датчик зору\n\n3\n00:00:03.820 --> 00:00:06.440\nдля розпізнавання об'єктів різних кольорів.\n\n4\n00:00:06.440 --> 00:00:10.300\nСпочатку, під'єднайте micro-USB кабель від вашого комп'ютера\n\n5\n00:00:10.300 --> 00:00:12.113\nдо основи датчика зору.\n\n6\n00:00:13.300 --> 00:00:17.353\nДалі, поверніться до VEXcode V5 і відкрийте вікно пристроїв.\n\n7\n00:00:19.840 --> 00:00:24.840\nТепер натисніть \"Додати пристрій\" і виберіть датчик зору.\n\n8\n00:00:27.360 --> 00:00:29.940\nДля закінчення виберіть порт, у який ви приєднали\n\n9\n00:00:29.940 --> 00:00:33.170\nдатчик зору до VEX V5 Brain.\n\n10\n00:00:33.170 --> 00:00:35.480\nЗ'явиться вікно датчика зору.\n\n11\n00:00:35.480 --> 00:00:39.460\nЗвідси ви можете змінити \nім'я датчика зору.\n\n12\n00:00:39.460 --> 00:00:42.090\nТакож ви можете налаштувати датчик зору.\n\n13\n00:00:42.090 --> 00:00:45.273\nНатисніть на кнопку \"Налаштування\", щоб відкрити підпрограму датчика.\n\n14\n00:00:48.580 --> 00:00:50.330\nВсередині підпрограми\n\n15\n00:00:50.330 --> 00:00:53.400\nви побачите трансляцію зображення з датчика зору.\n\n16\n00:00:53.400 --> 00:00:55.090\nТрансляція допоможе вам\n\n17\n00:00:55.090 --> 00:00:59.460\nналаштувати датчик зору на розпізнавання кольорів.\n\n18\n00:00:59.460 --> 00:01:01.820\nДля налаштування визначення кольору\n\n19\n00:01:01.820 --> 00:01:06.020\nрозмістіть або тримайте об'єкт перед датчиком зору,\n\n20\n00:01:06.020 --> 00:01:07.870\nа потім натисніть \"Freeze\",\n\n21\n00:01:07.870 --> 00:01:09.523\nщоб зафіксувати зображення.\n\n22\n00:01:12.270 --> 00:01:15.060\nДалі, поставте і розтягніть рамку навколо кольору,\n\n23\n00:01:15.060 --> 00:01:18.620\nякий ви хочете розпізнавати датчиком зору.\n\n24\n00:01:18.620 --> 00:01:20.970\nТепер оберіть одну з кнопок \"Set\"\n\n25\n00:01:20.970 --> 00:01:23.050\nіз правого боку підпрограми датчика\n\n26\n00:01:23.050 --> 00:01:25.400\nдля збереження сигнатури кольору.\n\n27\n00:01:25.400 --> 00:01:27.910\nКоли датчик зору вловить колір,\n\n28\n00:01:27.910 --> 00:01:31.490\nвсі пропорції кольору збережуться в сигнатурі.\n\n29\n00:01:31.490 --> 00:01:33.180\nДатчик зору може зберігати\n\n30\n00:01:33.180 --> 00:01:35.550\nдо семи різних сигнатур.\n\n31\n00:01:35.550 --> 00:01:37.700\nНаостанок, ви можете перейменувати сигнатуру\n\n32\n00:01:37.700 --> 00:01:40.823\nдля кращого впізнавання кожної сигнатури в проєкті.\n\n33\n00:01:45.020 --> 00:01:47.630\nЩойно ви закінчите налаштування датчика,\n\n34\n00:01:47.630 --> 00:01:49.603\nможете закрити підпрограму.\n\n35\n00:01:50.690 --> 00:01:52.440\nНе забудьте натиснути \"Готово\"\n\n36\n00:01:52.440 --> 00:01:53.843\nу вікні пристрою.\n\n37\n00:01:57.640 --> 00:02:00.733\nБлоки датчика зору з'являться в наборі блоків.\n\n38\n00:02:02.120 --> 00:02:05.263\nТепер датчик зору налаштований і готовий до використання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->Trong dự án khối V5,</v>\n\n2\n00:00:02.060 --> 00:00:03.820\nbạn có thể định cấu hình cảm biến tầm nhìn của mình\n\n3\n00:00:03.820 --> 00:00:06.440\nđể phát hiện các đối tượng có màu sắc khác nhau.\n\n4\n00:00:06.440 --> 00:00:10.300\nĐầu tiên, kết nối cáp micro-USB từ máy tính của bạn\n\n5\n00:00:10.300 --> 00:00:12.113\nở dưới cùng của cảm biến thị lực.\n\n6\n00:00:13.300 --> 00:00:17.353\nTiếp theo, quay lại VEXcode V5, mở cửa sổ Thiết bị.\n\n7\n00:00:19.840 --> 00:00:24.840\nBây giờ, chọn Thêm thiết bị và chọn Tầm nhìn.\n\n8\n00:00:27.360 --> 00:00:29.940\nCuối cùng, chọn cổng cảm biến thị lực\n\n9\n00:00:29.940 --> 00:00:33.170\nđược kết nối với não VEX V5.\n\n10\n00:00:33.170 --> 00:00:35.480\nMàn hình thiết bị thị giác xuất hiện.\n\n11\n00:00:35.480 --> 00:00:39.460\nTừ đây, bạn thay đổi tên của cảm biến thị lực của mình.\n\n12\n00:00:39.460 --> 00:00:42.090\nBạn cũng có thể định cấu hình cảm biến thị lực của mình.\n\n13\n00:00:42.090 --> 00:00:45.273\nChọn nút cấu hình để mở tiện ích tầm nhìn.\n\n14\n00:00:48.580 --> 00:00:50.330\nBên trong tiện ích tầm nhìn,\n\n15\n00:00:50.330 --> 00:00:53.400\nbạn sẽ thấy một nguồn cấp dữ liệu trực tiếp từ cảm biến thị lực.\n\n16\n00:00:53.400 --> 00:00:55.090\nNguồn cấp dữ liệu trực tiếp được sử dụng để cho phép bạn\n\n17\n00:00:55.090 --> 00:00:59.460\nđể định cấu hình cảm biến thị lực để phát hiện các màu khác nhau.\n\n18\n00:00:59.460 --> 00:01:01.820\nĐể định cấu hình một màu được phát hiện,\n\n19\n00:01:01.820 --> 00:01:06.020\nđặt hoặc giữ một đối tượng trước cảm biến thị lực,\n\n20\n00:01:06.020 --> 00:01:07.870\nsau đó chọn nút Freeze\n\n21\n00:01:07.870 --> 00:01:09.523\nđể giữ cho hình ảnh được chụp.\n\n22\n00:01:12.270 --> 00:01:15.060\nTiếp theo, chọn và kéo hộp xung quanh màu\n\n23\n00:01:15.060 --> 00:01:18.620\nbạn muốn định cấu hình cảm biến thị lực để phát hiện.\n\n24\n00:01:18.620 --> 00:01:20.970\nBây giờ, hãy chọn một trong các thanh Đặt\n\n25\n00:01:20.970 --> 00:01:23.050\nở bên phải của tiện ích tầm nhìn\n\n26\n00:01:23.050 --> 00:01:25.400\nđể lưu trữ màu này trong một chữ ký.\n\n27\n00:01:25.400 --> 00:01:27.910\nBất cứ khi nào cảm biến thị lực chụp một màu,\n\n28\n00:01:27.910 --> 00:01:31.490\ntất cả các thuộc tính của màu được lưu trữ dưới dạng chữ ký.\n\n29\n00:01:31.490 --> 00:01:33.180\nCảm biến tầm nhìn có thể lưu trữ\n\n30\n00:01:33.180 --> 00:01:35.550\nlên đến bảy chữ ký khác nhau.\n\n31\n00:01:35.550 --> 00:01:37.700\nCuối cùng, bạn có thể đổi tên chữ ký của mình\n\n32\n00:01:37.700 --> 00:01:40.823\nđể xác định từng chữ ký trong dự án của bạn.\n\n33\n00:01:45.020 --> 00:01:47.630\nKhi bạn đã hoàn tất việc định cấu hình cảm biến thị lực,\n\n34\n00:01:47.630 --> 00:01:49.603\nbạn có thể đóng tiện ích tầm nhìn.\n\n35\n00:01:50.690 --> 00:01:52.440\nNgoài ra, hãy nhớ chọn Xong,\n\n36\n00:01:52.440 --> 00:01:53.843\ntrong cửa sổ thiết bị.\n\n37\n00:01:57.640 --> 00:02:00.733\nCác khối cảm biến tầm nhìn bây giờ sẽ xuất hiện trong hộp công cụ.\n\n38\n00:02:02.120 --> 00:02:05.263\nCảm biến thị lực của bạn hiện đã được định cấu hình và sẵn sàng sử dụng.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\ncrwdns95724:0crwdne95724:0\n\n2\n00:00:02.060 --> 00:00:03.820\ncrwdns95726:0crwdne95726:0\n\n3\n00:00:03.820 --> 00:00:06.440\ncrwdns95728:0crwdne95728:0\n\n4\n00:00:06.440 --> 00:00:10.300\ncrwdns95730:0crwdne95730:0\n\n5\n00:00:10.300 --> 00:00:12.113\ncrwdns95732:0crwdne95732:0\n\n6\n00:00:13.300 --> 00:00:17.353\ncrwdns95734:0crwdne95734:0\n\n7\n00:00:19.840 --> 00:00:24.840\ncrwdns95736:0crwdne95736:0\n\n8\n00:00:27.360 --> 00:00:29.940\ncrwdns95738:0crwdne95738:0\n\n9\n00:00:29.940 --> 00:00:33.170\ncrwdns95740:0crwdne95740:0\n\n10\n00:00:33.170 --> 00:00:35.480\ncrwdns95742:0crwdne95742:0\n\n11\n00:00:35.480 --> 00:00:39.460\ncrwdns95744:0crwdne95744:0\n\n12\n00:00:39.460 --> 00:00:42.090\ncrwdns95746:0crwdne95746:0\n\n13\n00:00:42.090 --> 00:00:45.273\ncrwdns95748:0crwdne95748:0\n\n14\n00:00:48.580 --> 00:00:50.330\ncrwdns95750:0crwdne95750:0\n\n15\n00:00:50.330 --> 00:00:53.400\ncrwdns396191:0crwdne396191:0\n\n16\n00:00:53.400 --> 00:00:55.090\ncrwdns95754:0crwdne95754:0\n\n17\n00:00:55.090 --> 00:00:59.460\ncrwdns95756:0crwdne95756:0\n\n18\n00:00:59.460 --> 00:01:01.820\ncrwdns95758:0crwdne95758:0\n\n19\n00:01:01.820 --> 00:01:06.020\ncrwdns95760:0crwdne95760:0\n\n20\n00:01:06.020 --> 00:01:07.870\ncrwdns95762:0crwdne95762:0\n\n21\n00:01:07.870 --> 00:01:09.523\ncrwdns95764:0crwdne95764:0\n\n22\n00:01:12.270 --> 00:01:15.060\ncrwdns95766:0crwdne95766:0\n\n23\n00:01:15.060 --> 00:01:18.620\ncrwdns95768:0crwdne95768:0\n\n24\n00:01:18.620 --> 00:01:20.970\ncrwdns95770:0crwdne95770:0\n\n25\n00:01:20.970 --> 00:01:23.050\ncrwdns95772:0crwdne95772:0\n\n26\n00:01:23.050 --> 00:01:25.400\ncrwdns95774:0crwdne95774:0\n\n27\n00:01:25.400 --> 00:01:27.910\ncrwdns95776:0crwdne95776:0\n\n28\n00:01:27.910 --> 00:01:31.490\ncrwdns95778:0crwdne95778:0\n\n29\n00:01:31.490 --> 00:01:33.180\ncrwdns95780:0crwdne95780:0\n\n30\n00:01:33.180 --> 00:01:35.550\ncrwdns95782:0crwdne95782:0\n\n31\n00:01:35.550 --> 00:01:37.700\ncrwdns95784:0crwdne95784:0\n\n32\n00:01:37.700 --> 00:01:40.823\ncrwdns95786:0crwdne95786:0\n\n33\n00:01:45.020 --> 00:01:47.630\ncrwdns95788:0crwdne95788:0\n\n34\n00:01:47.630 --> 00:01:49.603\ncrwdns95790:0crwdne95790:0\n\n35\n00:01:50.690 --> 00:01:52.440\ncrwdns95792:0crwdne95792:0\n\n36\n00:01:52.440 --> 00:01:53.843\ncrwdns95794:0crwdne95794:0\n\n37\n00:01:57.640 --> 00:02:00.733\ncrwdns95796:0crwdne95796:0\n\n38\n00:02:02.120 --> 00:02:05.263\ncrwdns95798:0crwdne95798:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.260 --> 00:00:02.060\n<v ->在一个V5指令块程序中，</v>\n\n2\n00:00:02.060 --> 00:00:03.820\n你可以设置视觉传感器。\n\n3\n00:00:03.820 --> 00:00:06.440\n来检测不同颜色的对象。\n\n4\n00:00:06.440 --> 00:00:10.300\n首先，从电脑连接USB电缆\n\n5\n00:00:10.300 --> 00:00:12.113\n至视觉传感器的底部。\n\n6\n00:00:13.300 --> 00:00:17.353\n接下来，回到VEXcode V5，打开“设备”窗口。\n\n7\n00:00:19.840 --> 00:00:24.840\n现在，选择“添加设备”并选中视觉传感器。\n\n8\n00:00:27.360 --> 00:00:29.940\n最后，选择视觉传感器连接\n\n9\n00:00:29.940 --> 00:00:33.170\n到V5主控器的端口号。\n\n10\n00:00:33.170 --> 00:00:35.480\n视觉传感器设备屏幕出现。\n\n11\n00:00:35.480 --> 00:00:39.460\n从这里，您可以重命名视觉传感器。\n\n12\n00:00:39.460 --> 00:00:42.090\n你也可以设置视觉传感器。\n\n13\n00:00:42.090 --> 00:00:45.273\n选择“设置”按钮以打开视觉传感器工具。\n\n14\n00:00:48.580 --> 00:00:50.330\n在视觉传感器工具中，\n\n15\n00:00:50.330 --> 00:00:53.400\n您将看到来自视觉传感器的实时画面。\n\n16\n00:00:53.400 --> 00:00:55.090\n实时画面用于让你\n\n17\n00:00:55.090 --> 00:00:59.460\n设置视觉传感器来检测不同颜色。\n\n18\n00:00:59.460 --> 00:01:01.820\n欲设置需检测的颜色，\n\n19\n00:01:01.820 --> 00:01:06.020\n首先放置或握持一个对象在视觉传感器前方，\n\n20\n00:01:06.020 --> 00:01:07.870\n然后选择“冻结”按钮\n\n21\n00:01:07.870 --> 00:01:09.523\n以保持图像被捕获。\n\n22\n00:01:12.270 --> 00:01:15.060\n接下来，选择并拖动一个方框，\n\n23\n00:01:15.060 --> 00:01:18.620\n你想要设置视觉传感器去检测的颜色。\n\n24\n00:01:18.620 --> 00:01:20.970\n现在，选中视觉传感器工具右侧\n\n25\n00:01:20.970 --> 00:01:23.050\n其中一个“设定”按钮。\n\n26\n00:01:23.050 --> 00:01:25.400\n将该颜色存储到一个标记中。\n\n27\n00:01:25.400 --> 00:01:27.910\n任何时候视觉传感器捕捉一个颜色，\n\n28\n00:01:27.910 --> 00:01:31.490\n所有的颜色属性都存储为一个标记。\n\n29\n00:01:31.490 --> 00:01:33.180\n视觉传感器最多可以存储\n\n30\n00:01:33.180 --> 00:01:35.550\n7个不同的标记。\n\n31\n00:01:35.550 --> 00:01:37.700\n最后，你可以重命名标记\n\n32\n00:01:37.700 --> 00:01:40.823\n为了识别程序中的每个标记。\n\n33\n00:01:45.020 --> 00:01:47.630\n一旦你完成设置视觉传感器，\n\n34\n00:01:47.630 --> 00:01:49.603\n你可以关闭视觉传感器工具。\n\n35\n00:01:50.690 --> 00:01:52.440\n同时，记得选择设备窗口\n\n36\n00:01:52.440 --> 00:01:53.843\n中的“完成”。\n\n37\n00:01:57.640 --> 00:02:00.733\n视觉传感器指令块现在将显示在工具箱中。\n\n38\n00:02:02.120 --> 00:02:05.263\n你的视觉传感器现在已经设置完成并待用。\n\n"}},{"thumb":"V5_Tutorial_tuningVision.jpg","mov":"V5Blocks_TuningVisionSensor","description":"Tuning the Vision Sensor","filter":"","placeholder":false,"vimeo":"475944338","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nA Vision Sensor\ncan be used to see objects\n\n2\n00:00:03.124 --> 00:00:04.959\nand allow your robot to interact\n\n3\n00:00:04.959 --> 00:00:07.003\nwith the world around it.\n\n4\n00:00:07.003 --> 00:00:09.630\nOccasionally, the robot\nmay have difficulty\n\n5\n00:00:09.630 --> 00:00:11.591\ndetecting known objects.\n\n6\n00:00:11.591 --> 00:00:13.968\nThis is often due to a change in lighting.\n\n7\n00:00:14.802 --> 00:00:16.053\nTo solve this problem,\n\n8\n00:00:16.053 --> 00:00:18.347\nyou may have to tune your Vision Sensor.\n\n9\n00:00:18.347 --> 00:00:22.059\nYou can tune the Vision Sensor\nusing the Vision Utility.\n\n10\n00:00:22.059 --> 00:00:23.185\nIn this tutorial,\n\n11\n00:00:23.185 --> 00:00:26.314\nwe will be using the\nDetecting Objects(Vision)\n\n12\n00:00:26.314 --> 00:00:28.149\nexample project.\n\n13\n00:00:28.149 --> 00:00:31.319\nIn this project, the Vision\nSensor has been configured\n\n14\n00:00:31.319 --> 00:00:35.865\nto detect a blue, red or green object.\n\n15\n00:00:35.865 --> 00:00:37.575\nTo tune the Vision Sensor,\n\n16\n00:00:37.575 --> 00:00:40.911\nplace a known object in\nfront of the Vision Sensor.\n\n17\n00:00:40.911 --> 00:00:43.164\nHere, the Vision Sensor should detect\n\n18\n00:00:43.164 --> 00:00:45.249\nthat this is a blue object.\n\n19\n00:00:45.249 --> 00:00:48.252\nHowever, since the lighting\nconditions have changed,\n\n20\n00:00:48.252 --> 00:00:49.920\nthe Vision Sensor is having trouble\n\n21\n00:00:49.920 --> 00:00:52.381\ndetecting the blue object.\n\n22\n00:00:52.381 --> 00:00:54.133\nBegin tuning the Vision Sensor\n\n23\n00:00:54.133 --> 00:00:57.511\nby selecting the color\nsignature of the blue object\n\n24\n00:00:57.511 --> 00:00:59.513\nand adjusting the slider.\n\n25\n00:00:59.513 --> 00:01:03.392\nMove the slider to detect\nmore of the blue object.\n\n26\n00:01:03.392 --> 00:01:04.560\nThe slider determines\n\n27\n00:01:04.560 --> 00:01:06.937\nthe width of the color to be detected.\n\n28\n00:01:06.937 --> 00:01:08.272\nIncreasing the width means\n\n29\n00:01:08.272 --> 00:01:11.317\nincluding lighter and\ndarker shades of color.\n\n30\n00:01:11.317 --> 00:01:13.736\nNow that the Vision Sensor has been tuned,\n\n31\n00:01:13.736 --> 00:01:17.239\nit should more easily\ndetect the blue object.\n\n32\n00:01:17.239 --> 00:01:19.200\nAnother way to tune the Vision Sensor\n\n33\n00:01:19.200 --> 00:01:21.035\nis to change the brightness.\n\n34\n00:01:21.035 --> 00:01:23.704\nChanging the brightness\nincreases or decreases\n\n35\n00:01:23.704 --> 00:01:26.415\nthe Vision Sensor's sensitivity to light.\n\n36\n00:01:26.415 --> 00:01:29.502\nAdjusting the brightness\naffects all colors.\n\n37\n00:01:29.502 --> 00:01:30.503\nAdjusting the brightness\n\n38\n00:01:30.503 --> 00:01:32.004\nand increasing the width of the color\n\n39\n00:01:32.004 --> 00:01:33.923\ndetected by the Vision Sensor,\n\n40\n00:01:33.923 --> 00:01:35.758\nshould tune the Vision Sensor\n\n41\n00:01:35.758 --> 00:01:38.094\nso it can be used in\ndifferent environments.\n\n42\n00:01:39.053 --> 00:01:42.098\nHowever, if neither of these\noptions solve the problem,\n\n43\n00:01:42.098 --> 00:01:43.557\nclear the color signature\n\n44\n00:01:43.557 --> 00:01:47.561\nand then retrain the objects.\n\n45\n00:01:47.561 --> 00:01:49.063\nTuning will allow you to use\n\n46\n00:01:49.063 --> 00:01:52.149\nyour Vision Sensor projects\nin any environment.\n\n","ar":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nيمكن استخدام جهاز استشعار الرؤية\nلرؤية الأجسام\n\n2\n00:00:03.124 --> 00:00:04.959\nوالسماح للروبوت الخاص بك بالتفاعل\n\n3\n00:00:04.959 --> 00:00:07.003\nمع العالم حوله.\n\n4\n00:00:07.003 --> 00:00:09.630\nفي بعض الأحيان، قد يواجه الروبوت\nصعوبة\n\n5\n00:00:09.630 --> 00:00:11.591\nفي اكتشاف الكائنات المعروفة.\n\n6\n00:00:11.591 --> 00:00:13.968\nويرجع ذلك في كثير من الأحيان إلى تغير في الإضاءة.\n\n7\n00:00:14.802 --> 00:00:16.053\nلحل هذه المشكلة،\n\n8\n00:00:16.053 --> 00:00:18.347\nقد تحتاج إلى ضبط جهاز استشعار الرؤية الخاص بك.\n\n9\n00:00:18.347 --> 00:00:22.059\nيمكنك ضبط مستشعر الرؤية\nباستخدام خدمة الرؤية.\n\n10\n00:00:22.059 --> 00:00:23.185\nفي هذا البرنامج التعليمي،\n\n11\n00:00:23.185 --> 00:00:26.314\nسوف نستخدم \nالكاشف عن الأجسام (الرؤية)\n\n12\n00:00:26.314 --> 00:00:28.149\nمثال للمشروع.\n\n13\n00:00:28.149 --> 00:00:31.319\nفي هذا المشروع، تم تكوين جهاز استشعار الرؤية\n\n14\n00:00:31.319 --> 00:00:35.865\nللكشف عن جسم أزرق أو أحمر أو أخضر.\n\n15\n00:00:35.865 --> 00:00:37.575\nلضبط مستشعر الرؤية ،\n\n16\n00:00:37.575 --> 00:00:40.911\nضع جسما معروفاً\nأمام مستشعر الرؤية.\n\n17\n00:00:40.911 --> 00:00:43.164\nوهنا، ينبغي أن يكشف مستشعر الرؤية\n\n18\n00:00:43.164 --> 00:00:45.249\nأن هذا الجسم اأزرق.\n\n19\n00:00:45.249 --> 00:00:48.252\nلكن ، مع تغير ظروف الإضاءة\n\n20\n00:00:48.252 --> 00:00:49.920\nيواجه مستشعر الرؤية مشكلة\n\n21\n00:00:49.920 --> 00:00:52.381\nالكشف عن الجسم الأزرق.\n\n22\n00:00:52.381 --> 00:00:54.133\nالبدء في ضبط مستشعر الرؤية\n\n23\n00:00:54.133 --> 00:00:57.511\nعن طريق تحديد لون العينة \nللجسم الأزرق\n\n24\n00:00:57.511 --> 00:00:59.513\nو تعديل الشريط.\n\n25\n00:00:59.513 --> 00:01:03.392\nحرك الشريط لكشف\nالمزيد من الجسم الأزرق.\n\n26\n00:01:03.392 --> 00:01:04.560\nشريط التمرير يحدد\n\n27\n00:01:04.560 --> 00:01:06.937\nعرض اللون المراد اكتشافه.\n\n28\n00:01:06.937 --> 00:01:08.272\nزيادة عرض الوسائل\n\n29\n00:01:08.272 --> 00:01:11.317\nبما في ذلك ظلال أفتح وأغمق.\n\n30\n00:01:11.317 --> 00:01:13.736\nالآن بعد أن تم ضبط مستشعر الرؤية،\n\n31\n00:01:13.736 --> 00:01:17.239\nيجب أن يكون أكثر سهولة\nفي اكتشاف الجسم الأزرق.\n\n32\n00:01:17.239 --> 00:01:19.200\nطريقة أخرى لضبط مستشعر الرؤية\n\n33\n00:01:19.200 --> 00:01:21.035\nهو تغيير السطوع.\n\n34\n00:01:21.035 --> 00:01:23.704\nتغيير السطوع\nيزيد أو ينقص\n\n35\n00:01:23.704 --> 00:01:26.415\nحساسية مستشعر الرؤية للضوء.\n\n36\n00:01:26.415 --> 00:01:29.502\nتعديل السطوع\nيؤثر على جميع الألوان.\n\n37\n00:01:29.502 --> 00:01:30.503\nضبط السطوع\n\n38\n00:01:30.503 --> 00:01:32.004\nوزيادة عرض اللون\n\n39\n00:01:32.004 --> 00:01:33.923\nيتم اكتشافه من قبل مستشعر الرؤية،\n\n40\n00:01:33.923 --> 00:01:35.758\nلضبط مستشعر الرؤية ،\n\n41\n00:01:35.758 --> 00:01:38.094\nحتى يمكن استخدامه في\nبيئات مختلفة.\n\n42\n00:01:39.053 --> 00:01:42.098\nومع ذلك، إذا لم يكن أي من هذه الخيارات\nحلا للمشكلة\n\n43\n00:01:42.098 --> 00:01:43.557\nامسح عينة اللون\n\n44\n00:01:43.557 --> 00:01:47.561\nثم إعادة تدريب الأشياء.\n\n45\n00:01:47.561 --> 00:01:49.063\nضبط سيسمح لك بالاستخدام\n\n46\n00:01:49.063 --> 00:01:52.149\nجهاز استشعار الرؤية الخاص بك\nفي أي بيئة.\n\n","cs":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nKamera může být použita k vidění objektů\n\n2\n00:00:03.124 --> 00:00:04.959\na umožňuje tvému robotovi interakci\n\n3\n00:00:04.959 --> 00:00:07.003\ns okolním světem.\n\n4\n00:00:07.003 --> 00:00:09.630\nObčas může mít robot problémy\n\n5\n00:00:09.630 --> 00:00:11.591\nvnímat známé objekty.\n\n6\n00:00:11.591 --> 00:00:13.968\nČasto je to kvůli změně osvětlení.\n\n7\n00:00:14.802 --> 00:00:16.053\nPro vyřešení tohoto problému\n\n8\n00:00:16.053 --> 00:00:18.347\nmožná budeš muset seřídit svoji Kameru.\n\n9\n00:00:18.347 --> 00:00:22.059\nKameru může seřídit\npomocí Nastavení kamery.\n\n10\n00:00:22.059 --> 00:00:23.185\nV tomto výukovém videu\n\n11\n00:00:23.185 --> 00:00:26.314\nbudeme používat\nDetekce objektů (Kamera)\n\n12\n00:00:26.314 --> 00:00:28.149\njako ukázkový projekt.\n\n13\n00:00:28.149 --> 00:00:31.319\nV tomto projektu je\nKamera nastavena\n\n14\n00:00:31.319 --> 00:00:35.865\npro detekci modrého, červeného nebo zeleného objektu.\n\n15\n00:00:35.865 --> 00:00:37.575\nPro seřízení Kamery\n\n16\n00:00:37.575 --> 00:00:40.911\numísti známý objekt\npřed Kameru.\n\n17\n00:00:40.911 --> 00:00:43.164\nTady by měla Kamera detekovat,\n\n18\n00:00:43.164 --> 00:00:45.249\nže je to modrý objekt.\n\n19\n00:00:45.249 --> 00:00:48.252\nAvšak protože se světelné\npodmínky změnily,\n\n20\n00:00:48.252 --> 00:00:49.920\nmá Kamera potíže\n\n21\n00:00:49.920 --> 00:00:52.381\ndetekovat modrý objekt.\n\n22\n00:00:52.381 --> 00:00:54.133\nSeřízení Kamery začni\n\n23\n00:00:54.133 --> 00:00:57.511\nvýběrem barevné\nsignatury modrého objektu\n\n24\n00:00:57.511 --> 00:00:59.513\na upravením posuvníku.\n\n25\n00:00:59.513 --> 00:01:03.392\nPohni s posuvníkem pro detekci\nvíce modrého objektu.\n\n26\n00:01:03.392 --> 00:01:04.560\nPosuvník určuje\n\n27\n00:01:04.560 --> 00:01:06.937\nšířku barevného pásma, které má být detekováno.\n\n28\n00:01:06.937 --> 00:01:08.272\nZvyšování šířky znamená\n\n29\n00:01:08.272 --> 00:01:11.317\nzahrnutí světlejších a\ntmavších odstínů barvy.\n\n30\n00:01:11.317 --> 00:01:13.736\nTeď, když byla Kamera seřízena,\n\n31\n00:01:13.736 --> 00:01:17.239\nby měla jednodušeji\ndetekovat modré objekty.\n\n32\n00:01:17.239 --> 00:01:19.200\nJiný způsob, jak Kameru seřídit,\n\n33\n00:01:19.200 --> 00:01:21.035\nje změnit jas.\n\n34\n00:01:21.035 --> 00:01:23.704\nZměna jasu\nzvyšuje nebo snižuje\n\n35\n00:01:23.704 --> 00:01:26.415\ncitlivost Kamery na světlo.\n\n36\n00:01:26.415 --> 00:01:29.502\nNastavení jasu\novlivňuje všechny barvy.\n\n37\n00:01:29.502 --> 00:01:30.503\nNastavení jasu\n\n38\n00:01:30.503 --> 00:01:32.004\na zvětšení šířky barevného pásma\n\n39\n00:01:32.004 --> 00:01:33.923\ndetekovaného Kamerou\n\n40\n00:01:33.923 --> 00:01:35.758\nby mělo Kameru seřídit tak,\n\n41\n00:01:35.758 --> 00:01:38.094\naby mohla být použita\nv různých prostředích.\n\n42\n00:01:39.053 --> 00:01:42.098\nAle jestliže žádná z těchto\nmožností problém nevyřeší,\n\n43\n00:01:42.098 --> 00:01:43.557\nsmaž barevnou signaturu\n\n44\n00:01:43.557 --> 00:01:47.561\na znovu vytrénuj dané objekty.\n\n45\n00:01:47.561 --> 00:01:49.063\nSeřízení ti umožní používat\n\n46\n00:01:49.063 --> 00:01:52.149\ntvé projekty s Kamerou\nv jakémkoliv prostředí.\n\n","de":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nEin Vision-Sensor kann verwendet werden,\n\n2\n00:00:03.124 --> 00:00:04.959\num Objekte zu sehen und deinem Roboter zu ermöglichen,\n\n3\n00:00:04.959 --> 00:00:07.003\nmit der Welt um ihn herum zu interagieren.\n\n4\n00:00:07.003 --> 00:00:09.630\nGelegentlich kann der Roboter\nSchwierigkeiten haben\n\n5\n00:00:09.630 --> 00:00:11.591\nbekannte Objekte zu erkennen.\n\n6\n00:00:11.591 --> 00:00:13.968\nDies ist meist auf eine Veränderung der Beleuchtung zurückzuführen.\n\n7\n00:00:14.802 --> 00:00:16.053\nUm das Problem zu lösen,\n\n8\n00:00:16.053 --> 00:00:18.347\nmuss vielleicht der Vision-Sensor neu eingestellt werden.\n\n9\n00:00:18.347 --> 00:00:22.059\nDu kannst den Vision-Sensor\nmit Vision Utility einstellen.\n\n10\n00:00:22.059 --> 00:00:23.185\nFür dieses Tutorial,\n\n11\n00:00:23.185 --> 00:00:26.314\nwerden wir die das Beispiel\n\n12\n00:00:26.314 --> 00:00:28.149\nObjekterkennung (Vision) verwenden.\n\n13\n00:00:28.149 --> 00:00:31.319\nIn diesem Projekt wurde der Vision\nSensor so konfiguriert\n\n14\n00:00:31.319 --> 00:00:35.865\num ein blaues, rotes oder grünes Objekt zu erkennen.\n\n15\n00:00:35.865 --> 00:00:37.575\nUm den Vision-Sensor anzupassen,\n\n16\n00:00:37.575 --> 00:00:40.911\nplatziere ein bekanntes Objekt\nvor dem Vision-Sensor.\n\n17\n00:00:40.911 --> 00:00:43.164\nHier sollte der Vision-Sensor erkennen\n\n18\n00:00:43.164 --> 00:00:45.249\ndass dies ein blaues Objekt ist.\n\n19\n00:00:45.249 --> 00:00:48.252\nJedoch haben sich die Beleuchtung-\nBedingungen geändert,\n\n20\n00:00:48.252 --> 00:00:49.920\nder Vision-Sensor hat Probleme\n\n21\n00:00:49.920 --> 00:00:52.381\ndas blaue Objekt erkennen.\n\n22\n00:00:52.381 --> 00:00:54.133\nUm den Vision-Sensor anzupassen\n\n23\n00:00:54.133 --> 00:00:57.511\nwird die Farb-Signatur\ndes blauen Objekts ausgewählt\n\n24\n00:00:57.511 --> 00:00:59.513\nund über den Schieberegler angepasst.\n\n25\n00:00:59.513 --> 00:01:03.392\nVerschiebe den Schieberegler, um\nmehr des blauen Objekts zu erkennen.\n\n26\n00:01:03.392 --> 00:01:04.560\nDer Schieberegler bestimmt\n\n27\n00:01:04.560 --> 00:01:06.937\ndie Breite der zu ermittelnden Farbe.\n\n28\n00:01:06.937 --> 00:01:08.272\nErhöhen der Breite bedeutet\n\n29\n00:01:08.272 --> 00:01:11.317\ndas einschließen heller und\ndunkler Farbtöne.\n\n30\n00:01:11.317 --> 00:01:13.736\nJetzt, da der Vision-Sensor abgestimmt wurde,\n\n31\n00:01:13.736 --> 00:01:17.239\nsollte es einfacher sein\ndas blaue Objekt zu erkennen.\n\n32\n00:01:17.239 --> 00:01:19.200\nEin anderer Weg um den Vision-Sensor anzupassen\n\n33\n00:01:19.200 --> 00:01:21.035\nist, die Helligkeit zu ändern.\n\n34\n00:01:21.035 --> 00:01:23.704\nDas Ändern der Helligkeit\nerhöht oder verringert\n\n35\n00:01:23.704 --> 00:01:26.415\ndie Empfindlichkeit des Vision Sensors gegenüber Licht.\n\n36\n00:01:26.415 --> 00:01:29.502\nDie Anpassung der Helligkeit\nwirkt sich auf alle Farben aus.\n\n37\n00:01:29.502 --> 00:01:30.503\nHelligkeit anpassen\n\n38\n00:01:30.503 --> 00:01:32.004\nund die Breite der Farbe erhöhen\n\n39\n00:01:32.004 --> 00:01:33.923\nwerden vom Vision-Sensor erkannt\n\n40\n00:01:33.923 --> 00:01:35.758\nund sollten den Vision-Sensor anpassen\n\n41\n00:01:35.758 --> 00:01:38.094\ndamit er in\nverschiedenen Umgebungen verwendet werden kann.\n\n42\n00:01:39.053 --> 00:01:42.098\nWenn jedoch keine dieser\nOptionen das Problem löst\n\n43\n00:01:42.098 --> 00:01:43.557\nleere die Farbsignatur\n\n44\n00:01:43.557 --> 00:01:47.561\nund dann die Objekte neu zu definieren.\n\n45\n00:01:47.561 --> 00:01:49.063\nTuning erlaubt es dir\n\n46\n00:01:49.063 --> 00:01:52.149\nden Vision Sensor in jeder\nUmgebung einzusetzen.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nUn sensor de visión\npuede ser usado para ver objetos\n\n2\n00:00:03.124 --> 00:00:04.959\ny permitir que su robot interactúe\n\n3\n00:00:04.959 --> 00:00:07.003\ncon el todo a su alrededor.\n\n4\n00:00:07.003 --> 00:00:09.630\nOcasionalmente, el robot\npuede tener dificultad\n\n5\n00:00:09.630 --> 00:00:11.591\ndetectando objetos conocidos.\n\n6\n00:00:11.591 --> 00:00:13.968\nEsto se debe generalmente a un cambio en la iluminación.\n\n7\n00:00:14.802 --> 00:00:16.053\nPara resolver este problema,\n\n8\n00:00:16.053 --> 00:00:18.347\npuede que tenga que ajustar su Sensor de Visión.\n\n9\n00:00:18.347 --> 00:00:22.059\nPuede ajustar el Sensor de Visión\nusando la Utilidad de Visión.\n\n10\n00:00:22.059 --> 00:00:23.185\nEn este tutorial\n\n11\n00:00:23.185 --> 00:00:26.314\nusaremos el proyecto de ejemplo\n\n12\n00:00:26.314 --> 00:00:28.149\nde Detección de Objetos (Visión).\n\n13\n00:00:28.149 --> 00:00:31.319\nEn este proyecto, se ha \nconfigurado el Sensor de Visión\n\n14\n00:00:31.319 --> 00:00:35.865\npara detectar un objeto azul, rojo, o verde.\n\n15\n00:00:35.865 --> 00:00:37.575\nPara afinar el Sensor de Visión,\n\n16\n00:00:37.575 --> 00:00:40.911\ncoloca un objeto conocido en\nfrente del Sensor de Visión.\n\n17\n00:00:40.911 --> 00:00:43.164\nAquí, el Sensor de Visión debe detectar\n\n18\n00:00:43.164 --> 00:00:45.249\nque este es un objeto azul.\n\n19\n00:00:45.249 --> 00:00:48.252\nSin embargo, como las condiciones de iluminación\nhan cambiado,\n\n20\n00:00:48.252 --> 00:00:49.920\nel Sensor de Visión está teniendo problemas\n\n21\n00:00:49.920 --> 00:00:52.381\ndetectando el objeto azul.\n\n22\n00:00:52.381 --> 00:00:54.133\nComience a ajustar el Sensor de Visión\n\n23\n00:00:54.133 --> 00:00:57.511\nseleccionando la firma del color\ndel objeto azul\n\n24\n00:00:57.511 --> 00:00:59.513\ny ajustando el deslizador.\n\n25\n00:00:59.513 --> 00:01:03.392\nMueve el deslizador para detectar\nmás del objeto azul.\n\n26\n00:01:03.392 --> 00:01:04.560\nEl deslizador determina\n\n27\n00:01:04.560 --> 00:01:06.937\nla anchura del color a ser detectado.\n\n28\n00:01:06.937 --> 00:01:08.272\nAumentar los medios de ancho\n\n29\n00:01:08.272 --> 00:01:11.317\ntonos de color más ligeros y\nmás oscuros serán incluidos.\n\n30\n00:01:11.317 --> 00:01:13.736\nAhora que el Sensor de Visión ha sido afinado,\n\n31\n00:01:13.736 --> 00:01:17.239\ndetectar el objeto azul debería ser más fácil.\n\n32\n00:01:17.239 --> 00:01:19.200\nOtra manera de afinar el Sensor de Visión\n\n33\n00:01:19.200 --> 00:01:21.035\nes cambiar el brillo.\n\n34\n00:01:21.035 --> 00:01:23.704\nCambiar el brillo\naumenta o disminuye\n\n35\n00:01:23.704 --> 00:01:26.415\nla sensibilidad del Sensor de Visión a la luz.\n\n36\n00:01:26.415 --> 00:01:29.502\nAjustar el brillo\nafecta a todos los colores.\n\n37\n00:01:29.502 --> 00:01:30.503\nAjustar el brillo\n\n38\n00:01:30.503 --> 00:01:32.004\ny aumentando el ancho del color\n\n39\n00:01:32.004 --> 00:01:33.923\ndetectado por el Sensor de Visión,\n\n40\n00:01:33.923 --> 00:01:35.758\ndebería afinar el Sensor de Visión\n\n41\n00:01:35.758 --> 00:01:38.094\npara que se pueda utilizar en\nentornos diferentes.\n\n42\n00:01:39.053 --> 00:01:42.098\nSin embargo, si ninguna de estas\nopciones resuelve el problema,\n\n43\n00:01:42.098 --> 00:01:43.557\nborre la firma de color\n\n44\n00:01:43.557 --> 00:01:47.561\ny luego volver a entrenar los objetos.\n\n45\n00:01:47.561 --> 00:01:49.063\nAfinar le permitirá usar\n\n46\n00:01:49.063 --> 00:01:52.149\nsu proyecto con el Sensor de \nVisión en cualquier entorno.\n\n","es":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nUn sensor de visión\npuede ser usado para ver objetos\n\n2\n00:00:03.124 --> 00:00:04.959\ny permitir que su robot interactúe\n\n3\n00:00:04.959 --> 00:00:07.003\ncon el todo a su alrededor.\n\n4\n00:00:07.003 --> 00:00:09.630\nOcasionalmente, el robot\npuede tener dificultad\n\n5\n00:00:09.630 --> 00:00:11.591\ndetectando objetos conocidos.\n\n6\n00:00:11.591 --> 00:00:13.968\nEsto se debe generalmente a un cambio en la iluminación.\n\n7\n00:00:14.802 --> 00:00:16.053\nPara resolver este problema,\n\n8\n00:00:16.053 --> 00:00:18.347\npuede que tenga que ajustar su Sensor de Visión.\n\n9\n00:00:18.347 --> 00:00:22.059\nPuede ajustar el Sensor de Visión\nusando la Utilidad de Visión.\n\n10\n00:00:22.059 --> 00:00:23.185\nEn este tutorial\n\n11\n00:00:23.185 --> 00:00:26.314\nusaremos el proyecto de ejemplo\n\n12\n00:00:26.314 --> 00:00:28.149\nde Detección de Objetos (Visión).\n\n13\n00:00:28.149 --> 00:00:31.319\nEn este proyecto, se ha \nconfigurado el Sensor de Visión\n\n14\n00:00:31.319 --> 00:00:35.865\npara detectar un objeto azul, rojo, o verde.\n\n15\n00:00:35.865 --> 00:00:37.575\nPara afinar el Sensor de Visión,\n\n16\n00:00:37.575 --> 00:00:40.911\ncoloca un objeto conocido en\nfrente del Sensor de Visión.\n\n17\n00:00:40.911 --> 00:00:43.164\nAquí, el Sensor de Visión debe detectar\n\n18\n00:00:43.164 --> 00:00:45.249\nque este es un objeto azul.\n\n19\n00:00:45.249 --> 00:00:48.252\nSin embargo, como las condiciones de iluminación\nhan cambiado,\n\n20\n00:00:48.252 --> 00:00:49.920\nel Sensor de Visión está teniendo problemas\n\n21\n00:00:49.920 --> 00:00:52.381\ndetectando el objeto azul.\n\n22\n00:00:52.381 --> 00:00:54.133\nComience a ajustar el Sensor de Visión\n\n23\n00:00:54.133 --> 00:00:57.511\nseleccionando la firma del color\ndel objeto azul\n\n24\n00:00:57.511 --> 00:00:59.513\ny ajustando el deslizador.\n\n25\n00:00:59.513 --> 00:01:03.392\nMueve el deslizador para detectar\nmás del objeto azul.\n\n26\n00:01:03.392 --> 00:01:04.560\nEl deslizador determina\n\n27\n00:01:04.560 --> 00:01:06.937\nla anchura del color a ser detectado.\n\n28\n00:01:06.937 --> 00:01:08.272\nAumentar los medios de ancho\n\n29\n00:01:08.272 --> 00:01:11.317\ntonos de color más ligeros y\nmás oscuros serán incluidos.\n\n30\n00:01:11.317 --> 00:01:13.736\nAhora que el Sensor de Visión ha sido afinado,\n\n31\n00:01:13.736 --> 00:01:17.239\ndetectar el objeto azul debería ser más fácil.\n\n32\n00:01:17.239 --> 00:01:19.200\nOtra manera de afinar el Sensor de Visión\n\n33\n00:01:19.200 --> 00:01:21.035\nes cambiar el brillo.\n\n34\n00:01:21.035 --> 00:01:23.704\nCambiar el brillo\naumenta o disminuye\n\n35\n00:01:23.704 --> 00:01:26.415\nla sensibilidad del Sensor de Visión a la luz.\n\n36\n00:01:26.415 --> 00:01:29.502\nAjustar el brillo\nafecta a todos los colores.\n\n37\n00:01:29.502 --> 00:01:30.503\nAjustar el brillo\n\n38\n00:01:30.503 --> 00:01:32.004\ny aumentando el ancho del color\n\n39\n00:01:32.004 --> 00:01:33.923\ndetectado por el Sensor de Visión,\n\n40\n00:01:33.923 --> 00:01:35.758\ndebería afinar el Sensor de Visión\n\n41\n00:01:35.758 --> 00:01:38.094\npara que se pueda utilizar en\nentornos diferentes.\n\n42\n00:01:39.053 --> 00:01:42.098\nSin embargo, si ninguna de estas\nopciones resuelve el problema,\n\n43\n00:01:42.098 --> 00:01:43.557\nborre la firma de color\n\n44\n00:01:43.557 --> 00:01:47.561\ny luego volver a entrenar los objetos.\n\n45\n00:01:47.561 --> 00:01:49.063\nAfinar le permitirá usar\n\n46\n00:01:49.063 --> 00:01:52.149\nsu proyecto con el Sensor de \nVisión en cualquier entorno.\n\n","fi":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nVision Kamera havaitsee kohteita\n\n2\n00:00:03.124 --> 00:00:04.959\nja robotti voi sen keskustella\n\n3\n00:00:04.959 --> 00:00:07.003\nympäröivän maailman kanssa.\n\n4\n00:00:07.003 --> 00:00:09.630\nVälillä robotilla voi olla vaikeuksia\n\n5\n00:00:09.630 --> 00:00:11.591\nhavaita etsittyjä esineitä.\n\n6\n00:00:11.591 --> 00:00:13.968\nSyynä on yleensä valaistus.\n\n7\n00:00:14.802 --> 00:00:16.053\nVoit ratkaista tätä ongelmaa\n\n8\n00:00:16.053 --> 00:00:18.347\nsäätämällä Vision Kameraa.\n\n9\n00:00:18.347 --> 00:00:22.059\nSäätäminen tehdään kameran Vision Utility-toiminnolla.\n\n10\n00:00:22.059 --> 00:00:23.185\nTässä ohjeessa\n\n11\n00:00:23.185 --> 00:00:26.314\nkäytämme Määritä (Vision) toimintoa\n\n12\n00:00:26.314 --> 00:00:28.149\nesimerkkinä.\n\n13\n00:00:28.149 --> 00:00:31.319\nTässä ohjelmassa Vision kameraa on määritelty\n\n14\n00:00:31.319 --> 00:00:35.865\nhavaitsemaan sininen, punainen ja vihreä esine.\n\n15\n00:00:35.865 --> 00:00:37.575\nAloita Vision Kameran säätö\n\n16\n00:00:37.575 --> 00:00:40.911\nlaittamalla kameran eteen etsitty esine.\n\n17\n00:00:40.911 --> 00:00:43.164\nVision Kameran pitäsi havaita\n\n18\n00:00:43.164 --> 00:00:45.249\nsininen esine.\n\n19\n00:00:45.249 --> 00:00:48.252\nKun valaistusolosuhteet on muuttuneet\n\n20\n00:00:48.252 --> 00:00:49.920\nVision Kameralla on vaikeuksia\n\n21\n00:00:49.920 --> 00:00:52.381\nhavaita sininen esine.\n\n22\n00:00:52.381 --> 00:00:54.133\nAloita Vision Kameran säätö\n\n23\n00:00:54.133 --> 00:00:57.511\nvalitsemalla sinisen esineen tallennettu merkki\n\n24\n00:00:57.511 --> 00:00:59.513\nja säädä sen vieressä olevaa liukusäätöä.\n\n25\n00:00:59.513 --> 00:01:03.392\nLiukua siirtämällä oikealla kamera näkee paremmin sinistä väriä.\n\n26\n00:01:03.392 --> 00:01:04.560\nLiukusäädin määrää\n\n27\n00:01:04.560 --> 00:01:06.937\nvärisävyn havaitsemisleveyden spektrissä.\n\n28\n00:01:06.937 --> 00:01:08.272\nKasvattamalla leveyttä\n\n29\n00:01:08.272 --> 00:01:11.317\nniin himmeämmät ja tummemmat värisävyt väristä tulee mukaan esineen merkkiin.\n\n30\n00:01:11.317 --> 00:01:13.736\nKun Vision Kameraa on säädetty\n\n31\n00:01:13.736 --> 00:01:17.239\nkameran pitäisi havaita paremmin sinisen esineen.\n\n32\n00:01:17.239 --> 00:01:19.200\nToinen tapa virittää Vision Kameraa\n\n33\n00:01:19.200 --> 00:01:21.035\non muuttaa valaistuksen kirkkautta.\n\n34\n00:01:21.035 --> 00:01:23.704\nValaistuksen voimakkuutta muuttamalla\n\n35\n00:01:23.704 --> 00:01:26.415\nVision Kamera on herkempi valolle.\n\n36\n00:01:26.415 --> 00:01:29.502\nSäätämällä valon voimakkuutta vaikuttaa väreihin.\n\n37\n00:01:29.502 --> 00:01:30.503\nSäätämällä valovoimaa\n\n38\n00:01:30.503 --> 00:01:32.004\nja lisäämällä samalla värin leveyttä valon spektrissä\n\n39\n00:01:32.004 --> 00:01:33.923\njonka Vision Kameraa havaitsee\n\n40\n00:01:33.923 --> 00:01:35.758\nsäätää samalla kameraa\n\n41\n00:01:35.758 --> 00:01:38.094\nniin että voit käyttää sitä eri ympäristöissä.\n\n42\n00:01:39.053 --> 00:01:42.098\nJos kumpikaan toimenpide ei ratkaise esineen havaitsemisongelmaa\n\n43\n00:01:42.098 --> 00:01:43.557\npoista esineen merkki Vision Utility-ikkunassa\n\n44\n00:01:43.557 --> 00:01:47.561\nja tee säätö uudelleen.\n\n45\n00:01:47.561 --> 00:01:49.063\nSäätämällä värisävyn leveyttä ja valaistusta\n\n46\n00:01:49.063 --> 00:01:52.149\nVision Kamera toimii paremmin joka tilanteissa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nUn Capteur de Vision\npeut être utilisé pour voir des objets\n\n2\n00:00:03.124 --> 00:00:04.959\net permettre à votre robot d'interagir\n\n3\n00:00:04.959 --> 00:00:07.003\navec le monde autour de lui.\n\n4\n00:00:07.003 --> 00:00:09.630\nParfois, le robot\npeut avoir de la difficulté\n\n5\n00:00:09.630 --> 00:00:11.591\nà détecter des objets connus.\n\n6\n00:00:11.591 --> 00:00:13.968\nCeci est souvent dû à un changement d'éclairage.\n\n7\n00:00:14.802 --> 00:00:16.053\nPour résoudre ce problème,\n\n8\n00:00:16.053 --> 00:00:18.347\nvous devrez peut-être régler votre Capteur de Vision.\n\n9\n00:00:18.347 --> 00:00:22.059\nVous pouvez régler le Capteur de Vision\nà l'aide de l'Utilitaire Vision.\n\n10\n00:00:22.059 --> 00:00:23.185\nDans ce tutoriel,\n\n11\n00:00:23.185 --> 00:00:26.314\nnous utiliserons l'exemple de projet\n\n12\n00:00:26.314 --> 00:00:28.149\nDétection d'Objet(Vision).\n\n13\n00:00:28.149 --> 00:00:31.319\nDans ce projet, le Détecteur de Vision\na été configuré\n\n14\n00:00:31.319 --> 00:00:35.865\npour détecter un objet bleu, rouge ou vert.\n\n15\n00:00:35.865 --> 00:00:37.575\nPour régler le Capteur de Vision,\n\n16\n00:00:37.575 --> 00:00:40.911\nplacez un objet connu\ndevant le Capteur de Vision.\n\n17\n00:00:40.911 --> 00:00:43.164\nIci, le Capteur de Vision devrait détecter\n\n18\n00:00:43.164 --> 00:00:45.249\nqu'il s'agit d'un objet bleu.\n\n19\n00:00:45.249 --> 00:00:48.252\nCependant, depuis que les conditions d'éclairage\nont changé,\n\n20\n00:00:48.252 --> 00:00:49.920\nle Capteur de Vision a des difficultés\n\n21\n00:00:49.920 --> 00:00:52.381\nà détecter l'objet bleu.\n\n22\n00:00:52.381 --> 00:00:54.133\nCommencez à ajuster le Capteur de Vision\n\n23\n00:00:54.133 --> 00:00:57.511\nen sélectionnant la signature\nde la couleur de l'objet bleu\n\n24\n00:00:57.511 --> 00:00:59.513\net en ajustant le curseur.\n\n25\n00:00:59.513 --> 00:01:03.392\nDéplacez le curseur pour\ndétecter plus de l'objet bleu.\n\n26\n00:01:03.392 --> 00:01:04.560\nLe curseur détermine\n\n27\n00:01:04.560 --> 00:01:06.937\nl'étendue de la couleur à détecter.\n\n28\n00:01:06.937 --> 00:01:08.272\nAugmenter l'étendue signifie\n\n29\n00:01:08.272 --> 00:01:11.317\najouter des teintes plus claires et plus sombres de la couleur.\n\n30\n00:01:11.317 --> 00:01:13.736\nMaintenant que le Capteur de Vision a été ajusté,\n\n31\n00:01:13.736 --> 00:01:17.239\nil devrait plus facilement\ndétecter l'objet bleu.\n\n32\n00:01:17.239 --> 00:01:19.200\nUne autre façon d'ajuster le Capteur de Vision\n\n33\n00:01:19.200 --> 00:01:21.035\nconsiste à changer la luminosité.\n\n34\n00:01:21.035 --> 00:01:23.704\nChanger la luminosité\naugmente ou diminue\n\n35\n00:01:23.704 --> 00:01:26.415\nla sensibilité à la lumière du Capteur de Vision.\n\n36\n00:01:26.415 --> 00:01:29.502\nAjuster la luminosité\naffecte toutes les couleurs.\n\n37\n00:01:29.502 --> 00:01:30.503\nAjuster la luminosité\n\n38\n00:01:30.503 --> 00:01:32.004\net augmenter l'étendue de la couleur\n\n39\n00:01:32.004 --> 00:01:33.923\ndétectée par le Capteur de Vision,\n\n40\n00:01:33.923 --> 00:01:35.758\ndoit permettre au Capteur de Vision\n\n41\n00:01:35.758 --> 00:01:38.094\nd'être utilisé dans des\nenvironnements différents.\n\n42\n00:01:39.053 --> 00:01:42.098\nCependant, si aucune de ces options\nne résout le problème,\n\n43\n00:01:42.098 --> 00:01:43.557\neffacez la signature de la couleur\n\n44\n00:01:43.557 --> 00:01:47.561\npuis entraînez à nouveau à la reconnaissance des objets.\n\n45\n00:01:47.561 --> 00:01:49.063\nCes réglages vous permettront d'utiliser\n\n46\n00:01:49.063 --> 00:01:52.149\nvos projets utilisant le Capteur de Vision\ndans n'importe quel environnement.\n\n","hu-HU":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nA látás érzékelő \nhasználható tárgyak megtekintésére\n\n2\n00:00:03.124 --> 00:00:04.959\nés lehetővé teszi a robotnak, hogy kapcsolatba lépjen\n\n3\n00:00:04.959 --> 00:00:07.003\na körülötte lévő világgal.\n\n4\n00:00:07.003 --> 00:00:09.630\nEsetenként a robotnak\nnehézségei lehetnek\n\n5\n00:00:09.630 --> 00:00:11.591\nismert tárgyak felderítésével.\n\n6\n00:00:11.591 --> 00:00:13.968\nEnnek oka gyakran a világítás megváltozása.\n\n7\n00:00:14.802 --> 00:00:16.053\nA probléma megoldásához\n\n8\n00:00:16.053 --> 00:00:18.347\nlehet, hogy be kell hangolnia a látás érzékelőt.\n\n9\n00:00:18.347 --> 00:00:22.059\nBeállíthatja a látás érzékelőt\na látási segédprogram használatával.\n\n10\n00:00:22.059 --> 00:00:23.185\nEbben az oktatóanyagban\n\n11\n00:00:23.185 --> 00:00:26.314\nhasználni fogjuk az\nObjektumok Észlelése (látás)\n\n12\n00:00:26.314 --> 00:00:28.149\npélda projektet.\n\n13\n00:00:28.149 --> 00:00:31.319\nEbben a projektben a látás érzékelő \nkonfigurálása megtörtént ahhoz, hogy\n\n14\n00:00:31.319 --> 00:00:35.865\nkék, piros vagy zöld tárgyat észleljen.\n\n15\n00:00:35.865 --> 00:00:37.575\nA látás érzékelő beállításához\n\n16\n00:00:37.575 --> 00:00:40.911\nelőször helyezzen el egy ismert \ntárgyat a látás érzékelő elé.\n\n17\n00:00:40.911 --> 00:00:43.164\nItt a látás érzékelőnek észlelnie kell azt,\n\n18\n00:00:43.164 --> 00:00:45.249\nhogy ez egy kék tárgy.\n\n19\n00:00:45.249 --> 00:00:48.252\nAzonban, mivel a világítási\nkörülmények megváltoztak,\n\n20\n00:00:48.252 --> 00:00:49.920\na látás érzékelőnek gondjai lesznek\n\n21\n00:00:49.920 --> 00:00:52.381\na kék tárgy észlelésével.\n\n22\n00:00:52.381 --> 00:00:54.133\nA látás érzékelő beállítását\n\n23\n00:00:54.133 --> 00:00:57.511\negy kék tárgy szín aláírásának \nkiválasztásával kezdjük\n\n24\n00:00:57.511 --> 00:00:59.513\nés a csúszka beállításával.\n\n25\n00:00:59.513 --> 00:01:03.392\nMozgassa a csúszkát a kék \nobjektum több részének észleléséhez.\n\n26\n00:01:03.392 --> 00:01:04.560\nA csúszka meghatározza\n\n27\n00:01:04.560 --> 00:01:06.937\naz észlelhető szín szélességét.\n\n28\n00:01:06.937 --> 00:01:08.272\nA szélesség növelése\n\n29\n00:01:08.272 --> 00:01:11.317\na világosabb és sötétebb színárnyalatokat is magában foglalja.\n\n30\n00:01:11.317 --> 00:01:13.736\nMost, hogy a látás érzékelő be lett állítva,\n\n31\n00:01:13.736 --> 00:01:17.239\nkönnyebben észlelheti \na kék tárgyat.\n\n32\n00:01:17.239 --> 00:01:19.200\nEgy másik lehetőség a látás érzékelő beállításához\n\n33\n00:01:19.200 --> 00:01:21.035\na fényerő megváltoztatása.\n\n34\n00:01:21.035 --> 00:01:23.704\nA fényerő megváltoztatása\nnöveli vagy csökkenti\n\n35\n00:01:23.704 --> 00:01:26.415\na látás érzékelő fényérzékenységét.\n\n36\n00:01:26.415 --> 00:01:29.502\nA fényerő beállítása\nminden színre hatással van.\n\n37\n00:01:29.502 --> 00:01:30.503\nA fényerő beállítása\n\n38\n00:01:30.503 --> 00:01:32.004\naz észlelt szín szélességének növelése,\n\n39\n00:01:32.004 --> 00:01:33.923\na látás érzékelő által\n\n40\n00:01:33.923 --> 00:01:35.758\nbe kellene állítsa a látás érzékelőt\n\n41\n00:01:35.758 --> 00:01:38.094\nígy különböző környezetben \nis lehet használni.\n\n42\n00:01:39.053 --> 00:01:42.098\nHa azonban egyik lehetőség sem oldja meg a problémát,\n\n43\n00:01:42.098 --> 00:01:43.557\ntörölje a szín aláírását\n\n44\n00:01:43.557 --> 00:01:47.561\nmajd tanítsa újra az objektumokat.\n\n45\n00:01:47.561 --> 00:01:49.063\nA beállítás lehetővé teszi, hogy\n\n46\n00:01:49.063 --> 00:01:52.149\na látás érzékelő minden \nkörnyezetben működjön.\n\n","ko":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\n비전 센서는 물체를 보는 데 사용되고\n\n2\n00:00:03.124 --> 00:00:04.959\n로봇이 주위와\n\n3\n00:00:04.959 --> 00:00:07.003\n상호 작용할 수 있게 합니다.\n\n4\n00:00:07.003 --> 00:00:09.630\n때때로 로봇은 물체를 감지하는 데\n\n5\n00:00:09.630 --> 00:00:11.591\n어려움을 겪을 수 있습니다.\n\n6\n00:00:11.591 --> 00:00:13.968\n이것은 주로 조명의 변화 때문입니다.\n\n7\n00:00:14.802 --> 00:00:16.053\n이 문제를 해결하기 위해서\n\n8\n00:00:16.053 --> 00:00:18.347\n비전 센서를 조정해야 합니다.\n\n9\n00:00:18.347 --> 00:00:22.059\n비전 유틸리티를 사용하여 비전 센서를 조정할 수 있습니다.\n\n10\n00:00:22.059 --> 00:00:23.185\n이 사용 지침서에서는\n\n11\n00:00:23.185 --> 00:00:26.314\n물체 감지 (비전 센서) 예제 프로젝트를\n\n12\n00:00:26.314 --> 00:00:28.149\n사용합니다.\n\n13\n00:00:28.149 --> 00:00:31.319\n이 프로젝트에서 비전 센서는\n\n14\n00:00:31.319 --> 00:00:35.865\n파란색과 빨간색, 초록색 물체를 감지하도록 구성되어 있습니다.\n\n15\n00:00:35.865 --> 00:00:37.575\n비전 센서를 조정하려면\n\n16\n00:00:37.575 --> 00:00:40.911\n비전 센서 앞에 물체를 놓습니다.\n\n17\n00:00:40.911 --> 00:00:43.164\n여기에서 비전 센서는\n\n18\n00:00:43.164 --> 00:00:45.249\n이것이 파란색 물체임을 감지해야 합니다.\n\n19\n00:00:45.249 --> 00:00:48.252\n그러나 조명 조건이 변경되어\n\n20\n00:00:48.252 --> 00:00:49.920\n비전 센서가 파란색 물체를 감지하는 데\n\n21\n00:00:49.920 --> 00:00:52.381\n문제가 있습니다.\n\n22\n00:00:52.381 --> 00:00:54.133\n파란색 물체의 대표 색상을 선택하고\n\n23\n00:00:54.133 --> 00:00:57.511\n슬라이드를 움직여\n\n24\n00:00:57.511 --> 00:00:59.513\n비전 센서 조정을 시작합니다.\n\n25\n00:00:59.513 --> 00:01:03.392\n파란색 물체를 더 많이 감지하려면 슬라이드를 움직입니다.\n\n26\n00:01:03.392 --> 00:01:04.560\n슬라이드는 감지할 색상의\n\n27\n00:01:04.560 --> 00:01:06.937\n너비를 결정합니다.\n\n28\n00:01:06.937 --> 00:01:08.272\n너비를 늘리면\n\n29\n00:01:08.272 --> 00:01:11.317\n더 밝고 더 어두운 색조가 포함됩니다.\n\n30\n00:01:11.317 --> 00:01:13.736\n이제 비전 센서가 조정되었으므로\n\n31\n00:01:13.736 --> 00:01:17.239\n파란색 물체를 더 쉽게 감지할 수 있습니다.\n\n32\n00:01:17.239 --> 00:01:19.200\n비전 센서를 조정하는\n\n33\n00:01:19.200 --> 00:01:21.035\n또 다른 방법은 밝기를 변경하는 것입니다.\n\n34\n00:01:21.035 --> 00:01:23.704\n밝기를 변경하면\n\n35\n00:01:23.704 --> 00:01:26.415\n빛에 대한 비전 센서의 감도가 증가하거나 감소합니다.\n\n36\n00:01:26.415 --> 00:01:29.502\n밝기를 조정하면 모든 색상에 영향을 줍니다.\n\n37\n00:01:29.502 --> 00:01:30.503\n비전 센서가 감지한 색상의 밝기를 조정하고\n\n38\n00:01:30.503 --> 00:01:32.004\n폭을 넓히기 위해\n\n39\n00:01:32.004 --> 00:01:33.923\n비전 센서를 조정하면\n\n40\n00:01:33.923 --> 00:01:35.758\n다른 환경에서\n\n41\n00:01:35.758 --> 00:01:38.094\n사용될 수 있습니다.\n\n42\n00:01:39.053 --> 00:01:42.098\n그러나 이러한 방법으로 문제가 해결되지 않는다면\n\n43\n00:01:42.098 --> 00:01:43.557\n대표 색상을 삭제하고\n\n44\n00:01:43.557 --> 00:01:47.561\n물체 감지를 다시 훈련 시키세요.\n\n45\n00:01:47.561 --> 00:01:49.063\n조정을 통해 모든 환경에서\n\n46\n00:01:49.063 --> 00:01:52.149\n비전 센서 프로젝트를 사용할 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nVaizdo jutikliu galima pamatyti objektus\n\n2\n00:00:03.124 --> 00:00:04.959\nir leisti robotui sąveikauti\n\n3\n00:00:04.959 --> 00:00:07.003\nsu aplinkiniu pasauliu.\n\n4\n00:00:07.003 --> 00:00:09.630\nKartais, robotui gali sunkiai sektis\n\n5\n00:00:09.630 --> 00:00:11.591\naptikti žinomus objektus.\n\n6\n00:00:11.591 --> 00:00:13.968\nDažnai tai susiję su apšvietimo pokyčiais.\n\n7\n00:00:14.802 --> 00:00:16.053\nŠiai problemai išspręsti,\n\n8\n00:00:16.053 --> 00:00:18.347\ngali reikėti sureguliuoti savo vaizdo jutiklį.\n\n9\n00:00:18.347 --> 00:00:22.059\nTai galite padaryti vaizdo programa.\n\n10\n00:00:22.059 --> 00:00:23.185\nŠiame pavyzdyje,\n\n11\n00:00:23.185 --> 00:00:26.314\nnaudosime pavyzdinį \"Objektų aptikimo (Vaizdo)\"\n\n12\n00:00:26.314 --> 00:00:28.149\nprojektą.\n\n13\n00:00:28.149 --> 00:00:31.319\nŠiame projekte, vaizdo jutiklis buvo sukonfigūruotas\n\n14\n00:00:31.319 --> 00:00:35.865\nmėlynam, raudonam ar žaliam objektui aptikti.\n\n15\n00:00:35.865 --> 00:00:37.575\nNorėdami sureguliuoti vaizdo jutiklį,\n\n16\n00:00:37.575 --> 00:00:40.911\nžinomą objektą padėkite priešais vaizdo jutiklį.\n\n17\n00:00:40.911 --> 00:00:43.164\nVaizdo jutiklis turėtų fiksuoti,\n\n18\n00:00:43.164 --> 00:00:45.249\nkad tai mėlynas objektas.\n\n19\n00:00:45.249 --> 00:00:48.252\nTačiau, kadangi apšvietimo sąlygos pasikeitė,\n\n20\n00:00:48.252 --> 00:00:49.920\nvaizdo jutikliui sunkiai sekasi\n\n21\n00:00:49.920 --> 00:00:52.381\naptikti mėlyną objektą.\n\n22\n00:00:52.381 --> 00:00:54.133\nPradėkite reguliuoti vaizdo jutiklį,\n\n23\n00:00:54.133 --> 00:00:57.511\npasirinkdami mėlyno objekto spalvos signatūrą\n\n24\n00:00:57.511 --> 00:00:59.513\nir reguliuodami slankiklį.\n\n25\n00:00:59.513 --> 00:01:03.392\nJudinkite slankiklį, kad aptiktumėte daugiau mėlyno objekto.\n\n26\n00:01:03.392 --> 00:01:04.560\nSlankiklis nustato\n\n27\n00:01:04.560 --> 00:01:06.937\naptinkamos spalvos plotį.\n\n28\n00:01:06.937 --> 00:01:08.272\nPločio didinimas reiškia\n\n29\n00:01:08.272 --> 00:01:11.317\nšviesesnių ir tamsesnių spalvos atspalvių įtraukimą.\n\n30\n00:01:11.317 --> 00:01:13.736\nSureguliavus vaizdo jutiklį,\n\n31\n00:01:13.736 --> 00:01:17.239\nmėlyną objektą aptikti turėtų būti lengviau.\n\n32\n00:01:17.239 --> 00:01:19.200\nVaizdo jutiklį taip pat galima reguliuoti\n\n33\n00:01:19.200 --> 00:01:21.035\nkeičiant ryškumą.\n\n34\n00:01:21.035 --> 00:01:23.704\nRyškumo keitimas padidina arba sumažina\n\n35\n00:01:23.704 --> 00:01:26.415\nvaizdo jutiklio jautrumą šviesai.\n\n36\n00:01:26.415 --> 00:01:29.502\nRyškumo reguliavimas daro įtaką visoms spalvoms.\n\n37\n00:01:29.502 --> 00:01:30.503\nRyškumo reguliavimas\n\n38\n00:01:30.503 --> 00:01:32.004\nir spalvos, kurią aptinka vaizdo jutiklis,\n\n39\n00:01:32.004 --> 00:01:33.923\ndidinimas,\n\n40\n00:01:33.923 --> 00:01:35.758\nturėtų sureguliuoti vaizdo jutiklį\n\n41\n00:01:35.758 --> 00:01:38.094\ntaip, kad jį būtų galima naudoti skirtingoje aplinkoje.\n\n42\n00:01:39.053 --> 00:01:42.098\nTačiau, jei nė vienas šių pasirinkimų problemos neišsprendžia,\n\n43\n00:01:42.098 --> 00:01:43.557\ništrinkite spalvos signatūrą\n\n44\n00:01:43.557 --> 00:01:47.561\nir išsaugokite objektus.\n\n45\n00:01:47.561 --> 00:01:49.063\nReguliavimas leis Jums\n\n46\n00:01:49.063 --> 00:01:52.149\nbet kurioje aplinkoje naudoti savo vaizdo jutiklį.\n\n","lv":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nAttēla sensoru var izmantot\nobjektu uztveršanai\n\n2\n00:00:03.124 --> 00:00:04.959\nun nodrošināt robota darbošanos\n\n3\n00:00:04.959 --> 00:00:07.003\napkārtējās pasaules vidē.\n\n4\n00:00:07.003 --> 00:00:09.630\nReizēm robotam\nvar būt grūtības\n\n5\n00:00:09.630 --> 00:00:11.591\nzināmu objektu noteikšanai.\n\n6\n00:00:11.591 --> 00:00:13.968\nTo bieži vien izraisa apgaismojuma izmaiņas.\n\n7\n00:00:14.802 --> 00:00:16.053\nLai atrisinātu šo problēmu,\n\n8\n00:00:16.053 --> 00:00:18.347\niespējams, būs jāregulē attēla sensors.\n\n9\n00:00:18.347 --> 00:00:22.059\nAttēla sensoru var noregulēt, \nizmantojot utilītu “Vision Utility”.\n\n10\n00:00:22.059 --> 00:00:23.185\nŠajā apmācībā\n\n11\n00:00:23.185 --> 00:00:26.314\nmēs izmantosim\n“Detecting Objects (Vision)”\n\n12\n00:00:26.314 --> 00:00:28.149\nparauga projektu.\n\n13\n00:00:28.149 --> 00:00:31.319\nŠajā projektā attēla\nsensors ir konfigurēts,\n\n14\n00:00:31.319 --> 00:00:35.865\nlai uztvertu zilu, sarkanu vai zaļu objektu.\n\n15\n00:00:35.865 --> 00:00:37.575\nLai regulētu attēla sensoru,\n\n16\n00:00:37.575 --> 00:00:40.911\nnovietojiet atpazīstamu objektu\nattēla sensora priekšpusē.\n\n17\n00:00:40.911 --> 00:00:43.164\nTādējādi attēla sensoram ir jāspēj uztvert,\n\n18\n00:00:43.164 --> 00:00:45.249\nka tas ir zils objekts.\n\n19\n00:00:45.249 --> 00:00:48.252\nTā kā apgaismojuma apstākļi\nir mainījušies,\n\n20\n00:00:48.252 --> 00:00:49.920\nattēla sensoram rada problēmas\n\n21\n00:00:49.920 --> 00:00:52.381\nuztvert zilo objektu.\n\n22\n00:00:52.381 --> 00:00:54.133\nSāciet regulēt attēla sensoru,\n\n23\n00:00:54.133 --> 00:00:57.511\nizvēloties zilā\nobjekta krāsu spiedogu\n\n24\n00:00:57.511 --> 00:00:59.513\nun bīdot slīdni.\n\n25\n00:00:59.513 --> 00:01:03.392\nPārvietojiet slīdni, lai uztvertu\nvairāk zilo objektu.\n\n26\n00:01:03.392 --> 00:01:04.560\nSlīdnis nosaka\n\n27\n00:01:04.560 --> 00:01:06.937\nuztveramās krāsas apjomu.\n\n28\n00:01:06.937 --> 00:01:08.272\nApjoma palielināšana ļauj\n\n29\n00:01:08.272 --> 00:01:11.317\nuztvert gaišākus un tumšākus\natlasītās krāsas toņus.\n\n30\n00:01:11.317 --> 00:01:13.736\nTagad, kad attēla sensors ir noregulēts,\n\n31\n00:01:13.736 --> 00:01:17.239\ntam jāspēj vieglāk\nuztvert zilo objektu.\n\n32\n00:01:17.239 --> 00:01:19.200\nCits veids kā regulēt attēla sensoru,\n\n33\n00:01:19.200 --> 00:01:21.035\nir mainīt spilgtumu.\n\n34\n00:01:21.035 --> 00:01:23.704\nSpilgtuma maiņa palielinās\nvai samazinās\n\n35\n00:01:23.704 --> 00:01:26.415\nattēla sensora jutīgumu pret gaismu.\n\n36\n00:01:26.415 --> 00:01:29.502\nSpilgtuma regulēšana\nietekmē visas krāsas.\n\n37\n00:01:29.502 --> 00:01:30.503\nRegulējot spilgtumu\n\n38\n00:01:30.503 --> 00:01:32.004\nun palielinot krāsas apjoma\n\n39\n00:01:32.004 --> 00:01:33.923\nuztveršanu attēla sensorā,\n\n40\n00:01:33.923 --> 00:01:35.758\nnoregulēs attēla sensoru tā,\n\n41\n00:01:35.758 --> 00:01:38.094\nlai to var izmantot\ndažādās vidēs.\n\n42\n00:01:39.053 --> 00:01:42.098\nTomēr, ja neviena no šīm\niespējām neatrisina problēmu,\n\n43\n00:01:42.098 --> 00:01:43.557\nnodzēsiet krāsu spiedogu\n\n44\n00:01:43.557 --> 00:01:47.561\nun tad atkārtoti iestatiet objektus.\n\n45\n00:01:47.561 --> 00:01:49.063\nRegulēšana ļaus izmantot\n\n46\n00:01:49.063 --> 00:01:52.149\njūsu attēla sensora\nprojektus jebkurā vidē.\n\n","nl":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nEen Beeldsensor kan gebruikt worden om objecten te zien\n\n2\n00:00:03.124 --> 00:00:04.959\nen uw robot in staat te stellen te communiceren\n\n3\n00:00:04.959 --> 00:00:07.003\nmet de wereld eromheen.\n\n4\n00:00:07.003 --> 00:00:09.630\nAf en toe kan de robot problemen hebben\n\n5\n00:00:09.630 --> 00:00:11.591\nmet bekende objecten detecteren.\n\n6\n00:00:11.591 --> 00:00:13.968\nDit is vaak het gevolg van een verandering van verlichting.\n\n7\n00:00:14.802 --> 00:00:16.053\nOm dit probleem te oplossen\n\n8\n00:00:16.053 --> 00:00:18.347\nmoet u misschien uw Beeldsensor afstellen.\n\n9\n00:00:18.347 --> 00:00:22.059\nU kunt de Beeldsensor afstellen met het Beeld hulpprogramma.\n\n10\n00:00:22.059 --> 00:00:23.185\nIn deze tutorial,\n\n11\n00:00:23.185 --> 00:00:26.314\nwe zullen gebruik maken van het Objecten Detecteren (Beeld)\n\n12\n00:00:26.314 --> 00:00:28.149\nvoorbeeldproject.\n\n13\n00:00:28.149 --> 00:00:31.319\nIn dit project is de Beeldsensor geconfigureerd\n\n14\n00:00:31.319 --> 00:00:35.865\nom een blauw, rood of groen object te detecteren.\n\n15\n00:00:35.865 --> 00:00:37.575\nOm de Beeldsensor af te stellen\n\n16\n00:00:37.575 --> 00:00:40.911\nplaats een bekend object voor de Beeldsensor.\n\n17\n00:00:40.911 --> 00:00:43.164\nHier zou de Beeldsensor moeten detecteren\n\n18\n00:00:43.164 --> 00:00:45.249\ndat dit een blauw object is.\n\n19\n00:00:45.249 --> 00:00:48.252\nOmdat de lichtomstandigheden zijn veranderd,\n\n20\n00:00:48.252 --> 00:00:49.920\nheeft de Beeldsensor echter problemen\n\n21\n00:00:49.920 --> 00:00:52.381\nom het blauwe object te detecteren.\n\n22\n00:00:52.381 --> 00:00:54.133\nBegin met het afstellen van de Beeldsensor\n\n23\n00:00:54.133 --> 00:00:57.511\ndoor de kleursignatuur van het blauwe object te selecteren\n\n24\n00:00:57.511 --> 00:00:59.513\nen de schuifregelaar aan te passen.\n\n25\n00:00:59.513 --> 00:01:03.392\nBeweeg de schuifregelaar om meer van de blauwe objecten te detecteren.\n\n26\n00:01:03.392 --> 00:01:04.560\nDe schuifregelaar bepaalt\n\n27\n00:01:04.560 --> 00:01:06.937\nde breedte van de kleur die gevonden moet worden.\n\n28\n00:01:06.937 --> 00:01:08.272\nHet vergroten van de breedte betekent\n\n29\n00:01:08.272 --> 00:01:11.317\nhet opnemen van lichtere en donkerdere kleurtinten.\n\n30\n00:01:11.317 --> 00:01:13.736\nNu de Beeldsensor is afgesteld,\n\n31\n00:01:13.736 --> 00:01:17.239\nzou het gemakkelijker moeten zijn om het blauwe object te detecteren.\n\n32\n00:01:17.239 --> 00:01:19.200\nEen andere manier om de Beeldsensor af te stellen\n\n33\n00:01:19.200 --> 00:01:21.035\nis om de helderheid te veranderen.\n\n34\n00:01:21.035 --> 00:01:23.704\nDoor de helderheid te wijzigen, wordt de gevoeligheid\n\n35\n00:01:23.704 --> 00:01:26.415\nvan de Beeldsensor voor licht verhoogd of verlaagd.\n\n36\n00:01:26.415 --> 00:01:29.502\nHet aanpassen van de helderheid is van invloed op alle kleuren.\n\n37\n00:01:29.502 --> 00:01:30.503\nDoor de helderheid aan te passen\n\n38\n00:01:30.503 --> 00:01:32.004\nen de breedte van de kleur\n\n39\n00:01:32.004 --> 00:01:33.923\ndie door de Beeldsensor wordt gedetecteerd,\n\n40\n00:01:33.923 --> 00:01:35.758\nte vergroten, moet de Beeldsensor worden afgesteld\n\n41\n00:01:35.758 --> 00:01:38.094\nzodat deze in verschillende omgevingen kan worden gebruikt.\n\n42\n00:01:39.053 --> 00:01:42.098\nAls geen van deze opties het probleem oplost,\n\n43\n00:01:42.098 --> 00:01:43.557\nwis dan de kleursignatuur\n\n44\n00:01:43.557 --> 00:01:47.561\nen train dan opnieuw om objecten te herkennen.\n\n45\n00:01:47.561 --> 00:01:49.063\nDoor af te stellen kunt u\n\n46\n00:01:49.063 --> 00:01:52.149\nuw Beeldsensor projecten gebruiken in elke omgeving.\n\n","pl":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nCzujnik wizji\nmoże być używany do widzenia obiektów\n\n2\n00:00:03.124 --> 00:00:04.959\ni pozwala robotowi na interakcję\n\n3\n00:00:04.959 --> 00:00:07.003\nz otaczającym go światem.\n\n4\n00:00:07.003 --> 00:00:09.630\nCzasami robot\nmoże mieć trudności\n\n5\n00:00:09.630 --> 00:00:11.591\nw wykrywaniu znanych obiektów.\n\n6\n00:00:11.591 --> 00:00:13.968\nWynika to często ze zmian w oświetleniu.\n\n7\n00:00:14.802 --> 00:00:16.053\nAby rozwiązać ten problem,\n\n8\n00:00:16.053 --> 00:00:18.347\nmoże być konieczne dostosowanie Czujnika Widzenia.\n\n9\n00:00:18.347 --> 00:00:22.059\nMożesz dostosować czujnik widzenia\nza pomocą narzędzia \"dostosowywania widzenia\".\n\n10\n00:00:22.059 --> 00:00:23.185\nW tym samouczku,\n\n11\n00:00:23.185 --> 00:00:26.314\nbędziemy używać\nWykrywania Obiektów (Wizja)\n\n12\n00:00:26.314 --> 00:00:28.149\nw przykładowy projekcje.\n\n13\n00:00:28.149 --> 00:00:31.319\nW tym projekcie Czujnik Wizji\nzostał skonfigurowany\n\n14\n00:00:31.319 --> 00:00:35.865\naby wykryć niebieski, czerwony lub zielony obiekt.\n\n15\n00:00:35.865 --> 00:00:37.575\nAby dostosować czujnik widzenia,\n\n16\n00:00:37.575 --> 00:00:40.911\numieść znany obiekt \nprzed czujnikiem widzenia.\n\n17\n00:00:40.911 --> 00:00:43.164\nTutaj, czujnik widzenia powinien wykryć\n\n18\n00:00:43.164 --> 00:00:45.249\nże jest to obiekt niebieski.\n\n19\n00:00:45.249 --> 00:00:48.252\nJednak od czasu zmiany warunków oświetlenia\n\n20\n00:00:48.252 --> 00:00:49.920\nczujnik widzenia ma problemy z\n\n21\n00:00:49.920 --> 00:00:52.381\nwykryciem niebieskiego obiektu.\n\n22\n00:00:52.381 --> 00:00:54.133\nRozpocznij dostrajanie czujnika widzenia\n\n23\n00:00:54.133 --> 00:00:57.511\npoprzez wybranie nazwy koloru \nprzy niebieskim obiekcie\n\n24\n00:00:57.511 --> 00:00:59.513\ni regulacji suwaka.\n\n25\n00:00:59.513 --> 00:01:03.392\nPrzesuń suwak, aby wykryć\nwięcej niebieskiego obiektu.\n\n26\n00:01:03.392 --> 00:01:04.560\nSuwak określa\n\n27\n00:01:04.560 --> 00:01:06.937\nszerokość wykrywanego koloru.\n\n28\n00:01:06.937 --> 00:01:08.272\nZwiększenie szerokości oznacza\n\n29\n00:01:08.272 --> 00:01:11.317\nwykrywanie łącznie z jaśniejszymi i\nciemniejszymi odcieniami koloru.\n\n30\n00:01:11.317 --> 00:01:13.736\nTeraz, gdy Czujnik Wizji został dostosowany,\n\n31\n00:01:13.736 --> 00:01:17.239\npowinien łatwiej\nwykryć niebieski obiekt.\n\n32\n00:01:17.239 --> 00:01:19.200\nInny sposób na dostosowanie czujnika widzenia\n\n33\n00:01:19.200 --> 00:01:21.035\njest możliwe dzięki zmianie jasności.\n\n34\n00:01:21.035 --> 00:01:23.704\nZmiana jasności\nzwiększa lub zmniejsza\n\n35\n00:01:23.704 --> 00:01:26.415\nwrażliwość czujnika widzenia na światło.\n\n36\n00:01:26.415 --> 00:01:29.502\nDostosowanie jasności\ndotyczy wszystkich kolorów.\n\n37\n00:01:29.502 --> 00:01:30.503\nDostosuj jasność\n\n38\n00:01:30.503 --> 00:01:32.004\ni zwiększ szerokość koloru\n\n39\n00:01:32.004 --> 00:01:33.923\nwykrywanego przez Czujnik Widzenia,\n\n40\n00:01:33.923 --> 00:01:35.758\npowinno dostosować czujnik widzenia\n\n41\n00:01:35.758 --> 00:01:38.094\nwięc może być użyty w\nróżnych środowiskach.\n\n42\n00:01:39.053 --> 00:01:42.098\nJeśli jednak żadna z tych\nopcji nie rozwiąże problemu,\n\n43\n00:01:42.098 --> 00:01:43.557\nwyczyść podpis koloru\n\n44\n00:01:43.557 --> 00:01:47.561\na następnie przekwalifikuj obiekty.\n\n45\n00:01:47.561 --> 00:01:49.063\nDostrajanie pozwoli ci użyć\n\n46\n00:01:49.063 --> 00:01:52.149\ntwój Czujnik Wizji\nw dowolnym środowisku.\n\n","ru":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nКамера может быть использована для обнаружения объектов\n\n2\n00:00:03.124 --> 00:00:04.959\nи взаимодействия робота\n\n3\n00:00:04.959 --> 00:00:07.003\nс окружающим миром.\n\n4\n00:00:07.003 --> 00:00:09.630\nИногда, робот бывает сложно\n\n5\n00:00:09.630 --> 00:00:11.591\nобнаружить известные объекты.\n\n6\n00:00:11.591 --> 00:00:13.968\nЭто часто связано с изменением освещения.\n\n7\n00:00:14.802 --> 00:00:16.053\nДля решения этой проблемы\n\n8\n00:00:16.053 --> 00:00:18.347\nвы можете настроить камеру.\n\n9\n00:00:18.347 --> 00:00:22.059\nВы можете настроить камеру с помощью меню настройки.\n\n10\n00:00:22.059 --> 00:00:23.185\nВ этом разделе\n\n11\n00:00:23.185 --> 00:00:26.314\nмы будем использовать пример проекта\n\n12\n00:00:26.314 --> 00:00:28.149\nпо обнаружению объекта.\n\n13\n00:00:28.149 --> 00:00:31.319\nВ этом проекте камера будет настроена для обнаружения\n\n14\n00:00:31.319 --> 00:00:35.865\nсинего, красного или зелёного объектов.\n\n15\n00:00:35.865 --> 00:00:37.575\nДля настройки камеры\n\n16\n00:00:37.575 --> 00:00:40.911\nпоместите известный предмет перед камерой.\n\n17\n00:00:40.911 --> 00:00:43.164\nКамера должна определить синий\n\n18\n00:00:43.164 --> 00:00:45.249\nцвет объекта.\n\n19\n00:00:45.249 --> 00:00:48.252\nОднако, при изменении условий освещения,\n\n20\n00:00:48.252 --> 00:00:49.920\nкамера может столкнуться с проблемой\n\n21\n00:00:49.920 --> 00:00:52.381\nпоиска синего объекта.\n\n22\n00:00:52.381 --> 00:00:54.133\nНачните настройку камеры,\n\n23\n00:00:54.133 --> 00:00:57.511\nвыбрав сигнатуру синего объекта\n\n24\n00:00:57.511 --> 00:00:59.513\nи ползунок.\n\n25\n00:00:59.513 --> 00:01:03.392\nПередвигайте ползунок для обнаружения большего числа синих объектов.\n\n26\n00:01:03.392 --> 00:01:04.560\nПолзунок определяет\n\n27\n00:01:04.560 --> 00:01:06.937\nширину объекта нужного цвета.\n\n28\n00:01:06.937 --> 00:01:08.272\nУвеличение ширины обозначает\n\n29\n00:01:08.272 --> 00:01:11.317\nизменение количества теней определяемого цвета.\n\n30\n00:01:11.317 --> 00:01:13.736\nПосле настройки камеры\n\n31\n00:01:13.736 --> 00:01:17.239\nвероятность нахождения синего объекта должна увеличиться.\n\n32\n00:01:17.239 --> 00:01:19.200\nДругим путём настройки камеры\n\n33\n00:01:19.200 --> 00:01:21.035\nявляется изменение яркости.\n\n34\n00:01:21.035 --> 00:01:23.704\nИзменение яркости увеличивает или уменьшает\n\n35\n00:01:23.704 --> 00:01:26.415\nчувствительность камеры.\n\n36\n00:01:26.415 --> 00:01:29.502\nРегулировка яркости влияет на цвета.\n\n37\n00:01:29.502 --> 00:01:30.503\nНастройка яркости\n\n38\n00:01:30.503 --> 00:01:32.004\nи увеличение ширины цвета,\n\n39\n00:01:32.004 --> 00:01:33.923\nнайденного камерой,\n\n40\n00:01:33.923 --> 00:01:35.758\nдолжен позволить камере\n\n41\n00:01:35.758 --> 00:01:38.094\nориентироваться при разных внешних условиях.\n\n42\n00:01:39.053 --> 00:01:42.098\nОднако, если никакая из этих подстроек не решает проблему,\n\n43\n00:01:42.098 --> 00:01:43.557\nочистите сигнатуру цвета\n\n44\n00:01:43.557 --> 00:01:47.561\nи заново создайте объекты.\n\n45\n00:01:47.561 --> 00:01:49.063\nНастройка позволяет вам использовать\n\n46\n00:01:49.063 --> 00:01:52.149\nкамеру в любых условиях.\n\n","th":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nวิชันเซนเซอร์\nสามารถใช้เพื่อดูวัตถุ\n\n2\n00:00:03.124 --> 00:00:04.959\nและทำให้หุ่นยนต์ของคุณโต้ตอบ\n\n3\n00:00:04.959 --> 00:00:07.003\nกับโลกรอบตัวได้\n\n4\n00:00:07.003 --> 00:00:09.630\nในบางครั้งหุ่นยนต์\nอาจมีปัญหา\n\n5\n00:00:09.630 --> 00:00:11.591\nในการตรวจจับวัตถุที่รู้จัก\n\n6\n00:00:11.591 --> 00:00:13.968\nซึ่งมักเกิดจากการเปลี่ยนแปลงของแสง\n\n7\n00:00:14.802 --> 00:00:16.053\nเพื่อแก้ปัญหานี้\n\n8\n00:00:16.053 --> 00:00:18.347\nคุณอาจต้องปรับแต่งวิชันเซนเซอร์ของคุณ\n\n9\n00:00:18.347 --> 00:00:22.059\nคุณสามารถปรับวิชันเซนเซอร์ได้\nโดยใช้ Vision Utility\n\n10\n00:00:22.059 --> 00:00:23.185\nในบทเรียนนี้\n\n11\n00:00:23.185 --> 00:00:26.314\nเราจะใช้ไฟล์\nDetecting Objects(Vision)\n\n12\n00:00:26.314 --> 00:00:28.149\nโปรเจ็คตัวอย่าง\n\n13\n00:00:28.149 --> 00:00:31.319\nในโปรเจ็คนี้ Vision Sensor ได้รับการกำหนดค่าแล้ว\n\n14\n00:00:31.319 --> 00:00:35.865\nเพื่อตรวจจับวัตถุสีน้ำเงินสีแดงหรือสีเขียว\n\n15\n00:00:35.865 --> 00:00:37.575\nในการปรับ Vision Sensor\n\n16\n00:00:37.575 --> 00:00:40.911\nวางวัตถุที่รู้จักใน\nด้านหน้าของ Vision Sensor\n\n17\n00:00:40.911 --> 00:00:43.164\nที่นี่ Vision Sensor ควรตรวจจับ\n\n18\n00:00:43.164 --> 00:00:45.249\nว่าเป็นวัตถุสีน้ำเงิน\n\n19\n00:00:45.249 --> 00:00:48.252\nอย่างไรก็ตามเนื่องจากสภาพแสงเปลี่ยนไป\n\n20\n00:00:48.252 --> 00:00:49.920\nวิชันเซนเซอร์มีปัญหาในการ\n\n21\n00:00:49.920 --> 00:00:52.381\nตรวจจับวัตถุสีน้ำเงิน\n\n22\n00:00:52.381 --> 00:00:54.133\nเริ่มปรับแต่ง Vision Sensor\n\n23\n00:00:54.133 --> 00:00:57.511\nโดยการเลือกลายเซ็นสีของวัตถุสีน้ำเงิน\n\n24\n00:00:57.511 --> 00:00:59.513\nและปรับแถบเลื่อน\n\n25\n00:00:59.513 --> 00:01:03.392\nเลื่อนแถบเลื่อนเพื่อตรวจจับวัตถุสีน้ำเงินเพิ่มเติม\n\n26\n00:01:03.392 --> 00:01:04.560\nแถบเลื่อนเป็นตัวกำหนด\n\n27\n00:01:04.560 --> 00:01:06.937\nthe width of the color to be detected.\n\n28\n00:01:06.937 --> 00:01:08.272\nการเพิ่มความกว้างหมายถึง\n\n29\n00:01:08.272 --> 00:01:11.317\nรวมถึงเฉดสีที่อ่อนลงและเข้มขึ้น\n\n30\n00:01:11.317 --> 00:01:13.736\nตอนนี้ Vision Sensor ได้รับการปรับแต่งแล้ว\n\n31\n00:01:13.736 --> 00:01:17.239\nควรตรวจจับวัตถุสีน้ำเงินได้อย่างง่ายดาย\n\n32\n00:01:17.239 --> 00:01:19.200\nอีกวิธีหนึ่งวิธีในการปรับ Vision Sensor\n\n33\n00:01:19.200 --> 00:01:21.035\nคือการเปลี่ยนความสว่าง\n\n34\n00:01:21.035 --> 00:01:23.704\nการเปลี่ยนความสว่าง\nจะเพิ่มหรือลด\n\n35\n00:01:23.704 --> 00:01:26.415\nความไวของวิชันเซนเซอร์ที่มีต่อแสง\n\n36\n00:01:26.415 --> 00:01:29.502\nการปรับความสว่างมีผลกับทุกสี\n\n37\n00:01:29.502 --> 00:01:30.503\nการปรับความสว่าง\n\n38\n00:01:30.503 --> 00:01:32.004\nและเพิ่มความกว้างของสี\n\n39\n00:01:32.004 --> 00:01:33.923\nที่ตรวจพบได้ของ Vision Sensor\n\n40\n00:01:33.923 --> 00:01:35.758\nควรปรับแต่ง Vision Sensor\n\n41\n00:01:35.758 --> 00:01:38.094\nเพื่อให้สามารถใช้งานได้ในสภาพแวดล้อมที่แตกต่างกัน\n\n42\n00:01:39.053 --> 00:01:42.098\nอย่างไรก็ตามหากตัวเลือกเหล่านี้ไม่สามารถแก้ปัญหาได้\n\n43\n00:01:42.098 --> 00:01:43.557\nล้างลายเซ็นสี\n\n44\n00:01:43.557 --> 00:01:47.561\nแล้วฝึกวัตถุอีกครั้ง\n\n45\n00:01:47.561 --> 00:01:49.063\nการปรับแต่งจะช่วยให้คุณสามารถใช้\n\n46\n00:01:49.063 --> 00:01:52.149\nโปรเจ็ค Vision Sensor ของคุณได้ในทุกสภาพแวดล้อม\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nДатчик зору можна використати \nдля розпізнавання об'єктів\n\n2\n00:00:03.124 --> 00:00:04.959\nі дати змогу роботам взаємодіяти\n\n3\n00:00:04.959 --> 00:00:07.003\nз навколишнім світом.\n\n4\n00:00:07.003 --> 00:00:09.630\nІноді робот \nмає труднощі\n\n5\n00:00:09.630 --> 00:00:11.591\nз розпізнаванням відомих об'єктів.\n\n6\n00:00:11.591 --> 00:00:13.968\nТаке буває через зміну освітлення.\n\n7\n00:00:14.802 --> 00:00:16.053\nЩоб розв'язати цю проблему,\n\n8\n00:00:16.053 --> 00:00:18.347\nви також можете налаштувати датчик зору.\n\n9\n00:00:18.347 --> 00:00:22.059\nМожна налаштувати датчик зору,\nвикориставши Vision Utility.\n\n10\n00:00:22.059 --> 00:00:23.185\nДля цього посібника\n\n11\n00:00:23.185 --> 00:00:26.314\nми використаємо\nвизначення об'єктів(Зір) -\n\n12\n00:00:26.314 --> 00:00:28.149\nприклад проєкту.\n\n13\n00:00:28.149 --> 00:00:31.319\nУ цьому проєкті датчик зору\nвже налаштований\n\n14\n00:00:31.319 --> 00:00:35.865\nна визначення синього, червоного або зеленого об'єкта.\n\n15\n00:00:35.865 --> 00:00:37.575\nДля налаштування датчика зору,\n\n16\n00:00:37.575 --> 00:00:40.911\nрозмістіть або тримайте об'єкт \nперед датчиком зору.\n\n17\n00:00:40.911 --> 00:00:43.164\nТак, датчик зору повинен визначити,\n\n18\n00:00:43.164 --> 00:00:45.249\nщо цей об'єкт синій.\n\n19\n00:00:45.249 --> 00:00:48.252\nПроте, оскільки \nосвітлення змінилося,\n\n20\n00:00:48.252 --> 00:00:49.920\nдатчик зору має проблеми\n\n21\n00:00:49.920 --> 00:00:52.381\nз розпізнаванням синього об'єкта.\n\n22\n00:00:52.381 --> 00:00:54.133\nПочніть регулювання датчика зору,\n\n23\n00:00:54.133 --> 00:00:57.511\nвиберіть колір \nсигнатури синього об'єкта\n\n24\n00:00:57.511 --> 00:00:59.513\nі регулюйте повзунок.\n\n25\n00:00:59.513 --> 00:01:03.392\nРухайте повзунок до кращого \nрозпізнавання синього об'єкта.\n\n26\n00:01:03.392 --> 00:01:04.560\nПовзунок визначає\n\n27\n00:01:04.560 --> 00:01:06.937\nширину кольору для розпізнавання.\n\n28\n00:01:06.937 --> 00:01:08.272\nЗбільшення ширини\n\n29\n00:01:08.272 --> 00:01:11.317\nдодає світліші і\nтемніші відтінки кольору.\n\n30\n00:01:11.317 --> 00:01:13.736\nТепер, коли датчик зору налаштовано,\n\n31\n00:01:13.736 --> 00:01:17.239\nбуде легше \nрозпізнати синій об'єкт.\n\n32\n00:01:17.239 --> 00:01:19.200\nІнший спосіб налаштування датчика зору -\n\n33\n00:01:19.200 --> 00:01:21.035\nзмінити яскравість.\n\n34\n00:01:21.035 --> 00:01:23.704\nЗміна яскравості \nзбільшує або зменшує\n\n35\n00:01:23.704 --> 00:01:26.415\nчутливість датчика зору до світла.\n\n36\n00:01:26.415 --> 00:01:29.502\nРегулювання яскравості \nвпливає на всі кольори.\n\n37\n00:01:29.502 --> 00:01:30.503\nРегулювання яскравості\n\n38\n00:01:30.503 --> 00:01:32.004\nзбільшує ширину кольору\n\n39\n00:01:32.004 --> 00:01:33.923\nдля розпізнавання датчиком зору,\n\n40\n00:01:33.923 --> 00:01:35.758\nналаштовуйте датчик зору\n\n41\n00:01:35.758 --> 00:01:38.094\nі він добре працюватиме\nу різному середовищі.\n\n42\n00:01:39.053 --> 00:01:42.098\nПроте, якщо жоден із\nваріантів не розв'язав проблему,\n\n43\n00:01:42.098 --> 00:01:43.557\nспробуйте очистити сигнатуру кольору\n\n44\n00:01:43.557 --> 00:01:47.561\nі натренувати об'єкти заново.\n\n45\n00:01:47.561 --> 00:01:49.063\nРегулювання дасть вам змогу користуватися\n\n46\n00:01:49.063 --> 00:01:52.149\nпроєктами з датчиком зору\nв будь-якому середовищі.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\nMột Cảm biến Tầm nhìn\ncó thể được sử dụng để xem các đối tượng\n\n2\n00:00:03.124 --> 00:00:04.959\nvà cho phép rô bốt của bạn tương tác\n\n3\n00:00:04.959 --> 00:00:07.003\nvới thế giới xung quanh nó.\n\n4\n00:00:07.003 --> 00:00:09.630\nĐôi khi, rô bốt\ncó thể gặp khó khăn\n\n5\n00:00:09.630 --> 00:00:11.591\nphát hiện các đối tượng đã biết.\n\n6\n00:00:11.591 --> 00:00:13.968\nĐiều này thường là do sự thay đổi trong ánh sáng.\n\n7\n00:00:14.802 --> 00:00:16.053\nĐể giải quyết vấn đề này,\n\n8\n00:00:16.053 --> 00:00:18.347\nbạn có thể phải điều chỉnh Cảm biến Tầm nhìn của mình.\n\n9\n00:00:18.347 --> 00:00:22.059\nBạn có thể điều chỉnh Cảm biến Tầm nhìn\nbằng cách sử dụng Tiện ích Tầm nhìn.\n\n10\n00:00:22.059 --> 00:00:23.185\nTrong hướng dẫn này,\n\n11\n00:00:23.185 --> 00:00:26.314\nchúng tôi sẽ sử dụng\nPhát hiện Đối tượng (Tầm nhìn)\n\n12\n00:00:26.314 --> 00:00:28.149\ndự án ví dụ.\n\n13\n00:00:28.149 --> 00:00:31.319\nTrong dự án này, Cảm biến Vision\nđã được định cấu hình\n\n14\n00:00:31.319 --> 00:00:35.865\nđể phát hiện một đối tượng màu xanh lam, đỏ hoặc xanh lá cây.\n\n15\n00:00:35.865 --> 00:00:37.575\nĐể điều chỉnh Cảm biến Tầm nhìn,\n\n16\n00:00:37.575 --> 00:00:40.911\nđặt một đối tượng đã biết ở\nphía trước của Cảm biến Tầm nhìn.\n\n17\n00:00:40.911 --> 00:00:43.164\nTại đây, Cảm biến Tầm nhìn sẽ phát hiện\n\n18\n00:00:43.164 --> 00:00:45.249\nrằng đây là một vật thể màu xanh lam.\n\n19\n00:00:45.249 --> 00:00:48.252\nTuy nhiên, vì điều kiện chiếu sáng\nđã thay đổi,\n\n20\n00:00:48.252 --> 00:00:49.920\nCảm biến Tầm nhìn đang gặp sự cố\n\n21\n00:00:49.920 --> 00:00:52.381\nphát hiện đối tượng màu xanh.\n\n22\n00:00:52.381 --> 00:00:54.133\nBắt đầu điều chỉnh Cảm biến Tầm nhìn\n\n23\n00:00:54.133 --> 00:00:57.511\nbằng cách chọn chữ ký\nmàu của đối tượng màu xanh lam\n\n24\n00:00:57.511 --> 00:00:59.513\nvà điều chỉnh thanh trượt.\n\n25\n00:00:59.513 --> 00:01:03.392\nDi chuyển thanh trượt để phát hiện thêm\nđối tượng màu xanh lam.\n\n26\n00:01:03.392 --> 00:01:04.560\nThanh trượt xác định\n\n27\n00:01:04.560 --> 00:01:06.937\nchiều rộng của màu được phát hiện.\n\n28\n00:01:06.937 --> 00:01:08.272\nTăng chiều rộng có nghĩa là\n\n29\n00:01:08.272 --> 00:01:11.317\nbao gồm các sắc thái màu sáng hơn và\nđậm hơn.\n\n30\n00:01:11.317 --> 00:01:13.736\nBây giờ Cảm biến Tầm nhìn đã được điều chỉnh,\n\n31\n00:01:13.736 --> 00:01:17.239\nnó sẽ dễ dàng hơn\nphát hiện đối tượng màu xanh lam.\n\n32\n00:01:17.239 --> 00:01:19.200\nMột cách khác để điều chỉnh Cảm biến Tầm nhìn\n\n33\n00:01:19.200 --> 00:01:21.035\nlà thay đổi độ sáng.\n\n34\n00:01:21.035 --> 00:01:23.704\nThay đổi độ sáng\ntăng hoặc giảm\n\n35\n00:01:23.704 --> 00:01:26.415\nđộ nhạy của Cảm biến Tầm nhìn đối với ánh sáng.\n\n36\n00:01:26.415 --> 00:01:29.502\nĐiều chỉnh độ sáng\nảnh hưởng đến tất cả các màu.\n\n37\n00:01:29.502 --> 00:01:30.503\nĐiều chỉnh độ sáng\n\n38\n00:01:30.503 --> 00:01:32.004\nvà tăng chiều rộng của màu\n\n39\n00:01:32.004 --> 00:01:33.923\nđược phát hiện bởi Cảm biến Tầm nhìn,\n\n40\n00:01:33.923 --> 00:01:35.758\nnên điều chỉnh Cảm biến Tầm nhìn\n\n41\n00:01:35.758 --> 00:01:38.094\nvì vậy nó có thể được sử dụng trong\ncác môi trường khác nhau.\n\n42\n00:01:39.053 --> 00:01:42.098\nTuy nhiên, nếu cả hai tùy chọn\nnày đều không giải quyết được vấn đề,\n\n43\n00:01:42.098 --> 00:01:43.557\nxóa chữ ký màu\n\n44\n00:01:43.557 --> 00:01:47.561\nvà sau đó đào tạo lại các đối tượng.\n\n45\n00:01:47.561 --> 00:01:49.063\nĐiều chỉnh sẽ cho phép bạn sử dụng\n\n46\n00:01:49.063 --> 00:01:52.149\nDự án Cảm biến Tầm nhìn của bạn\ntrong bất kỳ môi trường nào.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\ncrwdns88874:0crwdne88874:0\n\n2\n00:00:03.124 --> 00:00:04.959\ncrwdns88876:0crwdne88876:0\n\n3\n00:00:04.959 --> 00:00:07.003\ncrwdns88878:0crwdne88878:0\n\n4\n00:00:07.003 --> 00:00:09.630\ncrwdns88880:0crwdne88880:0\n\n5\n00:00:09.630 --> 00:00:11.591\ncrwdns88882:0crwdne88882:0\n\n6\n00:00:11.591 --> 00:00:13.968\ncrwdns88884:0crwdne88884:0\n\n7\n00:00:14.802 --> 00:00:16.053\ncrwdns88886:0crwdne88886:0\n\n8\n00:00:16.053 --> 00:00:18.347\ncrwdns88888:0crwdne88888:0\n\n9\n00:00:18.347 --> 00:00:22.059\ncrwdns88890:0crwdne88890:0\n\n10\n00:00:22.059 --> 00:00:23.185\ncrwdns88892:0crwdne88892:0\n\n11\n00:00:23.185 --> 00:00:26.314\ncrwdns88894:0crwdne88894:0\n\n12\n00:00:26.314 --> 00:00:28.149\ncrwdns88896:0crwdne88896:0\n\n13\n00:00:28.149 --> 00:00:31.319\ncrwdns88898:0crwdne88898:0\n\n14\n00:00:31.319 --> 00:00:35.865\ncrwdns88900:0crwdne88900:0\n\n15\n00:00:35.865 --> 00:00:37.575\ncrwdns88902:0crwdne88902:0\n\n16\n00:00:37.575 --> 00:00:40.911\ncrwdns88904:0crwdne88904:0\n\n17\n00:00:40.911 --> 00:00:43.164\ncrwdns88906:0crwdne88906:0\n\n18\n00:00:43.164 --> 00:00:45.249\ncrwdns88908:0crwdne88908:0\n\n19\n00:00:45.249 --> 00:00:48.252\ncrwdns88910:0crwdne88910:0\n\n20\n00:00:48.252 --> 00:00:49.920\ncrwdns88912:0crwdne88912:0\n\n21\n00:00:49.920 --> 00:00:52.381\ncrwdns88914:0crwdne88914:0\n\n22\n00:00:52.381 --> 00:00:54.133\ncrwdns88916:0crwdne88916:0\n\n23\n00:00:54.133 --> 00:00:57.511\ncrwdns88918:0crwdne88918:0\n\n24\n00:00:57.511 --> 00:00:59.513\ncrwdns88920:0crwdne88920:0\n\n25\n00:00:59.513 --> 00:01:03.392\ncrwdns88922:0crwdne88922:0\n\n26\n00:01:03.392 --> 00:01:04.560\ncrwdns88924:0crwdne88924:0\n\n27\n00:01:04.560 --> 00:01:06.937\ncrwdns88926:0crwdne88926:0\n\n28\n00:01:06.937 --> 00:01:08.272\ncrwdns88928:0crwdne88928:0\n\n29\n00:01:08.272 --> 00:01:11.317\ncrwdns88930:0crwdne88930:0\n\n30\n00:01:11.317 --> 00:01:13.736\ncrwdns88932:0crwdne88932:0\n\n31\n00:01:13.736 --> 00:01:17.239\ncrwdns88934:0crwdne88934:0\n\n32\n00:01:17.239 --> 00:01:19.200\ncrwdns88936:0crwdne88936:0\n\n33\n00:01:19.200 --> 00:01:21.035\ncrwdns88938:0crwdne88938:0\n\n34\n00:01:21.035 --> 00:01:23.704\ncrwdns88940:0crwdne88940:0\n\n35\n00:01:23.704 --> 00:01:26.415\ncrwdns88942:0crwdne88942:0\n\n36\n00:01:26.415 --> 00:01:29.502\ncrwdns88944:0crwdne88944:0\n\n37\n00:01:29.502 --> 00:01:30.503\ncrwdns88946:0crwdne88946:0\n\n38\n00:01:30.503 --> 00:01:32.004\ncrwdns88948:0crwdne88948:0\n\n39\n00:01:32.004 --> 00:01:33.923\ncrwdns88950:0crwdne88950:0\n\n40\n00:01:33.923 --> 00:01:35.758\ncrwdns88952:0crwdne88952:0\n\n41\n00:01:35.758 --> 00:01:38.094\ncrwdns88954:0crwdne88954:0\n\n42\n00:01:39.053 --> 00:01:42.098\ncrwdns88956:0crwdne88956:0\n\n43\n00:01:42.098 --> 00:01:43.557\ncrwdns88958:0crwdne88958:0\n\n44\n00:01:43.557 --> 00:01:47.561\ncrwdns88960:0crwdne88960:0\n\n45\n00:01:47.561 --> 00:01:49.063\ncrwdns88962:0crwdne88962:0\n\n46\n00:01:49.063 --> 00:01:52.149\ncrwdns88964:0crwdne88964:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\n视觉传感器可被用于查看对象\n\n2\n00:00:03.124 --> 00:00:04.959\n并允许你的机器人\n\n3\n00:00:04.959 --> 00:00:07.003\n和它周围的环境进行交互。\n\n4\n00:00:07.003 --> 00:00:09.630\n偶尔地，机器人可能有困难\n\n5\n00:00:09.630 --> 00:00:11.591\n检测已知的对象。\n\n6\n00:00:11.591 --> 00:00:13.968\n这通常是因为光线变化的缘故。\n\n7\n00:00:14.802 --> 00:00:16.053\n欲解决这个问题，\n\n8\n00:00:16.053 --> 00:00:18.347\n你可能需要调试视觉传感器。\n\n9\n00:00:18.347 --> 00:00:22.059\n你可以使用视觉传感器工具来调试。\n\n10\n00:00:22.059 --> 00:00:23.185\n在本辅导视频中，\n\n11\n00:00:23.185 --> 00:00:26.314\n我们将使用“检测对象（视觉传感器）”\n\n12\n00:00:26.314 --> 00:00:28.149\n示例程序。\n\n13\n00:00:28.149 --> 00:00:31.319\n在本程序中，视觉传感器已经配置好\n\n14\n00:00:31.319 --> 00:00:35.865\n去检测一个蓝色，红色，或绿色对象。\n\n15\n00:00:35.865 --> 00:00:37.575\n欲调试视觉传感器，\n\n16\n00:00:37.575 --> 00:00:40.911\n放置一个已知的对象在视觉传感器前方。\n\n17\n00:00:40.911 --> 00:00:43.164\n在这里，视觉传感器应该检测到\n\n18\n00:00:43.164 --> 00:00:45.249\n那是一个蓝色对象。\n\n19\n00:00:45.249 --> 00:00:48.252\n但是，因为光线条件已经改变了，\n\n20\n00:00:48.252 --> 00:00:49.920\n视觉传感器检测\n\n21\n00:00:49.920 --> 00:00:52.381\n蓝色对象有困难。\n\n22\n00:00:52.381 --> 00:00:54.133\n通过选择蓝色对象颜色标记\n\n23\n00:00:54.133 --> 00:00:57.511\n和调节滑条\n\n24\n00:00:57.511 --> 00:00:59.513\n来开始调试视觉传感器。\n\n25\n00:00:59.513 --> 00:01:03.392\n移动滑条来检测蓝色对象的更多部分。\n\n26\n00:01:03.392 --> 00:01:04.560\n滑条决定了\n\n27\n00:01:04.560 --> 00:01:06.937\n被检测颜色的宽度。\n\n28\n00:01:06.937 --> 00:01:08.272\n增加宽度意味着\n\n29\n00:01:08.272 --> 00:01:11.317\n包含较亮和较深的颜色阴影。\n\n30\n00:01:11.317 --> 00:01:13.736\n现在视觉传感器已经调试过了，\n\n31\n00:01:13.736 --> 00:01:17.239\n它应该更容易检测到蓝色对象。\n\n32\n00:01:17.239 --> 00:01:19.200\n另一种调试视觉传感器的方式\n\n33\n00:01:19.200 --> 00:01:21.035\n是改变亮度\n\n34\n00:01:21.035 --> 00:01:23.704\n改变亮度增加或减小\n\n35\n00:01:23.704 --> 00:01:26.415\n视觉传感器对光线的灵敏度。\n\n36\n00:01:26.415 --> 00:01:29.502\n调节亮度影响所有的颜色。\n\n37\n00:01:29.502 --> 00:01:30.503\n调节亮度\n\n38\n00:01:30.503 --> 00:01:32.004\n并增加视觉传感器\n\n39\n00:01:32.004 --> 00:01:33.923\n检测到的颜色宽度，\n\n40\n00:01:33.923 --> 00:01:35.758\n应当调试视觉传感器\n\n41\n00:01:35.758 --> 00:01:38.094\n以便它可被用在不同的环境中。\n\n42\n00:01:39.053 --> 00:01:42.098\n但是，如果不管哪种方法都不能解决问题，\n\n43\n00:01:42.098 --> 00:01:43.557\n清除颜色标记，\n\n44\n00:01:43.557 --> 00:01:47.561\n然后再重新训练对象。\n\n45\n00:01:47.561 --> 00:01:49.063\n调试将允许你\n\n46\n00:01:49.063 --> 00:01:52.149\n在任何环境中使用视觉传感器程序。\n\n","zh-TW":"WEBVTT\n\n1\n00:00:00.580 --> 00:00:03.124\n視覺感測器\n可以用來查看物體\n\n2\n00:00:03.124 --> 00:00:04.959\n並允許您的機器人\n\n3\n00:00:04.959 --> 00:00:07.003\n和周圍的世界互動。\n\n4\n00:00:07.003 --> 00:00:09.630\n有時候，機器人\n可能會在偵測物體時\n\n5\n00:00:09.630 --> 00:00:11.591\n遇到困難。\n\n6\n00:00:11.591 --> 00:00:13.968\n這通常是因為光線的變化。\n\n7\n00:00:14.802 --> 00:00:16.053\n若要解決這個問題，\n\n8\n00:00:16.053 --> 00:00:18.347\n您可能需要調整您的視覺感測器。\n\n9\n00:00:18.347 --> 00:00:22.059\n您可以用視覺感測器工具\n來調整視覺感測器。\n\n10\n00:00:22.059 --> 00:00:23.185\n在此教程中，\n\n11\n00:00:23.185 --> 00:00:26.314\n我們將會使用\n偵測物件（視覺）的\n\n12\n00:00:26.314 --> 00:00:28.149\n範例專案。\n\n13\n00:00:28.149 --> 00:00:31.319\n在此專案中，已經配置好\n視覺感測器\n\n14\n00:00:31.319 --> 00:00:35.865\n偵測藍、紅或綠的物件。\n\n15\n00:00:35.865 --> 00:00:37.575\n若要調整視覺感測器，\n\n16\n00:00:37.575 --> 00:00:40.911\n在視覺感測器前\n放置一個已知物體。\n\n17\n00:00:40.911 --> 00:00:43.164\n在這裡，視覺感測器應該要偵測到\n\n18\n00:00:43.164 --> 00:00:45.249\n這是個藍色物件。\n\n19\n00:00:45.249 --> 00:00:48.252\n但是，因為光線\n條件改變，\n\n20\n00:00:48.252 --> 00:00:49.920\n視覺感測器\n\n21\n00:00:49.920 --> 00:00:52.381\n偵測藍色物件就有困難。\n\n22\n00:00:52.381 --> 00:00:54.133\n藉由選擇\n\n23\n00:00:54.133 --> 00:00:57.511\n藍色物件的顏色識別標誌\n和調整滑桿\n\n24\n00:00:57.511 --> 00:00:59.513\n來校準視覺感測器。\n\n25\n00:00:59.513 --> 00:01:03.392\n移動滑桿以偵測\n更多藍色物件。\n\n26\n00:01:03.392 --> 00:01:04.560\n滑桿決定\n\n27\n00:01:04.560 --> 00:01:06.937\n被偵測的顏色廣度。\n\n28\n00:01:06.937 --> 00:01:08.272\n增加廣度代表\n\n29\n00:01:08.272 --> 00:01:11.317\n包含更淺\n和更深的顏色。\n\n30\n00:01:11.317 --> 00:01:13.736\n現在視覺感測器已經調整好，\n\n31\n00:01:13.736 --> 00:01:17.239\n偵測藍色物件\n應該會更容易。\n\n32\n00:01:17.239 --> 00:01:19.200\n調整視覺感測器的其他方法為\n\n33\n00:01:19.200 --> 00:01:21.035\n改變亮度。\n\n34\n00:01:21.035 --> 00:01:23.704\n改變亮度\n以增加或減少\n\n35\n00:01:23.704 --> 00:01:26.415\n視覺感測器對光線的敏感度。\n\n36\n00:01:26.415 --> 00:01:29.502\n調整亮度\n會影響所有顏色。\n\n37\n00:01:29.502 --> 00:01:30.503\n藉由視覺感測器的偵測\n\n38\n00:01:30.503 --> 00:01:32.004\n來調整亮度\n\n39\n00:01:32.004 --> 00:01:33.923\n並增加顏色的廣度，\n\n40\n00:01:33.923 --> 00:01:35.758\n應該要校準視覺感測器\n\n41\n00:01:35.758 --> 00:01:38.094\n它才可以在\n不同環境中使用。\n\n42\n00:01:39.053 --> 00:01:42.098\n但是，若這兩種方法都無法解決問題，\n\n43\n00:01:42.098 --> 00:01:43.557\n清除顏色識別標誌\n\n44\n00:01:43.557 --> 00:01:47.561\n再重新校準物件。\n\n45\n00:01:47.561 --> 00:01:49.063\n調整將允許您\n\n46\n00:01:49.063 --> 00:01:52.149\n在任何環境中\n使用您的視覺感測器程式。\n\n"}},{"thumb":"V5_Tutorial_movingBlocks.jpg","mov":"V5_Blocks_MovingRemovingBlocks_V2","description":"Moving and Removing Blocks","filter":"","placeholder":false,"vimeo":"475899751","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Creating a V5 blocks project is easy.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBlocks can be dragged from the toolbox\n\n3\n00:00:06.010 --> 00:00:07.963\ninto the project workspace.\n\n4\n00:00:11.250 --> 00:00:13.560\nThere, blocks can be stacked together\n\n5\n00:00:13.560 --> 00:00:14.923\nto create your project.\n\n6\n00:00:16.270 --> 00:00:18.070\nYou can also rearrange blocks\n\n7\n00:00:18.070 --> 00:00:19.850\nby dragging them off of a stack\n\n8\n00:00:20.970 --> 00:00:24.093\nand inserting them in a different spot in your project.\n\n9\n00:00:25.170 --> 00:00:26.090\nAt some point,\n\n10\n00:00:26.090 --> 00:00:29.240\nyou may want to delete a block from your project.\n\n11\n00:00:29.240 --> 00:00:31.070\nTo delete part of a stack of blocks\n\n12\n00:00:31.070 --> 00:00:32.440\nthat are not within a loop,\n\n13\n00:00:32.440 --> 00:00:34.430\nseparate the blocks from your project\n\n14\n00:00:34.430 --> 00:00:36.363\nand drag it back to the toolbox area.\n\n15\n00:00:39.270 --> 00:00:41.670\nTo delete a block that is the middle of a stack,\n\n16\n00:00:42.510 --> 00:00:45.480\nright-click on the block you would like to delete\n\n17\n00:00:45.480 --> 00:00:47.663\nand select the delete option.\n\n18\n00:00:48.560 --> 00:00:50.170\nIf using a tablet,\n\n19\n00:00:50.170 --> 00:00:53.440\npress and hold the block until the options appear.\n\n20\n00:00:53.440 --> 00:00:55.053\nThen, select delete.\n\n21\n00:00:57.030 --> 00:00:58.410\nIf you would like to move a block\n\n22\n00:00:58.410 --> 00:01:00.460\nfrom your project for later use,\n\n23\n00:01:00.460 --> 00:01:04.220\nremove it from the stack and move it off to the side.\n\n24\n00:01:04.220 --> 00:01:06.990\nKeep in mind that only blocks connected to hat blocks\n\n25\n00:01:06.990 --> 00:01:10.383\nwill be sent to the robot when your project is downloaded.\n\n","ar":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>إنشاء مشروع مقاطع V5 أمر سهل.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nيمكن سحب المقاطع البرمجية من قائمة الأدوات\n\n3\n00:00:06.010 --> 00:00:07.963\nإلى مساحة عمل المشروع.\n\n4\n00:00:11.250 --> 00:00:13.560\nهناك ، يمكن تجميع المقاطع معا\n\n5\n00:00:13.560 --> 00:00:14.923\nلإنشاء المشروع الخاص بك.\n\n6\n00:00:16.270 --> 00:00:18.070\nيمكنك أيضا إعادة ترتيب المقاطع\n\n7\n00:00:18.070 --> 00:00:19.850\nعن طريق سحبهم من المجموعة\n\n8\n00:00:20.970 --> 00:00:24.093\nوإدراجها في مكان مختلف في مشروعك.\n\n9\n00:00:25.170 --> 00:00:26.090\nفي مرحلة ما،\n\n10\n00:00:26.090 --> 00:00:29.240\nقد ترغب في حذف مقطع من مشروعك.\n\n11\n00:00:29.240 --> 00:00:31.070\nلحذف جزء من مجموعة المقاطع\n\n12\n00:00:31.070 --> 00:00:32.440\nالتي ليست ضمن الحلقة\n\n13\n00:00:32.440 --> 00:00:34.430\nإفصل المقاطع عن مشروعك\n\n14\n00:00:34.430 --> 00:00:36.363\nوإسحب مرة أخرى إلى قائمة الأدوات.\n\n15\n00:00:39.270 --> 00:00:41.670\nلحذف مقطع موجود وسط المجموعة\n\n16\n00:00:42.510 --> 00:00:45.480\nانقر بالزر الأيمن على المقطع الذي ترغب في حذفه\n\n17\n00:00:45.480 --> 00:00:47.663\nوحدد خيار الحذف.\n\n18\n00:00:48.560 --> 00:00:50.170\nإذا كنت تستخدم حاسوب لوحي\n\n19\n00:00:50.170 --> 00:00:53.440\nاضغط مع الاستمرار على المقطع حتى تظهر الخيارات،.\n\n20\n00:00:53.440 --> 00:00:55.053\nثم حدد الحذف.\n\n21\n00:00:57.030 --> 00:00:58.410\nإذا كنت ترغب في نقل مقطع\n\n22\n00:00:58.410 --> 00:01:00.460\nمن مشروعك لاستخدامه لاحقا،\n\n23\n00:01:00.460 --> 00:01:04.220\nقم بإزالته من المجموعة و نقله إلى الجانب.\n\n24\n00:01:04.220 --> 00:01:06.990\nضع في الاعتبار أن المقاطع فقط متصلة بمقاطع القبعة\n\n25\n00:01:06.990 --> 00:01:10.383\nسيتم إرسالها إلى الروبوت عند تنزيل مشروعك.\n\n","cs":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Vytváření blokového V5 projektu je snadné.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBloky lze přetáhnout z panelu nástrojů\n\n3\n00:00:06.010 --> 00:00:07.963\ndo pracovního prostoru projektu.\n\n4\n00:00:11.250 --> 00:00:13.560\nTady mohou být bloky spojovány dohromady\n\n5\n00:00:13.560 --> 00:00:14.923\npro vytvoření tvého projektu.\n\n6\n00:00:16.270 --> 00:00:18.070\nBloky můžeš také přeskupovat\n\n7\n00:00:18.070 --> 00:00:19.850\npřetažením z jejich zásobníku\n\n8\n00:00:20.970 --> 00:00:24.093\na vložením na jiném místě ve tvém projektu.\n\n9\n00:00:25.170 --> 00:00:26.090\nV určitém okamžiku\n\n10\n00:00:26.090 --> 00:00:29.240\nmůžeš chtít smazat blok ze svého projektu.\n\n11\n00:00:29.240 --> 00:00:31.070\nK vymazání části zásobníku bloků,\n\n12\n00:00:31.070 --> 00:00:32.440\nkteré nejsou součástí cyklu,\n\n13\n00:00:32.440 --> 00:00:34.430\nodděl bloky z tvého projektu\n\n14\n00:00:34.430 --> 00:00:36.363\na přetáhni je zpět do oblasti panelu nástrojů.\n\n15\n00:00:39.270 --> 00:00:41.670\nK odstranění bloku, který je uprostřed zásobníku,\n\n16\n00:00:42.510 --> 00:00:45.480\nklikni pravým tlačítkem myši na blok, který chceš smazat,\n\n17\n00:00:45.480 --> 00:00:47.663\na vyber možnost Vymazat.\n\n18\n00:00:48.560 --> 00:00:50.170\nJestliže používáš tablet,\n\n19\n00:00:50.170 --> 00:00:53.440\nstiskni a podrž daný blok dokud se neobjeví nabídka možností.\n\n20\n00:00:53.440 --> 00:00:55.053\nPotom vyber Vymazat.\n\n21\n00:00:57.030 --> 00:00:58.410\nJestliže chceš blok přesunout\n\n22\n00:00:58.410 --> 00:01:00.460\nze svého projektu pro pozdější použití,\n\n23\n00:01:00.460 --> 00:01:04.220\nodeber jej ze zásobníku a přesuň ho na stranu.\n\n24\n00:01:04.220 --> 00:01:06.990\nPamatuj, že pouze bloky připojené k počátečním blokům,\n\n25\n00:01:06.990 --> 00:01:10.383\nbudou poslány tvému robotovi při stažení projektu.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Crear un proyecto de bloques V5 es fácil.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nLos bloques pueden ser arrastrados desde la caja de herramientas\n\n3\n00:00:06.010 --> 00:00:07.963\nal espacio de trabajo del proyecto.\n\n4\n00:00:11.250 --> 00:00:13.560\nAhí, los bloques pueden ser apliados juntos\n\n5\n00:00:13.560 --> 00:00:14.923\npara crear su proyecto.\n\n6\n00:00:16.270 --> 00:00:18.070\nTambién puedes reorganizar bloques\n\n7\n00:00:18.070 --> 00:00:19.850\narrastrándolos de una pila\n\n8\n00:00:20.970 --> 00:00:24.093\ne insertarlos en un lugar diferente de su proyecto.\n\n9\n00:00:25.170 --> 00:00:26.090\nEn algún momento,\n\n10\n00:00:26.090 --> 00:00:29.240\nes posible que desee eliminar un bloque del proyecto.\n\n11\n00:00:29.240 --> 00:00:31.070\nPara eliminar parte de una pila de bloques\n\n12\n00:00:31.070 --> 00:00:32.440\nque no están dentro de un bucle,\n\n13\n00:00:32.440 --> 00:00:34.430\nsepara los bloques de su proyecto\n\n14\n00:00:34.430 --> 00:00:36.363\ny arrástralo de vuelta al área de la caja de herramientas.\n\n15\n00:00:39.270 --> 00:00:41.670\nPara eliminar un bloque que está en medio de una pila,\n\n16\n00:00:42.510 --> 00:00:45.480\nclic derecho en el bloque que desea eliminar\n\n17\n00:00:45.480 --> 00:00:47.663\ny seleccione la opción Eliminar (borrar).\n\n18\n00:00:48.560 --> 00:00:50.170\nSi se utiliza una tableta,\n\n19\n00:00:50.170 --> 00:00:53.440\nmantén presionado el bloque hasta que aparezcan las opciones.\n\n20\n00:00:53.440 --> 00:00:55.053\nLuego, selecciona Eliminar (borrar).\n\n21\n00:00:57.030 --> 00:00:58.410\nSi desea mover un bloque\n\n22\n00:00:58.410 --> 00:01:00.460\nde su proyecto para su uso posterior\n\n23\n00:01:00.460 --> 00:01:04.220\nelimínelo de la pila y muévalo hacia un lado.\n\n24\n00:01:04.220 --> 00:01:06.990\nTen en cuenta que solo bloques conectados a bloques con tapa\n\n25\n00:01:06.990 --> 00:01:10.383\nse enviará al robot cuando su proyecto sea descargado.\n\n","es":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Crear un proyecto de bloques V5 es fácil.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nLos bloques pueden ser arrastrados desde la caja de herramientas\n\n3\n00:00:06.010 --> 00:00:07.963\nal espacio de trabajo del proyecto.\n\n4\n00:00:11.250 --> 00:00:13.560\nAhí, los bloques pueden ser apliados juntos\n\n5\n00:00:13.560 --> 00:00:14.923\npara crear su proyecto.\n\n6\n00:00:16.270 --> 00:00:18.070\nTambién puedes reorganizar bloques\n\n7\n00:00:18.070 --> 00:00:19.850\narrastrándolos de una pila\n\n8\n00:00:20.970 --> 00:00:24.093\ne insertarlos en un lugar diferente de su proyecto.\n\n9\n00:00:25.170 --> 00:00:26.090\nEn algún momento,\n\n10\n00:00:26.090 --> 00:00:29.240\nes posible que desee eliminar un bloque del proyecto.\n\n11\n00:00:29.240 --> 00:00:31.070\nPara eliminar parte de una pila de bloques\n\n12\n00:00:31.070 --> 00:00:32.440\nque no están dentro de un bucle,\n\n13\n00:00:32.440 --> 00:00:34.430\nsepara los bloques de su proyecto\n\n14\n00:00:34.430 --> 00:00:36.363\ny arrástralo de vuelta al área de la caja de herramientas.\n\n15\n00:00:39.270 --> 00:00:41.670\nPara eliminar un bloque que está en medio de una pila,\n\n16\n00:00:42.510 --> 00:00:45.480\nclic derecho en el bloque que desea eliminar\n\n17\n00:00:45.480 --> 00:00:47.663\ny seleccione la opción Eliminar (borrar).\n\n18\n00:00:48.560 --> 00:00:50.170\nSi se utiliza una tableta,\n\n19\n00:00:50.170 --> 00:00:53.440\nmantén presionado el bloque hasta que aparezcan las opciones.\n\n20\n00:00:53.440 --> 00:00:55.053\nLuego, selecciona Eliminar (borrar).\n\n21\n00:00:57.030 --> 00:00:58.410\nSi desea mover un bloque\n\n22\n00:00:58.410 --> 00:01:00.460\nde su proyecto para su uso posterior\n\n23\n00:01:00.460 --> 00:01:04.220\nelimínelo de la pila y muévalo hacia un lado.\n\n24\n00:01:04.220 --> 00:01:06.990\nTen en cuenta que solo bloques conectados a bloques con tapa\n\n25\n00:01:06.990 --> 00:01:10.383\nse enviará al robot cuando su proyecto sea descargado.\n\n","fi":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>V5 blokkiohjelman teko on helppoa.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBlokit voi raahata työkaluikkunasta\n\n3\n00:00:06.010 --> 00:00:07.963\nohjelman työalueelle.\n\n4\n00:00:11.250 --> 00:00:13.560\nBlokit pitää pinota päällekkäin\n\n5\n00:00:13.560 --> 00:00:14.923\nja niistä syntyy oma ohjelmasi.\n\n6\n00:00:16.270 --> 00:00:18.070\nVoit uudelleenjärjestää blokit\n\n7\n00:00:18.070 --> 00:00:19.850\nirrottamalla ne vetämällä pois pinosta\n\n8\n00:00:20.970 --> 00:00:24.093\nja siirtämällä eri kohtaan ohjelmaasi.\n\n9\n00:00:25.170 --> 00:00:26.090\nJoskus\n\n10\n00:00:26.090 --> 00:00:29.240\nhaluat poistaa blokin ohjelmasta.\n\n11\n00:00:29.240 --> 00:00:31.070\nOsan blokkien poisto pinosta,\n\n12\n00:00:31.070 --> 00:00:32.440\njos blokit eivät ole toistorakenteen sisällä\n\n13\n00:00:32.440 --> 00:00:34.430\ntapahtuu erottamalla ne muusta ohjelmasta\n\n14\n00:00:34.430 --> 00:00:36.363\nja vetämällä paketti takaisin työkalualueelle.\n\n15\n00:00:39.270 --> 00:00:41.670\nKeskellä pinoa olevan blokkin poisto\n\n16\n00:00:42.510 --> 00:00:45.480\nonnistuu painamalla blokkia hiiren oikealla\n\n17\n00:00:45.480 --> 00:00:47.663\nja valitsemalla Poista blokki.\n\n18\n00:00:48.560 --> 00:00:50.170\nJos käytät tablettia ohjelmoinnissa\n\n19\n00:00:50.170 --> 00:00:53.440\npaina ja pidä blokkia kunnes eri valinnat tulevat näkyviin.\n\n20\n00:00:53.440 --> 00:00:55.053\nja valitse Poista.\n\n21\n00:00:57.030 --> 00:00:58.410\nJos haluat siirtää blokkia pinossa\n\n22\n00:00:58.410 --> 00:01:00.460\npinosta myöhempään käyttöä varten\n\n23\n00:01:00.460 --> 00:01:04.220\nvoit siirtää blokin pinosta ohjelma-alueen reunaan.\n\n24\n00:01:04.220 --> 00:01:06.990\nVain ns aloitusblokkeihin pinotut blokit\n\n25\n00:01:06.990 --> 00:01:10.383\nlähetään robottiin, kun ohjelma ladataan V5 Aivoihin.\n\n","fr":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>La création d'un projet V5 Blocs est facile.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nLes blocs peuvent être glissés et déposés depuis la boîte à outils\n\n3\n00:00:06.010 --> 00:00:07.963\ndans l'espace de travail du projet.\n\n4\n00:00:11.250 --> 00:00:13.560\nIci, les blocs peuvent être empilés les uns sur les autres\n\n5\n00:00:13.560 --> 00:00:14.923\npour créer votre projet.\n\n6\n00:00:16.270 --> 00:00:18.070\nVous pouvez également réarranger les blocs\n\n7\n00:00:18.070 --> 00:00:19.850\nen les faisant glisser en dehors d'une pile\n\n8\n00:00:20.970 --> 00:00:24.093\net en les insérant à un endroit différent de votre projet.\n\n9\n00:00:25.170 --> 00:00:26.090\nÀ un moment ou à un autre,\n\n10\n00:00:26.090 --> 00:00:29.240\nvous pourriez vouloir supprimer un bloc de votre projet.\n\n11\n00:00:29.240 --> 00:00:31.070\nPour supprimer une partie d'une pile de blocs\n\n12\n00:00:31.070 --> 00:00:32.440\nqui ne sont pas dans une boucle,\n\n13\n00:00:32.440 --> 00:00:34.430\nséparez les blocs de votre projet\n\n14\n00:00:34.430 --> 00:00:36.363\net faites-les glisser vers la boîte à outils.\n\n15\n00:00:39.270 --> 00:00:41.670\nPour supprimer un bloc au milieu d'une pile,\n\n16\n00:00:42.510 --> 00:00:45.480\nfaites un clic droit sur le bloc que vous souhaitez supprimer\n\n17\n00:00:45.480 --> 00:00:47.663\net choisissez l'option \"Supprimer\".\n\n18\n00:00:48.560 --> 00:00:50.170\nSi vous utilisez une tablette,\n\n19\n00:00:50.170 --> 00:00:53.440\npressez et maintenez le bloc jusqu'à ce que les options apparaissent.\n\n20\n00:00:53.440 --> 00:00:55.053\nEnsuite, choisissez \"Supprimer\".\n\n21\n00:00:57.030 --> 00:00:58.410\nSi vous voulez déplacer un bloc\n\n22\n00:00:58.410 --> 00:01:00.460\nde votre projet pour une utilisation ultérieure,\n\n23\n00:01:00.460 --> 00:01:04.220\nretirez-le de la pile et déplacez-le sur le côté.\n\n24\n00:01:04.220 --> 00:01:06.990\nGardez à l'esprit que seuls les blocs connectés aux blocs chapeaux\n\n25\n00:01:06.990 --> 00:01:10.383\nseront envoyés au robot lorsque votre projet sera téléchargé.\n\n","ko":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>V5 블록 프로젝트를 만들기는 쉽습니다.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\n도구 상자로부터 블록을 드래그하여\n\n3\n00:00:06.010 --> 00:00:07.963\n프로젝트 작업 공간으로 옮길 수 있습니다.\n\n4\n00:00:11.250 --> 00:00:13.560\n거기에서 블록을 쌓아\n\n5\n00:00:13.560 --> 00:00:14.923\n프로젝트를 만들 수 있습니다.\n\n6\n00:00:16.270 --> 00:00:18.070\n블록을 스택에서 드래그하여\n\n7\n00:00:18.070 --> 00:00:19.850\n프로젝트의 다른 위치로 옮겨\n\n8\n00:00:20.970 --> 00:00:24.093\n재정렬할 수도 있습니다.\n\n9\n00:00:25.170 --> 00:00:26.090\n언젠가는\n\n10\n00:00:26.090 --> 00:00:29.240\n프로젝트에서 블록을 삭제하고 싶을 수 있습니다.\n\n11\n00:00:29.240 --> 00:00:31.070\n루프 내에 있지 않은\n\n12\n00:00:31.070 --> 00:00:32.440\n블록 스택의 일부를 삭제하려면\n\n13\n00:00:32.440 --> 00:00:34.430\n프로젝트에서 블록을 분리하여\n\n14\n00:00:34.430 --> 00:00:36.363\n도구 상자 영역으로 다시 드래그하세요.\n\n15\n00:00:39.270 --> 00:00:41.670\n스택 중간에 있는 블록을 삭제하려면\n\n16\n00:00:42.510 --> 00:00:45.480\n삭제할 블록 위에서 마우스 오른쪽을 클릭하여\n\n17\n00:00:45.480 --> 00:00:47.663\n삭제를 선택합니다.\n\n18\n00:00:48.560 --> 00:00:50.170\n태블릿을 사용하고 있다면\n\n19\n00:00:50.170 --> 00:00:53.440\n옵션이 나타날 때까지 블록을 길게 누르세요.\n\n20\n00:00:53.440 --> 00:00:55.053\n그리고 삭제를 선택하세요.\n\n21\n00:00:57.030 --> 00:00:58.410\n나중에 사용하기 위해\n\n22\n00:00:58.410 --> 00:01:00.460\n프로젝트에서 블록을 이동하려면\n\n23\n00:01:00.460 --> 00:01:04.220\n스택에서 블록을 떼어내 분리하여 옆으로 옮겨 두세요.\n\n24\n00:01:04.220 --> 00:01:06.990\n프로젝트를 다운로드할 때 모자 블록(Hat Blocks)에 연결된 블록만\n\n25\n00:01:06.990 --> 00:01:10.383\n로봇으로 전송됨을 기억하세요.\n\n","lt":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Lengva sukurti \"V5\" blokų projektą.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nIš parankinės į projekto darbinę sritį\n\n3\n00:00:06.010 --> 00:00:07.963\ngalite tįsti blokus.\n\n4\n00:00:11.250 --> 00:00:13.560\nDarbo srityje blokus galite sudėti vieną ant kito\n\n5\n00:00:13.560 --> 00:00:14.923\nsavo projektui sukurti.\n\n6\n00:00:16.270 --> 00:00:18.070\nBlokus taip pat galite pertvarkyti,\n\n7\n00:00:18.070 --> 00:00:19.850\ntįsdami juos nuo krūvos\n\n8\n00:00:20.970 --> 00:00:24.093\nir patalpindami į skirtingą projekto vietą.\n\n9\n00:00:25.170 --> 00:00:26.090\nKažkada\n\n10\n00:00:26.090 --> 00:00:29.240\ngalite norėti iš savo projekto ištrinti bloką.\n\n11\n00:00:29.240 --> 00:00:31.070\nKad ištrintumėte blokų krūvos dalį,\n\n12\n00:00:31.070 --> 00:00:32.440\nkuri nėra programos ciklo dalis,\n\n13\n00:00:32.440 --> 00:00:34.430\niš savo projekto atskirkite blokus\n\n14\n00:00:34.430 --> 00:00:36.363\nir tįskite atgal į parankinės sritį.\n\n15\n00:00:39.270 --> 00:00:41.670\nNorėdami ištrinti krūvos viduryje esantį bloką,\n\n16\n00:00:42.510 --> 00:00:45.480\nant norimo ištrinti bloko spustelėkite dešinįjį pelės klavišą\n\n17\n00:00:45.480 --> 00:00:47.663\nir pasirinkite parinktį \"Ištrinti\".\n\n18\n00:00:48.560 --> 00:00:50.170\nJeigu naudojate planšetę,\n\n19\n00:00:50.170 --> 00:00:53.440\nlaikykite nuspaudę bloką, kol ekrane pasirodys atitinkamos parinktys.\n\n20\n00:00:53.440 --> 00:00:55.053\nPo to, spustelėkite \"Ištrinti\".\n\n21\n00:00:57.030 --> 00:00:58.410\nJeigu norite perkelti bloką\n\n22\n00:00:58.410 --> 00:01:00.460\niš savo vėlesniam naudojimui skirto projekto,\n\n23\n00:01:00.460 --> 00:01:04.220\nišimkite bloką iš krūvos ir patraukite į šalį.\n\n24\n00:01:04.220 --> 00:01:06.990\nĮsidėmėkite, kad tik prie kitų blokų prijungti blokai\n\n25\n00:01:06.990 --> 00:01:10.383\nbus siunčiami robotui, kai Jūsų projektas bus parsiųstas.\n\n","lv":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>V5 Bloku projekta izveidošana ir vienkārša.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBlokus var vilkt no rīklodziņa\n\n3\n00:00:06.010 --> 00:00:07.963\nprojekta darbalaukā.\n\n4\n00:00:11.250 --> 00:00:13.560\nŠeit blokus var salikt kopā,\n\n5\n00:00:13.560 --> 00:00:14.923\nlai izveidotu savu projektu.\n\n6\n00:00:16.270 --> 00:00:18.070\nBlokus var arī pārkārtot,\n\n7\n00:00:18.070 --> 00:00:19.850\nizvelkot tos no saliktajiem blokiem\n\n8\n00:00:20.970 --> 00:00:24.093\nun ievietojot tos citā jūsu projekta daļā.\n\n9\n00:00:25.170 --> 00:00:26.090\nTurpinot darboties, iespējams,\n\n10\n00:00:26.090 --> 00:00:29.240\njūs vēlēsieties izdzēst kādu no blokiem no sava projekta.\n\n11\n00:00:29.240 --> 00:00:31.070\nLai dzēstu daļu no saliktajiem blokiem,\n\n12\n00:00:31.070 --> 00:00:32.440\nkas neatrodas ciklā,\n\n13\n00:00:32.440 --> 00:00:34.430\natdaliet blokus no sava projekta\n\n14\n00:00:34.430 --> 00:00:36.363\nun velciet tos atpakaļ rīklodziņa laukumā.\n\n15\n00:00:39.270 --> 00:00:41.670\nLai izdzēstu bloku, kas atrodas kombinēto bloku vidū,\n\n16\n00:00:42.510 --> 00:00:45.480\nnoklikšķiniet ar peles labo pogu uz bloka, kuru vēlaties izdzēst\n\n17\n00:00:45.480 --> 00:00:47.663\nun izvēlieties opciju “Delete”.\n\n18\n00:00:48.560 --> 00:00:50.170\nJa lietojiet planšetdatoru,\n\n19\n00:00:50.170 --> 00:00:53.440\nspiediet un turiet bloku, līdz tiek parādītas opcijas.\n\n20\n00:00:53.440 --> 00:00:55.053\nPēc tam izvēlieties “Delete”.\n\n21\n00:00:57.030 --> 00:00:58.410\nJa vēlaties izņemt bloku\n\n22\n00:00:58.410 --> 00:01:00.460\nno jūsu projekta vēlākai izmantošanai,\n\n23\n00:01:00.460 --> 00:01:04.220\nizņemiet to no saliktā bloka un pārvietojiet uz sāniem.\n\n24\n00:01:04.220 --> 00:01:06.990\nŅemiet vērā, ka tikai tie bloki, kas savienoti ar sākuma bloku,\n\n25\n00:01:06.990 --> 00:01:10.383\ntiks nosūtīti uz robotu, kad tiks lejupielādēts jūsu projekts.\n\n","nl":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Het is makkelijk om een V5 block-project te maken.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBlokken kunnen vanuit de werkbalk\n\n3\n00:00:06.010 --> 00:00:07.963\nnaar de projectwerkruimte worden gesleept.\n\n4\n00:00:11.250 --> 00:00:13.560\nDaar kunnen blokken op elkaar worden gestapeld\n\n5\n00:00:13.560 --> 00:00:14.923\nom uw project te creëren.\n\n6\n00:00:16.270 --> 00:00:18.070\nU kunt blokken ook herschikken\n\n7\n00:00:18.070 --> 00:00:19.850\ndoor ze van een stapel te slepen\n\n8\n00:00:20.970 --> 00:00:24.093\nen ze op een andere plek in het project invoegen.\n\n9\n00:00:25.170 --> 00:00:26.090\nOp een gegeven moment\n\n10\n00:00:26.090 --> 00:00:29.240\nwilt u misschien een blok uit uw project verwijderen.\n\n11\n00:00:29.240 --> 00:00:31.070\nOm een deel van een stapel blokken te verwijderen\n\n12\n00:00:31.070 --> 00:00:32.440\ndie niet binnen een lus vallen,\n\n13\n00:00:32.440 --> 00:00:34.430\nscheid de blokken van uw project\n\n14\n00:00:34.430 --> 00:00:36.363\nen sleep het terug naar de werkbalk.\n\n15\n00:00:39.270 --> 00:00:41.670\nOm een blok te verwijderen dat zich in het midden van een stapel bevindt\n\n16\n00:00:42.510 --> 00:00:45.480\nklik met de rechtermuisknop op het blok dat u wilt verwijderen\n\n17\n00:00:45.480 --> 00:00:47.663\nen selecteer de optie Verwijderen.\n\n18\n00:00:48.560 --> 00:00:50.170\nBij gebruik van een tablet,\n\n19\n00:00:50.170 --> 00:00:53.440\nhoud het blok ingedrukt totdat de opties verschijnen.\n\n20\n00:00:53.440 --> 00:00:55.053\nSelecteer dan Verwijderen.\n\n21\n00:00:57.030 --> 00:00:58.410\nAls u een blok uit uw project wilt verplaatsen\n\n22\n00:00:58.410 --> 00:01:00.460\nom het later te gebruiken,\n\n23\n00:01:00.460 --> 00:01:04.220\nverwijder het van de stapel en verplaats het opzij.\n\n24\n00:01:04.220 --> 00:01:06.990\nHoud er rekening mee dat alleen blokken die aan de hoed blokken verbonden zijn\n\n25\n00:01:06.990 --> 00:01:10.383\nnaar de robot worden gestuurd wanneer uw project is gedownload.\n\n","pl":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Tworzenie projektu V5 jest łatwe.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nBloki mogą być przeciągane z przybornika\n\n3\n00:00:06.010 --> 00:00:07.963\ndo obszaru roboczego projektu.\n\n4\n00:00:11.250 --> 00:00:13.560\nTam bloki mogą być połączone razem\n\n5\n00:00:13.560 --> 00:00:14.923\naby utworzyć swój projekt.\n\n6\n00:00:16.270 --> 00:00:18.070\nMożesz również zmienić kolejność bloków\n\n7\n00:00:18.070 --> 00:00:19.850\nprzeciągając je ze stosu\n\n8\n00:00:20.970 --> 00:00:24.093\ni umieścić je w innym miejscu w Twoim projekcie.\n\n9\n00:00:25.170 --> 00:00:26.090\nW pewnym momencie,\n\n10\n00:00:26.090 --> 00:00:29.240\nmożesz chcieć usunąć blok z projektu.\n\n11\n00:00:29.240 --> 00:00:31.070\nAby usunąć część zestawu bloków\n\n12\n00:00:31.070 --> 00:00:32.440\nktóre nie znajdują się w pętli,\n\n13\n00:00:32.440 --> 00:00:34.430\nusunąć blok z projektu\n\n14\n00:00:34.430 --> 00:00:36.363\ni przeciągnij go z powrotem do obszaru przybornika.\n\n15\n00:00:39.270 --> 00:00:41.670\nAby usunąć blok, który znajduje się na środku stosu,\n\n16\n00:00:42.510 --> 00:00:45.480\nkliknij prawym przyciskiem myszy na blok, który chcesz usunąć\n\n17\n00:00:45.480 --> 00:00:47.663\ni wybierz opcję Usuń.\n\n18\n00:00:48.560 --> 00:00:50.170\nW przypadku stosowania tabletu,\n\n19\n00:00:50.170 --> 00:00:53.440\nnaciśnij i przytrzymaj blok aż do pojawienia się opcji.\n\n20\n00:00:53.440 --> 00:00:55.053\nNastępnie wybierz Usuń.\n\n21\n00:00:57.030 --> 00:00:58.410\nJeśli chcesz przesunąć blok\n\n22\n00:00:58.410 --> 00:01:00.460\nz twojego projektu do późniejszego użycia,\n\n23\n00:01:00.460 --> 00:01:04.220\nusuń go ze stosu i przesuń go na bok.\n\n24\n00:01:04.220 --> 00:01:06.990\nPamiętaj, że tylko bloki połączone z \"hat\" blok\n\n25\n00:01:06.990 --> 00:01:10.383\nzostaną wysłane do robota\npo rozpoczęciu projektu.\n\n","ru":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Блоковый проект создать довольно просто.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nБлоки можно перетаскивать из библиотеки блоков\n\n3\n00:00:06.010 --> 00:00:07.963\nв ваш проект.\n\n4\n00:00:11.250 --> 00:00:13.560\nБлоки могут соединяться между собой\n\n5\n00:00:13.560 --> 00:00:14.923\nдля создания проекта.\n\n6\n00:00:16.270 --> 00:00:18.070\nВы можете реорганизовывать блоки,\n\n7\n00:00:18.070 --> 00:00:19.850\nпросто убирая их из стэка блоков,\n\n8\n00:00:20.970 --> 00:00:24.093\nи вставляя в другое место вашего проекта.\n\n9\n00:00:25.170 --> 00:00:26.090\nВ какой-то момент,\n\n10\n00:00:26.090 --> 00:00:29.240\nвам понадобится удалить блоки из проекта.\n\n11\n00:00:29.240 --> 00:00:31.070\nДля удаления стэка блоков\n\n12\n00:00:31.070 --> 00:00:32.440\nвне цикла,\n\n13\n00:00:32.440 --> 00:00:34.430\nотделите их от вашего проекта\n\n14\n00:00:34.430 --> 00:00:36.363\nи перетащите в область библиотеки блоков.\n\n15\n00:00:39.270 --> 00:00:41.670\nДля удаления блоков в середине стэка,\n\n16\n00:00:42.510 --> 00:00:45.480\nнажмите правой кнопкой мыши на нужный блок\n\n17\n00:00:45.480 --> 00:00:47.663\nи нажмите «Удалить».\n\n18\n00:00:48.560 --> 00:00:50.170\nПри использовании планшета,\n\n19\n00:00:50.170 --> 00:00:53.440\nнажмите и удерживайте блок, пока не появятся опции.\n\n20\n00:00:53.440 --> 00:00:55.053\nЗатем, нажмите удалить.\n\n21\n00:00:57.030 --> 00:00:58.410\nЕсли вы хотите переместить блок\n\n22\n00:00:58.410 --> 00:01:00.460\nдля дальнейшего использования\n\n23\n00:01:00.460 --> 00:01:04.220\nпереместите его из общего стека в сторону.\n\n24\n00:01:04.220 --> 00:01:06.990\nПомните, что выполняются только блоки, подсоединённые\n\n25\n00:01:06.990 --> 00:01:10.383\nк блоку начала программы, и они же будут запущены при запуске программы.\n\n","th":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor> การสร้างโปรเจ็คบล็อก V5 นั้นเป็นเรื่องง่าย </v>\n\n2\n00:00:03.740 --> 00:00:06.010\nบล็อกสามารถลากมาจาก toolbox\n\n3\n00:00:06.010 --> 00:00:07.963\nมาที่ workspace ของโปรเจ็ค\n\n4\n00:00:11.250 --> 00:00:13.560\nที่นี่, บล็อกสามารถเชื่อมติดกัน\n\n5\n00:00:13.560 --> 00:00:14.923\nเพื่อสร้างโปรเจ็คของคุณ\n\n6\n00:00:16.270 --> 00:00:18.070\nคุณยังสามารถจัดเรียงบล็อก\n\n7\n00:00:18.070 --> 00:00:19.850\nได้โดยการลากบล็อกออกจากการเชื่อมต่อกัน\n\n8\n00:00:20.970 --> 00:00:24.093\nและเพิ่มบล็อกดังกล่าวลงไปในตำแหน่งอื่นในโปรเจ็คของคุณ\n\n9\n00:00:25.170 --> 00:00:26.090\nในบางกรณี\n\n10\n00:00:26.090 --> 00:00:29.240\nคุณอาจจะต้องการลบบล็อกออกจากโปรเจ็คของคุณ\n\n11\n00:00:29.240 --> 00:00:31.070\nหากต้องการลบกลุ่มของบล็อก\n\n12\n00:00:31.070 --> 00:00:32.440\nที่ไม่ได้อยู่ในลูป\n\n13\n00:00:32.440 --> 00:00:34.430\nทำได้โดยการแยกบล็อกในโปรเจ็คของคุณออกมา\n\n14\n00:00:34.430 --> 00:00:36.363\nและลากบล็อกนั้นกลับไปที่กล่องเครื่องมือ toolbox\n\n15\n00:00:39.270 --> 00:00:41.670\nหากต้องการลบบล็อกที่เชื่อมกันอยู่\n\n16\n00:00:42.510 --> 00:00:45.480\nคลิ๊กขวา ที่บล็อกที่ต้องการลบ\n\n17\n00:00:45.480 --> 00:00:47.663\nและเลือกลบ\n\n18\n00:00:48.560 --> 00:00:50.170\nหากคุณใช้ tablet\n\n19\n00:00:50.170 --> 00:00:53.440\nกดค้างที่บล็อกจนกว่าจะเห็นตัวเลือกขึ้นมา\n\n20\n00:00:53.440 --> 00:00:55.053\nจากนั้นเลือกลบ delete\n\n21\n00:00:57.030 --> 00:00:58.410\nหากคุณต้องการย้ายบล็อก\n\n22\n00:00:58.410 --> 00:01:00.460\nจากโปรเจ็คของคุณเพื่อใช้ในภายหลัง\n\n23\n00:01:00.460 --> 00:01:04.220\nนำออกจาก stack แล้วย้ายออกไปด้านข้าง\n\n24\n00:01:04.220 --> 00:01:06.990\nโปรดทราบว่าบล็อกที่เชื่อมต่อกับ hat blocks เท่านั้น\n\n25\n00:01:06.990 --> 00:01:10.383\nที่จะถูกส่งไปยังหุ่นยนต์เมื่อโปรเจ็คของคุณถูกดาวน์โหลด\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor> Створити блоковий V5 проєкт легко.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nБлоки можна перетягувати з набору блоків\n\n3\n00:00:06.010 --> 00:00:07.963\nдо робочої області проєкту.\n\n4\n00:00:11.250 --> 00:00:13.560\nТут блоки можна з'єднувати\n\n5\n00:00:13.560 --> 00:00:14.923\nдля створення проєкту.\n\n6\n00:00:16.270 --> 00:00:18.070\nТакож ви можете переставити блоки,\n\n7\n00:00:18.070 --> 00:00:19.850\nвитягнувши їх з однієї позиції стека\n\n8\n00:00:20.970 --> 00:00:24.093\nі вставивши в інше місце проєкту.\n\n9\n00:00:25.170 --> 00:00:26.090\nНа певному етапі\n\n10\n00:00:26.090 --> 00:00:29.240\nвиникне потреба видалити блок.\n\n11\n00:00:29.240 --> 00:00:31.070\nДля видалення частини блоків,\n\n12\n00:00:31.070 --> 00:00:32.440\nякі не є в циклі,\n\n13\n00:00:32.440 --> 00:00:34.430\nвідділіть непотрібні блоки від проєкту\n\n14\n00:00:34.430 --> 00:00:36.363\nі перемістіть їх назад до набору блоків.\n\n15\n00:00:39.270 --> 00:00:41.670\nДля видалення блока із середини стека\n\n16\n00:00:42.510 --> 00:00:45.480\nнатисніть на нього правою кнопкою миші\n\n17\n00:00:45.480 --> 00:00:47.663\nі виберіть \"Видалити\".\n\n18\n00:00:48.560 --> 00:00:50.170\nЯкщо використовуєте планшет,\n\n19\n00:00:50.170 --> 00:00:53.440\nнатисніть і утримуйте блок, поки не з'являться його параметри.\n\n20\n00:00:53.440 --> 00:00:55.053\nА потім виберіть \"Видалити\".\n\n21\n00:00:57.030 --> 00:00:58.410\nЯкщо ви хочете перемістити блок\n\n22\n00:00:58.410 --> 00:01:00.460\nіз вашого проєкту для використання пізніше,\n\n23\n00:01:00.460 --> 00:01:04.220\nвитягніть його зі стека і відсуньте убік.\n\n24\n00:01:04.220 --> 00:01:06.990\nМайте на увазі, що завантажені до робота будуть лише ті\n\n25\n00:01:06.990 --> 00:01:10.383\nблоки, які приєднані до стартових.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>Dễ dàng tạo dự án khối V5.</v>\n\n2\n00:00:03.740 --> 00:00:06.010\nCác khối có thể được kéo từ hộp công cụ\n\n3\n00:00:06.010 --> 00:00:07.963\nvào không gian làm việc của dự án.\n\n4\n00:00:11.250 --> 00:00:13.560\nỞ đó, các khối có thể được xếp chồng lên nhau\n\n5\n00:00:13.560 --> 00:00:14.923\nđể tạo dự án của bạn.\n\n6\n00:00:16.270 --> 00:00:18.070\nBạn cũng có thể sắp xếp lại các khối\n\n7\n00:00:18.070 --> 00:00:19.850\nbằng cách kéo chúng ra khỏi một ngăn xếp\n\n8\n00:00:20.970 --> 00:00:24.093\nvà chèn chúng vào một vị trí khác trong dự án của bạn.\n\n9\n00:00:25.170 --> 00:00:26.090\nỞ một vài điểm,\n\n10\n00:00:26.090 --> 00:00:29.240\nbạn có thể muốn xóa một khối khỏi dự án của mình.\n\n11\n00:00:29.240 --> 00:00:31.070\nĐể xóa một phần của chồng khối\n\n12\n00:00:31.070 --> 00:00:32.440\nkhông nằm trong một vòng lặp,\n\n13\n00:00:32.440 --> 00:00:34.430\ntách các khối khỏi dự án của bạn\n\n14\n00:00:34.430 --> 00:00:36.363\nvà kéo nó trở lại khu vực hộp công cụ.\n\n15\n00:00:39.270 --> 00:00:41.670\nĐể xóa một khối nằm giữa ngăn xếp,\n\n16\n00:00:42.510 --> 00:00:45.480\nnhấp chuột phải vào khối bạn muốn xóa\n\n17\n00:00:45.480 --> 00:00:47.663\nvà chọn tùy chọn xóa.\n\n18\n00:00:48.560 --> 00:00:50.170\nNếu sử dụng máy tính bảng,\n\n19\n00:00:50.170 --> 00:00:53.440\nnhấn và giữ khối cho đến khi các tùy chọn xuất hiện.\n\n20\n00:00:53.440 --> 00:00:55.053\nSau đó, chọn xóa.\n\n21\n00:00:57.030 --> 00:00:58.410\nNếu bạn muốn di chuyển một khối\n\n22\n00:00:58.410 --> 00:01:00.460\ntừ dự án của bạn để sử dụng sau này,\n\n23\n00:01:00.460 --> 00:01:04.220\nloại bỏ nó khỏi ngăn xếp và di chuyển nó sang một bên.\n\n24\n00:01:04.220 --> 00:01:06.990\nHãy nhớ rằng chỉ các khối được kết nối với khối mũ\n\n25\n00:01:06.990 --> 00:01:10.383\nsẽ được gửi đến rô bốt khi dự án của bạn được tải xuống.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\ncrwdns96222:0crwdne96222:0\n\n2\n00:00:03.740 --> 00:00:06.010\ncrwdns96224:0crwdne96224:0\n\n3\n00:00:06.010 --> 00:00:07.963\ncrwdns96226:0crwdne96226:0\n\n4\n00:00:11.250 --> 00:00:13.560\ncrwdns96228:0crwdne96228:0\n\n5\n00:00:13.560 --> 00:00:14.923\ncrwdns96230:0crwdne96230:0\n\n6\n00:00:16.270 --> 00:00:18.070\ncrwdns96232:0crwdne96232:0\n\n7\n00:00:18.070 --> 00:00:19.850\ncrwdns96234:0crwdne96234:0\n\n8\n00:00:20.970 --> 00:00:24.093\ncrwdns96236:0crwdne96236:0\n\n9\n00:00:25.170 --> 00:00:26.090\ncrwdns96238:0crwdne96238:0\n\n10\n00:00:26.090 --> 00:00:29.240\ncrwdns96240:0crwdne96240:0\n\n11\n00:00:29.240 --> 00:00:31.070\ncrwdns96242:0crwdne96242:0\n\n12\n00:00:31.070 --> 00:00:32.440\ncrwdns96244:0crwdne96244:0\n\n13\n00:00:32.440 --> 00:00:34.430\ncrwdns96246:0crwdne96246:0\n\n14\n00:00:34.430 --> 00:00:36.363\ncrwdns96248:0crwdne96248:0\n\n15\n00:00:39.270 --> 00:00:41.670\ncrwdns96250:0crwdne96250:0\n\n16\n00:00:42.510 --> 00:00:45.480\ncrwdns96252:0crwdne96252:0\n\n17\n00:00:45.480 --> 00:00:47.663\ncrwdns96254:0crwdne96254:0\n\n18\n00:00:48.560 --> 00:00:50.170\ncrwdns96256:0crwdne96256:0\n\n19\n00:00:50.170 --> 00:00:53.440\ncrwdns96258:0crwdne96258:0\n\n20\n00:00:53.440 --> 00:00:55.053\ncrwdns96260:0crwdne96260:0\n\n21\n00:00:57.030 --> 00:00:58.410\ncrwdns96262:0crwdne96262:0\n\n22\n00:00:58.410 --> 00:01:00.460\ncrwdns96264:0crwdne96264:0\n\n23\n00:01:00.460 --> 00:01:04.220\ncrwdns96266:0crwdne96266:0\n\n24\n00:01:04.220 --> 00:01:06.990\ncrwdns96268:0crwdne96268:0\n\n25\n00:01:06.990 --> 00:01:10.383\ncrwdns96270:0crwdne96270:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:03.740\n<v Instructor>创建一个V5指令块程序很容易。</v>\n\n2\n00:00:03.740 --> 00:00:06.010\n指令块可以从工具栏被拖拽\n\n3\n00:00:06.010 --> 00:00:07.963\n到程序编辑区。\n\n4\n00:00:11.250 --> 00:00:13.560\n在这里，指令块可以叠搭在一起\n\n5\n00:00:13.560 --> 00:00:14.923\n来创建您的程序。\n\n6\n00:00:16.270 --> 00:00:18.070\n您也可以通过拖离\n\n7\n00:00:18.070 --> 00:00:19.850\n或者将它们插入一个不同的位置\n\n8\n00:00:20.970 --> 00:00:24.093\n来重新排列程序中的指令块。\n\n9\n00:00:25.170 --> 00:00:26.090\n某些时候，\n\n10\n00:00:26.090 --> 00:00:29.240\n你可能想要从程序中删除一个指令块。\n\n11\n00:00:29.240 --> 00:00:31.070\n欲删除一部分不在循环语句里的\n\n12\n00:00:31.070 --> 00:00:32.440\n指令段，\n\n13\n00:00:32.440 --> 00:00:34.430\n从您的程序中分开指令块\n\n14\n00:00:34.430 --> 00:00:36.363\n并将它拖回工具栏区域。\n\n15\n00:00:39.270 --> 00:00:41.670\n欲删除指令段中间的一个指令块，\n\n16\n00:00:42.510 --> 00:00:45.480\n右键点击你想要删除的指令块\n\n17\n00:00:45.480 --> 00:00:47.663\n并选择“删除”选项。\n\n18\n00:00:48.560 --> 00:00:50.170\n如果使用一台平板电脑，\n\n19\n00:00:50.170 --> 00:00:53.440\n按住指令块直到选项出现。\n\n20\n00:00:53.440 --> 00:00:55.053\n然后，选择“删除”。\n\n21\n00:00:57.030 --> 00:00:58.410\n如果您想要从程序中\n\n22\n00:00:58.410 --> 00:01:00.460\n移动一个指令块以备稍后使用，\n\n23\n00:01:00.460 --> 00:01:04.220\n将它从指令段中移出并放到一边。\n\n24\n00:01:04.220 --> 00:01:06.990\n记住只有连接到帽状指令块的指令块\n\n25\n00:01:06.990 --> 00:01:10.383\n在程序已下载后将被发送到机器人。\n\n"}},{"thumb":"V5_Tutorial_basicMovement.jpg","mov":"V5_Blocks_DrivetrainMovements_V2","description":"Drivetrain Movements","filter":"","placeholder":false,"vimeo":"475899379","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Using the drivetrain in VEXcode V5 Blocks</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nmakes driving your robot simple.\n\n3\n00:00:06.310 --> 00:00:09.150\nOnce you have the drivetrain device added,\n\n4\n00:00:09.150 --> 00:00:12.633\na new category of blocks, named Drivetrain, will appear.\n\n5\n00:00:14.000 --> 00:00:15.410\nTo use the drivetrain,\n\n6\n00:00:15.410 --> 00:00:19.150\nselect the, drive forward, block from the toolbox.\n\n7\n00:00:19.150 --> 00:00:22.033\nThen connect it to the, when started block.\n\n8\n00:00:23.400 --> 00:00:26.333\nChoose the distance you'd like the drivetrain to travel.\n\n9\n00:00:28.030 --> 00:00:31.800\nThe distance can be entered in either inches or millimeters,\n\n10\n00:00:31.800 --> 00:00:33.593\nincluding decimal numbers.\n\n11\n00:00:34.700 --> 00:00:37.070\nBy default, the drivetrain will move\n\n12\n00:00:37.070 --> 00:00:39.030\nin the forward direction.\n\n13\n00:00:39.030 --> 00:00:41.170\nTo move the drivetrain in reverse,\n\n14\n00:00:41.170 --> 00:00:43.600\nchange, forward, to, reverse,\n\n15\n00:00:43.600 --> 00:00:44.893\nin the dropdown menu.\n\n16\n00:00:45.880 --> 00:00:49.420\nYou can combine the drive and turn commands together\n\n17\n00:00:49.420 --> 00:00:52.763\nto be able to quickly and autonomously drive your robot.\n\n","ar":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>استخدام نظام الدفع في مشروع VEXcode V5 للبرمجة. </v>\n\n2\n00:00:03.550 --> 00:00:06.310\nيجعل قيادة الروبوت بسيطة.\n\n3\n00:00:06.310 --> 00:00:09.150\nبمجرد إضافة نظام الدفع\n\n4\n00:00:09.150 --> 00:00:12.633\nستظهر فئة جديدة من المقاطع المسماة نظام الدفع.\n\n5\n00:00:14.000 --> 00:00:15.410\nلاستخدام نظام الدفع\n\n6\n00:00:15.410 --> 00:00:19.150\nإختر مقطع القيادة الى الأمام من قائمة الأدوات.\n\n7\n00:00:19.150 --> 00:00:22.033\nثم قم بتوصيل هذا المقطع إلى مقطع \"عند البدء\".\n\n8\n00:00:23.400 --> 00:00:26.333\nاختر المسافة التي ترغب أن يسافرها نظام الدفع.\n\n9\n00:00:28.030 --> 00:00:31.800\nالمسافة من الممكن ادخالها إما بالبوصة أو بالملليمتر،\n\n10\n00:00:31.800 --> 00:00:33.593\nبما في ذلك الأرقام العشرية.\n\n11\n00:00:34.700 --> 00:00:37.070\nعند غياب الاختيار، سيتحرك نظام الدفع\n\n12\n00:00:37.070 --> 00:00:39.030\nفي الاتجاه الأمامي.\n\n13\n00:00:39.030 --> 00:00:41.170\nلتحريك نظام الدفع في اتجاه عكسي،\n\n14\n00:00:41.170 --> 00:00:43.600\nغير الأمام الى الخلف\n\n15\n00:00:43.600 --> 00:00:44.893\nفي القائمة المنسدلة.\n\n16\n00:00:45.880 --> 00:00:49.420\nيمكنك الجمع بين أوامر القيادة والإستدار\n\n17\n00:00:49.420 --> 00:00:52.763\nلكي تكون قادراً على قيادة الروبوت الخاص بك بسرعة وبطريقة تلقائية.\n\n","cs":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Používání podvozku ve VEXcode V5 Blocích</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nusnadňuje řízení tvého robota.\n\n3\n00:00:06.310 --> 00:00:09.150\nJakmile je zařízení Podvozek přidáno,\n\n4\n00:00:09.150 --> 00:00:12.633\nobjeví se nová kategorie bloků s názvem Podvozek.\n\n5\n00:00:14.000 --> 00:00:15.410\nPro použití podvozku\n\n6\n00:00:15.410 --> 00:00:19.150\nvyber blok Jeď o na panelu nástrojů.\n\n7\n00:00:19.150 --> 00:00:22.033\nPotom ho připoj k bloku Při spuštění.\n\n8\n00:00:23.400 --> 00:00:26.333\nVyber vzdálenost, o kterou chceš, aby se tvůj podvozek pohyboval.\n\n9\n00:00:28.030 --> 00:00:31.800\nVzdálenost může být zadána buď v palcích, nebo milimetrech,\n\n10\n00:00:31.800 --> 00:00:33.593\nvčetně desetinných čísel.\n\n11\n00:00:34.700 --> 00:00:37.070\nVe výchozím nastavení pojede podvozek\n\n12\n00:00:37.070 --> 00:00:39.030\nsměrem dopředu.\n\n13\n00:00:39.030 --> 00:00:41.170\nPro rozjetí podvozku směrem dozadu\n\n14\n00:00:41.170 --> 00:00:43.600\nzměň Dopředu na Dozadu\n\n15\n00:00:43.600 --> 00:00:44.893\nv rozbalovacím menu.\n\n16\n00:00:45.880 --> 00:00:49.420\nMůžeš kombinovat příkazy pro jízdu a zatáčení\n\n17\n00:00:49.420 --> 00:00:52.763\npro schopnost rychle a samostatně řídit tvého robota.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Utilizando el Tren Motriz en VEXcode V5 Blocks (bloques)</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nhace que conducir su robot sea simple.\n\n3\n00:00:06.310 --> 00:00:09.150\nUna vez que se ha añadido el dispositivo de Tren Motriz,\n\n4\n00:00:09.150 --> 00:00:12.633\naparecerá una nueva categoría de bloques\nllamado Tren Motriz.\n\n5\n00:00:14.000 --> 00:00:15.410\nPara usar el Tren Motriz,\n\n6\n00:00:15.410 --> 00:00:19.150\nseleccione el bloque \"Conducir Por\" de la caja de herramientas.\n\n7\n00:00:19.150 --> 00:00:22.033\nLuego, conéctalo al bloque\n\"Cuando Empieza\".\n\n8\n00:00:23.400 --> 00:00:26.333\nElige la distancia que le gustaría el Tren Motriz para viajar.\n\n9\n00:00:28.030 --> 00:00:31.800\nLa distancia se puede introducir en milímetros o pulgadas,\n\n10\n00:00:31.800 --> 00:00:33.593\nincluyendo números decimales.\n\n11\n00:00:34.700 --> 00:00:37.070\nPor defecto, el Tren Motriz se moverá\n\n12\n00:00:37.070 --> 00:00:39.030\nen la dirección hacia adelante.\n\n13\n00:00:39.030 --> 00:00:41.170\nPara mover el Tren Motriz en revés,\n\n14\n00:00:41.170 --> 00:00:43.600\ncambia adelante a reversa\n\n15\n00:00:43.600 --> 00:00:44.893\nen el menú desplegable del bloque.\n\n16\n00:00:45.880 --> 00:00:49.420\nPuede combinar los comandos de Conducir y Dar vuelta\n\n17\n00:00:49.420 --> 00:00:52.763\npara poder manejar de forma rápida y\nautónoma su robot.\n\n","es":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Utilizando el Tren Motriz en VEXcode V5 Blocks (bloques)</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nhace que conducir su robot sea simple.\n\n3\n00:00:06.310 --> 00:00:09.150\nUna vez que se ha añadido el dispositivo de Tren Motriz,\n\n4\n00:00:09.150 --> 00:00:12.633\naparecerá una nueva categoría de bloques\nllamado Tren Motriz.\n\n5\n00:00:14.000 --> 00:00:15.410\nPara usar el Tren Motriz,\n\n6\n00:00:15.410 --> 00:00:19.150\nseleccione el bloque \"Conducir Por\" de la caja de herramientas.\n\n7\n00:00:19.150 --> 00:00:22.033\nLuego, conéctalo al bloque\n\"Cuando Empieza\".\n\n8\n00:00:23.400 --> 00:00:26.333\nElige la distancia que le gustaría el Tren Motriz para viajar.\n\n9\n00:00:28.030 --> 00:00:31.800\nLa distancia se puede introducir en milímetros o pulgadas,\n\n10\n00:00:31.800 --> 00:00:33.593\nincluyendo números decimales.\n\n11\n00:00:34.700 --> 00:00:37.070\nPor defecto, el Tren Motriz se moverá\n\n12\n00:00:37.070 --> 00:00:39.030\nen la dirección hacia adelante.\n\n13\n00:00:39.030 --> 00:00:41.170\nPara mover el Tren Motriz en reverso,\n\n14\n00:00:41.170 --> 00:00:43.600\ncambia adelante a reversa\n\n15\n00:00:43.600 --> 00:00:44.893\nen el menú desplegable del bloque.\n\n16\n00:00:45.880 --> 00:00:49.420\nPuede combinar los comandos de Conducir y Dar vuelta\n\n17\n00:00:49.420 --> 00:00:52.763\npara poder manejar de forma rápida y\nautónoma su robot.\n\n","fi":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Kun käyttää Ajopeli-määritystä VEXcode V5 Blocks -ohjelmassa</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nvoit tehdä robotin liikkumisen helpoksi.\n\n3\n00:00:06.310 --> 00:00:09.150\nKun Drivetrain-laite on valittu\n\n4\n00:00:09.150 --> 00:00:12.633\nAjoblokit ilmestyvät Ajopeli-valinnan alle työkaluissa.\n\n5\n00:00:14.000 --> 00:00:15.410\nKäytä Ajopeliä\n\n6\n00:00:15.410 --> 00:00:19.150\nvalitsemalla Aja eteenpäin -blokki työkaluista.\n\n7\n00:00:19.150 --> 00:00:22.033\nSiirrä se Kun käynnissä -aloitusblokin alle pinoon.\n\n8\n00:00:23.400 --> 00:00:26.333\nValise matka, jonka robotti liiikkuu.\n\n9\n00:00:28.030 --> 00:00:31.800\nMatkan yksikkö voi olla Tuuma tai MM\n\n10\n00:00:31.800 --> 00:00:33.593\nsisältäen desimaalitarkkuuden.\n\n11\n00:00:34.700 --> 00:00:37.070\nOletuksena Ajopeli\n\n12\n00:00:37.070 --> 00:00:39.030\nliikkuu eteenpäin.\n\n13\n00:00:39.030 --> 00:00:41.170\nJos haluat liikkua taaksepäin\n\n14\n00:00:41.170 --> 00:00:43.600\nmuuta eteenpäin -valinta taaksepäin -valinnaksi\n\n15\n00:00:43.600 --> 00:00:44.893\nalasvetolistalta.\n\n16\n00:00:45.880 --> 00:00:49.420\nVoit yhdistellä aja- ja käänny -blokkeja ohjelmassa,\n\n17\n00:00:49.420 --> 00:00:52.763\njoilla voit nopeasti ja automaattina liikuttaa robottia.\n\n","fr":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Utiliser la transmission dans VEXcode V5 Blocs</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nfacilite la conduite de votre robot.\n\n3\n00:00:06.310 --> 00:00:09.150\nUne fois que vous avez ajouté la transmission,\n\n4\n00:00:09.150 --> 00:00:12.633\nune nouvelle catégorie de blocs\nnommée \"Transmission\" apparaitra.\n\n5\n00:00:14.000 --> 00:00:15.410\nPour utiliser la transmission,\n\n6\n00:00:15.410 --> 00:00:19.150\nsélectionnez le bloc \"Avancer\" de la boîte à outils.\n\n7\n00:00:19.150 --> 00:00:22.033\nPuis connectez-le au bloc \"Au démarrage\".\n\n8\n00:00:23.400 --> 00:00:26.333\nChoisissez la distance que vous voulez faire parcourir à la transmission.\n\n9\n00:00:28.030 --> 00:00:31.800\nLa distance peut être saisie en pouces ou en millimètres,\n\n10\n00:00:31.800 --> 00:00:33.593\ny compris en nombres décimaux.\n\n11\n00:00:34.700 --> 00:00:37.070\nPar défaut, le drivetrain se déplacera\n\n12\n00:00:37.070 --> 00:00:39.030\nvers l'avant.\n\n13\n00:00:39.030 --> 00:00:41.170\nPour faire reculer la transmission,\n\n14\n00:00:41.170 --> 00:00:43.600\npasser de \"En avant\" à \"En arrière\"\n\n15\n00:00:43.600 --> 00:00:44.893\ndans le menu déroulant.\n\n16\n00:00:45.880 --> 00:00:49.420\nVous pouvez combiner les commandes de conduite et de rotation ensemble\n\n17\n00:00:49.420 --> 00:00:52.763\npour être en mesure de piloter rapidement et de façon autonome votre robot.\n\n","ko":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>VEXcode V5 Blocks에서 드라이브트레인을 사용하면</v>\n\n2\n00:00:03.550 --> 00:00:06.310\n로봇을 쉽게 드라이브 시킬 수 있습니다.\n\n3\n00:00:06.310 --> 00:00:09.150\n드라이브트레인 기기를 추가하면\n\n4\n00:00:09.150 --> 00:00:12.633\n드라이브트레인이라는 새 블록 카테고리가 나타납니다.\n\n5\n00:00:14.000 --> 00:00:15.410\n드라이브트레인을 사용하려면\n\n6\n00:00:15.410 --> 00:00:19.150\n도구 상자에서 '앞으로 드라이브' 블록을 선택합니다.\n\n7\n00:00:19.150 --> 00:00:22.033\n그리고 '시작하기' 블록에 연결합니다.\n\n8\n00:00:23.400 --> 00:00:26.333\n드라이브트레인이 이동할 거리를 선택하세요.\n\n9\n00:00:28.030 --> 00:00:31.800\n거리는 인치 (inch) 또는 밀리미터 (mm) 단위로 입력할 수 있고\n\n10\n00:00:31.800 --> 00:00:33.593\n소수점 이하 숫자를 포함해도 됩니다.\n\n11\n00:00:34.700 --> 00:00:37.070\n드라이브트레인의 기본값은\n\n12\n00:00:37.070 --> 00:00:39.030\n앞으로 이동입니다.\n\n13\n00:00:39.030 --> 00:00:41.170\n드라이브트레인을 반대 방향으로 이동하려면\n\n14\n00:00:41.170 --> 00:00:43.600\n드롭다운 메뉴에서\n\n15\n00:00:43.600 --> 00:00:44.893\n\"앞으로\"를 \"반대로\"로 변경합니다.\n\n16\n00:00:45.880 --> 00:00:49.420\n\"드라이브\"와 \"돌기\" 명령을 결합하여\n\n17\n00:00:49.420 --> 00:00:52.763\n로봇을 빠르고 자율적으로 운전할 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Lengva valdyti savo robotą,</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nprogramoje \"VEXcode V5 Blocks\" naudojant pavaros mechanizmą.\n\n3\n00:00:06.310 --> 00:00:09.150\nPridėję pavaros mechanizmo prietaisą,\n\n4\n00:00:09.150 --> 00:00:12.633\natsiras nauja blokų pavadintų \"Pavaros mechanizmas\" kategorija.\n\n5\n00:00:14.000 --> 00:00:15.410\nNorėdami naudoti pavaros mechanizmą,\n\n6\n00:00:15.410 --> 00:00:19.150\nparankinėje pasirinkite \"važiuoti į priekį\" bloką.\n\n7\n00:00:19.150 --> 00:00:22.033\nPo to, prijunkite jį prie \"kada pradėti\" bloko.\n\n8\n00:00:23.400 --> 00:00:26.333\nPasirinkite norimą nuvažiuoti pavaros mechanizmo atstumą.\n\n9\n00:00:28.030 --> 00:00:31.800\nAtstumą galite įvesti coliais arba milimetrais,\n\n10\n00:00:31.800 --> 00:00:33.593\nįskaitant, dešimtainius skaičius.\n\n11\n00:00:34.700 --> 00:00:37.070\nPagal nutylėjimą, pavaros mechanizmas\n\n12\n00:00:37.070 --> 00:00:39.030\njudės į priekį.\n\n13\n00:00:39.030 --> 00:00:41.170\nNorėdami, kad pavaros mechanizmas judėtų atbulai,\n\n14\n00:00:41.170 --> 00:00:43.600\nišplėstiniame meniu\n\n15\n00:00:43.600 --> 00:00:44.893\npakeiskite \"važiuoti į priekį\" į \"važiuoti atbulai\".\n\n16\n00:00:45.880 --> 00:00:49.420\nGalite sujungti važiavimo ir posūkio komandas,\n\n17\n00:00:49.420 --> 00:00:52.763\nkad greitai ir autonomiškai valdytumėte savo robotą.\n\n","lv":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Piedziņas sistēmas izmantošana VEXcode V5 Blocks</v>\n\n2\n00:00:03.550 --> 00:00:06.310\npadarīs robota vadīšanu vienkāršāku.\n\n3\n00:00:06.310 --> 00:00:09.150\nKad esiet piedziņas sistēmu pievienojis,\n\n4\n00:00:09.150 --> 00:00:12.633\nparādīsies jauna bloku kategorija ar nosaukumu “Drivetrain” (piedziņas sistēma).\n\n5\n00:00:14.000 --> 00:00:15.410\nPiedziņas sistēmas lietošanai,\n\n6\n00:00:15.410 --> 00:00:19.150\natlasiet rīklodziņā bloku “Drive forward” (virzīties uz priekšu).\n\n7\n00:00:19.150 --> 00:00:22.033\nPēc tam pievienojiet to pie bloka “When Started”.\n\n8\n00:00:23.400 --> 00:00:26.333\nIzvēlieties attālumu, kādu vēlaties, lai veic piedziņas sistēma.\n\n9\n00:00:28.030 --> 00:00:31.800\nAttālumu var ievadīt collās vai milimetros,\n\n10\n00:00:31.800 --> 00:00:33.593\nieskaitot decimālskaitļus.\n\n11\n00:00:34.700 --> 00:00:37.070\nPēc noklusējuma piedziņas sistēma virzīsies\n\n12\n00:00:37.070 --> 00:00:39.030\nvirzienā uz priekšu.\n\n13\n00:00:39.030 --> 00:00:41.170\nLai piedziņas sistēma virzītos atpakaļgaitā,\n\n14\n00:00:41.170 --> 00:00:43.600\nmainiet “forward” uz “reverse”\n\n15\n00:00:43.600 --> 00:00:44.893\nnolaižamajā izvēlnē.\n\n16\n00:00:45.880 --> 00:00:49.420\nKombinējiet vadīšanas un pagriešanas komandas,\n\n17\n00:00:49.420 --> 00:00:52.763\nlai ātri un autonomi vadītu savu robotu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor> Het gebruik van de aandrijflijn in VEXcode V5 Blokken </v>\n\n2\n00:00:03.550 --> 00:00:06.310\nmaakt het besturen van uw robot eenvoudig.\n\n3\n00:00:06.310 --> 00:00:09.150\nZodra u het aandrijflijn apparaat hebt toegevoegd,\n\n4\n00:00:09.150 --> 00:00:12.633\nverschijnt er een nieuwe categorie blokken met de naam Aandrijflijn.\n\n5\n00:00:14.000 --> 00:00:15.410\nOm de aandrijflijn te gebruiken\n\n6\n00:00:15.410 --> 00:00:19.150\nselecteer het rij voorwaarts blok uit de werkbalk.\n\n7\n00:00:19.150 --> 00:00:22.033\nEn sluit deze vervolgens aan op het wanneer gestart blok.\n\n8\n00:00:23.400 --> 00:00:26.333\nKies de afstand die u wilt dat de aandrijflijn gaat rijden.\n\n9\n00:00:28.030 --> 00:00:31.800\nDe afstand kan worden ingevoerd in inches of millimeters,\n\n10\n00:00:31.800 --> 00:00:33.593\ninclusief decimale getallen.\n\n11\n00:00:34.700 --> 00:00:37.070\nStandaard zal de aandrijflijn\n\n12\n00:00:37.070 --> 00:00:39.030\nvoorwaarts bewegen.\n\n13\n00:00:39.030 --> 00:00:41.170\nOm de aandrijflijn achterwaarts te laten bewegen,\n\n14\n00:00:41.170 --> 00:00:43.600\nverander voorwaarts naar achterwaarts\n\n15\n00:00:43.600 --> 00:00:44.893\nin het keuzelijst menu.\n\n16\n00:00:45.880 --> 00:00:49.420\nU kunt de rij- en draai-opdrachten combineren\n\n17\n00:00:49.420 --> 00:00:52.763\nom uw robot snel en autonoom te kunnen besturen.\n\n","pl":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Korzystanie z napędu w projekcie bloków V5</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nsprawia, że jazda twoim robotem jest prosta.\n\n3\n00:00:06.310 --> 00:00:09.150\nPo dodaniu napędu\n\n4\n00:00:09.150 --> 00:00:12.633\npojawi się nowa kategoria bloków\no nazwie Napęd.\n\n5\n00:00:14.000 --> 00:00:15.410\nAby użyć napędu,\n\n6\n00:00:15.410 --> 00:00:19.150\nwybierz blok \"jedź prosto\"\nz przybornika.\n\n7\n00:00:19.150 --> 00:00:22.033\nNastępnie połącz go z\nblokiem \"po uruchomieniu\".\n\n8\n00:00:23.400 --> 00:00:26.333\nWybierz odległość, którą chciałbyś przejechać dzięki napędowi.\n\n9\n00:00:28.030 --> 00:00:31.800\nOdległość może być wprowadzana w calach lub milimetrach,\n\n10\n00:00:31.800 --> 00:00:33.593\nwłączając liczby dziesiętne.\n\n11\n00:00:34.700 --> 00:00:37.070\nDomyślnie układ napędowy będzie poruszał się\n\n12\n00:00:37.070 --> 00:00:39.030\nw kierunku do przodu.\n\n13\n00:00:39.030 --> 00:00:41.170\nAby poruszać napędem wstecz,\n\n14\n00:00:41.170 --> 00:00:43.600\nzmień kierunek \"do przodu\" na \"do tyłu\",\n\n15\n00:00:43.600 --> 00:00:44.893\nw rozwijanym menu bloku.\n\n16\n00:00:45.880 --> 00:00:49.420\nMożesz połączyć jazdę polecenia skręcania razem\n\n17\n00:00:49.420 --> 00:00:52.763\nby szybko i autonomicznie\nnapędzać swojego robota.\n\n","ru":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Использование трансмиссии в VEXcode V5</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nупрощает управление роботом.\n\n3\n00:00:06.310 --> 00:00:09.150\nПосле добавления трансмиссии\n\n4\n00:00:09.150 --> 00:00:12.633\nв инструментарии появится новая категория блоков.\n\n5\n00:00:14.000 --> 00:00:15.410\nЧтобы использовать трансмиссию,\n\n6\n00:00:15.410 --> 00:00:19.150\nвыберите блоки управления из инструментария.\n\n7\n00:00:19.150 --> 00:00:22.033\nДалее, подсоедините его к блоку начала программы.\n\n8\n00:00:23.400 --> 00:00:26.333\nВыберите расстояние, на которое в бы хотели переместить трансмиссию.\n\n9\n00:00:28.030 --> 00:00:31.800\nРасстояние может быть указано в дюймах или миллиметрах,\n\n10\n00:00:31.800 --> 00:00:33.593\nвключая десятичные числа.\n\n11\n00:00:34.700 --> 00:00:37.070\nПо умолчанию, трансмиссия движется вперёд\n\n12\n00:00:37.070 --> 00:00:39.030\nвперёд.\n\n13\n00:00:39.030 --> 00:00:41.170\nДля движения в обратном направлении\n\n14\n00:00:41.170 --> 00:00:43.600\nизмените направление на противоположное\n\n15\n00:00:43.600 --> 00:00:44.893\nв раскрывающемся списке.\n\n16\n00:00:45.880 --> 00:00:49.420\nВы можете комбинировать блоки поворота и движения вместе\n\n17\n00:00:49.420 --> 00:00:52.763\nдля быстрого и автономного движения робота в указанные точки.\n\n","th":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor> การใช้ระบบขับเคลื่อน drivetrain ใน VEXcode V5 Blocks นั้น </v>\n\n2\n00:00:03.550 --> 00:00:06.310\nทำให้การขับเคลื่อนหุ่นยนต์ของคุณเป็นเรื่องง่าย\n\n3\n00:00:06.310 --> 00:00:09.150\nเมื่อคุณเพิ่มอุปกรณ์ระบบขับเคลื่อนแล้ว\n\n4\n00:00:09.150 --> 00:00:12.633\nจะมีหมวดหมู่ใหม่ของบล็อกชื่อ Drivetrain ปรากฏขึ้น\n\n5\n00:00:14.000 --> 00:00:15.410\nในการใช้ระบบขับเคลื่อน drivetrain\n\n6\n00:00:15.410 --> 00:00:19.150\nเลือกบล็อก ขับไปข้างหน้าบล็อก จากกล่องเครื่องมือ\n\n7\n00:00:19.150 --> 00:00:22.033\nจากนั้นเชื่อมต่อกับ when started บล็อก\n\n8\n00:00:23.400 --> 00:00:26.333\nเลือกระยะทางที่คุณต้องการให้ระบบขับเคลื่อนเดินทาง\n\n9\n00:00:28.030 --> 00:00:31.800\nสามารถป้อนระยะทางเป็นนิ้วหรือมิลลิเมตร\n\n10\n00:00:31.800 --> 00:00:33.593\nรวมทั้งตัวเลขทศนิยมก็ได้\n\n11\n00:00:34.700 --> 00:00:37.070\nโดยค่าเริ่มต้นระบบขับเคลื่อนจะเคลื่อนที่\n\n12\n00:00:37.070 --> 00:00:39.030\nในทิศทางไปข้างหน้า\n\n13\n00:00:39.030 --> 00:00:41.170\nหากต้องการให้ขับเคลื่อนถอยหลัง\n\n14\n00:00:41.170 --> 00:00:43.600\nเปลี่ยนจาก เดินหน้า เป็น ถอยหลัง\n\n15\n00:00:43.600 --> 00:00:44.893\nในเมนู dropdown\n\n16\n00:00:45.880 --> 00:00:49.420\nคุณสามารถรวมคำสั่งขับเคลื่อนและคำสั่งเลี้ยวเข้าด้วยกัน\n\n17\n00:00:49.420 --> 00:00:52.763\nเพื่อให้สามารถขับเคลื่อนหุ่นยนต์ของคุณได้อย่างรวดเร็วและเป็นอิสระ\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Використання трансмісії у VEXcode V5 Blocks</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nзробить керування роботом простішим.\n\n3\n00:00:06.310 --> 00:00:09.150\nЩойно ви додасте пристрій із трансмісією,\n\n4\n00:00:09.150 --> 00:00:12.633\nз'явиться нова категорія блоків \"Трансмісія\".\n\n5\n00:00:14.000 --> 00:00:15.410\nДля використання трансмісії\n\n6\n00:00:15.410 --> 00:00:19.150\nвиберіть блок руху вперед із набору блоків.\n\n7\n00:00:19.150 --> 00:00:22.033\nПотім приєднайте його до блока \"коли почнемо\".\n\n8\n00:00:23.400 --> 00:00:26.333\nОберіть відстань, яку ви хочете проїхати трансмісією.\n\n9\n00:00:28.030 --> 00:00:31.800\nВідстань можна задати у футах або міліметрах,\n\n10\n00:00:31.800 --> 00:00:33.593\nзокрема й десятковими числами.\n\n11\n00:00:34.700 --> 00:00:37.070\nЗа замовчуванням, трансмісія поїде\n\n12\n00:00:37.070 --> 00:00:39.030\nу передньому напрямку.\n\n13\n00:00:39.030 --> 00:00:41.170\nДля руху у зворотному напрямку\n\n14\n00:00:41.170 --> 00:00:43.600\nзмініть \"прямий\" на \"зворотний\"\n\n15\n00:00:43.600 --> 00:00:44.893\nу спадному меню.\n\n16\n00:00:45.880 --> 00:00:49.420\nОб'єднуйте команди прямих рухів і поворотів\n\n17\n00:00:49.420 --> 00:00:52.763\nдля швидкого і автономного руху робота.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>Sử dụng hệ thống truyền lực trong VEXcode V5 Blocks</v>\n\n2\n00:00:03.550 --> 00:00:06.310\nlàm cho việc điều khiển rô-bốt của bạn trở nên đơn giản.\n\n3\n00:00:06.310 --> 00:00:09.150\nSau khi bạn đã thêm thiết bị hệ thống truyền lực,\n\n4\n00:00:09.150 --> 00:00:12.633\nmột danh mục khối mới, có tên là Hệ thống truyền lực, sẽ xuất hiện.\n\n5\n00:00:14.000 --> 00:00:15.410\nĐể sử dụng hệ thống truyền lực,\n\n6\n00:00:15.410 --> 00:00:19.150\nchọn, lái xe về phía trước, chặn từ hộp công cụ.\n\n7\n00:00:19.150 --> 00:00:22.033\nSau đó, kết nối nó với khối, khi bắt đầu.\n\n8\n00:00:23.400 --> 00:00:26.333\nChọn khoảng cách bạn muốn hệ thống truyền lực di chuyển.\n\n9\n00:00:28.030 --> 00:00:31.800\nKhoảng cách có thể được nhập bằng inch hoặc milimét,\n\n10\n00:00:31.800 --> 00:00:33.593\nkể cả số thập phân.\n\n11\n00:00:34.700 --> 00:00:37.070\nTheo mặc định, hệ thống truyền lực sẽ di chuyển\n\n12\n00:00:37.070 --> 00:00:39.030\ntheo chiều thuận.\n\n13\n00:00:39.030 --> 00:00:41.170\nĐể chuyển hệ thống truyền lực ngược lại,\n\n14\n00:00:41.170 --> 00:00:43.600\nthay đổi, chuyển tiếp, tới, đảo ngược,\n\n15\n00:00:43.600 --> 00:00:44.893\ntrong menu thả xuống.\n\n16\n00:00:45.880 --> 00:00:49.420\nBạn có thể kết hợp ổ đĩa và chuyển lệnh với nhau\n\n17\n00:00:49.420 --> 00:00:52.763\nđể có thể điều khiển rô bốt của bạn một cách nhanh chóng và tự động.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\ncrwdns96046:0crwdne96046:0\n\n2\n00:00:03.550 --> 00:00:06.310\ncrwdns96048:0crwdne96048:0\n\n3\n00:00:06.310 --> 00:00:09.150\ncrwdns96050:0crwdne96050:0\n\n4\n00:00:09.150 --> 00:00:12.633\ncrwdns96052:0crwdne96052:0\n\n5\n00:00:14.000 --> 00:00:15.410\ncrwdns96054:0crwdne96054:0\n\n6\n00:00:15.410 --> 00:00:19.150\ncrwdns96056:0crwdne96056:0\n\n7\n00:00:19.150 --> 00:00:22.033\ncrwdns96058:0crwdne96058:0\n\n8\n00:00:23.400 --> 00:00:26.333\ncrwdns96060:0crwdne96060:0\n\n9\n00:00:28.030 --> 00:00:31.800\ncrwdns96062:0crwdne96062:0\n\n10\n00:00:31.800 --> 00:00:33.593\ncrwdns96064:0crwdne96064:0\n\n11\n00:00:34.700 --> 00:00:37.070\ncrwdns96066:0crwdne96066:0\n\n12\n00:00:37.070 --> 00:00:39.030\ncrwdns96068:0crwdne96068:0\n\n13\n00:00:39.030 --> 00:00:41.170\ncrwdns96070:0crwdne96070:0\n\n14\n00:00:41.170 --> 00:00:43.600\ncrwdns96072:0crwdne96072:0\n\n15\n00:00:43.600 --> 00:00:44.893\ncrwdns96074:0crwdne96074:0\n\n16\n00:00:45.880 --> 00:00:49.420\ncrwdns96076:0crwdne96076:0\n\n17\n00:00:49.420 --> 00:00:52.763\ncrwdns96078:0crwdne96078:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.280 --> 00:00:03.550\n<v Instructor>在VEXcode V5 Blocks使用底盘</v>\n\n2\n00:00:03.550 --> 00:00:06.310\n让您驱动机器人变得简单。\n\n3\n00:00:06.310 --> 00:00:09.150\n一旦您已经添加底盘后，\n\n4\n00:00:09.150 --> 00:00:12.633\n一个叫“底盘”的指令块新类别将会显现。\n\n5\n00:00:14.000 --> 00:00:15.410\n欲使用底盘，\n\n6\n00:00:15.410 --> 00:00:19.150\n从工具栏选择“驱动-正”指令块。\n\n7\n00:00:19.150 --> 00:00:22.033\n然后将它连接到“当开始”指令块。\n\n8\n00:00:23.400 --> 00:00:26.333\n选中您希望底盘行驶的距离。\n\n9\n00:00:28.030 --> 00:00:31.800\n距离单位可以为英寸或毫米，\n\n10\n00:00:31.800 --> 00:00:33.593\n可以有小数。\n\n11\n00:00:34.700 --> 00:00:37.070\n默认情况下，底盘将\n\n12\n00:00:37.070 --> 00:00:39.030\n正向移动。\n\n13\n00:00:39.030 --> 00:00:41.170\n欲使底盘反向运动，\n\n14\n00:00:41.170 --> 00:00:43.600\n更改“正”为“反”，\n\n15\n00:00:43.600 --> 00:00:44.893\n在下拉菜单中。\n\n16\n00:00:45.880 --> 00:00:49.420\n您可以组合驱动和转向指令块到一起\n\n17\n00:00:49.420 --> 00:00:52.763\n来迅速和自动地驱动您的机器人。\n\n"}},{"thumb":"V5_Tutorial_turning.jpg","mov":"V5_Blocks_DrivetrainTurns_V2","description":"Drivetrain Turns","filter":"","placeholder":false,"vimeo":"475899542","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Using the drivetrain in a V5 blocks project</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nmakes turning your robot simple.\n\n3\n00:00:05.320 --> 00:00:07.960\nOnce you have the drivetrain device added,\n\n4\n00:00:07.960 --> 00:00:11.033\na new category of blocks named drivetrain will appear.\n\n5\n00:00:12.120 --> 00:00:16.130\nTo use the drivetrain, select the turn for block\n\n6\n00:00:16.130 --> 00:00:21.130\nfrom the toolbox, then connect it to the when started block.\n\n7\n00:00:21.380 --> 00:00:23.290\nChoose the number of degrees you would like\n\n8\n00:00:23.290 --> 00:00:24.863\nthe drivetrain to turn.\n\n9\n00:00:25.760 --> 00:00:28.870\nThe drivetrain turn is measured in degrees.\n\n10\n00:00:28.870 --> 00:00:32.350\nBy default, the drivetrain will turn to the right.\n\n11\n00:00:32.350 --> 00:00:34.370\nTo turn the drivetrain to the left,\n\n12\n00:00:34.370 --> 00:00:38.370\nchange right to left in the dropdown menu.\n\n13\n00:00:38.370 --> 00:00:41.390\nYou can combine the drive and turn commands together\n\n14\n00:00:41.390 --> 00:00:44.563\nto be able to quick and autonomously drive your robot.\n\n","ar":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>استخدام نظام الدفع في V5 مشروع مقاطع </v>\n\n2\n00:00:02.970 --> 00:00:05.320\nيجعل قيادة الروبوت بسيطة.\n\n3\n00:00:05.320 --> 00:00:07.960\nبمجرد إضافة نظام الدفع\n\n4\n00:00:07.960 --> 00:00:11.033\nستظهر فئة جديدة من المقاطع المسماة نظام الدفع.\n\n5\n00:00:12.120 --> 00:00:16.130\nلاستخدام نظام الدفع ، حدد الدوران للمقطع\n\n6\n00:00:16.130 --> 00:00:21.130\nمن قائمة الأدوات، ثم قم بتوصيله إلى مقطع \"عند البدء\".\n\n7\n00:00:21.380 --> 00:00:23.290\nاختر عدد الدرجات التي تريدها\n\n8\n00:00:23.290 --> 00:00:24.863\nلنظام الدفع للانعطاف.\n\n9\n00:00:25.760 --> 00:00:28.870\nويقاس دوران نظام الدفع إلى درجات.\n\n10\n00:00:28.870 --> 00:00:32.350\nبشكل افتراضي، سيتحول نظام الدفع إلى اليمين.\n\n11\n00:00:32.350 --> 00:00:34.370\nلتحويل نظام الدفع إلى اليسار،\n\n12\n00:00:34.370 --> 00:00:38.370\nقم بتغيير اليمين إلى اليسار في القائمة المنسدلة.\n\n13\n00:00:38.370 --> 00:00:41.390\nيمكنك الجمع بين أوامر القيادة والإستدار\n\n14\n00:00:41.390 --> 00:00:44.563\nلكي تكون قادراً على قيادة الروبوت الخاص بك بسرعة وبطريقة تلقائية.\n\n","cs":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Používání podvozku ve V5 blokovém projektu</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nusnadňuje zatáčení tvého robota.\n\n3\n00:00:05.320 --> 00:00:07.960\nJakmile je zařízení Podvozek přidáno,\n\n4\n00:00:07.960 --> 00:00:11.033\nobjeví se nová kategorie bloků s názvem Podvozek.\n\n5\n00:00:12.120 --> 00:00:16.130\nPro použití podvozku vyber blok Otoč se o\n\n6\n00:00:16.130 --> 00:00:21.130\nna panelu nástrojů, potom ho připoj k bloku Při spuštění.\n\n7\n00:00:21.380 --> 00:00:23.290\nVyber počet stupňů, o které chceš,\n\n8\n00:00:23.290 --> 00:00:24.863\naby se tvůj podvozek otočil.\n\n9\n00:00:25.760 --> 00:00:28.870\nOtáčení podvozku je měřeno ve stupních.\n\n10\n00:00:28.870 --> 00:00:32.350\nVe výchozím nastavení se bude podvozek otáčet doprava.\n\n11\n00:00:32.350 --> 00:00:34.370\nPro otáčení podvozku doleva,\n\n12\n00:00:34.370 --> 00:00:38.370\nzměň v rozbalovacím menu doprava na doleva.\n\n13\n00:00:38.370 --> 00:00:41.390\nMůžeš kombinovat příkazy pro jízdu a zatáčení\n\n14\n00:00:41.390 --> 00:00:44.563\npro schopnost rychle a samostatně řídit tvého robota.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Usando el Tren Motriz en un proyecto de V5 Blocks (bloques)</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nhace que girar su robot sea simple.\n\n3\n00:00:05.320 --> 00:00:07.960\nUna vez que se ha añadido el dispositivo de Tren Motriz,\n\n4\n00:00:07.960 --> 00:00:11.033\naparecerá una nueva categoría de bloques\nllamado Tren Motriz.\n\n5\n00:00:12.120 --> 00:00:16.130\nPara usar el Chasis, selecciona el bloque \"Dar Vuelta Por\"\n\n6\n00:00:16.130 --> 00:00:21.130\nde la caja de herramientas, luego conéctelo al bloque Cuando Empieza.\n\n7\n00:00:21.380 --> 00:00:23.290\nElija el número de grados que desea\n\n8\n00:00:23.290 --> 00:00:24.863\nque gire el tren motriz.\n\n9\n00:00:25.760 --> 00:00:28.870\nEl gyro del Tren Motriz se mide en grados.\n\n10\n00:00:28.870 --> 00:00:32.350\nPor defecto, el Tren Motriz dara vuelta a la derecha.\n\n11\n00:00:32.350 --> 00:00:34.370\nPara girar el Tren Motriz a la izquierda,\n\n12\n00:00:34.370 --> 00:00:38.370\ncambie \"Derecha\" a \"Izquierda\" en el menú desplegable.\n\n13\n00:00:38.370 --> 00:00:41.390\nPuede combinar los comandos de Conducir y Dar vuelta\n\n14\n00:00:41.390 --> 00:00:44.563\npara poder manejar de forma rápida y\nautónoma su robot.\n\n","es":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Usando el Tren Motriz en un proyecto de V5 Blocks (bloques)</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nhace que girar su robot sea simple.\n\n3\n00:00:05.320 --> 00:00:07.960\nUna vez que se ha añadido el dispositivo de Tren Motriz,\n\n4\n00:00:07.960 --> 00:00:11.033\naparecerá una nueva categoría de bloques\nllamado Tren Motriz.\n\n5\n00:00:12.120 --> 00:00:16.130\nPara usar el Chasis, selecciona el bloque \"Dar Vuelta Por\"\n\n6\n00:00:16.130 --> 00:00:21.130\nde la caja de herramientas, luego conéctelo al bloque Cuando Empieza.\n\n7\n00:00:21.380 --> 00:00:23.290\nElija el número de grados que desea\n\n8\n00:00:23.290 --> 00:00:24.863\nque gire el tren motriz.\n\n9\n00:00:25.760 --> 00:00:28.870\nEl gyro del Tren Motriz se mide en grados.\n\n10\n00:00:28.870 --> 00:00:32.350\nPor defecto, el Tren Motriz dara vuelta a la derecha.\n\n11\n00:00:32.350 --> 00:00:34.370\nPara girar el Tren Motriz a la izquierda,\n\n12\n00:00:34.370 --> 00:00:38.370\ncambie \"Derecha\" a \"Izquierda\" en el menú desplegable.\n\n13\n00:00:38.370 --> 00:00:41.390\nPuede combinar los comandos de Conducir y Dar vuelta\n\n14\n00:00:41.390 --> 00:00:44.563\npara poder manejar de forma rápida y\nautónoma su robot.\n\n","fi":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Kun käytät Ajopeli-määritystä V5 blokkiohjelmassa</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nse tekee robotin liikkeenhallinnan helpoksi.\n\n3\n00:00:05.320 --> 00:00:07.960\nKun Drivetrain-laite on valittu\n\n4\n00:00:07.960 --> 00:00:11.033\nAjopelin komennot tulevat Ajopeli-kuvakkeen alle työkaluihin.\n\n5\n00:00:12.120 --> 00:00:16.130\nValitse Käänny määrän -blokki\n\n6\n00:00:16.130 --> 00:00:21.130\nja vedä se työkauluista ohjelmaikkunaan Kun käynnissä-blokin alle pinoon.\n\n7\n00:00:21.380 --> 00:00:23.290\nValitse astemäärä, jonka haluat\n\n8\n00:00:23.290 --> 00:00:24.863\nAjopelin kääntyvän.\n\n9\n00:00:25.760 --> 00:00:28.870\nAjopelin kääntyminen mitataan asteina.\n\n10\n00:00:28.870 --> 00:00:32.350\nOletuksena Ajopeli kääntyy oikealle.\n\n11\n00:00:32.350 --> 00:00:34.370\nJos haluat kääntyä Ajopelillä vasemmalle\n\n12\n00:00:34.370 --> 00:00:38.370\nvaihda arvo Oikea arvoon Vasen.\n\n13\n00:00:38.370 --> 00:00:41.390\nVoit yhdistellä ajo- ja käänny -blokkeja ohjelmassa\n\n14\n00:00:41.390 --> 00:00:44.563\nja saada robottisi ajamaan nopeasti automaattina.\n\n","fr":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Utiliser la transmission dans un projet V5 Blocs</v>\n\n2\n00:00:02.970 --> 00:00:05.320\npermet de faire tourner votre robot simplement.\n\n3\n00:00:05.320 --> 00:00:07.960\nUne fois que vous avez ajouté la transmission,\n\n4\n00:00:07.960 --> 00:00:11.033\nune nouvelle catégorie de blocs\nnommée \"Transmission\" apparaitra.\n\n5\n00:00:12.120 --> 00:00:16.130\nPour utiliser la transmission, sélectionnez le bloc \"Tourner de\"\n\n6\n00:00:16.130 --> 00:00:21.130\nde la Boîte à outils, puis connectez-le au bloc \"Au démarrage\".\n\n7\n00:00:21.380 --> 00:00:23.290\nChoisissez le nombre de degrés souhaités\n\n8\n00:00:23.290 --> 00:00:24.863\npour la rotation de la transmission.\n\n9\n00:00:25.760 --> 00:00:28.870\nLa rotation de la transmission se mesure en degrés.\n\n10\n00:00:28.870 --> 00:00:32.350\nPar défaut, la transmission\ntournera à droite.\n\n11\n00:00:32.350 --> 00:00:34.370\nPour faire tourner la transmission vers la gauche,\n\n12\n00:00:34.370 --> 00:00:38.370\npasser de \"Droite\" à \"Gauche\" dans le menu déroulant.\n\n13\n00:00:38.370 --> 00:00:41.390\nVous pouvez combiner les commandes de conduite et de rotation ensemble\n\n14\n00:00:41.390 --> 00:00:44.563\npour être en mesure de piloter rapidement et de façon autonome votre robot.\n\n","ko":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>V5 블록 프로젝트에서 드라이브트레인을 사용하면</v>\n\n2\n00:00:02.970 --> 00:00:05.320\n로봇을 쉽게 회전시킬 수 있습니다.\n\n3\n00:00:05.320 --> 00:00:07.960\n드라이브트레인 기기를 추가하면\n\n4\n00:00:07.960 --> 00:00:11.033\n드라이브트레인이라는 새 블록 카테고리가 나타납니다.\n\n5\n00:00:12.120 --> 00:00:16.130\n드라이브트레인을 사용하려면 도구 상자에서 '돌기' 블록을 선택하고\n\n6\n00:00:16.130 --> 00:00:21.130\n'시작하기' 블록에 연결합니다.\n\n7\n00:00:21.380 --> 00:00:23.290\n드라이브트레인이\n\n8\n00:00:23.290 --> 00:00:24.863\n회전할 각도를 선택하세요.\n\n9\n00:00:25.760 --> 00:00:28.870\n드라이브트레인의 도는 각도는 도 단위로 측정됩니다.\n\n10\n00:00:28.870 --> 00:00:32.350\n기본적으로 드라이브트레인은 오른쪽으로 돕니다.\n\n11\n00:00:32.350 --> 00:00:34.370\n드라이브트레인이 왼쪽으로 돌게 하려면\n\n12\n00:00:34.370 --> 00:00:38.370\n드롭다운 메뉴에서 \"오른쪽\"을 \"왼쪽\"으로 변경합니다.\n\n13\n00:00:38.370 --> 00:00:41.390\n\"드라이브\"와 \"돌기\" 명령어를 결합하여\n\n14\n00:00:41.390 --> 00:00:44.563\n빠르고 자율적으로 로봇을 드라이브시킬 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Lengva pasukti savo robotą,</v>\n\n2\n00:00:02.970 --> 00:00:05.320\n\"V5\" blokų projekte naudojant pavaros mechanizmą.\n\n3\n00:00:05.320 --> 00:00:07.960\nPridėję pavaros mechanizmo prietaisą,\n\n4\n00:00:07.960 --> 00:00:11.033\natsiras nauja blokų pavadintų \"Pavaros mechanizmas\" kategorija.\n\n5\n00:00:12.120 --> 00:00:16.130\nNorėdami naudoti pavaros mechanizmą, parankinėje pasirinkite \"pasukti kiek\"\n\n6\n00:00:16.130 --> 00:00:21.130\nbloką ir sujunkite su \"kada pradėti\" bloku.\n\n7\n00:00:21.380 --> 00:00:23.290\nPasirinkite kiek laipsnių norite,\n\n8\n00:00:23.290 --> 00:00:24.863\nkad pavaros mechanizmas pasuktų.\n\n9\n00:00:25.760 --> 00:00:28.870\nPavaros mechanizmo posūkiai matuojami laipsniais.\n\n10\n00:00:28.870 --> 00:00:32.350\nPagal nutylėjimą, pavaros mechanizmas pasuks į dešinę.\n\n11\n00:00:32.350 --> 00:00:34.370\nNorėdami pavaros mechanizmą pasukti į kairę,\n\n12\n00:00:34.370 --> 00:00:38.370\nišplėstiniame meniu pakeiskite \"dešinė\" į \"kairė\".\n\n13\n00:00:38.370 --> 00:00:41.390\nGalite sujungti važiavimo ir posūkio komandas,\n\n14\n00:00:41.390 --> 00:00:44.563\nkad greitai ir autonomiškai valdytumėte savo robotą.\n\n","lv":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Piedziņas sistēmas lietošana V5 bloku projektā/v>\n\n2\n00:00:02.970 --> 00:00:05.320\npadarīs robota pagriešanu vienkāršāku.\n\n3\n00:00:05.320 --> 00:00:07.960\nKad esiet piedziņas sistēmu pievienojis,\n\n4\n00:00:07.960 --> 00:00:11.033\nparādīsies jauna bloku kategorija ar nosaukumu “Drivetrain”.\n\n5\n00:00:12.120 --> 00:00:16.130\nLai izmantotu piedziņas sistēmu, atlasiet bloku “Turn for”\n\n6\n00:00:16.130 --> 00:00:21.130\nrīklodziņā, pēc tam pievienojiet to pie bloka “When Started”.\n\n7\n00:00:21.380 --> 00:00:23.290\nIzvēlieties vēlamo grādu skaitu, kādā vēlaties,\n\n8\n00:00:23.290 --> 00:00:24.863\nlai piedziņa veiktu pagriezienu.\n\n9\n00:00:25.760 --> 00:00:28.870\nPiedziņas sistēmas pagriezieni tiek mērīti grādos.\n\n10\n00:00:28.870 --> 00:00:32.350\nPēc noklusējuma piedziņas sistēma veic pagriezienu pa labi.\n\n11\n00:00:32.350 --> 00:00:34.370\nLai pagrieztu piedziņas sistēmu pa kreisi,\n\n12\n00:00:34.370 --> 00:00:38.370\nnolaižamajā izvēlnē mainiet “Right” uz “Left”.\n\n13\n00:00:38.370 --> 00:00:41.390\nKombinējiet vadīšanas un pagriešanas komandas,\n\n14\n00:00:41.390 --> 00:00:44.563\nlai ātri un autonomi vadītu savu robotu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Gebruik van de aandrijflijn in een V5 blokkenproject</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nmaakt het draaien van uw robot eenvoudig.\n\n3\n00:00:05.320 --> 00:00:07.960\nZodra u het aandrijflijn apparaat hebt toegevoegd,\n\n4\n00:00:07.960 --> 00:00:11.033\nverschijnt er een nieuwe categorie blokken met de naam Aandrijflijn.\n\n5\n00:00:12.120 --> 00:00:16.130\nOm de aandrijflijn te gebruiken, selecteert u draai blok\n\n6\n00:00:16.130 --> 00:00:21.130\nin de werkbalk en sluit u deze vervolgens aan op het blok wanneer gestart.\n\n7\n00:00:21.380 --> 00:00:23.290\nKies het aantal graden dat u\n\n8\n00:00:23.290 --> 00:00:24.863\nde aandrijflijn wilt laten draaien.\n\n9\n00:00:25.760 --> 00:00:28.870\nDe aandrijflijn draai wordt gemeten in graden.\n\n10\n00:00:28.870 --> 00:00:32.350\nStandaard zal de aandrijflijn naar rechts draaien.\n\n11\n00:00:32.350 --> 00:00:34.370\nOm de aandrijflijn naar links te draaien,\n\n12\n00:00:34.370 --> 00:00:38.370\nverandert u rechts naar links in het vervolgkeuzemenu.\n\n13\n00:00:38.370 --> 00:00:41.390\nU kunt de rij- en draai-opdrachten combineren\n\n14\n00:00:41.390 --> 00:00:44.563\nom uw robot snel en autonoom te kunnen besturen.\n\n","pl":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Korzystanie z napędu w projekcie bloków V5</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nsprawia, że jazda twoim robotem jest prosta.\n\n3\n00:00:05.320 --> 00:00:07.960\nPo dodaniu napędu\n\n4\n00:00:07.960 --> 00:00:11.033\npojawi się nowa kategoria bloków\no nazwie Napęd.\n\n5\n00:00:12.120 --> 00:00:16.130\nAby korzystać z napędu,\nzaznacz blok \"Skręć o\"\n\n6\n00:00:16.130 --> 00:00:21.130\nz przybornika i podłącz go do bloku \"po uruchomieniu\".\n\n7\n00:00:21.380 --> 00:00:23.290\nWybierz liczbę stopni, które chcesz\n\n8\n00:00:23.290 --> 00:00:24.863\naby układ napędowy się skręcił.\n\n9\n00:00:25.760 --> 00:00:28.870\nKąt obrotu napędu jest\nmierzony w stopniach.\n\n10\n00:00:28.870 --> 00:00:32.350\nDomyślnie napęd\nskręci w prawo.\n\n11\n00:00:32.350 --> 00:00:34.370\nAby skręcić napęd w lewo,\n\n12\n00:00:34.370 --> 00:00:38.370\nzmień prawo na lewo, w menu rozwijanym.\n\n13\n00:00:38.370 --> 00:00:41.390\nMożesz połączyć jazdę polecenia skręcania razem\n\n14\n00:00:41.390 --> 00:00:44.563\nby szybko i autonomicznie\nnapędzać swojego robota.\n\n","ru":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Использование трансмиссии в блоковом проекте</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nпозволяет упростить управление роботом.\n\n3\n00:00:05.320 --> 00:00:07.960\nПосле добавления трансмиссии\n\n4\n00:00:07.960 --> 00:00:11.033\nпоявится новая категория блоков для трансмиссии.\n\n5\n00:00:12.120 --> 00:00:16.130\nДля использования трансмиссии, выберите блок \"повернуть на\"\n\n6\n00:00:16.130 --> 00:00:21.130\nиз инструментария и присоедините его в блоку начала программы.\n\n7\n00:00:21.380 --> 00:00:23.290\nВыберите количество градусов, на которое\n\n8\n00:00:23.290 --> 00:00:24.863\nдолжна повернуться ваша тележка.\n\n9\n00:00:25.760 --> 00:00:28.870\nПоворот трансмиссии измеряется в градусах.\n\n10\n00:00:28.870 --> 00:00:32.350\nПо умолчанию трансмиссия поворачивает направо.\n\n11\n00:00:32.350 --> 00:00:34.370\nДля поворота трансмиссии налево\n\n12\n00:00:34.370 --> 00:00:38.370\nвыберите \"налево\" из раскрывающегося списка.\n\n13\n00:00:38.370 --> 00:00:41.390\nВы можете комбинировать блоки поворота и движения вместе\n\n14\n00:00:41.390 --> 00:00:44.563\nдля быстрого задания движения робота.\n\n","th":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor> การใช้ระบบขับเคลื่อน drivetrain ใน Vexcode V5 Blocks นั้น </v>\n\n2\n00:00:02.970 --> 00:00:05.320\nทำให้การเลี้ยวหุ่นยนต์ของคุณเป็นเรื่องง่าย\n\n3\n00:00:05.320 --> 00:00:07.960\nเมื่อคุณเพิ่มอุปกรณ์ระบบขับเคลื่อนแล้ว\n\n4\n00:00:07.960 --> 00:00:11.033\nจะมีหมวดหมู่ใหม่ของบล็อกชื่อ Drivetrain ปรากฏขึ้น\n\n5\n00:00:12.120 --> 00:00:16.130\nในการใช้ระบบขับเคลื่อนให้เลือก turn for บล็อก\n\n6\n00:00:16.130 --> 00:00:21.130\nจากกล่องเครื่องมือจากนั้นเชื่อมต่อกับ when started บล็อก\n\n7\n00:00:21.380 --> 00:00:23.290\nจากนั้นเลือกขนาดองศาที่คุณต้องการให้\n\n8\n00:00:23.290 --> 00:00:24.863\nหุ่นยนต์ของคุณหันไป\n\n9\n00:00:25.760 --> 00:00:28.870\nการขับเคลื่อนจำถูกกำหนดเป็นองศา\n\n10\n00:00:28.870 --> 00:00:32.350\nโดยค่าเริ่มต้นจะถูกกำหนดให้เป็นการเลี้ยวขวา\n\n11\n00:00:32.350 --> 00:00:34.370\nหากต้องการให้เลี้ยวไปด้านซ้าย\n\n12\n00:00:34.370 --> 00:00:38.370\nให้เปลี่ยนจาก ขวา เป็น ซ้าย ที่เมนู dropdown\n\n13\n00:00:38.370 --> 00:00:41.390\nคุณสามารถรวมคำสั่งขับเคลื่อนและคำสั่งเลี้ยวเข้าด้วยกัน\n\n14\n00:00:41.390 --> 00:00:44.563\nเพื่อให้สามารถขับเคลื่อนหุ่นยนต์ของคุณได้อย่างรวดเร็วและเป็นอิสระ\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Використання трансмісії у блоковому V5 проєкті</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nзробить керування роботом простішим.\n\n3\n00:00:05.320 --> 00:00:07.960\nЩойно ви додасте пристрій із трансмісією,\n\n4\n00:00:07.960 --> 00:00:11.033\nз'явиться нова категорія блоків \"Трансмісія\".\n\n5\n00:00:12.120 --> 00:00:16.130\nДля використання трансмісії виберіть блок руху\n\n6\n00:00:16.130 --> 00:00:21.130\nз набору блоків, потім приєднайте його до блока \"коли почнемо\".\n\n7\n00:00:21.380 --> 00:00:23.290\nОберіть кількість градусів, на яку ви хочете\n\n8\n00:00:23.290 --> 00:00:24.863\nповернути трансмісію.\n\n9\n00:00:25.760 --> 00:00:28.870\nПоворот трансмісії вимірюється градусами.\n\n10\n00:00:28.870 --> 00:00:32.350\nЗа замовчуванням, трансмісія поверне праворуч.\n\n11\n00:00:32.350 --> 00:00:34.370\nДля повороту ліворуч\n\n12\n00:00:34.370 --> 00:00:38.370\nзмініть \"праворуч\" на \"ліворуч\" у спадному меню.\n\n13\n00:00:38.370 --> 00:00:41.390\nОб'єднуйте команди прямих рухів і поворотів\n\n14\n00:00:41.390 --> 00:00:44.563\nдля швидкого і автономного руху робота.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>Sử dụng hệ thống truyền lực trong dự án khối V5</v>\n\n2\n00:00:02.970 --> 00:00:05.320\nlàm cho việc biến robot của bạn trở nên đơn giản.\n\n3\n00:00:05.320 --> 00:00:07.960\nSau khi bạn đã thêm thiết bị hệ thống truyền lực,\n\n4\n00:00:07.960 --> 00:00:11.033\nmột danh mục khối mới có tên là hệ thống truyền lực sẽ xuất hiện.\n\n5\n00:00:12.120 --> 00:00:16.130\nĐể sử dụng hệ thống truyền lực, hãy chọn ngã rẽ cho khối\n\n6\n00:00:16.130 --> 00:00:21.130\ntừ hộp công cụ, sau đó kết nối nó với khối khi bắt đầu.\n\n7\n00:00:21.380 --> 00:00:23.290\nChọn số độ bạn muốn\n\n8\n00:00:23.290 --> 00:00:24.863\nhệ thống truyền lực để quay.\n\n9\n00:00:25.760 --> 00:00:28.870\nVòng quay của hệ thống truyền lực được đo bằng độ.\n\n10\n00:00:28.870 --> 00:00:32.350\nTheo mặc định, hệ thống truyền lực sẽ rẽ sang phải.\n\n11\n00:00:32.350 --> 00:00:34.370\nĐể rẽ hệ thống truyền lực sang trái,\n\n12\n00:00:34.370 --> 00:00:38.370\nthay đổi từ phải sang trái trong menu thả xuống.\n\n13\n00:00:38.370 --> 00:00:41.390\nBạn có thể kết hợp ổ đĩa và chuyển lệnh với nhau\n\n14\n00:00:41.390 --> 00:00:44.563\nđể có thể điều khiển rô bốt của bạn một cách nhanh chóng và tự động.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\ncrwdns96080:0crwdne96080:0\n\n2\n00:00:02.970 --> 00:00:05.320\ncrwdns96082:0crwdne96082:0\n\n3\n00:00:05.320 --> 00:00:07.960\ncrwdns96084:0crwdne96084:0\n\n4\n00:00:07.960 --> 00:00:11.033\ncrwdns96086:0crwdne96086:0\n\n5\n00:00:12.120 --> 00:00:16.130\ncrwdns96088:0crwdne96088:0\n\n6\n00:00:16.130 --> 00:00:21.130\ncrwdns96090:0crwdne96090:0\n\n7\n00:00:21.380 --> 00:00:23.290\ncrwdns96092:0crwdne96092:0\n\n8\n00:00:23.290 --> 00:00:24.863\ncrwdns96094:0crwdne96094:0\n\n9\n00:00:25.760 --> 00:00:28.870\ncrwdns96096:0crwdne96096:0\n\n10\n00:00:28.870 --> 00:00:32.350\ncrwdns96098:0crwdne96098:0\n\n11\n00:00:32.350 --> 00:00:34.370\ncrwdns96100:0crwdne96100:0\n\n12\n00:00:34.370 --> 00:00:38.370\ncrwdns96102:0crwdne96102:0\n\n13\n00:00:38.370 --> 00:00:41.390\ncrwdns96104:0crwdne96104:0\n\n14\n00:00:41.390 --> 00:00:44.563\ncrwdns96106:0crwdne96106:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.190 --> 00:00:02.970\n<v Instructor>在V5指令块程序中使用底盘</v>\n\n2\n00:00:02.970 --> 00:00:05.320\n让您的机器人转向变得简单。\n\n3\n00:00:05.320 --> 00:00:07.960\n一旦您已经添加底盘后，\n\n4\n00:00:07.960 --> 00:00:11.033\n一个叫“底盘”的指令块新类别将会显现。\n\n5\n00:00:12.120 --> 00:00:16.130\n要使用底盘，从工具栏选择“转”指令块，\n\n6\n00:00:16.130 --> 00:00:21.130\n然后将它连接到“当开始”指令块。\n\n7\n00:00:21.380 --> 00:00:23.290\n选择您想要底盘\n\n8\n00:00:23.290 --> 00:00:24.863\n转动的度数。\n\n9\n00:00:25.760 --> 00:00:28.870\n底盘转向是以度数来测量的。\n\n10\n00:00:28.870 --> 00:00:32.350\n默认情况下，底盘会向右转。\n\n11\n00:00:32.350 --> 00:00:34.370\n要想底盘向左转，\n\n12\n00:00:34.370 --> 00:00:38.370\n在下拉菜单中将“右”更换成“左”。\n\n13\n00:00:38.370 --> 00:00:41.390\n您可以组合驱动和转向指令块到一起\n\n14\n00:00:41.390 --> 00:00:44.563\n来迅速和自动地驱动您的机器人。\n\n"}},{"thumb":"V5_Tutorial_arm.jpg","mov":"V5_Blocks_MovingArm_V2","description":"Moving the Arm","filter":"","placeholder":false,"vimeo":"475899949","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Moving the arm of a V5 Clawbot</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nis easy with VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nOnce you have the motors devices added,\n\n4\n00:00:08.250 --> 00:00:11.473\na new category of blocks named Motion will appear.\n\n5\n00:00:14.670 --> 00:00:18.880\nTo begin, select the spin for block from the toolbox.\n\n6\n00:00:18.880 --> 00:00:21.623\nThen, connect it to the when started block.\n\n7\n00:00:22.760 --> 00:00:27.760\nSelect the arm motor, up, for 90 degrees.\n\n8\n00:00:29.340 --> 00:00:31.660\nThis will raise the arm motor 90 degrees\n\n9\n00:00:31.660 --> 00:00:33.173\nfrom its current position.\n\n10\n00:00:34.060 --> 00:00:35.720\nYou can also move the arm motor\n\n11\n00:00:35.720 --> 00:00:37.883\nusing turns instead of degrees.\n\n12\n00:00:39.420 --> 00:00:41.590\nTo move the arm motor down,\n\n13\n00:00:41.590 --> 00:00:44.963\njust change Up to Down in the Blocks dropdown menu.\n\n","ar":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>تحريك ذراع V5 ا </v>\n\n2\n00:00:02.740 --> 00:00:05.850\nسهل مع VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nبمجرد اضافة جهاز محرك ،\n\n4\n00:00:08.250 --> 00:00:11.473\nستظهر فئة جديدة من المقاطع المسماة حركة.\n\n5\n00:00:14.670 --> 00:00:18.880\nللبدء، حدد الدوران للمقاطع من قائمة الأدوات.\n\n6\n00:00:18.880 --> 00:00:21.623\nثم قم بتوصيل المقطع بعند البدء.\n\n7\n00:00:22.760 --> 00:00:27.760\nحدد محرك الذراع، لأعلى لمدة 90 درجة.\n\n8\n00:00:29.340 --> 00:00:31.660\nهذا سوف يرفع محرك الذراع 90 درجة\n\n9\n00:00:31.660 --> 00:00:33.173\nمن موقعها الحالي.\n\n10\n00:00:34.060 --> 00:00:35.720\nيمكنك أيضا تحريك محرك الذراع\n\n11\n00:00:35.720 --> 00:00:37.883\nاستخدام الدوران بدلاً من الدرجات.\n\n12\n00:00:39.420 --> 00:00:41.590\nلتحريك محرك الذراع إلى الأسفل،\n\n13\n00:00:41.590 --> 00:00:44.963\nفقط قم بتغيير إلى أسفل في القائمة المنسدلة.\n\n","cs":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Pohybování ramene V5 Clawbota</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nje s VEXcode V5 snadné.\n\n3\n00:00:05.850 --> 00:00:08.250\nJakmile máš motorová zařízení přidána,\n\n4\n00:00:08.250 --> 00:00:11.473\nobjeví se nová kategorie bloků s názvem Pohyb.\n\n5\n00:00:14.670 --> 00:00:18.880\nPro začátek vyber blok Otoč o z panelu nástrojů.\n\n6\n00:00:18.880 --> 00:00:21.623\nPotom ho připoj k bloku Při spuštění.\n\n7\n00:00:22.760 --> 00:00:27.760\nVyber Motor Ramene, Nahoru, o 90 stupňů.\n\n8\n00:00:29.340 --> 00:00:31.660\nTo zvedne motor ramene o 90 stupňů\n\n9\n00:00:31.660 --> 00:00:33.173\nz jeho aktuální polohy.\n\n10\n00:00:34.060 --> 00:00:35.720\nMotorem ramene můžeš také pohybovat\n\n11\n00:00:35.720 --> 00:00:37.883\npoužitím otáček místo stupňů.\n\n12\n00:00:39.420 --> 00:00:41.590\nPro pohyb motoru ramene dolů\n\n13\n00:00:41.590 --> 00:00:44.963\nprostě změň Nahoru na Dolů v rozbalovacím menu bloků.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Moviendo el brazo de un Clawbot VEX V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nes fácil con VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nUna vez que tiene un dispositivo de motor añadido,\n\n4\n00:00:08.250 --> 00:00:11.473\naparecerá una nueva categoría de bloques llamado Movimiento.\n\n5\n00:00:14.670 --> 00:00:18.880\nPara empezar, selecciona el bloque de \"Gira Por\" en la caja de herramientas.\n\n6\n00:00:18.880 --> 00:00:21.623\nLuego, conéctalo al bloque \"Cuando Empieza\".\n\n7\n00:00:22.760 --> 00:00:27.760\nSelecciona el motor de la garra, Hacia Arriba por 90 grados.\n\n8\n00:00:29.340 --> 00:00:31.660\nEsto elevará el motor del brazo 90 grados\n\n9\n00:00:31.660 --> 00:00:33.173\ndesde su posición actual.\n\n10\n00:00:34.060 --> 00:00:35.720\nTambién puede mover el motor del brazo\n\n11\n00:00:35.720 --> 00:00:37.883\nusando vueltas en lugar de grados.\n\n12\n00:00:39.420 --> 00:00:41.590\nPara mover el motor del brazo hacia abajo,\n\n13\n00:00:41.590 --> 00:00:44.963\nsólo cambe \"hacia arriba\" a \"hacia abajo\" en el menú desplegable de bloques.\n\n","es":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Moviendo el brazo de un Clawbot VEX V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nes fácil con VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nUna vez que tiene un dispositivo de motor añadido,\n\n4\n00:00:08.250 --> 00:00:11.473\naparecerá una nueva categoría de bloques llamado Movimiento.\n\n5\n00:00:14.670 --> 00:00:18.880\nPara empezar, selecciona el bloque de \"Gira Por\" en la caja de herramientas.\n\n6\n00:00:18.880 --> 00:00:21.623\nLuego, conéctalo al bloque \"Cuando Empieza\".\n\n7\n00:00:22.760 --> 00:00:27.760\nSelecciona el motor de la garra, Hacia Arriba por 90 grados.\n\n8\n00:00:29.340 --> 00:00:31.660\nEsto elevará el motor del brazo 90 grados\n\n9\n00:00:31.660 --> 00:00:33.173\ndesde su posición actual.\n\n10\n00:00:34.060 --> 00:00:35.720\nTambién puede mover el motor del brazo\n\n11\n00:00:35.720 --> 00:00:37.883\nusando vueltas en lugar de grados.\n\n12\n00:00:39.420 --> 00:00:41.590\nPara mover el motor del brazo hacia abajo,\n\n13\n00:00:41.590 --> 00:00:44.963\nsólo cambe \"hacia arriba\" a \"hacia abajo\" en el menú desplegable de bloques.\n\n","fi":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>V5 Clawbot robotin käsivarren liike</v>\n\n2\n00:00:02.740 --> 00:00:05.850\non helppo ohjelmoida VEXcode V5 -ohjelmalla.\n\n3\n00:00:05.850 --> 00:00:08.250\nJos olet lisännyt moottorin Laitteet-ikkunassa,\n\n4\n00:00:08.250 --> 00:00:11.473\nnäet komennot Liike-valinnan alta.\n\n5\n00:00:14.670 --> 00:00:18.880\nValitse Pyöritä määrän -blokki työkaluista.\n\n6\n00:00:18.880 --> 00:00:21.623\nLiitä se Kun käynnissä-blokkiin.\n\n7\n00:00:22.760 --> 00:00:27.760\nValitse käsimoottori, suunta ylöspäin ja 90 astetta väliksi.\n\n8\n00:00:29.340 --> 00:00:31.660\nTämä nostaa käsivarsimoottoria 90 astetta\n\n9\n00:00:31.660 --> 00:00:33.173\nnykyisestä asennosta.\n\n10\n00:00:34.060 --> 00:00:35.720\nVoit myös liikuttaa kättä\n\n11\n00:00:35.720 --> 00:00:37.883\nasteiden sijaan kierroksina.\n\n12\n00:00:39.420 --> 00:00:41.590\nJos haluat laskea kättä alaspäin\n\n13\n00:00:41.590 --> 00:00:44.963\nvaihta pyörimissuuntaa suunnasta Eteenpäin suuntaan Taaksepäin.\n\n","fr":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Déplacer le bras d'un Robot Pince V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nest facile avec VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nUne fois que vous avez ajouté les appareils moteurs,\n\n4\n00:00:08.250 --> 00:00:11.473\nune nouvelle catégorie de blocs\nnommée \"Déplacement\" apparaitra.\n\n5\n00:00:14.670 --> 00:00:18.880\nPour commencer, sélectionnez le bloc \"Tourner de\" dans la Boîte à outils.\n\n6\n00:00:18.880 --> 00:00:21.623\nPuis connectez-le au bloc \"Au démarrage\".\n\n7\n00:00:22.760 --> 00:00:27.760\nSélectionnez le moteur du bras, \"En haut\", de 90 degrés.\n\n8\n00:00:29.340 --> 00:00:31.660\nCela montera le moteur du bras de 90 degrés\n\n9\n00:00:31.660 --> 00:00:33.173\nà partir de sa position actuelle.\n\n10\n00:00:34.060 --> 00:00:35.720\nVous pouvez également déplacer le moteur du bras\n\n11\n00:00:35.720 --> 00:00:37.883\nen utilisant des tours au lieu de degrés.\n\n12\n00:00:39.420 --> 00:00:41.590\nPour déplacer le moteur du bras vers le bas,\n\n13\n00:00:41.590 --> 00:00:44.963\nil suffit de changer \"haut\" par \"bas\" dans le menu déroulant Blocs.\n\n","ko":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>VEXcode V5를 통해 V5 클로봇의</v>\n\n2\n00:00:02.740 --> 00:00:05.850\n팔을 쉽게 움직일 수 있습니다.\n\n3\n00:00:05.850 --> 00:00:08.250\n모터를 추가하면\n\n4\n00:00:08.250 --> 00:00:11.473\n'모션'이라는 새 블록 카테고리가 나타납니다.\n\n5\n00:00:14.670 --> 00:00:18.880\n시작하려면 도구 상자에서 '회전하기' 블록을 선택합니다.\n\n6\n00:00:18.880 --> 00:00:21.623\n그리고 '시작하기' 블록에 연결합니다.\n\n7\n00:00:22.760 --> 00:00:27.760\n팔 모터를 \"위\"와 \"90도\"로 설정합니다.\n\n8\n00:00:29.340 --> 00:00:31.660\n그러면 팔 모터를 현재 위치에서\n\n9\n00:00:31.660 --> 00:00:33.173\n90도 위로 올릴 것입니다.\n\n10\n00:00:34.060 --> 00:00:35.720\n팔 모터를\n\n11\n00:00:35.720 --> 00:00:37.883\n각도 대신 \"돌기\"를 사용하여 움직일 수도 있습니다.\n\n12\n00:00:39.420 --> 00:00:41.590\n팔 모터를 아래로 이동하려면\n\n13\n00:00:41.590 --> 00:00:44.963\n블록의 드롭다운 메뉴에서 '위'를 '아래'로 변경하면 됩니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Programa \"VEXcode V5\" lengva</v>\n\n2\n00:00:02.740 --> 00:00:05.850\njudinti \"V5 Clawbot\" petį.\n\n3\n00:00:05.850 --> 00:00:08.250\nPridėję variklio prietaisą,\n\n4\n00:00:08.250 --> 00:00:11.473\natsiras nauja blokų pavadintų \"Motion\" (liet. Judėjimas) kategorija.\n\n5\n00:00:14.670 --> 00:00:18.880\nNorėdami pradėti, parankinėje pasirinkite \"suktis kiek\" bloką.\n\n6\n00:00:18.880 --> 00:00:21.623\nPo to, prijunkite jį prie \"kada pradėti\" bloko.\n\n7\n00:00:22.760 --> 00:00:27.760\nPasirinkite: peties variklis, į viršų, 90 laipsnių.\n\n8\n00:00:29.340 --> 00:00:31.660\nTai variklio petį iš dabartinės padėties\n\n9\n00:00:31.660 --> 00:00:33.173\npakelia 90 laipsnių.\n\n10\n00:00:34.060 --> 00:00:35.720\nVariklio petį taip pat galite judinti,\n\n11\n00:00:35.720 --> 00:00:37.883\nvietoje laipsnių naudodami posūkius.\n\n12\n00:00:39.420 --> 00:00:41.590\nNorėdami nuleisti variklio petį,\n\n13\n00:00:41.590 --> 00:00:44.963\nišplėstiniame blokų meniu pakeiskite \"į viršų\" į \"į apačią\".\n\n","lv":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>V5 Clawbot rokas pārvietošana</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nir vienkārša, izmantojot VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nKad esiet motora ierīces pievienojis,\n\n4\n00:00:08.250 --> 00:00:11.473\nparādīsies jauna bloku kategorija ar nosaukumu “Motion”.\n\n5\n00:00:14.670 --> 00:00:18.880\nLai sāktu, atlasiet rīklodziņā bloku “Spin For”.\n\n6\n00:00:18.880 --> 00:00:21.623\nPēc tam, pievienojiet to pie bloka “When Started”.\n\n7\n00:00:22.760 --> 00:00:27.760\nAtlasiet rokas motoru, uz augšu, 90 grādi.\n\n8\n00:00:29.340 --> 00:00:31.660\nTas rokas motoru par 90 grādiem\n\n9\n00:00:31.660 --> 00:00:33.173\npacels no pašreizējā stāvokļa.\n\n10\n00:00:34.060 --> 00:00:35.720\nRokas motoru var arī darbināt,\n\n11\n00:00:35.720 --> 00:00:37.883\nizmantojot pagriezienus, nevis grādus.\n\n12\n00:00:39.420 --> 00:00:41.590\nLai darbinātu rokas motoru uz leju,\n\n13\n00:00:41.590 --> 00:00:44.963\nvienkārši pārslēdziet nolaižamajā izvēlnē “Up” uz “Down”.\n\n","nl":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor> Het bewegen van de arm van een V5 Klauwbot </v>\n\n2\n00:00:02.740 --> 00:00:05.850\nis eenvoudig met VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nZodra u een motorapparaten heeft toegevoegd,\n\n4\n00:00:08.250 --> 00:00:11.473\nverschijnt er een nieuwe categorie blokken met de naam Beweging.\n\n5\n00:00:14.670 --> 00:00:18.880\nSelecteer om te beginnen het draai voor blok in de toolbox.\n\n6\n00:00:18.880 --> 00:00:21.623\nSluit het vervolgens aan bij het wanneer gestart blok.\n\n7\n00:00:22.760 --> 00:00:27.760\nSelecteer de ArmMotor, Omhoog, voor 90 graden.\n\n8\n00:00:29.340 --> 00:00:31.660\nHierdoor wordt de armmotor 90 graden opgetild\n\n9\n00:00:31.660 --> 00:00:33.173\nten opzichte van zijn huidige positie.\n\n10\n00:00:34.060 --> 00:00:35.720\nU kunt de armmotor ook met draaien\n\n11\n00:00:35.720 --> 00:00:37.883\nin plaats van graden bewegen.\n\n12\n00:00:39.420 --> 00:00:41.590\nOm de armmotor naar beneden te bewegen,\n\n13\n00:00:41.590 --> 00:00:44.963\nwijzigt u gewoon Omhoog naar Omlaag in het blokken vervolgkeuzemenu.\n\n","pl":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Poruszanie ramieniem Clawbot V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\njest łatwe przy pomocy bloków VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nPo dodaniu urządzenia,\n\n4\n00:00:08.250 --> 00:00:11.473\npojawi się nowa kategoria bloków\no nazwie Ruch.\n\n5\n00:00:14.670 --> 00:00:18.880\nAby rozpocząć, wybierz obrót dla bloku z przybornika.\n\n6\n00:00:18.880 --> 00:00:21.623\nNastępnie połącz go z\nblokiem \"po uruchomieniu\".\n\n7\n00:00:22.760 --> 00:00:27.760\nWybierz ramienia, podnieś, o 90 stopni.\n\n8\n00:00:29.340 --> 00:00:31.660\nPodniesie to o 90 stopni ramię\n\n9\n00:00:31.660 --> 00:00:33.173\nz jego obecnej pozycji.\n\n10\n00:00:34.060 --> 00:00:35.720\nMożesz również poruszać silnikiem ramienia\n\n11\n00:00:35.720 --> 00:00:37.883\nza pomocą skrętów zamiast stopni.\n\n12\n00:00:39.420 --> 00:00:41.590\nAby przesunąć ramię w dół,\n\n13\n00:00:41.590 --> 00:00:44.963\npo prostu zmień w \"górę\" na \"dół\" w rozwijanym menu.\n\n","ru":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Движение рукой Clawbot</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nосуществляется довольно просто.\n\n3\n00:00:05.850 --> 00:00:08.250\nПосле добавления приводов,\n\n4\n00:00:08.250 --> 00:00:11.473\nпоявится новый раздел блоков в инструментарии.\n\n5\n00:00:14.670 --> 00:00:18.880\nДля начала, выберите блок вращения из инструментария.\n\n6\n00:00:18.880 --> 00:00:21.623\nПодсоедините его к блоку начала программы.\n\n7\n00:00:22.760 --> 00:00:27.760\nВыберите привод руки, вверх на 90 градусов.\n\n8\n00:00:29.340 --> 00:00:31.660\nЭто позволит поднять руку на 90 градусов\n\n9\n00:00:31.660 --> 00:00:33.173\nиз текущего положения.\n\n10\n00:00:34.060 --> 00:00:35.720\nВы также можете двигать рукой,\n\n11\n00:00:35.720 --> 00:00:37.883\nиспользуя обороты вместо градусов.\n\n12\n00:00:39.420 --> 00:00:41.590\nДля того, чтобы изменить направление вращения,\n\n13\n00:00:41.590 --> 00:00:44.963\nпросто измените Вверх на Вниз в раскрывающемся списке.\n\n","th":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor> การขยับแขนของ V5 Clawbot </v>\n\n2\n00:00:02.740 --> 00:00:05.850\nนั้นทำได้ง่ายด้วย VEXcode V5\n\n3\n00:00:05.850 --> 00:00:08.250\nเมื่อคุณเพิ่มอุปกรณ์มอเตอร์แล้ว\n\n4\n00:00:08.250 --> 00:00:11.473\nจะมีหมวดหมู่ใหม่ของบล็อกชื่อ Motion ปรากฏขึ้น\n\n5\n00:00:14.670 --> 00:00:18.880\nในขั้นแรกให้เลือกการหมุนสำหรับบล็อก spin for block จากกล่องเครื่องมือ\n\n6\n00:00:18.880 --> 00:00:21.623\nจากนั้นเชื่อมต่อกับ when started บล็อก\n\n7\n00:00:22.760 --> 00:00:27.760\nเลือกมอเตอร์แขนขึ้นไปที่ 90 องศา\n\n8\n00:00:29.340 --> 00:00:31.660\nวิธีนี้จะทำให้มอเตอร์แขนยกขึ้น 90 องศา\n\n9\n00:00:31.660 --> 00:00:33.173\nจากตำแหน่งปัจจุบัน\n\n10\n00:00:34.060 --> 00:00:35.720\nคุณยังสามารถขยับมอเตอร์แขน\n\n11\n00:00:35.720 --> 00:00:37.883\nโดยใช้การหมุนแทนองศา\n\n12\n00:00:39.420 --> 00:00:41.590\nในการเลื่อนมอเตอร์แขนลง\n\n13\n00:00:41.590 --> 00:00:44.963\nเพียงแค่เปลี่ยนขึ้น Up เป็นลง Down ในเมนู dropdown\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Рухи рукою клешнебота V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nлегко з VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nКоли ви додасте мотори,\n\n4\n00:00:08.250 --> 00:00:11.473\nз'явиться категорія блоків із назвою \"Рух\".\n\n5\n00:00:14.670 --> 00:00:18.880\nЩоб почати, виберіть блок для обертання з набору блоків.\n\n6\n00:00:18.880 --> 00:00:21.623\nПотім приєднайте його до блока \"коли почнемо\".\n\n7\n00:00:22.760 --> 00:00:27.760\nВиберіть мотор руки, вгору, на 90 градусів.\n\n8\n00:00:29.340 --> 00:00:31.660\nЦе підніме руку на 90 градусів\n\n9\n00:00:31.660 --> 00:00:33.173\nвідносно її поточної позиції.\n\n10\n00:00:34.060 --> 00:00:35.720\nВи також можете рухати руку\n\n11\n00:00:35.720 --> 00:00:37.883\nвикористовуючи повороти замість градусів.\n\n12\n00:00:39.420 --> 00:00:41.590\nДля переміщення руки вниз\n\n13\n00:00:41.590 --> 00:00:44.963\nзмініть \"вгору\" на \"вниз\" у спадному меню блока.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>Di chuyển cánh tay của Clawbot V5</v>\n\n2\n00:00:02.740 --> 00:00:05.850\nthật dễ dàng với VEXcode V5.\n\n3\n00:00:05.850 --> 00:00:08.250\nSau khi bạn đã thêm các thiết bị động cơ,\n\n4\n00:00:08.250 --> 00:00:11.473\nmột danh mục khối mới có tên Chuyển động sẽ xuất hiện.\n\n5\n00:00:14.670 --> 00:00:18.880\nĐể bắt đầu, hãy chọn vòng quay cho khối từ hộp công cụ.\n\n6\n00:00:18.880 --> 00:00:21.623\nSau đó, kết nối nó với khối khi bắt đầu.\n\n7\n00:00:22.760 --> 00:00:27.760\nChọn động cơ cánh tay, lên, 90 độ.\n\n8\n00:00:29.340 --> 00:00:31.660\nĐiều này sẽ nâng động cơ cánh tay lên 90 độ\n\n9\n00:00:31.660 --> 00:00:33.173\ntừ vị trí hiện tại của nó.\n\n10\n00:00:34.060 --> 00:00:35.720\nBạn cũng có thể di chuyển động cơ cánh tay\n\n11\n00:00:35.720 --> 00:00:37.883\nsử dụng lượt thay vì độ.\n\n12\n00:00:39.420 --> 00:00:41.590\nĐể di chuyển động cơ cánh tay xuống,\n\n13\n00:00:41.590 --> 00:00:44.963\nchỉ cần thay đổi Lên thành Xuống trong menu thả xuống Khối.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\ncrwdns96196:0crwdne96196:0\n\n2\n00:00:02.740 --> 00:00:05.850\ncrwdns96198:0crwdne96198:0\n\n3\n00:00:05.850 --> 00:00:08.250\ncrwdns96200:0crwdne96200:0\n\n4\n00:00:08.250 --> 00:00:11.473\ncrwdns96202:0crwdne96202:0\n\n5\n00:00:14.670 --> 00:00:18.880\ncrwdns96204:0crwdne96204:0\n\n6\n00:00:18.880 --> 00:00:21.623\ncrwdns96206:0crwdne96206:0\n\n7\n00:00:22.760 --> 00:00:27.760\ncrwdns96208:0crwdne96208:0\n\n8\n00:00:29.340 --> 00:00:31.660\ncrwdns96210:0crwdne96210:0\n\n9\n00:00:31.660 --> 00:00:33.173\ncrwdns96212:0crwdne96212:0\n\n10\n00:00:34.060 --> 00:00:35.720\ncrwdns96214:0crwdne96214:0\n\n11\n00:00:35.720 --> 00:00:37.883\ncrwdns96216:0crwdne96216:0\n\n12\n00:00:39.420 --> 00:00:41.590\ncrwdns96218:0crwdne96218:0\n\n13\n00:00:41.590 --> 00:00:44.963\ncrwdns96220:0crwdne96220:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.830 --> 00:00:02.740\n<v Instructor>通过VEXcode V5移动一台V5钳爪机器人</v>\n\n2\n00:00:02.740 --> 00:00:05.850\n的机械臂很容易。\n\n3\n00:00:05.850 --> 00:00:08.250\n一旦您已经添加电机设备后，\n\n4\n00:00:08.250 --> 00:00:11.473\n一个叫“运动”的指令块新类别就会出现。\n\n5\n00:00:14.670 --> 00:00:18.880\n欲开始，从工具栏选择“转”指令块。\n\n6\n00:00:18.880 --> 00:00:21.623\n然后，将它连接到“当开始”指令块。\n\n7\n00:00:22.760 --> 00:00:27.760\n选择机械臂电机，上，90度。\n\n8\n00:00:29.340 --> 00:00:31.660\n该指令将使机械臂从当前位置\n\n9\n00:00:31.660 --> 00:00:33.173\n抬升90度。\n\n10\n00:00:34.060 --> 00:00:35.720\n您也可以使用转而不是度\n\n11\n00:00:35.720 --> 00:00:37.883\n来移动机械臂电机。\n\n12\n00:00:39.420 --> 00:00:41.590\n欲使机械臂电机向下移动，\n\n13\n00:00:41.590 --> 00:00:44.963\n只需要在下拉菜单将“上”改为“下”。\n\n"}},{"thumb":"V5_Tutorial_claw.jpg","mov":"V5_Blocks_OpeningtheClaw_V2","description":"Opening the Claw","filter":"","placeholder":false,"vimeo":"475900648","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Moving the claw of a V5 ClawBot</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nis easy within a V5 Blocks project.\n\n3\n00:00:06.000 --> 00:00:08.440\nOnce you have the motor's devices added,\n\n4\n00:00:08.440 --> 00:00:12.410\na new category of blocks named Motion will appear.\n\n5\n00:00:12.410 --> 00:00:15.780\nSelect the Spin For block from the toolbox.\n\n6\n00:00:15.780 --> 00:00:18.610\nConnect it to the When Started block.\n\n7\n00:00:18.610 --> 00:00:20.033\nSelect the claw motor.\n\n8\n00:00:21.470 --> 00:00:22.303\nOpen.\n\n9\n00:00:23.220 --> 00:00:24.603\nFor 60 degrees.\n\n10\n00:00:26.350 --> 00:00:27.660\nThis opens the claw motor\n\n11\n00:00:27.660 --> 00:00:29.943\n60 degrees from its current position.\n\n12\n00:00:31.090 --> 00:00:33.570\nYou can also move the claw motor using turns,\n\n13\n00:00:33.570 --> 00:00:35.460\ninstead of degrees.\n\n14\n00:00:35.460 --> 00:00:37.040\nA tip for using the claw motor\n\n15\n00:00:37.040 --> 00:00:39.810\nis to use the set motor timeout block.\n\n16\n00:00:39.810 --> 00:00:41.590\nThis block sets a time limit,\n\n17\n00:00:41.590 --> 00:00:43.440\nto allow the stack to continue,\n\n18\n00:00:43.440 --> 00:00:47.230\nif the motor cannot reach its target within the time limit.\n\n19\n00:00:47.230 --> 00:00:49.420\nSet the motor to the claw motor.\n\n20\n00:00:49.420 --> 00:00:52.270\nAnd the timeout to two seconds.\n\n21\n00:00:52.270 --> 00:00:55.420\nUse another Spin Forward block from the toolbox.\n\n22\n00:00:55.420 --> 00:00:56.823\nConnect it to the stack.\n\n23\n00:00:57.790 --> 00:00:59.203\nSelect the claw motor.\n\n24\n00:01:00.410 --> 00:01:01.243\nClosed.\n\n25\n00:01:02.930 --> 00:01:04.283\nFor 30 degrees.\n\n26\n00:01:07.300 --> 00:01:10.233\nYour claw motor is now ready to grab an object.\n\n","ar":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>تحريك ذراع V5 ا </v>\n\n2\n00:00:02.710 --> 00:00:06.000\nسهلة مع مشروع المقاطع 5V.\n\n3\n00:00:06.000 --> 00:00:08.440\nبمجرد اضافة جهاز محرك ،\n\n4\n00:00:08.440 --> 00:00:12.410\nستظهر فئة جديدة من المقاطع المسماة حركة.\n\n5\n00:00:12.410 --> 00:00:15.780\nحدد محرك المقاطع من قائمة الأدوات.\n\n6\n00:00:15.780 --> 00:00:18.610\nثم قم بتوصيل هذا المقطع إلى مقطع \"عند البدء\".\n\n7\n00:00:18.610 --> 00:00:20.033\nحدد محرك الذراع.\n\n8\n00:00:21.470 --> 00:00:22.303\nإفتح.\n\n9\n00:00:23.220 --> 00:00:24.603\nل 60 درجة.\n\n10\n00:00:26.350 --> 00:00:27.660\nهذا يفتح محرك المخلب\n\n11\n00:00:27.660 --> 00:00:29.943\n60 درجة عن وضعها الحالي.\n\n12\n00:00:31.090 --> 00:00:33.570\nيمكنك أيضا نقل\nمحرك المخلب باستخدام الدوران,\n\n13\n00:00:33.570 --> 00:00:35.460\nبدلاً من الدرجات.\n\n14\n00:00:35.460 --> 00:00:37.040\nنصيحة لاستخدام محرك المخلب\n\n15\n00:00:37.040 --> 00:00:39.810\nهو استخدام مجموعة مقطع مهلة المحرك.\n\n16\n00:00:39.810 --> 00:00:41.590\nهذ المقطع يحدد حد زمني،\n\n17\n00:00:41.590 --> 00:00:43.440\nللسماح للمجموعة بالاستمرار ،\n\n18\n00:00:43.440 --> 00:00:47.230\nإذا لم يتمكن المحرك من بلوغ هدفه في غضون المهلة المحددة.\n\n19\n00:00:47.230 --> 00:00:49.420\nعيّن المحرك إلى محرك المخلب.\n\n20\n00:00:49.420 --> 00:00:52.270\nاضبط مهلة العمل إلى ثانيتين.\n\n21\n00:00:52.270 --> 00:00:55.420\nإستخدم مقطع ''دورة أخرى'' من قائمة الأدوات.\n\n22\n00:00:55.420 --> 00:00:56.823\nقم بتوصيله إلى المجموعة.\n\n23\n00:00:57.790 --> 00:00:59.203\nحدد محرك الذراع.\n\n24\n00:01:00.410 --> 00:01:01.243\nمغلق.\n\n25\n00:01:02.930 --> 00:01:04.283\nل 30 درجة.\n\n26\n00:01:07.300 --> 00:01:10.233\nمحرك المخلب الخاص بك الآن جاهز لالتقاط جسم.\n\n","cs":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Pohybování drapáku V5 Clawbota</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nje v blokovém projektu V5 snadné.\n\n3\n00:00:06.000 --> 00:00:08.440\nJakmile máš motorová zařízení přidána,\n\n4\n00:00:08.440 --> 00:00:12.410\nobjeví se nová kategorie bloků s názvem Pohyb.\n\n5\n00:00:12.410 --> 00:00:15.780\nVyber blok Otoč o na panelu nástrojů.\n\n6\n00:00:15.780 --> 00:00:18.610\nPřipoj ho k bloku Při spuštění.\n\n7\n00:00:18.610 --> 00:00:20.033\nVyber Motor Drapáku.\n\n8\n00:00:21.470 --> 00:00:22.303\nOtevřít.\n\n9\n00:00:23.220 --> 00:00:24.603\nO 60 stupňů.\n\n10\n00:00:26.350 --> 00:00:27.660\nTo otevře motor drapáku\n\n11\n00:00:27.660 --> 00:00:29.943\no 60 stupňů z jeho aktuální polohy.\n\n12\n00:00:31.090 --> 00:00:33.570\nMotorem drapáku můžeš také pohybovat použitím otáček\n\n13\n00:00:33.570 --> 00:00:35.460\nmísto stupňů.\n\n14\n00:00:35.460 --> 00:00:37.040\nRada pro používání motoru drapáku je,\n\n15\n00:00:37.040 --> 00:00:39.810\npoužít blok nastavení časového limitu motoru.\n\n16\n00:00:39.810 --> 00:00:41.590\nTento blok nastaví časový limit,\n\n17\n00:00:41.590 --> 00:00:43.440\naby umožnil zásobníku instrukcí pokračovat,\n\n18\n00:00:43.440 --> 00:00:47.230\njestliže motor nedokáže dosáhnout svého cíle v časovém limitu.\n\n19\n00:00:47.230 --> 00:00:49.420\nNastav motor na Motor Drapáku.\n\n20\n00:00:49.420 --> 00:00:52.270\nA časový limit na dvě vteřiny.\n\n21\n00:00:52.270 --> 00:00:55.420\nPoužij další blok Otoč o z panelu nástrojů.\n\n22\n00:00:55.420 --> 00:00:56.823\nPřipoj ho do zásobníku instrukcí.\n\n23\n00:00:57.790 --> 00:00:59.203\nVyber Motor Drapáku.\n\n24\n00:01:00.410 --> 00:01:01.243\nZavřít.\n\n25\n00:01:02.930 --> 00:01:04.283\nO 30 stupňů.\n\n26\n00:01:07.300 --> 00:01:10.233\nTvůj Motor Drapáku je nyní připravený něco chňapnout.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Moviendo el brazo de un Clawbot VEX V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nes fácil con un proyecto de V5 Blocks (bloques).\n\n3\n00:00:06.000 --> 00:00:08.440\nUna vez que tiene un dispositivo de motor añadido,\n\n4\n00:00:08.440 --> 00:00:12.410\naparecerá una nueva categoría de bloques llamado Movimiento.\n\n5\n00:00:12.410 --> 00:00:15.780\nSeleccione el bloque \"Gira Por\" de la caja de herramientas.\n\n6\n00:00:15.780 --> 00:00:18.610\nConéctelo al bloque \"Cuado Empieza\".\n\n7\n00:00:18.610 --> 00:00:20.033\nSeleccione el motor del brazo.\n\n8\n00:00:21.470 --> 00:00:22.303\nAbrir.\n\n9\n00:00:23.220 --> 00:00:24.603\nPor 60 grados.\n\n10\n00:00:26.350 --> 00:00:27.660\nEsto abre el motor de la garra\n\n11\n00:00:27.660 --> 00:00:29.943\n60 grados desde su posición actual.\n\n12\n00:00:31.090 --> 00:00:33.570\nTambién puede mover el motor de la garra usando giros,\n\n13\n00:00:33.570 --> 00:00:35.460\nen lugar de grados.\n\n14\n00:00:35.460 --> 00:00:37.040\nUn consejo para usar el motor de la garra es\n\n15\n00:00:37.040 --> 00:00:39.810\nusar el bloque \"Establecer Motor Tiempo Fuera\".\n\n16\n00:00:39.810 --> 00:00:41.590\nEste bloque establece un límite de tiempo,\n\n17\n00:00:41.590 --> 00:00:43.440\npara permitir que la pila continúe,\n\n18\n00:00:43.440 --> 00:00:47.230\nsi el motor no puede alcanzar su objetivo dentro del límite de tiempo.\n\n19\n00:00:47.230 --> 00:00:49.420\nEstablece el motor al motor de la garra.\n\n20\n00:00:49.420 --> 00:00:52.270\nY el fuera de tiempo a dos segundos.\n\n21\n00:00:52.270 --> 00:00:55.420\nSeleccione otro bloque \"Gira Por\" de la caja de herramientas.\n\n22\n00:00:55.420 --> 00:00:56.823\nConéctalo a la pila.\n\n23\n00:00:57.790 --> 00:00:59.203\nSeleccione el motor del brazo.\n\n24\n00:01:00.410 --> 00:01:01.243\nCerrar.\n\n25\n00:01:02.930 --> 00:01:04.283\nPor 30 grados.\n\n26\n00:01:07.300 --> 00:01:10.233\nSu motor de la garra ahora está \nlisto para agarrar un objeto.\n\n","es":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Moviendo el brazo de un Clawbot VEX V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nes fácil con un proyecto de V5 Blocks (bloques).\n\n3\n00:00:06.000 --> 00:00:08.440\nUna vez que tiene un dispositivo de motor añadido,\n\n4\n00:00:08.440 --> 00:00:12.410\naparecerá una nueva categoría de bloques llamado Movimiento.\n\n5\n00:00:12.410 --> 00:00:15.780\nSeleccione el bloque \"Gira Por\" de la caja de herramientas.\n\n6\n00:00:15.780 --> 00:00:18.610\nConéctelo al bloque \"Cuado Empieza\".\n\n7\n00:00:18.610 --> 00:00:20.033\nSeleccione el motor del brazo.\n\n8\n00:00:21.470 --> 00:00:22.303\nAbrir.\n\n9\n00:00:23.220 --> 00:00:24.603\nPor 60 grados.\n\n10\n00:00:26.350 --> 00:00:27.660\nEsto abre el motor de la garra\n\n11\n00:00:27.660 --> 00:00:29.943\n60 grados desde su posición actual.\n\n12\n00:00:31.090 --> 00:00:33.570\nTambién puede mover el motor de la garra usando giros,\n\n13\n00:00:33.570 --> 00:00:35.460\nen lugar de grados.\n\n14\n00:00:35.460 --> 00:00:37.040\nUn consejo para usar el motor de la garra es\n\n15\n00:00:37.040 --> 00:00:39.810\nusar el bloque \"Establecer Motor Tiempo Fuera\".\n\n16\n00:00:39.810 --> 00:00:41.590\nEste bloque establece un límite de tiempo,\n\n17\n00:00:41.590 --> 00:00:43.440\npara permitir que la pila continúe,\n\n18\n00:00:43.440 --> 00:00:47.230\nsi el motor no puede alcanzar su objetivo dentro del límite de tiempo.\n\n19\n00:00:47.230 --> 00:00:49.420\nEstablece el motor al motor de la garra.\n\n20\n00:00:49.420 --> 00:00:52.270\nY el fuera de tiempo a dos segundos.\n\n21\n00:00:52.270 --> 00:00:55.420\nSeleccione otro bloque \"Gira Por\" de la caja de herramientas.\n\n22\n00:00:55.420 --> 00:00:56.823\nConéctalo a la pila.\n\n23\n00:00:57.790 --> 00:00:59.203\nSeleccione el motor del brazo.\n\n24\n00:01:00.410 --> 00:01:01.243\nCerrar.\n\n25\n00:01:02.930 --> 00:01:04.283\nPor 30 grados.\n\n26\n00:01:07.300 --> 00:01:10.233\nSu motor de la garra ahora está \nlisto para agarrar un objeto.\n\n","fi":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>V5 ClawBot robotin kouran avaaminen</v>\n\n2\n00:00:02.710 --> 00:00:06.000\non helppoa V5 Blocks ohjelmassa.\n\n3\n00:00:06.000 --> 00:00:08.440\nKun kouramoottori on lisätty Laitteet-ikkunassa\n\n4\n00:00:08.440 --> 00:00:12.410\nnäet sen komennot Liike-valinnasta.\n\n5\n00:00:12.410 --> 00:00:15.780\nValitse Pyöritä määrän -blokki työkaluista.\n\n6\n00:00:15.780 --> 00:00:18.610\nSiirrä se Kun käynnissä -blokin alle pinoon.\n\n7\n00:00:18.610 --> 00:00:20.033\nValise moottoriksi Koura.\n\n8\n00:00:21.470 --> 00:00:22.303\nEteenpäin-valinta\n\n9\n00:00:23.220 --> 00:00:24.603\n60 astetta.\n\n10\n00:00:26.350 --> 00:00:27.660\nTämä avaa kouramoottorilla kouran\n\n11\n00:00:27.660 --> 00:00:29.943\n60 astetta nykyisestä asennosta.\n\n12\n00:00:31.090 --> 00:00:33.570\nYksikkönä voi käyttää myös kierros-valintaa\n\n13\n00:00:33.570 --> 00:00:35.460\nasteiden tilalla.\n\n14\n00:00:35.460 --> 00:00:37.040\nKannattaa kouramoottorille asettaa\n\n15\n00:00:37.040 --> 00:00:39.810\naikaraja komennolla Aseta aika.\n\n16\n00:00:39.810 --> 00:00:41.590\nKun aikaraja on asetettu\n\n17\n00:00:41.590 --> 00:00:43.440\nohjelman suoritus voi jatkua seuraavilla pinon blokeilla\n\n18\n00:00:43.440 --> 00:00:47.230\njos kouramoottori ei saavuta 60 astetta ja aikaleikkuri auttaaohjelmasuorituksen jatkoblokkeihin.\n\n19\n00:00:47.230 --> 00:00:49.420\nValitse Kouramoottori.\n\n20\n00:00:49.420 --> 00:00:52.270\nAseta aika-blokin aikarajaksi kaksi sekunttia.\n\n21\n00:00:52.270 --> 00:00:55.420\nKäytä uudelleen Pyöritä määrän-blokki.\n\n22\n00:00:55.420 --> 00:00:56.823\ntuo se blokkipinoon.\n\n23\n00:00:57.790 --> 00:00:59.203\nValise moottoriksi Koura.\n\n24\n00:01:00.410 --> 00:01:01.243\nSuunta Taaksepäin\n\n25\n00:01:02.930 --> 00:01:04.283\n30 astetta.\n\n26\n00:01:07.300 --> 00:01:10.233\nNyt kouramoottori on valmis tarttumaan esineeseen.\n\n","fr":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Déplacer la pince d'un Robot Pince V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nest facile dans un projet V5 Blocks.\n\n3\n00:00:06.000 --> 00:00:08.440\nUne fois que vous avez ajouté les appareils moteurs,\n\n4\n00:00:08.440 --> 00:00:12.410\nune nouvelle catégorie de blocs\nnommée \"Déplacement\" apparaitra.\n\n5\n00:00:12.410 --> 00:00:15.780\nSélectionnez le bloc \"Tourner de\" de la Boîte à outils.\n\n6\n00:00:15.780 --> 00:00:18.610\nConnectez-le au bloc \"Au démarrage\".\n\n7\n00:00:18.610 --> 00:00:20.033\nSélectionnez le moteur de la pince.\n\n8\n00:00:21.470 --> 00:00:22.303\n\"Ouvrir\".\n\n9\n00:00:23.220 --> 00:00:24.603\nDe 60 degrés.\n\n10\n00:00:26.350 --> 00:00:27.660\nCela ouvrira le moteur de la pince\n\n11\n00:00:27.660 --> 00:00:29.943\nde 60 degrés à partir de sa position actuelle.\n\n12\n00:00:31.090 --> 00:00:33.570\nVous pouvez également déplacer le moteur de la pince en indiquant un nombre de tours,\n\n13\n00:00:33.570 --> 00:00:35.460\nà la place des degrés.\n\n14\n00:00:35.460 --> 00:00:37.040\nUne astuce pour utiliser le moteur de la pince consiste à\n\n15\n00:00:37.040 --> 00:00:39.810\nutiliser le bloc \"Définir la temporisation du moteur\".\n\n16\n00:00:39.810 --> 00:00:41.590\nCe bloc définit une limite de temps,\n\n17\n00:00:41.590 --> 00:00:43.440\npour permettre à la pile de continuer,\n\n18\n00:00:43.440 --> 00:00:47.230\nsi le moteur ne peut pas atteindre la cible définie dans le délai indiqué.\n\n19\n00:00:47.230 --> 00:00:49.420\nDéfinir le moteur sur le moteur de pince.\n\n20\n00:00:49.420 --> 00:00:52.270\nEt la temporisation à deux secondes.\n\n21\n00:00:52.270 --> 00:00:55.420\nUtilisez un autre bloc \"Tourner de\" depuis la Boîte à outils.\n\n22\n00:00:55.420 --> 00:00:56.823\nConnectez-le à la pile.\n\n23\n00:00:57.790 --> 00:00:59.203\nSélectionnez le moteur de la pince.\n\n24\n00:01:00.410 --> 00:01:01.243\n\"Fermer\".\n\n25\n00:01:02.930 --> 00:01:04.283\nDe 30 degrés.\n\n26\n00:01:07.300 --> 00:01:10.233\nVotre moteur de pince est maintenant prêt à saisir un objet.\n\n","ko":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>V5 블록 프로젝트를 통해 V5 클로봇의</v>\n\n2\n00:00:02.710 --> 00:00:06.000\n집게발을 쉽게 움직일 수 있습니다.\n\n3\n00:00:06.000 --> 00:00:08.440\n모터를 추가하면\n\n4\n00:00:08.440 --> 00:00:12.410\n'모션'이라는 새 블록 카테고리가 나타납니다.\n\n5\n00:00:12.410 --> 00:00:15.780\n도구 상자에서 '회전하기' 블록을 선택합니다.\n\n6\n00:00:15.780 --> 00:00:18.610\n'시작하기' 블록에 연결합니다.\n\n7\n00:00:18.610 --> 00:00:20.033\n집게발 모터를 선택합니다.\n\n8\n00:00:21.470 --> 00:00:22.303\n60도 열기로\n\n9\n00:00:23.220 --> 00:00:24.603\n설정합니다.\n\n10\n00:00:26.350 --> 00:00:27.660\n집게발 모터가 현재 상태에서\n\n11\n00:00:27.660 --> 00:00:29.943\n60도 열립니다.\n\n12\n00:00:31.090 --> 00:00:33.570\n각도 대신 회전을 선택하여\n\n13\n00:00:33.570 --> 00:00:35.460\n집게발 모터를 움직일 수도 있습니다.\n\n14\n00:00:35.460 --> 00:00:37.040\n집게발 모터의 사용 방법은\n\n15\n00:00:37.040 --> 00:00:39.810\n'모터 타임 아웃 설정' 블록을 사용하는 것입니다.\n\n16\n00:00:39.810 --> 00:00:41.590\n이 블록은 모터가 제한된 시간 내에\n\n17\n00:00:41.590 --> 00:00:43.440\n목표에 도달할 수 없는 경우 스택이 지속되는\n\n18\n00:00:43.440 --> 00:00:47.230\n시간 제한을 설정합니다.\n\n19\n00:00:47.230 --> 00:00:49.420\n모터를 집게발 모터로 설정합니다.\n\n20\n00:00:49.420 --> 00:00:52.270\n타임 아웃을 2초로 설정합니다.\n\n21\n00:00:52.270 --> 00:00:55.420\n도구 상자에서 다른 '앞으로 회전하기' 블록을 사용하세요.\n\n22\n00:00:55.420 --> 00:00:56.823\n스택에 연결하세요.\n\n23\n00:00:57.790 --> 00:00:59.203\n집게발 모터를 선택합니다.\n\n24\n00:01:00.410 --> 00:01:01.243\n30도 닫기로\n\n25\n00:01:02.930 --> 00:01:04.283\n설정하세요.\n\n26\n00:01:07.300 --> 00:01:10.233\n이제 집게발 모터는 물체를 잡을 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>\"V5 Blocks\" projektu lengva</v>\n\n2\n00:00:02.710 --> 00:00:06.000\njudinti \"V5 ClawBot\" leteną.\n\n3\n00:00:06.000 --> 00:00:08.440\nPridėję variklio prietaisus,\n\n4\n00:00:08.440 --> 00:00:12.410\natsiras nauja blokų pavadintų \"Judėjimas\" kategorija.\n\n5\n00:00:12.410 --> 00:00:15.780\nParankinėje pasirinkite \"suktis kiek\" bloką.\n\n6\n00:00:15.780 --> 00:00:18.610\nPrijunkite jį prie \"kada pradėti\" bloko.\n\n7\n00:00:18.610 --> 00:00:20.033\nPasirinkite letenos variklį.\n\n8\n00:00:21.470 --> 00:00:22.303\nAtidaryti.\n\n9\n00:00:23.220 --> 00:00:24.603\n60 Laipsnių.\n\n10\n00:00:26.350 --> 00:00:27.660\nTai letenos variklį atveria\n\n11\n00:00:27.660 --> 00:00:29.943\n60 laipsnių nuo dabartinės padėties.\n\n12\n00:00:31.090 --> 00:00:33.570\nTaip pat, variklio leteną galite judinti vietoje laipsnių,\n\n13\n00:00:33.570 --> 00:00:35.460\nnaudodami posūkius.\n\n14\n00:00:35.460 --> 00:00:37.040\nPatarimas naudojant letenos variklį,\n\n15\n00:00:37.040 --> 00:00:39.810\nnaudokite nustatytą variklio \"delsos\" bloką.\n\n16\n00:00:39.810 --> 00:00:41.590\nŠis blokas nustato laiko limitą,\n\n17\n00:00:41.590 --> 00:00:43.440\nleidžiantį blokų krūvai tęsti veiksmą,\n\n18\n00:00:43.440 --> 00:00:47.230\njeigu variklis negali pasiekti savo taikinio per nustatytą laiko limitą.\n\n19\n00:00:47.230 --> 00:00:49.420\nNustatykite letenos variklį.\n\n20\n00:00:49.420 --> 00:00:52.270\nIr delsą dviem sekundėms.\n\n21\n00:00:52.270 --> 00:00:55.420\nIš parankinės naudokite dar vieną \"suktis kiek\" bloką.\n\n22\n00:00:55.420 --> 00:00:56.823\nPrijunkite prie blokų krūvos.\n\n23\n00:00:57.790 --> 00:00:59.203\nPasirinkite letenos variklį.\n\n24\n00:01:00.410 --> 00:01:01.243\nUždaryti.\n\n25\n00:01:02.930 --> 00:01:04.283\n30 Laipsnių.\n\n26\n00:01:07.300 --> 00:01:10.233\nJūsų letenos variklis dabar gali sugriebti objektą.\n\n","lv":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>V5 ClawBot spīles pārvietošana</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nir viegli paveicama ar V5 bloku projektu.\n\n3\n00:00:06.000 --> 00:00:08.440\nKad esiet motora ierīces pievienojis,\n\n4\n00:00:08.440 --> 00:00:12.410\nparādīsies jauna bloku kategorija ar nosaukumu “Motion”.\n\n5\n00:00:12.410 --> 00:00:15.780\nAtlasiet rīklodziņā bloku “Spin For”.\n\n6\n00:00:15.780 --> 00:00:18.610\nPievienojiet to pie bloka “When Started” (sākot).\n\n7\n00:00:18.610 --> 00:00:20.033\nAtlasiet spīles motoru.\n\n8\n00:00:21.470 --> 00:00:22.303\nAtvērt.\n\n9\n00:00:23.220 --> 00:00:24.603\n60 grādi.\n\n10\n00:00:26.350 --> 00:00:27.660\nTas atvērs spīles motoru par\n\n11\n00:00:27.660 --> 00:00:29.943\n60 grādiem no pašreizējā stāvokļa.\n\n12\n00:00:31.090 --> 00:00:33.570\nSpīles motoru var arī pārvietot, izmantojot pagriezienus,\n\n13\n00:00:33.570 --> 00:00:35.460\nnevis norādot grādus.\n\n14\n00:00:35.460 --> 00:00:37.040\nSpīles motora lietošanas padoms —\n\n15\n00:00:37.040 --> 00:00:39.810\nizmantojiet bloku “Set Motor Timeout”.\n\n16\n00:00:39.810 --> 00:00:41.590\nŠis bloks nosaka laika ierobežojumu,\n\n17\n00:00:41.590 --> 00:00:43.440\nlai kombinētais bloks varētu turpināt darbību,\n\n18\n00:00:43.440 --> 00:00:47.230\nja motors nevar sasniegt savu mērķi noteiktā laikā.\n\n19\n00:00:47.230 --> 00:00:49.420\nUzstādiet motoru pie spīles motoru\n\n20\n00:00:49.420 --> 00:00:52.270\nun taimautu līdz divām sekundēm.\n\n21\n00:00:52.270 --> 00:00:55.420\nAtlasiet rīklodziņā vēl vienu bloku “Spin Forward”.\n\n22\n00:00:55.420 --> 00:00:56.823\nSavienojiet to ar kombinētajiem blokiem.\n\n23\n00:00:57.790 --> 00:00:59.203\nAtlasiet spīles motoru.\n\n24\n00:01:00.410 --> 00:01:01.243\nAizvērt.\n\n25\n00:01:02.930 --> 00:01:04.283\n30 grādi.\n\n26\n00:01:07.300 --> 00:01:10.233\nSpīles motors tagad ir gatavs sagrābt kādu priekšmetu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor> Het bewegen van de klauw van een V5 Klauwbot </v>\n\n2\n00:00:02.710 --> 00:00:06.000\nis eenvoudig met een V5 blokkenproject.\n\n3\n00:00:06.000 --> 00:00:08.440\nZodra u motorapparaten heeft toegevoegd,\n\n4\n00:00:08.440 --> 00:00:12.410\nverschijnt er een nieuwe categorie blokken met de naam Beweging.\n\n5\n00:00:12.410 --> 00:00:15.780\nSelecteer de draai voor blok uit de toolbox.\n\n6\n00:00:15.780 --> 00:00:18.610\nSluit het aan bij het Wanneer gestart blok.\n\n7\n00:00:18.610 --> 00:00:20.033\nSelecteer de klauw motor.\n\n8\n00:00:21.470 --> 00:00:22.303\nOpenen.\n\n9\n00:00:23.220 --> 00:00:24.603\nVoor 60 graden.\n\n10\n00:00:26.350 --> 00:00:27.660\nDit opent de klauwmotor\n\n11\n00:00:27.660 --> 00:00:29.943\n60 graden vanaf zijn huidige positie.\n\n12\n00:00:31.090 --> 00:00:33.570\nU kunt de klauw motor ook verplaatsen met draaien,\n\n13\n00:00:33.570 --> 00:00:35.460\nin plaats van graden.\n\n14\n00:00:35.460 --> 00:00:37.040\nEen tip voor het gebruik van de klauw motor\n\n15\n00:00:37.040 --> 00:00:39.810\nis om de ingestelde motor time-out blok te gebruiken.\n\n16\n00:00:39.810 --> 00:00:41.590\nDit blok stelt een tijdslimiet in,\n\n17\n00:00:41.590 --> 00:00:43.440\nom de stapel door te laten gaan\n\n18\n00:00:43.440 --> 00:00:47.230\nals de motor zijn doel niet binnen de gestelde termijn kan bereiken.\n\n19\n00:00:47.230 --> 00:00:49.420\nStel de motor op de klauw motor in.\n\n20\n00:00:49.420 --> 00:00:52.270\nEn de time-out op twee seconden.\n\n21\n00:00:52.270 --> 00:00:55.420\nGebruik een andere draai voorwaarts blok vanuit de werkbalk.\n\n22\n00:00:55.420 --> 00:00:56.823\nSluit het aan op de stapel.\n\n23\n00:00:57.790 --> 00:00:59.203\nSelecteer de klauw motor.\n\n24\n00:01:00.410 --> 00:01:01.243\nSluiten.\n\n25\n00:01:02.930 --> 00:01:04.283\nVoor 30 graden.\n\n26\n00:01:07.300 --> 00:01:10.233\nUw klauw motor is nu klaar om een voorwerp te pakken.\n\n","pl":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Poruszanie kleszczami Clawbot V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\njest łatwy w ramach projektu V5 Blocks.\n\n3\n00:00:06.000 --> 00:00:08.440\nPo dodaniu urządzenia,\n\n4\n00:00:08.440 --> 00:00:12.410\npojawi się nowa kategoria bloków\no nazwie Ruch.\n\n5\n00:00:12.410 --> 00:00:15.780\nWybierz blok \"obróć o\"\nz przybornika.\n\n6\n00:00:15.780 --> 00:00:18.610\nNastępnie połącz go z\nblokiem \"po uruchomieniu\".\n\n7\n00:00:18.610 --> 00:00:20.033\nWybierz silnik kleszczy.\n\n8\n00:00:21.470 --> 00:00:22.303\nOtwórz.\n\n9\n00:00:23.220 --> 00:00:24.603\nDla 60 stopni.\n\n10\n00:00:26.350 --> 00:00:27.660\nTo otworzy kleszcze\n\n11\n00:00:27.660 --> 00:00:29.943\no 60 stopni od aktualnego położenia.\n\n12\n00:00:31.090 --> 00:00:33.570\nMożesz również poruszać\nkleszczami za pomocą skrętów,\n\n13\n00:00:33.570 --> 00:00:35.460\nzamiast stopniami.\n\n14\n00:00:35.460 --> 00:00:37.040\nWskazówka do użycia silnika kleszczy jest\n\n15\n00:00:37.040 --> 00:00:39.810\naby użyć bloku \"czas pracy silnika\".\n\n16\n00:00:39.810 --> 00:00:41.590\nTen blok ustawia limit czasowy,\n\n17\n00:00:41.590 --> 00:00:43.440\naby umożliwić kontynuowanie stosu,\n\n18\n00:00:43.440 --> 00:00:47.230\njeżeli kleszcze nie są w stanie osiągnąć swojego celu w określonym czasie.\n\n19\n00:00:47.230 --> 00:00:49.420\nUstaw silnik kleszczy.\n\n20\n00:00:49.420 --> 00:00:52.270\nZ limitem czasu na 2 sekundy.\n\n21\n00:00:52.270 --> 00:00:55.420\nWybierz inny blok \"obróć o\"\nz przybornika.\n\n22\n00:00:55.420 --> 00:00:56.823\nPodłącz go do stosu.\n\n23\n00:00:57.790 --> 00:00:59.203\nWybierz silnik kleszczy.\n\n24\n00:01:00.410 --> 00:01:01.243\nZamknij.\n\n25\n00:01:02.930 --> 00:01:04.283\nNa 30 stopni.\n\n26\n00:01:07.300 --> 00:01:10.233\nTwoje kleszcze są teraz\ngotowe do schwytania obiektu.\n\n","ru":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Движение схватом робота Clawbot</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nлегко реализуется в блоковом проекте.\n\n3\n00:00:06.000 --> 00:00:08.440\nПосле добавления приводов,\n\n4\n00:00:08.440 --> 00:00:12.410\nпоявится новый раздел блоков в инструментарии.\n\n5\n00:00:12.410 --> 00:00:15.780\nВыберите блок \"Вращение\" из списка.\n\n6\n00:00:15.780 --> 00:00:18.610\nСоедините его с блоком начала программы.\n\n7\n00:00:18.610 --> 00:00:20.033\nВыберите привод схвата.\n\n8\n00:00:21.470 --> 00:00:22.303\nОткрыть.\n\n9\n00:00:23.220 --> 00:00:24.603\nНа 60 градусов.\n\n10\n00:00:26.350 --> 00:00:27.660\nДанная команда откроет схват\n\n11\n00:00:27.660 --> 00:00:29.943\nна 60 градусов из текущего положения.\n\n12\n00:00:31.090 --> 00:00:33.570\nВы также можете открыть схват, используя обороты,\n\n13\n00:00:33.570 --> 00:00:35.460\nвместо градусов.\n\n14\n00:00:35.460 --> 00:00:37.040\nОдной из хитростей является использование\n\n15\n00:00:37.040 --> 00:00:39.810\nблока \"timeout\" для схвата.\n\n16\n00:00:39.810 --> 00:00:41.590\nЭтот блок устанавливает ограничение времени работы\n\n17\n00:00:41.590 --> 00:00:43.440\nи позволяет продолжить работу,\n\n18\n00:00:43.440 --> 00:00:47.230\nесли привод не достиг своего конечного положения.\n\n19\n00:00:47.230 --> 00:00:49.420\nУстановите привод на Claw Motor.\n\n20\n00:00:49.420 --> 00:00:52.270\nИ время таймаута на две секунды.\n\n21\n00:00:52.270 --> 00:00:55.420\nИспользуйте другой блок вращения из инструментария.\n\n22\n00:00:55.420 --> 00:00:56.823\nСоедините его со стеком.\n\n23\n00:00:57.790 --> 00:00:59.203\nВыберите привод схвата.\n\n24\n00:01:00.410 --> 00:01:01.243\nЗакрыть.\n\n25\n00:01:02.930 --> 00:01:04.283\nНа 30 градусов.\n\n26\n00:01:07.300 --> 00:01:10.233\nВаш привод готов к захвату объектов.\n\n","th":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor> การย้ายกรงเล็บของ V5 ClawBot </v>\n\n2\n00:00:02.710 --> 00:00:06.000\nนั้นเป็นเรื่องง่ายภายในโครงการ V5 Blocks\n\n3\n00:00:06.000 --> 00:00:08.440\nเมื่อคุณเพิ่มอุปกรณ์มอเตอร์แล้ว\n\n4\n00:00:08.440 --> 00:00:12.410\nจะมีหมวดหมู่ใหม่ของบล็อกชื่อ Motion ปรากฏขึ้น\n\n5\n00:00:12.410 --> 00:00:15.780\nในขั้นแรกให้เลือก Spin For block จากกล่องเครื่องมือ\n\n6\n00:00:15.780 --> 00:00:18.610\nจากนั้นเชื่อมต่อกับ When Started บล็อก\n\n7\n00:00:18.610 --> 00:00:20.033\nเลือกมอเตอร์กรงเล็บ\n\n8\n00:00:21.470 --> 00:00:22.303\nเปิด\n\n9\n00:00:23.220 --> 00:00:24.603\nขนาด 60 องศา\n\n10\n00:00:26.350 --> 00:00:27.660\nซึ่งจะเปิดมอเตอร์กรงเล็บ\n\n11\n00:00:27.660 --> 00:00:29.943\nไปขนาด 60 องศาจากตำแหน่งปัจจุบัน\n\n12\n00:00:31.090 --> 00:00:33.570\nคุณยังสามารถเคลื่อนมอเตอร์กรงเล็บโดยใช้รอบ\n\n13\n00:00:33.570 --> 00:00:35.460\nนอกเหนือจากองศา\n\n14\n00:00:35.460 --> 00:00:37.040\nเคล็ดลับสำหรับการใช้มอเตอร์กรงเล็บ\n\n15\n00:00:37.040 --> 00:00:39.810\nคือการใช้บล็อกการหมดเวลาของมอเตอร์ที่ตั้งไว้\n\n16\n00:00:39.810 --> 00:00:41.590\nบล็อกนี้กำหนดระยะเวลา\n\n17\n00:00:41.590 --> 00:00:43.440\nเพื่อให้ stack ทำงาน\n\n18\n00:00:43.440 --> 00:00:47.230\nหากมอเตอร์ไม่สามารถไปถึงเป้าหมายได้ภายในเวลาที่กำหนด\n\n19\n00:00:47.230 --> 00:00:49.420\nตั้งมอเตอร์เป็นมอเตอร์กรงเล็บ\n\n20\n00:00:49.420 --> 00:00:52.270\nและหมดเวลาเป็นสองวินาที\n\n21\n00:00:52.270 --> 00:00:55.420\nใช้บล็อก Spin Forward อื่นๆ จากกล่องเครื่องมือ\n\n22\n00:00:55.420 --> 00:00:56.823\nเพื่อเชื่อมต่อกับสแต็ก\n\n23\n00:00:57.790 --> 00:00:59.203\nเลือกมอเตอร์กรงเล็บ\n\n24\n00:01:00.410 --> 00:01:01.243\nปิด\n\n25\n00:01:02.930 --> 00:01:04.283\nขนาด 30 องศา\n\n26\n00:01:07.300 --> 00:01:10.233\nตอนนี้มอเตอร์กรงเล็บของคุณพร้อมที่จะคว้าวัตถุแล้ว\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Рухи клешнею клешнебота V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\nлегко запрограмувати у блоковому проєкті V5.\n\n3\n00:00:06.000 --> 00:00:08.440\nКоли ви додасте мотор,\n\n4\n00:00:08.440 --> 00:00:12.410\nз'явиться категорія блоків із назвою \"Рух\".\n\n5\n00:00:12.410 --> 00:00:15.780\nВиберіть блок обертання з набору блоків.\n\n6\n00:00:15.780 --> 00:00:18.610\nПриєднайте його до блоку \"коли почнемо\".\n\n7\n00:00:18.610 --> 00:00:20.033\nВиберіть мотор клешні.\n\n8\n00:00:21.470 --> 00:00:22.303\nВідкрити.\n\n9\n00:00:23.220 --> 00:00:24.603\nНа 60 градусів.\n\n10\n00:00:26.350 --> 00:00:27.660\nЦе відкриє клешню\n\n11\n00:00:27.660 --> 00:00:29.943\nна 60 градусів відносно її поточної позиції.\n\n12\n00:00:31.090 --> 00:00:33.570\nВи також можете керувати \nмотором клешні обертами,\n\n13\n00:00:33.570 --> 00:00:35.460\nзамість градусів.\n\n14\n00:00:35.460 --> 00:00:37.040\nПідказка для використання мотора клешні\n\n15\n00:00:37.040 --> 00:00:39.810\nце додати блок обмеження часу руху мотора.\n\n16\n00:00:39.810 --> 00:00:41.590\nЦей блок встановлює часовий ліміт\n\n17\n00:00:41.590 --> 00:00:43.440\nі дає змогу програмі продовжити,\n\n18\n00:00:43.440 --> 00:00:47.230\nякщо мотор не зможе повністю прокрутитися за встановлений час.\n\n19\n00:00:47.230 --> 00:00:49.420\nВстановіть блок руху для мотора клешні.\n\n20\n00:00:49.420 --> 00:00:52.270\nІ обмежте час руху на дві секунди.\n\n21\n00:00:52.270 --> 00:00:55.420\nВикористайте ще один блок для обертання.\n\n22\n00:00:55.420 --> 00:00:56.823\nПід'єднайте його до стека.\n\n23\n00:00:57.790 --> 00:00:59.203\nВиберіть мотор клешні.\n\n24\n00:01:00.410 --> 00:01:01.243\nЗакрити.\n\n25\n00:01:02.930 --> 00:01:04.283\nНа 30 градусів.\n\n26\n00:01:07.300 --> 00:01:10.233\nТепер ваш мотор клешні готовий хапати об'єкти.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>Di chuyển vuốt của ClawBot V5</v>\n\n2\n00:00:02.710 --> 00:00:06.000\ndễ dàng trong dự án Khối V5.\n\n3\n00:00:06.000 --> 00:00:08.440\nSau khi bạn đã thêm các thiết bị của động cơ,\n\n4\n00:00:08.440 --> 00:00:12.410\nmột danh mục khối mới có tên Chuyển động sẽ xuất hiện.\n\n5\n00:00:12.410 --> 00:00:15.780\nChọn khối Spin For từ hộp công cụ.\n\n6\n00:00:15.780 --> 00:00:18.610\nKết nối nó với khối When Started.\n\n7\n00:00:18.610 --> 00:00:20.033\nChọn động cơ vuốt.\n\n8\n00:00:21.470 --> 00:00:22.303\nMở.\n\n9\n00:00:23.220 --> 00:00:24.603\nĐối với 60 độ.\n\n10\n00:00:26.350 --> 00:00:27.660\nĐiều này mở động cơ vuốt\n\n11\n00:00:27.660 --> 00:00:29.943\n60 độ so với vị trí hiện tại của nó.\n\n12\n00:00:31.090 --> 00:00:33.570\nBạn cũng có thể di chuyển động cơ vuốt bằng cách sử dụng các lượt,\n\n13\n00:00:33.570 --> 00:00:35.460\nthay vì độ.\n\n14\n00:00:35.460 --> 00:00:37.040\nMẹo sử dụng mô tơ vuốt\n\n15\n00:00:37.040 --> 00:00:39.810\nlà sử dụng khối thời gian chờ động cơ đã đặt.\n\n16\n00:00:39.810 --> 00:00:41.590\nKhối này đặt giới hạn thời gian,\n\n17\n00:00:41.590 --> 00:00:43.440\nđể cho phép ngăn xếp tiếp tục,\n\n18\n00:00:43.440 --> 00:00:47.230\nnếu động cơ không thể đạt được mục tiêu của nó trong thời hạn.\n\n19\n00:00:47.230 --> 00:00:49.420\nĐặt động cơ thành động cơ vuốt.\n\n20\n00:00:49.420 --> 00:00:52.270\nVà thời gian chờ đến hai giây.\n\n21\n00:00:52.270 --> 00:00:55.420\nSử dụng một khối Spin Forward khác từ hộp công cụ.\n\n22\n00:00:55.420 --> 00:00:56.823\nKết nối nó với ngăn xếp.\n\n23\n00:00:57.790 --> 00:00:59.203\nChọn động cơ vuốt.\n\n24\n00:01:00.410 --> 00:01:01.243\nĐã đóng cửa.\n\n25\n00:01:02.930 --> 00:01:04.283\nĐối với 30 độ.\n\n26\n00:01:07.300 --> 00:01:10.233\nĐộng cơ vuốt của bạn bây giờ đã sẵn sàng để lấy một vật thể.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\ncrwdns96416:0crwdne96416:0\n\n2\n00:00:02.710 --> 00:00:06.000\ncrwdns96418:0crwdne96418:0\n\n3\n00:00:06.000 --> 00:00:08.440\ncrwdns96420:0crwdne96420:0\n\n4\n00:00:08.440 --> 00:00:12.410\ncrwdns96422:0crwdne96422:0\n\n5\n00:00:12.410 --> 00:00:15.780\ncrwdns96424:0crwdne96424:0\n\n6\n00:00:15.780 --> 00:00:18.610\ncrwdns96426:0crwdne96426:0\n\n7\n00:00:18.610 --> 00:00:20.033\ncrwdns96428:0crwdne96428:0\n\n8\n00:00:21.470 --> 00:00:22.303\ncrwdns96430:0crwdne96430:0\n\n9\n00:00:23.220 --> 00:00:24.603\ncrwdns96432:0crwdne96432:0\n\n10\n00:00:26.350 --> 00:00:27.660\ncrwdns96434:0crwdne96434:0\n\n11\n00:00:27.660 --> 00:00:29.943\ncrwdns96436:0crwdne96436:0\n\n12\n00:00:31.090 --> 00:00:33.570\ncrwdns96438:0crwdne96438:0\n\n13\n00:00:33.570 --> 00:00:35.460\ncrwdns96440:0crwdne96440:0\n\n14\n00:00:35.460 --> 00:00:37.040\ncrwdns96442:0crwdne96442:0\n\n15\n00:00:37.040 --> 00:00:39.810\ncrwdns96444:0crwdne96444:0\n\n16\n00:00:39.810 --> 00:00:41.590\ncrwdns96446:0crwdne96446:0\n\n17\n00:00:41.590 --> 00:00:43.440\ncrwdns96448:0crwdne96448:0\n\n18\n00:00:43.440 --> 00:00:47.230\ncrwdns96450:0crwdne96450:0\n\n19\n00:00:47.230 --> 00:00:49.420\ncrwdns96452:0crwdne96452:0\n\n20\n00:00:49.420 --> 00:00:52.270\ncrwdns96454:0crwdne96454:0\n\n21\n00:00:52.270 --> 00:00:55.420\ncrwdns96456:0crwdne96456:0\n\n22\n00:00:55.420 --> 00:00:56.823\ncrwdns96458:0crwdne96458:0\n\n23\n00:00:57.790 --> 00:00:59.203\ncrwdns96460:0crwdne96460:0\n\n24\n00:01:00.410 --> 00:01:01.243\ncrwdns96462:0crwdne96462:0\n\n25\n00:01:02.930 --> 00:01:04.283\ncrwdns96464:0crwdne96464:0\n\n26\n00:01:07.300 --> 00:01:10.233\ncrwdns96466:0crwdne96466:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.550 --> 00:00:02.710\n<v Instructor>通过VEXcode V5移动一台V5钳爪机器人</v>\n\n2\n00:00:02.710 --> 00:00:06.000\n的机械臂很容易。\n\n3\n00:00:06.000 --> 00:00:08.440\n一旦您已经添加电机设备后，\n\n4\n00:00:08.440 --> 00:00:12.410\n一个叫“运动”的指令块新类别就会出现。\n\n5\n00:00:12.410 --> 00:00:15.780\n从工具栏选择“转动”指令块。\n\n6\n00:00:15.780 --> 00:00:18.610\n将其连接到“当开始”指令块。\n\n7\n00:00:18.610 --> 00:00:20.033\n选择机械臂电机。\n\n8\n00:00:21.470 --> 00:00:22.303\n打开。\n\n9\n00:00:23.220 --> 00:00:24.603\n60度。\n\n10\n00:00:26.350 --> 00:00:27.660\n这就让钳爪电机\n\n11\n00:00:27.660 --> 00:00:29.943\n从当前位置转动60度。\n\n12\n00:00:31.090 --> 00:00:33.570\n您也可以使用转数来移动钳爪电机,\n\n13\n00:00:33.570 --> 00:00:35.460\n转动机械臂电机。\n\n14\n00:00:35.460 --> 00:00:37.040\n一个使用钳爪电机的提示\n\n15\n00:00:37.040 --> 00:00:39.810\n是使用设定电机超时指令块。\n\n16\n00:00:39.810 --> 00:00:41.590\n该指令块设定一个限制时间，\n\n17\n00:00:41.590 --> 00:00:43.440\n来允许指令段继续，\n\n18\n00:00:43.440 --> 00:00:47.230\n如果电机不能在限制时间内达到目标值。\n\n19\n00:00:47.230 --> 00:00:49.420\n设定电机为钳爪电机，\n\n20\n00:00:49.420 --> 00:00:52.270\n并且超时时间为2秒。\n\n21\n00:00:52.270 --> 00:00:55.420\n从工具栏选择另一个“正转”指令块。\n\n22\n00:00:55.420 --> 00:00:56.823\n把它连接到指令段。\n\n23\n00:00:57.790 --> 00:00:59.203\n选择机械臂电机。\n\n24\n00:01:00.410 --> 00:01:01.243\n关闭。\n\n25\n00:01:02.930 --> 00:01:04.283\n30度。\n\n26\n00:01:07.300 --> 00:01:10.233\n您的钳爪电机现在已准备好抓取物体了。\n\n"}},{"thumb":"V5_Tutorial_downloadAndRunAProject.jpg","mov":"V5_Blocks_DownloadRunProject_V2","description":"Download and Run a Project","filter":"","placeholder":false,"vimeo":"475899324","proglang":["blocks","python","cpp"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Downloading and running</v>\n\n2\n00:00:01.330 --> 00:00:04.110\na V5 Blocks project is easy.\n\n3\n00:00:04.110 --> 00:00:05.993\nFirst, save the project,\n\n4\n00:00:07.340 --> 00:00:08.943\nand choose a project slot.\n\n5\n00:00:10.610 --> 00:00:14.050\nNext, connect the USB cable from your computer\n\n6\n00:00:14.050 --> 00:00:15.873\nto the V5 robot brain.\n\n7\n00:00:17.260 --> 00:00:22.010\nThen, press the home button until the V5 brain turns on.\n\n8\n00:00:22.010 --> 00:00:24.410\nWhen the V5 brain has successfully connected\n\n9\n00:00:24.410 --> 00:00:25.600\nto your computer,\n\n10\n00:00:25.600 --> 00:00:28.623\nthe brain icon in the toolbar will turn green.\n\n11\n00:00:29.930 --> 00:00:32.880\nFinally, select download to send the project\n\n12\n00:00:32.880 --> 00:00:35.263\nto the V5 brain selected slot.\n\n13\n00:00:36.230 --> 00:00:38.040\nYou can now select run\n\n14\n00:00:38.040 --> 00:00:40.440\nto start the project from your computer\n\n15\n00:00:40.440 --> 00:00:43.193\nor run the project directly from the brain.\n\n","ar":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>تحميل وتشغيل</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nمشروع برمجة V5 سهل.\n\n3\n00:00:04.110 --> 00:00:05.993\nأولا، سجل المشروع،\n\n4\n00:00:07.340 --> 00:00:08.943\nواختر فتحة للمشروع.\n\n5\n00:00:10.610 --> 00:00:14.050\nثم، قم بتوصيل سلك التوصيل USB الصغير من جهاز الحاسوب الخاص بك\n\n6\n00:00:14.050 --> 00:00:15.873\nإلى عقل الروبوت V5.\n\n7\n00:00:17.260 --> 00:00:22.010\nثم اضغط على زر المنزل حتى يعمل دماغ V5.\n\n8\n00:00:22.010 --> 00:00:24.410\nعندما يرتبط عقل V5 بنجاح\n\n9\n00:00:24.410 --> 00:00:25.600\nإلى الحاسوب،\n\n10\n00:00:25.600 --> 00:00:28.623\nرمز العقل في قائمة الأدوات سيصبح أخضر.\n\n11\n00:00:29.930 --> 00:00:32.880\nأخيرا ، إختر التحميل لإرسال المشروع\n\n12\n00:00:32.880 --> 00:00:35.263\nإلى خانة عقل V5 المختارة.\n\n13\n00:00:36.230 --> 00:00:38.040\nيمكنك الآن اختيار تشغيل\n\n14\n00:00:38.040 --> 00:00:40.440\nلبدء المشروع من حاسوبك\n\n15\n00:00:40.440 --> 00:00:43.193\nأو تشغيل المشروع مباشرة من العقل.\n\n","cs":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Stahování a spouštění</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nV5 blokového projektu je snadné.\n\n3\n00:00:04.110 --> 00:00:05.993\nNejprve projekt ulož\n\n4\n00:00:07.340 --> 00:00:08.943\na vyber si projektový slot.\n\n5\n00:00:10.610 --> 00:00:14.050\nPotom připoj USB kabel ze tvého počítače\n\n6\n00:00:14.050 --> 00:00:15.873\nk robotovu V5 Mozku.\n\n7\n00:00:17.260 --> 00:00:22.010\nPotom stiskni tlačítko Domů, dokud se nezapne V5 Mozek.\n\n8\n00:00:22.010 --> 00:00:24.410\nKdyž je V5 mozek úspěšně připojen\n\n9\n00:00:24.410 --> 00:00:25.600\nke tvému počítači,\n\n10\n00:00:25.600 --> 00:00:28.623\nikonka mozku na panelu nástrojů zezelená.\n\n11\n00:00:29.930 --> 00:00:32.880\nNakonec vyber Stáhnout pro odeslání projektu\n\n12\n00:00:32.880 --> 00:00:35.263\ndo vybraného slotu V5 mozku.\n\n13\n00:00:36.230 --> 00:00:38.040\nNyní můžeš vybrat Spustit\n\n14\n00:00:38.040 --> 00:00:40.440\npro spuštění projektu ze tvého počítače,\n\n15\n00:00:40.440 --> 00:00:43.193\nnebo spusť projekt přímo z mozku.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Descargando y ejecutando</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nun proyecto de V5 Blocks (bloques) es fácil.\n\n3\n00:00:04.110 --> 00:00:05.993\nPrimero, guarde el proyecto,\n\n4\n00:00:07.340 --> 00:00:08.943\ny elija una ranura de proyecto.\n\n5\n00:00:10.610 --> 00:00:14.050\nAhora, conecte el cable MicroUSB desde su computadora\n\n6\n00:00:14.050 --> 00:00:15.873\nal V5 Brain.\n\n7\n00:00:17.260 --> 00:00:22.010\nLuego, pulse el botón de inicio hasta que el V5 Brain se encienda.\n\n8\n00:00:22.010 --> 00:00:24.410\nCuando el V5 Brain se ha conectado con éxito\n\n9\n00:00:24.410 --> 00:00:25.600\na su computadora,\n\n10\n00:00:25.600 --> 00:00:28.623\nel icono del V5 Brain en la barra de herramientas se volverá verde.\n\n11\n00:00:29.930 --> 00:00:32.880\nSeleccione Descarga para enviar el proyecto\n\n12\n00:00:32.880 --> 00:00:35.263\na la ranura seleccionada del V5 Brain.\n\n13\n00:00:36.230 --> 00:00:38.040\nAhora puede seleccionar ejecutar\n\n14\n00:00:38.040 --> 00:00:40.440\npara iniciar el proyecto desde su computadora\n\n15\n00:00:40.440 --> 00:00:43.193\no ejecute el proyecto desde el Brain.\n\n","es":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Descargando y ejecutando</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nun proyecto de V5 Blocks (bloques) es fácil.\n\n3\n00:00:04.110 --> 00:00:05.993\nPrimero, guarde el proyecto,\n\n4\n00:00:07.340 --> 00:00:08.943\ny elija una ranura de proyecto.\n\n5\n00:00:10.610 --> 00:00:14.050\nAhora, conecte el cable MicroUSB desde su computadora\n\n6\n00:00:14.050 --> 00:00:15.873\nal V5 Brain.\n\n7\n00:00:17.260 --> 00:00:22.010\nLuego, pulse el botón de inicio hasta que el V5 Brain se encienda.\n\n8\n00:00:22.010 --> 00:00:24.410\nCuando el V5 Brain se ha conectado con éxito\n\n9\n00:00:24.410 --> 00:00:25.600\na su computadora,\n\n10\n00:00:25.600 --> 00:00:28.623\nel icono del V5 Brain en la barra de herramientas se volverá verde.\n\n11\n00:00:29.930 --> 00:00:32.880\nSeleccione Descarga para enviar el proyecto\n\n12\n00:00:32.880 --> 00:00:35.263\na la ranura seleccionada del V5 Brain.\n\n13\n00:00:36.230 --> 00:00:38.040\nAhora puede seleccionar ejecutar\n\n14\n00:00:38.040 --> 00:00:40.440\npara iniciar el proyecto desde su computadora\n\n15\n00:00:40.440 --> 00:00:43.193\no ejecute el proyecto desde el Brain.\n\n","fi":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>V5 Blocks -ohjelman lataus ja ajaminen</v>\n\n2\n00:00:01.330 --> 00:00:04.110\non helppoa.\n\n3\n00:00:04.110 --> 00:00:05.993\nEnsiksi tallenna ohjelmasi\n\n4\n00:00:07.340 --> 00:00:08.943\nja valitse oikea muistipaikka 1-8 ohjelmalle robotissa.\n\n5\n00:00:10.610 --> 00:00:14.050\nLiitä USB -kaapeli tietokoneen\n\n6\n00:00:14.050 --> 00:00:15.873\nja V5 Aivojen välillä.\n\n7\n00:00:17.260 --> 00:00:22.010\nKäynnistä V5 robotti Käynnistys -painikkeesta.\n\n8\n00:00:22.010 --> 00:00:24.410\nKun yhteys V5 Aivoihin on kunnossa\n\n9\n00:00:24.410 --> 00:00:25.600\ntietokoneeseen\n\n10\n00:00:25.600 --> 00:00:28.623\nkun Aivot -kuvakkeen väri muuttuu vihreäksi.\n\n11\n00:00:29.930 --> 00:00:32.880\nValitse Lataa-painike lähettääksesi ohjelman\n\n12\n00:00:32.880 --> 00:00:35.263\nV5 robotin Aivoihin haluamaasi muistipaikkaan.\n\n13\n00:00:36.230 --> 00:00:38.040\nNyt voit valita Suorita ohjelma-painikkeen\n\n14\n00:00:38.040 --> 00:00:40.440\nkäynnistääksesi ohjelman tietokoneelta\n\n15\n00:00:40.440 --> 00:00:43.193\ntai voit suorittaa sen valitsemalla sen suoraan robotin aivoissa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Télécharger et exécuter</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nun projet V5 Blocs est facile.\n\n3\n00:00:04.110 --> 00:00:05.993\nTout d'abord, enregistrer le projet,\n\n4\n00:00:07.340 --> 00:00:08.943\net choisissez un emplacement de projet.\n\n5\n00:00:10.610 --> 00:00:14.050\nEnsuite, connectez le câble USB depuis votre ordinateur\n\n6\n00:00:14.050 --> 00:00:15.873\nvers le cerveau du robot V5.\n\n7\n00:00:17.260 --> 00:00:22.010\nEnsuite, appuyez sur le bouton d'accueil jusqu'à ce que le cerveau V5 s'allume.\n\n8\n00:00:22.010 --> 00:00:24.410\nQuand le cerveau V5 s'est connecté avec succès\n\n9\n00:00:24.410 --> 00:00:25.600\nà votre ordinateur,\n\n10\n00:00:25.600 --> 00:00:28.623\nl'icône Cerveau dans la barre d'outils devient verte.\n\n11\n00:00:29.930 --> 00:00:32.880\nEnfin, sélectionnez \"Télécharger\" pour envoyer le projet\n\n12\n00:00:32.880 --> 00:00:35.263\nà l'emplacement sélectionné du cerveau V5.\n\n13\n00:00:36.230 --> 00:00:38.040\nVous pouvez maintenant cliquer sur \"Démarrer\"\n\n14\n00:00:38.040 --> 00:00:40.440\npour démarrer le projet à partir de votre ordinateur\n\n15\n00:00:40.440 --> 00:00:43.193\nou exécutez le projet directement à partir du cerveau.\n\n","ko":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>V5 블록 프로젝트를 다운로드하여\n\n2\n00:00:01.330 --> 00:00:04.110\n실행하는 것은</v> 쉽습니다.\n\n3\n00:00:04.110 --> 00:00:05.993\n먼저 프로젝트를 저장하고\n\n4\n00:00:07.340 --> 00:00:08.943\n프로젝트 슬롯을 선택합니다.\n\n5\n00:00:10.610 --> 00:00:14.050\n그런 다음 컴퓨터의 USB 케이블을\n\n6\n00:00:14.050 --> 00:00:15.873\nV5 로봇 브레인에 연결합니다.\n\n7\n00:00:17.260 --> 00:00:22.010\n그리고 V5 브레인이 켜질 때까지 홈 버튼을 누르세요.\n\n8\n00:00:22.010 --> 00:00:24.410\nV5 브레인이 컴퓨터에 성공적으로\n\n9\n00:00:24.410 --> 00:00:25.600\n연결되면\n\n10\n00:00:25.600 --> 00:00:28.623\n도구 모음의 브레인 아이콘이 녹색으로 바뀝니다.\n\n11\n00:00:29.930 --> 00:00:32.880\n다운로드를 선택하여\n\n12\n00:00:32.880 --> 00:00:35.263\nV5 브레인에서 선택한 슬롯으로 프로젝트를 전송합니다.\n\n13\n00:00:36.230 --> 00:00:38.040\n이제 '실행'하여\n\n14\n00:00:38.040 --> 00:00:40.440\n컴퓨터에서 프로젝트를 시작하거나\n\n15\n00:00:40.440 --> 00:00:43.193\n브레인에서 직접 프로젝트를 실행합니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Lengva parsisiųsti ir paleisti</v>\n\n2\n00:00:01.330 --> 00:00:04.110\n\"V5 Blocks\" projektą.\n\n3\n00:00:04.110 --> 00:00:05.993\nPirmiausia, išsaugokite projektą\n\n4\n00:00:07.340 --> 00:00:08.943\nir pasirinkite jo vietą.\n\n5\n00:00:10.610 --> 00:00:14.050\nPo to, prijunkite USB laidą iš savo kompiuterio\n\n6\n00:00:14.050 --> 00:00:15.873\nį \"V5\" roboto smegenis.\n\n7\n00:00:17.260 --> 00:00:22.010\nPo to, spustelėkite mygtuką \"Pradžia\", kol įsijungia \"V5\" smegenys.\n\n8\n00:00:22.010 --> 00:00:24.410\nSėkmingai prie Jūsų kompiuterio prijungus\n\n9\n00:00:24.410 --> 00:00:25.600\n\"V5\" smegenis,\n\n10\n00:00:25.600 --> 00:00:28.623\nparankinėje esanti smegenų ikona šviečia žaliai.\n\n11\n00:00:29.930 --> 00:00:32.880\nPasirinkite parsisiųsti, kad nusiųstumėte savo projektą\n\n12\n00:00:32.880 --> 00:00:35.263\nį pasirinktą \"V5\" smegenų vietą.\n\n13\n00:00:36.230 --> 00:00:38.040\nDabar, galite pasirinkti \"Paleisti\",\n\n14\n00:00:38.040 --> 00:00:40.440\nkad iš savo kompiuterio paleistumėte projektą\n\n15\n00:00:40.440 --> 00:00:43.193\narba projektą paleistumėte tiesiogiai iš smegenų.\n\n","lv":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Lejupielādēt un palaist</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nV5 Blocks projektus ir vienkārši.\n\n3\n00:00:04.110 --> 00:00:05.993\nVispirms saglabājiet projektu\n\n4\n00:00:07.340 --> 00:00:08.943\nun izvēlieties projekta slotu.\n\n5\n00:00:10.610 --> 00:00:14.050\nPēc tam savienojiet mikro USB kabeli ar datoru\n\n6\n00:00:14.050 --> 00:00:15.873\nun V5 robota smadzenēm.\n\n7\n00:00:17.260 --> 00:00:22.010\nPēc tam nospiediet sākuma pogu, līdz ieslēdzas V5 smadzenes.\n\n8\n00:00:22.010 --> 00:00:24.410\nKad V5 smadzenes ir veiksmīgi savienotas\n\n9\n00:00:24.410 --> 00:00:25.600\npie datora,\n\n10\n00:00:25.600 --> 00:00:28.623\nrīkjoslā ikona “Brain” uzrādīsies zaļa.\n\n11\n00:00:29.930 --> 00:00:32.880\nTad atlasiet lejupielādi, lai nosūtītu projektu\n\n12\n00:00:32.880 --> 00:00:35.263\nuz V5 smadzeņu izvēlēto slotu.\n\n13\n00:00:36.230 --> 00:00:38.040\nTagad varat atlasīt “Run”,\n\n14\n00:00:38.040 --> 00:00:40.440\nlai palaistu projektu uz datora\n\n15\n00:00:40.440 --> 00:00:43.193\nvai palaistu projektu, izmantojot smadzenes.\n\n","nl":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Downloaden en uitvoeren</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nvan een V5 Blokken project is makkelijk.\n\n3\n00:00:04.110 --> 00:00:05.993\nSla het project eerst op,\n\n4\n00:00:07.340 --> 00:00:08.943\nen kies een project sleuf.\n\n5\n00:00:10.610 --> 00:00:14.050\nSluit daarna de micro-USB-kabel van uw computer aan\n\n6\n00:00:14.050 --> 00:00:15.873\nde V5 robot brein.\n\n7\n00:00:17.260 --> 00:00:22.010\nDruk vervolgens op de naar huis knop totdat het V5 brein wordt ingeschakeld.\n\n8\n00:00:22.010 --> 00:00:24.410\nWanneer het V5 brein succesvol is aangesloten\n\n9\n00:00:24.410 --> 00:00:25.600\naan uw computer,\n\n10\n00:00:25.600 --> 00:00:28.623\nhet brein icoon in de werkbalk zal groen worden.\n\n11\n00:00:29.930 --> 00:00:32.880\nSelecteer tot slot download om het project te verzenden\n\n12\n00:00:32.880 --> 00:00:35.263\nnaar het geselecteerde sleuf van V5.\n\n13\n00:00:36.230 --> 00:00:38.040\nU kunt nu uitvoeren selecteren\n\n14\n00:00:38.040 --> 00:00:40.440\nom het project vanaf uw computer te starten\n\n15\n00:00:40.440 --> 00:00:43.193\nof het project rechtstreeks vanuit het brein uitvoeren.\n\n","pl":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Pobieranie i uruchamianie</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nprojektu V5 jest proste.\n\n3\n00:00:04.110 --> 00:00:05.993\nNajpierw zapisz projekt,\n\n4\n00:00:07.340 --> 00:00:08.943\ni wybierz miejsce projektu.\n\n5\n00:00:10.610 --> 00:00:14.050\nNastępnie podłącz kabel USB ze swojego komputera\n\n6\n00:00:14.050 --> 00:00:15.873\ndo mózgu robota V5.\n\n7\n00:00:17.260 --> 00:00:22.010\nNastępnie wcisnąć przycisk Home aż do włączenia mózgu V5.\n\n8\n00:00:22.010 --> 00:00:24.410\nKiedy mózg V5 pomyślnie się połączył\n\n9\n00:00:24.410 --> 00:00:25.600\nz twoim komputerem\n\n10\n00:00:25.600 --> 00:00:28.623\nikona Brain w pasku narzędzi staje się zielona.\n\n11\n00:00:29.930 --> 00:00:32.880\nWybierz Pobierz aby wysłać projekt\n\n12\n00:00:32.880 --> 00:00:35.263\ndo wybranego wejścia mózgu.\n\n13\n00:00:36.230 --> 00:00:38.040\nMożesz teraz wybrać uruchomienie\n\n14\n00:00:38.040 --> 00:00:40.440\naby uruchomić projekt z komputera\n\n15\n00:00:40.440 --> 00:00:43.193\nlub uruchom projekt z mózgu.\n\n","ru":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Загрузка и запуск</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nблокового проекта V5 проста.\n\n3\n00:00:04.110 --> 00:00:05.993\nДля начала, сохраните проект\n\n4\n00:00:07.340 --> 00:00:08.943\nи выберите слот проекта.\n\n5\n00:00:10.610 --> 00:00:14.050\nДалее, подсоедините USB кабель от ПК\n\n6\n00:00:14.050 --> 00:00:15.873\nк контроллеру.\n\n7\n00:00:17.260 --> 00:00:22.010\nЗатем, нажмите кнопку включения на контроллере.\n\n8\n00:00:22.010 --> 00:00:24.410\nКогда контроллер будет успешно подключён\n\n9\n00:00:24.410 --> 00:00:25.600\nк ПК,\n\n10\n00:00:25.600 --> 00:00:28.623\nиконка контроллера на панели загорится зелёным.\n\n11\n00:00:29.930 --> 00:00:32.880\nНаконец, нажмите кнопку загрузки для отправки\n\n12\n00:00:32.880 --> 00:00:35.263\nпроекта на контроллер.\n\n13\n00:00:36.230 --> 00:00:38.040\nВы можете нажать кнопку \"Запуска\"\n\n14\n00:00:38.040 --> 00:00:40.440\nдля запуска проекта с ПК\n\n15\n00:00:40.440 --> 00:00:43.193\nили запустить проект с контроллера.\n\n","th":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor> กำลังดาวน์โหลดและเรียกใช้ </v>\n\n2\n00:00:01.330 --> 00:00:04.110\nโปรเจ็ค V5 Blocks เป็นเรื่องง่าย\n\n3\n00:00:04.110 --> 00:00:05.993\nขั้นแรกให้บันทึกโปรเจ็ค\n\n4\n00:00:07.340 --> 00:00:08.943\nและเลือก slot โปรเจ็ค\n\n5\n00:00:10.610 --> 00:00:14.050\nขั้นแรกให้เชื่อมต่อสายไมโคร USB จากคอมพิวเตอร์ของคุณ\n\n6\n00:00:14.050 --> 00:00:15.873\nกับสมองกลหุ่นยนต์ V5 Brain\n\n7\n00:00:17.260 --> 00:00:22.010\nจากนั้นกดปุ่มโฮมจนกว่า V5 brain จะเปิดขึ้น\n\n8\n00:00:22.010 --> 00:00:24.410\nเมื่อเชื่อมต่อสมองกล V5\n\n9\n00:00:24.410 --> 00:00:25.600\nกับเครื่องคอมพิวเตอร์ของคุณสำเร็จแล้ว\n\n10\n00:00:25.600 --> 00:00:28.623\nbrain icon ในแถบเครื่องมือจะเปลี่ยนเป็นสีเขียว\n\n11\n00:00:29.930 --> 00:00:32.880\nสุดท้ายเลือกดาวน์โหลดเพื่อดาว์โหลดโปรเจ็ค\n\n12\n00:00:32.880 --> 00:00:35.263\nไปยัง V5 brain ของ slot ที่ถูกเลือกไว้\n\n13\n00:00:36.230 --> 00:00:38.040\nตอนนี้คุณสามารถเลือก run\n\n14\n00:00:38.040 --> 00:00:40.440\nเพื่อเริ่มโปรเจ็คจากคอมพิวเตอรของคุณ\n\n15\n00:00:40.440 --> 00:00:43.193\nหรือดำเนินโปรเจ็คได้โดยตรงจากสมองกล\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Завантаження та запуск</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nблокового V5 проєкту легко.\n\n3\n00:00:04.110 --> 00:00:05.993\nСпершу, збережіть проєкт\n\n4\n00:00:07.340 --> 00:00:08.943\nі виберіть слот проєкту.\n\n5\n00:00:10.610 --> 00:00:14.050\nПотім приєднайте USB кабель від комп'ютера\n\n6\n00:00:14.050 --> 00:00:15.873\nдо V5 Brain робота.\n\n7\n00:00:17.260 --> 00:00:22.010\nДалі, тисніть кнопку \"Додому\", поки V5 Brain не увімкнеться.\n\n8\n00:00:22.010 --> 00:00:24.410\nКоли V5 Brain під'єднається\n\n9\n00:00:24.410 --> 00:00:25.600\nдо вашого комп'ютера,\n\n10\n00:00:25.600 --> 00:00:28.623\nпозначка Brain на панелі інструментів стане зеленою.\n\n11\n00:00:29.930 --> 00:00:32.880\nНасамкінець, виберіть \"Завантажити\", щоб надіслати проєкт\n\n12\n00:00:32.880 --> 00:00:35.263\nдо вибраного слота V5 Brain.\n\n13\n00:00:36.230 --> 00:00:38.040\nТепер ви можете натиснути \"Запуск\",\n\n14\n00:00:38.040 --> 00:00:40.440\nщоб запустити проєкт із комп'ютера,\n\n15\n00:00:40.440 --> 00:00:43.193\nабо запустіть проєкт із Brain.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>Tải xuống và chạy</v>\n\n2\n00:00:01.330 --> 00:00:04.110\nmột dự án Khối V5 thật dễ dàng.\n\n3\n00:00:04.110 --> 00:00:05.993\nĐầu tiên, hãy lưu dự án,\n\n4\n00:00:07.340 --> 00:00:08.943\nvà chọn một vị trí dự án.\n\n5\n00:00:10.610 --> 00:00:14.050\nTiếp theo, kết nối cáp USB từ máy tính của bạn\n\n6\n00:00:14.050 --> 00:00:15.873\ntới bộ não robot V5.\n\n7\n00:00:17.260 --> 00:00:22.010\nSau đó, nhấn nút home cho đến khi não V5 bật.\n\n8\n00:00:22.010 --> 00:00:24.410\nKhi não V5 đã kết nối thành công\n\n9\n00:00:24.410 --> 00:00:25.600\nđến máy tính của bạn,\n\n10\n00:00:25.600 --> 00:00:28.623\nbiểu tượng bộ não trên thanh công cụ sẽ chuyển sang màu xanh lục.\n\n11\n00:00:29.930 --> 00:00:32.880\nCuối cùng, chọn tải xuống để gửi dự án\n\n12\n00:00:32.880 --> 00:00:35.263\nđến khe đã chọn của bộ não V5.\n\n13\n00:00:36.230 --> 00:00:38.040\nBây giờ bạn có thể chọn chạy\n\n14\n00:00:38.040 --> 00:00:40.440\nđể bắt đầu dự án từ máy tính của bạn\n\n15\n00:00:40.440 --> 00:00:43.193\nhoặc chạy dự án trực tiếp từ bộ não.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\ncrwdns96016:0crwdne96016:0\n\n2\n00:00:01.330 --> 00:00:04.110\ncrwdns96018:0crwdne96018:0\n\n3\n00:00:04.110 --> 00:00:05.993\ncrwdns96020:0crwdne96020:0\n\n4\n00:00:07.340 --> 00:00:08.943\ncrwdns96022:0crwdne96022:0\n\n5\n00:00:10.610 --> 00:00:14.050\ncrwdns96024:0crwdne96024:0\n\n6\n00:00:14.050 --> 00:00:15.873\ncrwdns96026:0crwdne96026:0\n\n7\n00:00:17.260 --> 00:00:22.010\ncrwdns96028:0crwdne96028:0\n\n8\n00:00:22.010 --> 00:00:24.410\ncrwdns96030:0crwdne96030:0\n\n9\n00:00:24.410 --> 00:00:25.600\ncrwdns96032:0crwdne96032:0\n\n10\n00:00:25.600 --> 00:00:28.623\ncrwdns96034:0crwdne96034:0\n\n11\n00:00:29.930 --> 00:00:32.880\ncrwdns96036:0crwdne96036:0\n\n12\n00:00:32.880 --> 00:00:35.263\ncrwdns96038:0crwdne96038:0\n\n13\n00:00:36.230 --> 00:00:38.040\ncrwdns96040:0crwdne96040:0\n\n14\n00:00:38.040 --> 00:00:40.440\ncrwdns96042:0crwdne96042:0\n\n15\n00:00:40.440 --> 00:00:43.193\ncrwdns96044:0crwdne96044:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:01.330\n<v Instructor>下载和运行</v>\n\n2\n00:00:01.330 --> 00:00:04.110\n一个V5指令块程序很容易。\n\n3\n00:00:04.110 --> 00:00:05.993\n首先，保存程序，\n\n4\n00:00:07.340 --> 00:00:08.943\n并选择一个程序槽位。\n\n5\n00:00:10.610 --> 00:00:14.050\n接下来，从电脑连接USB电缆\n\n6\n00:00:14.050 --> 00:00:15.873\n至您的V5主控器。\n\n7\n00:00:17.260 --> 00:00:22.010\n然后，按下V5主控器的开机按键直到开机。\n\n8\n00:00:22.010 --> 00:00:24.410\n当V5主控器成功连接\n\n9\n00:00:24.410 --> 00:00:25.600\n至电脑后，\n\n10\n00:00:25.600 --> 00:00:28.623\n工具栏的主控器图标将会变为绿色。\n\n11\n00:00:29.930 --> 00:00:32.880\n选中“下载”来将程序发送\n\n12\n00:00:32.880 --> 00:00:35.263\n至选定的V5主控器槽位。\n\n13\n00:00:36.230 --> 00:00:38.040\n您现在可以选择“运行”\n\n14\n00:00:38.040 --> 00:00:40.440\n来从电脑开始程序\n\n15\n00:00:40.440 --> 00:00:43.193\n或者直接从主控器运行程序。\n\n"}},{"thumb":"V5_Tutorial_competition.jpg","mov":"V5_Blocks_CompetitionTemplate_V2","description":"Competition Template","filter":"","placeholder":false,"vimeo":"475898275","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>A V5 Blocks project makes it easy</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nto get your robot ready for competition.\n\n3\n00:00:05.390 --> 00:00:07.700\nOne of the included examples\n\n4\n00:00:07.700 --> 00:00:10.680\nis the VRC competition template.\n\n5\n00:00:10.680 --> 00:00:13.820\nA competition template project is used to write code\n\n6\n00:00:13.820 --> 00:00:17.190\nto command your robot in each phase of the competition.\n\n7\n00:00:17.190 --> 00:00:20.280\nUsing a competition template also ensures your robot\n\n8\n00:00:20.280 --> 00:00:22.910\nis in compliance with VRC rules,\n\n9\n00:00:22.910 --> 00:00:25.753\nand will properly communicate with the competitions.\n\n10\n00:00:26.610 --> 00:00:30.080\nThere are three parts to a VRC competition project,\n\n11\n00:00:30.080 --> 00:00:34.030\nsetup, autonomous mode, and driver control mode.\n\n12\n00:00:34.030 --> 00:00:35.670\nDuring a competition match,\n\n13\n00:00:35.670 --> 00:00:38.030\nthe field control system will take care\n\n14\n00:00:38.030 --> 00:00:40.080\nof sending a message to your robot\n\n15\n00:00:40.080 --> 00:00:43.260\nto automatically start the correct stack in your project,\n\n16\n00:00:43.260 --> 00:00:46.060\nand stop the other competition stacks.\n\n17\n00:00:46.060 --> 00:00:48.240\nTo begin with your competition template,\n\n18\n00:00:48.240 --> 00:00:51.210\nfirst use the when started hat block.\n\n19\n00:00:51.210 --> 00:00:54.830\nThis block can be used for any setup your robot may need\n\n20\n00:00:54.830 --> 00:00:58.160\nsuch as calibrating a gyro, setting variables\n\n21\n00:00:58.160 --> 00:01:00.060\nor other device settings.\n\n22\n00:01:00.060 --> 00:01:01.560\nIf no setup is needed,\n\n23\n00:01:01.560 --> 00:01:04.960\nthe when started stack can remain empty.\n\n24\n00:01:04.960 --> 00:01:07.500\nNext, the when autonomous hat block\n\n25\n00:01:07.500 --> 00:01:09.280\nis used for controlling your robot\n\n26\n00:01:09.280 --> 00:01:12.810\nduring the autonomous portion of a competition match.\n\n27\n00:01:12.810 --> 00:01:14.450\nBlocks attached to this stack\n\n28\n00:01:14.450 --> 00:01:17.660\nwill run when the match begins the autonomous mode.\n\n29\n00:01:17.660 --> 00:01:19.800\nIf no autonomous mode is desired,\n\n30\n00:01:19.800 --> 00:01:22.780\nthe when autonomous stack can remain empty.\n\n31\n00:01:22.780 --> 00:01:25.520\nFinally, the when driver control hat block\n\n32\n00:01:25.520 --> 00:01:27.330\nis used for controlling your robot\n\n33\n00:01:27.330 --> 00:01:30.960\nduring the driver control portion of a competition match.\n\n34\n00:01:30.960 --> 00:01:33.380\nBlocks attached to this stack will run\n\n35\n00:01:33.380 --> 00:01:36.170\nwhen the match begins the driver control mode.\n\n36\n00:01:36.170 --> 00:01:37.930\nThe forever loop is provided,\n\n37\n00:01:37.930 --> 00:01:41.570\nas most users will place conditional C blocks in this stack\n\n38\n00:01:41.570 --> 00:01:44.760\nto respond to input from the V5 controller.\n\n39\n00:01:44.760 --> 00:01:47.500\nOnce your stacks are made, your robot and project\n\n40\n00:01:47.500 --> 00:01:49.723\nwill be ready to compete, good luck.\n\n","ar":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor> مشروع البرمجة V5 يسهل </v>\n\n2\n00:00:02.700 --> 00:00:05.390\nإعداد الروبوت للمسابقة.\n\n3\n00:00:05.390 --> 00:00:07.700\nمن أحد الأمثلة المدرجة\n\n4\n00:00:07.700 --> 00:00:10.680\nهو نموذج مسابقة VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nيستخدم نموذج المسابقة لكتابة تعليمات البرمجة\n\n6\n00:00:13.820 --> 00:00:17.190\nللتحكم بالروبوت الخاص بك في كل مرحلة من المسابقة.\n\n7\n00:00:17.190 --> 00:00:20.280\nاستخدام نموذج المسابقة يضمن أيضاً أن الروبوت الخاص بك\n\n8\n00:00:20.280 --> 00:00:22.910\nيكون ممتثلاً لقواعد VRC،\n\n9\n00:00:22.910 --> 00:00:25.753\nوسيتواصل على النحو المناسب مع المسابقات.\n\n10\n00:00:26.610 --> 00:00:30.080\nهناك ثلاثة أجزاء في مشروع مسابقة VRC،\n\n11\n00:00:30.080 --> 00:00:34.030\nالإعداد والوضع التلقائي ووضع التحكم من السائق.\n\n12\n00:00:34.030 --> 00:00:35.670\nأثناء المباراة\n\n13\n00:00:35.670 --> 00:00:38.030\nسيحرص نظام مراقبة الميدان\n\n14\n00:00:38.030 --> 00:00:40.080\nمن إرسال رسالة إلى الروبوت الخاص بك\n\n15\n00:00:40.080 --> 00:00:43.260\nلبدء البرنامج المناسب تلقائياً في مشروعك،\n\n16\n00:00:43.260 --> 00:00:46.060\nوإيقاف البرامج الاخرى.\n\n17\n00:00:46.060 --> 00:00:48.240\nللبدء نموذج المسابقة الخاص بك،\n\n18\n00:00:48.240 --> 00:00:51.210\nإستخدم أولاً مقطع البرمجة \"عند البداية\".\n\n19\n00:00:51.210 --> 00:00:54.830\nيمكن استخدام هذا المقطع لضبط أي إعدادات قد يحتاج إليها الروبوت\n\n20\n00:00:54.830 --> 00:00:58.160\nمثل تعديل gyro (مدوار)، أو ضبط المتغيرات\n\n21\n00:00:58.160 --> 00:01:00.060\nأو أي إعدادات أخرى للجهاز.\n\n22\n00:01:00.060 --> 00:01:01.560\nإذا لم تكن هناك حاجة إلى الضبط،\n\n23\n00:01:01.560 --> 00:01:04.960\nيمكن أن يظل مقطع \"عند البداية\" فارغاً.\n\n24\n00:01:04.960 --> 00:01:07.500\nبعد ذلك، يستعمل مقطع \"عندما تلقائي\"\n\n25\n00:01:07.500 --> 00:01:09.280\nللتحكم فالروبوت\n\n26\n00:01:09.280 --> 00:01:12.810\nخلال الجزء التلقائي من المباراة.\n\n27\n00:01:12.810 --> 00:01:14.450\nمقاطع البرمجة الملحقة بهذه المجموعة\n\n28\n00:01:14.450 --> 00:01:17.660\nسيتم تشغيلها عندما تبدأ المباراة في الوضع التلقائي.\n\n29\n00:01:17.660 --> 00:01:19.800\nإذا لم يكن هناك وضع تلقائي،\n\n30\n00:01:19.800 --> 00:01:22.780\nيمكن أن يظل مقطع \"عندما تلقائي\" فارغاً.\n\n31\n00:01:22.780 --> 00:01:25.520\nأخيرا، يستعمل مقطع \"عند تحكم السائق\"\n\n32\n00:01:25.520 --> 00:01:27.330\nللتحكم فالروبوت\n\n33\n00:01:27.330 --> 00:01:30.960\nخلال جزء تحكم السائق من المباراة.\n\n34\n00:01:30.960 --> 00:01:33.380\nسيتم تشغيل مقاطع البرمجة الملحقة بهذه المجموعة\n\n35\n00:01:33.380 --> 00:01:36.170\nعند بداية وضع تحكم السائق.\n\n36\n00:01:36.170 --> 00:01:37.930\nتم توفير حلقة التكرار للأبد\n\n37\n00:01:37.930 --> 00:01:41.570\nلأن معظم المستخدمين سيستعملون قطع البرمجية C الشرطية في هذا المجموعة\n\n38\n00:01:41.570 --> 00:01:44.760\nللرد على الادخال من وحدة تحكم V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nعند صنع مجموعات قطع البرمجة, يصبح الروبوت والمشروع الخاص بك\n\n40\n00:01:47.500 --> 00:01:49.723\nجاهزاً للمسابقة, حظاً سعيداً.\n\n","cs":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Blokový V5 projekt usnadňuje</v>\n\n2\n00:00:02.700 --> 00:00:05.390\npřípravu tvého robota na soutěž.\n\n3\n00:00:05.390 --> 00:00:07.700\nJeden z uvedených příkladů\n\n4\n00:00:07.700 --> 00:00:10.680\nje šablona soutěže VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nProjekt soutěžní šablony je použit pro psaní kódu,\n\n6\n00:00:13.820 --> 00:00:17.190\nkterý ovládá tvého robota v každé fázi soutěže.\n\n7\n00:00:17.190 --> 00:00:20.280\nPoužití soutěžní šablony také zajišťuje, že je tvůj robot\n\n8\n00:00:20.280 --> 00:00:22.910\nv souladu s pravidly VRC\n\n9\n00:00:22.910 --> 00:00:25.753\na bude správně komunikovat se soutěžemi.\n\n10\n00:00:26.610 --> 00:00:30.080\nProjekt VRC soutěže obsahuje tři části,\n\n11\n00:00:30.080 --> 00:00:34.030\nnastavení, autonomní režim a režim ovládání řidičem.\n\n12\n00:00:34.030 --> 00:00:35.670\nBěhem soutěžního utkání\n\n13\n00:00:35.670 --> 00:00:38.030\nse kontrolní systém herní plochy postará o\n\n14\n00:00:38.030 --> 00:00:40.080\nzasílání zpráv tvému robotovi\n\n15\n00:00:40.080 --> 00:00:43.260\npro automatické spuštění správného zásobníku instrukcí ve tvém projektu\n\n16\n00:00:43.260 --> 00:00:46.060\na zastavení ostatních soutěžních zásobníků.\n\n17\n00:00:46.060 --> 00:00:48.240\nNa začátek tvé soutěžní šablony\n\n18\n00:00:48.240 --> 00:00:51.210\nnejprve použij počáteční blok Při spuštění.\n\n19\n00:00:51.210 --> 00:00:54.830\nTento blok může být použit pro jakékoliv nastavení tvého robota,\n\n20\n00:00:54.830 --> 00:00:58.160\njako je kalibrace gyroskopu, nastavení proměnných,\n\n21\n00:00:58.160 --> 00:01:00.060\nnebo jiná nastavení zařízení.\n\n22\n00:01:00.060 --> 00:01:01.560\nJestliže není nastavení potřeba,\n\n23\n00:01:01.560 --> 00:01:04.960\nmůže zásobník bloku Při spuštění zůstat prázdný.\n\n24\n00:01:04.960 --> 00:01:07.500\nDále, počáteční blok Když autonomní\n\n25\n00:01:07.500 --> 00:01:09.280\nje použit pro ovládání tvého robota\n\n26\n00:01:09.280 --> 00:01:12.810\nběhem autonomní části soutěžního utkání.\n\n27\n00:01:12.810 --> 00:01:14.450\nBloky připojené k tomuto zásobníku\n\n28\n00:01:14.450 --> 00:01:17.660\nbudou spuštěny, když utkání zahájí autonomní režim.\n\n29\n00:01:17.660 --> 00:01:19.800\nPokud není autonomní režim požadován,\n\n30\n00:01:19.800 --> 00:01:22.780\nmůže zásobník bloku Když autonomní zůstat prázdný.\n\n31\n00:01:22.780 --> 00:01:25.520\nA konečně, počáteční blok Když řidič\n\n32\n00:01:25.520 --> 00:01:27.330\nje použit pro ovládání tvého robota\n\n33\n00:01:27.330 --> 00:01:30.960\nběhem řízené části soutěžního utkání.\n\n34\n00:01:30.960 --> 00:01:33.380\nBloky připojené k tomuto zásobníku budou spuštěny,\n\n35\n00:01:33.380 --> 00:01:36.170\nkdyž utkání zahájí Režim ovládání řidičem.\n\n36\n00:01:36.170 --> 00:01:37.930\nJe poskytnut cyklus Opakuj stále,\n\n37\n00:01:37.930 --> 00:01:41.570\nprotože většina uživatelů umístí do tohoto zásobníku podmínkové bloky\n\n38\n00:01:41.570 --> 00:01:44.760\npro reakci na vstup z ovladače V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nJakmile jsou tvé zásobníky vytvořeny, tvůj robot a projekt\n\n40\n00:01:47.500 --> 00:01:49.723\nbudou připraveny soutěžit, hodně štěstí.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Un proyecto de V5 Blocks (bloques) hace que sea fácil</v>\n\n2\n00:00:02.700 --> 00:00:05.390\npara preparar a su robot para competir.\n\n3\n00:00:05.390 --> 00:00:07.700\nUno de los ejemplos incluidos\n\n4\n00:00:07.700 --> 00:00:10.680\nes la Plantilla de Competencia de VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nSe utiliza un proyecto de plantilla de competencia para escribir código\n\n6\n00:00:13.820 --> 00:00:17.190\npara mandar su robot en cada fase de la competencia.\n\n7\n00:00:17.190 --> 00:00:20.280\nUsar una plantilla de competencia también asegura que su robot\n\n8\n00:00:20.280 --> 00:00:22.910\ncumple con las reglas de VRC,\n\n9\n00:00:22.910 --> 00:00:25.753\ny se comunicará correctamente con las competiciones.\n\n10\n00:00:26.610 --> 00:00:30.080\nHay tres partes en un proyecto de competición VRC,\n\n11\n00:00:30.080 --> 00:00:34.030\nconfiguración, modo autónomo y modo de control de controladores.\n\n12\n00:00:34.030 --> 00:00:35.670\nDurante un partido de competición,\n\n13\n00:00:35.670 --> 00:00:38.030\nel sistema de control del campo se encargará de\n\n14\n00:00:38.030 --> 00:00:40.080\nde enviar un mensaje a su robot\n\n15\n00:00:40.080 --> 00:00:43.260\npara iniciar automáticamente la pila correcta en su proyecto,\n\n16\n00:00:43.260 --> 00:00:46.060\ny detener las otras pilas de competición.\n\n17\n00:00:46.060 --> 00:00:48.240\nPara empezar con su plantilla de competición,\n\n18\n00:00:48.240 --> 00:00:51.210\nprimero use el bloque de \"Cuando Empieza\".\n\n19\n00:00:51.210 --> 00:00:54.830\nEste bloque puede ser usado para cualquier configuración que su robot pueda necesitar\n\n20\n00:00:54.830 --> 00:00:58.160\ntales como la calibración de un giro, configurando variables\n\n21\n00:00:58.160 --> 00:01:00.060\nu otros ajustes del dispositivo.\n\n22\n00:01:00.060 --> 00:01:01.560\nSi no se requiere ninguna configuración,\n\n23\n00:01:01.560 --> 00:01:04.960\nla pila de \"Cuando Empieza\" puede permanecer vacía.\n\n24\n00:01:04.960 --> 00:01:07.500\nLuego, el bloque con tapa \"Autónomo\"\n\n25\n00:01:07.500 --> 00:01:09.280\nse utiliza para controlar tu robot\n\n26\n00:01:09.280 --> 00:01:12.810\ndurante la parte autónoma de un partido de competencia.\n\n27\n00:01:12.810 --> 00:01:14.450\nBloques conectados a esta pila\n\n28\n00:01:14.450 --> 00:01:17.660\nse ejecutará cuando la partida comience el modo autónomo.\n\n29\n00:01:17.660 --> 00:01:19.800\nSi no se desea ningún modo autónomo,\n\n30\n00:01:19.800 --> 00:01:22.780\nla pila de \"Cuando Autónomo\" puede permanecer vacía.\n\n31\n00:01:22.780 --> 00:01:25.520\nFinalmente, el bloque con tapa \"Cuando Modo Conductor\"\n\n32\n00:01:25.520 --> 00:01:27.330\nse utiliza para controlar tu robot\n\n33\n00:01:27.330 --> 00:01:30.960\ndurante la porción de control del conductor de un partido de competencia.\n\n34\n00:01:30.960 --> 00:01:33.380\nLos bloques conectados a esta pila se ejecutarán\n\n35\n00:01:33.380 --> 00:01:36.170\ncuando la partida comienza el modo de control del controlador.\n\n36\n00:01:36.170 --> 00:01:37.930\nSe proporciona el bucle por siempre,\n\n37\n00:01:37.930 --> 00:01:41.570\nya que la mayoría de los usuarios colocarán bloques C de condicionales en esta pila\n\n38\n00:01:41.570 --> 00:01:44.760\npara responder a la entrada del Controlador V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nUna vez que tus pilas estén hechas, tu robot y proyecto\n\n40\n00:01:47.500 --> 00:01:49.723\nestarán listo para competir, buena suerte.\n\n","es":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Un proyecto de V5 Blocks (bloques) hace que sea fácil</v>\n\n2\n00:00:02.700 --> 00:00:05.390\npara preparar a su robot para competir.\n\n3\n00:00:05.390 --> 00:00:07.700\nUno de los ejemplos incluidos\n\n4\n00:00:07.700 --> 00:00:10.680\nes la Plantilla de Competencia de VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nSe utiliza un proyecto de plantilla de competencia para escribir código\n\n6\n00:00:13.820 --> 00:00:17.190\npara mandar su robot en cada fase de la competencia.\n\n7\n00:00:17.190 --> 00:00:20.280\nUsar una plantilla de competencia también asegura que su robot\n\n8\n00:00:20.280 --> 00:00:22.910\ncumple con las reglas de VRC,\n\n9\n00:00:22.910 --> 00:00:25.753\ny se comunicará correctamente con las competiciones.\n\n10\n00:00:26.610 --> 00:00:30.080\nHay tres partes en un proyecto de competición VRC,\n\n11\n00:00:30.080 --> 00:00:34.030\nconfiguración, modo autónomo y modo de control de controladores.\n\n12\n00:00:34.030 --> 00:00:35.670\nDurante un partido de competición,\n\n13\n00:00:35.670 --> 00:00:38.030\nel sistema de control del campo se encargará de\n\n14\n00:00:38.030 --> 00:00:40.080\nde enviar un mensaje a su robot\n\n15\n00:00:40.080 --> 00:00:43.260\npara iniciar automáticamente la pila correcta en su proyecto,\n\n16\n00:00:43.260 --> 00:00:46.060\ny detener las otras pilas de competición.\n\n17\n00:00:46.060 --> 00:00:48.240\nPara empezar con su plantilla de competición,\n\n18\n00:00:48.240 --> 00:00:51.210\nprimero use el bloque de \"Cuando Empieza\".\n\n19\n00:00:51.210 --> 00:00:54.830\nEste bloque puede ser usado para cualquier configuración que su robot pueda necesitar\n\n20\n00:00:54.830 --> 00:00:58.160\ntales como la calibración de un giro, configurando variables\n\n21\n00:00:58.160 --> 00:01:00.060\nu otros ajustes del dispositivo.\n\n22\n00:01:00.060 --> 00:01:01.560\nSi no se requiere ninguna configuración,\n\n23\n00:01:01.560 --> 00:01:04.960\nla pila de \"Cuando Empieza\" puede permanecer vacía.\n\n24\n00:01:04.960 --> 00:01:07.500\nLuego, el bloque con tapa \"Autónomo\"\n\n25\n00:01:07.500 --> 00:01:09.280\nse utiliza para controlar tu robot\n\n26\n00:01:09.280 --> 00:01:12.810\ndurante la parte autónoma de un partido de competencia.\n\n27\n00:01:12.810 --> 00:01:14.450\nBloques conectados a esta pila\n\n28\n00:01:14.450 --> 00:01:17.660\nse ejecutará cuando la partida comience el modo autónomo.\n\n29\n00:01:17.660 --> 00:01:19.800\nSi no se desea ningún modo autónomo,\n\n30\n00:01:19.800 --> 00:01:22.780\nla pila de \"Cuando Autónomo\" puede permanecer vacía.\n\n31\n00:01:22.780 --> 00:01:25.520\nFinalmente, el bloque con tapa \"Cuando Modo Conductor\"\n\n32\n00:01:25.520 --> 00:01:27.330\nse utiliza para controlar tu robot\n\n33\n00:01:27.330 --> 00:01:30.960\ndurante la porción de control del conductor de un partido de competencia.\n\n34\n00:01:30.960 --> 00:01:33.380\nLos bloques conectados a esta pila se ejecutarán\n\n35\n00:01:33.380 --> 00:01:36.170\ncuando la partida comienza el modo de control del controlador.\n\n36\n00:01:36.170 --> 00:01:37.930\nSe proporciona el bucle por siempre,\n\n37\n00:01:37.930 --> 00:01:41.570\nya que la mayoría de los usuarios colocarán bloques C de condicionales en esta pila\n\n38\n00:01:41.570 --> 00:01:44.760\npara responder a la entrada del Controlador V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nUna vez que tus pilas estén hechas, tu robot y proyecto\n\n40\n00:01:47.500 --> 00:01:49.723\nestarán listo para competir, buena suerte.\n\n","fi":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>V5 Blocks -ohjelmalla on helppo</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nsaada robottisi valmiiksi kilpailuun.\n\n3\n00:00:05.390 --> 00:00:07.700\nYksi esimerkkiohjelmista\n\n4\n00:00:07.700 --> 00:00:10.680\non VRC -kilpailumalli.\n\n5\n00:00:10.680 --> 00:00:13.820\nKilpailumalli ohjelman avulla kirjoitat\n\n6\n00:00:13.820 --> 00:00:17.190\nrobotin komennot erikseen jokaiseen kilpailun vaiheeseen.\n\n7\n00:00:17.190 --> 00:00:20.280\nKun käyttää kilpailumallia varmistuu että robottisi\n\n8\n00:00:20.280 --> 00:00:22.910\non VRC kilpailun sääntöjen mukainen\n\n9\n00:00:22.910 --> 00:00:25.753\nja kommunikoi oikein kilpailun control-järjestelmän kanssa.\n\n10\n00:00:26.610 --> 00:00:30.080\nVRC kilpailuohjelmassa on kolme osaa:\n\n11\n00:00:30.080 --> 00:00:34.030\nasetukset, automaattiosuus ja ohjaimella ajo-osuus.\n\n12\n00:00:34.030 --> 00:00:35.670\nKilpailuajon aikana\n\n13\n00:00:35.670 --> 00:00:38.030\nkentän kontrollijärjestelmä ottaa\n\n14\n00:00:38.030 --> 00:00:40.080\nviestiohjauksen robottiin\n\n15\n00:00:40.080 --> 00:00:43.260\nautomaattisesti käynnistämään oikean ohjelmaosan komentopinon ohjelmastasi\n\n16\n00:00:43.260 --> 00:00:46.060\nja lopettamaan kilpailuohjelman.\n\n17\n00:00:46.060 --> 00:00:48.240\nKilpailumallissa ohjelmointi aloitetaan\n\n18\n00:00:48.240 --> 00:00:51.210\nKun käynnissä -blokilla.\n\n19\n00:00:51.210 --> 00:00:54.830\nTässä ohjelmaosassa määritellään kaikki ne määritykset, jotka robotti tarvitsee\n\n20\n00:00:54.830 --> 00:00:58.160\nkuten kiertokulman kalibrointi, muuttujien asetus\n\n21\n00:00:58.160 --> 00:01:00.060\nja muut laiteasetukset.\n\n22\n00:01:00.060 --> 00:01:01.560\nJos näitä ei tarvita\n\n23\n00:01:01.560 --> 00:01:04.960\nKun käynnissä-ohjelmaosa voi jäädä tyhjäksi.\n\n24\n00:01:04.960 --> 00:01:07.500\nSeuraavana ohjelmoidaan Kun automaatti-ohjelmaosuus\n\n25\n00:01:07.500 --> 00:01:09.280\njoka kontrolloi robottiasi\n\n26\n00:01:09.280 --> 00:01:12.810\nkilpailun alun 15 s automaattiajon ajan.\n\n27\n00:01:12.810 --> 00:01:14.450\nTämän osan blokit\n\n28\n00:01:14.450 --> 00:01:17.660\nsuoritetaan kilpailun alussa automaattiosuudella.\n\n29\n00:01:17.660 --> 00:01:19.800\nJos automaattiosaa ei haluta\n\n30\n00:01:19.800 --> 00:01:22.780\njätetään se tyhjäksi.\n\n31\n00:01:22.780 --> 00:01:25.520\nLopussa on Kun ajetaan ohjaimella -osa\n\n32\n00:01:25.520 --> 00:01:27.330\njoka kontrolloi robottiasi\n\n33\n00:01:27.330 --> 00:01:30.960\nkilpailun ohjainossa automaattiosuuden jälkeen ajan 1 min 45 s.\n\n34\n00:01:30.960 --> 00:01:33.380\nKun ajetaan ohjaimella -osan blokit suoritetaan\n\n35\n00:01:33.380 --> 00:01:36.170\nkun ohjainajo alkaa.\n\n36\n00:01:36.170 --> 00:01:37.930\nTässä ohjelmaosassa pitää olla ikuinen Toista-silmukka\n\n37\n00:01:37.930 --> 00:01:41.570\nja useimmat kilpailijat laittavat ehdollisia blokkeja tähän osaan kilpailuohjelmaa\n\n38\n00:01:41.570 --> 00:01:44.760\nvastaamaan V5 ohjaimelta annettujen nappien ja tattien painalluksiin.\n\n39\n00:01:44.760 --> 00:01:47.500\nKun nämä kolme ohjelmaosaa on koodattu ohjelmaasi\n\n40\n00:01:47.500 --> 00:01:49.723\nolet valmis kilpailuun, menestystä ajoon.\n\n","fr":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Un projet V5 Blocs rend facile</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nla préparation de votre robot pour la compétition.\n\n3\n00:00:05.390 --> 00:00:07.700\nUn des exemples inclus\n\n4\n00:00:07.700 --> 00:00:10.680\nest le modèle de compétition VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nUn modèle de projet de compétition est utile pour écrire du code\n\n6\n00:00:13.820 --> 00:00:17.190\npour commander votre robot dans chaque phase de la compétition.\n\n7\n00:00:17.190 --> 00:00:20.280\nUtiliser un modèle de compétition garantit également que votre robot\n\n8\n00:00:20.280 --> 00:00:22.910\nest conforme aux règles du VRC,\n\n9\n00:00:22.910 --> 00:00:25.753\net s'adressera correctement aux compétitions.\n\n10\n00:00:26.610 --> 00:00:30.080\nIl y a trois parties à un projet de compétition VRC,\n\n11\n00:00:30.080 --> 00:00:34.030\nla configuration, le mode autonome et le mode pilotage.\n\n12\n00:00:34.030 --> 00:00:35.670\nLors d'un match de compétition,\n\n13\n00:00:35.670 --> 00:00:38.030\nle système de contrôle du terrain prendra soin\n\n14\n00:00:38.030 --> 00:00:40.080\nd'envoyer un message à votre robot\n\n15\n00:00:40.080 --> 00:00:43.260\npour démarrer automatiquement la bonne pile dans votre projet,\n\n16\n00:00:43.260 --> 00:00:46.060\net arrêter les autres piles de la compétition.\n\n17\n00:00:46.060 --> 00:00:48.240\nPour commencer avec votre modèle de compétition,\n\n18\n00:00:48.240 --> 00:00:51.210\nutilisez d'abord le bloc chapeau \"Au démarrage\".\n\n19\n00:00:51.210 --> 00:00:54.830\nCe bloc peut être utilisé pour n'importe quelle configuration dont votre robot peut avoir besoin\n\n20\n00:00:54.830 --> 00:00:58.160\ncomme calibrer un gyro, définir des variables\n\n21\n00:00:58.160 --> 00:01:00.060\nou d'autres paramètres de l'appareil.\n\n22\n00:01:00.060 --> 00:01:01.560\nSi aucune configuration n'est requise,\n\n23\n00:01:01.560 --> 00:01:04.960\nla pile \"Au démarrage\" peut rester vide.\n\n24\n00:01:04.960 --> 00:01:07.500\nEnsuite, le bloc « Quand autonome »\n\n25\n00:01:07.500 --> 00:01:09.280\nest utilisé pour contrôler votre robot\n\n26\n00:01:09.280 --> 00:01:12.810\npendant la partie autonome d'un match de compétition.\n\n27\n00:01:12.810 --> 00:01:14.450\nLes blocs attachés à cette pile\n\n28\n00:01:14.450 --> 00:01:17.660\ns'exécuteront lorsque le mode autonome du match démarre.\n\n29\n00:01:17.660 --> 00:01:19.800\nSi aucun mode autonome n'est désiré,\n\n30\n00:01:19.800 --> 00:01:22.780\nla pile \"Quand autonome\" peut rester vide.\n\n31\n00:01:22.780 --> 00:01:25.520\nEnfin, le bloc chapeau \"Quand le pilote contrôle\"\n\n32\n00:01:25.520 --> 00:01:27.330\nest utilisé pour contrôler votre robot\n\n33\n00:01:27.330 --> 00:01:30.960\npendant la partie pilotage d'un match de compétition.\n\n34\n00:01:30.960 --> 00:01:33.380\nLes blocs attachés à cette pile seront exécutés\n\n35\n00:01:33.380 --> 00:01:36.170\nlorsque le mode de pilotage contrôlé du match démarre.\n\n36\n00:01:36.170 --> 00:01:37.930\nLa boucle \"Indéfiniment\" est fournie,\n\n37\n00:01:37.930 --> 00:01:41.570\ncar la plupart des utilisateurs placeront des blocs C conditionnels dans cette pile\n\n38\n00:01:41.570 --> 00:01:44.760\npour répondre aux entrées de la manette V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nUne fois vos piles faites, votre robot et votre projet\n\n40\n00:01:47.500 --> 00:01:49.723\nseront prêts pour la compétition, bonne chance.\n\n","ko":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>V5 블록 프로젝트로 쉽게</v>\n\n2\n00:00:02.700 --> 00:00:05.390\n경기를 준비할 수 있습니다.\n\n3\n00:00:05.390 --> 00:00:07.700\n프로젝트 예제 중에는\n\n4\n00:00:07.700 --> 00:00:10.680\nVRC 경기 템플릿이 있습니다.\n\n5\n00:00:10.680 --> 00:00:13.820\n경기 템플릿 프로젝트는 경기의 각 단계에서\n\n6\n00:00:13.820 --> 00:00:17.190\n로봇에 명령하는 코드 작성에 사용됩니다.\n\n7\n00:00:17.190 --> 00:00:20.280\n또한 경기 템플릿을 사용하면\n\n8\n00:00:20.280 --> 00:00:22.910\n로봇이 VRC 규칙을 준수하고\n\n9\n00:00:22.910 --> 00:00:25.753\n경기와 올바르게 통신할 수 있습니다.\n\n10\n00:00:26.610 --> 00:00:30.080\nVRC 경기 프로젝트에는\n\n11\n00:00:30.080 --> 00:00:34.030\n설정과 자율 운행 모드, 드라이버 컨트롤 모드 등 3가지 파트가 있습니다.\n\n12\n00:00:34.030 --> 00:00:35.670\n경기 중에\n\n13\n00:00:35.670 --> 00:00:38.030\n필드 컨트롤 시스템은\n\n14\n00:00:38.030 --> 00:00:40.080\n로봇에게 메시지를 보내\n\n15\n00:00:40.080 --> 00:00:43.260\n프로젝트에서 올바른 스택을 자동으로 시작하고\n\n16\n00:00:43.260 --> 00:00:46.060\n다른 경기 스택을 중지합니다.\n\n17\n00:00:46.060 --> 00:00:48.240\n경기 템플릿을 시작하려면\n\n18\n00:00:48.240 --> 00:00:51.210\n시작하기 모자 블록(Hat Block)을 사용하세요.\n\n19\n00:00:51.210 --> 00:00:54.830\n이 블록은 로봇에게 필요한\n\n20\n00:00:54.830 --> 00:00:58.160\n자이로 센서 조정, 변수 설정 또는 기타 기기 설정 등\n\n21\n00:00:58.160 --> 00:01:00.060\n모든 설정에 사용할 수 있습니다.\n\n22\n00:01:00.060 --> 00:01:01.560\n설정이 필요하지 않은 경우\n\n23\n00:01:01.560 --> 00:01:04.960\n시작하기 스택을 비워둘 수 있습니다.\n\n24\n00:01:04.960 --> 00:01:07.500\n다음으로, 자율 운행 모자 블록(Hat Block)은\n\n25\n00:01:07.500 --> 00:01:09.280\n경기의 자율 운행 부분에서\n\n26\n00:01:09.280 --> 00:01:12.810\n로봇 제어에 사용됩니다.\n\n27\n00:01:12.810 --> 00:01:14.450\n이 스택에 연결된 블록은\n\n28\n00:01:14.450 --> 00:01:17.660\n경기에서 자율 운행 모드를 시작할 때 실행됩니다.\n\n29\n00:01:17.660 --> 00:01:19.800\n자율 운행 모드가 필요하지 않은 경우\n\n30\n00:01:19.800 --> 00:01:22.780\n자율 운행 스택을 비워둘 수 있습니다.\n\n31\n00:01:22.780 --> 00:01:25.520\n마지막으로, 드라이버 컨트롤 모자 블록(Hat Block)은\n\n32\n00:01:25.520 --> 00:01:27.330\n경기의 드라이버 컨트롤 부분에서\n\n33\n00:01:27.330 --> 00:01:30.960\n로봇 제어에 사용됩니다.\n\n34\n00:01:30.960 --> 00:01:33.380\n이 스택에 연결된 블록은\n\n35\n00:01:33.380 --> 00:01:36.170\n경기에서 드라이버 컨트롤 모드를 시작할 때 실행됩니다.\n\n36\n00:01:36.170 --> 00:01:37.930\n대부분의 사용자가\n\n37\n00:01:37.930 --> 00:01:41.570\n이 스택에 조건부 C 블록을 배치하여\n\n38\n00:01:41.570 --> 00:01:44.760\nV5 컨트롤러의 입력에 응답하기 때문에 무한반복 루프가 제공됩니다.\n\n39\n00:01:44.760 --> 00:01:47.500\n스택이 만들어지면 로봇과 프로젝트는\n\n40\n00:01:47.500 --> 00:01:49.723\n경기할 준비가 됩니다. 행운을 빕니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>\"V5 Blocks\" projektas palengvina</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nroboto paruošimą rungtynėms.\n\n3\n00:00:05.390 --> 00:00:07.700\nVienas iš įtrauktų pavyzdžių\n\n4\n00:00:07.700 --> 00:00:10.680\nyra VRC varžybų šablonas.\n\n5\n00:00:10.680 --> 00:00:13.820\nVaržybų šablono projektas naudojamas rašyti kodą tam,\n\n6\n00:00:13.820 --> 00:00:17.190\nkad kiekviename varžybų etape galėtumėte siųsti nurodymus savo robotui.\n\n7\n00:00:17.190 --> 00:00:20.280\nNaudodami varžybų šabloną, taip pat užtikrinate, kad Jūsų robotas\n\n8\n00:00:20.280 --> 00:00:22.910\natitinka VRC taisykles\n\n9\n00:00:22.910 --> 00:00:25.753\nir deramai komunikuoja varžybų metu.\n\n10\n00:00:26.610 --> 00:00:30.080\nVRC varžybų projektą sudaro trys dalys:\n\n11\n00:00:30.080 --> 00:00:34.030\nparengimas, autonominis režimas ir vairuotojo valdymo režimas.\n\n12\n00:00:34.030 --> 00:00:35.670\nVaržybų metu,\n\n13\n00:00:35.670 --> 00:00:38.030\nlauko kontrolės sistema\n\n14\n00:00:38.030 --> 00:00:40.080\nJūsų robotui išsiųs žinutę,\n\n15\n00:00:40.080 --> 00:00:43.260\nkad Jūsų projekte būtų automatiškai paleista kodo krūva,\n\n16\n00:00:43.260 --> 00:00:46.060\no kitos varžybų kodo krūvos būtų sustabdytos.\n\n17\n00:00:46.060 --> 00:00:48.240\nNorėdami pradėti naudoti varžybų šabloną,\n\n18\n00:00:48.240 --> 00:00:51.210\npirmiausia naudokite \"kada pradėti\" bloką.\n\n19\n00:00:51.210 --> 00:00:54.830\nŠį kodą galite naudoti bet kokiam parengimui,\n\n20\n00:00:54.830 --> 00:00:58.160\npavyzdžiui, giroskopo kalibravimui, kintamųjų nustatymui\n\n21\n00:00:58.160 --> 00:01:00.060\narba kitiems prietaiso nustatymams.\n\n22\n00:01:00.060 --> 00:01:01.560\nJeigu parengti nereikia,\n\n23\n00:01:01.560 --> 00:01:04.960\n\"kada pradėti\" kodo krūva gali likti tuščia.\n\n24\n00:01:04.960 --> 00:01:07.500\nPo to, \"kada autonominis\" bloku\n\n25\n00:01:07.500 --> 00:01:09.280\nvaržybų autonominėje dalyje\n\n26\n00:01:09.280 --> 00:01:12.810\nvaldysite savo robotą.\n\n27\n00:01:12.810 --> 00:01:14.450\nPrie šios krūvos pridėti blokai\n\n28\n00:01:14.450 --> 00:01:17.660\nįsijungs, kai bus paleistas autonominis režimas.\n\n29\n00:01:17.660 --> 00:01:19.800\nJeigu autonominis režimas nebūtinas,\n\n30\n00:01:19.800 --> 00:01:22.780\n\"kada autonominis\" krūva gali likti tuščia.\n\n31\n00:01:22.780 --> 00:01:25.520\nGaliausiai, \"kada valdomas vairuotojo\" blokas\n\n32\n00:01:25.520 --> 00:01:27.330\nvaržybų autonominėje dalyje, kai robotą valdo vairuotojas,\n\n33\n00:01:27.330 --> 00:01:30.960\nvaldo Jūsų robotą.\n\n34\n00:01:30.960 --> 00:01:33.380\nPrie šios krūvos pridėti blokai įsijungs,\n\n35\n00:01:33.380 --> 00:01:36.170\nkai varžybų metu bus paleistas vairuotojo kontrolės režimas.\n\n36\n00:01:36.170 --> 00:01:37.930\nPateikiamas amžinas ciklas,\n\n37\n00:01:37.930 --> 00:01:41.570\nnes daugelis naudotojų prie šios krūvos pridės sąlyginius \"C\" blokus,\n\n38\n00:01:41.570 --> 00:01:44.760\nkad reaguotų į V5 valdiklio įvestis.\n\n39\n00:01:44.760 --> 00:01:47.500\nSukūrus kodo krūvas, Jūsų robotas ir projektas\n\n40\n00:01:47.500 --> 00:01:49.723\nbus pasirengę varžytis, sėkmės.\n\n","lv":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>V5 Blocks projekts ļauj ērti un vienkārši</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nsagatavot robotu sacensībām.\n\n3\n00:00:05.390 --> 00:00:07.700\nViens no iekļautajiem piemēriem\n\n4\n00:00:07.700 --> 00:00:10.680\nir VRC sacensību veidne.\n\n5\n00:00:10.680 --> 00:00:13.820\nSacensību veidnes projektu izmanto koda rakstīšanai,\n\n6\n00:00:13.820 --> 00:00:17.190\nlai komandētu savu robotu katrā sacensību fāzē.\n\n7\n00:00:17.190 --> 00:00:20.280\nSacensību veidnes izmantošana nodrošina, ka robots\n\n8\n00:00:20.280 --> 00:00:22.910\natbilst VRC noteikumiem,\n\n9\n00:00:22.910 --> 00:00:25.753\nun pareizi komunicēs ar konkursantiem.\n\n10\n00:00:26.610 --> 00:00:30.080\nVRC sacensību projektam ir trīs daļas,\n\n11\n00:00:30.080 --> 00:00:34.030\nuzstādīšana, autonomais režīms un draivera vadības režīms.\n\n12\n00:00:34.030 --> 00:00:35.670\nSacensību laikā\n\n13\n00:00:35.670 --> 00:00:38.030\nlaukuma kontroles sistēmā parūpēsies\n\n14\n00:00:38.030 --> 00:00:40.080\npar informācijas nosūtīšanu robotam,\n\n15\n00:00:40.080 --> 00:00:43.260\nlai automātiski startētu pareizo bloku kopu no jūsu projekta\n\n16\n00:00:43.260 --> 00:00:46.060\nun apturēt pārējās sacensību bloku kopas.\n\n17\n00:00:46.060 --> 00:00:48.240\nLai sāktu ar jūsu sacensību veidni,\n\n18\n00:00:48.240 --> 00:00:51.210\nvispirms izmantojiet sākuma bloku “When Started”.\n\n19\n00:00:51.210 --> 00:00:54.830\nŠo bloku var izmantot jebkuram uzstādījumam, kas jūsu robotam var būt nepieciešams,\n\n20\n00:00:54.830 --> 00:00:58.160\npiemēram, žiroskopa kalibrēšana, mainīgo iestatīšanai\n\n21\n00:00:58.160 --> 00:01:00.060\nvai citiem ierīces uzstādījumiem.\n\n22\n00:01:00.060 --> 00:01:01.560\nJa uzstādīšana nav nepieciešama,\n\n23\n00:01:01.560 --> 00:01:04.960\nsākuma bloks var palikt tukšs.\n\n24\n00:01:04.960 --> 00:01:07.500\nSākuma bloks “When Autonomous”\n\n25\n00:01:07.500 --> 00:01:09.280\ntiek izmantots robota vadīšanai\n\n26\n00:01:09.280 --> 00:01:12.810\nsacensību mača autonomās daļas laikā.\n\n27\n00:01:12.810 --> 00:01:14.450\nŠajā pakotnē pievienotie bloki\n\n28\n00:01:14.450 --> 00:01:17.660\ntiks palaisti, kad sāksies sacensību autonomā režīma daļa.\n\n29\n00:01:17.660 --> 00:01:19.800\nJa nav vēlams autonomais režīms,\n\n30\n00:01:19.800 --> 00:01:22.780\ntad bloks “When autonomous” var palikt tukšs.\n\n31\n00:01:22.780 --> 00:01:25.520\nDraivera vadības sākuma bloks\n\n32\n00:01:25.520 --> 00:01:27.330\ntiek izmantots robota vadīšanai\n\n33\n00:01:27.330 --> 00:01:30.960\nsacensību mača daļā, kad jālieto draivera vadība.\n\n34\n00:01:30.960 --> 00:01:33.380\nSaliktajā blokā pievienotie bloki tiks darbināti,\n\n35\n00:01:33.380 --> 00:01:36.170\nkad sacensībās tiks palaista draivera vadības daļa.\n\n36\n00:01:36.170 --> 00:01:37.930\nIr pieejams bezgalības cikls,\n\n37\n00:01:37.930 --> 00:01:41.570\njo vairums lietotāju saliktajā blokā izvietos nosacījuma cikla blokus,\n\n38\n00:01:41.570 --> 00:01:44.760\nkas atbilst V5 vadības ierīces ievadei.\n\n39\n00:01:44.760 --> 00:01:47.500\nKad saliktie bloki ir gatavi, robots un projekts\n\n40\n00:01:47.500 --> 00:01:49.723\nbūs gatavi sacensībām. Veiksmi!\n\n","nl":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Een V5 Blokken project maakt het gemakkelijk</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nom uw robot klaar te maken voor wedstrijden.\n\n3\n00:00:05.390 --> 00:00:07.700\nEen van de meegeleverde voorbeelden\n\n4\n00:00:07.700 --> 00:00:10.680\nis het VRC-wedstrijdsjabloon.\n\n5\n00:00:10.680 --> 00:00:13.820\nEen wedstrijdsjabloon project wordt gebruikt om programma te schrijven\n\n6\n00:00:13.820 --> 00:00:17.190\nom uw robot in elke fase van de wedstrijd te besturen.\n\n7\n00:00:17.190 --> 00:00:20.280\nDoor een wedstrijdsjabloon te gebruiken, zorgt u er ook voor dat uw robot\n\n8\n00:00:20.280 --> 00:00:22.910\nvoldoet aan de VRC-regels\n\n9\n00:00:22.910 --> 00:00:25.753\nen zal naar behoren communiceren met de wedstrijden.\n\n10\n00:00:26.610 --> 00:00:30.080\nEen VRC-wedstrijdproject bestaat uit drie delen:\n\n11\n00:00:30.080 --> 00:00:34.030\nconfiguratie, autonome modus en bestuurder controle modus.\n\n12\n00:00:34.030 --> 00:00:35.670\nTijdens een competitie wedstrijd\n\n13\n00:00:35.670 --> 00:00:38.030\nzorgt het veld controle systeem ervoor\n\n14\n00:00:38.030 --> 00:00:40.080\ndat er een bericht naar uw robot wordt gestuurd\n\n15\n00:00:40.080 --> 00:00:43.260\nom automatisch de juiste stapel in uw project te starten\n\n16\n00:00:43.260 --> 00:00:46.060\nen de andere wedstrijdstapels te stoppen.\n\n17\n00:00:46.060 --> 00:00:48.240\nOm met uw wedstrijdsjabloon te beginnen,\n\n18\n00:00:48.240 --> 00:00:51.210\ngebruik eerst het \"wanneer gestart\" hoed blok.\n\n19\n00:00:51.210 --> 00:00:54.830\nDeze blok kan worden gebruikt voor alle instellingen die uw robot nodig heeft\n\n20\n00:00:54.830 --> 00:00:58.160\nzoals het kalibreren van een gyro, het instellen van variabelen\n\n21\n00:00:58.160 --> 00:01:00.060\nof andere apparaat-instellingen.\n\n22\n00:01:00.060 --> 00:01:01.560\nAls er geen configuratie nodig is\n\n23\n00:01:01.560 --> 00:01:04.960\nde \"wanneer gestart\" stapel kan leeg blijven.\n\n24\n00:01:04.960 --> 00:01:07.500\nVervolgens wordt het autonome wanneer hoed blok\n\n25\n00:01:07.500 --> 00:01:09.280\ngebruikt om uw robot te besturen\n\n26\n00:01:09.280 --> 00:01:12.810\ntijdens het autonome deel van een competitiewedstrijd.\n\n27\n00:01:12.810 --> 00:01:14.450\nBlokken die aan deze stapel zijn gekoppeld,\n\n28\n00:01:14.450 --> 00:01:17.660\nworden uitgevoerd wanneer de wedstrijd de autonome modus begint.\n\n29\n00:01:17.660 --> 00:01:19.800\nAls geen autonome modus gewenst is,\n\n30\n00:01:19.800 --> 00:01:22.780\nde autonome wanneer gestart stapel kan leeg blijven.\n\n31\n00:01:22.780 --> 00:01:25.520\nTot slot wordt het \"wanneer controle bestuurder\" hoed blok\n\n32\n00:01:25.520 --> 00:01:27.330\ngebruikt om uw robot te besturen\n\n33\n00:01:27.330 --> 00:01:30.960\ntijdens het besturingsgecontroleerde gedeelte van een competitiewedstrijd.\n\n34\n00:01:30.960 --> 00:01:33.380\nBlokken die aan deze stapel zijn gekoppeld,\n\n35\n00:01:33.380 --> 00:01:36.170\nworden uitgevoerd wanneer de wedstrijd de besturingsmodus van de bestuurder begint.\n\n36\n00:01:36.170 --> 00:01:37.930\nDe voor altijd lus is aanwezig,\n\n37\n00:01:37.930 --> 00:01:41.570\naangezien de meeste gebruikers voorwaardelijke C-blokken in deze stapel\n\n38\n00:01:41.570 --> 00:01:44.760\nplaatsen om te reageren op invoer van de V5-controller.\n\n39\n00:01:44.760 --> 00:01:47.500\nWanneer je stapels eenmaal gemaakt zijn, zijn uw robot en project\n\n40\n00:01:47.500 --> 00:01:49.723\nklaar zijn om te concurreren. Veel plezier!\n\n","pl":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Projekt V5 Blocks sprawia, że łatwo</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nprzygotować robota do zawodów.\n\n3\n00:00:05.390 --> 00:00:07.700\nJeden z załączonych przykładów\n\n4\n00:00:07.700 --> 00:00:10.680\njest szablonem konkursu VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nSzablon konkursu jest używany do pisania kodu\n\n6\n00:00:13.820 --> 00:00:17.190\naby wydawać polecenia robotowi w każdej fazie konkursu.\n\n7\n00:00:17.190 --> 00:00:20.280\nKorzystanie z szablonu konkursu zapewnia również, że Twój robot\n\n8\n00:00:20.280 --> 00:00:22.910\njest zgodny z zasadami VRC,\n\n9\n00:00:22.910 --> 00:00:25.753\ni we właściwy sposób komunikuje się z zadaniami.\n\n10\n00:00:26.610 --> 00:00:30.080\nProjekt konkursu VRC obejmuje trzy części\n\n11\n00:00:30.080 --> 00:00:34.030\nkonfiguracja, tryb autonomiczny i tryb sterowania kierowcy.\n\n12\n00:00:34.030 --> 00:00:35.670\nPodczas meczu konkursowego,\n\n13\n00:00:35.670 --> 00:00:38.030\nsystem kontroli terenowej będzie się zajmować\n\n14\n00:00:38.030 --> 00:00:40.080\nwysyłaniem wiadomości do twojego robota\n\n15\n00:00:40.080 --> 00:00:43.260\naby automatycznie uruchomić poprawny stos w Twoim projekcie,\n\n16\n00:00:43.260 --> 00:00:46.060\ni powstrzymać pozostałe stosy konkurencji.\n\n17\n00:00:46.060 --> 00:00:48.240\nAby zacząć pracę z szablonem konkursu,\n\n18\n00:00:48.240 --> 00:00:51.210\nnajpierw użyj \"hat\" blok \"po rozpoczęciu\".\n\n19\n00:00:51.210 --> 00:00:54.830\nTen blok może być użyty do każdej konfiguracji, jakiej może potrzebować robot\n\n20\n00:00:54.830 --> 00:00:58.160\ntakie jak kalibrowanie żyroskopów, ustawienia zmiennych\n\n21\n00:00:58.160 --> 00:01:00.060\nlub inne ustawienia urządzenia.\n\n22\n00:01:00.060 --> 00:01:01.560\nJeśli konfiguracja nie jest wymagana,\n\n23\n00:01:01.560 --> 00:01:04.960\nstos \"po uruchomieniu\" może zostać pusty.\n\n24\n00:01:04.960 --> 00:01:07.500\nNastępnie kiedy \"hat\" blok \"kiedy automatycznie\"\n\n25\n00:01:07.500 --> 00:01:09.280\njest używany do kontrolowania robota\n\n26\n00:01:09.280 --> 00:01:12.810\npodczas autonomicznej części meczu konkursowego.\n\n27\n00:01:12.810 --> 00:01:14.450\nBloki dołączone do tego stosu\n\n28\n00:01:14.450 --> 00:01:17.660\nuruchomi się, gdy mecz zacznie tryb autonomiczny.\n\n29\n00:01:17.660 --> 00:01:19.800\nJeśli nie jest potrzebny tryb autonomiczny,\n\n30\n00:01:19.800 --> 00:01:22.780\nstos \"automatycznie\" może zostać pusty.\n\n31\n00:01:22.780 --> 00:01:25.520\nNa koniec, kiedy \"hat\" blok \"kontrola kierowcy\"\n\n32\n00:01:25.520 --> 00:01:27.330\njest używany do kontrolowania robota\n\n33\n00:01:27.330 --> 00:01:30.960\npodczas sterowanej przez kierowcę części meczu konkursowego.\n\n34\n00:01:30.960 --> 00:01:33.380\nBloki dołączone do tego stosu zostaną uruchomione\n\n35\n00:01:33.380 --> 00:01:36.170\ngdy mecz rozpoczyna tryb sterowania kierowcy.\n\n36\n00:01:36.170 --> 00:01:37.930\nDostępna jest pętla na zawsze\n\n37\n00:01:37.930 --> 00:01:41.570\nponieważ większość użytkowników umieści bloki warunkowe C w tym stosie\n\n38\n00:01:41.570 --> 00:01:44.760\naby odpowiedzieć na dane wejściowe od kontrolera V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nPo utworzeniu twoich stosów, Twój robot i projekt\n\n40\n00:01:47.500 --> 00:01:49.723\nbędzie gotowy do współzawodnictwa, powodzenia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Блоковый проект V5 легко позволяет</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nподготовить вашего робота к соревнованиям.\n\n3\n00:00:05.390 --> 00:00:07.700\nВ одном из примеров вы найдёте\n\n4\n00:00:07.700 --> 00:00:10.680\nшаблон для соревнований VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nПроект шаблона соревнований используется для написания кода\n\n6\n00:00:13.820 --> 00:00:17.190\nуправления вашим роботом на каждом этапе соревнований.\n\n7\n00:00:17.190 --> 00:00:20.280\nИспользование шаблона для соревнований помогает роботу\n\n8\n00:00:20.280 --> 00:00:22.910\nсоответствовать правилам VRC\n\n9\n00:00:22.910 --> 00:00:25.753\nи правильно себя вести на соревнованиях.\n\n10\n00:00:26.610 --> 00:00:30.080\nСоревновательный проект состоит из трёх частей:\n\n11\n00:00:30.080 --> 00:00:34.030\nнастройка, автономный и управляемый режимы.\n\n12\n00:00:34.030 --> 00:00:35.670\nВ ходе матча\n\n13\n00:00:35.670 --> 00:00:38.030\nсистема управления полем будет\n\n14\n00:00:38.030 --> 00:00:40.080\nпосылать сигналы роботу\n\n15\n00:00:40.080 --> 00:00:43.260\nдля запуска определённой части проекта\n\n16\n00:00:43.260 --> 00:00:46.060\nи остановки других частей проекта.\n\n17\n00:00:46.060 --> 00:00:48.240\nДля начала, в соревновательном шаблоне\n\n18\n00:00:48.240 --> 00:00:51.210\nпервым делом используйте блок начала программы.\n\n19\n00:00:51.210 --> 00:00:54.830\nЭтот блок может быть использован для предварительной настойки робота,\n\n20\n00:00:54.830 --> 00:00:58.160\nтакой как калибровка гироскопа, установка начальных значений\n\n21\n00:00:58.160 --> 00:01:00.060\nили настройка других устройств.\n\n22\n00:01:00.060 --> 00:01:01.560\nЕсли настройка не нужна,\n\n23\n00:01:01.560 --> 00:01:04.960\nто блок начала можно оставить пустым.\n\n24\n00:01:04.960 --> 00:01:07.500\nДалее, настроим блок автономного управления,\n\n25\n00:01:07.500 --> 00:01:09.280\nкоторый используется для управления\n\n26\n00:01:09.280 --> 00:01:12.810\nроботом во время автономной части матча.\n\n27\n00:01:12.810 --> 00:01:14.450\nБлоки, прикрепленные к этому стеку,\n\n28\n00:01:14.450 --> 00:01:17.660\nбудут запущены при начале автономной части матча.\n\n29\n00:01:17.660 --> 00:01:19.800\nЕсли автономная часть не предусмотрена,\n\n30\n00:01:19.800 --> 00:01:22.780\nто вы можете оставить этот блок пустым.\n\n31\n00:01:22.780 --> 00:01:25.520\nНаконец, необходимо настроить блок управляемого режима,\n\n32\n00:01:25.520 --> 00:01:27.330\nкоторый используется для управления роботом\n\n33\n00:01:27.330 --> 00:01:30.960\nво время режима управления.\n\n34\n00:01:30.960 --> 00:01:33.380\nБлоки, прикрепленные к этому стеку,\n\n35\n00:01:33.380 --> 00:01:36.170\nбудут запущены во время управляемого периода матча.\n\n36\n00:01:36.170 --> 00:01:37.930\nЗапускается бесконечный цикл,\n\n37\n00:01:37.930 --> 00:01:41.570\nтак как большинство пользователей размещают блоки C в этом стеке\n\n38\n00:01:41.570 --> 00:01:44.760\nдля обеспечения связи с контроллером.\n\n39\n00:01:44.760 --> 00:01:47.500\nПосле настройки режимов работы, ваш робот и проект\n\n40\n00:01:47.500 --> 00:01:49.723\nбудут готовы к соревнованиям, удачи.\n\n","th":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor> โครงการ V5 Blocks นั้นทำให้ </v>\n\n2\n00:00:02.700 --> 00:00:05.390\nการเตรียมหุ่นยนต์ของคุณให้พร้อมสำหรับการแข่งขันเป็นเรื่องง่าย\n\n3\n00:00:05.390 --> 00:00:07.700\nหนึ่งในตัวอย่างที่มี\n\n4\n00:00:07.700 --> 00:00:10.680\nคือเทมเพลตการแข่งขัน VRC\n\n5\n00:00:10.680 --> 00:00:13.820\nเทมเพลตโปรเจ็คการแข่งขันใช้ในการเขียนโค้ด\n\n6\n00:00:13.820 --> 00:00:17.190\nเพื่อสั่งการหุ่นยนต์ของคุณในแต่ละช่วงของการแข่งขัน\n\n7\n00:00:17.190 --> 00:00:20.280\nการใช้เทมเพลตการแข่งขันยังช่วยให้หุ่นยนต์ของคุณ\n\n8\n00:00:20.280 --> 00:00:22.910\nทำตามกฎของ VRC\n\n9\n00:00:22.910 --> 00:00:25.753\nและจะเข้าร่วมการแข่งขันอย่างถูกต้อง\n\n10\n00:00:26.610 --> 00:00:30.080\nโปรเจ็คการแข่งขัน VRC นั้น ประกอบไปด้วยสามส่วน\n\n11\n00:00:30.080 --> 00:00:34.030\nการตั้งค่า, โหมดอัตโนมัติและโหมดควบคุมไดรเวอร์\n\n12\n00:00:34.030 --> 00:00:35.670\nในระหว่างการแข่งขัน\n\n13\n00:00:35.670 --> 00:00:38.030\nระบบควบคุมสนามจะดูแล\n\n14\n00:00:38.030 --> 00:00:40.080\nในส่วนของการส่งข้อความไปยังหุ่นยนต์ของคุณ\n\n15\n00:00:40.080 --> 00:00:43.260\nเพื่อเริ่ม stack ที่ถูกต้องในโปรเจ็คของคุณโดยอัตโนมัติ\n\n16\n00:00:43.260 --> 00:00:46.060\nและหยุด stack การแข่งขันอื่น ๆ\n\n17\n00:00:46.060 --> 00:00:48.240\nในการเริ่มต้นด้วยเทมเพลตการแข่งขันของคุณ\n\n18\n00:00:48.240 --> 00:00:51.210\nจะเริ่มโดยการใช้ hat block\n\n19\n00:00:51.210 --> 00:00:54.830\nบล็อกนี้สามารถใช้สำหรับการตั้งค่าต่างๆ ที่หุ่นยนต์ของคุณต้องการ\n\n20\n00:00:54.830 --> 00:00:58.160\nเช่นการปรับไจโร, การตั้งค่าตัวแปร\n\n21\n00:00:58.160 --> 00:01:00.060\nหรือตั้งค่าอุปกรณ์อื่นๆ\n\n22\n00:01:00.060 --> 00:01:01.560\nหากไม่จำเป็นต้องตั้งค่าใด ๆ\n\n23\n00:01:01.560 --> 00:01:04.960\nstack เริ่มต้นจะว่างเปล่า\n\n24\n00:01:04.960 --> 00:01:07.500\nจากนั้น เมื่อ autonomous hat block\n\n25\n00:01:07.500 --> 00:01:09.280\nถูกใช้เพื่อควบคุมหุ่นยนต์ของคุณ\n\n26\n00:01:09.280 --> 00:01:12.810\nในระหว่างการแข่งขันแบบอัตโนมัติ\n\n27\n00:01:12.810 --> 00:01:14.450\nบล็อกที่แนบมากับ stack นี้\n\n28\n00:01:14.450 --> 00:01:17.660\nจะทำงานเมื่อการแข่งขันเริ่มขึ้นในโหมดอิสระ autonomous mode\n\n29\n00:01:17.660 --> 00:01:19.800\nหากไม่ต้องการใช้โหมดอัตโนมัติ autonomous mode\n\n30\n00:01:19.800 --> 00:01:22.780\nwhen autonomous stack สามารถเว้นให้ว่างเปล่าได้\n\n31\n00:01:22.780 --> 00:01:25.520\nสุดท้าย เมื่อ driver control hat block\n\n32\n00:01:25.520 --> 00:01:27.330\nถูกใช้เพื่อควบคุมหุ่นยนต์ของคุณ\n\n33\n00:01:27.330 --> 00:01:30.960\nระหว่างส่วนควบคุมคนขับของการแข่งขัน\n\n34\n00:01:30.960 --> 00:01:33.380\nบล็อกที่แนบมากับ stack นี้จะทำงาน\n\n35\n00:01:33.380 --> 00:01:36.170\nเมื่อการแข่งขันเริ่มโหมดควบคุมด้วยคนขับ\n\n36\n00:01:36.170 --> 00:01:37.930\nforever loop จะถูกใช้งาน\n\n37\n00:01:37.930 --> 00:01:41.570\nเนื่องจากผู้ใช้ส่วนใหญ่จะวางบล็อก C แบบมีเงื่อนไขไว้ใน stack นี้\n\n38\n00:01:41.570 --> 00:01:44.760\nเพื่อให้ตอบสนองต่ออินพุตจาก V5 คอนโทรลเลอร์\n\n39\n00:01:44.760 --> 00:01:47.500\nเมื่อคุณสร้าง stack แล้ว หุ่นยนต์และโปรเจ็คของคุณ\n\n40\n00:01:47.500 --> 00:01:49.723\nก็จะพร้อมสำหรับการแข่งขัน ขอให้คุณโชคดี!\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Блоковий проєкт V5 полегшить</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nпідготовку робота до змагань.\n\n3\n00:00:05.390 --> 00:00:07.700\nОдин із вбудованих прикладів -\n\n4\n00:00:07.700 --> 00:00:10.680\nшаблон змагань VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nПроєкт шаблону змагань використовують для написання коду,\n\n6\n00:00:13.820 --> 00:00:17.190\nщоб контролювати робота в кожній фазі змагань.\n\n7\n00:00:17.190 --> 00:00:20.280\nВикористання шаблону змагань також гарантує, що ваш робот\n\n8\n00:00:20.280 --> 00:00:22.910\nвідповідатиме правилам VRC\n\n9\n00:00:22.910 --> 00:00:25.753\nі належно комунікуватиме зі змаганнями.\n\n10\n00:00:26.610 --> 00:00:30.080\nЄ три частини проєкту VRC змагань:\n\n11\n00:00:30.080 --> 00:00:34.030\nналаштування, автономний режим і режим ручного керування.\n\n12\n00:00:34.030 --> 00:00:35.670\nУпродовж матчу змагань\n\n13\n00:00:35.670 --> 00:00:38.030\nсистема контролю поля подбає\n\n14\n00:00:38.030 --> 00:00:40.080\nпро надсилання повідомлення до вашого робота\n\n15\n00:00:40.080 --> 00:00:43.260\nпро автоматичний запуск потрібного стека вашого проєкту\n\n16\n00:00:43.260 --> 00:00:46.060\nі зупинку інших стеків програми змагань.\n\n17\n00:00:46.060 --> 00:00:48.240\nЩоб почати роботу з шаблоном змагань,\n\n18\n00:00:48.240 --> 00:00:51.210\nспочатку використаємо стартовий блок \"коли почнемо\".\n\n19\n00:00:51.210 --> 00:00:54.830\nЦей блок знадобиться для налаштувань, потрібних для робота,\n\n20\n00:00:54.830 --> 00:00:58.160\nяк-от калібрування гіроскопа, налаштування змінних\n\n21\n00:00:58.160 --> 00:01:00.060\nабо налаштування інших пристроїв.\n\n22\n00:01:00.060 --> 00:01:01.560\nЯкщо налаштування не потрібні,\n\n23\n00:01:01.560 --> 00:01:04.960\nстек \"коли почнемо\" можна залишити пустим.\n\n24\n00:01:04.960 --> 00:01:07.500\nДалі, стартовий блок \"коли автономно\",\n\n25\n00:01:07.500 --> 00:01:09.280\nйого використовують для керування роботом\n\n26\n00:01:09.280 --> 00:01:12.810\nупродовж автономного періоду матчу змагань.\n\n27\n00:01:12.810 --> 00:01:14.450\nБлоки, закріплені за цим стеком,\n\n28\n00:01:14.450 --> 00:01:17.660\nпочнуть працювати, коли почнеться автономний період матчу.\n\n29\n00:01:17.660 --> 00:01:19.800\nЯкщо автономний режим не передбачено,\n\n30\n00:01:19.800 --> 00:01:22.780\nто стек \"коли автономно\" можна залишити пустим.\n\n31\n00:01:22.780 --> 00:01:25.520\nОстанній, стартовий блок \"коли ручне керування\",\n\n32\n00:01:25.520 --> 00:01:27.330\nйого використовують для керування роботом\n\n33\n00:01:27.330 --> 00:01:30.960\nупродовж періоду ручного керування матчу змагань.\n\n34\n00:01:30.960 --> 00:01:33.380\nБлоки, закріплені за цим стеком, почнуть\n\n35\n00:01:33.380 --> 00:01:36.170\nпрацювати, коли почнеться період ручного керування матчу.\n\n36\n00:01:36.170 --> 00:01:37.930\nБлок циклу \"завжди\" використовується\n\n37\n00:01:37.930 --> 00:01:41.570\nбільшістю користувачів для розміщення в ньому С-подібних блоків умови,\n\n38\n00:01:41.570 --> 00:01:44.760\nщоб робот реагував на вхідні команди з контролера V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nЩойно стеки будуть зроблені, ваш робот і проєкт\n\n40\n00:01:47.500 --> 00:01:49.723\nбудуть готові до змагань. Щасти.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>Dự án V5 Blocks giúp việc này trở nên dễ dàng</v>\n\n2\n00:00:02.700 --> 00:00:05.390\nđể chuẩn bị sẵn sàng cho robot của bạn để cạnh tranh.\n\n3\n00:00:05.390 --> 00:00:07.700\nMột trong những ví dụ bao gồm\n\n4\n00:00:07.700 --> 00:00:10.680\nlà mẫu cuộc thi VRC.\n\n5\n00:00:10.680 --> 00:00:13.820\nMột dự án mẫu cạnh tranh được sử dụng để viết mã\n\n6\n00:00:13.820 --> 00:00:17.190\nđể chỉ huy robot của bạn trong mỗi giai đoạn của cuộc thi.\n\n7\n00:00:17.190 --> 00:00:20.280\nSử dụng mẫu cạnh tranh cũng đảm bảo rô bốt của bạn\n\n8\n00:00:20.280 --> 00:00:22.910\ntuân thủ các quy tắc VRC,\n\n9\n00:00:22.910 --> 00:00:25.753\nvà sẽ giao tiếp đúng với các cuộc thi.\n\n10\n00:00:26.610 --> 00:00:30.080\nDự án cạnh tranh VRC có ba phần,\n\n11\n00:00:30.080 --> 00:00:34.030\nthiết lập, chế độ tự hành và chế độ điều khiển trình điều khiển.\n\n12\n00:00:34.030 --> 00:00:35.670\nTrong một trận đấu cạnh tranh,\n\n13\n00:00:35.670 --> 00:00:38.030\nhệ thống kiểm soát hiện trường sẽ chăm sóc\n\n14\n00:00:38.030 --> 00:00:40.080\ngửi tin nhắn đến rô bốt của bạn\n\n15\n00:00:40.080 --> 00:00:43.260\nđể tự động bắt đầu ngăn xếp chính xác trong dự án của bạn,\n\n16\n00:00:43.260 --> 00:00:46.060\nvà dừng các ngăn xếp cạnh tranh khác.\n\n17\n00:00:46.060 --> 00:00:48.240\nĐể bắt đầu với mẫu cạnh tranh của bạn,\n\n18\n00:00:48.240 --> 00:00:51.210\nđầu tiên sử dụng khối mũ khi bắt đầu.\n\n19\n00:00:51.210 --> 00:00:54.830\nKhối này có thể được sử dụng cho bất kỳ thiết lập nào mà rô bốt của bạn có thể cần\n\n20\n00:00:54.830 --> 00:00:58.160\nchẳng hạn như hiệu chỉnh một con quay hồi chuyển, thiết lập các biến\n\n21\n00:00:58.160 --> 00:01:00.060\nhoặc các cài đặt thiết bị khác.\n\n22\n00:01:00.060 --> 00:01:01.560\nNếu không cần thiết lập,\n\n23\n00:01:01.560 --> 00:01:04.960\nngăn xếp khi bắt đầu có thể vẫn trống.\n\n24\n00:01:04.960 --> 00:01:07.500\nTiếp theo, khi khối mũ tự động\n\n25\n00:01:07.500 --> 00:01:09.280\nđược sử dụng để điều khiển rô bốt của bạn\n\n26\n00:01:09.280 --> 00:01:12.810\ntrong phần tự trị của một trận đấu cạnh tranh.\n\n27\n00:01:12.810 --> 00:01:14.450\nCác khối được gắn vào ngăn xếp này\n\n28\n00:01:14.450 --> 00:01:17.660\nsẽ chạy khi trận đấu bắt đầu ở chế độ tự động.\n\n29\n00:01:17.660 --> 00:01:19.800\nNếu không có chế độ tự quản nào được mong muốn,\n\n30\n00:01:19.800 --> 00:01:22.780\nkhi ngăn xếp tự trị có thể vẫn trống.\n\n31\n00:01:22.780 --> 00:01:25.520\nCuối cùng, khi người lái xe điều khiển mũ chặn\n\n32\n00:01:25.520 --> 00:01:27.330\nđược sử dụng để điều khiển rô bốt của bạn\n\n33\n00:01:27.330 --> 00:01:30.960\ntrong phần điều khiển trình điều khiển của một trận đấu cạnh tranh.\n\n34\n00:01:30.960 --> 00:01:33.380\nCác khối được gắn vào ngăn xếp này sẽ chạy\n\n35\n00:01:33.380 --> 00:01:36.170\nkhi trận đấu bắt đầu chế độ điều khiển trình điều khiển.\n\n36\n00:01:36.170 --> 00:01:37.930\nVòng lặp mãi mãi được cung cấp,\n\n37\n00:01:37.930 --> 00:01:41.570\nvì hầu hết người dùng sẽ đặt các khối C có điều kiện trong ngăn xếp này\n\n38\n00:01:41.570 --> 00:01:44.760\nđể phản hồi đầu vào từ bộ điều khiển V5.\n\n39\n00:01:44.760 --> 00:01:47.500\nSau khi các ngăn xếp của bạn được tạo thành, rô bốt và dự án của bạn\n\n40\n00:01:47.500 --> 00:01:49.723\nsẽ sẵn sàng để cạnh tranh, chúc may mắn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\ncrwdns95644:0crwdne95644:0\n\n2\n00:00:02.700 --> 00:00:05.390\ncrwdns95646:0crwdne95646:0\n\n3\n00:00:05.390 --> 00:00:07.700\ncrwdns95648:0crwdne95648:0\n\n4\n00:00:07.700 --> 00:00:10.680\ncrwdns95650:0crwdne95650:0\n\n5\n00:00:10.680 --> 00:00:13.820\ncrwdns95652:0crwdne95652:0\n\n6\n00:00:13.820 --> 00:00:17.190\ncrwdns95654:0crwdne95654:0\n\n7\n00:00:17.190 --> 00:00:20.280\ncrwdns95656:0crwdne95656:0\n\n8\n00:00:20.280 --> 00:00:22.910\ncrwdns95658:0crwdne95658:0\n\n9\n00:00:22.910 --> 00:00:25.753\ncrwdns95660:0crwdne95660:0\n\n10\n00:00:26.610 --> 00:00:30.080\ncrwdns95662:0crwdne95662:0\n\n11\n00:00:30.080 --> 00:00:34.030\ncrwdns95664:0crwdne95664:0\n\n12\n00:00:34.030 --> 00:00:35.670\ncrwdns95666:0crwdne95666:0\n\n13\n00:00:35.670 --> 00:00:38.030\ncrwdns95668:0crwdne95668:0\n\n14\n00:00:38.030 --> 00:00:40.080\ncrwdns95670:0crwdne95670:0\n\n15\n00:00:40.080 --> 00:00:43.260\ncrwdns95672:0crwdne95672:0\n\n16\n00:00:43.260 --> 00:00:46.060\ncrwdns95674:0crwdne95674:0\n\n17\n00:00:46.060 --> 00:00:48.240\ncrwdns95676:0crwdne95676:0\n\n18\n00:00:48.240 --> 00:00:51.210\ncrwdns95678:0crwdne95678:0\n\n19\n00:00:51.210 --> 00:00:54.830\ncrwdns95680:0crwdne95680:0\n\n20\n00:00:54.830 --> 00:00:58.160\ncrwdns95682:0crwdne95682:0\n\n21\n00:00:58.160 --> 00:01:00.060\ncrwdns95684:0crwdne95684:0\n\n22\n00:01:00.060 --> 00:01:01.560\ncrwdns95686:0crwdne95686:0\n\n23\n00:01:01.560 --> 00:01:04.960\ncrwdns95688:0crwdne95688:0\n\n24\n00:01:04.960 --> 00:01:07.500\ncrwdns95690:0crwdne95690:0\n\n25\n00:01:07.500 --> 00:01:09.280\ncrwdns95692:0crwdne95692:0\n\n26\n00:01:09.280 --> 00:01:12.810\ncrwdns95694:0crwdne95694:0\n\n27\n00:01:12.810 --> 00:01:14.450\ncrwdns95696:0crwdne95696:0\n\n28\n00:01:14.450 --> 00:01:17.660\ncrwdns95698:0crwdne95698:0\n\n29\n00:01:17.660 --> 00:01:19.800\ncrwdns95700:0crwdne95700:0\n\n30\n00:01:19.800 --> 00:01:22.780\ncrwdns95702:0crwdne95702:0\n\n31\n00:01:22.780 --> 00:01:25.520\ncrwdns95704:0crwdne95704:0\n\n32\n00:01:25.520 --> 00:01:27.330\ncrwdns95706:0crwdne95706:0\n\n33\n00:01:27.330 --> 00:01:30.960\ncrwdns95708:0crwdne95708:0\n\n34\n00:01:30.960 --> 00:01:33.380\ncrwdns95710:0crwdne95710:0\n\n35\n00:01:33.380 --> 00:01:36.170\ncrwdns95712:0crwdne95712:0\n\n36\n00:01:36.170 --> 00:01:37.930\ncrwdns95714:0crwdne95714:0\n\n37\n00:01:37.930 --> 00:01:41.570\ncrwdns95716:0crwdne95716:0\n\n38\n00:01:41.570 --> 00:01:44.760\ncrwdns95718:0crwdne95718:0\n\n39\n00:01:44.760 --> 00:01:47.500\ncrwdns95720:0crwdne95720:0\n\n40\n00:01:47.500 --> 00:01:49.723\ncrwdns95722:0crwdne95722:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.310 --> 00:00:02.700\n<v Instructor>V5指令块程序</v>\n\n2\n00:00:02.700 --> 00:00:05.390\n让您的机器人备赛很容易。\n\n3\n00:00:05.390 --> 00:00:07.700\n一个已包含的样例\n\n4\n00:00:07.700 --> 00:00:10.680\n是VRC竞赛模板。\n\n5\n00:00:10.680 --> 00:00:13.820\n竞赛模板程序用于编写代码\n\n6\n00:00:13.820 --> 00:00:17.190\n来在竞赛的每个阶段命令您的机器人。\n\n7\n00:00:17.190 --> 00:00:20.280\n使用竞赛模板也确保您的机器人\n\n8\n00:00:20.280 --> 00:00:22.910\n是符合VRC的规则的，\n\n9\n00:00:22.910 --> 00:00:25.753\n并将正确地与竞赛进行通信。\n\n10\n00:00:26.610 --> 00:00:30.080\nVRC竞赛程序有三个部分，\n\n11\n00:00:30.080 --> 00:00:34.030\n设置，自动模式，以及操作手遥控模式。\n\n12\n00:00:34.030 --> 00:00:35.670\n在一场比赛中，\n\n13\n00:00:35.670 --> 00:00:38.030\n场地控制系统将负责\n\n14\n00:00:38.030 --> 00:00:40.080\n向机器人发送一条消息\n\n15\n00:00:40.080 --> 00:00:43.260\n来启动程序中正确的程序段，\n\n16\n00:00:43.260 --> 00:00:46.060\n以及停止其它的竞赛程序段。\n\n17\n00:00:46.060 --> 00:00:48.240\n欲开始您的竞赛模板，\n\n18\n00:00:48.240 --> 00:00:51.210\n首先使用“当开始”帽状指令块。\n\n19\n00:00:51.210 --> 00:00:54.830\n该指令块可被用于机器人可能需要的任何设置\n\n20\n00:00:54.830 --> 00:00:58.160\n比如校准一个陀螺仪，设定变量\n\n21\n00:00:58.160 --> 00:01:00.060\n或者其它设备设置。\n\n22\n00:01:00.060 --> 00:01:01.560\n如果不需要设置，\n\n23\n00:01:01.560 --> 00:01:04.960\n“当开始”指令块可以保持空白。\n\n24\n00:01:04.960 --> 00:01:07.500\n接下来，“当自动”帽状指令块\n\n25\n00:01:07.500 --> 00:01:09.280\n用于在比赛的自动时段\n\n26\n00:01:09.280 --> 00:01:12.810\n控制您的机器人。\n\n27\n00:01:12.810 --> 00:01:14.450\n连接到该指令段的指令块\n\n28\n00:01:14.450 --> 00:01:17.660\n将在比赛开始自动模式时运行。\n\n29\n00:01:17.660 --> 00:01:19.800\n如果不期望自动模式，\n\n30\n00:01:19.800 --> 00:01:22.780\n“当自动”指令段可以保持空白。\n\n31\n00:01:22.780 --> 00:01:25.520\n最后，“当遥控”帽状指令块\n\n32\n00:01:25.520 --> 00:01:27.330\n用于在比赛的自动时段\n\n33\n00:01:27.330 --> 00:01:30.960\n控制您的机器人。\n\n34\n00:01:30.960 --> 00:01:33.380\n连接到该指令段的指令块\n\n35\n00:01:33.380 --> 00:01:36.170\n将在比赛开始操作手遥控模式时运行。\n\n36\n00:01:36.170 --> 00:01:37.930\n提供了“永久循环”，\n\n37\n00:01:37.930 --> 00:01:41.570\n因为大多数用户将在此指令段中放置带条件的C型指令块\n\n38\n00:01:41.570 --> 00:01:44.760\n以响应来自V5遥控器的输入。\n\n39\n00:01:44.760 --> 00:01:47.500\n一旦您的指令段完成了，您的机器人和程序\n\n40\n00:01:47.500 --> 00:01:49.723\n将准备好去比赛，祝您好运。\n\n"}},{"thumb":"Tutorial_broadcasting.jpg","mov":"V5_Blocks_UsingEvents_V2","description":"Using Events","filter":"","placeholder":false,"vimeo":"475901295","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Sometimes, your robot may need</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nto perform multiple behaviors.\n\n3\n00:00:04.350 --> 00:00:06.400\nFor example, in programming,\n\n4\n00:00:06.400 --> 00:00:08.940\nmultiple stacks can communicate with each other\n\n5\n00:00:08.940 --> 00:00:11.760\nby signaling and handling events.\n\n6\n00:00:11.760 --> 00:00:13.980\nAn event then is like a message\n\n7\n00:00:13.980 --> 00:00:15.963\nfrom one programming stack to another.\n\n8\n00:00:17.040 --> 00:00:19.630\nNot only can events be signaled by blocks,\n\n9\n00:00:19.630 --> 00:00:22.693\nbut they can also be signaled by sensors and buttons.\n\n10\n00:00:23.860 --> 00:00:26.170\nIn a blocks project, blocks whose labels\n\n11\n00:00:26.170 --> 00:00:29.270\nbegan with broadcast, signal events.\n\n12\n00:00:29.270 --> 00:00:32.750\nBlocks whose labels began with when, handle events.\n\n13\n00:00:32.750 --> 00:00:36.890\nMeaning they trigger a block or stack of blocks to run.\n\n14\n00:00:36.890 --> 00:00:39.290\nIn this blocks project, the events blocks\n\n15\n00:00:39.290 --> 00:00:41.730\nthat begin with when, allow you to control\n\n16\n00:00:41.730 --> 00:00:43.300\nthe arm and claw motors\n\n17\n00:00:43.300 --> 00:00:45.373\nwith the buttons on the remote control.\n\n18\n00:00:46.950 --> 00:00:49.780\nThe broadcast block can signal events.\n\n19\n00:00:49.780 --> 00:00:51.960\nIn this project, the broadcast block\n\n20\n00:00:51.960 --> 00:00:55.010\nsignals a message for the robot to drive forward\n\n21\n00:00:55.010 --> 00:00:58.960\nfor 300 millimeters, and then to print a message.\n\n22\n00:00:58.960 --> 00:01:01.730\nThe when I receive block handles the events,\n\n23\n00:01:01.730 --> 00:01:04.090\ntriggering the robot to move forward.\n\n24\n00:01:04.090 --> 00:01:07.090\nThis allows both stacks of code to be run.\n\n25\n00:01:07.090 --> 00:01:10.170\nYou can also use a broadcast and wait block.\n\n26\n00:01:10.170 --> 00:01:12.763\nThis pauses one stack while the other one runs.\n\n27\n00:01:14.494 --> 00:01:16.190\nUsing events allows your robot\n\n28\n00:01:16.190 --> 00:01:18.373\nto complete more advanced behaviors.\n\n","ar":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>في بعض الأحيان قد يحتاج الروبوت الخاص بك</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nإلى أداء سلوكيات متعددة.\n\n3\n00:00:04.350 --> 00:00:06.400\nعلى سبيل المثال في البرمجة،\n\n4\n00:00:06.400 --> 00:00:08.940\nيمكن لوحدات متعددة التواصل مع بعضها البعض\n\n5\n00:00:08.940 --> 00:00:11.760\nعن طريق الإشارة والتعامل مع الأحداث.\n\n6\n00:00:11.760 --> 00:00:13.980\nالحدث بعد ذلك هو رسالة\n\n7\n00:00:13.980 --> 00:00:15.963\nمن مجموعة برمجة إلى أخرى.\n\n8\n00:00:17.040 --> 00:00:19.630\nلا يمكن فقط الإشارة إلى الأحداث بواسطة المقاطع،\n\n9\n00:00:19.630 --> 00:00:22.693\nو لكن يمكن أيضا الإشارة إليها بأجهزة الاستشعار و الأزرار.\n\n10\n00:00:23.860 --> 00:00:26.170\nفي مشروع الكتل البرمجية، كتل التي تسميها\n\n11\n00:00:26.170 --> 00:00:29.270\nمع أحداث إشارة البث.\n\n12\n00:00:29.270 --> 00:00:32.750\nالمقاطع التي تبدأ تسميتها ب''متى'', تتعامل مع الأحداث،.\n\n13\n00:00:32.750 --> 00:00:36.890\nيعني أنها تحفز مقطع أو مجموعة من المقاطع لتشغيلها.\n\n14\n00:00:36.890 --> 00:00:39.290\nفي هذا المشروع،مقاطع الأحداث\n\n15\n00:00:39.290 --> 00:00:41.730\nالذي يبدأ ب''متى'' تسمح لك بالتحكم\n\n16\n00:00:41.730 --> 00:00:43.300\nفي الذراع ومحركات المخلب\n\n17\n00:00:43.300 --> 00:00:45.373\nمع الأزرار على جهاز التحكم عن بعد.\n\n18\n00:00:46.950 --> 00:00:49.780\nيمكن مقاطع البث أن تشير إلى الأحداث.\n\n19\n00:00:49.780 --> 00:00:51.960\nفي هذا المشروع،مقاطع الأحداث\n\n20\n00:00:51.960 --> 00:00:55.010\nتشير إلى رسالة للروبوت ليقود إلى الأمام\n\n21\n00:00:55.010 --> 00:00:58.960\nلمدة 300 ملليمتر، ثم لطباعة رسالة.\n\n22\n00:00:58.960 --> 00:01:01.730\nمقطع ''عندما أتلقى\" يتولى الحدث,\n\n23\n00:01:01.730 --> 00:01:04.090\nتحفيز الروبوت للتحرك إلى الأمام.\n\n24\n00:01:04.090 --> 00:01:07.090\nوهذا يسمح بتشغيل كلاً من المجموعات المبرمجة.\n\n25\n00:01:07.090 --> 00:01:10.170\nيمكنك أيضًا استخدام مقطع الإرسال و الانتظار.\n\n26\n00:01:10.170 --> 00:01:12.763\nو يوقف هذا مجموعة واحد بينما تعمل المجموعة الآخر.\n\n27\n00:01:14.494 --> 00:01:16.190\nاستخدام الأحداث يسمح للروبوت الخاص بك\n\n28\n00:01:16.190 --> 00:01:18.373\nلإكمال المزيد من السلوكيات المتقدمة.\n\n","cs":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Občas může tvůj robot potřebovat</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nprovést několik chování.\n\n3\n00:00:04.350 --> 00:00:06.400\nNapříklad v programování\n\n4\n00:00:06.400 --> 00:00:08.940\nspolu může komunikovat několik zásobníků instrukcí\n\n5\n00:00:08.940 --> 00:00:11.760\npomocí signalizace a řízení událostí.\n\n6\n00:00:11.760 --> 00:00:13.980\nUdálost je jako zpráva\n\n7\n00:00:13.980 --> 00:00:15.963\nod jednoho programovacího zásobníku druhému.\n\n8\n00:00:17.040 --> 00:00:19.630\nNejenže mohou být události signalizovány bloky,\n\n9\n00:00:19.630 --> 00:00:22.693\nale mohou být také signalizovány senzory a tlačítky.\n\n10\n00:00:23.860 --> 00:00:26.170\nV blokovém projektu bloky, jejichž popisek\n\n11\n00:00:26.170 --> 00:00:29.270\nzačíná Vyšli, signalizují události.\n\n12\n00:00:29.270 --> 00:00:32.750\nBloky, jejichž popisky začínají Když, řídí události.\n\n13\n00:00:32.750 --> 00:00:36.890\nTo znamená, že spouštějí blok nebo zásobník bloků.\n\n14\n00:00:36.890 --> 00:00:39.290\nV tomto blokovém projektu bloky událostí,\n\n15\n00:00:39.290 --> 00:00:41.730\nkteré začínají Když, ti umožňují řídit\n\n16\n00:00:41.730 --> 00:00:43.300\nmotory ramene a drapáku\n\n17\n00:00:43.300 --> 00:00:45.373\npomocí tlačítek na dálkovém ovládání.\n\n18\n00:00:46.950 --> 00:00:49.780\nBlok Vyšli může signalizovat události.\n\n19\n00:00:49.780 --> 00:00:51.960\nV tomto projektu blok Vyšli\n\n20\n00:00:51.960 --> 00:00:55.010\nsignalizuje zprávu pro robota, aby jel dopředu\n\n21\n00:00:55.010 --> 00:00:58.960\no 300 milimetrů a potom vypsal zprávů.\n\n22\n00:00:58.960 --> 00:01:01.730\nBlok Po obdržení zprávy řídí událost\n\n23\n00:01:01.730 --> 00:01:04.090\nspuštěním pohybu robota dopředu.\n\n24\n00:01:04.090 --> 00:01:07.090\nTo umožňuje běh obou zásobníků kódu.\n\n25\n00:01:07.090 --> 00:01:10.170\nMůžeš také použít blok Vyšli a čekej.\n\n26\n00:01:10.170 --> 00:01:12.763\nTo pozastaví jeden zásobník, zatímco druhý běží.\n\n27\n00:01:14.494 --> 00:01:16.190\nPoužívání událostí umožňuje tvému robotovi\n\n28\n00:01:16.190 --> 00:01:18.373\ndokončit pokročilejší chování.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>A veces su robot puede necesitar</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nejecutar múltiples comportamientos.\n\n3\n00:00:04.350 --> 00:00:06.400\nPor ejemplo, en programación,\n\n4\n00:00:06.400 --> 00:00:08.940\nmúltiples pilas pueden comunicarse entre sí\n\n5\n00:00:08.940 --> 00:00:11.760\nindicando y manejando eventos.\n\n6\n00:00:11.760 --> 00:00:13.980\nUn evento, \"Entonces\", es como un mensaje\n\n7\n00:00:13.980 --> 00:00:15.963\nde una pila de programación a otra.\n\n8\n00:00:17.040 --> 00:00:19.630\nLos eventos no sólo pueden ser señalados por bloques,\n\n9\n00:00:19.630 --> 00:00:22.693\nsino también pueden ser señalizados por sensores y botones.\n\n10\n00:00:23.860 --> 00:00:26.170\nEn un proyecto de bloques, bloques con etiquetas\n\n11\n00:00:26.170 --> 00:00:29.270\nque comienza con Transmitir, señalan eventos.\n\n12\n00:00:29.270 --> 00:00:32.750\nBloques que tienen etiquetas que comienzan con eventos de \"Cuando\", manejan eventos.\n\n13\n00:00:32.750 --> 00:00:36.890\nSignificando que activan un bloque de pila de bloques a ejecutar.\n\n14\n00:00:36.890 --> 00:00:39.290\nEn este proyecto de bloques, los bloques de eventos\n\n15\n00:00:39.290 --> 00:00:41.730\nque comienzan con \"cuando\" le permita controlar\n\n16\n00:00:41.730 --> 00:00:43.300\nlos motores de brazo y garra\n\n17\n00:00:43.300 --> 00:00:45.373\ncon los botones del control.\n\n18\n00:00:46.950 --> 00:00:49.780\nEl bloque de transmisión puede señalar eventos.\n\n19\n00:00:49.780 --> 00:00:51.960\nEn este proyecto, el bloque de transmitir\n\n20\n00:00:51.960 --> 00:00:55.010\nseñala un mensaje para que el robot avance\n\n21\n00:00:55.010 --> 00:00:58.960\npara 300 milímetros, y luego para imprimir un mensaje.\n\n22\n00:00:58.960 --> 00:01:01.730\nEl bloque de \"Cuando Recibo\" maneja los eventos,\n\n23\n00:01:01.730 --> 00:01:04.090\nactivando el robot para avanzar.\n\n24\n00:01:04.090 --> 00:01:07.090\nEsto permite que ambas pilas de código sean ejecutadas.\n\n25\n00:01:07.090 --> 00:01:10.170\nTambién puedes usar una bloque de emisión y esperar.\n\n26\n00:01:10.170 --> 00:01:12.763\nEsto pausa una pila mientras la otra se ejecuta.\n\n27\n00:01:14.494 --> 00:01:16.190\nEl uso de Eventos permite que su robot\n\n28\n00:01:16.190 --> 00:01:18.373\ncompletar comportamientos más avanzados.\n\n","es":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>A veces su robot puede necesitar</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nejecutar múltiples comportamientos.\n\n3\n00:00:04.350 --> 00:00:06.400\nPor ejemplo, en programación,\n\n4\n00:00:06.400 --> 00:00:08.940\nmúltiples pilas pueden comunicarse entre sí\n\n5\n00:00:08.940 --> 00:00:11.760\nindicando y manejando eventos.\n\n6\n00:00:11.760 --> 00:00:13.980\nUn evento, entonces, es como un mensaje\n\n7\n00:00:13.980 --> 00:00:15.963\nde una pila de programación a otra.\n\n8\n00:00:17.040 --> 00:00:19.630\nLos eventos no sólo pueden ser señalados por bloques,\n\n9\n00:00:19.630 --> 00:00:22.693\nsino también pueden ser señalizados por sensores y botones.\n\n10\n00:00:23.860 --> 00:00:26.170\nEn un proyecto de bloques, bloques con etiquetas\n\n11\n00:00:26.170 --> 00:00:29.270\nque comienza con Transmitir, señalan eventos.\n\n12\n00:00:29.270 --> 00:00:32.750\nBloques que tienen etiquetas que comienzan con eventos de \"Cuando\", manejan eventos.\n\n13\n00:00:32.750 --> 00:00:36.890\nSignificando que activan un bloque de pila de bloques a ejecutar.\n\n14\n00:00:36.890 --> 00:00:39.290\nEn este proyecto de bloques, los bloques de eventos\n\n15\n00:00:39.290 --> 00:00:41.730\nque comienzan con \"cuando\" le permita controlar\n\n16\n00:00:41.730 --> 00:00:43.300\nlos motores de brazo y garra\n\n17\n00:00:43.300 --> 00:00:45.373\ncon los botones del control.\n\n18\n00:00:46.950 --> 00:00:49.780\nEl bloque de transmisión puede señalar eventos.\n\n19\n00:00:49.780 --> 00:00:51.960\nEn este proyecto, el bloque de transmitir\n\n20\n00:00:51.960 --> 00:00:55.010\nseñala un mensaje para que el robot avance\n\n21\n00:00:55.010 --> 00:00:58.960\npara 300 milímetros, y luego para imprimir un mensaje.\n\n22\n00:00:58.960 --> 00:01:01.730\nEl bloque de \"Cuando Recibo\" maneja los eventos,\n\n23\n00:01:01.730 --> 00:01:04.090\nactivando el robot para avanzar.\n\n24\n00:01:04.090 --> 00:01:07.090\nEsto permite que ambas pilas de código sean ejecutadas.\n\n25\n00:01:07.090 --> 00:01:10.170\nTambién puedes usar una bloque de emisión y esperar.\n\n26\n00:01:10.170 --> 00:01:12.763\nEsto pausa una pila mientras la otra se ejecuta.\n\n27\n00:01:14.494 --> 00:01:16.190\nEl uso de Eventos permite que su robot\n\n28\n00:01:16.190 --> 00:01:18.373\ncompletar comportamientos más avanzados.\n\n","fi":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Joskus robottisi täytyy</v>\n\n2\n00:00:02.170 --> 00:00:04.350\ntehdä useampia toimenpiteitä.\n\n3\n00:00:04.350 --> 00:00:06.400\nEsimerkiksi ohjelmoinnissa\n\n4\n00:00:06.400 --> 00:00:08.940\nuseampi rinnakkainen prosessi pitää keskustella toistensa kanssa\n\n5\n00:00:08.940 --> 00:00:11.760\nviestittämällä ja eri tapahtumiin reagoimalla.\n\n6\n00:00:11.760 --> 00:00:13.980\nTapahtuma on kuin lähettäisi viestin\n\n7\n00:00:13.980 --> 00:00:15.963\nyhdestä pinosta blokkeja toiseen.\n\n8\n00:00:17.040 --> 00:00:19.630\nTapahtumia ei pelkästään käynnistä muut blokit\n\n9\n00:00:19.630 --> 00:00:22.693\nvaan myös anturit antamat arvot tai ohjaimen painonappien painaminen voi käynnistää uusia toimenpiteitä.\n\n10\n00:00:23.860 --> 00:00:26.170\nOhjelmassa ne tapahtumablokit, joissa on\n\n11\n00:00:26.170 --> 00:00:29.270\nmerkitty joku aloitusviesti, ottaa vastaan käskytapahtumia.\n\n12\n00:00:29.270 --> 00:00:32.750\nBlokit, jotka ovat valittavissa Tapahtuma valinta, ovat blokkeja, jotka voivat käynnistää toimenpiteitä.\n\n13\n00:00:32.750 --> 00:00:36.890\nTapahtumablokit reagoivat haluttuun signaaliin ja suorittavat sen alla olevat toimenpiteet.\n\n14\n00:00:36.890 --> 00:00:39.290\nTässä ohjelmassa tapahtumablokit,\n\n15\n00:00:39.290 --> 00:00:41.730\njotka alkavat Kun -sanalla, antaa sinulle mahdollisuuden\n\n16\n00:00:41.730 --> 00:00:43.300\nohjata käsi- ja kouramoottoreita\n\n17\n00:00:43.300 --> 00:00:45.373\nohjaimen tietyistä painonapeista.\n\n18\n00:00:46.950 --> 00:00:49.780\nLähetysblokki voi käynnistää signaalin tapahtumasta.\n\n19\n00:00:49.780 --> 00:00:51.960\nTässä esimerkissä Lähetä viesti-blokki\n\n20\n00:00:51.960 --> 00:00:55.010\nantaa signaalin robotille ajaa eteenpäin\n\n21\n00:00:55.010 --> 00:00:58.960\n300 mm ja sitten tulostaa näytölle viestin.\n\n22\n00:00:58.960 --> 00:01:01.730\nKun saan viestin -blokki ottaa vastaan kutsun,\n\n23\n00:01:01.730 --> 00:01:04.090\nja käynnistää robotin liikkeen eteenpäin.\n\n24\n00:01:04.090 --> 00:01:07.090\nMolemmat blokkipinot, kutsuja ja kutsuttu suoritetaan yhtäaikaa.\n\n25\n00:01:07.090 --> 00:01:10.170\nVoit myös jäädä odottamaan kutsutun blokkipinon suoritusta valisemalla optio Ja odota.\n\n26\n00:01:10.170 --> 00:01:12.763\nTämä pysäyttää kutsuvan blokkipinon suorituksen kunnes kusuttu pino on loppuun suoritettu.\n\n27\n00:01:14.494 --> 00:01:16.190\nKäyttämällä tapahtumia robotti pystyy\n\n28\n00:01:16.190 --> 00:01:18.373\nsuorittamaan monimutkaisempia tehtäviä.\n\n","fr":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Parfois, votre robot peut avoir besoin</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nd'adopter plusieurs comportements.\n\n3\n00:00:04.350 --> 00:00:06.400\nPar exemple, dans la programmation,\n\n4\n00:00:06.400 --> 00:00:08.940\nplusieurs piles peuvent communiquer entre elles\n\n5\n00:00:08.940 --> 00:00:11.760\nen signalant et en gérant des événements.\n\n6\n00:00:11.760 --> 00:00:13.980\nUn événement est donc comme un message\n\n7\n00:00:13.980 --> 00:00:15.963\nd'une pile de programmation à une autre.\n\n8\n00:00:17.040 --> 00:00:19.630\nNon seulement les événements peuvent être signalés par des blocs,\n\n9\n00:00:19.630 --> 00:00:22.693\nmais ils peuvent aussi être initiés par des capteurs et boutons.\n\n10\n00:00:23.860 --> 00:00:26.170\nDans un projet par blocs, les blocs dont les étiquettes\n\n11\n00:00:26.170 --> 00:00:29.270\ncommencent par \"Envoyer\" initie des évènements.\n\n12\n00:00:29.270 --> 00:00:32.750\nLes blocs dont les libellés commencent par \"Lorsque\" gèrent les événements.\n\n13\n00:00:32.750 --> 00:00:36.890\nCe qui signifie qu'ils déclenchent un bloc ou une pile de blocs à exécuter.\n\n14\n00:00:36.890 --> 00:00:39.290\nDans ce projet par blocs, les blocs d'événements\n\n15\n00:00:39.290 --> 00:00:41.730\nqui commencent par \"Lorsque\" vous permettent de contrôler\n\n16\n00:00:41.730 --> 00:00:43.300\nles moteurs du bras et de la pince\n\n17\n00:00:43.300 --> 00:00:45.373\navec les boutons de la manette.\n\n18\n00:00:46.950 --> 00:00:49.780\nLe bloc \"Envoyer\" peut signaler des événements.\n\n19\n00:00:49.780 --> 00:00:51.960\nDans ce projet, le bloc d'envoi\n\n20\n00:00:51.960 --> 00:00:55.010\ninitie un message pour que le robot avance\n\n21\n00:00:55.010 --> 00:00:58.960\nde 300 millimètres, puis affiche un message.\n\n22\n00:00:58.960 --> 00:01:01.730\nLe bloc \"Lorsque je reçois\" gère l'événement,\n\n23\n00:01:01.730 --> 00:01:04.090\ndéclenchant le mouvement vers l'avant du robot.\n\n24\n00:01:04.090 --> 00:01:07.090\nCela permet aux deux piles de code d'être exécutées.\n\n25\n00:01:07.090 --> 00:01:10.170\nVous pouvez également utiliser un bloc \"Envoyer et attendre\".\n\n26\n00:01:10.170 --> 00:01:12.763\nCela met une pile en pause pendant que l'autre s'exécute.\n\n27\n00:01:14.494 --> 00:01:16.190\nUtiliser des événements permet à votre robot\n\n28\n00:01:16.190 --> 00:01:18.373\nd'adopter des comportements plus élaborés.\n\n","ko":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>때로는 로봇이</v>\n\n2\n00:00:02.170 --> 00:00:04.350\n여러 가지 동작을 수행해야 할 수도 있습니다.\n\n3\n00:00:04.350 --> 00:00:06.400\n예를 들어 프로그래밍에서\n\n4\n00:00:06.400 --> 00:00:08.940\n여러 스택은 신호를 보내고 이벤트를 처리함으로써\n\n5\n00:00:08.940 --> 00:00:11.760\n서로 통신할 수 있습니다.\n\n6\n00:00:11.760 --> 00:00:13.980\n이벤트는 한 프로그래밍 스택에서\n\n7\n00:00:13.980 --> 00:00:15.963\n다른 프로그래밍 스택으로 보내는 메시지와 같습니다.\n\n8\n00:00:17.040 --> 00:00:19.630\n이벤트는 블록에 의해 신호를 받을 수 있을 뿐만 아니라\n\n9\n00:00:19.630 --> 00:00:22.693\n센서와 버튼으로도 신호를 받을 수 있습니다.\n\n10\n00:00:23.860 --> 00:00:26.170\n블록 프로젝트에서\n\n11\n00:00:26.170 --> 00:00:29.270\n\"신호 보내기\" 레이블로 시작하는 블록은 이벤트에 신호를 보냅니다.\n\n12\n00:00:29.270 --> 00:00:32.750\n레이블이 '~할 때'로 시작하는 블록은 이벤트를 처리합니다.\n\n13\n00:00:32.750 --> 00:00:36.890\n즉 블록 또는 블록 스택이 실행되도록 작동시킵니다.\n\n14\n00:00:36.890 --> 00:00:39.290\n이 블록 프로젝트에서\n\n15\n00:00:39.290 --> 00:00:41.730\n\"~할 때\"로 시작하는 이벤트 블록을 사용하면\n\n16\n00:00:41.730 --> 00:00:43.300\n리모컨의 버튼으로 팔과 집게발 모터를\n\n17\n00:00:43.300 --> 00:00:45.373\n제어할 수 있습니다.\n\n18\n00:00:46.950 --> 00:00:49.780\n'신호 보내기' 블록은 이벤트를 신호할 수 있습니다.\n\n19\n00:00:49.780 --> 00:00:51.960\n이 프로젝트에서 '신호 보내기' 블록은\n\n20\n00:00:51.960 --> 00:00:55.010\n로봇이 300mm 전진한 다음\n\n21\n00:00:55.010 --> 00:00:58.960\n메시지를 출력하라는 메시지를 보냅니다.\n\n22\n00:00:58.960 --> 00:01:01.730\n'신호 받을 때' 블록은\n\n23\n00:01:01.730 --> 00:01:04.090\n로봇이 앞으로 이동하도록 작동시키는 이벤트를 처리합니다.\n\n24\n00:01:04.090 --> 00:01:07.090\n이렇게 하면 두 코드 스택이 모두 실행될 수 있습니다.\n\n25\n00:01:07.090 --> 00:01:10.170\n'신호 보내기'와 '기다리기' 블록을 사용할 수도 있습니다.\n\n26\n00:01:10.170 --> 00:01:12.763\n이렇게 하면 다른 스택이 실행되는 동안 한 스택이 일시 중지됩니다.\n\n27\n00:01:14.494 --> 00:01:16.190\n이벤트를 사용하면 로봇이\n\n28\n00:01:16.190 --> 00:01:18.373\n보다 고급 동작을 할 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Kartais Jūsų robotui gali reikėti</v>\n\n2\n00:00:02.170 --> 00:00:04.350\natlikti kelias funkcijas.\n\n3\n00:00:04.350 --> 00:00:06.400\nPavyzdžiui, programavime,\n\n4\n00:00:06.400 --> 00:00:08.940\nkelios blokų krūvos gali komunikuoti viena su kita,\n\n5\n00:00:08.940 --> 00:00:11.760\npranešdamos apie ir tvarkydamos įvykius.\n\n6\n00:00:11.760 --> 00:00:13.980\nĮvykis yra tarsi vienos programavimo krūvos\n\n7\n00:00:13.980 --> 00:00:15.963\npranešimas kitai programavimo krūvai.\n\n8\n00:00:17.040 --> 00:00:19.630\nNe vien blokai, bet ir jutikliai bei mygtukai\n\n9\n00:00:19.630 --> 00:00:22.693\ngali pranešti apie įvykius.\n\n10\n00:00:23.860 --> 00:00:26.170\nBlokų projekte, blokai, kurių žymos\n\n11\n00:00:26.170 --> 00:00:29.270\nprasideda transliavimu, perduoda įvykius.\n\n12\n00:00:29.270 --> 00:00:32.750\nBlokai, kurių žymos prasideda \"kada\", tvarko įvykius.\n\n13\n00:00:32.750 --> 00:00:36.890\nTai reiškia, kad jie paleidžia bloką arba jų krūvą.\n\n14\n00:00:36.890 --> 00:00:39.290\nŠiame blokų projekte, įvykių blokai,\n\n15\n00:00:39.290 --> 00:00:41.730\nkurie prasideda \"kada\", leidžia valdyti\n\n16\n00:00:41.730 --> 00:00:43.300\npeties ir letenos variklius\n\n17\n00:00:43.300 --> 00:00:45.373\nnuotolinio pultelio mygtukais.\n\n18\n00:00:46.950 --> 00:00:49.780\nTransliavimo blokas gali pranešti apie įvykius.\n\n19\n00:00:49.780 --> 00:00:51.960\nŠiame projekte, transliavimo blokas\n\n20\n00:00:51.960 --> 00:00:55.010\nperduoda žinutę robotui važiuoti į priekį\n\n21\n00:00:55.010 --> 00:00:58.960\n300 mm ir atspausdinti žinutę.\n\n22\n00:00:58.960 --> 00:01:01.730\nBlokas \"kai gaunu\" tvarko įvykius,\n\n23\n00:01:01.730 --> 00:01:04.090\nliepia robotui judėti į priekį.\n\n24\n00:01:04.090 --> 00:01:07.090\nTai leidžia veikti abejoms kodo krūvoms.\n\n25\n00:01:07.090 --> 00:01:10.170\nTaip pat galite naudoti transliavimo ir laukimo blokus.\n\n26\n00:01:10.170 --> 00:01:12.763\nKol viena krūva paleidžiama, kita sustabdoma.\n\n27\n00:01:14.494 --> 00:01:16.190\nĮvykių naudojimas leidžia Jūsų robotui\n\n28\n00:01:16.190 --> 00:01:18.373\natlikti pažangesnes funkcijas.\n\n","lv":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Dažkārt robotam var būt nepieciešams</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nveikt vairākas darbības.\n\n3\n00:00:04.350 --> 00:00:06.400\nPiemēram, programmēšanā,\n\n4\n00:00:06.400 --> 00:00:08.940\nvairāki kombinētie bloki var savstarpēji sazināties,\n\n5\n00:00:08.940 --> 00:00:11.760\nsignalizējot un rīkojoties ar notikumiem.\n\n6\n00:00:11.760 --> 00:00:13.980\nNotikums šādā gadījumā ir kā ziņa\n\n7\n00:00:13.980 --> 00:00:15.963\nno viena programmēšanas bloka uz citu.\n\n8\n00:00:17.040 --> 00:00:19.630\nNe tikai notikumus var norādīt ar blokiem,\n\n9\n00:00:19.630 --> 00:00:22.693\nbet tos var norādīt arī ar sensoriem un pogām.\n\n10\n00:00:23.860 --> 00:00:26.170\nBloku projektā bloki, kuru apzīmējums\n\n11\n00:00:26.170 --> 00:00:29.270\nSākas ar apraides, signālu notikumiem.\n\n12\n00:00:29.270 --> 00:00:32.750\nBloki, kuru apzīmējums atbilst notikumiem “When”, “Handle”.\n\n13\n00:00:32.750 --> 00:00:36.890\nNozīmē, ka tie darbina bloku vai saliktos blokus.\n\n14\n00:00:36.890 --> 00:00:39.290\nŠajā bloku projektā notikumu bloki,\n\n15\n00:00:39.290 --> 00:00:41.730\nkas sākas ar “When”, ļauj vadīt\n\n16\n00:00:41.730 --> 00:00:43.300\nrokas un spīles motorus\n\n17\n00:00:43.300 --> 00:00:45.373\nar tālvadības pults pogām.\n\n18\n00:00:46.950 --> 00:00:49.780\nApraides bloks var signalizēt par notikumiem.\n\n19\n00:00:49.780 --> 00:00:51.960\nŠajā projektā apraides bloki\n\n20\n00:00:51.960 --> 00:00:55.010\nnodod ziņu robotam, ka jāvirzās uz priekšu\n\n21\n00:00:55.010 --> 00:00:58.960\npar 300 milimetriem un pēc tam jāizdrukā ziņojumu.\n\n22\n00:00:58.960 --> 00:01:01.730\nKad bloks “When I receive” apstrādā notikumu,\n\n23\n00:01:01.730 --> 00:01:04.090\nuz priekšu tiek virzīts robots.\n\n24\n00:01:04.090 --> 00:01:07.090\nTas ļauj izpildīt abas kodu paketes.\n\n25\n00:01:07.090 --> 00:01:10.170\nVar izmantot arī apraides un gaidīšanas bloku.\n\n26\n00:01:10.170 --> 00:01:12.763\nTas aptur vienu paketi, kamēr tiek palaista otra.\n\n27\n00:01:14.494 --> 00:01:16.190\nNotikumu izmantošana ļauj izmantot robotu,\n\n28\n00:01:16.190 --> 00:01:18.373\npaveicot sarežģītākas darbības.\n\n","nl":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Soms kan uw robot het nodig hebben</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nom meerdere gedragingen uit te voeren.\n\n3\n00:00:04.350 --> 00:00:06.400\nBij het programmeren\n\n4\n00:00:06.400 --> 00:00:08.940\nkunnen bijvoorbeeld meerdere stapels met elkaar communiceren\n\n5\n00:00:08.940 --> 00:00:11.760\ndoor gebeurtenissen te signaleren en af te handelen.\n\n6\n00:00:11.760 --> 00:00:13.980\nEen gebeurtenis lijkt dan op een bericht\n\n7\n00:00:13.980 --> 00:00:15.963\nvan de ene programmeerstapel naar de andere.\n\n8\n00:00:17.040 --> 00:00:19.630\nGebeurtenissen kunnen niet alleen worden gesignaleerd door blokken,\n\n9\n00:00:19.630 --> 00:00:22.693\nmaar ze kunnen ook worden gesignaleerd door sensoren en knoppen.\n\n10\n00:00:23.860 --> 00:00:26.170\nIn een blokkenproject, blokken waarvan de labels\n\n11\n00:00:26.170 --> 00:00:29.270\nbegonnen met uitzending, signaleren gebeurtenissen.\n\n12\n00:00:29.270 --> 00:00:32.750\nBlokken waarvan de labels beginnen met \"wanneer\", behandelen gebeurtenissen.\n\n13\n00:00:32.750 --> 00:00:36.890\nWat betekent dat ze een blok of stapel blokken activeren om uit te voeren.\n\n14\n00:00:36.890 --> 00:00:39.290\nIn dit blokkenproject stellen de gebeurtenissenblokken\n\n15\n00:00:39.290 --> 00:00:41.730\ndie beginnen met \"wanneer\", u in staat\n\n16\n00:00:41.730 --> 00:00:43.300\nom de arm- en klauwmotoren\n\n17\n00:00:43.300 --> 00:00:45.373\nmet de knoppen op de afstandsbediening.\n\n18\n00:00:46.950 --> 00:00:49.780\nHet uitzendingsblok kan gebeurtenissen signaleren.\n\n19\n00:00:49.780 --> 00:00:51.960\nIn dit project geeft het uitzendblok\n\n20\n00:00:51.960 --> 00:00:55.010\neen bericht aan de robot om\n\n21\n00:00:55.010 --> 00:00:58.960\n300 millimeter voorwaarts te rijden en vervolgens een bericht af te drukken.\n\n22\n00:00:58.960 --> 00:01:01.730\nHet wanneer ik ontvang blok behandelt de gebeurtenis,\n\n23\n00:01:01.730 --> 00:01:04.090\ndie de robot triggert om voorwaarts te bewegen.\n\n24\n00:01:04.090 --> 00:01:07.090\nHierdoor kunnen beide stapels code worden uitgevoerd.\n\n25\n00:01:07.090 --> 00:01:10.170\nU kunt ook een uitzending en een wacht blok gebruiken.\n\n26\n00:01:10.170 --> 00:01:12.763\nDit pauzeert de ene stapel terwijl de andere wordt uitgevoerd.\n\n27\n00:01:14.494 --> 00:01:16.190\nDoor gebeurtenissen te gebruiken, kan uw robot\n\n28\n00:01:16.190 --> 00:01:18.373\nmeer geavanceerde gedragingen voltooien.\n\n","pl":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Czasami Twój robot może potrzebować</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nwykonać wiele zadań.\n\n3\n00:00:04.350 --> 00:00:06.400\nNa przykład w programowaniu,\n\n4\n00:00:06.400 --> 00:00:08.940\nwiele stosów może komunikować się ze sobą\n\n5\n00:00:08.940 --> 00:00:11.760\npoprzez sygnalizację i obsługę zdarzeń.\n\n6\n00:00:11.760 --> 00:00:13.980\nWydarzenie jest więc jak wiadomość\n\n7\n00:00:13.980 --> 00:00:15.963\nz jednego stosu programowania do innego.\n\n8\n00:00:17.040 --> 00:00:19.630\nNie tylko zdarzenia mogą być sygnalizowane przez bloki,\n\n9\n00:00:19.630 --> 00:00:22.693\nale mogą być również sygnalizowane przez czujniki i przyciski.\n\n10\n00:00:23.860 --> 00:00:26.170\nW projekcie blokowym bloki, których etykiety\n\n11\n00:00:26.170 --> 00:00:29.270\nrozpoczął się od nadawania, wydarzeń sygnałowych.\n\n12\n00:00:29.270 --> 00:00:32.750\nBloki, których etykiety zaczynają się od \"kiedy\" - obsługują wydarzenia.\n\n13\n00:00:32.750 --> 00:00:36.890\nCo oznacza, że uruchamiają blok lub stos bloków.\n\n14\n00:00:36.890 --> 00:00:39.290\nW tym projekcie bloki zdarzeń\n\n15\n00:00:39.290 --> 00:00:41.730\nzaczynają się od \"kiedy\" pozwalają kontrolować\n\n16\n00:00:41.730 --> 00:00:43.300\nsilniki ramienia i kleszczy\n\n17\n00:00:43.300 --> 00:00:45.373\nprzyciskami zdalnego sterowania.\n\n18\n00:00:46.950 --> 00:00:49.780\nBlok transmisji może sygnalizować zdarzenia.\n\n19\n00:00:49.780 --> 00:00:51.960\nW tym projekcie blok nadawania\n\n20\n00:00:51.960 --> 00:00:55.010\nsygnalizuje robotowi by jechał do przodu\n\n21\n00:00:55.010 --> 00:00:58.960\ndla 300 milimetrów, a następnie wydrukuj wiadomość.\n\n22\n00:00:58.960 --> 00:01:01.730\nKiedy otrzymam blok obsługujący wydarzenie,\n\n23\n00:01:01.730 --> 00:01:04.090\nwyzwala on ruch robota do przodu.\n\n24\n00:01:04.090 --> 00:01:07.090\nPozwala to na uruchomienie obu stosów kodu.\n\n25\n00:01:07.090 --> 00:01:10.170\nMożesz również użyć transmisji i bloku oczekiwania.\n\n26\n00:01:10.170 --> 00:01:12.763\nTo wstrzymuje jeden stos, podczas gdy drugi jest uruchomiony.\n\n27\n00:01:14.494 --> 00:01:16.190\nUżywanie zdarzeń pozwala na użycie robota\n\n28\n00:01:16.190 --> 00:01:18.373\naby wykonywać bardziej zaawansowane zadania.\n\n","ru":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Иногда роботу может понадобиться</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nвыполнять несколько действий.\n\n3\n00:00:04.350 --> 00:00:06.400\nНапример, при программировании\n\n4\n00:00:06.400 --> 00:00:08.940\nстеки могут взаимодействовать между собой\n\n5\n00:00:08.940 --> 00:00:11.760\nпосредством подачи сигналов и обработки событий.\n\n6\n00:00:11.760 --> 00:00:13.980\nОбработка событий представляет собой\n\n7\n00:00:13.980 --> 00:00:15.963\nсообщение от одного стека к другому.\n\n8\n00:00:17.040 --> 00:00:19.630\nПомимо сообщений, блоки могут получать\n\n9\n00:00:19.630 --> 00:00:22.693\nинформацию посредством датчиков и кнопок.\n\n10\n00:00:23.860 --> 00:00:26.170\nВ блоковом проекте, блоки помеченные\n\n11\n00:00:26.170 --> 00:00:29.270\n\"передать\" или \"получить\", являются сигнальными.\n\n12\n00:00:29.270 --> 00:00:32.750\nБлоки, начинающиеся с \"когда\", обрабатывают события.\n\n13\n00:00:32.750 --> 00:00:36.890\nТакие блоки запускают последовательность блоков.\n\n14\n00:00:36.890 --> 00:00:39.290\nВ проекте блоки событий,\n\n15\n00:00:39.290 --> 00:00:41.730\nначинающиеся с \"когда\", позволяют контролировать руку\n\n16\n00:00:41.730 --> 00:00:43.300\nи схват робота\n\n17\n00:00:43.300 --> 00:00:45.373\nкнопками на пульте управления.\n\n18\n00:00:46.950 --> 00:00:49.780\nБлоки передачи могут обрабатывать сигналы.\n\n19\n00:00:49.780 --> 00:00:51.960\nВ проекте блоки передачи,\n\n20\n00:00:51.960 --> 00:00:55.010\nотправляют сигнал роботу для движения вперёд\n\n21\n00:00:55.010 --> 00:00:58.960\nна 300 мм, а затем выводит сообщение на экран.\n\n22\n00:00:58.960 --> 00:01:01.730\nПосле обработки принимающим блоком событий,\n\n23\n00:01:01.730 --> 00:01:04.090\nробот движется вперёд.\n\n24\n00:01:04.090 --> 00:01:07.090\nЭто позволяет запустить оба стека.\n\n25\n00:01:07.090 --> 00:01:10.170\nВы также можете использовать блоки передачи и ожидания.\n\n26\n00:01:10.170 --> 00:01:12.763\nЭто приостанавливает один стек, в то время как другой выполняется.\n\n27\n00:01:14.494 --> 00:01:16.190\nИспользование событий позволяет роботу\n\n28\n00:01:16.190 --> 00:01:18.373\nсовершать более сложные действия.\n\n","th":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator> บางครั้งหุ่นยนต์ของคุณอาจต้อง </v>\n\n2\n00:00:02.170 --> 00:00:04.350\nแสดงพฤติกรรมหลายอย่าง\n\n3\n00:00:04.350 --> 00:00:06.400\nตัวอย่างเช่น ในการเขียนโปรแกรม\n\n4\n00:00:06.400 --> 00:00:08.940\nหลายๆ stacks สามารถสื่อสารกันได้\n\n5\n00:00:08.940 --> 00:00:11.760\nโดยการใช้ signalling และ handling events\n\n6\n00:00:11.760 --> 00:00:13.980\nEvent หนึ่งๆ ก็เหมือนข้อความ\n\n7\n00:00:13.980 --> 00:00:15.963\nจาก โปรแกรมมิ่ง stack หนึ่งไปยังอีก stack\n\n8\n00:00:17.040 --> 00:00:19.630\nไม่เพียง แต่สามารถส่งสัญญาณเหตุการณ์โดยบล็อกได้\n\n9\n00:00:19.630 --> 00:00:22.693\nแต่ยังสามารถส่งสัญญาณโดยเซ็นเซอร์และปุ่มต่างๆได้อีกด้วย\n\n10\n00:00:23.860 --> 00:00:26.170\nในบล็อกโปรเจ็ค บล็อกที่มีป้ายกำกับ\n\n11\n00:00:26.170 --> 00:00:29.270\nจะเริ่มด้วยการ broadcast ซึ่งเป็น signal events\n\n12\n00:00:29.270 --> 00:00:32.750\nบล็อกที่ป้ายกำกับเป็น when จะเป็น handle events\n\n13\n00:00:32.750 --> 00:00:36.890\nหมายความว่ามัน trigger บล็อกหรือ stack ของบล็อกให้ทำงาน\n\n14\n00:00:36.890 --> 00:00:39.290\nในโปรเจ็คบล็อกนี้ ตัว events บล็อก\n\n15\n00:00:39.290 --> 00:00:41.730\nที่เริ่มต้นด้วย when จะช่วยให้คุณสามารถควบคุม\n\n16\n00:00:41.730 --> 00:00:43.300\nแขนและกรงเล็บมอเตอร์ได้\n\n17\n00:00:43.300 --> 00:00:45.373\nด้วยปุ่มบนรีโมทคอนโทรล\n\n18\n00:00:46.950 --> 00:00:49.780\nbroadcast บล็อก สามารถส่งสัญญาณ events\n\n19\n00:00:49.780 --> 00:00:51.960\nในโปรเจ็คนี้ ตัว broadcast บล็อกนี้\n\n20\n00:00:51.960 --> 00:00:55.010\nจะส่งสัญญาข้อความให้หุ่นยนต์เดินไปข้างหน้า\n\n21\n00:00:55.010 --> 00:00:58.960\nระยะทาง 300 มิลลิเมตร และพิมพ์ข้อความออกมา\n\n22\n00:00:58.960 --> 00:01:01.730\nwhen I receive บล็อกจะทำหน้าที่ จัดการกับ event\n\n23\n00:01:01.730 --> 00:01:04.090\nส่งสัญญาให้หุ่นยนต์เดินไปข้างหน้า\n\n24\n00:01:04.090 --> 00:01:07.090\nซึ่งจะช่วยให้สามารถรันโค้ดทั้งสองชุดได้\n\n25\n00:01:07.090 --> 00:01:10.170\nคุณสามารถใช้ broadcast และ wait บล็อกได้\n\n26\n00:01:10.170 --> 00:01:12.763\nสิ่งนี้จะหยุด stack หนึ่งไว้ในขณะที่ stack อื่นกำลังทำงาน\n\n27\n00:01:14.494 --> 00:01:16.190\nการใช้ event จะช่วยให้หุ่นยนต์ของคุณ\n\n28\n00:01:16.190 --> 00:01:18.373\nสามารถทำพฤติกรรมที่ซับซ้อนมากขึ้นได้\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Іноді ваш робот повинен</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nвиконувати декілька дій.\n\n3\n00:00:04.350 --> 00:00:06.400\nТак, у програмуванні\n\n4\n00:00:06.400 --> 00:00:08.940\nрізні стеки блоків можуть взаємодіяти один з одним\n\n5\n00:00:08.940 --> 00:00:11.760\nнадсилаючи і вловлюючи події.\n\n6\n00:00:11.760 --> 00:00:13.980\nПодія - це як повідомлення\n\n7\n00:00:13.980 --> 00:00:15.963\nвід одного стека програми до іншого.\n\n8\n00:00:17.040 --> 00:00:19.630\nПодію можна викликати не лише блоками,\n\n9\n00:00:19.630 --> 00:00:22.693\nа і датчиками або кнопками.\n\n10\n00:00:23.860 --> 00:00:26.170\nУ блоковому проєкті блоки з написом\n\n11\n00:00:26.170 --> 00:00:29.270\nна початку \"надіслати\" викликають подію.\n\n12\n00:00:29.270 --> 00:00:32.750\nБлоки з написом на початку \"коли\" вловлюють подію.\n\n13\n00:00:32.750 --> 00:00:36.890\nТобто вони запускають блок або стек блоків.\n\n14\n00:00:36.890 --> 00:00:39.290\nУ цьому блоковому проєкті блок подій,\n\n15\n00:00:39.290 --> 00:00:41.730\nщо починається з \"коли\", дає вам змогу контролювати\n\n16\n00:00:41.730 --> 00:00:43.300\nмотори руки і клешні\n\n17\n00:00:43.300 --> 00:00:45.373\nкнопками на пристрої віддаленого керування.\n\n18\n00:00:46.950 --> 00:00:49.780\nБлок із \"надіслати\" може викликати події.\n\n19\n00:00:49.780 --> 00:00:51.960\nУ цьому проєкті блок \"надіслати\"\n\n20\n00:00:51.960 --> 00:00:55.010\nнадсилає повідомлення роботу рухатись уперед\n\n21\n00:00:55.010 --> 00:00:58.960\n300 міліметрів а потім вивести повідомлення.\n\n22\n00:00:58.960 --> 00:01:01.730\nБлок \"коли отримано\" вловлює подію\n\n23\n00:01:01.730 --> 00:01:04.090\nі запускає робота на рух уперед.\n\n24\n00:01:04.090 --> 00:01:07.090\nЦе дає змогу запускати обидва стека коду.\n\n25\n00:01:07.090 --> 00:01:10.170\nТакож можна використовувати блоки \"надіслати\" і \"чекати\".\n\n26\n00:01:10.170 --> 00:01:12.763\nЦе зупинить один стек, поки інший працює.\n\n27\n00:01:14.494 --> 00:01:16.190\nВикористання подій дозволить роботу\n\n28\n00:01:16.190 --> 00:01:18.373\nвиконувати складніші завдання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>Đôi khi, rô bốt của bạn có thể cần</v>\n\n2\n00:00:02.170 --> 00:00:04.350\nđể thực hiện nhiều hành vi.\n\n3\n00:00:04.350 --> 00:00:06.400\nVí dụ, trong lập trình,\n\n4\n00:00:06.400 --> 00:00:08.940\nnhiều ngăn xếp có thể giao tiếp với nhau\n\n5\n00:00:08.940 --> 00:00:11.760\nbằng cách báo hiệu và xử lý các sự kiện.\n\n6\n00:00:11.760 --> 00:00:13.980\nSau đó, một sự kiện giống như một thông điệp\n\n7\n00:00:13.980 --> 00:00:15.963\ntừ ngăn xếp lập trình này sang ngăn xếp lập trình khác.\n\n8\n00:00:17.040 --> 00:00:19.630\nCác sự kiện không chỉ có thể được báo hiệu bằng các khối,\n\n9\n00:00:19.630 --> 00:00:22.693\nnhưng chúng cũng có thể được báo hiệu bằng các cảm biến và nút.\n\n10\n00:00:23.860 --> 00:00:26.170\nTrong một dự án khối, các khối có nhãn\n\n11\n00:00:26.170 --> 00:00:29.270\nbắt đầu với các sự kiện phát sóng, tín hiệu.\n\n12\n00:00:29.270 --> 00:00:32.750\nCác khối có nhãn bắt đầu bằng khi nào, xử lý các sự kiện.\n\n13\n00:00:32.750 --> 00:00:36.890\nCó nghĩa là chúng kích hoạt một khối hoặc chồng khối để chạy.\n\n14\n00:00:36.890 --> 00:00:39.290\nTrong dự án khối này, các khối sự kiện\n\n15\n00:00:39.290 --> 00:00:41.730\nbắt đầu với thời điểm, cho phép bạn kiểm soát\n\n16\n00:00:41.730 --> 00:00:43.300\nđộng cơ cánh tay và móng vuốt\n\n17\n00:00:43.300 --> 00:00:45.373\nbằng các nút trên điều khiển từ xa.\n\n18\n00:00:46.950 --> 00:00:49.780\nKhối quảng bá có thể báo hiệu các sự kiện.\n\n19\n00:00:49.780 --> 00:00:51.960\nTrong dự án này, khối phát\n\n20\n00:00:51.960 --> 00:00:55.010\nphát tín hiệu thông báo cho rô-bốt lái xe về phía trước\n\n21\n00:00:55.010 --> 00:00:58.960\ncho 300 milimét, và sau đó để in tin nhắn.\n\n22\n00:00:58.960 --> 00:01:01.730\nKhi tôi nhận được khối xử lý các sự kiện,\n\n23\n00:01:01.730 --> 00:01:04.090\nkích hoạt rô bốt di chuyển về phía trước.\n\n24\n00:01:04.090 --> 00:01:07.090\nĐiều này cho phép cả hai ngăn xếp mã được chạy.\n\n25\n00:01:07.090 --> 00:01:10.170\nBạn cũng có thể sử dụng khối phát và chờ.\n\n26\n00:01:10.170 --> 00:01:12.763\nĐiều này tạm dừng một ngăn xếp trong khi ngăn xếp kia chạy.\n\n27\n00:01:14.494 --> 00:01:16.190\nSử dụng các sự kiện cho phép rô bốt của bạn\n\n28\n00:01:16.190 --> 00:01:18.373\nđể hoàn thành các hành vi nâng cao hơn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\ncrwdns96596:0crwdne96596:0\n\n2\n00:00:02.170 --> 00:00:04.350\ncrwdns96598:0crwdne96598:0\n\n3\n00:00:04.350 --> 00:00:06.400\ncrwdns96600:0crwdne96600:0\n\n4\n00:00:06.400 --> 00:00:08.940\ncrwdns96602:0crwdne96602:0\n\n5\n00:00:08.940 --> 00:00:11.760\ncrwdns96604:0crwdne96604:0\n\n6\n00:00:11.760 --> 00:00:13.980\ncrwdns96606:0crwdne96606:0\n\n7\n00:00:13.980 --> 00:00:15.963\ncrwdns96608:0crwdne96608:0\n\n8\n00:00:17.040 --> 00:00:19.630\ncrwdns96610:0crwdne96610:0\n\n9\n00:00:19.630 --> 00:00:22.693\ncrwdns96612:0crwdne96612:0\n\n10\n00:00:23.860 --> 00:00:26.170\ncrwdns96614:0crwdne96614:0\n\n11\n00:00:26.170 --> 00:00:29.270\ncrwdns96616:0crwdne96616:0\n\n12\n00:00:29.270 --> 00:00:32.750\ncrwdns96618:0crwdne96618:0\n\n13\n00:00:32.750 --> 00:00:36.890\ncrwdns96620:0crwdne96620:0\n\n14\n00:00:36.890 --> 00:00:39.290\ncrwdns96622:0crwdne96622:0\n\n15\n00:00:39.290 --> 00:00:41.730\ncrwdns96624:0crwdne96624:0\n\n16\n00:00:41.730 --> 00:00:43.300\ncrwdns96626:0crwdne96626:0\n\n17\n00:00:43.300 --> 00:00:45.373\ncrwdns96628:0crwdne96628:0\n\n18\n00:00:46.950 --> 00:00:49.780\ncrwdns96630:0crwdne96630:0\n\n19\n00:00:49.780 --> 00:00:51.960\ncrwdns96632:0crwdne96632:0\n\n20\n00:00:51.960 --> 00:00:55.010\ncrwdns96634:0crwdne96634:0\n\n21\n00:00:55.010 --> 00:00:58.960\ncrwdns96636:0crwdne96636:0\n\n22\n00:00:58.960 --> 00:01:01.730\ncrwdns96638:0crwdne96638:0\n\n23\n00:01:01.730 --> 00:01:04.090\ncrwdns96640:0crwdne96640:0\n\n24\n00:01:04.090 --> 00:01:07.090\ncrwdns96642:0crwdne96642:0\n\n25\n00:01:07.090 --> 00:01:10.170\ncrwdns96644:0crwdne96644:0\n\n26\n00:01:10.170 --> 00:01:12.763\ncrwdns96646:0crwdne96646:0\n\n27\n00:01:14.494 --> 00:01:16.190\ncrwdns96648:0crwdne96648:0\n\n28\n00:01:16.190 --> 00:01:18.373\ncrwdns96650:0crwdne96650:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:02.170\n<v Narrator>有时候您的机器人可能需要</v>\n\n2\n00:00:02.170 --> 00:00:04.350\n执行多个动作。\n\n3\n00:00:04.350 --> 00:00:06.400\n例如，在编程中，\n\n4\n00:00:06.400 --> 00:00:08.940\n多个指令段可以互相沟通\n\n5\n00:00:08.940 --> 00:00:11.760\n来互相沟通。\n\n6\n00:00:11.760 --> 00:00:13.980\n一个事件就像一条消息\n\n7\n00:00:13.980 --> 00:00:15.963\n从一个编程指令段到另一个指令段的消息。\n\n8\n00:00:17.040 --> 00:00:19.630\n时间不仅可以由指令块发信号，\n\n9\n00:00:19.630 --> 00:00:22.693\n而且它们也可以通过传感器和按键来发信号。\n\n10\n00:00:23.860 --> 00:00:26.170\n在一个指令块程序中，那些\n\n11\n00:00:26.170 --> 00:00:29.270\n以“广播”标签开始的指令块，发布事件信号。\n\n12\n00:00:29.270 --> 00:00:32.750\n以“当”标签开始的指令块，处理事件，\n\n13\n00:00:32.750 --> 00:00:36.890\n意味着它们触发一个指令块或指令段去运行。\n\n14\n00:00:36.890 --> 00:00:39.290\n在本程序中，以“当”开始的\n\n15\n00:00:39.290 --> 00:00:41.730\n事件指令块，允许您通过遥控器\n\n16\n00:00:41.730 --> 00:00:43.300\n的按键来控制\n\n17\n00:00:43.300 --> 00:00:45.373\n来控制机械臂和钳爪的电机。\n\n18\n00:00:46.950 --> 00:00:49.780\n“广播”指令块可以发布事件信号。\n\n19\n00:00:49.780 --> 00:00:51.960\n在本程序中，“广播”指令块\n\n20\n00:00:51.960 --> 00:00:55.010\n发布一个消息让机器人正向驱动\n\n21\n00:00:55.010 --> 00:00:58.960\n300毫米，然后打印一个消息。\n\n22\n00:00:58.960 --> 00:01:01.730\n“当我收到”指令块处理事件，\n\n23\n00:01:01.730 --> 00:01:04.090\n触使机器人向前运动。\n\n24\n00:01:04.090 --> 00:01:07.090\n这使得两个指令段都执行。\n\n25\n00:01:07.090 --> 00:01:10.170\n你也可以使用一个“广播并等待”指令块。\n\n26\n00:01:10.170 --> 00:01:12.763\n它将暂停一个指令段而让另一个运行。\n\n27\n00:01:14.494 --> 00:01:16.190\n使用事件可以让你的机器人\n\n28\n00:01:16.190 --> 00:01:18.373\n完成更高级的动作。\n\n"}},{"thumb":"V5_Tutorial_usingLoops.jpg","mov":"V5_Blocks_UsingLoops_V2","description":"Using Loops","filter":"","placeholder":false,"vimeo":"475901797","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Sometimes there's an action</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nthat you want your robot to repeat.\n\n3\n00:00:03.610 --> 00:00:05.390\nFor example, if you want your robot\n\n4\n00:00:05.390 --> 00:00:07.520\nto move around a square, the robot will need\n\n5\n00:00:07.520 --> 00:00:10.940\nto move forward and turn right four times.\n\n6\n00:00:10.940 --> 00:00:12.230\nTo repeat that action,\n\n7\n00:00:12.230 --> 00:00:15.243\nyou could duplicate those two blocks four times.\n\n8\n00:00:21.060 --> 00:00:22.773\nHowever, there is a better way;\n\n9\n00:00:23.940 --> 00:00:26.193\nyou can use the repeat C-block.\n\n10\n00:00:27.310 --> 00:00:30.320\nThe repeat C-block loops the blocks contained inside\n\n11\n00:00:30.320 --> 00:00:31.943\nfor a set number of times.\n\n12\n00:00:34.370 --> 00:00:36.720\nSet the repeat C-block to four,\n\n13\n00:00:36.720 --> 00:00:39.193\nand your robot will now move around the square.\n\n14\n00:00:40.870 --> 00:00:44.550\nSometimes you may want to repeat a set of actions forever.\n\n15\n00:00:44.550 --> 00:00:47.713\nIn this situation, you can use the forever C-block.\n\n16\n00:00:49.940 --> 00:00:53.900\nThe forever C-block is often used when using sensor feedback\n\n17\n00:00:53.900 --> 00:00:56.120\nto make repeated decisions.\n\n18\n00:00:56.120 --> 00:00:59.320\nBoth the forever and the repeat C-blocks enable you\n\n19\n00:00:59.320 --> 00:01:01.223\nto repeat a set of actions.\n\n","ar":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>في بعض الأحيان هناك إجراء</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nتريد من الروبوت الخاص بك أن يكرره.\n\n3\n00:00:03.610 --> 00:00:05.390\nعلى سبيل المثال، إذا كنت تريد الروبوت الخاص بك\n\n4\n00:00:05.390 --> 00:00:07.520\nللتحرك حول مربع, الروبوت سوف يحتاج\n\n5\n00:00:07.520 --> 00:00:10.940\nالتحرك إلى الأمام والاستدارة إلى الأمام أربع مرات.\n\n6\n00:00:10.940 --> 00:00:12.230\n2 - لتكرار ذلك الإجراء،\n\n7\n00:00:12.230 --> 00:00:15.243\nيمكنك إنشاء نسخه مطابقه لهذين المقطعين أربع مرات.\n\n8\n00:00:21.060 --> 00:00:22.773\nومع ذلك، هناك طريقة أفضل;\n\n9\n00:00:23.940 --> 00:00:26.193\nيمكنك استخدام مقطع التكرار ''C''.\n\n10\n00:00:27.310 --> 00:00:30.320\nمقطع التكرار ''C'' يكرر المقاطع الموجودة بالداخل\n\n11\n00:00:30.320 --> 00:00:31.943\nلعدد محدد من المرات.\n\n12\n00:00:34.370 --> 00:00:36.720\nعيّن المقطع ''C'' المكرر إلى أربعة,\n\n13\n00:00:36.720 --> 00:00:39.193\nوسيتحرك الروبوت الخاص بك الآن حول المربع.\n\n14\n00:00:40.870 --> 00:00:44.550\nأحياناً قد ترغب في تكرار مجموعة من الإجراءات إلى الأبد.\n\n15\n00:00:44.550 --> 00:00:47.713\nفي هذه الحالة، يمكنك استخدام المقطع''C إلى الأبد''.\n\n16\n00:00:49.940 --> 00:00:53.900\nغالباً ما تستخدم المقاطع ''C إلى الأبد'' لملاحظة ردود فعل المستشعر\n\n17\n00:00:53.900 --> 00:00:56.120\nلاتخاذ قرارات متكررة.\n\n18\n00:00:56.120 --> 00:00:59.320\nكلاً من مقاطع ''التكرار ''C\" و \"إلى الأبد''\n\n19\n00:00:59.320 --> 00:01:01.223\nلتكرار مجموعة من الإجراءات.\n\n","cs":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Občas se vyskytne akce,</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nkterou chceš, aby tvůj robot opakoval.\n\n3\n00:00:03.610 --> 00:00:05.390\nNapříklad jestliže chceš, aby se tvůj robot\n\n4\n00:00:05.390 --> 00:00:07.520\npohyboval po čtverci, bude robot muset\n\n5\n00:00:07.520 --> 00:00:10.940\njet dopředu a zatočit vpravo čtyřikrát.\n\n6\n00:00:10.940 --> 00:00:12.230\nPro opakování teto akce\n\n7\n00:00:12.230 --> 00:00:15.243\nmůžeš tyto dva bloky zkopírovat čtyřikrát.\n\n8\n00:00:21.060 --> 00:00:22.773\nNicméně je zde i lepší způsob;\n\n9\n00:00:23.940 --> 00:00:26.193\nmůžeš použít blok Opakuj-krát.\n\n10\n00:00:27.310 --> 00:00:30.320\nBlok Opakuj-krát provede bloky obsažené uvnitř\n\n11\n00:00:30.320 --> 00:00:31.943\ntolikrát, kolikrát nastavíš.\n\n12\n00:00:34.370 --> 00:00:36.720\nNastav blok Opakuj-krát na čtyři\n\n13\n00:00:36.720 --> 00:00:39.193\na tvůj robot se bude pohybovat ve tvaru čtverce.\n\n14\n00:00:40.870 --> 00:00:44.550\nNěkdy můžeš chtít opakovat sadu akcí donekonečna.\n\n15\n00:00:44.550 --> 00:00:47.713\nV takové situaci můžeš použít blok Opakuj stále.\n\n16\n00:00:49.940 --> 00:00:53.900\nBlok Opakuj stále se často používá při použití zpětné vazby senzoru\n\n17\n00:00:53.900 --> 00:00:56.120\nk opakovanému rozhodování.\n\n18\n00:00:56.120 --> 00:00:59.320\nJak blok Opakuj stále, tak blok Opakuj-krát ti umožní\n\n19\n00:00:59.320 --> 00:01:01.223\nopakovat sadu akcí.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>A veces hay una acción</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nque desea que se repita su robot.\n\n3\n00:00:03.610 --> 00:00:05.390\nPor ejemplo, si desea que su robot\n\n4\n00:00:05.390 --> 00:00:07.520\nse mueva alrededor de un cuadrado, el robot necesitará\n\n5\n00:00:07.520 --> 00:00:10.940\navanzar y girar a la derecha cuatro veces.\n\n6\n00:00:10.940 --> 00:00:12.230\nPara repetir esa acción,\n\n7\n00:00:12.230 --> 00:00:15.243\npodrías duplicar esos dos bloques cuatro veces.\n\n8\n00:00:21.060 --> 00:00:22.773\nSin embargo, hay una forma mejor;\n\n9\n00:00:23.940 --> 00:00:26.193\npuedes usar el bloque C de Repetir.\n\n10\n00:00:27.310 --> 00:00:30.320\nEl bloque C de Repetición reproduce los bloques contenidos en el interior\n\n11\n00:00:30.320 --> 00:00:31.943\npara un número de veces determinado.\n\n12\n00:00:34.370 --> 00:00:36.720\nEstablece el bloque C de repetición a cuatro,\n\n13\n00:00:36.720 --> 00:00:39.193\ny su robot ahora se moverá alrededor de la cuadra.\n\n14\n00:00:40.870 --> 00:00:44.550\nA veces puede que desee repetir un conjunto de acciones por siempre.\n\n15\n00:00:44.550 --> 00:00:47.713\nEn esta situación, puede utilizar el bloque C de Por Siempre.\n\n16\n00:00:49.940 --> 00:00:53.900\nEl bloque C Por Siempre se utiliza a menudo al usar retroalimentación del sensor\n\n17\n00:00:53.900 --> 00:00:56.120\npara tomar decisiones repetidas.\n\n18\n00:00:56.120 --> 00:00:59.320\nTanto los bloques C de Por Siempre como los de Repetición\n\n19\n00:00:59.320 --> 00:01:01.223\nle permite repetir un conjunto de acciones.\n\n","es":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>A veces hay una acción</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nque desea que se repita su robot.\n\n3\n00:00:03.610 --> 00:00:05.390\nPor ejemplo, si desea que su robot\n\n4\n00:00:05.390 --> 00:00:07.520\nse mueva alrededor de un cuadrado, el robot necesitará\n\n5\n00:00:07.520 --> 00:00:10.940\navanzar y girar a la derecha cuatro veces.\n\n6\n00:00:10.940 --> 00:00:12.230\nPara repetir esa acción,\n\n7\n00:00:12.230 --> 00:00:15.243\npodrías duplicar esos dos bloques cuatro veces.\n\n8\n00:00:21.060 --> 00:00:22.773\nSin embargo, hay una forma mejor;\n\n9\n00:00:23.940 --> 00:00:26.193\npuedes usar el bloque C de Repetir.\n\n10\n00:00:27.310 --> 00:00:30.320\nEl bloque C de Repetición reproduce los bloques contenidos en el interior\n\n11\n00:00:30.320 --> 00:00:31.943\npara un número de veces determinado.\n\n12\n00:00:34.370 --> 00:00:36.720\nEstablece el bloque C de repetición a cuatro,\n\n13\n00:00:36.720 --> 00:00:39.193\ny su robot ahora se moverá alrededor de la cuadra.\n\n14\n00:00:40.870 --> 00:00:44.550\nA veces puede que desee repetir un conjunto de acciones por siempre.\n\n15\n00:00:44.550 --> 00:00:47.713\nEn esta situación, puede utilizar el bloque C de Por Siempre.\n\n16\n00:00:49.940 --> 00:00:53.900\nEl bloque C Por Siempre se utiliza a menudo al usar retroalimentación del sensor\n\n17\n00:00:53.900 --> 00:00:56.120\npara tomar decisiones repetidas.\n\n18\n00:00:56.120 --> 00:00:59.320\nTanto los bloques C de Por Siempre como los de Repetición\n\n19\n00:00:59.320 --> 00:01:01.223\nle permite repetir un conjunto de acciones.\n\n","fi":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Joskus ohjelmassa on toimenpiteitä</v>\n\n2\n00:00:01.570 --> 00:00:03.610\ntoistaen jotain tehtävää.\n\n3\n00:00:03.610 --> 00:00:05.390\nEsimerkiksi haluat robottisi\n\n4\n00:00:05.390 --> 00:00:07.520\najavan neliömuodon ts robotti\n\n5\n00:00:07.520 --> 00:00:10.940\ntoistaa aja eteenpäin ja käänny - blokit 4 kertaa.\n\n6\n00:00:10.940 --> 00:00:12.230\nJotta voit toistaa tämän\n\n7\n00:00:12.230 --> 00:00:15.243\nsinun pitäsi tehdä näiden blokkien tuplaus neljä kertaa.\n\n8\n00:00:21.060 --> 00:00:22.773\nOn kuitenkin helpompikin tapa,\n\n9\n00:00:23.940 --> 00:00:26.193\nkun käytät Toista c-blokkia.\n\n10\n00:00:27.310 --> 00:00:30.320\nToista c-blokin sisällä olevat komennot toistetaan\n\n11\n00:00:30.320 --> 00:00:31.943\nsen lukumäärän kuin haluat.\n\n12\n00:00:34.370 --> 00:00:36.720\nAseta toistojen määräksi neljä\n\n13\n00:00:36.720 --> 00:00:39.193\nja robotti tekee neliöliikkeen.\n\n14\n00:00:40.870 --> 00:00:44.550\nJos haluat valita rajoittamattoman toiston,\n\n15\n00:00:44.550 --> 00:00:47.713\nvalitse pelkkä Toista -blokki.\n\n16\n00:00:49.940 --> 00:00:53.900\nPelkkää Toista -blokkia voi käyttää antureiden arvojen palautteen mukaan\n\n17\n00:00:53.900 --> 00:00:56.120\ntekemään toisteisia päätöksiä.\n\n18\n00:00:56.120 --> 00:00:59.320\nMolempien joko Toista- tai Toista C-kertaa blokkien avulla\n\n19\n00:00:59.320 --> 00:01:01.223\nsaat toimenpiteitä toistettua.\n\n","fr":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Il y a parfois une action</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nque vous souhaitez que votre robot répète.\n\n3\n00:00:03.610 --> 00:00:05.390\nPar exemple, si vous voulez que votre robot\n\n4\n00:00:05.390 --> 00:00:07.520\nse déplace le long d'un carré, le robot aura besoin\n\n5\n00:00:07.520 --> 00:00:10.940\nd'avancer et de tourner à droite quatre fois.\n\n6\n00:00:10.940 --> 00:00:12.230\nPour répéter cette action,\n\n7\n00:00:12.230 --> 00:00:15.243\nvous pouvez dupliquer ces deux blocs quatre fois.\n\n8\n00:00:21.060 --> 00:00:22.773\nToutefois, il y a une meilleure solution ;\n\n9\n00:00:23.940 --> 00:00:26.193\nvous pouvez utiliser le bloc C « Répéter ».\n\n10\n00:00:27.310 --> 00:00:30.320\nLe bloc C « répéter » exécute en boucle les blocs contenus à l'intérieur\n\n11\n00:00:30.320 --> 00:00:31.943\npour un certain nombre de fois.\n\n12\n00:00:34.370 --> 00:00:36.720\nDéfinissez le bloc C de répétition à quatre,\n\n13\n00:00:36.720 --> 00:00:39.193\net votre robot se déplacera maintenant le long d'un carré.\n\n14\n00:00:40.870 --> 00:00:44.550\nVous souhaiterez parfois répéter une série d'actions indéfiniment.\n\n15\n00:00:44.550 --> 00:00:47.713\nDans ce cas, vous pouvez utiliser le bloc C \"Indéfiniment\".\n\n16\n00:00:49.940 --> 00:00:53.900\nLe bloc C \"Indéfiniment\" est souvent utilisé lorsque vous utilisez le retour d'un capteur\n\n17\n00:00:53.900 --> 00:00:56.120\npour prendre des décisions répétitives.\n\n18\n00:00:56.120 --> 00:00:59.320\nLes blocs C \"Indéfiniment\" et \"Répéter\" vous permettent\n\n19\n00:00:59.320 --> 00:01:01.223\nde répéter une série d'actions.\n\n","ko":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>때때로</v>\n\n2\n00:00:01.570 --> 00:00:03.610\n로봇이 반복하기 원하는 동작이 있습니다.\n\n3\n00:00:03.610 --> 00:00:05.390\n예를 들어 로봇이 정사각형을 따라 이동하도록 하려면\n\n4\n00:00:05.390 --> 00:00:07.520\n로봇은 '앞으로 이동'과\n\n5\n00:00:07.520 --> 00:00:10.940\n'오른쪽으로 돌기'를 4회 해야 합니다.\n\n6\n00:00:10.940 --> 00:00:12.230\n이 동작을 반복하기 위해\n\n7\n00:00:12.230 --> 00:00:15.243\n이 두 블록을 4번 복사하면 됩니다.\n\n8\n00:00:21.060 --> 00:00:22.773\n그러나 더 나은 방법이 있습니다;\n\n9\n00:00:23.940 --> 00:00:26.193\n반복 C 블록을 사용하는 것입니다.\n\n10\n00:00:27.310 --> 00:00:30.320\n반복 C 블록은 내부에 포함된 블록을\n\n11\n00:00:30.320 --> 00:00:31.943\n설정하는 횟수만큼 반복합니다.\n\n12\n00:00:34.370 --> 00:00:36.720\n반복 C 블록을 4로 설정하면\n\n13\n00:00:36.720 --> 00:00:39.193\n로봇은 정사각형을 따라 이동할 것입니다.\n\n14\n00:00:40.870 --> 00:00:44.550\n때때로 일련의 동작을 무한 반복하고 싶을 수 있습니다.\n\n15\n00:00:44.550 --> 00:00:47.713\n이 때는 무한 반복 C 블록을 사용하면 됩니다.\n\n16\n00:00:49.940 --> 00:00:53.900\n무한 반복 C 블록은 센서 피드백을 사용하여\n\n17\n00:00:53.900 --> 00:00:56.120\n반복해서 결정해야 할 때 자주 사용합니다.\n\n18\n00:00:56.120 --> 00:00:59.320\n'무한 반복'과 '반복' C 블록을 사용하면\n\n19\n00:00:59.320 --> 00:01:01.223\n일련의 동작을 반복할 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Kartais norite, kad Jūsų robotas</v>\n\n2\n00:00:01.570 --> 00:00:03.610\npakartotų veiksmą.\n\n3\n00:00:03.610 --> 00:00:05.390\nPavyzdžiui, jeigu norite, kad Jūsų robotas\n\n4\n00:00:05.390 --> 00:00:07.520\njudėtų aplink kvadratą, robotui reikės\n\n5\n00:00:07.520 --> 00:00:10.940\njudėti į priekį ir pasukti į dešinę keturis kartus.\n\n6\n00:00:10.940 --> 00:00:12.230\nNorėdami pakartoti šį veiksmą,\n\n7\n00:00:12.230 --> 00:00:15.243\ngalite keturis kartus pakartoti šiuos du blokus.\n\n8\n00:00:21.060 --> 00:00:22.773\nTačiau, yra geresnis būdas;\n\n9\n00:00:23.940 --> 00:00:26.193\ngalite naudoti \"pasikartojantį C\" bloką.\n\n10\n00:00:27.310 --> 00:00:30.320\n\"Pasikartojantis C\" blokas nustatytą kartų skaičių\n\n11\n00:00:30.320 --> 00:00:31.943\natlieka viduje esančių blokų ciklą.\n\n12\n00:00:34.370 --> 00:00:36.720\nNustatykite, kad C blokas kartotųsi keturis kartus,\n\n13\n00:00:36.720 --> 00:00:39.193\nir dabar Jūsų robotas judės aplink kvadratą.\n\n14\n00:00:40.870 --> 00:00:44.550\nKartais norite, kad veiksmai būtų kartojami amžinai.\n\n15\n00:00:44.550 --> 00:00:47.713\nŠioje situacijoje galite naudoti \"amžinai C\" bloką.\n\n16\n00:00:49.940 --> 00:00:53.900\nJis dažnai naudojamas naudojant jutiklio grįžtamąjį ryšį\n\n17\n00:00:53.900 --> 00:00:56.120\npakartotiniams veiksmams atlikti.\n\n18\n00:00:56.120 --> 00:00:59.320\nTiek \"amžinai\", tiek \"pasikartojantis C\" blokai leidžia\n\n19\n00:00:59.320 --> 00:01:01.223\nJums kartoti veiksmus.\n\n","lv":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Dažkārt ir darbības,</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nkuras vēlaties, lai robots atkārtotu.\n\n3\n00:00:03.610 --> 00:00:05.390\nPiemēram, ja vēlaties, lai robots\n\n4\n00:00:05.390 --> 00:00:07.520\npārvietotos kvadrāta formā, robotam vajadzēs\n\n5\n00:00:07.520 --> 00:00:10.940\nvirzīties uz priekšu un pagriezties četras reizes pa labi.\n\n6\n00:00:10.940 --> 00:00:12.230\nLai atkārtotu darbību,\n\n7\n00:00:12.230 --> 00:00:15.243\nšādus divus blokus varētu kopēt četras reizes.\n\n8\n00:00:21.060 --> 00:00:22.773\nTomēr ir labāks veids, kā to izdarīt,\n\n9\n00:00:23.940 --> 00:00:26.193\nizmantojot atkārtošanas cikla bloku.\n\n10\n00:00:27.310 --> 00:00:30.320\nAtkārtošanas cikla bloks tajā ievietoto bloku darbību\n\n11\n00:00:30.320 --> 00:00:31.943\natkārtos pēc iestatītā reižu skaita.\n\n12\n00:00:34.370 --> 00:00:36.720\nIestatiet atkārtošanas cikla bloku uz četri,\n\n13\n00:00:36.720 --> 00:00:39.193\nun robots tagad pārvietosies kvadrāta laukuma formā.\n\n14\n00:00:40.870 --> 00:00:44.550\nDažreiz, iespējams vēlēsities atkārtot darbību kopumu bezgalīgi.\n\n15\n00:00:44.550 --> 00:00:47.713\nŠādā gadījumā jūs variet izmantot bezgalības cikla bloku.\n\n16\n00:00:49.940 --> 00:00:53.900\nBezgalības cikla bloku bieži izmanto kopā ar sensoru iegūto informāciju,\n\n17\n00:00:53.900 --> 00:00:56.120\nlai pieņemtu atkārtotus lēmumus.\n\n18\n00:00:56.120 --> 00:00:59.320\nGan bezgalības, gan atkārtošanas cikla bloki ļaus\n\n19\n00:00:59.320 --> 00:01:01.223\nveikt atkārtoti darbību kopumu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Soms is er een actie</v>\n\n2\n00:00:01.570 --> 00:00:03.610\ndie u wilt dat uw robot herhaalt.\n\n3\n00:00:03.610 --> 00:00:05.390\nAls u bijvoorbeeld wilt dat uw robot\n\n4\n00:00:05.390 --> 00:00:07.520\nover een vierkant rijdt, moet de robot\n\n5\n00:00:07.520 --> 00:00:10.940\nvoorwaarts rijden en vier keer naar rechts draaien.\n\n6\n00:00:10.940 --> 00:00:12.230\nOm die actie te herhalen\n\n7\n00:00:12.230 --> 00:00:15.243\nzou u deze twee blokken vier keer kunnen dupliceren.\n\n8\n00:00:21.060 --> 00:00:22.773\nEr is echter een betere manier;\n\n9\n00:00:23.940 --> 00:00:26.193\nu kunt het herhaal C blok gebruiken.\n\n10\n00:00:27.310 --> 00:00:30.320\nHet herhaal C blok herhaalt de blokken die erin zitten\n\n11\n00:00:30.320 --> 00:00:31.943\nvoor een bepaald aantal keren.\n\n12\n00:00:34.370 --> 00:00:36.720\nZet het herhaal C blok op vier,\n\n13\n00:00:36.720 --> 00:00:39.193\nen uw robot zal zich nu rond het vierkant rijden.\n\n14\n00:00:40.870 --> 00:00:44.550\nSoms kun u een set acties altijd herhalen.\n\n15\n00:00:44.550 --> 00:00:47.713\nIn deze situatie kunt u het voor altijd C-blok gebruiken.\n\n16\n00:00:49.940 --> 00:00:53.900\nHet voor altijd C blok wordt vaak gebruikt bij het gebruik van sensorfeedback\n\n17\n00:00:53.900 --> 00:00:56.120\nom herhaaldelijke beslissingen te nemen.\n\n18\n00:00:56.120 --> 00:00:59.320\nZowel de voor altijd als de herhaal C blokken\n\n19\n00:00:59.320 --> 00:01:01.223\nstellen u in staat een reeks acties te herhalen.\n\n","pl":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Czasami jest akcja</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nktórą chcesz, aby Twój robot powtórzył.\n\n3\n00:00:03.610 --> 00:00:05.390\nNa przykład, jeśli chcesz, aby robot\n\n4\n00:00:05.390 --> 00:00:07.520\nporuszał się wokół kwadratu, robot będzie potrzebował\n\n5\n00:00:07.520 --> 00:00:10.940\nczterokrotnie poruszać się do przodu i skręcić w prawo.\n\n6\n00:00:10.940 --> 00:00:12.230\nAby powtórz tę czynność,\n\n7\n00:00:12.230 --> 00:00:15.243\nmożesz powielić te dwa bloki cztery razy.\n\n8\n00:00:21.060 --> 00:00:22.773\nJest jednak lepsza droga;\n\n9\n00:00:23.940 --> 00:00:26.193\nmożesz użyć bloku \"powtórz\".\n\n10\n00:00:27.310 --> 00:00:30.320\nPowtórz blok C zawiera pętlę, która powtarza blok w środku\n\n11\n00:00:30.320 --> 00:00:31.943\nustaloną liczbę razy.\n\n12\n00:00:34.370 --> 00:00:36.720\nUstaw w bloku powtórki C wartość cztery,\n\n13\n00:00:36.720 --> 00:00:39.193\na Twój robot będzie się teraz poruszał po kwadracie.\n\n14\n00:00:40.870 --> 00:00:44.550\nCzasami możesz chcieć powtarzać zestaw czynności bez końca.\n\n15\n00:00:44.550 --> 00:00:47.713\nW tej sytuacji możesz użyć bloku C \"na zawsze\".\n\n16\n00:00:49.940 --> 00:00:53.900\nBlok C \"w nieskończoność\" jest często używany do użycia informacji zwrotnej czujnika\n\n17\n00:00:53.900 --> 00:00:56.120\ndo podejmowania powtarzających się decyzji.\n\n18\n00:00:56.120 --> 00:00:59.320\nZarówno \"na zawsze\", jak i \"powtarzaj\" umożliwiają Ci\n\n19\n00:00:59.320 --> 00:01:01.223\npowtórzyć zestaw działań.\n\n","ru":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Иногда возникает действие,</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nкоторое необходимо выполнить несколько раз.\n\n3\n00:00:03.610 --> 00:00:05.390\nНапример, если роботу необходимо\n\n4\n00:00:05.390 --> 00:00:07.520\nобъехать по квадрату, ему необходимо\n\n5\n00:00:07.520 --> 00:00:10.940\nпроехать вперёд и повернуться четыре раза.\n\n6\n00:00:10.940 --> 00:00:12.230\nДля повторения действия\n\n7\n00:00:12.230 --> 00:00:15.243\nвы можете продублировать эти два блока четыре раза.\n\n8\n00:00:21.060 --> 00:00:22.773\nОднако, есть решение получше;\n\n9\n00:00:23.940 --> 00:00:26.193\nвы можете использовать С блок повторения.\n\n10\n00:00:27.310 --> 00:00:30.320\nБлок повторения зацикливает блоки внутри себя\n\n11\n00:00:30.320 --> 00:00:31.943\nна определённое количество раз.\n\n12\n00:00:34.370 --> 00:00:36.720\nУстановите блок повторения на 4,\n\n13\n00:00:36.720 --> 00:00:39.193\nи робот объедет квадрат.\n\n14\n00:00:40.870 --> 00:00:44.550\nИногда, вам может понадобиться бесконечно повторять действия.\n\n15\n00:00:44.550 --> 00:00:47.713\nВ данной ситуации вы можете использовать блок «всегда».\n\n16\n00:00:49.940 --> 00:00:53.900\nБлок «всегда» часто используется для работы с датчиками\n\n17\n00:00:53.900 --> 00:00:56.120\nдля принятия повторяющихся ращений.\n\n18\n00:00:56.120 --> 00:00:59.320\nБесконечный блок и блок повторения\n\n19\n00:00:59.320 --> 00:01:01.223\nпозволяют повторять несколько действий.\n\n","th":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor> บางครั้งอาจมีการดำเนินการ </v>\n\n2\n00:00:01.570 --> 00:00:03.610\nที่คุณต้องการให้หุ่นยนต์ทำซ้ำ\n\n3\n00:00:03.610 --> 00:00:05.390\nตัวอย่างเช่นหากคุณต้องการให้หุ่นยนต์ของคุณ\n\n4\n00:00:05.390 --> 00:00:07.520\nหุ่นยนต์จะต้องเคลื่อนที่ไปรอบๆ สี่เหลี่ยม\n\n5\n00:00:07.520 --> 00:00:10.940\nเพื่อเดินหน้าและเลี้ยวขวาสี่ครั้ง\n\n6\n00:00:10.940 --> 00:00:12.230\nหากต้องการทำซ้ำการกระทำนั้น\n\n7\n00:00:12.230 --> 00:00:15.243\nคุณสามารถทำซ้ำสองบล็อกเหล่านั้นสี่ครั้ง\n\n8\n00:00:21.060 --> 00:00:22.773\nอย่างไรก็ตามมีวิธีที่ดีกว่า\n\n9\n00:00:23.940 --> 00:00:26.193\nคุณสามารถใช้ C-block ซ้ำได้\n\n10\n00:00:27.310 --> 00:00:30.320\nC-block ที่ทำซ้ำจะวนซ้ำบล็อกที่อยู่ภายใน\n\n11\n00:00:30.320 --> 00:00:31.943\nตามจำนวนครั้งที่กำหนด\n\n12\n00:00:34.370 --> 00:00:36.720\nตั้งค่า C-block ซ้ำเป็นสี่\n\n13\n00:00:36.720 --> 00:00:39.193\nและหุ่นยนต์ของคุณจะเคลื่อนที่ไปรอบ ๆ สี่เหลี่ยมจัตุรัส\n\n14\n00:00:40.870 --> 00:00:44.550\nบางครั้งคุณอาจต้องการทำซ้ำชุดการกระทำตลอดไป\n\n15\n00:00:44.550 --> 00:00:47.713\nในสถานการณ์นี้คุณสามารถใช้ forever C-block บล็อก\n\n16\n00:00:49.940 --> 00:00:53.900\nforever C-block บล็อกนี้ มักใช้เมื่อใช้การตอบสนองของเซ็นเซอร์\n\n17\n00:00:53.900 --> 00:00:56.120\nเพื่อทำการตัดสินใจซ้ำ ๆ\n\n18\n00:00:56.120 --> 00:00:59.320\nทั้งบล็อก forever และ repeat C-blocks ช่วยให้คุณ\n\n19\n00:00:59.320 --> 00:01:01.223\nสามารถทำการกระทำซ้ำๆได้\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Іноді є дії,</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nякі робот повинен повторювати.\n\n3\n00:00:03.610 --> 00:00:05.390\nНаприклад, якщо ви хочете, щоб робот\n\n4\n00:00:05.390 --> 00:00:07.520\nрухався навколо квадрата, то він має\n\n5\n00:00:07.520 --> 00:00:10.940\nпроїхати вперед і повернути праворуч чотири рази.\n\n6\n00:00:10.940 --> 00:00:12.230\nЩоб повторити ці дії,\n\n7\n00:00:12.230 --> 00:00:15.243\nви можете скопіювати ці два блоки чотири рази.\n\n8\n00:00:21.060 --> 00:00:22.773\nПроте, є краще рішення;\n\n9\n00:00:23.940 --> 00:00:26.193\nвикористайте С-подібний блок \"повторити\".\n\n10\n00:00:27.310 --> 00:00:30.320\nБлок \"повторити\" зациклить блоки всередині\n\n11\n00:00:30.320 --> 00:00:31.943\nвстановлену кількість разів.\n\n12\n00:00:34.370 --> 00:00:36.720\nВстановіть кількість повторень на чотири,\n\n13\n00:00:36.720 --> 00:00:39.193\nі тепер ваш робот рухатиметься навколо квадрата.\n\n14\n00:00:40.870 --> 00:00:44.550\nІноді потрібно повторювати дії постійно.\n\n15\n00:00:44.550 --> 00:00:47.713\nВ цьому випадку, використайте С-подібний блок \"завжди\".\n\n16\n00:00:49.940 --> 00:00:53.900\nБлок \"завжди\" часто використовують для зворотного зв'язку з датчиками,\n\n17\n00:00:53.900 --> 00:00:56.120\nщоб приймати повторювані рішення.\n\n18\n00:00:56.120 --> 00:00:59.320\nБлоки \"завжди і \"повторити\" дають вам змогу\n\n19\n00:00:59.320 --> 00:01:01.223\nповторити декілька дій.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>Đôi khi có một hành động</v>\n\n2\n00:00:01.570 --> 00:00:03.610\nmà bạn muốn rô bốt của mình lặp lại.\n\n3\n00:00:03.610 --> 00:00:05.390\nVí dụ: nếu bạn muốn rô bốt của mình\n\n4\n00:00:05.390 --> 00:00:07.520\nđể di chuyển xung quanh một hình vuông, robot sẽ cần\n\n5\n00:00:07.520 --> 00:00:10.940\nđể tiến và rẽ phải bốn lần.\n\n6\n00:00:10.940 --> 00:00:12.230\nĐể lặp lại hành động đó,\n\n7\n00:00:12.230 --> 00:00:15.243\nbạn có thể nhân đôi hai khối đó bốn lần.\n\n8\n00:00:21.060 --> 00:00:22.773\nTuy nhiên, có một cách tốt hơn;\n\n9\n00:00:23.940 --> 00:00:26.193\nbạn có thể sử dụng khối C lặp lại.\n\n10\n00:00:27.310 --> 00:00:30.320\nKhối C lặp lại lặp lại các khối chứa bên trong\n\n11\n00:00:30.320 --> 00:00:31.943\ntrong một số lần nhất định.\n\n12\n00:00:34.370 --> 00:00:36.720\nĐặt khối C lặp lại thành bốn,\n\n13\n00:00:36.720 --> 00:00:39.193\nvà rô bốt của bạn bây giờ sẽ di chuyển xung quanh hình vuông.\n\n14\n00:00:40.870 --> 00:00:44.550\nĐôi khi bạn có thể muốn lặp lại một loạt các hành động mãi mãi.\n\n15\n00:00:44.550 --> 00:00:47.713\nTrong tình huống này, bạn có thể sử dụng khối C vĩnh viễn.\n\n16\n00:00:49.940 --> 00:00:53.900\nKhối C vĩnh viễn thường được sử dụng khi sử dụng phản hồi cảm biến\n\n17\n00:00:53.900 --> 00:00:56.120\nđể đưa ra các quyết định lặp đi lặp lại.\n\n18\n00:00:56.120 --> 00:00:59.320\nCả khối vĩnh viễn và khối C lặp lại đều cho phép bạn\n\n19\n00:00:59.320 --> 00:01:01.223\nđể lặp lại một tập hợp các hành động.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\ncrwdns96714:0crwdne96714:0\n\n2\n00:00:01.570 --> 00:00:03.610\ncrwdns96716:0crwdne96716:0\n\n3\n00:00:03.610 --> 00:00:05.390\ncrwdns96718:0crwdne96718:0\n\n4\n00:00:05.390 --> 00:00:07.520\ncrwdns96720:0crwdne96720:0\n\n5\n00:00:07.520 --> 00:00:10.940\ncrwdns96722:0crwdne96722:0\n\n6\n00:00:10.940 --> 00:00:12.230\ncrwdns96724:0crwdne96724:0\n\n7\n00:00:12.230 --> 00:00:15.243\ncrwdns96726:0crwdne96726:0\n\n8\n00:00:21.060 --> 00:00:22.773\ncrwdns96728:0crwdne96728:0\n\n9\n00:00:23.940 --> 00:00:26.193\ncrwdns96730:0crwdne96730:0\n\n10\n00:00:27.310 --> 00:00:30.320\ncrwdns96732:0crwdne96732:0\n\n11\n00:00:30.320 --> 00:00:31.943\ncrwdns96734:0crwdne96734:0\n\n12\n00:00:34.370 --> 00:00:36.720\ncrwdns96736:0crwdne96736:0\n\n13\n00:00:36.720 --> 00:00:39.193\ncrwdns96738:0crwdne96738:0\n\n14\n00:00:40.870 --> 00:00:44.550\ncrwdns96740:0crwdne96740:0\n\n15\n00:00:44.550 --> 00:00:47.713\ncrwdns96742:0crwdne96742:0\n\n16\n00:00:49.940 --> 00:00:53.900\ncrwdns96744:0crwdne96744:0\n\n17\n00:00:53.900 --> 00:00:56.120\ncrwdns96746:0crwdne96746:0\n\n18\n00:00:56.120 --> 00:00:59.320\ncrwdns96748:0crwdne96748:0\n\n19\n00:00:59.320 --> 00:01:01.223\ncrwdns96750:0crwdne96750:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.100 --> 00:00:01.570\n<v Instructor>有时有一个动作</v>\n\n2\n00:00:01.570 --> 00:00:03.610\n您想要机器人去重复。\n\n3\n00:00:03.610 --> 00:00:05.390\n例如，如果您想要机器人\n\n4\n00:00:05.390 --> 00:00:07.520\n沿着正方形移动，机器人将需要\n\n5\n00:00:07.520 --> 00:00:10.940\n正向移动并右转四次。\n\n6\n00:00:10.940 --> 00:00:12.230\n欲重复这个动作，\n\n7\n00:00:12.230 --> 00:00:15.243\n你可以复制这两个指令块四次。\n\n8\n00:00:21.060 --> 00:00:22.773\n但是，还有更好的方法，\n\n9\n00:00:23.940 --> 00:00:26.193\n你可以使用“重复”C型指令块。\n\n10\n00:00:27.310 --> 00:00:30.320\n“重复”C型指令块循环它包含在内的指令块\n\n11\n00:00:30.320 --> 00:00:31.943\n循环执行包含其内的指令块。\n\n12\n00:00:34.370 --> 00:00:36.720\n设定“重复”C型指令块的值为4，\n\n13\n00:00:36.720 --> 00:00:39.193\n你的机器人就会沿着正方形移动。\n\n14\n00:00:40.870 --> 00:00:44.550\n有时您可能想要永远的重复一系列的动作。\n\n15\n00:00:44.550 --> 00:00:47.713\n在这种情况下，您可以使用“永久循环”C型指令块。\n\n16\n00:00:49.940 --> 00:00:53.900\n“永久循环”C型指令块常用于使用传感器反馈\n\n17\n00:00:53.900 --> 00:00:56.120\n来重复做出决定时。\n\n18\n00:00:56.120 --> 00:00:59.320\n“永久循环”和“重复”这两个C型指令块都\n\n19\n00:00:59.320 --> 00:01:01.223\n使得您可以重复一系列动作。\n\n"}},{"thumb":"V5_Tutorial_ifThenElse.jpg","mov":"V5_Blocks_UsingIfThenElse_V2","description":"If-Then-Else Blocks","filter":"","placeholder":false,"vimeo":"475901885","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Robots sometimes need to make decisions.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nA commonly used block to make those decisions\n\n3\n00:00:05.680 --> 00:00:09.240\nis the if then else C block.\n\n4\n00:00:09.240 --> 00:00:10.450\nThis block is located\n\n5\n00:00:10.450 --> 00:00:12.853\nin the control category of the toolbox.\n\n6\n00:00:18.320 --> 00:00:21.550\nAnd if then else C block has two parts:\n\n7\n00:00:21.550 --> 00:00:23.080\nthe if then branch\n\n8\n00:00:24.220 --> 00:00:25.543\nand the else branch.\n\n9\n00:00:27.780 --> 00:00:31.610\nIf the condition in the if then else C block is true,\n\n10\n00:00:31.610 --> 00:00:35.550\nthe blocks that are in the if then branch will be run.\n\n11\n00:00:35.550 --> 00:00:39.450\nIf the condition in the if then else C block is false,\n\n12\n00:00:39.450 --> 00:00:42.363\nthe blocks that are in the else branch will be run.\n\n13\n00:00:43.390 --> 00:00:44.720\nOne thing to keep in mind\n\n14\n00:00:44.720 --> 00:00:46.810\nis that the if then else C block\n\n15\n00:00:46.810 --> 00:00:49.630\nonly makes this decision once.\n\n16\n00:00:49.630 --> 00:00:51.810\nIn order to repeatedly make a decision,\n\n17\n00:00:51.810 --> 00:00:54.500\nyou can place the if then else C block\n\n18\n00:00:54.500 --> 00:00:56.853\ninside of a forever C block.\n\n","ar":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>في بعض الأحيان تحتاج الروبوتات إلى اتخاذ قرارات</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nمقطع شائع الاستخدام لاتخاذ تلك القرارات\n\n3\n00:00:05.680 --> 00:00:09.240\nهو ''إذا''،''إذن''،\"وإلا\", مقطع ''C''.\n\n4\n00:00:09.240 --> 00:00:10.450\nهذا المقطع موجود\n\n5\n00:00:10.450 --> 00:00:12.853\nفي فئة التحكم في قائمة الأدوات.\n\n6\n00:00:18.320 --> 00:00:21.550\nو يحتوي''إذا'', ''إذن'',\"وإلا\", مقطع ''C'' على جزأين,:\n\n7\n00:00:21.550 --> 00:00:23.080\nفرع \"إذا\", \"إذن\"\n\n8\n00:00:24.220 --> 00:00:25.543\nوالفرع الآخر.\n\n9\n00:00:27.780 --> 00:00:31.610\nإذا كان الشرط في مقطع ''إذا'', ''إذن'', ''C'' صحيحة,\n\n10\n00:00:31.610 --> 00:00:35.550\nالمقاطع الموجودة في ''إذا''، سيتم تشغيل الفرع.\n\n11\n00:00:35.550 --> 00:00:39.450\nإذا كان الشرط في ''إذا'', ''إذن'', ''C'', \"وإلا\" خاطئ\n\n12\n00:00:39.450 --> 00:00:42.363\nسيتم تشغيل المقاطع الموجودة في فرع آخر.\n\n13\n00:00:43.390 --> 00:00:44.720\nشيء واحد يجب أن يوضع في الحسبان\n\n14\n00:00:44.720 --> 00:00:46.810\nهو أن ''إذا'' ، ''إذن'' ''وإلا'' ، مقطع ''C''\n\n15\n00:00:46.810 --> 00:00:49.630\nيتخذ هذا القرار مرة واحدة فقط.\n\n16\n00:00:49.630 --> 00:00:51.810\nمن أجل اتخاذ قرار متكرر،\n\n17\n00:00:51.810 --> 00:00:54.500\nيمكنك وضع ''إذا ''،''إذن''،''وإلا'' مقطع ''C'' ،\n\n18\n00:00:54.500 --> 00:00:56.853\nداخل مقطع ''C'' للأبد.\n\n","cs":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Roboti musí občas dělat rozhodnutí.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nBěžně používaný blok pro tato rozhodnutí\n\n3\n00:00:05.680 --> 00:00:09.240\nje blok Když-tak-jinak.\n\n4\n00:00:09.240 --> 00:00:10.450\nTento blok se nachází\n\n5\n00:00:10.450 --> 00:00:12.853\nv kategorii Ovládání na panelu nástrojů.\n\n6\n00:00:18.320 --> 00:00:21.550\nA blok Když-tak-jinak má dvě části:\n\n7\n00:00:21.550 --> 00:00:23.080\nvětev Když-tak\n\n8\n00:00:24.220 --> 00:00:25.543\na větev Jinak.\n\n9\n00:00:27.780 --> 00:00:31.610\nJestliže je podmínka v bloku Když-tak-jinak splněná,\n\n10\n00:00:31.610 --> 00:00:35.550\nbudou spuštěny bloky, které se nacházejí ve větvi Když-tak.\n\n11\n00:00:35.550 --> 00:00:39.450\nJestliže je podmínka v bloku Když-tak-jinak nepravda,\n\n12\n00:00:39.450 --> 00:00:42.363\nbudou spuštěny bloky, které se nacházejí ve větvi Jinak.\n\n13\n00:00:43.390 --> 00:00:44.720\nJedna věc, kterou je potřeba mít na paměti je,\n\n14\n00:00:44.720 --> 00:00:46.810\nže blok Když-tak-jinak\n\n15\n00:00:46.810 --> 00:00:49.630\ndělá toto rozhodnutí pouze jednou.\n\n16\n00:00:49.630 --> 00:00:51.810\nZa účelem opakovaného rozhodování\n\n17\n00:00:51.810 --> 00:00:54.500\nmůžeš vnořit blok Když-tak-jinak\n\n18\n00:00:54.500 --> 00:00:56.853\ndo bloku Opakuj stále.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>A veces los robots necesitan tomar decisiones.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nUn bloque comúnmente usado para tomar esas decisiones\n\n3\n00:00:05.680 --> 00:00:09.240\nes el bloque C de if-entonces-si no.\n\n4\n00:00:09.240 --> 00:00:10.450\nEste bloque se encuentra\n\n5\n00:00:10.450 --> 00:00:12.853\nen la categoría de control de la caja de herramientas.\n\n6\n00:00:18.320 --> 00:00:21.550\nUn bloque C, de si-entonces-si no, tiene dos partes:\n\n7\n00:00:21.550 --> 00:00:23.080\nla rama de si-entonces\n\n8\n00:00:24.220 --> 00:00:25.543\ny la rama de si no.\n\n9\n00:00:27.780 --> 00:00:31.610\nSi la condición en el bloque C, de si-entonces-si no, es verdad,\n\n10\n00:00:31.610 --> 00:00:35.550\nlos bloques que están en la rama de si-entonces serán ejecutados.\n\n11\n00:00:35.550 --> 00:00:39.450\nSi la condición en el bloque C, de si-entonces-si no, es falso,\n\n12\n00:00:39.450 --> 00:00:42.363\nlos bloques que están en la rama si-no serán ejecutados.\n\n13\n00:00:43.390 --> 00:00:44.720\nUna cosa a tener en cuenta\n\n14\n00:00:44.720 --> 00:00:46.810\nes el bloque C de if-entonces-si no\n\n15\n00:00:46.810 --> 00:00:49.630\nsólo toma esta decisión una vez.\n\n16\n00:00:49.630 --> 00:00:51.810\nPara tomar una decisión repetidamente\n\n17\n00:00:51.810 --> 00:00:54.500\npuede colocar el bloque C, de si-entonces-si no, dentro\n\n18\n00:00:54.500 --> 00:00:56.853\nde un bloque C de Por Siempre.\n\n","es":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>A veces los robots necesitan tomar decisiones.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nUn bloque comúnmente usado para tomar esas decisiones\n\n3\n00:00:05.680 --> 00:00:09.240\nes el bloque C de if-entonces-si no.\n\n4\n00:00:09.240 --> 00:00:10.450\nEste bloque se encuentra\n\n5\n00:00:10.450 --> 00:00:12.853\nen la categoría de control de la caja de herramientas.\n\n6\n00:00:18.320 --> 00:00:21.550\nUn bloque C, de si-entonces-si no, tiene dos partes:\n\n7\n00:00:21.550 --> 00:00:23.080\nla rama de si-entonces\n\n8\n00:00:24.220 --> 00:00:25.543\ny la rama de si no.\n\n9\n00:00:27.780 --> 00:00:31.610\nSi la condición en el bloque C, de si-entonces-si no, es verdad,\n\n10\n00:00:31.610 --> 00:00:35.550\nlos bloques que están en la rama de si-entonces serán ejecutados.\n\n11\n00:00:35.550 --> 00:00:39.450\nSi la condición en el bloque C, de si-entonces-si no, es falso,\n\n12\n00:00:39.450 --> 00:00:42.363\nlos bloques que están en la rama si-no serán ejecutados.\n\n13\n00:00:43.390 --> 00:00:44.720\nUna cosa a tener en cuenta\n\n14\n00:00:44.720 --> 00:00:46.810\nes el bloque C de if-entonces-si no\n\n15\n00:00:46.810 --> 00:00:49.630\nsólo toma esta decisión una vez.\n\n16\n00:00:49.630 --> 00:00:51.810\nPara tomar una decisión repetidamente\n\n17\n00:00:51.810 --> 00:00:54.500\npuede colocar el bloque C, de si-entonces-si no, dentro\n\n18\n00:00:54.500 --> 00:00:56.853\nde un bloque C de Por Siempre.\n\n","fi":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Robottien täytyy joskus tehdä itse päätöksiä.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nNormaalisti käytetty blokki päätöksentekoon\n\n3\n00:00:05.680 --> 00:00:09.240\non Jos niin muuten-blokki.\n\n4\n00:00:09.240 --> 00:00:10.450\nBlokki löytyy\n\n5\n00:00:10.450 --> 00:00:12.853\nOhjaus -työkaluista.\n\n6\n00:00:18.320 --> 00:00:21.550\nJos niin muuten -blokissa on kaksi osaa:\n\n7\n00:00:21.550 --> 00:00:23.080\nJos -haara\n\n8\n00:00:24.220 --> 00:00:25.543\nja Muuten-haara.\n\n9\n00:00:27.780 --> 00:00:31.610\nKun Jos-haaran ehto on tosi\n\n10\n00:00:31.610 --> 00:00:35.550\nblokit sen sisältä suoritetaan.\n\n11\n00:00:35.550 --> 00:00:39.450\nKun Jos -haaran ehto on epätosi\n\n12\n00:00:39.450 --> 00:00:42.363\nhaaran Muuten blokit suoritetaan.\n\n13\n00:00:43.390 --> 00:00:44.720\nAina pitää muistaa,\n\n14\n00:00:44.720 --> 00:00:46.810\nettä Jos niin muuten -blokin\n\n15\n00:00:46.810 --> 00:00:49.630\nehdon laukaisemat suoritukset tehdään aina vain kerran.\n\n16\n00:00:49.630 --> 00:00:51.810\nJos haluat toistaa päätöksenteon,\n\n17\n00:00:51.810 --> 00:00:54.500\nlaita se toistorakenteen\n\n18\n00:00:54.500 --> 00:00:56.853\nToista-blokin sisälle.\n\n","fr":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Les robots ont parfois besoin de prendre des décisions.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nUn bloc communément utilisé pour prendre ces décisions\n\n3\n00:00:05.680 --> 00:00:09.240\nest le bloc C \"si alors sinon\".\n\n4\n00:00:09.240 --> 00:00:10.450\nCe bloc est situé\n\n5\n00:00:10.450 --> 00:00:12.853\ndans la catégorie \"Contrôle\" de la boîte à outils.\n\n6\n00:00:18.320 --> 00:00:21.550\nUn bloc C \"si alors sinon\" a deux parties :\n\n7\n00:00:21.550 --> 00:00:23.080\nla branche \"si alors\"\n\n8\n00:00:24.220 --> 00:00:25.543\net la branche \"sinon\".\n\n9\n00:00:27.780 --> 00:00:31.610\nSi la condition dans le bloc C \"si alors sinon\" est vraie,\n\n10\n00:00:31.610 --> 00:00:35.550\nles blocs qui sont dans la branche \"si alors\" seront exécutés.\n\n11\n00:00:35.550 --> 00:00:39.450\nSi la condition dans le bloc C \"si alors sinon\" est fausse,\n\n12\n00:00:39.450 --> 00:00:42.363\nce les blocs qui sont dans la branche \"sinon\" qui seront exécutés.\n\n13\n00:00:43.390 --> 00:00:44.720\nUne chose à garder à l'esprit\n\n14\n00:00:44.720 --> 00:00:46.810\nest que le bloc C \"si alors sinon\"\n\n15\n00:00:46.810 --> 00:00:49.630\nne prend cette décision qu'une seule fois.\n\n16\n00:00:49.630 --> 00:00:51.810\nPour prendre une décision à plusieurs reprises,\n\n17\n00:00:51.810 --> 00:00:54.500\nvous pouvez placer le bloc C \"si alors sinon\"\n\n18\n00:00:54.500 --> 00:00:56.853\nà l'intérieur d'un bloc C \"Indéfiniment\".\n\n","ko":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>로봇은 때때로 결정을 내려야 합니다.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\n이러한 결정을 내리는 데 일반적으로 사용되는 블록은\n\n3\n00:00:05.680 --> 00:00:09.240\n조건문 C 블록입니다.\n\n4\n00:00:09.240 --> 00:00:10.450\n이 블록은\n\n5\n00:00:10.450 --> 00:00:12.853\n도구 상자의 컨트롤 카테고리에 있습니다.\n\n6\n00:00:18.320 --> 00:00:21.550\n조건문 C 블록은\n\n7\n00:00:21.550 --> 00:00:23.080\n'만약 ~(이)라면'과\n\n8\n00:00:24.220 --> 00:00:25.543\n'아니면'으로 구성됩니다.\n\n9\n00:00:27.780 --> 00:00:31.610\n조건문 C 블록의 조건이 참이면\n\n10\n00:00:31.610 --> 00:00:35.550\n'만약 ~(이)라면'에 있는 블록이 실행됩니다.\n\n11\n00:00:35.550 --> 00:00:39.450\n조건문 C 블록의 조건이 거짓이면\n\n12\n00:00:39.450 --> 00:00:42.363\n'아니면'에 있는 블록이 실행됩니다.\n\n13\n00:00:43.390 --> 00:00:44.720\n한 가지 명심해야 할 점은\n\n14\n00:00:44.720 --> 00:00:46.810\n조건문 C 블록은\n\n15\n00:00:46.810 --> 00:00:49.630\n이 결정을 단 한 번만 내린다는 것입니다.\n\n16\n00:00:49.630 --> 00:00:51.810\n반복해서 결정을 내리기 위해\n\n17\n00:00:51.810 --> 00:00:54.500\n조건문 C 블록을\n\n18\n00:00:54.500 --> 00:00:56.853\n무한 반복 C 블록 안에 배치할 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Kartais robotams reikia priimti sprendimus.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nTiems sprendimams priimti dažniausiai naudojami blokai yra\n\n3\n00:00:05.680 --> 00:00:09.240\n\"jei-tai-arba C\" blokas.\n\n4\n00:00:09.240 --> 00:00:10.450\nŠis blokas yra\n\n5\n00:00:10.450 --> 00:00:12.853\nparankinės valdymo kategorijoje.\n\n6\n00:00:18.320 --> 00:00:21.550\n\"Jei-tai-arba C\" blokas susideda iš dviejų dalių,\n\n7\n00:00:21.550 --> 00:00:23.080\n\"jei\" ir \"tai\" linijos\n\n8\n00:00:24.220 --> 00:00:25.543\nbei \"arba\" linijos.\n\n9\n00:00:27.780 --> 00:00:31.610\nJeigu bloko \"jei-tai-arba C\" sąlyga yra teisinga,\n\n10\n00:00:31.610 --> 00:00:35.550\nbus paleisti tie blokai, kurie yra \"jeigu\" ir \"tai\" linijoje.\n\n11\n00:00:35.550 --> 00:00:39.450\nJeigu bloko \"jei-tai-arba C\" sąlyga yra neteisinga,\n\n12\n00:00:39.450 --> 00:00:42.363\nbus paleisti tie blokai, kurie yra \"arba\" linijoje.\n\n13\n00:00:43.390 --> 00:00:44.720\nSvarbu prisiminti,\n\n14\n00:00:44.720 --> 00:00:46.810\nkad \"jei\", \"tai\", \"arba\" ir \"C\" blokas\n\n15\n00:00:46.810 --> 00:00:49.630\nšį sprendimą priima tik kartą.\n\n16\n00:00:49.630 --> 00:00:51.810\nNorėdami sprendimą priimti pakartotinai,\n\n17\n00:00:51.810 --> 00:00:54.500\n\"jeigu\", \"tai\", \"arba\" ir \"C\" bloką galite įtalpinti\n\n18\n00:00:54.500 --> 00:00:56.853\nį \"amžinai C\" bloką.\n\n","lv":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Robotiem dažkārt ir jāpieņem lēmumi.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nLēmumu pieņemšanai bieži tiek izmantots\n\n3\n00:00:05.680 --> 00:00:09.240\ncikla bloks “if, then”.\n\n4\n00:00:09.240 --> 00:00:10.450\nŠis bloks atrodas\n\n5\n00:00:10.450 --> 00:00:12.853\nrīklodziņa vadības kategorijā.\n\n6\n00:00:18.320 --> 00:00:21.550\nCikla blokam “if, then, else” ir divas daļas:\n\n7\n00:00:21.550 --> 00:00:23.080\n“If, then” atzars\n\n8\n00:00:24.220 --> 00:00:25.543\nun “Else” atzars.\n\n9\n00:00:27.780 --> 00:00:31.610\nJa cikla bloka nosacījums “if, then, else” ir patiess,\n\n10\n00:00:31.610 --> 00:00:35.550\ntiks palaisti bloki, kas ir pievienoti pie daļas “if, then”.\n\n11\n00:00:35.550 --> 00:00:39.450\nJa cikla bloka nosacījums “if, then, else” nav patiess,\n\n12\n00:00:39.450 --> 00:00:42.363\ntiks palaisti bloki, kas ir pievienoti pie daļas “else” (citādāk).\n\n13\n00:00:43.390 --> 00:00:44.720\nViena lieta, kas jāpatur prātā,\n\n14\n00:00:44.720 --> 00:00:46.810\ncikla bloks “if, then, else”\n\n15\n00:00:46.810 --> 00:00:49.630\nšo lēmumu pieņem tikai vienu reizi.\n\n16\n00:00:49.630 --> 00:00:51.810\nLai atkārtoti pieņemtu lēmumu,\n\n17\n00:00:51.810 --> 00:00:54.500\ncikla bloku “if, then, else” var ievietot\n\n18\n00:00:54.500 --> 00:00:56.853\nbezgalīgajā cikla blokā.\n\n","nl":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Robots moeten soms beslissingen nemen.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nEen vaak gebruikt blok om deze beslissingen te nemen\n\n3\n00:00:05.680 --> 00:00:09.240\nis het als, dan, dan anders, C blok.\n\n4\n00:00:09.240 --> 00:00:10.450\nDit blok bevindt zich\n\n5\n00:00:10.450 --> 00:00:12.853\nin de controlecategorie van de toolbox.\n\n6\n00:00:18.320 --> 00:00:21.550\nHet als, dan, dan anders, C blok heeft twee delen:\n\n7\n00:00:21.550 --> 00:00:23.080\nhet als, dan tak\n\n8\n00:00:24.220 --> 00:00:25.543\nen ander de andere tak.\n\n9\n00:00:27.780 --> 00:00:31.610\nAls de voorwaarde in het als, dan, dan anders, C blok waar is,\n\n10\n00:00:31.610 --> 00:00:35.550\nde blokken die in de als, dan tak worden uitgevoerd.\n\n11\n00:00:35.550 --> 00:00:39.450\nAls de voorwaarde in het als, dan, dan anders, C blok onjuist is,\n\n12\n00:00:39.450 --> 00:00:42.363\nde blokken die in de anders tak staan worden uitgevoerd.\n\n13\n00:00:43.390 --> 00:00:44.720\nEén ding om in gedachten te houden\n\n14\n00:00:44.720 --> 00:00:46.810\nis dat het als, dan, dan anders, C blok\n\n15\n00:00:46.810 --> 00:00:49.630\nneemt deze beslissing maar één keer.\n\n16\n00:00:49.630 --> 00:00:51.810\nOm herhaaldelijk een beslissing te nemen\n\n17\n00:00:51.810 --> 00:00:54.500\nu kunt het als, dan, dan anders, C blok\n\n18\n00:00:54.500 --> 00:00:56.853\nbinnen een voor altijd C blok plaatsen.\n\n","pl":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Roboty czasami muszą podejmować decyzje.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nCzęsto używany blok do podejmowania tych decyzji\n\n3\n00:00:05.680 --> 00:00:09.240\njest blokiem C jeżeli-wtedy-w przeciwnym razie.\n\n4\n00:00:09.240 --> 00:00:10.450\nTen blok znajduje się\n\n5\n00:00:10.450 --> 00:00:12.853\nw kategorii kontroli.\n\n6\n00:00:18.320 --> 00:00:21.550\nBlok ten składa się z dwóch części:\n\n7\n00:00:21.550 --> 00:00:23.080\ngałęź: jeżeli wówczas\n\n8\n00:00:24.220 --> 00:00:25.543\ngałęź: inne działanie.\n\n9\n00:00:27.780 --> 00:00:31.610\nJeżeli warunek w bloku jest prawdą,\n\n10\n00:00:31.610 --> 00:00:35.550\nbloki, które znajdują się w gałęzi jeśli, będą uruchomione.\n\n11\n00:00:35.550 --> 00:00:39.450\nJeżeli warunek w bloku jest fałszywy,\n\n12\n00:00:39.450 --> 00:00:42.363\nbloki, które znajdują się w gałęzi w przeciwnym razie, będą uruchomione.\n\n13\n00:00:43.390 --> 00:00:44.720\nJedno o czym należy pamiętać\n\n14\n00:00:44.720 --> 00:00:46.810\nże blok C jeżeli-wtedy-w przeciwnym razie\n\n15\n00:00:46.810 --> 00:00:49.630\npodejmuje tę decyzję tylko raz.\n\n16\n00:00:49.630 --> 00:00:51.810\nW celu wielokrotnego podejmowania decyzji,\n\n17\n00:00:51.810 --> 00:00:54.500\nmożesz umieścić ten blok\n\n18\n00:00:54.500 --> 00:00:56.853\nwewnątrz bloku C \"na zawsze\".\n\n","ru":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Иногда роботу необходимо принимать решения.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nБлоки, которые могут использоваться в данном контексте, это\n\n3\n00:00:05.680 --> 00:00:09.240\nесли, тогда, иначе и С блоки.\n\n4\n00:00:09.240 --> 00:00:10.450\nЭти блоки расположены\n\n5\n00:00:10.450 --> 00:00:12.853\nв категории управления инструментария.\n\n6\n00:00:18.320 --> 00:00:21.550\nБлоки если, тогда, иначе и С блоки состоят из двух частей:\n\n7\n00:00:21.550 --> 00:00:23.080\nесли, затем ветвь\n\n8\n00:00:24.220 --> 00:00:25.543\nи далее иначе.\n\n9\n00:00:27.780 --> 00:00:31.610\nЕсли условие правда, то\n\n10\n00:00:31.610 --> 00:00:35.550\nвыполняются стеки после если.\n\n11\n00:00:35.550 --> 00:00:39.450\nЕсли условия ложь, то\n\n12\n00:00:39.450 --> 00:00:42.363\nвыполняется стек после иначе.\n\n13\n00:00:43.390 --> 00:00:44.720\nЗапомните один момент:\n\n14\n00:00:44.720 --> 00:00:46.810\nблоки если, тогда, иначе, С блоки\n\n15\n00:00:46.810 --> 00:00:49.630\nпринимают решение только один раз.\n\n16\n00:00:49.630 --> 00:00:51.810\nДля многократного принятия решений\n\n17\n00:00:51.810 --> 00:00:54.500\nвы может поместить эти блоки\n\n18\n00:00:54.500 --> 00:00:56.853\nвнутрь С блока «всегда».\n\n","th":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor> บางครั้งหุ่นยนต์จำเป็นต้องทำการตัดสินใจ </v>\n\n2\n00:00:03.060 --> 00:00:05.680\nบล็อกที่ใช้กันทั่วไปในการตัดสินใจเหล่านั้น\n\n3\n00:00:05.680 --> 00:00:09.240\nคือ if then else C บล็อก\n\n4\n00:00:09.240 --> 00:00:10.450\nบล็อกนี้ตั้งอยู่\n\n5\n00:00:10.450 --> 00:00:12.853\nในหมวดควบคุมของกล่องเครื่องมือ\n\n6\n00:00:18.320 --> 00:00:21.550\nและ if then else C บล็อกนี้ ประกอบด้วยสองส่วน\n\n7\n00:00:21.550 --> 00:00:23.080\nส่วนของ if then\n\n8\n00:00:24.220 --> 00:00:25.543\nและส่วนของ else\n\n9\n00:00:27.780 --> 00:00:31.610\nหากเงื่อนไขของ if then else C บล็อกนั้นเป็นจริง\n\n10\n00:00:31.610 --> 00:00:35.550\nบล็อกที่อยู่ใน if then จะถูกทำงาน\n\n11\n00:00:35.550 --> 00:00:39.450\nหากเงื่อนไข if then else C บล็อก เป็นเท็จ\n\n12\n00:00:39.450 --> 00:00:42.363\nบล็อกที่อยู่ใน else จะถูกทำงาน\n\n13\n00:00:43.390 --> 00:00:44.720\nสิ่งหนึ่งที่ควรทราบ\n\n14\n00:00:44.720 --> 00:00:46.810\nคือ if then else C บล็อก\n\n15\n00:00:46.810 --> 00:00:49.630\nจะถูกใช้งานเพียงแค่ครั้งเดียว\n\n16\n00:00:49.630 --> 00:00:51.810\nหากต้องการทำการตรวจสอบเงื่อนไขซ้ำ\n\n17\n00:00:51.810 --> 00:00:54.500\nคุณสามารถวางลงใน if then else C บล็อก\n\n18\n00:00:54.500 --> 00:00:56.853\nลงใน forever C บล็อก\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Іноді робот повинен приймати рішення.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nНайпопулярнішим блоком для рішень\n\n3\n00:00:05.680 --> 00:00:09.240\nє С-подібний блок \"якщо-то-інакше\".\n\n4\n00:00:09.240 --> 00:00:10.450\nЦей блок розміщений\n\n5\n00:00:10.450 --> 00:00:12.853\nу категорії \"Керування\" набору блоків.\n\n6\n00:00:18.320 --> 00:00:21.550\nБлок \"якщо-то-інакше\" має дві частини:\n\n7\n00:00:21.550 --> 00:00:23.080\nчастина \"якщо-то\"\n\n8\n00:00:24.220 --> 00:00:25.543\nі частина \"інакше\".\n\n9\n00:00:27.780 --> 00:00:31.610\nЯкщо умова у блоці \"якщо-то-інакше\" істинна або правильна,\n\n10\n00:00:31.610 --> 00:00:35.550\nспрацюють блоки всередині частини \"якщо-то\".\n\n11\n00:00:35.550 --> 00:00:39.450\nЯкщо ж умова в \"якщо-то-інакше\" хибна або неправильна,\n\n12\n00:00:39.450 --> 00:00:42.363\nспрацюють блоки всередині частини \"інакше\".\n\n13\n00:00:43.390 --> 00:00:44.720\nВарто пам'ятати,\n\n14\n00:00:44.720 --> 00:00:46.810\nщо блок \"якщо-то-інакше\"\n\n15\n00:00:46.810 --> 00:00:49.630\nробить вибір один раз.\n\n16\n00:00:49.630 --> 00:00:51.810\nДля повторюваного вибору\n\n17\n00:00:51.810 --> 00:00:54.500\nпотрібно розмістити блок \"якщо-то-інакше\"\n\n18\n00:00:54.500 --> 00:00:56.853\nвсередині блока \"завжди\".\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n<v Instructor>Đôi khi, rô bốt cần đưa ra quyết định.</v>\n\n2\n00:00:03.060 --> 00:00:05.680\nMột khối thường được sử dụng để đưa ra những quyết định đó\n\n3\n00:00:05.680 --> 00:00:09.240\nlà khối if then else C.\n\n4\n00:00:09.240 --> 00:00:10.450\nKhối này nằm\n\n5\n00:00:10.450 --> 00:00:12.853\ntrong danh mục điều khiển của hộp công cụ.\n\n6\n00:00:18.320 --> 00:00:21.550\nVà if then else khối C có hai phần:\n\n7\n00:00:21.550 --> 00:00:23.080\nnhánh if then\n\n8\n00:00:24.220 --> 00:00:25.543\nvà nhánh khác.\n\n9\n00:00:27.780 --> 00:00:31.610\nNếu điều kiện trong khối if thì else C là đúng,\n\n10\n00:00:31.610 --> 00:00:35.550\ncác khối nằm trong nhánh if then sẽ được chạy.\n\n11\n00:00:35.550 --> 00:00:39.450\nNếu điều kiện trong khối if then else C là false,\n\n12\n00:00:39.450 --> 00:00:42.363\ncác khối nằm trong nhánh khác sẽ được chạy.\n\n13\n00:00:43.390 --> 00:00:44.720\nMột điều cần lưu ý\n\n14\n00:00:44.720 --> 00:00:46.810\nđó có phải là khối if thì else C không\n\n15\n00:00:46.810 --> 00:00:49.630\nchỉ đưa ra quyết định này một lần.\n\n16\n00:00:49.630 --> 00:00:51.810\nĐể liên tục đưa ra quyết định,\n\n17\n00:00:51.810 --> 00:00:54.500\nbạn có thể đặt khối if then else C\n\n18\n00:00:54.500 --> 00:00:56.853\nbên trong của một khối C mãi mãi.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\ncrwdns96678:0crwdne96678:0\n\n2\n00:00:03.060 --> 00:00:05.680\ncrwdns96680:0crwdne96680:0\n\n3\n00:00:05.680 --> 00:00:09.240\ncrwdns96682:0crwdne96682:0\n\n4\n00:00:09.240 --> 00:00:10.450\ncrwdns96684:0crwdne96684:0\n\n5\n00:00:10.450 --> 00:00:12.853\ncrwdns96686:0crwdne96686:0\n\n6\n00:00:18.320 --> 00:00:21.550\ncrwdns96688:0crwdne96688:0\n\n7\n00:00:21.550 --> 00:00:23.080\ncrwdns96690:0crwdne96690:0\n\n8\n00:00:24.220 --> 00:00:25.543\ncrwdns96692:0crwdne96692:0\n\n9\n00:00:27.780 --> 00:00:31.610\ncrwdns96694:0crwdne96694:0\n\n10\n00:00:31.610 --> 00:00:35.550\ncrwdns96696:0crwdne96696:0\n\n11\n00:00:35.550 --> 00:00:39.450\ncrwdns96698:0crwdne96698:0\n\n12\n00:00:39.450 --> 00:00:42.363\ncrwdns96700:0crwdne96700:0\n\n13\n00:00:43.390 --> 00:00:44.720\ncrwdns96702:0crwdne96702:0\n\n14\n00:00:44.720 --> 00:00:46.810\ncrwdns96704:0crwdne96704:0\n\n15\n00:00:46.810 --> 00:00:49.630\ncrwdns96706:0crwdne96706:0\n\n16\n00:00:49.630 --> 00:00:51.810\ncrwdns96708:0crwdne96708:0\n\n17\n00:00:51.810 --> 00:00:54.500\ncrwdns96710:0crwdne96710:0\n\n18\n00:00:54.500 --> 00:00:56.853\ncrwdns96712:0crwdne96712:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.220 --> 00:00:03.060\n机器人有时需要作决策。\n\n2\n00:00:03.060 --> 00:00:05.680\n一个经常使用的做这些决策的指令块\n\n3\n00:00:05.680 --> 00:00:09.240\n是“如果，那么，否则”C型指令块。\n\n4\n00:00:09.240 --> 00:00:10.450\n本指令块位于\n\n5\n00:00:10.450 --> 00:00:12.853\n工具栏“控制”类别中。\n\n6\n00:00:18.320 --> 00:00:21.550\n“如果，那么，否则”C型指令块有两个部分，\n\n7\n00:00:21.550 --> 00:00:23.080\n“如果，那么”部分，\n\n8\n00:00:24.220 --> 00:00:25.543\n以及“否则”部分。\n\n9\n00:00:27.780 --> 00:00:31.610\n如果“如果-那么-否则”C型指令块中的条件为真，\n\n10\n00:00:31.610 --> 00:00:35.550\n在“如果，那么”部分的指令块将被运行。\n\n11\n00:00:35.550 --> 00:00:39.450\n如果“如果-那么-否则”C型指令块中的条件为假，\n\n12\n00:00:39.450 --> 00:00:42.363\n则“否则”部分里面的指令块就会运行。\n\n13\n00:00:43.390 --> 00:00:44.720\n有一件事要记住的\n\n14\n00:00:44.720 --> 00:00:46.810\n是“如果，那么，否则”C型指令块\n\n15\n00:00:46.810 --> 00:00:49.630\n只能作一次决策。\n\n16\n00:00:49.630 --> 00:00:51.810\n如果要反复地作决策，\n\n17\n00:00:51.810 --> 00:00:54.500\n您可以放置“如果，那么，否则”C型指令块\n\n18\n00:00:54.500 --> 00:00:56.853\n到“永久循环”C型指令块中。\n\n"}},{"thumb":"Tutorial_myBlocks_v2.jpg","mov":"V5_Blocks_MyBlocks_V2","description":"My Blocks","filter":"","placeholder":false,"vimeo":"475899998","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Sometimes you will want</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nto use a sequence of blocks multiple times\n\n3\n00:00:04.430 --> 00:00:06.510\nin the same project.\n\n4\n00:00:06.510 --> 00:00:09.150\nInstead of recreating the same sequence each time,\n\n5\n00:00:09.150 --> 00:00:11.650\nit is easier to group the sequence of blocks\n\n6\n00:00:11.650 --> 00:00:14.020\ninto one single block.\n\n7\n00:00:14.020 --> 00:00:15.820\nBy creating a My Block,\n\n8\n00:00:15.820 --> 00:00:18.370\nyou only need to create the sequence once\n\n9\n00:00:18.370 --> 00:00:20.550\nand then you can reuse it.\n\n10\n00:00:20.550 --> 00:00:22.700\nThis can help break up longer projects\n\n11\n00:00:22.700 --> 00:00:25.210\nto make them easier to work with.\n\n12\n00:00:25.210 --> 00:00:27.590\nMy Blocks can be customized.\n\n13\n00:00:27.590 --> 00:00:28.863\nYou can name the block,\n\n14\n00:00:30.210 --> 00:00:35.210\nadd a number input, a boolean input or another label.\n\n15\n00:00:46.660 --> 00:00:50.040\nOnce the block is customized, select Okay\n\n16\n00:00:50.040 --> 00:00:54.240\nto save the changes or cancel to remove them.\n\n17\n00:00:54.240 --> 00:00:58.080\nTo delete an input or label, select the clear icon\n\n18\n00:00:58.080 --> 00:00:59.993\nabove the item to delete it.\n\n19\n00:01:01.110 --> 00:01:03.390\nOnce the My Block has been created,\n\n20\n00:01:03.390 --> 00:01:06.160\nthe defined block will appear.\n\n21\n00:01:06.160 --> 00:01:08.760\nAdd blocks to the defined block that will be reused.\n\n22\n00:01:14.960 --> 00:01:17.400\nParameters for the defined block can be used\n\n23\n00:01:17.400 --> 00:01:19.703\nonce additional blocks are added to it.\n\n24\n00:01:22.420 --> 00:01:26.093\nFinally, attach the My Block to the When Started Block.\n\n25\n00:01:27.770 --> 00:01:30.480\nThe blocks under the defined block are now grouped\n\n26\n00:01:30.480 --> 00:01:32.630\ninto the My Block.\n\n27\n00:01:32.630 --> 00:01:35.853\nYour My Block is now created and ready to be used.\n\n","ar":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>في بعض الأحيان ستريد</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nإستخدام سلسلة من المقاطع عدة مرات\n\n3\n00:00:04.430 --> 00:00:06.510\nفي نفس المشروع.\n\n4\n00:00:06.510 --> 00:00:09.150\nبدلا من إعادة إنشاء نفس التسلسل في كل مرة،\n\n5\n00:00:09.150 --> 00:00:11.650\nمن الأسهل تجميع تسلسل المقاطع\n\n6\n00:00:11.650 --> 00:00:14.020\nإلى مقطع واحد.\n\n7\n00:00:14.020 --> 00:00:15.820\nعن طريق إنشاء My Block\n\n8\n00:00:15.820 --> 00:00:18.370\nتحتاج فقط إلى إنشاء التسلسل مرة واحدة،\n\n9\n00:00:18.370 --> 00:00:20.550\nومن ثم يمكنك إعادة استخدامه.\n\n10\n00:00:20.550 --> 00:00:22.700\nهذا يمكن أن يساعد على تفكيك مشاريع أطول\n\n11\n00:00:22.700 --> 00:00:25.210\nلجعلهم أكثر سهولة في العمل.\n\n12\n00:00:25.210 --> 00:00:27.590\nيمكن تخصيص عناصر برمجة جديدة.\n\n13\n00:00:27.590 --> 00:00:28.863\nيمكنك تسمية المقطع ،\n\n14\n00:00:30.210 --> 00:00:35.210\nإضافة مدخلات رقمية ، مدخلات منطقية أو تسمية أخرى.\n\n15\n00:00:46.660 --> 00:00:50.040\nبمجرد تخصيص المقاطع، حدد حسنا\n\n16\n00:00:50.040 --> 00:00:54.240\nلحفظ التغييرات، أو إلغاء لإزالتها.\n\n17\n00:00:54.240 --> 00:00:58.080\nلحذف إدخال أو تسمية ، حدد الرمز الواضح\n\n18\n00:00:58.080 --> 00:00:59.993\nفوق العنصر لحذفه.\n\n19\n00:01:01.110 --> 00:01:03.390\nبمجرد أن يتم إنشاء My Block\n\n20\n00:01:03.390 --> 00:01:06.160\nسيظهر المقطع المحدد.\n\n21\n00:01:06.160 --> 00:01:08.760\nضف مقاطع إلى المقاطع المحددة التي سيتم إعادة استخدامها.\n\n22\n00:01:14.960 --> 00:01:17.400\nالمحددات للمقاطع\n\n23\n00:01:17.400 --> 00:01:19.703\nيمكن استخدامها بمجرد إضافة مقاطع إضافية إليها.\n\n24\n00:01:22.420 --> 00:01:26.093\nأخيرا، أرفق عناصر البرمجة بمقطع ''عند بدء''.\n\n25\n00:01:27.770 --> 00:01:30.480\nتم تجميع المقاطع تحت المقطع المحدد الآن\n\n26\n00:01:30.480 --> 00:01:32.630\nفي عناصر البرمجة جديدة.\n\n27\n00:01:32.630 --> 00:01:35.853\nتم إنشاء My Block الخاص بك الآن وجاهز للاستخدام.\n\n","cs":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Občas budeš chtít</v>\n\n2\n00:00:01.890 --> 00:00:04.430\npoužít posloupnost bloků vícekrát\n\n3\n00:00:04.430 --> 00:00:06.510\nve stejném projektu.\n\n4\n00:00:06.510 --> 00:00:09.150\nNamísto vytváření stejné posloupnosti pořád dokola\n\n5\n00:00:09.150 --> 00:00:11.650\nje jednodušší danou posloupnost bloků seskupit\n\n6\n00:00:11.650 --> 00:00:14.020\ndo jediného bloku.\n\n7\n00:00:14.020 --> 00:00:15.820\nVytvořením Mého bloku\n\n8\n00:00:15.820 --> 00:00:18.370\nbudeš muset vytvořit posloupnost pouze jednou\n\n9\n00:00:18.370 --> 00:00:20.550\na potom ji můžeš opakovaně používat.\n\n10\n00:00:20.550 --> 00:00:22.700\nToto může pomoci rozložit delší projekty\n\n11\n00:00:22.700 --> 00:00:25.210\ntak, aby se s nimi jednodušeji pracovalo.\n\n12\n00:00:25.210 --> 00:00:27.590\nMoje bloky mohou být upravovány.\n\n13\n00:00:27.590 --> 00:00:28.863\nBlok si můžeš pojmenovat,\n\n14\n00:00:30.210 --> 00:00:35.210\npřidat číselný vstup, logický vstup, nebo jiný popisek.\n\n15\n00:00:46.660 --> 00:00:50.040\nJakmile je blok upraven, vyber OK\n\n16\n00:00:50.040 --> 00:00:54.240\npro uložení změn, nebo Zrušit pro jejich odstranění.\n\n17\n00:00:54.240 --> 00:00:58.080\nPro smazání vstupu nebo popisku, vyber ikonku Vymazat\n\n18\n00:00:58.080 --> 00:00:59.993\nnad položkou, kterou chceš odstranit.\n\n19\n00:01:01.110 --> 00:01:03.390\nJakmile je Můj blok vytvořen,\n\n20\n00:01:03.390 --> 00:01:06.160\nobjeví se blok Definuj.\n\n21\n00:01:06.160 --> 00:01:08.760\nPřidej bloky k bloku Definuj, který bude opětovně používán.\n\n22\n00:01:14.960 --> 00:01:17.400\nParametry z bloku Definuj mohou být použity\n\n23\n00:01:17.400 --> 00:01:19.703\njakmile jsou do něj přidány další bloky.\n\n24\n00:01:22.420 --> 00:01:26.093\nNakonec připoj Můj blok k bloku Při spuštění.\n\n25\n00:01:27.770 --> 00:01:30.480\nBloky pod blokem Definuj jsou nyní seskupeny\n\n26\n00:01:30.480 --> 00:01:32.630\ndo Mého bloku.\n\n27\n00:01:32.630 --> 00:01:35.853\nTvůj Můj blok je nyní vytvořen a připraven k použití.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>A veces, querrá usar</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nuna secuencia de bloques múltiples veces\n\n3\n00:00:04.430 --> 00:00:06.510\nen el mismo proyecto.\n\n4\n00:00:06.510 --> 00:00:09.150\nEn lugar de recrear la misma secuencia cada vez,\n\n5\n00:00:09.150 --> 00:00:11.650\nes más fácil agrupar la secuencia de Bloques\n\n6\n00:00:11.650 --> 00:00:14.020\nen un solo bloque.\n\n7\n00:00:14.020 --> 00:00:15.820\nCreando un \"Mi Block\",\n\n8\n00:00:15.820 --> 00:00:18.370\nsolo necesitaras crear la secuencia una vez\n\n9\n00:00:18.370 --> 00:00:20.550\ny luego puede reutilizarlo.\n\n10\n00:00:20.550 --> 00:00:22.700\nEsto puede ayudar a dividir proyectos más largos\n\n11\n00:00:22.700 --> 00:00:25.210\npara hacerlos más fáciles de trabajar.\n\n12\n00:00:25.210 --> 00:00:27.590\nMis Bloques pueden ser personalizados.\n\n13\n00:00:27.590 --> 00:00:28.863\nPuede nombrar el bloque,\n\n14\n00:00:30.210 --> 00:00:35.210\nañadir una entrada de número, una entrada booleana u otra etiqueta.\n\n15\n00:00:46.660 --> 00:00:50.040\nUna vez que el bloque está personalizado, seleccione OK\n\n16\n00:00:50.040 --> 00:00:54.240\npara guardar los cambios o Cancelar para eliminarlos.\n\n17\n00:00:54.240 --> 00:00:58.080\nPara eliminar una entrada o etiqueta, seleccione el icono de Borrar\n\n18\n00:00:58.080 --> 00:00:59.993\narriba del articulo para eliminarlo.\n\n19\n00:01:01.110 --> 00:01:03.390\nUna vez que Mi Bloque ha sido creado,\n\n20\n00:01:03.390 --> 00:01:06.160\naparecerá el bloque \"definir\".\n\n21\n00:01:06.160 --> 00:01:08.760\nAgrega bloques al Bloque Definir que serán reutilizados.\n\n22\n00:01:14.960 --> 00:01:17.400\nParámetros del \"Bloque Definir\" pueden utilizarse\n\n23\n00:01:17.400 --> 00:01:19.703\nuna vez que se le agregan Bloques adicionales.\n\n24\n00:01:22.420 --> 00:01:26.093\nFinalmente, conecte el Mi Bloque al Bloque Cuando Empieza.\n\n25\n00:01:27.770 --> 00:01:30.480\nLos bloques bajo el bloque \"definir\" ahora están agrupados\n\n26\n00:01:30.480 --> 00:01:32.630\nen \"Mi Bloque\".\n\n27\n00:01:32.630 --> 00:01:35.853\nSu Mi Bloque ha sido creado y listo para ser usado.\n\n","es":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>A veces, querrá usar</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nuna secuencia de bloques múltiples veces\n\n3\n00:00:04.430 --> 00:00:06.510\nen el mismo proyecto.\n\n4\n00:00:06.510 --> 00:00:09.150\nEn lugar de recrear la misma secuencia cada vez,\n\n5\n00:00:09.150 --> 00:00:11.650\nes más fácil agrupar la secuencia de Bloques\n\n6\n00:00:11.650 --> 00:00:14.020\nen un solo bloque.\n\n7\n00:00:14.020 --> 00:00:15.820\nCreando un \"Mi Block\",\n\n8\n00:00:15.820 --> 00:00:18.370\nsolo necesitaras crear la secuencia una vez\n\n9\n00:00:18.370 --> 00:00:20.550\ny luego puede reutilizarlo.\n\n10\n00:00:20.550 --> 00:00:22.700\nEsto puede ayudar a dividir proyectos más largos\n\n11\n00:00:22.700 --> 00:00:25.210\npara hacerlos más fáciles de trabajar.\n\n12\n00:00:25.210 --> 00:00:27.590\nMis Bloques pueden ser personalizados.\n\n13\n00:00:27.590 --> 00:00:28.863\nPuede nombrar el bloque,\n\n14\n00:00:30.210 --> 00:00:35.210\nañadir una entrada de número, una entrada booleana u otra etiqueta.\n\n15\n00:00:46.660 --> 00:00:50.040\nUna vez que el bloque está personalizado, seleccione OK\n\n16\n00:00:50.040 --> 00:00:54.240\npara guardar los cambios o Cancelar para eliminarlos.\n\n17\n00:00:54.240 --> 00:00:58.080\nPara eliminar una entrada o etiqueta, seleccione el icono de Borrar\n\n18\n00:00:58.080 --> 00:00:59.993\narriba del articulo para eliminarlo.\n\n19\n00:01:01.110 --> 00:01:03.390\nUna vez que Mi Bloque ha sido creado,\n\n20\n00:01:03.390 --> 00:01:06.160\naparecerá el bloque \"definir\".\n\n21\n00:01:06.160 --> 00:01:08.760\nAgrega bloques al Bloque Definir que serán reutilizados.\n\n22\n00:01:14.960 --> 00:01:17.400\nParámetros del \"Bloque Definir\" pueden utilizarse\n\n23\n00:01:17.400 --> 00:01:19.703\nuna vez que se le agregan Bloques adicionales.\n\n24\n00:01:22.420 --> 00:01:26.093\nFinalmente, conecte el Mi Bloque al Bloque Cuando Empieza.\n\n25\n00:01:27.770 --> 00:01:30.480\nLos bloques bajo el bloque \"definir\" ahora están agrupados\n\n26\n00:01:30.480 --> 00:01:32.630\nen \"Mi Bloque\".\n\n27\n00:01:32.630 --> 00:01:35.853\nSu Mi Bloque ha sido creado y listo para ser usado.\n\n","fi":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Joskus voit haluta</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nkäyttää samaa blokkijonoa useampaan kertaan\n\n3\n00:00:04.430 --> 00:00:06.510\nohjelmassasi.\n\n4\n00:00:06.510 --> 00:00:09.150\nSen sijaan, että kopioisit blokit uudelleen ohjelmassa\n\n5\n00:00:09.150 --> 00:00:11.650\nvoit ryhmitellä blokit\n\n6\n00:00:11.650 --> 00:00:14.020\nyhdeksi blokiksi.\n\n7\n00:00:14.020 --> 00:00:15.820\nKun painat Omat blokit -valinnassa Tee blokki-painonappia\n\n8\n00:00:15.820 --> 00:00:18.370\nsaat luotua aliohjelmana saman toistettavan blokkijonon\n\n9\n00:00:18.370 --> 00:00:20.550\nja voit kutsua sitä useamman kerran ohjelmassa.\n\n10\n00:00:20.550 --> 00:00:22.700\nTämä selventää ja lyhentää pitkiä ohjelmia\n\n11\n00:00:22.700 --> 00:00:25.210\njolloin on helpompi hallita ohjelmaa.\n\n12\n00:00:25.210 --> 00:00:27.590\nOmaa blokkia voi räätälöidä.\n\n13\n00:00:27.590 --> 00:00:28.863\nVoit nimetä oman blokkisi\n\n14\n00:00:30.210 --> 00:00:35.210\nlisätä parametreihin numeromuuttujia, boolean muuttujia ja selventää käyttöä teksteillä.\n\n15\n00:00:46.660 --> 00:00:50.040\nKun aliohjelmablokkisi on määritelty valitse OK -painike\n\n16\n00:00:50.040 --> 00:00:54.240\ntalletaksesi muutokset tai Peruuta, jos hylkäät muutokset.\n\n17\n00:00:54.240 --> 00:00:58.080\nJos haluat korjata parametreja tai tekstejä, valitse Roskakori-ikoni\n\n18\n00:00:58.080 --> 00:00:59.993\nsiinä kohtaan kutsua, jossa haluat parametrin tai tekstin poistaa.\n\n19\n00:01:01.110 --> 00:01:03.390\nKun Minun Blokit on luotu,\n\n20\n00:01:03.390 --> 00:01:06.160\nDefine oma blokki -nimellä ilmestyy työalueelle.\n\n21\n00:01:06.160 --> 00:01:08.760\nLisää Define-aloitusblokin alle ne blokit, joita toistuvasti tarvitset.\n\n22\n00:01:14.960 --> 00:01:17.400\nParametrien arvot annetaan kutsuttaessa pääohjelmassa ja niitä voi aliohjelmassa sen jälkeen muuttujina käyttää\n\n23\n00:01:17.400 --> 00:01:19.703\nDefine -aloitusblokissa blokkikomennoissa samoilla nimillä.\n\n24\n00:01:22.420 --> 00:01:26.093\nLisää Minun Blokit -kutsut Kun käynnissä-pääohjelmaan.\n\n25\n00:01:27.770 --> 00:01:30.480\nDefine-blokin alle on nyt valittu toistettavat blokit\n\n26\n00:01:30.480 --> 00:01:32.630\nMinun blokit -toiminnolla.\n\n27\n00:01:32.630 --> 00:01:35.853\nNyt luomasi Minun blokit -aliohjelma on valmis.\n\n","fr":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Parfois, vous voudrez</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nutiliser une séquence de blocs plusieurs fois\n\n3\n00:00:04.430 --> 00:00:06.510\ndans le même projet.\n\n4\n00:00:06.510 --> 00:00:09.150\nAu lieu de recréer la même séquence à chaque fois,\n\n5\n00:00:09.150 --> 00:00:11.650\nil est plus facile de regrouper la séquence de Blocs\n\n6\n00:00:11.650 --> 00:00:14.020\nen un seul bloc.\n\n7\n00:00:14.020 --> 00:00:15.820\nEn créant un \"Mon bloc\",\n\n8\n00:00:15.820 --> 00:00:18.370\nvous n'avez besoin de créer la séquence qu'une seule fois\n\n9\n00:00:18.370 --> 00:00:20.550\net vous pouvez ensuite la réutiliser.\n\n10\n00:00:20.550 --> 00:00:22.700\nCela peut aider à segmenter des projets plus longs\n\n11\n00:00:22.700 --> 00:00:25.210\npour les rendre plus faciles à utiliser.\n\n12\n00:00:25.210 --> 00:00:27.590\nLes \"Mes blocs\" peuvent être personnalisés.\n\n13\n00:00:27.590 --> 00:00:28.863\nVous pouvez nommer le bloc,\n\n14\n00:00:30.210 --> 00:00:35.210\najouter un nombre ou un booléen en entrée, ou une autre étiquette.\n\n15\n00:00:46.660 --> 00:00:50.040\nUne fois le bloc personnalisé, sélectionnez \"OK\"\n\n16\n00:00:50.040 --> 00:00:54.240\npour enregistrer les modifications ou \"Annuler\" pour les supprimer.\n\n17\n00:00:54.240 --> 00:00:58.080\nPour supprimer une entrée ou un libellé, sélectionnez l'icône de corbeille\n\n18\n00:00:58.080 --> 00:00:59.993\nau-dessus de l'élément pour le supprimer.\n\n19\n00:01:01.110 --> 00:01:03.390\nUne fois que le \"Mon bloc\" a été créé,\n\n20\n00:01:03.390 --> 00:01:06.160\nun bloc \"Définir\" va apparaître.\n\n21\n00:01:06.160 --> 00:01:08.760\nAjouter les blocs qui seront réutilisés au bloc \"Définir\".\n\n22\n00:01:14.960 --> 00:01:17.400\nLes paramètres du bloc \"Définir\" peuvent être utilisés\n\n23\n00:01:17.400 --> 00:01:19.703\nune fois que des blocs supplémentaires y ont été ajoutés.\n\n24\n00:01:22.420 --> 00:01:26.093\nEnfin, attachez le bloc \"Mon Bloc\" au bloc \"Au démarrage\".\n\n25\n00:01:27.770 --> 00:01:30.480\nLes blocs sous le bloc \"Définir\" sont maintenant regroupés\n\n26\n00:01:30.480 --> 00:01:32.630\ndans \"Mon Bloc\".\n\n27\n00:01:32.630 --> 00:01:35.853\nVotre bloc \"Mon bloc\" est maintenant créé et prêt à être utilisé.\n\n","ko":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>때로는</v>\n\n2\n00:00:01.890 --> 00:00:04.430\n동일한 프로젝트에서 일련의 블록들을\n\n3\n00:00:04.430 --> 00:00:06.510\n여러 번 사용하고 싶을 수 있습니다.\n\n4\n00:00:06.510 --> 00:00:09.150\n매번 동일한 시퀀스를 다시 만드는 대신\n\n5\n00:00:09.150 --> 00:00:11.650\n일련의 블록들을 하나로\n\n6\n00:00:11.650 --> 00:00:14.020\n그룹화하는 것이 더 쉽습니다.\n\n7\n00:00:14.020 --> 00:00:15.820\n'내 블록'을 만들면\n\n8\n00:00:15.820 --> 00:00:18.370\n시퀀스를 한 번만 만들어서\n\n9\n00:00:18.370 --> 00:00:20.550\n다시 사용할 수 있습니다.\n\n10\n00:00:20.550 --> 00:00:22.700\n이렇게 하면 긴 프로젝트를 나누어\n\n11\n00:00:22.700 --> 00:00:25.210\n더 쉽게 작업할 수 있습니다.\n\n12\n00:00:25.210 --> 00:00:27.590\n'내 블록'은 사용자가 정의할 수 있습니다.\n\n13\n00:00:27.590 --> 00:00:28.863\n블록 이름 정하기, 숫자 입력하기,\n\n14\n00:00:30.210 --> 00:00:35.210\n부울을 입력하거나 다른 레이블을 추가할 수 있습니다.\n\n15\n00:00:46.660 --> 00:00:50.040\n블록을 원하는 대로 만들고\n\n16\n00:00:50.040 --> 00:00:54.240\n변경 사항을 저장하려면 확인을, 제거하려면 취소를 선택합니다.\n\n17\n00:00:54.240 --> 00:00:58.080\n입력 또는 레이블을 삭제하고 싶으면\n\n18\n00:00:58.080 --> 00:00:59.993\n그 항목 위에 있는 삭제 아이콘을 선택합니다.\n\n19\n00:01:01.110 --> 00:01:03.390\n'내 블록'이 만들어지면\n\n20\n00:01:03.390 --> 00:01:06.160\n블록 정의가 나타납니다.\n\n21\n00:01:06.160 --> 00:01:08.760\n다시 사용할 블록을 블록 정의에 추가하세요.\n\n22\n00:01:14.960 --> 00:01:17.400\n정의된 블록에 대한 매개 변수는\n\n23\n00:01:17.400 --> 00:01:19.703\n블록이 추가되면 사용할 수 있습니다.\n\n24\n00:01:22.420 --> 00:01:26.093\n마지막으로 '내 블록'을 '시작하기' 블록에 연결합니다.\n\n25\n00:01:27.770 --> 00:01:30.480\n블록 정의 아래 블록들은\n\n26\n00:01:30.480 --> 00:01:32.630\n이제 '내 블록'으로 그룹화됩니다.\n\n27\n00:01:32.630 --> 00:01:35.853\n이제 '내 블록'이 만들어지고 사용할 준비가 되었습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Kartais norėsite</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nkelis kartus tame pačiame projekte\n\n3\n00:00:04.430 --> 00:00:06.510\nnaudoti sekos blokus.\n\n4\n00:00:06.510 --> 00:00:09.150\nVietoje to, kad kiekvieną kartą atkurtumėte tą pačią seką,\n\n5\n00:00:09.150 --> 00:00:11.650\nlengviau grupuoti blokų seką\n\n6\n00:00:11.650 --> 00:00:14.020\nį vieną bloką.\n\n7\n00:00:14.020 --> 00:00:15.820\nSukurdami \"Mano blokas\",\n\n8\n00:00:15.820 --> 00:00:18.370\nJums seką reikės sukurti tik kartą\n\n9\n00:00:18.370 --> 00:00:20.550\nir po to ją galėsite panaudoti iš naujo.\n\n10\n00:00:20.550 --> 00:00:22.700\nTai gali palengvinti ilgesnių projektų skirstymą,\n\n11\n00:00:22.700 --> 00:00:25.210\ndarbą su jais padarant lengvesniu.\n\n12\n00:00:25.210 --> 00:00:27.590\nGalite pritaikyti \"Mano blokus\".\n\n13\n00:00:27.590 --> 00:00:28.863\nGalite suteikti pavadinimą blokui,\n\n14\n00:00:30.210 --> 00:00:35.210\npridėti skaitinę, Būlio įvestį ar kitokią žymą.\n\n15\n00:00:46.660 --> 00:00:50.040\nPritaikę bloką, spustelėkite \"Gerai\"\n\n16\n00:00:50.040 --> 00:00:54.240\npakeitimams išsaugoti arba \"Atšaukti\" jiems panaikinti.\n\n17\n00:00:54.240 --> 00:00:58.080\nNorėdami ištrinti įvestį arba žymą, spustelėkite aukščiau elemento\n\n18\n00:00:58.080 --> 00:00:59.993\nesančią ištrynimo ikoną.\n\n19\n00:01:01.110 --> 00:01:03.390\nSukūrus \"Mano bloką\",\n\n20\n00:01:03.390 --> 00:01:06.160\npasirodys \"Bloko apibrėžimas\".\n\n21\n00:01:06.160 --> 00:01:08.760\nBlokus, kuriuos naudosite dar kartą, pridėkite prie \"Bloko apibrėžimo\".\n\n22\n00:01:14.960 --> 00:01:17.400\n\"Bloko apibrėžimo\" parametrus galite naudoti,\n\n23\n00:01:17.400 --> 00:01:19.703\nkai pridedami papildomi blokai.\n\n24\n00:01:22.420 --> 00:01:26.093\nGaliausiai, \"Mano bloką\" pridėkite prie \"kada pradėti\" bloko.\n\n25\n00:01:27.770 --> 00:01:30.480\nĮ \"bloko apibrėžimą\" patenkantys blokai grupuojami\n\n26\n00:01:30.480 --> 00:01:32.630\nį \"Mano blokas\".\n\n27\n00:01:32.630 --> 00:01:35.853\n\"Mano blokas\" sukurtas ir parengtas naudoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Dažkārt vēlēsities</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nizmantot bloku secību vairākas reizes\n\n3\n00:00:04.430 --> 00:00:06.510\nvienā projektā.\n\n4\n00:00:06.510 --> 00:00:09.150\nTā vietā, lai katru reizi izveidotu vienu un to pašu virkni,\n\n5\n00:00:09.150 --> 00:00:11.650\nir vieglāk grupēt bloku virkni\n\n6\n00:00:11.650 --> 00:00:14.020\nvienā blokā.\n\n7\n00:00:14.020 --> 00:00:15.820\nIzveidojot “My Block”,\n\n8\n00:00:15.820 --> 00:00:18.370\nbloku virkni jāizveido tikai vienu reizi\n\n9\n00:00:18.370 --> 00:00:20.550\nun tad to var atkārtoti izmantot.\n\n10\n00:00:20.550 --> 00:00:22.700\nTas var palīdzēt strukturēt garus projektus,\n\n11\n00:00:22.700 --> 00:00:25.210\natvieglojot darbu ar tiem.\n\n12\n00:00:25.210 --> 00:00:27.590\nPašu izveidotus blokus var pielāgot.\n\n13\n00:00:27.590 --> 00:00:28.863\nVariet nosaukt bloku,\n\n14\n00:00:30.210 --> 00:00:35.210\npievienot numura ievadi, Būla ievadi vai citu apzīmējumu.\n\n15\n00:00:46.660 --> 00:00:50.040\nKad bloks ir pielāgots, atlasiet “Okay”,\n\n16\n00:00:50.040 --> 00:00:54.240\nlai saglabātu izmaiņas, vai “Cancel”, lai tās noņemtu.\n\n17\n00:00:54.240 --> 00:00:58.080\nLai izdzēstu ievadi vai apzīmējumu, izvēlieties notīrīšanas ikonu\n\n18\n00:00:58.080 --> 00:00:59.993\nvirs vienuma, lai to izdzēstu.\n\n19\n00:01:01.110 --> 00:01:03.390\nKad ir izveidots “My Block” (mans bloks),\n\n20\n00:01:03.390 --> 00:01:06.160\ntiks norādīts bloks “Define Block”.\n\n21\n00:01:06.160 --> 00:01:08.760\nPievienojiet blokus pie definētā bloka, kas tiks izmantots atkārtoti.\n\n22\n00:01:14.960 --> 00:01:17.400\nDefinētā bloka parametrus var pielietot,\n\n23\n00:01:17.400 --> 00:01:19.703\nkad pie tā ir pievienoti papildu bloki.\n\n24\n00:01:22.420 --> 00:01:26.093\nPievienojiet bloku “My Block” blokam “When Started”.\n\n25\n00:01:27.770 --> 00:01:30.480\nBloki zem definētā bloka tagad ir grupēti\n\n26\n00:01:30.480 --> 00:01:32.630\nblokā “My Block”.\n\n27\n00:01:32.630 --> 00:01:35.853\nJūsu bloks “My Block” ir izveidots un gatavs lietošanai.\n\n","nl":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor> Soms wilt u</v>\n\n2\n00:00:01.890 --> 00:00:04.430\ndat een volgorde blokken meerdere keren\n\n3\n00:00:04.430 --> 00:00:06.510\nin hetzelfde project gebruikt wordt.\n\n4\n00:00:06.510 --> 00:00:09.150\nIn plaats van elke keer dezelfde volgorde opnieuw te maken\n\n5\n00:00:09.150 --> 00:00:11.650\nis het gemakkelijker om de reeks blokken\n\n6\n00:00:11.650 --> 00:00:14.020\nin één enkel blok te groeperen.\n\n7\n00:00:14.020 --> 00:00:15.820\nDoor een Mijn blok aan te maken,\n\n8\n00:00:15.820 --> 00:00:18.370\nhoeft u de reeks maar één keer aan te maken\n\n9\n00:00:18.370 --> 00:00:20.550\nen kan je deze vervolgens opnieuw gebruiken.\n\n10\n00:00:20.550 --> 00:00:22.700\nDit kan helpen om langere projecten op te splitsen\n\n11\n00:00:22.700 --> 00:00:25.210\nzodat u er gemakkelijker mee kunt werken.\n\n12\n00:00:25.210 --> 00:00:27.590\nMijn blokken kunnen aangepast worden.\n\n13\n00:00:27.590 --> 00:00:28.863\nJe kunt het blok een naam geven,\n\n14\n00:00:30.210 --> 00:00:35.210\neen numerieke invoer, booleaanse invoer of een ander label toevoegen.\n\n15\n00:00:46.660 --> 00:00:50.040\nZodra het blok is aangepast, selecteer Okay\n\n16\n00:00:50.040 --> 00:00:54.240\nom de wijzigingen op te slaan of annuleert u om ze te verwijderen.\n\n17\n00:00:54.240 --> 00:00:58.080\nOm een invoer of label te verwijderen, selecteert u het wispictogram\n\n18\n00:00:58.080 --> 00:00:59.993\nboven het item om het te verwijderen.\n\n19\n00:01:01.110 --> 00:01:03.390\nZodra Mijn blok is aangemaakt,\n\n20\n00:01:03.390 --> 00:01:06.160\nhet gedefinieerde blok zal verschijnen.\n\n21\n00:01:06.160 --> 00:01:08.760\nVoeg blokken toe aan het definieerblok dat opnieuw zal worden gebruikt.\n\n22\n00:01:14.960 --> 00:01:17.400\nParameters voor het definieerblok kunnen worden gebruikt\n\n23\n00:01:17.400 --> 00:01:19.703\nwanneer er extra blokken aan worden toegevoegd.\n\n24\n00:01:22.420 --> 00:01:26.093\nBevestig tot slot Mijn blok aan het Wanneer gestart blok.\n\n25\n00:01:27.770 --> 00:01:30.480\nDe blokken onder het gedefinieerde blok zijn nu gegroepeerd\n\n26\n00:01:30.480 --> 00:01:32.630\nin het Mijn blok.\n\n27\n00:01:32.630 --> 00:01:35.853\nUw eigen Mijn blok is nu gemaakt en klaar om gebruikt te worden.\n\n","pl":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Czasami będziesz chciał</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nużyć sekwencji bloków wielokrotnie\n\n3\n00:00:04.430 --> 00:00:06.510\nw tym samym projekcie.\n\n4\n00:00:06.510 --> 00:00:09.150\nZamiast odtwarzania tej samej sekwencji za każdym razem,\n\n5\n00:00:09.150 --> 00:00:11.650\nłatwiej jest grupować sekwencje bloków\n\n6\n00:00:11.650 --> 00:00:14.020\nw jeden blok.\n\n7\n00:00:14.020 --> 00:00:15.820\nTworząc \"Mój blok\",\n\n8\n00:00:15.820 --> 00:00:18.370\nmusisz utworzyć sekwencję tylko raz\n\n9\n00:00:18.370 --> 00:00:20.550\na następnie można ją ponownie użyć.\n\n10\n00:00:20.550 --> 00:00:22.700\nMoże to pomóc rozbić dłuższe projekty\n\n11\n00:00:22.700 --> 00:00:25.210\ntak by ułatwić z nimi pracę.\n\n12\n00:00:25.210 --> 00:00:27.590\nMoje bloki można dostosować.\n\n13\n00:00:27.590 --> 00:00:28.863\nMożesz nazwać blok,\n\n14\n00:00:30.210 --> 00:00:35.210\ndodaj dane liczbowe, dane logiczne lub inną etykietę.\n\n15\n00:00:46.660 --> 00:00:50.040\nGdy blok zostanie dostosowany, wybierz Ok\n\n16\n00:00:50.040 --> 00:00:54.240\naby zapisać zmiany lub Anuluj aby je usunąć.\n\n17\n00:00:54.240 --> 00:00:58.080\nAby usunąć dane wejściowe lub etykietę, wybierz ikonę wyczyść\n\n18\n00:00:58.080 --> 00:00:59.993\npowyżej elementu do usunięcia.\n\n19\n00:01:01.110 --> 00:01:03.390\nPo utworzeniu mojego bloku,\n\n20\n00:01:03.390 --> 00:01:06.160\npojawi się zdefiniowany blok.\n\n21\n00:01:06.160 --> 00:01:08.760\nDodaj bloki do zdefiniowanego bloku, który zostanie ponownie użyty.\n\n22\n00:01:14.960 --> 00:01:17.400\nParametry z bloku zdefiniowanego mogą być użyte\n\n23\n00:01:17.400 --> 00:01:19.703\npo dodaniu do niego dodatkowych bloków.\n\n24\n00:01:22.420 --> 00:01:26.093\nNa koniec dodaj mój blok do bloku po uruchomieniu.\n\n25\n00:01:27.770 --> 00:01:30.480\nBloki w zdefiniowanym bloku są teraz zgrupowane\n\n26\n00:01:30.480 --> 00:01:32.630\nw moim bloku.\n\n27\n00:01:32.630 --> 00:01:35.853\nTwój blok został utworzony i jest gotowy do użycia.\n\n","ru":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Иногда, вам может понадобиться</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nиспользовать одинаковые последовательности блоков\n\n3\n00:00:04.430 --> 00:00:06.510\nв текущем проекте.\n\n4\n00:00:06.510 --> 00:00:09.150\nВместо повторного использования такой последовательности,\n\n5\n00:00:09.150 --> 00:00:11.650\nлегче всего сгруппировать эти блоки\n\n6\n00:00:11.650 --> 00:00:14.020\nв один единственный блок.\n\n7\n00:00:14.020 --> 00:00:15.820\nСоздание собственного блока\n\n8\n00:00:15.820 --> 00:00:18.370\nпозволяет создать последовательность только один раз\n\n9\n00:00:18.370 --> 00:00:20.550\nдля дальнейшего использования.\n\n10\n00:00:20.550 --> 00:00:22.700\nЭто поможет уменьшить объём кода\n\n11\n00:00:22.700 --> 00:00:25.210\nи облегчить работу с ним.\n\n12\n00:00:25.210 --> 00:00:27.590\nВаш блок может быть настроен под задачу.\n\n13\n00:00:27.590 --> 00:00:28.863\nВы можете дать имя своему блоку,\n\n14\n00:00:30.210 --> 00:00:35.210\nдобавить числовой, логический выводы или другую метку.\n\n15\n00:00:46.660 --> 00:00:50.040\nПосле настройки блока нажмите \"Ок\"\n\n16\n00:00:50.040 --> 00:00:54.240\nдля сохранения изменений или \"Отмена\" для отмены изменений.\n\n17\n00:00:54.240 --> 00:00:58.080\nДля удаления ввода или метки выберите иконку \"Очистить\",\n\n18\n00:00:58.080 --> 00:00:59.993\nнаходящую вверху окна создания блока.\n\n19\n00:01:01.110 --> 00:01:03.390\nПосле создания блока\n\n20\n00:01:03.390 --> 00:01:06.160\nпоявится его структура.\n\n21\n00:01:06.160 --> 00:01:08.760\nДобавьте повторяющуюся последовательность к блоку.\n\n22\n00:01:14.960 --> 00:01:17.400\nВходные параметры вашего блока могут быть использованы\n\n23\n00:01:17.400 --> 00:01:19.703\nпосле добавления блоков к вашему блоку.\n\n24\n00:01:22.420 --> 00:01:26.093\nПрикрепите ваш блок к блоку начала программы.\n\n25\n00:01:27.770 --> 00:01:30.480\nБлоки под \"шапкой\" вашего блока сгруппированы\n\n26\n00:01:30.480 --> 00:01:32.630\nвнутри этого блока.\n\n27\n00:01:32.630 --> 00:01:35.853\nВаш блок создан и готов к использованию.\n\n","th":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor> บางครั้งคุณอาจต้องการ </v>\n\n2\n00:00:01.890 --> 00:00:04.430\nเพื่อใช้ลำดับของบล็อกหลายๆ ครั้ง\n\n3\n00:00:04.430 --> 00:00:06.510\nในโปรเจ็คเดียวกัน\n\n4\n00:00:06.510 --> 00:00:09.150\nแทนที่จะสร้างลำดับบล็อกซ้ำๆในแต่ละครั้ง\n\n5\n00:00:09.150 --> 00:00:11.650\nยังมีวิธีอื่นที่ง่ายกว่าเพื่อที่จะรวมกลุ่มบล็อกดังกล่าว\n\n6\n00:00:11.650 --> 00:00:14.020\nให้อยู่ในบล็อกๆเดียว\n\n7\n00:00:14.020 --> 00:00:15.820\nโดยการสร้าง My block\n\n8\n00:00:15.820 --> 00:00:18.370\nคุณแค่สร้างลำดับของบล็อกแค่ครั้งเดียว\n\n9\n00:00:18.370 --> 00:00:20.550\nแล้วสามารถใช้บล็อกดังกล่าวซ้ำได้\n\n10\n00:00:20.550 --> 00:00:22.700\nโดยวิธีการนี้จะทำให้โปรเจ็คที่ยาวสั้นลง\n\n11\n00:00:22.700 --> 00:00:25.210\nและง่ายต่อการทำงาน\n\n12\n00:00:25.210 --> 00:00:27.590\nMy blocks สามารถปรับแต่งได้\n\n13\n00:00:27.590 --> 00:00:28.863\nคุณสามารถตั้งชื่อบล็อก,\n\n14\n00:00:30.210 --> 00:00:35.210\nเพิ่มการป้อน input แบบตัวเลข หรือบูลีน หรือป้ายกำกับอื่นๆ ได้\n\n15\n00:00:46.660 --> 00:00:50.040\nเมื่อบล็อกได้ถูกปรับแต่งแล้ว เลือก ตกลง\n\n16\n00:00:50.040 --> 00:00:54.240\nเพื่อบันทึกความเปลี่ยนแปลง หรือกด ยกเลิก เพื่อละทิ้งการกระทำดังกล่าว\n\n17\n00:00:54.240 --> 00:00:58.080\nในการลบอินพุตหรือป้ายกำกับให้เลือกไอคอนล้าง\n\n18\n00:00:58.080 --> 00:00:59.993\nข้างบนของไอเท็มที่ต้องการลบ\n\n19\n00:01:01.110 --> 00:01:03.390\nเมื่อ My block ได้ถูกสร้างขึ้นมาแล้ว\n\n20\n00:01:03.390 --> 00:01:06.160\ndefine block จะปรากฎขึ้นมา\n\n21\n00:01:06.160 --> 00:01:08.760\nเพิ่มบล็อกใน define block ที่จะนำกลับมาใช้\n\n22\n00:01:14.960 --> 00:01:17.400\nตัวแปรจาก define block สามารถใช้ได้\n\n23\n00:01:17.400 --> 00:01:19.703\nเมื่อมีการเพิ่มบล็อกเพิ่มเติมลงไป\n\n24\n00:01:22.420 --> 00:01:26.093\nท้ายที่สุด, แนบ My block กับ When started บล็อก\n\n25\n00:01:27.770 --> 00:01:30.480\nตอนนี้บล็อกภายใต้บล็อกที่กำหนดไว้จะถูกจัดกลุ่ม\n\n26\n00:01:30.480 --> 00:01:32.630\nให้อยู่ใน My Block\n\n27\n00:01:32.630 --> 00:01:35.853\nMy Block ของคุณถูกสร้างแล้วและพร้อมใช้งานได้ทันที\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Іноді вам потрібно</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nвикористати одну послідовність блоків кілька разів\n\n3\n00:00:04.430 --> 00:00:06.510\nу одному проєкті.\n\n4\n00:00:06.510 --> 00:00:09.150\nЗамість того, щоб копіювати одну послідовність щоразу,\n\n5\n00:00:09.150 --> 00:00:11.650\nпростіше згрупувати кілька блоків\n\n6\n00:00:11.650 --> 00:00:14.020\nв один блок.\n\n7\n00:00:14.020 --> 00:00:15.820\nДля створення свого блока\n\n8\n00:00:15.820 --> 00:00:18.370\nвам треба скласти послідовність лише раз,\n\n9\n00:00:18.370 --> 00:00:20.550\nа потім повторно її використовувати.\n\n10\n00:00:20.550 --> 00:00:22.700\nЦе допоможе розділити великий проєкт\n\n11\n00:00:22.700 --> 00:00:25.210\nі спростити роботу з ним.\n\n12\n00:00:25.210 --> 00:00:27.590\nМої блоки можна налаштувати.\n\n13\n00:00:27.590 --> 00:00:28.863\nВи можете назвати блок,\n\n14\n00:00:30.210 --> 00:00:35.210\nдодати числовий вхід, логічний вхід або інші позначки.\n\n15\n00:00:46.660 --> 00:00:50.040\nЩойно блок буде налаштований, натисніть ОК\n\n16\n00:00:50.040 --> 00:00:54.240\nдля збереження змін, або скасуйте для видалення.\n\n17\n00:00:54.240 --> 00:00:58.080\nДля видалення входів або позначок виберіть іконку очистити\n\n18\n00:00:58.080 --> 00:00:59.993\nнад елементом для видалення.\n\n19\n00:01:01.110 --> 00:01:03.390\nКоли мій блок буде створено,\n\n20\n00:01:03.390 --> 00:01:06.160\nз'явиться блок \"визначити\".\n\n21\n00:01:06.160 --> 00:01:08.760\nДодайте блоки до блока \"визначити\", щоб використовувати їх повторно.\n\n22\n00:01:14.960 --> 00:01:17.400\nПараметри для блока \"визначити\" можна використовувати\n\n23\n00:01:17.400 --> 00:01:19.703\nпісля розміщення додаткових блоків.\n\n24\n00:01:22.420 --> 00:01:26.093\nНарешті, прикріпіть свій блок до блока \"коли почнемо\".\n\n25\n00:01:27.770 --> 00:01:30.480\nБлоки під \"визначити\" тепер згруповані\n\n26\n00:01:30.480 --> 00:01:32.630\nу мій блок.\n\n27\n00:01:32.630 --> 00:01:35.853\nВаш власний блок створений і готовий до використання.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>Đôi khi bạn sẽ muốn</v>\n\n2\n00:00:01.890 --> 00:00:04.430\nđể sử dụng một chuỗi các khối nhiều lần\n\n3\n00:00:04.430 --> 00:00:06.510\ntrong cùng một dự án.\n\n4\n00:00:06.510 --> 00:00:09.150\nThay vì tạo lại cùng một trình tự mỗi lần,\n\n5\n00:00:09.150 --> 00:00:11.650\ndễ dàng hơn để nhóm chuỗi các khối\n\n6\n00:00:11.650 --> 00:00:14.020\nthành một khối duy nhất.\n\n7\n00:00:14.020 --> 00:00:15.820\nBằng cách tạo Khối của tôi,\n\n8\n00:00:15.820 --> 00:00:18.370\nbạn chỉ cần tạo trình tự một lần\n\n9\n00:00:18.370 --> 00:00:20.550\nvà sau đó bạn có thể sử dụng lại nó.\n\n10\n00:00:20.550 --> 00:00:22.700\nĐiều này có thể giúp chia nhỏ các dự án dài hơn\n\n11\n00:00:22.700 --> 00:00:25.210\nđể giúp họ làm việc dễ dàng hơn.\n\n12\n00:00:25.210 --> 00:00:27.590\nKhối của tôi có thể được tùy chỉnh.\n\n13\n00:00:27.590 --> 00:00:28.863\nBạn có thể đặt tên cho khối,\n\n14\n00:00:30.210 --> 00:00:35.210\nthêm một đầu vào số, một đầu vào boolean hoặc một nhãn khác.\n\n15\n00:00:46.660 --> 00:00:50.040\nSau khi khối được tùy chỉnh, hãy chọn Đồng ý\n\n16\n00:00:50.040 --> 00:00:54.240\nđể lưu các thay đổi hoặc hủy để xóa chúng.\n\n17\n00:00:54.240 --> 00:00:58.080\nĐể xóa đầu vào hoặc nhãn, hãy chọn biểu tượng xóa\n\n18\n00:00:58.080 --> 00:00:59.993\nphía trên mục để xóa nó.\n\n19\n00:01:01.110 --> 00:01:03.390\nKhi Khối của tôi đã được tạo,\n\n20\n00:01:03.390 --> 00:01:06.160\nkhối xác định sẽ xuất hiện.\n\n21\n00:01:06.160 --> 00:01:08.760\nThêm khối vào khối đã xác định sẽ được sử dụng lại.\n\n22\n00:01:14.960 --> 00:01:17.400\nCác thông số cho khối đã xác định có thể được sử dụng\n\n23\n00:01:17.400 --> 00:01:19.703\nkhi các khối bổ sung được thêm vào nó.\n\n24\n00:01:22.420 --> 00:01:26.093\nCuối cùng, đính kèm Khối của tôi vào Khối Khi bắt đầu.\n\n25\n00:01:27.770 --> 00:01:30.480\nCác khối trong khối đã xác định hiện được nhóm lại\n\n26\n00:01:30.480 --> 00:01:32.630\nvào Khối của tôi.\n\n27\n00:01:32.630 --> 00:01:35.853\nKhối của tôi của bạn hiện đã được tạo và sẵn sàng sử dụng.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\ncrwdns96272:0crwdne96272:0\n\n2\n00:00:01.890 --> 00:00:04.430\ncrwdns96274:0crwdne96274:0\n\n3\n00:00:04.430 --> 00:00:06.510\ncrwdns96276:0crwdne96276:0\n\n4\n00:00:06.510 --> 00:00:09.150\ncrwdns96278:0crwdne96278:0\n\n5\n00:00:09.150 --> 00:00:11.650\ncrwdns96280:0crwdne96280:0\n\n6\n00:00:11.650 --> 00:00:14.020\ncrwdns96282:0crwdne96282:0\n\n7\n00:00:14.020 --> 00:00:15.820\ncrwdns96284:0crwdne96284:0\n\n8\n00:00:15.820 --> 00:00:18.370\ncrwdns96286:0crwdne96286:0\n\n9\n00:00:18.370 --> 00:00:20.550\ncrwdns96288:0crwdne96288:0\n\n10\n00:00:20.550 --> 00:00:22.700\ncrwdns96290:0crwdne96290:0\n\n11\n00:00:22.700 --> 00:00:25.210\ncrwdns96292:0crwdne96292:0\n\n12\n00:00:25.210 --> 00:00:27.590\ncrwdns96294:0crwdne96294:0\n\n13\n00:00:27.590 --> 00:00:28.863\ncrwdns96296:0crwdne96296:0\n\n14\n00:00:30.210 --> 00:00:35.210\ncrwdns96298:0crwdne96298:0\n\n15\n00:00:46.660 --> 00:00:50.040\ncrwdns96300:0crwdne96300:0\n\n16\n00:00:50.040 --> 00:00:54.240\ncrwdns96302:0crwdne96302:0\n\n17\n00:00:54.240 --> 00:00:58.080\ncrwdns96304:0crwdne96304:0\n\n18\n00:00:58.080 --> 00:00:59.993\ncrwdns96306:0crwdne96306:0\n\n19\n00:01:01.110 --> 00:01:03.390\ncrwdns96308:0crwdne96308:0\n\n20\n00:01:03.390 --> 00:01:06.160\ncrwdns96310:0crwdne96310:0\n\n21\n00:01:06.160 --> 00:01:08.760\ncrwdns96312:0crwdne96312:0\n\n22\n00:01:14.960 --> 00:01:17.400\ncrwdns96314:0crwdne96314:0\n\n23\n00:01:17.400 --> 00:01:19.703\ncrwdns96316:0crwdne96316:0\n\n24\n00:01:22.420 --> 00:01:26.093\ncrwdns96318:0crwdne96318:0\n\n25\n00:01:27.770 --> 00:01:30.480\ncrwdns96320:0crwdne96320:0\n\n26\n00:01:30.480 --> 00:01:32.630\ncrwdns96322:0crwdne96322:0\n\n27\n00:01:32.630 --> 00:01:35.853\ncrwdns96324:0crwdne96324:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.600 --> 00:00:01.890\n<v Instructor>有时候您将需要</v>\n\n2\n00:00:01.890 --> 00:00:04.430\n在同一个程序中\n\n3\n00:00:04.430 --> 00:00:06.510\n多次使用一系列的指令块。\n\n4\n00:00:06.510 --> 00:00:09.150\n与其每次重复创建相同的序列，\n\n5\n00:00:09.150 --> 00:00:11.650\n将一系列指令块组合到\n\n6\n00:00:11.650 --> 00:00:14.020\n一个单独的指令块更容易。\n\n7\n00:00:14.020 --> 00:00:15.820\n通过创建一个“我的指令块”，\n\n8\n00:00:15.820 --> 00:00:18.370\n您只需要创建一次序列，\n\n9\n00:00:18.370 --> 00:00:20.550\n然后您可以重新使用它。\n\n10\n00:00:20.550 --> 00:00:22.700\n这可以帮助你将冗长的程序拆分，\n\n11\n00:00:22.700 --> 00:00:25.210\n从而让它们更容易处理。\n\n12\n00:00:25.210 --> 00:00:27.590\n“我的指令块”可以自定义。\n\n13\n00:00:27.590 --> 00:00:28.863\n您可以给指令块命名。\n\n14\n00:00:30.210 --> 00:00:35.210\n添加一个数字输入，一个布尔输入或另一个标签。\n\n15\n00:00:46.660 --> 00:00:50.040\n一旦指令块自定义后，选择“确认”\n\n16\n00:00:50.040 --> 00:00:54.240\n来保存更改或者取消来移除它们。\n\n17\n00:00:54.240 --> 00:00:58.080\n欲删除输入或标签，选择项目上方的“清除”图标\n\n18\n00:00:58.080 --> 00:00:59.993\n来删除它。\n\n19\n00:01:01.110 --> 00:01:03.390\n当“我的指令块”创建后，\n\n20\n00:01:03.390 --> 00:01:06.160\n“定义指令块”将显示。\n\n21\n00:01:06.160 --> 00:01:08.760\n添加将被重新使用的指令块至定义指令块中。\n\n22\n00:01:14.960 --> 00:01:17.400\n一旦额外的指令块被添加至其中，\n\n23\n00:01:17.400 --> 00:01:19.703\n定义指令块的参数就可以被使用。\n\n24\n00:01:22.420 --> 00:01:26.093\n最后，将“我的指令块”连接到“当开始”指令块下面。\n\n25\n00:01:27.770 --> 00:01:30.480\n定义指令块下面的指令块现在被组合\n\n26\n00:01:30.480 --> 00:01:32.630\n到“我的指令块”中。\n\n27\n00:01:32.630 --> 00:01:35.853\n你的“我的指令块”现在已经创建好并待用。\n\n"}},{"thumb":"Tutorial_variableLists_v2.jpg","mov":"V5_Blocks_StoringData_V2","description":"Storing Data","filter":"","placeholder":false,"vimeo":"475900878","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 has four different ways</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nto store and use data inside of your project.\n\n3\n00:00:06.660 --> 00:00:10.190\nBooleans to store a true or false value,\n\n4\n00:00:10.190 --> 00:00:14.470\nnumeric variables to store a single numeric value,\n\n5\n00:00:14.470 --> 00:00:19.010\nlists to store multiple numeric values that are related,\n\n6\n00:00:19.010 --> 00:00:21.470\nand two-dimensional lists,\n\n7\n00:00:21.470 --> 00:00:23.790\nwhich stores multiple related lists\n\n8\n00:00:23.790 --> 00:00:26.823\nor large groups of related numeric values.\n\n9\n00:00:27.770 --> 00:00:29.620\nBoolean variables are useful\n\n10\n00:00:29.620 --> 00:00:32.760\nfor storing a single true or false value,\n\n11\n00:00:32.760 --> 00:00:35.380\nsuch as the value from a bumper sensor\n\n12\n00:00:35.380 --> 00:00:37.023\nor a controller button.\n\n13\n00:00:38.930 --> 00:00:40.920\nNumeric variables are useful\n\n14\n00:00:40.920 --> 00:00:43.960\nfor storing and retrieving numeric data.\n\n15\n00:00:43.960 --> 00:00:46.450\nNumeric data can come from reporter blocks,\n\n16\n00:00:46.450 --> 00:00:50.860\nsuch as the vision sensor or a controller axis.\n\n17\n00:00:50.860 --> 00:00:54.370\nVariables are great to store information in your project,\n\n18\n00:00:54.370 --> 00:00:55.890\nsuch as the number of times\n\n19\n00:00:55.890 --> 00:00:57.840\na bumper sensor has been pressed,\n\n20\n00:00:57.840 --> 00:01:00.540\nor the distance a motor has traveled.\n\n21\n00:01:00.540 --> 00:01:02.650\nYou can then use numeric variables\n\n22\n00:01:02.650 --> 00:01:05.223\nto make decisions based on stored data.\n\n23\n00:01:06.210 --> 00:01:08.760\nIf your data is still from one sensor,\n\n24\n00:01:08.760 --> 00:01:12.283\nbut at different times, that is when you would use the list.\n\n25\n00:01:14.040 --> 00:01:15.050\nIn this example,\n\n26\n00:01:15.050 --> 00:01:18.110\nthe list will store the value of the motor's position\n\n27\n00:01:18.110 --> 00:01:20.050\nonce every second.\n\n28\n00:01:20.050 --> 00:01:22.090\nThis information could be used later\n\n29\n00:01:22.090 --> 00:01:23.410\nto create a calculation\n\n30\n00:01:23.410 --> 00:01:25.573\nto determine the motor's average speed.\n\n31\n00:01:27.060 --> 00:01:28.320\nIf you want sensor data\n\n32\n00:01:28.320 --> 00:01:30.970\nfrom multiple sensors at all different times,\n\n33\n00:01:30.970 --> 00:01:33.040\nyou can use a 2D list.\n\n34\n00:01:33.040 --> 00:01:34.460\nWith this 2D list,\n\n35\n00:01:34.460 --> 00:01:37.903\nyou can store the value of the position of two motors.\n\n36\n00:01:42.340 --> 00:01:45.170\nUsing a 2D list instead of multiple lists\n\n37\n00:01:45.170 --> 00:01:46.950\nmakes it easier to use the data\n\n38\n00:01:46.950 --> 00:01:49.960\nfor further calculations in your project.\n\n39\n00:01:49.960 --> 00:01:52.760\nThe ability to store and use different data types\n\n40\n00:01:52.760 --> 00:01:54.570\nprovides you with the opportunity\n\n41\n00:01:54.570 --> 00:01:57.463\nto create more interesting and advanced projects.\n\n","ar":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>لمقاطع VEXcode IQ أربع طرق مختلفة</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nلتخزين واستخدام البيانات داخل مشروعك.\n\n3\n00:00:06.660 --> 00:00:10.190\nمتغير منطقي لتخزين قيمة صحيحة أو خاطئة,\n\n4\n00:00:10.190 --> 00:00:14.470\nالمتغيرات الرقمية لتخزين قيمة رقمية واحدة,\n\n5\n00:00:14.470 --> 00:00:19.010\nقوائم لتخزين القيم الرقمية المتعددة ذات الصلة,\n\n6\n00:00:19.010 --> 00:00:21.470\nقائمتين ثنائيتا الأبعاد\n\n7\n00:00:21.470 --> 00:00:23.790\nالتي تخزن قوائم متعددة ذات صلة\n\n8\n00:00:23.790 --> 00:00:26.823\nأو مجموعات كبيرة من القيم الرقمية ذات الصلة.\n\n9\n00:00:27.770 --> 00:00:29.620\nالمتغيرات الرقمية مفيدة للتخزين\n\n10\n00:00:29.620 --> 00:00:32.760\nلتخزين قيمة حقيقية أو كاذبة واحدة،\n\n11\n00:00:32.760 --> 00:00:35.380\nمثل عدد المرات التي يقوم فيها مستشعر الاصطدام\n\n12\n00:00:35.380 --> 00:00:37.023\nأو زر وحدة التحكم.\n\n13\n00:00:38.930 --> 00:00:40.920\nالمتغيرات الرقمية مفيدة للتخزين\n\n14\n00:00:40.920 --> 00:00:43.960\nواستعادة البيانات الرقمية.\n\n15\n00:00:43.960 --> 00:00:46.450\nالبيانات الرقمية يمكن أن تأتي من مقاطع المراسلين،\n\n16\n00:00:46.450 --> 00:00:50.860\nمثل مستشعر الرؤية أو محور وحدة التحكم.\n\n17\n00:00:50.860 --> 00:00:54.370\nالمتغيرات جيدة لتخزين المعلومات في مشروعك،\n\n18\n00:00:54.370 --> 00:00:55.890\nكعدد المرات\n\n19\n00:00:55.890 --> 00:00:57.840\nتم الضغط على مستشعر الاصطدام\n\n20\n00:00:57.840 --> 00:01:00.540\nأو المسافة التي قطعها المحرك.\n\n21\n00:01:00.540 --> 00:01:02.650\nيمكنك بعد ذلك استخدام المتغيرات الرقمية\n\n22\n00:01:02.650 --> 00:01:05.223\nلاتخاذ قرارات استناداً على البيانات المخزنة.\n\n23\n00:01:06.210 --> 00:01:08.760\nإذا كانت بياناتك لا تزال من جهاز استشعار واحد،\n\n24\n00:01:08.760 --> 00:01:12.283\nولكن في أوقات مختلفة، هذا هو الوقت الذي تستخدم فيه القائمة.\n\n25\n00:01:14.040 --> 00:01:15.050\nفي هذا المثال ،\n\n26\n00:01:15.050 --> 00:01:18.110\nسوف تخزن القائمة قيمة موضع المحرك\n\n27\n00:01:18.110 --> 00:01:20.050\nمرة كل ثانية.\n\n28\n00:01:20.050 --> 00:01:22.090\nويمكن استخدام هذه المعلومات في وقت لاحق\n\n29\n00:01:22.090 --> 00:01:23.410\nلإنشاء عملية حساب\n\n30\n00:01:23.410 --> 00:01:25.573\nلتحديد معدل سرعة المحرك.\n\n31\n00:01:27.060 --> 00:01:28.320\nإذا كنت تريد بيانات استشعار\n\n32\n00:01:28.320 --> 00:01:30.970\nمن مستشعرات متعددة في جميع الأوقات المختلفة،\n\n33\n00:01:30.970 --> 00:01:33.040\nيمكنك استخدام قائمة ثنائية الأبعاد.\n\n34\n00:01:33.040 --> 00:01:34.460\nمع هذه القائمة ثنائية الأبعاد،\n\n35\n00:01:34.460 --> 00:01:37.903\nيمكنك تخزين قيمة موقع المحركين.\n\n36\n00:01:42.340 --> 00:01:45.170\nباستخدام قائمة ثنائية الأبعاد بدلاً من قوائم متعددة\n\n37\n00:01:45.170 --> 00:01:46.950\nيجعل من الأسهل استخدام البيانات\n\n38\n00:01:46.950 --> 00:01:49.960\nلمزيد من الحسابات في برنامجك.\n\n39\n00:01:49.960 --> 00:01:52.760\nتوفر القدرة على تخزين واستخدام أنواع مختلفة من البيانات\n\n40\n00:01:52.760 --> 00:01:54.570\nيوفر لك الفرصة\n\n41\n00:01:54.570 --> 00:01:57.463\nلإنشاء المزيد من البرامج المثيرة للاهتمام والمتقدمة.\n\n","cs":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 má čtyři různé způsoby</v>\n\n2\n00:00:02.980 --> 00:00:05.593\npro ukládání a používání dat ve tvém projektu.\n\n3\n00:00:06.660 --> 00:00:10.190\nLogické proměnné pro uložení hodnoty pravda nebo nepravda,\n\n4\n00:00:10.190 --> 00:00:14.470\nčíselné proměnné pro uložení jedné číselné hodnoty,\n\n5\n00:00:14.470 --> 00:00:19.010\nseznamy pro uložení více souvisejících číselných hodnot,\n\n6\n00:00:19.010 --> 00:00:21.470\na dvourozměrné seznamy,\n\n7\n00:00:21.470 --> 00:00:23.790\nkteré ukládají více souvisejících seznamů,\n\n8\n00:00:23.790 --> 00:00:26.823\nnebo velké skupiny souvisejících číselných hodnot.\n\n9\n00:00:27.770 --> 00:00:29.620\nLogické proměnné jsou užitečné\n\n10\n00:00:29.620 --> 00:00:32.760\npro ukládání jedné hodnoty pravda nebo nepravda,\n\n11\n00:00:32.760 --> 00:00:35.380\njako například hodnoty z nárazníkového senzoru,\n\n12\n00:00:35.380 --> 00:00:37.023\nnebo tlačítka ovladače.\n\n13\n00:00:38.930 --> 00:00:40.920\nČíselné proměnné jsou užitečné\n\n14\n00:00:40.920 --> 00:00:43.960\npro ukládání a zpětné získávání číselných údajů.\n\n15\n00:00:43.960 --> 00:00:46.450\nČíselná data mohou pocházet z ohlašovacích bloků,\n\n16\n00:00:46.450 --> 00:00:50.860\njako je kamera nebo osy ovladače.\n\n17\n00:00:50.860 --> 00:00:54.370\nProměnné jsou skvělé pro ukládání informací ve tvém projektu,\n\n18\n00:00:54.370 --> 00:00:55.890\njako je třeba kolikrát\n\n19\n00:00:55.890 --> 00:00:57.840\nbyl nárazníkový senzor stisknut,\n\n20\n00:00:57.840 --> 00:01:00.540\nnebo vzdálenost, kterou motor urazil.\n\n21\n00:01:00.540 --> 00:01:02.650\nPotom můžeš použít číselné proměnné\n\n22\n00:01:02.650 --> 00:01:05.223\nk rozhodování na základě uložených dat.\n\n23\n00:01:06.210 --> 00:01:08.760\nJestliže jsou tvoje data pořád z jednoho senzoru,\n\n24\n00:01:08.760 --> 00:01:12.283\nale z různých časů, je to případ pro použití seznamu.\n\n25\n00:01:14.040 --> 00:01:15.050\nV tomto příkladu\n\n26\n00:01:15.050 --> 00:01:18.110\nseznam uloží hodnotu polohy motoru\n\n27\n00:01:18.110 --> 00:01:20.050\njednou za vteřinu.\n\n28\n00:01:20.050 --> 00:01:22.090\nTyto informace by mohly být použity později\n\n29\n00:01:22.090 --> 00:01:23.410\npro vytvoření výpočtu\n\n30\n00:01:23.410 --> 00:01:25.573\nk určení průměrné rychlosti motoru.\n\n31\n00:01:27.060 --> 00:01:28.320\nJestliže chceš data senzorů\n\n32\n00:01:28.320 --> 00:01:30.970\nz více senzorů, všechny v různých časech,\n\n33\n00:01:30.970 --> 00:01:33.040\nmůžeš použít 2D seznam.\n\n34\n00:01:33.040 --> 00:01:34.460\nS tímto 2D seznamem\n\n35\n00:01:34.460 --> 00:01:37.903\nmůžeš ukládat hodnoty polohy dvou motorů.\n\n36\n00:01:42.340 --> 00:01:45.170\nPoužívání 2D seznamu místo několika seznamů\n\n37\n00:01:45.170 --> 00:01:46.950\nusnadňuje použití dat\n\n38\n00:01:46.950 --> 00:01:49.960\npro další výpočty ve tvém projektu.\n\n39\n00:01:49.960 --> 00:01:52.760\nSchopnost ukládat a používat různé datové typy\n\n40\n00:01:52.760 --> 00:01:54.570\nti poskytuje příležitost\n\n41\n00:01:54.570 --> 00:01:57.463\nvytvořit zajímavější a pokročilejší projekty.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 tiene cuatro formas diferentes</v>\n\n2\n00:00:02.980 --> 00:00:05.593\npara almacenar y utilizar datos dentro de su proyecto.\n\n3\n00:00:06.660 --> 00:00:10.190\nBooleanos para almacenar un valor verdad o falso,\n\n4\n00:00:10.190 --> 00:00:14.470\nvariables numéricas para almacenar un único valor numérico\n\n5\n00:00:14.470 --> 00:00:19.010\nlistas para almacenar múltiples valores numéricos relacionados,\n\n6\n00:00:19.010 --> 00:00:21.470\ny listas de dos dimensiones,\n\n7\n00:00:21.470 --> 00:00:23.790\nque almacena varias listas relacionadas\n\n8\n00:00:23.790 --> 00:00:26.823\no grupos grandes de valores numéricos relacionados.\n\n9\n00:00:27.770 --> 00:00:29.620\nLas variables booleanas son útiles\n\n10\n00:00:29.620 --> 00:00:32.760\npara almacenar un solo valor verdad o falso,\n\n11\n00:00:32.760 --> 00:00:35.380\ntal como el valor de un sensor de parachoques\n\n12\n00:00:35.380 --> 00:00:37.023\no un botón del controlador.\n\n13\n00:00:38.930 --> 00:00:40.920\nVariables numéricas son útiles\n\n14\n00:00:40.920 --> 00:00:43.960\npara almacenar y recuperar datos numéricos.\n\n15\n00:00:43.960 --> 00:00:46.450\nLos datos numéricos pueden provenir de bloques reporteros,\n\n16\n00:00:46.450 --> 00:00:50.860\ncomo el sensor de visión o el eje de un controlador.\n\n17\n00:00:50.860 --> 00:00:54.370\nVariables son excelentes para almacenar información en su proyecto,\n\n18\n00:00:54.370 --> 00:00:55.890\ntal como el número de veces\n\n19\n00:00:55.890 --> 00:00:57.840\nque se ha presionado un sensor de parachoques,\n\n20\n00:00:57.840 --> 00:01:00.540\no la distancia que un motor ha recorrido.\n\n21\n00:01:00.540 --> 00:01:02.650\nA continuación, puede utilizar Variables Numéricas\n\n22\n00:01:02.650 --> 00:01:05.223\npara tomar decisiones basadas en datos almacenados.\n\n23\n00:01:06.210 --> 00:01:08.760\nSi sus datos todavía son de un sensor,\n\n24\n00:01:08.760 --> 00:01:12.283\npero en momentos diferentes, es cuando usaría la lista.\n\n25\n00:01:14.040 --> 00:01:15.050\nEn este ejemplo,\n\n26\n00:01:15.050 --> 00:01:18.110\nla lista almacenará el valor de la posición del motor\n\n27\n00:01:18.110 --> 00:01:20.050\nuna vez cada segundo.\n\n28\n00:01:20.050 --> 00:01:22.090\nEsta información podría ser usada más tarde\n\n29\n00:01:22.090 --> 00:01:23.410\npara crear un cálculo\n\n30\n00:01:23.410 --> 00:01:25.573\npara determinar la velocidad promedio del motor.\n\n31\n00:01:27.060 --> 00:01:28.320\nSi desea datos del sensor\n\n32\n00:01:28.320 --> 00:01:30.970\nde múltiples sensores todos en diferentes momentos,\n\n33\n00:01:30.970 --> 00:01:33.040\npuede usar una lista 2D.\n\n34\n00:01:33.040 --> 00:01:34.460\nCon esta lista 2D\n\n35\n00:01:34.460 --> 00:01:37.903\npuede almacenar el valor de la posición de dos motores.\n\n36\n00:01:42.340 --> 00:01:45.170\nUsando una lista 2D en lugar de varias listas\n\n37\n00:01:45.170 --> 00:01:46.950\nhace más fácil usar los datos luego\n\n38\n00:01:46.950 --> 00:01:49.960\nen más cálculos de su proyecto.\n\n39\n00:01:49.960 --> 00:01:52.760\nLa capacidad de almacenar y utilizar diferentes tipos de datos\n\n40\n00:01:52.760 --> 00:01:54.570\nle ofrece la oportunidad de crear\n\n41\n00:01:54.570 --> 00:01:57.463\nproyectos más interesantes y avanzados.\n\n","es":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 tiene cuatro formas diferentes</v>\n\n2\n00:00:02.980 --> 00:00:05.593\npara almacenar y utilizar datos dentro de su proyecto.\n\n3\n00:00:06.660 --> 00:00:10.190\nBooleanos para almacenar un valor verdad o falso,\n\n4\n00:00:10.190 --> 00:00:14.470\nvariables numéricas para almacenar un único valor numérico\n\n5\n00:00:14.470 --> 00:00:19.010\nlistas para almacenar múltiples valores numéricos relacionados,\n\n6\n00:00:19.010 --> 00:00:21.470\ny listas de dos dimensiones,\n\n7\n00:00:21.470 --> 00:00:23.790\nque almacena varias listas relacionadas\n\n8\n00:00:23.790 --> 00:00:26.823\no grupos grandes de valores numéricos relacionados.\n\n9\n00:00:27.770 --> 00:00:29.620\nLas variables booleanas son útiles\n\n10\n00:00:29.620 --> 00:00:32.760\npara almacenar un solo valor verdad o falso,\n\n11\n00:00:32.760 --> 00:00:35.380\ntal como el valor de un sensor de parachoques\n\n12\n00:00:35.380 --> 00:00:37.023\no un botón del controlador.\n\n13\n00:00:38.930 --> 00:00:40.920\nVariables numéricas son útiles\n\n14\n00:00:40.920 --> 00:00:43.960\npara almacenar y recuperar datos numéricos.\n\n15\n00:00:43.960 --> 00:00:46.450\nLos datos numéricos pueden provenir de bloques reporteros,\n\n16\n00:00:46.450 --> 00:00:50.860\ncomo el sensor de visión o el eje de un controlador.\n\n17\n00:00:50.860 --> 00:00:54.370\nVariables son excelentes para almacenar información en su proyecto,\n\n18\n00:00:54.370 --> 00:00:55.890\ntal como el número de veces\n\n19\n00:00:55.890 --> 00:00:57.840\nque se ha presionado un sensor de parachoques,\n\n20\n00:00:57.840 --> 00:01:00.540\no la distancia que un motor ha recorrido.\n\n21\n00:01:00.540 --> 00:01:02.650\nA continuación, puede utilizar Variables Numéricas\n\n22\n00:01:02.650 --> 00:01:05.223\npara tomar decisiones basadas en datos almacenados.\n\n23\n00:01:06.210 --> 00:01:08.760\nSi sus datos todavía son de un sensor,\n\n24\n00:01:08.760 --> 00:01:12.283\npero en momentos diferentes, es cuando usaría la lista.\n\n25\n00:01:14.040 --> 00:01:15.050\nEn este ejemplo,\n\n26\n00:01:15.050 --> 00:01:18.110\nla lista almacenará el valor de la posición del motor\n\n27\n00:01:18.110 --> 00:01:20.050\nuna vez cada segundo.\n\n28\n00:01:20.050 --> 00:01:22.090\nEsta información podría ser usada más tarde\n\n29\n00:01:22.090 --> 00:01:23.410\npara crear un cálculo\n\n30\n00:01:23.410 --> 00:01:25.573\npara determinar la velocidad promedio del motor.\n\n31\n00:01:27.060 --> 00:01:28.320\nSi desea datos del sensor\n\n32\n00:01:28.320 --> 00:01:30.970\nde múltiples sensores todos en diferentes momentos,\n\n33\n00:01:30.970 --> 00:01:33.040\npuede usar una lista 2D.\n\n34\n00:01:33.040 --> 00:01:34.460\nCon esta lista 2D\n\n35\n00:01:34.460 --> 00:01:37.903\npuede almacenar el valor de la posición de dos motores.\n\n36\n00:01:42.340 --> 00:01:45.170\nUsando una lista 2D en lugar de varias listas\n\n37\n00:01:45.170 --> 00:01:46.950\nhace más fácil usar los datos luego\n\n38\n00:01:46.950 --> 00:01:49.960\nen más cálculos de su proyecto.\n\n39\n00:01:49.960 --> 00:01:52.760\nLa capacidad de almacenar y utilizar diferentes tipos de datos\n\n40\n00:01:52.760 --> 00:01:54.570\nle ofrece la oportunidad de crear\n\n41\n00:01:54.570 --> 00:01:57.463\nproyectos más interesantes y avanzados.\n\n","fi":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 ohjelmassa on neljä eri tapaa</v>\n\n2\n00:00:02.980 --> 00:00:05.593\ntallentaa ja käyttää tietoja ohjelmassasi.\n\n3\n00:00:06.660 --> 00:00:10.190\nBoolean -muuttuja arvoilla Tosi ja Epätosi,\n\n4\n00:00:10.190 --> 00:00:14.470\nnumeerinen muuttuja säilömään numeerisen arvon,\n\n5\n00:00:14.470 --> 00:00:19.010\ntaulukoita säilömään monikertaisia arvoja luettelo - ja\n\n6\n00:00:19.010 --> 00:00:21.470\n2d taulukossa,\n\n7\n00:00:21.470 --> 00:00:23.790\njoissa saa talteen useamman arvon\n\n8\n00:00:23.790 --> 00:00:26.823\ntai taulukossa ryhmän numeroarvoja.\n\n9\n00:00:27.770 --> 00:00:29.620\nBoolean -tyyppinen muuttuja on käyttökelpoinen\n\n10\n00:00:29.620 --> 00:00:32.760\nsäilömään Tosi ja Epätosi -arvoja\n\n11\n00:00:32.760 --> 00:00:35.380\nkuten Painokytkimen painalluksia\n\n12\n00:00:35.380 --> 00:00:37.023\ntai Ohjaimen nappien painalluksia.\n\n13\n00:00:38.930 --> 00:00:40.920\nNumeeriset muuttujat ovay käyttökelpoisia\n\n14\n00:00:40.920 --> 00:00:43.960\nsaada talteen numeerista tietoa.\n\n15\n00:00:43.960 --> 00:00:46.450\nNumeerisia arvoja saa\n\n16\n00:00:46.450 --> 00:00:50.860\nVision -kameran antamista muuttuja-arvoista tai ohjaimen tatin kääntämisestä.\n\n17\n00:00:50.860 --> 00:00:54.370\nMuuttujiin tallennetut sensoriarvot auttavat päätöksiin ohjelman suorituksen aikana\n\n18\n00:00:54.370 --> 00:00:55.890\nkuten montako kertaa\n\n19\n00:00:55.890 --> 00:00:57.840\nPainokytkintä on painettu\n\n20\n00:00:57.840 --> 00:01:00.540\ntai minkä astemäärän moottori on pyörinyt.\n\n21\n00:01:00.540 --> 00:01:02.650\nVoit käyttää numeerisia muuttujia,\n\n22\n00:01:02.650 --> 00:01:05.223\njotta voit tehdä oikeita päätelmiä ohjelman kuluessa.\n\n23\n00:01:06.210 --> 00:01:08.760\nJos tarvitset useamman anturin arvon\n\n24\n00:01:08.760 --> 00:01:12.283\neri aikoina , niin voit käyttää luetteloa.\n\n25\n00:01:14.040 --> 00:01:15.050\nTässä esimerkissä\n\n26\n00:01:15.050 --> 00:01:18.110\nmoottorin kiertoasento tallennetaan luetteloon\n\n27\n00:01:18.110 --> 00:01:20.050\nsekunnin välein.\n\n28\n00:01:20.050 --> 00:01:22.090\nTätä luetteloa voi käyttää\n\n29\n00:01:22.090 --> 00:01:23.410\njos haluaa laskea\n\n30\n00:01:23.410 --> 00:01:25.573\nmoottorin keskinopeuden.\n\n31\n00:01:27.060 --> 00:01:28.320\nJos haluat käyttää\n\n32\n00:01:28.320 --> 00:01:30.970\nuseampaa anturidataa samanaikaisesti ajan kuluessa\n\n33\n00:01:30.970 --> 00:01:33.040\nvoit käyttää 2d taulukkoa.\n\n34\n00:01:33.040 --> 00:01:34.460\n2d tauluon avulla\n\n35\n00:01:34.460 --> 00:01:37.903\nvoit tallentaa kahden eri moottorin asennot ajan kuluessa.\n\n36\n00:01:42.340 --> 00:01:45.170\nKaksiulotteisen taulukon avulla\n\n37\n00:01:45.170 --> 00:01:46.950\non helppoa käsitellä tietoa\n\n38\n00:01:46.950 --> 00:01:49.960\nohjelmasi laskennoissa.\n\n39\n00:01:49.960 --> 00:01:52.760\nKyky tallentaa ja käyttää eri muotoista tietoa\n\n40\n00:01:52.760 --> 00:01:54.570\nantaa mahdollisuuden\n\n41\n00:01:54.570 --> 00:01:57.463\ntehdä mielenkiintoisia ja kehittyneitä ohjelmia.\n\n","fr":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 offre quatre manières différentes</v>\n\n2\n00:00:02.980 --> 00:00:05.593\npour stocker et utiliser des données à l'intérieur de votre projet.\n\n3\n00:00:06.660 --> 00:00:10.190\nLes booléens, pour stocker la valeur \"vrai\" ou \"faux\",\n\n4\n00:00:10.190 --> 00:00:14.470\nles variables numériques, pour stocker une seule valeur numérique,\n\n5\n00:00:14.470 --> 00:00:19.010\nles listes, pour stocker plusieurs valeurs numériques qui sont liées,\n\n6\n00:00:19.010 --> 00:00:21.470\net listes en deux dimensions,\n\n7\n00:00:21.470 --> 00:00:23.790\nqui stockent plusieurs listes liées\n\n8\n00:00:23.790 --> 00:00:26.823\nou de grands groupes de valeurs numériques liées.\n\n9\n00:00:27.770 --> 00:00:29.620\nLes variables booléennes sont utiles\n\n10\n00:00:29.620 --> 00:00:32.760\npour stocker une seule valeur \"Vrai\" ou \"Faux\",\n\n11\n00:00:32.760 --> 00:00:35.380\ncomme la valeur d'un capteur bumper\n\n12\n00:00:35.380 --> 00:00:37.023\nou d'un bouton de manette.\n\n13\n00:00:38.930 --> 00:00:40.920\nLes variables numériques sont utiles\n\n14\n00:00:40.920 --> 00:00:43.960\npour stocker et récupérer des données numériques.\n\n15\n00:00:43.960 --> 00:00:46.450\nLes données numériques peuvent provenir de blocs qui renvoient des données,\n\n16\n00:00:46.450 --> 00:00:50.860\ncomme le capteur de vision ou l'axe de la manette.\n\n17\n00:00:50.860 --> 00:00:54.370\nLes variables sont géniales pour stocker des informations dans votre projet,\n\n18\n00:00:54.370 --> 00:00:55.890\ncomme le nombre de fois\n\n19\n00:00:55.890 --> 00:00:57.840\nqu'un capteur bumper a été pressé,\n\n20\n00:00:57.840 --> 00:01:00.540\nou la distance parcourue par un moteur.\n\n21\n00:01:00.540 --> 00:01:02.650\nVous pouvez ensuite utiliser les variables numériques\n\n22\n00:01:02.650 --> 00:01:05.223\npour prendre des décisions basées sur ces données stockées.\n\n23\n00:01:06.210 --> 00:01:08.760\nSi vos données proviennent toujours d'un même capteur,\n\n24\n00:01:08.760 --> 00:01:12.283\nmais à des moments différents, c'est à ce moment-là que vous utiliserez une liste.\n\n25\n00:01:14.040 --> 00:01:15.050\nDans cet exemple,\n\n26\n00:01:15.050 --> 00:01:18.110\nla liste va stocker la valeur de la position du moteur\n\n27\n00:01:18.110 --> 00:01:20.050\nune fois par seconde.\n\n28\n00:01:20.050 --> 00:01:22.090\nCes informations pourront être utilisées plus tard\n\n29\n00:01:22.090 --> 00:01:23.410\npour créer un calcul\n\n30\n00:01:23.410 --> 00:01:25.573\nafin de déterminer la vitesse moyenne du moteur.\n\n31\n00:01:27.060 --> 00:01:28.320\nSi vous voulez des données de capteur\n\n32\n00:01:28.320 --> 00:01:30.970\nà partir de plusieurs capteurs tous à des moments différents,\n\n33\n00:01:30.970 --> 00:01:33.040\nvous pouvez utiliser une liste 2D.\n\n34\n00:01:33.040 --> 00:01:34.460\nAvec cette liste 2D,\n\n35\n00:01:34.460 --> 00:01:37.903\nvous pouvez stocker la valeur de la position de deux moteurs.\n\n36\n00:01:42.340 --> 00:01:45.170\nUtiliser une liste 2D au lieu de plusieurs listes\n\n37\n00:01:45.170 --> 00:01:46.950\nfacilite l'utilisation des données\n\n38\n00:01:46.950 --> 00:01:49.960\npour de plus amples calculs dans votre projet.\n\n39\n00:01:49.960 --> 00:01:52.760\nLa possibilité de stocker et d'utiliser différents types de données\n\n40\n00:01:52.760 --> 00:01:54.570\nvous donne l'opportunité\n\n41\n00:01:54.570 --> 00:01:57.463\nde créer des projets plus intéressants et plus avancés.\n\n","ko":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5에는 프로젝트 내부에</v>\n\n2\n00:00:02.980 --> 00:00:05.593\n데이터를 저장하고 사용할 수 있는 네 가지 방법이 있습니다.\n\n3\n00:00:06.660 --> 00:00:10.190\n부울은 참 또는 거짓 값을 저장하고\n\n4\n00:00:10.190 --> 00:00:14.470\n숫자 변수는 단일 숫자의 값을 저장합니다.\n\n5\n00:00:14.470 --> 00:00:19.010\n리스트는 관련된 여러 숫자의 값을 저장하고\n\n6\n00:00:19.010 --> 00:00:21.470\n2D 리스트는\n\n7\n00:00:21.470 --> 00:00:23.790\n여러 관련 리스트\n\n8\n00:00:23.790 --> 00:00:26.823\n또는 관련 숫자 값의 큰 집합을 저장합니다.\n\n9\n00:00:27.770 --> 00:00:29.620\n부울 변수는 범퍼 센서 또는 컨트롤러 버튼의 값처럼\n\n10\n00:00:29.620 --> 00:00:32.760\n단일의 참 또는 거짓 값을\n\n11\n00:00:32.760 --> 00:00:35.380\n저장하는 데\n\n12\n00:00:35.380 --> 00:00:37.023\n유용합니다.\n\n13\n00:00:38.930 --> 00:00:40.920\n숫자 변수는 숫자 데이터를 저장하고\n\n14\n00:00:40.920 --> 00:00:43.960\n검색하는 데 유용합니다.\n\n15\n00:00:43.960 --> 00:00:46.450\n숫자 데이터는 비전 센서 또는 컨트롤러의 축과 같은\n\n16\n00:00:46.450 --> 00:00:50.860\n보고 블록(Reporter Blocks)에서 얻을 수 있습니다.\n\n17\n00:00:50.860 --> 00:00:54.370\n변수는 범퍼 센서를 누른 횟수\n\n18\n00:00:54.370 --> 00:00:55.890\n또는 모터가 이동한 거리 등\n\n19\n00:00:55.890 --> 00:00:57.840\n프로젝트에 정보를 저장하는 데\n\n20\n00:00:57.840 --> 00:01:00.540\n유용합니다.\n\n21\n00:01:00.540 --> 00:01:02.650\n그런 다음 숫자 변수를 사용하여\n\n22\n00:01:02.650 --> 00:01:05.223\n저장된 데이터를 기반으로 결정을 내릴 수 있습니다.\n\n23\n00:01:06.210 --> 00:01:08.760\n데이터가 여전히 하나의 센서에서 전송되지만\n\n24\n00:01:08.760 --> 00:01:12.283\n다른 시간에 전송되는 경우 이 때 리스트를 사용합니다.\n\n25\n00:01:14.040 --> 00:01:15.050\n이 예제에서\n\n26\n00:01:15.050 --> 00:01:18.110\n리스트는 모터의 위치 값을\n\n27\n00:01:18.110 --> 00:01:20.050\n1초에 한 번씩 저장합니다.\n\n28\n00:01:20.050 --> 00:01:22.090\n이 정보는 나중에\n\n29\n00:01:22.090 --> 00:01:23.410\n모터의 평균 속도를 결정하는\n\n30\n00:01:23.410 --> 00:01:25.573\n계산에 사용될 수 있습니다.\n\n31\n00:01:27.060 --> 00:01:28.320\n서로 다른 시간대의\n\n32\n00:01:28.320 --> 00:01:30.970\n다양한 센서로부터 취합된 센서 데이터를\n\n33\n00:01:30.970 --> 00:01:33.040\n원하는 경우 2D 리스트를 사용할 수 있습니다.\n\n34\n00:01:33.040 --> 00:01:34.460\n2D 리스트를 사용하면\n\n35\n00:01:34.460 --> 00:01:37.903\n두 모터의 위치 값을 저장할 수 있습니다.\n\n36\n00:01:42.340 --> 00:01:45.170\n여러 리스트 대신 2D 리스트를 사용하면\n\n37\n00:01:45.170 --> 00:01:46.950\n프로젝트의 추가 계산에\n\n38\n00:01:46.950 --> 00:01:49.960\n데이터를 더 쉽게 사용할 수 있습니다.\n\n39\n00:01:49.960 --> 00:01:52.760\n다양한 데이터 유형을 저장하고 사용할 수 있는 기능은\n\n40\n00:01:52.760 --> 00:01:54.570\n더 흥미롭고 발전된 프로젝트를 만들 수 있는\n\n41\n00:01:54.570 --> 00:01:57.463\n기회를 제공합니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>Programa \"VEXcode V5\" keturiais skirtingais būdais</v>\n\n2\n00:00:02.980 --> 00:00:05.593\ngali saugoti ir naudoti Jūsų projekto duomenis.\n\n3\n00:00:06.660 --> 00:00:10.190\nBūlio lygtimis saugoma teisinga arba neteisinga vertė,\n\n4\n00:00:10.190 --> 00:00:14.470\nskaitiniais kintamaisiais saugomos skaitinės vertės,\n\n5\n00:00:14.470 --> 00:00:19.010\nįrašai saugo įvairias susijusias skaitines vertes,\n\n6\n00:00:19.010 --> 00:00:21.470\ndvimačiai sąrašai,\n\n7\n00:00:21.470 --> 00:00:23.790\nkuriuose saugomi keli susiję sąrašai\n\n8\n00:00:23.790 --> 00:00:26.823\narba dideles susijusių skaitinių verčių grupes.\n\n9\n00:00:27.770 --> 00:00:29.620\nBūlio kintamieji naudingi\n\n10\n00:00:29.620 --> 00:00:32.760\nsaugoti teisingoms arba neteisingoms vertėms,\n\n11\n00:00:32.760 --> 00:00:35.380\npavyzdžiui, buferio jutiklio\n\n12\n00:00:35.380 --> 00:00:37.023\narba valdiklio mygtuko vertei.\n\n13\n00:00:38.930 --> 00:00:40.920\nSkaitiniai kintamieji naudingi\n\n14\n00:00:40.920 --> 00:00:43.960\nsaugoti ir gauti skaitinius duomenis.\n\n15\n00:00:43.960 --> 00:00:46.450\nSkaitinius duomenis gali pateikti \"ataskaitos\" blokai,\n\n16\n00:00:46.450 --> 00:00:50.860\npavyzdžiui, vaizdo jutiklis arba valdiklio ašis.\n\n17\n00:00:50.860 --> 00:00:54.370\nKintamieji puikiai tinka informacijai Jūsų projekte saugoti,\n\n18\n00:00:54.370 --> 00:00:55.890\npavyzdžiui, kiek kartų\n\n19\n00:00:55.890 --> 00:00:57.840\nbuvo nuspaustas buferio jutiklis\n\n20\n00:00:57.840 --> 00:01:00.540\narba kokį atstumą nukeliavo variklis.\n\n21\n00:01:00.540 --> 00:01:02.650\nSkaitines vertes galite naudoti\n\n22\n00:01:02.650 --> 00:01:05.223\nsprendimams pagal saugomus duomenis priimti.\n\n23\n00:01:06.210 --> 00:01:08.760\nJeigu Jūsų duomenys yra iš vieno jutiklio,\n\n24\n00:01:08.760 --> 00:01:12.283\nbet iš skirtingų laikų, tada naudojate sąrašą.\n\n25\n00:01:14.040 --> 00:01:15.050\nŠiame pavyzdyje,\n\n26\n00:01:15.050 --> 00:01:18.110\nsąrašas kartą kiekvieną sekundę\n\n27\n00:01:18.110 --> 00:01:20.050\nišsaugo variklio padėties vertę.\n\n28\n00:01:20.050 --> 00:01:22.090\nŠią informaciją galima panaudoti vėliau\n\n29\n00:01:22.090 --> 00:01:23.410\nvariklio vidutinio greičio skaičiavimams\n\n30\n00:01:23.410 --> 00:01:25.573\nsukurti.\n\n31\n00:01:27.060 --> 00:01:28.320\nJeigu norite gauti jutiklio duomenis\n\n32\n00:01:28.320 --> 00:01:30.970\niš skirtingų jutiklių skirtingais laikais,\n\n33\n00:01:30.970 --> 00:01:33.040\ngalite naudoti dvimatį sąrašą.\n\n34\n00:01:33.040 --> 00:01:34.460\nJame\n\n35\n00:01:34.460 --> 00:01:37.903\ngalite išsaugoti dviejų variklių padėties vertę.\n\n36\n00:01:42.340 --> 00:01:45.170\nVietoje kelių sąrašų naudojant 2D sąrašą,\n\n37\n00:01:45.170 --> 00:01:46.950\nlengviau naudoti duomenis\n\n38\n00:01:46.950 --> 00:01:49.960\ntolesniems skaičiavimams Jūsų projekte atlikti.\n\n39\n00:01:49.960 --> 00:01:52.760\nGalimybė saugoti ir naudoti skirtingus duomenų tipus suteikia\n\n40\n00:01:52.760 --> 00:01:54.570\ngalimybę\n\n41\n00:01:54.570 --> 00:01:57.463\nkurti įdomesnius ir pažangesnius projektus.\n\n","lv":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 ir četri dažādi veidi,</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nlai saglabātu un izmantotu datus jūsu projekta ietvaros.\n\n3\n00:00:06.660 --> 00:00:10.190\nBūla, lai saglabātu patiesu vai nepatiesu vērtību,\n\n4\n00:00:10.190 --> 00:00:14.470\nskaitliskie mainīgie, lai saglabātu vienu skaitlisku vērtību,\n\n5\n00:00:14.470 --> 00:00:19.010\nsaraksti, lai saglabātu vairākas saistītas skaitliskas vērtības,\n\n6\n00:00:19.010 --> 00:00:21.470\nun divdimensiju saraksti,\n\n7\n00:00:21.470 --> 00:00:23.790\nkas glabā vairākus saistītus sarakstus\n\n8\n00:00:23.790 --> 00:00:26.823\nvai lielas saistīto skaitlisko vērtību grupas.\n\n9\n00:00:27.770 --> 00:00:29.620\nBūla mainīgie ir noderīgi\n\n10\n00:00:29.620 --> 00:00:32.760\nvienas patiesas vai nepatiesas vērtības saglabāšanai,\n\n11\n00:00:32.760 --> 00:00:35.380\npiemēram, iegūtā vērtība no saskares slēdža\n\n12\n00:00:35.380 --> 00:00:37.023\nvai vadāmierīces pogas.\n\n13\n00:00:38.930 --> 00:00:40.920\nSkaitliskie mainīgie ir noderīgi,\n\n14\n00:00:40.920 --> 00:00:43.960\nlai saglabātu un iegūtu skaitliskus datus.\n\n15\n00:00:43.960 --> 00:00:46.450\nSkaitliskos datus var iegūt no ziņošanas blokiem,\n\n16\n00:00:46.450 --> 00:00:50.860\npiemēram, attēla sensora vai vadāmierīces sviras.\n\n17\n00:00:50.860 --> 00:00:54.370\nMainīgie ir lieliski, lai ievadītu informāciju jūsu projektā,\n\n18\n00:00:54.370 --> 00:00:55.890\npiemēram, reižu skaitu, cik\n\n19\n00:00:55.890 --> 00:00:57.840\nir nospiests saskares slēdzis,\n\n20\n00:00:57.840 --> 00:01:00.540\nvai arī attālums, kādā ir braucis motors.\n\n21\n00:01:00.540 --> 00:01:02.650\nŠādas skaitliskās mainīgais vērtības lieto,\n\n22\n00:01:02.650 --> 00:01:05.223\nlai pieņemtu lēmumus, pamatojoties uz saglabātajiem datiem.\n\n23\n00:01:06.210 --> 00:01:08.760\nJa dati ir iegūti no viena sensora,\n\n24\n00:01:08.760 --> 00:01:12.283\nbet dažādos laikos, tad izmantosiet sarakstu.\n\n25\n00:01:14.040 --> 00:01:15.050\nŠajā piemērā\n\n26\n00:01:15.050 --> 00:01:18.110\nsarakstā tiek saglabāta motora pozīcijas vērtība\n\n27\n00:01:18.110 --> 00:01:20.050\nik pēc sekundes.\n\n28\n00:01:20.050 --> 00:01:22.090\nŠādu informāciju var izmantot vēlāk,\n\n29\n00:01:22.090 --> 00:01:23.410\nlai izveidotu aprēķinu\n\n30\n00:01:23.410 --> 00:01:25.573\nun noteiktu motora vidējo ātrumu.\n\n31\n00:01:27.060 --> 00:01:28.320\nJa vēlaties iegūt sensora datus\n\n32\n00:01:28.320 --> 00:01:30.970\nno vairākiem sensoriem dažādos laikos,\n\n33\n00:01:30.970 --> 00:01:33.040\nvar izmantot 2D sarakstu.\n\n34\n00:01:33.040 --> 00:01:34.460\nAr šo 2D sarakstu,\n\n35\n00:01:34.460 --> 00:01:37.903\nvariet saglabāt divu motoru pozīcijas vērtības.\n\n36\n00:01:42.340 --> 00:01:45.170\nIzmantojot 2D sarakstu nevis vairākus sarakstus,\n\n37\n00:01:45.170 --> 00:01:46.950\natvieglo datu izmantošanu,\n\n38\n00:01:46.950 --> 00:01:49.960\nveicot papildu aprēķinus projektā.\n\n39\n00:01:49.960 --> 00:01:52.760\nSpēja ievadīt un izmantot dažādus datu tipus\n\n40\n00:01:52.760 --> 00:01:54.570\nnodrošina iespēju\n\n41\n00:01:54.570 --> 00:01:57.463\nradīt interesantākus un progresīvākus projektus.\n\n","nl":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor> VEXcode V5 heeft vier verschillende manieren </v>\n\n2\n00:00:02.980 --> 00:00:05.593\nom gegevens binnen uw project op te slaan en te gebruiken.\n\n3\n00:00:06.660 --> 00:00:10.190\nBooleans om een waar of onjuist waarde op te slaan,\n\n4\n00:00:10.190 --> 00:00:14.470\nnumerieke variabelen om een enkele numerieke waarde op te slaan,\n\n5\n00:00:14.470 --> 00:00:19.010\nlijsten om meerdere numerieke waarden op te slaan die gerelateerd zijn,\n\n6\n00:00:19.010 --> 00:00:21.470\nen tweedimensionale lijsten,\n\n7\n00:00:21.470 --> 00:00:23.790\nwaarin meerdere gerelateerde lijsten\n\n8\n00:00:23.790 --> 00:00:26.823\nof grote groepen gerelateerde numerieke waarden worden opgeslagen.\n\n9\n00:00:27.770 --> 00:00:29.620\nBooleaanse variabelen zijn nuttig\n\n10\n00:00:29.620 --> 00:00:32.760\nvoor het opslaan van enkele ware of onjuiste waarde\n\n11\n00:00:32.760 --> 00:00:35.380\nzoals de waarde van een bumper sensor\n\n12\n00:00:35.380 --> 00:00:37.023\nof een controller knop.\n\n13\n00:00:38.930 --> 00:00:40.920\nNumerieke variabelen zijn handig voor het opslaan\n\n14\n00:00:40.920 --> 00:00:43.960\nen ophalen van numerieke gegevens.\n\n15\n00:00:43.960 --> 00:00:46.450\nNumerieke gegevens kunnen afkomstig zijn van reporterblokken,\n\n16\n00:00:46.450 --> 00:00:50.860\nzoals de beeldsensor of een controller-as.\n\n17\n00:00:50.860 --> 00:00:54.370\nVariabelen zijn geweldig om informatie in uw project op te slaan,\n\n18\n00:00:54.370 --> 00:00:55.890\nzoals het aantal keren\n\n19\n00:00:55.890 --> 00:00:57.840\ndat een bumper sensor is ingedrukt,\n\n20\n00:00:57.840 --> 00:01:00.540\nof de afstand die een motor heeft afgelegd.\n\n21\n00:01:00.540 --> 00:01:02.650\nU kunt vervolgens numerieke variabelen\n\n22\n00:01:02.650 --> 00:01:05.223\ngebruiken om beslissingen te nemen op basis van opgeslagen gegevens.\n\n23\n00:01:06.210 --> 00:01:08.760\nAls uw gegevens nog steeds van één sensor komen,\n\n24\n00:01:08.760 --> 00:01:12.283\nmaar op verschillende tijdstippen, dan zou u de lijst gebruiken.\n\n25\n00:01:14.040 --> 00:01:15.050\nIn dit voorbeeld,\n\n26\n00:01:15.050 --> 00:01:18.110\nzal de lijst de waarde van de motorpositie\n\n27\n00:01:18.110 --> 00:01:20.050\neenmaal per seconde opslaan.\n\n28\n00:01:20.050 --> 00:01:22.090\nDeze informatie kan later gebruikt worden\n\n29\n00:01:22.090 --> 00:01:23.410\nom een berekening te maken\n\n30\n00:01:23.410 --> 00:01:25.573\nom de gemiddelde snelheid van de motor te bepalen.\n\n31\n00:01:27.060 --> 00:01:28.320\nAls u sensorgegevens\n\n32\n00:01:28.320 --> 00:01:30.970\nvan meerdere sensoren op verschillende tijdstippen wilt,\n\n33\n00:01:30.970 --> 00:01:33.040\nkunt u een 2D-lijst gebruiken.\n\n34\n00:01:33.040 --> 00:01:34.460\nMet deze 2D lijst\n\n35\n00:01:34.460 --> 00:01:37.903\nkunt u de waarde van de positie van twee motoren opslaan.\n\n36\n00:01:42.340 --> 00:01:45.170\nAls u een 2D-lijst gebruikt in plaats van meerdere lijsten,\n\n37\n00:01:45.170 --> 00:01:46.950\nkunt u de gegevens gemakkelijker gebruiken\n\n38\n00:01:46.950 --> 00:01:49.960\nvoor verdere berekeningen in uw project.\n\n39\n00:01:49.960 --> 00:01:52.760\nDe mogelijkheid om verschillende gegevenstypen op te slaan en te gebruiken\n\n40\n00:01:52.760 --> 00:01:54.570\nbiedt u de mogelijkheid\n\n41\n00:01:54.570 --> 00:01:57.463\nom interessantere en geavanceerdere projecten te maken.\n\n","pl":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>Bloki VEXcode V5 mają cztery różne sposoby</v>\n\n2\n00:00:02.980 --> 00:00:05.593\naby przechowywać i używać danych wewnątrz projektu.\n\n3\n00:00:06.660 --> 00:00:10.190\nWartości logiczne do przechowywania wartości prawdziwych lub fałszywych,\n\n4\n00:00:10.190 --> 00:00:14.470\nzmienne liczbowe do przechowywania pojedynczej wartości numerycznej,\n\n5\n00:00:14.470 --> 00:00:19.010\nlisty, aby przechowywać wiele wartości numerycznych, które są powiązane,\n\n6\n00:00:19.010 --> 00:00:21.470\nlisty dwuwymiarowe,\n\n7\n00:00:21.470 --> 00:00:23.790\nktóry przechowuje wiele powiązanych list\n\n8\n00:00:23.790 --> 00:00:26.823\nlub duże grupy powiązanych wartości liczbowych.\n\n9\n00:00:27.770 --> 00:00:29.620\nZmienne logiczne są przydatne\n\n10\n00:00:29.620 --> 00:00:32.760\ndo przechowywania pojedynczej wartości prawda lub fałsz\n\n11\n00:00:32.760 --> 00:00:35.380\nnp. wartość z czujnika zderzaka\n\n12\n00:00:35.380 --> 00:00:37.023\nlub przycisk kontrolera.\n\n13\n00:00:38.930 --> 00:00:40.920\nZmienne liczbowe są przydatne\n\n14\n00:00:40.920 --> 00:00:43.960\ndo przechowywania i pobierania danych numerycznych.\n\n15\n00:00:43.960 --> 00:00:46.450\nDane liczbowe mogą pochodzić z bloków zgłaszających,\n\n16\n00:00:46.450 --> 00:00:50.860\ntakie jak czujnik widzenia lub oś sterowania.\n\n17\n00:00:50.860 --> 00:00:54.370\nZmienne są świetne do przechowywania informacji w Twoim projekcie,\n\n18\n00:00:54.370 --> 00:00:55.890\nnp. liczba razy\n\n19\n00:00:55.890 --> 00:00:57.840\nktóre wciśnięto czujnik zderzaka,\n\n20\n00:00:57.840 --> 00:01:00.540\nlub odległość, jaką pokonał silnik.\n\n21\n00:01:00.540 --> 00:01:02.650\nNastępnie można użyć wartości liczbowych\n\n22\n00:01:02.650 --> 00:01:05.223\ndo podejmowani decyzji na podstawie przechowywanych danych.\n\n23\n00:01:06.210 --> 00:01:08.760\nJeśli dane nadal pochodzą z jednego czujnika,\n\n24\n00:01:08.760 --> 00:01:12.283\nale w różnych momentów, kiedy chcesz użyć listy.\n\n25\n00:01:14.040 --> 00:01:15.050\nW tym przykładzie\n\n26\n00:01:15.050 --> 00:01:18.110\nlista będzie przechowywać wartość pozycji silnika\n\n27\n00:01:18.110 --> 00:01:20.050\nraz na sekundę.\n\n28\n00:01:20.050 --> 00:01:22.090\nInformacje te można wykorzystać później\n\n29\n00:01:22.090 --> 00:01:23.410\naby obliczyć\n\n30\n00:01:23.410 --> 00:01:25.573\ndo określenia średniej prędkości silnika.\n\n31\n00:01:27.060 --> 00:01:28.320\nJeśli chcesz, zebrać dane czujnika\n\n32\n00:01:28.320 --> 00:01:30.970\nz wielu czujników w różnych czasach,\n\n33\n00:01:30.970 --> 00:01:33.040\nmożesz użyć listy 2D.\n\n34\n00:01:33.040 --> 00:01:34.460\nZ tą listą 2D,\n\n35\n00:01:34.460 --> 00:01:37.903\nmożesz przechowywać wartość pozycji dwóch silników.\n\n36\n00:01:42.340 --> 00:01:45.170\nUżywanie listy 2D zamiast wielu list\n\n37\n00:01:45.170 --> 00:01:46.950\nułatwia korzystanie z danych\n\n38\n00:01:46.950 --> 00:01:49.960\ndo dalszych obliczeń w twoim programie.\n\n39\n00:01:49.960 --> 00:01:52.760\nMożliwość przechowywania i używania różnych typów danych\n\n40\n00:01:52.760 --> 00:01:54.570\ndaje Ci możliwość\n\n41\n00:01:54.570 --> 00:01:57.463\naby stworzyć bardziej interesujące i zaawansowane programy.\n\n","ru":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 имеет четыре способа хранения</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nи использования информации внутри проекта.\n\n3\n00:00:06.660 --> 00:00:10.190\nЛогические переменные хранят true или false,\n\n4\n00:00:10.190 --> 00:00:14.470\nчисловые переменные могут хранить одно числовое значение,\n\n5\n00:00:14.470 --> 00:00:19.010\nсписки могут хранить несколько числовых значений,\n\n6\n00:00:19.010 --> 00:00:21.470\nдвумерные списки\n\n7\n00:00:21.470 --> 00:00:23.790\nхранят в себе списки\n\n8\n00:00:23.790 --> 00:00:26.823\nили большие объёмы единичных числовых значений.\n\n9\n00:00:27.770 --> 00:00:29.620\nЛогические переменные удобно использовать\n\n10\n00:00:29.620 --> 00:00:32.760\nдля хранения значений true или false,\n\n11\n00:00:32.760 --> 00:00:35.380\nтакой как событие нажатия датчика касания\n\n12\n00:00:35.380 --> 00:00:37.023\nили кнопки пульта управления.\n\n13\n00:00:38.930 --> 00:00:40.920\nЧисловые переменные удобно использовать\n\n14\n00:00:40.920 --> 00:00:43.960\nдля хранения и получения числовых данных.\n\n15\n00:00:43.960 --> 00:00:46.450\nЧисловые данные могут приходить с других блоков,\n\n16\n00:00:46.450 --> 00:00:50.860\nтаких как блоки камеры или осей пульта управления.\n\n17\n00:00:50.860 --> 00:00:54.370\nПеременные полезны для хранения информации в вашем проекте,\n\n18\n00:00:54.370 --> 00:00:55.890\nтакой как число нажатий\n\n19\n00:00:55.890 --> 00:00:57.840\nдатчика касания\n\n20\n00:00:57.840 --> 00:01:00.540\nили расстояние, пройденное приводом.\n\n21\n00:01:00.540 --> 00:01:02.650\nЧисловые переменные можно использовать\n\n22\n00:01:02.650 --> 00:01:05.223\nдля принятия решения на основе хранимых данных.\n\n23\n00:01:06.210 --> 00:01:08.760\nЕсли данные приходят с одного датчика,\n\n24\n00:01:08.760 --> 00:01:12.283\nно в разное время, то для хранения лучше всего использовать список.\n\n25\n00:01:14.040 --> 00:01:15.050\nВ этом примере\n\n26\n00:01:15.050 --> 00:01:18.110\nсписок хранит положения привода,\n\n27\n00:01:18.110 --> 00:01:20.050\nполучаемые ежесекундно.\n\n28\n00:01:20.050 --> 00:01:22.090\nДанная информация может быть использована позднее\n\n29\n00:01:22.090 --> 00:01:23.410\nдля проведения вычисления\n\n30\n00:01:23.410 --> 00:01:25.573\nсредней скорости привода.\n\n31\n00:01:27.060 --> 00:01:28.320\nЕсли вы хотите получить данные\n\n32\n00:01:28.320 --> 00:01:30.970\nот нескольких устройств,\n\n33\n00:01:30.970 --> 00:01:33.040\nвы можете использовать 2D список.\n\n34\n00:01:33.040 --> 00:01:34.460\nВ двумерном списке\n\n35\n00:01:34.460 --> 00:01:37.903\nвы можете хранить положения двух приводов.\n\n36\n00:01:42.340 --> 00:01:45.170\nИспользование двумерного списка вместо нескольких списков\n\n37\n00:01:45.170 --> 00:01:46.950\nоблегчает дальнейшие\n\n38\n00:01:46.950 --> 00:01:49.960\nвычисления в программе.\n\n39\n00:01:49.960 --> 00:01:52.760\nВозможность хранить и использовать различные типы данных\n\n40\n00:01:52.760 --> 00:01:54.570\nпозволит вам создавать более интересные\n\n41\n00:01:54.570 --> 00:01:57.463\nи продвинутые проекты.\n\n","th":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor> VEXcode V5 มีสี่วิธีที่แตกต่างกัน </v>\n\n2\n00:00:02.980 --> 00:00:05.593\nเพื่อจัดเก็บและใช้ข้อมูลภายในโปรเจ็คของคุณ\n\n3\n00:00:06.660 --> 00:00:10.190\nBooleans ใช้เพื่อเก็บค่าจริงหรือเท็จ\n\n4\n00:00:10.190 --> 00:00:14.470\nตัวแปรตัวเลข ใช้เพื่อจัดเก็บค่าตัวเลขเดียว\n\n5\n00:00:14.470 --> 00:00:19.010\nรายการ ใช้เพื่อเก็บค่าตัวเลขหลายค่าที่เกี่ยวข้อง\n\n6\n00:00:19.010 --> 00:00:21.470\nและรายการแบบสองมิติ\n\n7\n00:00:21.470 --> 00:00:23.790\nเพื่อเก็บรายการที่เกี่ยวข้องหลายรายการ\n\n8\n00:00:23.790 --> 00:00:26.823\nหรือกลุ่มใหญ่ของค่าตัวเลขที่เกี่ยวข้อง\n\n9\n00:00:27.770 --> 00:00:29.620\nตัวแปร Boolean มีประโยชน์\n\n10\n00:00:29.620 --> 00:00:32.760\nสำหรับการจัดเก็บค่าจริงหรือเท็จเพียงค่าเดียว\n\n11\n00:00:32.760 --> 00:00:35.380\nเช่นค่าจากเซ็นเซอร์กันชน\n\n12\n00:00:35.380 --> 00:00:37.023\nหรือปุ่มควบคุม\n\n13\n00:00:38.930 --> 00:00:40.920\nตัวแปร ตัวเลข มีประโยชน์\n\n14\n00:00:40.920 --> 00:00:43.960\nสำหรับจัดเก็บและดึงข้อมูลตัวเลข\n\n15\n00:00:43.960 --> 00:00:46.450\nข้อมูลตัวเลขอาจมาจากบล็อกผู้รายงาน\n\n16\n00:00:46.450 --> 00:00:50.860\nเช่นเซ็นเซอร์การมองเห็นหรือแกนควบคุม\n\n17\n00:00:50.860 --> 00:00:54.370\nตัวแปรเป็นสิ่งที่ดีในการจัดเก็บข้อมูลในโปรเจ็คของคุณ\n\n18\n00:00:54.370 --> 00:00:55.890\nเช่นจำนวนครั้ง\n\n19\n00:00:55.890 --> 00:00:57.840\nที่เซ็นเซอร์กันชนถูกกด\n\n20\n00:00:57.840 --> 00:01:00.540\nหรือระยะทางที่มอเตอร์เคลื่อนที่ไป\n\n21\n00:01:00.540 --> 00:01:02.650\nจากนั้นคุณสามารถใช้ตัวแปรตัวเลข\n\n22\n00:01:02.650 --> 00:01:05.223\nในการตัดสินใจตามข้อมูลที่จัดเก็บไว้\n\n23\n00:01:06.210 --> 00:01:08.760\nหากข้อมูลของคุณยังมาจากเซ็นเซอร์เดียว\n\n24\n00:01:08.760 --> 00:01:12.283\nแต่ในเวลาที่ต่างกันนั่นคือเวลาที่คุณจะใช้รายการ list\n\n25\n00:01:14.040 --> 00:01:15.050\nในตัวอย่างนี้\n\n26\n00:01:15.050 --> 00:01:18.110\nรายการจะเก็บค่าของตำแหน่งของมอเตอร์\n\n27\n00:01:18.110 --> 00:01:20.050\nทุกๆวินาที\n\n28\n00:01:20.050 --> 00:01:22.090\nซึ่งข้อมูลนี้สามารถนำไปใช้ได้ในภายหลัง\n\n29\n00:01:22.090 --> 00:01:23.410\nเพื่อสร้างการคำนวณ\n\n30\n00:01:23.410 --> 00:01:25.573\nเพื่อกำหนดความเร็วเฉลี่ยของมอเตอร์\n\n31\n00:01:27.060 --> 00:01:28.320\nหากคุณต้องการข้อมูลเซ็นเซอร์\n\n32\n00:01:28.320 --> 00:01:30.970\nจากเซ็นเซอร์หลายตัวในเวลาที่ต่างกัน\n\n33\n00:01:30.970 --> 00:01:33.040\nคุณสามารถใช้รายการ 2D list\n\n34\n00:01:33.040 --> 00:01:34.460\n2D list นี้\n\n35\n00:01:34.460 --> 00:01:37.903\nคุณสามารถจัดเก็บค่าตำแหน่งของมอเตอร์สองตัว\n\n36\n00:01:42.340 --> 00:01:45.170\nใช้รายการ 2D แทนหลายรายการ\n\n37\n00:01:45.170 --> 00:01:46.950\nทำให้ง่ายต่อการใช้ข้อมูล\n\n38\n00:01:46.950 --> 00:01:49.960\nเพื่อการคำนวณเพิ่มเติมในโครงการของคุณ\n\n39\n00:01:49.960 --> 00:01:52.760\nความสามารถในการจัดเก็บและใช้ข้อมูลประเภทต่างๆ\n\n40\n00:01:52.760 --> 00:01:54.570\nทำให้คุณมีโอกาส\n\n41\n00:01:54.570 --> 00:01:57.463\nสร้างโปรเจ็คที่น่าสนใจและก้าวหน้ามากขึ้น\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 має чотири способи</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nзберігання і використання даних усередині проєкту.\n\n3\n00:00:06.660 --> 00:00:10.190\nЛогічні змінні зберігають значення істина або хиба,\n\n4\n00:00:10.190 --> 00:00:14.470\nчислові змінні зберігають одне числове значення,\n\n5\n00:00:14.470 --> 00:00:19.010\nсписки зберігають кілька числових значень, які пов'язані,\n\n6\n00:00:19.010 --> 00:00:21.470\nі двовимірні списки,\n\n7\n00:00:21.470 --> 00:00:23.790\nзберігають декілька пов'язаних списків\n\n8\n00:00:23.790 --> 00:00:26.823\nабо великі групи пов'язаних числових значень.\n\n9\n00:00:27.770 --> 00:00:29.620\nЧислові змінні підходять\n\n10\n00:00:29.620 --> 00:00:32.760\nдля зберігання значень істина чи хиба,\n\n11\n00:00:32.760 --> 00:00:35.380\nнаприклад, значення з бамперного перемикача\n\n12\n00:00:35.380 --> 00:00:37.023\nабо кнопок керування.\n\n13\n00:00:38.930 --> 00:00:40.920\nЧислові змінні підходять\n\n14\n00:00:40.920 --> 00:00:43.960\nдля зберігання і отримання числових даних.\n\n15\n00:00:43.960 --> 00:00:46.450\nЧислові дані можуть надходити із блоків відповіді,\n\n16\n00:00:46.450 --> 00:00:50.860\nяк-от від датчика зору або вісі контролера.\n\n17\n00:00:50.860 --> 00:00:54.370\nЗмінні потрібні для зберігання інформації у вашому проєкті,\n\n18\n00:00:54.370 --> 00:00:55.890\nзокрема, скільки разів\n\n19\n00:00:55.890 --> 00:00:57.840\nспрацював бамперний перемикач,\n\n20\n00:00:57.840 --> 00:01:00.540\nабо відстань, яку мотор проїхав.\n\n21\n00:01:00.540 --> 00:01:02.650\nВи також можете використовувати числові змінні\n\n22\n00:01:02.650 --> 00:01:05.223\nдля прийняття рішень на основі наявних даних.\n\n23\n00:01:06.210 --> 00:01:08.760\nЯкщо дані отримано з одного датчика,\n\n24\n00:01:08.760 --> 00:01:12.283\nале в різний період часу, тоді краще використати список.\n\n25\n00:01:14.040 --> 00:01:15.050\nУ цьому прикладі\n\n26\n00:01:15.050 --> 00:01:18.110\nсписок зберігає значення позицій мотора\n\n27\n00:01:18.110 --> 00:01:20.050\nщосекунди.\n\n28\n00:01:20.050 --> 00:01:22.090\nЦю інформацію можна використати пізніше\n\n29\n00:01:22.090 --> 00:01:23.410\nдля обчислень,\n\n30\n00:01:23.410 --> 00:01:25.573\nщоб визначити середню швидкість мотора.\n\n31\n00:01:27.060 --> 00:01:28.320\nЯкщо ви отримуєте дані\n\n32\n00:01:28.320 --> 00:01:30.970\nз кількох датчиків у різний час,\n\n33\n00:01:30.970 --> 00:01:33.040\nможете використати 2D список.\n\n34\n00:01:33.040 --> 00:01:34.460\nЦей 2D список\n\n35\n00:01:34.460 --> 00:01:37.903\nдасть вам змогу зберігати значення позицій двох моторів.\n\n36\n00:01:42.340 --> 00:01:45.170\nВикористання 2D списку замість кількох звичайних\n\n37\n00:01:45.170 --> 00:01:46.950\nспростить використання даних\n\n38\n00:01:46.950 --> 00:01:49.960\nу подальших проєктних розрахунках.\n\n39\n00:01:49.960 --> 00:01:52.760\nМожливість зберігати і використовувати різні типи даних\n\n40\n00:01:52.760 --> 00:01:54.570\nдає можливості для\n\n41\n00:01:54.570 --> 00:01:57.463\nстворення цікавіших і серйозніших проєктів.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5 có bốn cách khác nhau</v>\n\n2\n00:00:02.980 --> 00:00:05.593\nđể lưu trữ và sử dụng dữ liệu bên trong dự án của bạn.\n\n3\n00:00:06.660 --> 00:00:10.190\nBoolean để lưu trữ một giá trị đúng hoặc sai,\n\n4\n00:00:10.190 --> 00:00:14.470\nbiến số để lưu trữ một giá trị số,\n\n5\n00:00:14.470 --> 00:00:19.010\ndanh sách để lưu trữ nhiều giá trị số có liên quan,\n\n6\n00:00:19.010 --> 00:00:21.470\nvà danh sách hai chiều,\n\n7\n00:00:21.470 --> 00:00:23.790\nnơi lưu trữ nhiều danh sách liên quan\n\n8\n00:00:23.790 --> 00:00:26.823\nhoặc các nhóm lớn các giá trị số có liên quan.\n\n9\n00:00:27.770 --> 00:00:29.620\nCác biến Boolean rất hữu ích\n\n10\n00:00:29.620 --> 00:00:32.760\nđể lưu trữ một giá trị đúng hoặc sai,\n\n11\n00:00:32.760 --> 00:00:35.380\nchẳng hạn như giá trị từ cảm biến đệm\n\n12\n00:00:35.380 --> 00:00:37.023\nhoặc một nút điều khiển.\n\n13\n00:00:38.930 --> 00:00:40.920\nCác biến số rất hữu ích\n\n14\n00:00:40.920 --> 00:00:43.960\nđể lưu trữ và truy xuất dữ liệu số.\n\n15\n00:00:43.960 --> 00:00:46.450\nDữ liệu số có thể đến từ các khối báo cáo,\n\n16\n00:00:46.450 --> 00:00:50.860\nchẳng hạn như cảm biến tầm nhìn hoặc trục bộ điều khiển.\n\n17\n00:00:50.860 --> 00:00:54.370\nCác biến rất tốt để lưu trữ thông tin trong dự án của bạn,\n\n18\n00:00:54.370 --> 00:00:55.890\nchẳng hạn như số lần\n\n19\n00:00:55.890 --> 00:00:57.840\nmột cảm biến đệm đã được nhấn,\n\n20\n00:00:57.840 --> 00:01:00.540\nhoặc quãng đường mà một động cơ đã đi được.\n\n21\n00:01:00.540 --> 00:01:02.650\nSau đó, bạn có thể sử dụng các biến số\n\n22\n00:01:02.650 --> 00:01:05.223\nđể đưa ra quyết định dựa trên dữ liệu được lưu trữ.\n\n23\n00:01:06.210 --> 00:01:08.760\nNếu dữ liệu của bạn vẫn từ một cảm biến,\n\n24\n00:01:08.760 --> 00:01:12.283\nnhưng vào những thời điểm khác nhau, đó là lúc bạn sẽ sử dụng danh sách.\n\n25\n00:01:14.040 --> 00:01:15.050\nTrong ví dụ này,\n\n26\n00:01:15.050 --> 00:01:18.110\ndanh sách sẽ lưu trữ giá trị của vị trí của động cơ\n\n27\n00:01:18.110 --> 00:01:20.050\nmỗi giây một lần.\n\n28\n00:01:20.050 --> 00:01:22.090\nThông tin này có thể được sử dụng sau này\n\n29\n00:01:22.090 --> 00:01:23.410\nđể tạo một phép tính\n\n30\n00:01:23.410 --> 00:01:25.573\nđể xác định tốc độ trung bình của động cơ.\n\n31\n00:01:27.060 --> 00:01:28.320\nNếu bạn muốn dữ liệu cảm biến\n\n32\n00:01:28.320 --> 00:01:30.970\ntừ nhiều cảm biến vào mọi thời điểm khác nhau,\n\n33\n00:01:30.970 --> 00:01:33.040\nbạn có thể sử dụng danh sách 2D.\n\n34\n00:01:33.040 --> 00:01:34.460\nVới danh sách 2D này,\n\n35\n00:01:34.460 --> 00:01:37.903\nbạn có thể lưu trữ giá trị của vị trí của hai động cơ.\n\n36\n00:01:42.340 --> 00:01:45.170\nSử dụng danh sách 2D thay vì nhiều danh sách\n\n37\n00:01:45.170 --> 00:01:46.950\ngiúp sử dụng dữ liệu dễ dàng hơn\n\n38\n00:01:46.950 --> 00:01:49.960\nđể tính toán thêm trong dự án của bạn.\n\n39\n00:01:49.960 --> 00:01:52.760\nKhả năng lưu trữ và sử dụng các kiểu dữ liệu khác nhau\n\n40\n00:01:52.760 --> 00:01:54.570\ncung cấp cho bạn cơ hội\n\n41\n00:01:54.570 --> 00:01:57.463\nđể tạo ra nhiều dự án thú vị và tiên tiến hơn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\ncrwdns96468:0crwdne96468:0\n\n2\n00:00:02.980 --> 00:00:05.593\ncrwdns96470:0crwdne96470:0\n\n3\n00:00:06.660 --> 00:00:10.190\ncrwdns96472:0crwdne96472:0\n\n4\n00:00:10.190 --> 00:00:14.470\ncrwdns96474:0crwdne96474:0\n\n5\n00:00:14.470 --> 00:00:19.010\ncrwdns96476:0crwdne96476:0\n\n6\n00:00:19.010 --> 00:00:21.470\ncrwdns96478:0crwdne96478:0\n\n7\n00:00:21.470 --> 00:00:23.790\ncrwdns96480:0crwdne96480:0\n\n8\n00:00:23.790 --> 00:00:26.823\ncrwdns96482:0crwdne96482:0\n\n9\n00:00:27.770 --> 00:00:29.620\ncrwdns96484:0crwdne96484:0\n\n10\n00:00:29.620 --> 00:00:32.760\ncrwdns96486:0crwdne96486:0\n\n11\n00:00:32.760 --> 00:00:35.380\ncrwdns96488:0crwdne96488:0\n\n12\n00:00:35.380 --> 00:00:37.023\ncrwdns96490:0crwdne96490:0\n\n13\n00:00:38.930 --> 00:00:40.920\ncrwdns96492:0crwdne96492:0\n\n14\n00:00:40.920 --> 00:00:43.960\ncrwdns96494:0crwdne96494:0\n\n15\n00:00:43.960 --> 00:00:46.450\ncrwdns96496:0crwdne96496:0\n\n16\n00:00:46.450 --> 00:00:50.860\ncrwdns96498:0crwdne96498:0\n\n17\n00:00:50.860 --> 00:00:54.370\ncrwdns96500:0crwdne96500:0\n\n18\n00:00:54.370 --> 00:00:55.890\ncrwdns96502:0crwdne96502:0\n\n19\n00:00:55.890 --> 00:00:57.840\ncrwdns96504:0crwdne96504:0\n\n20\n00:00:57.840 --> 00:01:00.540\ncrwdns96506:0crwdne96506:0\n\n21\n00:01:00.540 --> 00:01:02.650\ncrwdns96508:0crwdne96508:0\n\n22\n00:01:02.650 --> 00:01:05.223\ncrwdns96510:0crwdne96510:0\n\n23\n00:01:06.210 --> 00:01:08.760\ncrwdns96512:0crwdne96512:0\n\n24\n00:01:08.760 --> 00:01:12.283\ncrwdns96514:0crwdne96514:0\n\n25\n00:01:14.040 --> 00:01:15.050\ncrwdns96516:0crwdne96516:0\n\n26\n00:01:15.050 --> 00:01:18.110\ncrwdns96518:0crwdne96518:0\n\n27\n00:01:18.110 --> 00:01:20.050\ncrwdns96520:0crwdne96520:0\n\n28\n00:01:20.050 --> 00:01:22.090\ncrwdns96522:0crwdne96522:0\n\n29\n00:01:22.090 --> 00:01:23.410\ncrwdns96524:0crwdne96524:0\n\n30\n00:01:23.410 --> 00:01:25.573\ncrwdns96526:0crwdne96526:0\n\n31\n00:01:27.060 --> 00:01:28.320\ncrwdns96528:0crwdne96528:0\n\n32\n00:01:28.320 --> 00:01:30.970\ncrwdns96530:0crwdne96530:0\n\n33\n00:01:30.970 --> 00:01:33.040\ncrwdns96532:0crwdne96532:0\n\n34\n00:01:33.040 --> 00:01:34.460\ncrwdns96534:0crwdne96534:0\n\n35\n00:01:34.460 --> 00:01:37.903\ncrwdns96536:0crwdne96536:0\n\n36\n00:01:42.340 --> 00:01:45.170\ncrwdns96538:0crwdne96538:0\n\n37\n00:01:45.170 --> 00:01:46.950\ncrwdns96540:0crwdne96540:0\n\n38\n00:01:46.950 --> 00:01:49.960\ncrwdns96542:0crwdne96542:0\n\n39\n00:01:49.960 --> 00:01:52.760\ncrwdns96544:0crwdne96544:0\n\n40\n00:01:52.760 --> 00:01:54.570\ncrwdns96546:0crwdne96546:0\n\n41\n00:01:54.570 --> 00:01:57.463\ncrwdns96548:0crwdne96548:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.510 --> 00:00:02.980\n<v Instructor>VEXcode V5有四种不同的方式</v>\n\n2\n00:00:02.980 --> 00:00:05.593\n来存储和使用程序中的数据。\n\n3\n00:00:06.660 --> 00:00:10.190\n布尔变量用来存储一个“真”或“假”值，\n\n4\n00:00:10.190 --> 00:00:14.470\n数值变量用来存储一个单独的数字值，\n\n5\n00:00:14.470 --> 00:00:19.010\n数组用来存储多个相关的数字值。\n\n6\n00:00:19.010 --> 00:00:21.470\n以及二维数组，\n\n7\n00:00:21.470 --> 00:00:23.790\n用来存储多个相关的数组\n\n8\n00:00:23.790 --> 00:00:26.823\n或大量相关的数值。\n\n9\n00:00:27.770 --> 00:00:29.620\n布尔变量有助于存储\n\n10\n00:00:29.620 --> 00:00:32.760\n单个“真”或“假”值，\n\n11\n00:00:32.760 --> 00:00:35.380\n比如来自一个碰撞开关的值\n\n12\n00:00:35.380 --> 00:00:37.023\n或者遥控器一个按键的值。\n\n13\n00:00:38.930 --> 00:00:40.920\n数值变量有助于\n\n14\n00:00:40.920 --> 00:00:43.960\n存储和读取数字数据。\n\n15\n00:00:43.960 --> 00:00:46.450\n数字数据可来自于报告指令块，\n\n16\n00:00:46.450 --> 00:00:50.860\n比如视觉传感器或遥控器的某个轴。\n\n17\n00:00:50.860 --> 00:00:54.370\n变量对在程序中存储信息很有用，\n\n18\n00:00:54.370 --> 00:00:55.890\n比如一个碰撞开关\n\n19\n00:00:55.890 --> 00:00:57.840\n被按下的次数，\n\n20\n00:00:57.840 --> 00:01:00.540\n或者一个电机已行驶的距离。\n\n21\n00:01:00.540 --> 00:01:02.650\n您随后可以使用数值变量\n\n22\n00:01:02.650 --> 00:01:05.223\n用数值来做出决策。\n\n23\n00:01:06.210 --> 00:01:08.760\n如果你的数据都是来自同一个传感器，\n\n24\n00:01:08.760 --> 00:01:12.283\n只是在不同的时刻，这就是您可以使用数组的时候。\n\n25\n00:01:14.040 --> 00:01:15.050\n在本示例中，\n\n26\n00:01:15.050 --> 00:01:18.110\n数组将每秒一次存储\n\n27\n00:01:18.110 --> 00:01:20.050\n测距仪的值。\n\n28\n00:01:20.050 --> 00:01:22.090\n这些信息稍后将被用于\n\n29\n00:01:22.090 --> 00:01:23.410\n创建一个计算\n\n30\n00:01:23.410 --> 00:01:25.573\n来确定电机的平均速度。\n\n31\n00:01:27.060 --> 00:01:28.320\n如果你想要所有不同时间内\n\n32\n00:01:28.320 --> 00:01:30.970\n来自多个传感器的值，\n\n33\n00:01:30.970 --> 00:01:33.040\n您可以使用二维数组。\n\n34\n00:01:33.040 --> 00:01:34.460\n通过这个二维数组，\n\n35\n00:01:34.460 --> 00:01:37.903\n您可以存储两个电机的转位值。\n\n36\n00:01:42.340 --> 00:01:45.170\n使用一个二维数组而不是多个一维数组，\n\n37\n00:01:45.170 --> 00:01:46.950\n使得程序中利用该数据\n\n38\n00:01:46.950 --> 00:01:49.960\n在您的程序中进行进一步计算。\n\n39\n00:01:49.960 --> 00:01:52.760\n存储和使用不同数据类型的能力\n\n40\n00:01:52.760 --> 00:01:54.570\n给你提供了\n\n41\n00:01:54.570 --> 00:01:57.463\n创建更有趣和更高级程序的机会。\n\n"}},{"thumb":"V5_Tutorial_nameAndSave.jpg","mov":"V5_Blocks_NamingSavingMac_V2","description":"Naming and Saving Your Project (macOS)","filter":"","placeholder":false,"platform":["MacOS"],"vimeo":"475900541","proglang":["blocks","python","cpp"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>To give your project a name,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nopen the File menu, and select Save.\n\n3\n00:00:07.950 --> 00:00:09.970\nSelect a location to save your project\n\n4\n00:00:09.970 --> 00:00:13.393\nin and choose a name that best describes your project.\n\n5\n00:00:17.030 --> 00:00:18.450\nYou can also save your project\n\n6\n00:00:18.450 --> 00:00:21.390\nby selecting the project name in the toolbar.\n\n7\n00:00:21.390 --> 00:00:23.993\nThis will allow you to rename your project as well.\n\n8\n00:00:27.610 --> 00:00:29.770\nOnce your project is initially saved,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 will keep your project saved at all times.\n\n10\n00:00:36.180 --> 00:00:38.150\nIf you forget to save before opening\n\n11\n00:00:38.150 --> 00:00:39.423\nor creating a different project,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 will ask you if you would like\n\n13\n00:00:42.580 --> 00:00:45.720\nto save before you move on to your different projects.\n\n14\n00:00:45.720 --> 00:00:48.110\nYou can also discard your unsaved project\n\n15\n00:00:48.110 --> 00:00:49.743\nif you do not wish to save.\n\n","ar":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>لإعطاء المشروع الخاص بك اسم،</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nافتح قائمة الملفات وحدد \"حفظ\".\n\n3\n00:00:07.950 --> 00:00:09.970\nحدد موقع لحفظ مشروعك\n\n4\n00:00:09.970 --> 00:00:13.393\nواختر اسم يصف مشروعك بشكل جيد.\n\n5\n00:00:17.030 --> 00:00:18.450\nيمكنك أيضا حفظ مشروعك\n\n6\n00:00:18.450 --> 00:00:21.390\nعن طريق تحديد اسم المشروع في قائمة الأدوات.\n\n7\n00:00:21.390 --> 00:00:23.993\nكذلك, هذا سيسمح لك بإعادة تسمية مشروعك.\n\n8\n00:00:27.610 --> 00:00:29.770\nبمجرد حفظ مشروعك مبدئياً،\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 سيبقي مشروعك محفوظ في جميع الأوقات.\n\n10\n00:00:36.180 --> 00:00:38.150\nإذا نسيت الحفظ قبل الفتح\n\n11\n00:00:38.150 --> 00:00:39.423\nأو إنشاء مشروع مختلف،\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 سيسألك إذا كنت ترغب في الحفظ\n\n13\n00:00:42.580 --> 00:00:45.720\nللحفظ قبل الانتقال إلى\nإلى مشاريع مختلفة.\n\n14\n00:00:45.720 --> 00:00:48.110\nيمكنك أيضا تجاهل مشاريعك الغير محفوظة\n\n15\n00:00:48.110 --> 00:00:49.743\nإذا كنت لا ترغب في الحفظ.\n\n","cs":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Pro pojmenování svého projektu</v>\n\n2\n00:00:02.020 --> 00:00:05.713\notevři menu Soubor a vyber Uložit.\n\n3\n00:00:07.950 --> 00:00:09.970\nVyber umístění pro uložení tvého projektu\n\n4\n00:00:09.970 --> 00:00:13.393\na zvol si název, který tvůj projekt nejlépe popisuje.\n\n5\n00:00:17.030 --> 00:00:18.450\nSvůj projekt můžeš také uložit\n\n6\n00:00:18.450 --> 00:00:21.390\nvýběrem názvu projektu v panelu nástrojů.\n\n7\n00:00:21.390 --> 00:00:23.993\nTo ti také umožní přejmenovat svůj projekt.\n\n8\n00:00:27.610 --> 00:00:29.770\nJakmile je tvůj projekt alespoň jednou uložen,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 bude udržovat tvůj projekt uložený pořád.\n\n10\n00:00:36.180 --> 00:00:38.150\nJestliže zapomeneš na uložení před otevřením,\n\n11\n00:00:38.150 --> 00:00:39.423\nnebo vytvořením jiného projektu,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 se zeptá, jestli ho chceš\n\n13\n00:00:42.580 --> 00:00:45.720\nuložit, než přejdeš na své jiné projekty.\n\n14\n00:00:45.720 --> 00:00:48.110\nNeuložený projekt můžeš také zahodit,\n\n15\n00:00:48.110 --> 00:00:49.743\njestliže si nepřeješ ho uložit.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:07.950 --> 00:00:09.970\nSeleccione una ubicación en la que guardar su proyecto,\n\n4\n00:00:09.970 --> 00:00:13.393\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:17.030 --> 00:00:18.450\nTambién puede guardar su proyecto\n\n6\n00:00:18.450 --> 00:00:21.390\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:21.390 --> 00:00:23.993\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:27.610 --> 00:00:29.770\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:36.180 --> 00:00:38.150\nSi se olvida de guardar antes de abrir\n\n11\n00:00:38.150 --> 00:00:39.423\no crear un proyecto diferente\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 preguntará si desea\n\n13\n00:00:42.580 --> 00:00:45.720\nguardar antes de mover a sus diferentes proyectos.\n\n14\n00:00:45.720 --> 00:00:48.110\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:48.110 --> 00:00:49.743\nsi no desea guardar.\n\n","es":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:07.950 --> 00:00:09.970\nSeleccione una ubicación en la que guardar su proyecto,\n\n4\n00:00:09.970 --> 00:00:13.393\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:17.030 --> 00:00:18.450\nTambién puede guardar su proyecto\n\n6\n00:00:18.450 --> 00:00:21.390\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:21.390 --> 00:00:23.993\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:27.610 --> 00:00:29.770\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:36.180 --> 00:00:38.150\nSi se olvida de guardar antes de abrir\n\n11\n00:00:38.150 --> 00:00:39.423\no crear un proyecto diferente\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 preguntará si desea\n\n13\n00:00:42.580 --> 00:00:45.720\nguardar antes de mover a sus diferentes proyectos.\n\n14\n00:00:45.720 --> 00:00:48.110\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:48.110 --> 00:00:49.743\nsi no desea guardar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Halutessasi nimetä ohjelmasi</v>\n\n2\n00:00:02.020 --> 00:00:05.713\navaa Tiedosto alasvetovalikko ja valitse Tallenna.\n\n3\n00:00:07.950 --> 00:00:09.970\nValitse hakemisto, johon tallennat ohjelman\n\n4\n00:00:09.970 --> 00:00:13.393\nja nimeä ohjelmasi nimellä, joka parhaiten kuvaa sitä.\n\n5\n00:00:17.030 --> 00:00:18.450\nVoit myös nimetä ohjelmasi\n\n6\n00:00:18.450 --> 00:00:21.390\nkirjoittamalla ohjelman nimi työpalkkin nimikenttään.\n\n7\n00:00:21.390 --> 00:00:23.993\nVoit myös uudelleennimetä ohjelmasi työpalkin nimikentästä.\n\n8\n00:00:27.610 --> 00:00:29.770\nKun ohjelma on alussa nimetty,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 tallentaa ohjelmasi jatkuvasti.\n\n10\n00:00:36.180 --> 00:00:38.150\nKun avaat jonkun toisen ohjelman\n\n11\n00:00:38.150 --> 00:00:39.423\ntai luot uuden ohjelman\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 kysyy haluatko\n\n13\n00:00:42.580 --> 00:00:45.720\ntallentaa nykyisen ennen siirtymistä toiseen ohjelmaan.\n\n14\n00:00:45.720 --> 00:00:48.110\nVoit myös hylätä tallennuksen\n\n15\n00:00:48.110 --> 00:00:49.743\njos et halua tallentaa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Pour donner un nom à votre projet,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nouvrez le menu \"Fichier\" et sélectionnez \"Enregistrer\".\n\n3\n00:00:07.950 --> 00:00:09.970\nChoisissez l'emplacement dans lequel enregistrer votre projet\n\n4\n00:00:09.970 --> 00:00:13.393\net choisissez un nom qui décrit le mieux votre projet.\n\n5\n00:00:17.030 --> 00:00:18.450\nVous pouvez également enregistrer votre projet\n\n6\n00:00:18.450 --> 00:00:21.390\nen sélectionnant le nom du projet dans la barre d'outils.\n\n7\n00:00:21.390 --> 00:00:23.993\nCela vous permettra également de renommer votre projet.\n\n8\n00:00:27.610 --> 00:00:29.770\nUne fois le projet enregistré une première fois,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 enregistrera automatiquement les changements apportés à votre projet.\n\n10\n00:00:36.180 --> 00:00:38.150\nSi vous oubliez d'enregistrer votre projet avant d'ouvrir\n\n11\n00:00:38.150 --> 00:00:39.423\nou de créer un autre projet,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 vous demandera si vous souhaitez\n\n13\n00:00:42.580 --> 00:00:45.720\nenregistrer avant de continuer avec un autre projet.\n\n14\n00:00:45.720 --> 00:00:48.110\nVous pouvez également ignorer votre projet non sauvegardé\n\n15\n00:00:48.110 --> 00:00:49.743\nsi vous ne souhaitez pas l'enregistrer.\n\n","ko":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>프로젝트에 이름을 붙이려면</v>\n\n2\n00:00:02.020 --> 00:00:05.713\n파일 메뉴에서 '저장하기'를 선택하세요.\n\n3\n00:00:07.950 --> 00:00:09.970\n프로젝트를 저장할 위치를 선택하고\n\n4\n00:00:09.970 --> 00:00:13.393\n프로젝트를 가장 잘 설명하는 이름으로 저장합니다.\n\n5\n00:00:17.030 --> 00:00:18.450\n도구 모음에서 프로젝트 이름을 선택해\n\n6\n00:00:18.450 --> 00:00:21.390\n프로젝트를 저장할 수도 있습니다.\n\n7\n00:00:21.390 --> 00:00:23.993\n이 방법으로 프로젝트 이름 변경도 가능합니다.\n\n8\n00:00:27.610 --> 00:00:29.770\n프로젝트를 한 번 저장하면\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5는 프로젝트를 계속 저장합니다.\n\n10\n00:00:36.180 --> 00:00:38.150\n다른 프로젝트를 열거나 만들기 전에\n\n11\n00:00:38.150 --> 00:00:39.423\n저장하는 것을 잊었다면\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5는\n\n13\n00:00:42.580 --> 00:00:45.720\n다른 프로젝트를 하기 전에 저장할 것인지 묻습니다.\n\n14\n00:00:45.720 --> 00:00:48.110\n저장하지 않은 프로젝트를 저장하지 않으려면\n\n15\n00:00:48.110 --> 00:00:49.743\n삭제할 수도 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Norėdami pavadinti savo projektą,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\natidarykite bylų meniu ir spustelėkite \"Išsaugoti\".\n\n3\n00:00:07.950 --> 00:00:09.970\nPasirinkite vietą, kurioje išsaugosite savo projektą\n\n4\n00:00:09.970 --> 00:00:13.393\nir pasirinkite geriausiai Jūsų projektą apibūdinantį pavadinimą.\n\n5\n00:00:17.030 --> 00:00:18.450\nProjektą taip pat galite išsaugoti\n\n6\n00:00:18.450 --> 00:00:21.390\nparankinėje paspausdami ant jo pavadinimo.\n\n7\n00:00:21.390 --> 00:00:23.993\nTokiu būdu galite ir pervadinti savo projektą.\n\n8\n00:00:27.610 --> 00:00:29.770\nKai Jūsų projektas išsaugomas,\n\n9\n00:00:29.770 --> 00:00:33.433\nprograma \"VEXcode V5\" Jūsų projektą saugo visada.\n\n10\n00:00:36.180 --> 00:00:38.150\nJeigu prieš atidarydami arba\n\n11\n00:00:38.150 --> 00:00:39.423\nsukurdami kitą projektą pamirštate išsaugoti,\n\n12\n00:00:39.423 --> 00:00:42.580\nprograma \"VEXcode V5\" paklaus Jūsų, ar norėtumėte\n\n13\n00:00:42.580 --> 00:00:45.720\nišsaugoti prieš pereinant prie kitų projektų.\n\n14\n00:00:45.720 --> 00:00:48.110\nTaip pat galite atmesti savo neišsaugotą projektą,\n\n15\n00:00:48.110 --> 00:00:49.743\njeigu nenorite išsaugoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Narrator> Lai nosauktu savu projektu, </v>\n\n2\n00:00:02.020 --> 00:00:05.713\natveriet izvēlni “File”, un atlasiet “Save”.\n\n3\n00:00:07.950 --> 00:00:09.970\nAtlasiet vietu, kur saglabāt savu projektu,\n\n4\n00:00:09.970 --> 00:00:13.393\nun izvēlieties nosaukumu, kas vislabāk raksturo jūsu projektu.\n\n5\n00:00:17.030 --> 00:00:18.450\nJūs variet arī saglabāt savu projektu,\n\n6\n00:00:18.450 --> 00:00:21.390\natlasot projekta nosaukumu rīkjoslā.\n\n7\n00:00:21.390 --> 00:00:23.993\nKā arī šādi var arī pārdēvēt savu projektu.\n\n8\n00:00:27.610 --> 00:00:29.770\nKad projekts ir saglabāts,\n\n9\n00:00:29.770 --> 00:00:33.433\nprojekts programmā VEXcode V5 būs vienmēr saglabāts.\n\n10\n00:00:36.180 --> 00:00:38.150\nJa esat aizmirsis saglabāt pirms cita\n\n11\n00:00:38.150 --> 00:00:39.423\nprojekta atvēršanas vai izveidošanas,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 norādīs, vai nevēlaties\n\n13\n00:00:42.580 --> 00:00:45.720\nsaglabāt projektu pirms atvērsiet citu projektu.\n\n14\n00:00:45.720 --> 00:00:48.110\nVarat arī dzēst savu nesaglabāto projektu,\n\n15\n00:00:48.110 --> 00:00:49.743\nja nevēlaties to saglabāt.\n\n","nl":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Om uw project een naam te geven,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nopen het bestandsmenu en selecteer Opslaan.\n\n3\n00:00:07.950 --> 00:00:09.970\nKies een locatie om uw project in op te slaan\n\n4\n00:00:09.970 --> 00:00:13.393\nen kies een naam die uw project het beste beschrijft.\n\n5\n00:00:17.030 --> 00:00:18.450\nU kunt uw project ook opslaan\n\n6\n00:00:18.450 --> 00:00:21.390\ndoor de projectnaam in de werkbalk te selecteren.\n\n7\n00:00:21.390 --> 00:00:23.993\nHiermee kunt u ook uw project hernoemen.\n\n8\n00:00:27.610 --> 00:00:29.770\nZodra uw project in eerste instantie is opgeslagen,\n\n9\n00:00:29.770 --> 00:00:33.433\nbehoudt VEXcode V5 uw project te allen tijde opgeslagen.\n\n10\n00:00:36.180 --> 00:00:38.150\nAls u vergeet op te slaan voor het openen\n\n11\n00:00:38.150 --> 00:00:39.423\nof maakt u een ander project\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 zal vragen of u wilt opslaan\n\n13\n00:00:42.580 --> 00:00:45.720\nvoordat u verder gaat met een ander project.\n\n14\n00:00:45.720 --> 00:00:48.110\nU kunt ook uw niet-opgeslagen project verwijderen\n\n15\n00:00:48.110 --> 00:00:49.743\nals u het niet wilt bewaren.\n\n","pl":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Aby nadać nazwę projektowi,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\notwórz menu pliku i wybierz Zapisz.\n\n3\n00:00:07.950 --> 00:00:09.970\nWybierz lokalizację, w której chcesz zapisać swój projekt\n\n4\n00:00:09.970 --> 00:00:13.393\nwybierz nazwę, która najlepiej opisuje twój projekt.\n\n5\n00:00:17.030 --> 00:00:18.450\nMożesz również zapisać swój projekt\n\n6\n00:00:18.450 --> 00:00:21.390\nwybierając nazwę projektu na pasku narzędzi.\n\n7\n00:00:21.390 --> 00:00:23.993\nPozwoli to również na zmianę nazwy projektu.\n\n8\n00:00:27.610 --> 00:00:29.770\nGdy Twój projekt zostanie początkowo zapisany,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 będzie zawsze zapisywać Twój projekt.\n\n10\n00:00:36.180 --> 00:00:38.150\nJeśli zapomnisz zapisać przed otwarciem\n\n11\n00:00:38.150 --> 00:00:39.423\nlub tworząc inny projekt\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 zapyta cię czy chcesz\n\n13\n00:00:42.580 --> 00:00:45.720\nzapisać go zanim przejdziesz do innego projektu.\n\n14\n00:00:45.720 --> 00:00:48.110\nMożesz również odrzucić swój niezapisany projekt\n\n15\n00:00:48.110 --> 00:00:49.743\njeśli nie chcesz zapisywać.\n\n","ru":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Для назначения имени проекта</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nоткройте меню \"Файл\" и выберите \"Сохранить\".\n\n3\n00:00:07.950 --> 00:00:09.970\nВыберите место сохранения файла\n\n4\n00:00:09.970 --> 00:00:13.393\nи имя, которое лучше всего описывает содержание проекта.\n\n5\n00:00:17.030 --> 00:00:18.450\nВы также можете сохранить проект,\n\n6\n00:00:18.450 --> 00:00:21.390\nвыбрав имя проекта на панели управления.\n\n7\n00:00:21.390 --> 00:00:23.993\nЭто также позволит переименовать проект.\n\n8\n00:00:27.610 --> 00:00:29.770\nПосле сохранения проекта,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 постоянно сохраняет проект во время работы.\n\n10\n00:00:36.180 --> 00:00:38.150\nЕсли вы забыли сохраниться перед открытием\n\n11\n00:00:38.150 --> 00:00:39.423\nили созданием проекта,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 предложит вам сохранить проект,\n\n13\n00:00:42.580 --> 00:00:45.720\nперед использованием следующего проекта.\n\n14\n00:00:45.720 --> 00:00:48.110\nВы можете отменить изменения в проекте,\n\n15\n00:00:48.110 --> 00:00:49.743\nесли не хотите сохраняться.\n\n","th":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>ในการตั้งชื่อโปรเจ็คของคุณ,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nคุณสามารถเปิดเมนู File และเลือก Save\n\n3\n00:00:07.950 --> 00:00:09.970\nเลือกตำแหน่งเพื่อบันทึกโปรเจ็คของคุณ\n\n4\n00:00:09.970 --> 00:00:13.393\nและตั้งชื่อที่ตรงกับโปรเจ็คของคุณมากที่สุด\n\n5\n00:00:17.030 --> 00:00:18.450\nคุณยังสามารถบันทึกโครงการของคุณ\n\n6\n00:00:18.450 --> 00:00:21.390\nโดยเลือกชื่อโครงการในแถบเครื่องมือ\n\n7\n00:00:21.390 --> 00:00:23.993\nซึ่งจะช่วยให้คุณสามารถเปลี่ยนชื่อโครงการของคุณได้เช่นกัน\n\n8\n00:00:27.610 --> 00:00:29.770\nเมื่อโครงการของคุณได้รับการบันทึกในขั้นต้น\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 จะบันทึกโครงการของคุณไว้ตลอดเวลา\n\n10\n00:00:36.180 --> 00:00:38.150\nหากลืมบันทึกก่อนเปิด\n\n11\n00:00:38.150 --> 00:00:39.423\nหรือสร้างโปรเจ็คอื่น\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 จะถามว่าคุณต้องการบันทึกหรือไม่\n\n13\n00:00:42.580 --> 00:00:45.720\nก่อนที่คุณจะย้ายไปยังโปรเจ็คอื่น\n\n14\n00:00:45.720 --> 00:00:48.110\nคุณยังสามารถยกเลิกโปรเจ็กต์ที่ยังไม่ได้บันทึกของคุณได้\n\n15\n00:00:48.110 --> 00:00:49.743\nหากคุณไม่ต้องการบันทึก\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Щоб назвати проєкт,</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nвідкрийте меню \"Файл\" і виберіть \"Зберегти\".\n\n3\n00:00:07.950 --> 00:00:09.970\nВиберіть місце збереження проєкту\n\n4\n00:00:09.970 --> 00:00:13.393\nі оберіть ім'я, яке найкраще опише проєкт.\n\n5\n00:00:17.030 --> 00:00:18.450\nТакож ви можете зберегти проєкт,\n\n6\n00:00:18.450 --> 00:00:21.390\nобравши ім'я проєкту на панелі інструментів.\n\n7\n00:00:21.390 --> 00:00:23.993\nЦе дасть вам змогу і перейменувати збережений проєкт.\n\n8\n00:00:27.610 --> 00:00:29.770\nЩойно проєкт буде збережено вперше,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 зберігатиме цей проєкт постійно.\n\n10\n00:00:36.180 --> 00:00:38.150\nЯкщо ви забудете зберегти проєкт перед запуском\n\n11\n00:00:38.150 --> 00:00:39.423\nабо створенням іншого проєкту,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 запитає, чи треба зберегти\n\n13\n00:00:42.580 --> 00:00:45.720\nзберегти наявний проєкт перед переходом до нового.\n\n14\n00:00:45.720 --> 00:00:48.110\nВи також можете відхилити незбережений проєкт,\n\n15\n00:00:48.110 --> 00:00:49.743\nякщо не хочете його зберігати.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>Để đặt tên cho dự án của bạn, hãy</v>\n\n2\n00:00:02.020 --> 00:00:05.713\nmở menu Tệp và chọn Lưu.\n\n3\n00:00:07.950 --> 00:00:09.970\nChọn một vị trí để lưu dự án của bạn\n\n4\n00:00:09.970 --> 00:00:13.393\nvà chọn một tên mô tả tốt nhất dự án của bạn.\n\n5\n00:00:17.030 --> 00:00:18.450\nBạn cũng có thể lưu dự án của mình\n\n6\n00:00:18.450 --> 00:00:21.390\nbằng cách chọn tên dự án trên thanh công cụ.\n\n7\n00:00:21.390 --> 00:00:23.993\nĐiều này cũng sẽ cho phép bạn đổi tên dự án của mình.\n\n8\n00:00:27.610 --> 00:00:29.770\nSau khi dự án của bạn được lưu lần đầu,\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5 sẽ luôn lưu dự án của bạn.\n\n10\n00:00:36.180 --> 00:00:38.150\nNếu bạn quên lưu trước khi mở\n\n11\n00:00:38.150 --> 00:00:39.423\nhoặc tạo một dự án khác,\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5 sẽ hỏi bạn nếu bạn muốn\n\n13\n00:00:42.580 --> 00:00:45.720\nđể tiết kiệm trước khi bạn chuyển sang các dự án khác nhau của mình.\n\n14\n00:00:45.720 --> 00:00:48.110\nBạn cũng có thể hủy dự án chưa lưu của mình\n\n15\n00:00:48.110 --> 00:00:49.743\nnếu bạn không muốn tiết kiệm.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\ncrwdns96326:0crwdne96326:0\n\n2\n00:00:02.020 --> 00:00:05.713\ncrwdns96328:0crwdne96328:0\n\n3\n00:00:07.950 --> 00:00:09.970\ncrwdns96330:0crwdne96330:0\n\n4\n00:00:09.970 --> 00:00:13.393\ncrwdns96332:0crwdne96332:0\n\n5\n00:00:17.030 --> 00:00:18.450\ncrwdns96334:0crwdne96334:0\n\n6\n00:00:18.450 --> 00:00:21.390\ncrwdns96336:0crwdne96336:0\n\n7\n00:00:21.390 --> 00:00:23.993\ncrwdns96338:0crwdne96338:0\n\n8\n00:00:27.610 --> 00:00:29.770\ncrwdns96340:0crwdne96340:0\n\n9\n00:00:29.770 --> 00:00:33.433\ncrwdns96342:0crwdne96342:0\n\n10\n00:00:36.180 --> 00:00:38.150\ncrwdns96344:0crwdne96344:0\n\n11\n00:00:38.150 --> 00:00:39.423\ncrwdns96346:0crwdne96346:0\n\n12\n00:00:39.423 --> 00:00:42.580\ncrwdns96348:0crwdne96348:0\n\n13\n00:00:42.580 --> 00:00:45.720\ncrwdns96350:0crwdne96350:0\n\n14\n00:00:45.720 --> 00:00:48.110\ncrwdns96352:0crwdne96352:0\n\n15\n00:00:48.110 --> 00:00:49.743\ncrwdns96354:0crwdne96354:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:02.020\n<v Instructor>欲给您的程序命名，</v>\n\n2\n00:00:02.020 --> 00:00:05.713\n打开“文件”菜单并选择“保存”。\n\n3\n00:00:07.950 --> 00:00:09.970\n选择一个位置来保存您的程序\n\n4\n00:00:09.970 --> 00:00:13.393\n并选择一个最能描述该程序的名称。\n\n5\n00:00:17.030 --> 00:00:18.450\n您也可以保存您的项目\n\n6\n00:00:18.450 --> 00:00:21.390\n通过选中工具栏的程序名称。\n\n7\n00:00:21.390 --> 00:00:23.993\n这也将允许您重命名程序。\n\n8\n00:00:27.610 --> 00:00:29.770\n一旦您的程序初始保存后，\n\n9\n00:00:29.770 --> 00:00:33.433\nVEXcode V5将保持您的程序随时保存。\n\n10\n00:00:36.180 --> 00:00:38.150\n如果您在打开\n\n11\n00:00:38.150 --> 00:00:39.423\n或者创建一个不同的程序之前忘记保存，\n\n12\n00:00:39.423 --> 00:00:42.580\nVEXcode V5将询问您是否想要\n\n13\n00:00:42.580 --> 00:00:45.720\n在去到不同程序之前时保存。\n\n14\n00:00:45.720 --> 00:00:48.110\n您也可以放弃未保存程序\n\n15\n00:00:48.110 --> 00:00:49.743\n如果您不希望保存的话。\n\n"}},{"thumb":"V5_Tutorial_nameAndSave.jpg","mov":"V5_Blocks_NamingandSavingProjects_PC_V2","description":"Naming and Saving Your Project (Windows)","filter":"","placeholder":false,"platform":["Windows"],"vimeo":"475900542","proglang":["blocks","python","cpp"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>To give your project a name,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nopen the File menu, and select Save.\n\n3\n00:00:09.110 --> 00:00:11.563\nSelect a location to save your project in,\n\n4\n00:00:12.820 --> 00:00:15.603\nand choose a name that best describes your project.\n\n5\n00:00:19.410 --> 00:00:20.820\nYou can also save your project\n\n6\n00:00:20.820 --> 00:00:23.463\nby selecting the project name in the toolbar.\n\n7\n00:00:25.610 --> 00:00:28.203\nThis will allow you to rename your project as well.\n\n8\n00:00:32.290 --> 00:00:34.420\nOnce your project is initially saved,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 will keep your project saved at all times.\n\n10\n00:00:40.270 --> 00:00:42.240\nIf you forget to save before opening\n\n11\n00:00:42.240 --> 00:00:44.470\nor creating a different project,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 will ask you if you would like to save\n\n13\n00:00:47.440 --> 00:00:49.773\nbefore you move on to your different projects.\n\n14\n00:00:51.060 --> 00:00:53.460\nYou can also discard your unsaved project\n\n15\n00:00:53.460 --> 00:00:55.103\nif you do not wish to save.\n\n","ar":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>لإعطاء المشروع الخاص بك اسما،</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nافتح قائمة الملفات وحدد \"حفظ\".\n\n3\n00:00:09.110 --> 00:00:11.563\nحدد موقع لحفظ مشروعك,\n\n4\n00:00:12.820 --> 00:00:15.603\nواختر اسم يصف مشروعك بشكل جيد.\n\n5\n00:00:19.410 --> 00:00:20.820\nيمكنك أيضا حفظ مشروعك\n\n6\n00:00:20.820 --> 00:00:23.463\nعن طريق تحديد اسم المشروع في قائمة الأدوات.\n\n7\n00:00:25.610 --> 00:00:28.203\nكذلك, هذا سيسمح لك بإعادة تسمية مشروعك.\n\n8\n00:00:32.290 --> 00:00:34.420\nبمجرد حفظ مشروعك مبدئياً،\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 سيبقي مشروعك محفوظ في جميع الأوقات.\n\n10\n00:00:40.270 --> 00:00:42.240\nإذا نسيت الحفظ قبل الفتح\n\n11\n00:00:42.240 --> 00:00:44.470\nأو إنشاء مشروع مختلف،\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 سيسألك إذا كنت ترغب في الحفظ\n\n13\n00:00:47.440 --> 00:00:49.773\nقبل أن تنتقل إلى مشاريعك المختلفة.\n\n14\n00:00:51.060 --> 00:00:53.460\nيمكنك أيضا تجاهل مشاريعك الغير محفوظة\n\n15\n00:00:53.460 --> 00:00:55.103\nإذا كنت لا ترغب في الحفظ.\n\n","cs":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Pro pojmenování svého projektu</v>\n\n2\n00:00:01.940 --> 00:00:06.033\notevři menu Soubor a vyber Uložit.\n\n3\n00:00:09.110 --> 00:00:11.563\nVyber umístění pro uložení projektu\n\n4\n00:00:12.820 --> 00:00:15.603\na zvol si název, který tvůj projekt nejlépe popisuje.\n\n5\n00:00:19.410 --> 00:00:20.820\nSvůj projekt můžeš také uložit\n\n6\n00:00:20.820 --> 00:00:23.463\nvýběrem názvu projektu v panelu nástrojů.\n\n7\n00:00:25.610 --> 00:00:28.203\nTo ti také umožní přejmenovat svůj projekt.\n\n8\n00:00:32.290 --> 00:00:34.420\nJakmile je tvůj projekt alespoň jednou uložen,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 bude udržovat tvůj projekt uložený pořád.\n\n10\n00:00:40.270 --> 00:00:42.240\nJestliže zapomeneš na uložení před otevřením,\n\n11\n00:00:42.240 --> 00:00:44.470\nnebo vytvořením jiného projektu,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 se zeptá, jestli ho chceš uložit,\n\n13\n00:00:47.440 --> 00:00:49.773\nnež přejdeš na své jiné projekty.\n\n14\n00:00:51.060 --> 00:00:53.460\nNeuložený projekt můžeš také zahodit,\n\n15\n00:00:53.460 --> 00:00:55.103\njestliže si nepřeješ ho uložit.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:09.110 --> 00:00:11.563\nSeleccione una ubicación en la que guardar su proyecto\n\n4\n00:00:12.820 --> 00:00:15.603\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:19.410 --> 00:00:20.820\nTambién puede guardar su proyecto\n\n6\n00:00:20.820 --> 00:00:23.463\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:25.610 --> 00:00:28.203\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:32.290 --> 00:00:34.420\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:40.270 --> 00:00:42.240\nSi se olvida de guardar antes de abrir\n\n11\n00:00:42.240 --> 00:00:44.470\no crear un proyecto diferente\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 preguntará si desea guardar\n\n13\n00:00:47.440 --> 00:00:49.773\nantes de pasar a otro proyecto.\n\n14\n00:00:51.060 --> 00:00:53.460\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:53.460 --> 00:00:55.103\nsi no desea guardar.\n\n","es":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:09.110 --> 00:00:11.563\nSeleccione una ubicación en la que guardar su proyecto\n\n4\n00:00:12.820 --> 00:00:15.603\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:19.410 --> 00:00:20.820\nTambién puede guardar su proyecto\n\n6\n00:00:20.820 --> 00:00:23.463\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:25.610 --> 00:00:28.203\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:32.290 --> 00:00:34.420\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:40.270 --> 00:00:42.240\nSi se olvida de guardar antes de abrir\n\n11\n00:00:42.240 --> 00:00:44.470\no crear un proyecto diferente\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 preguntará si desea guardar\n\n13\n00:00:47.440 --> 00:00:49.773\nantes de pasar a otro proyecto.\n\n14\n00:00:51.060 --> 00:00:53.460\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:53.460 --> 00:00:55.103\nsi no desea guardar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Ohjelmasi nimeämiseen</v>\n\n2\n00:00:01.940 --> 00:00:06.033\navaa Tiedosto alasvetovalikko ja valitse Tallenna.\n\n3\n00:00:09.110 --> 00:00:11.563\nValitse kansio, johon tallennat ohjelmasi\n\n4\n00:00:12.820 --> 00:00:15.603\nja valitse paras ohjelmaa kuvaava nimi.\n\n5\n00:00:19.410 --> 00:00:20.820\nVoit myös nimetä ohjelmasi\n\n6\n00:00:20.820 --> 00:00:23.463\nkirjoittamalla ohjelman nimi työpalkkin nimikenttään.\n\n7\n00:00:25.610 --> 00:00:28.203\nVoit myös uudelleennimetä ohjelmasi työpalkin nimikentästä.\n\n8\n00:00:32.290 --> 00:00:34.420\nKun ohjelma on alussa nimetty\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 tallentaa ohjelmasi jatkuvasti.\n\n10\n00:00:40.270 --> 00:00:42.240\nKun avaat jonkun toisen ohjelman\n\n11\n00:00:42.240 --> 00:00:44.470\ntai luot uuden ohjelman\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 kysyy haluatko tallentaa\n\n13\n00:00:47.440 --> 00:00:49.773\nennen toiseen ohjelmaan siirtymistä.\n\n14\n00:00:51.060 --> 00:00:53.460\nVoit myös hylätä tallennuksen\n\n15\n00:00:53.460 --> 00:00:55.103\njos et halua tallentaa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Pour donner un nom à votre projet,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nouvrez le menu \"Fichier\" et sélectionnez \"Enregistrer\".\n\n3\n00:00:09.110 --> 00:00:11.563\nSélectionnez un emplacement où enregistrer votre projet,\n\n4\n00:00:12.820 --> 00:00:15.603\net choisissez un nom qui décrit le mieux votre projet.\n\n5\n00:00:19.410 --> 00:00:20.820\nVous pouvez également enregistrer votre projet\n\n6\n00:00:20.820 --> 00:00:23.463\nen sélectionnant le nom du projet dans la barre d'outils.\n\n7\n00:00:25.610 --> 00:00:28.203\nCela vous permettra également de renommer votre projet.\n\n8\n00:00:32.290 --> 00:00:34.420\nUne fois le projet enregistré une première fois,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 enregistrera automatiquement les changements apportés à votre projet.\n\n10\n00:00:40.270 --> 00:00:42.240\nSi vous oubliez d'enregistrer votre projet avant d'ouvrir\n\n11\n00:00:42.240 --> 00:00:44.470\nou de créer un autre projet,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 vous demandera si vous souhaitez enregistrer\n\n13\n00:00:47.440 --> 00:00:49.773\navant de continuer avec un autre projet.\n\n14\n00:00:51.060 --> 00:00:53.460\nVous pouvez également ignorer votre projet non sauvegardé\n\n15\n00:00:53.460 --> 00:00:55.103\nsi vous ne souhaitez pas l'enregistrer.\n\n","ko":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>프로젝트에 이름을 붙이려면</v>\n\n2\n00:00:01.940 --> 00:00:06.033\n파일 메뉴에서 '저장하기'를 선택하세요.\n\n3\n00:00:09.110 --> 00:00:11.563\n프로젝트를 저장할 위치를 선택하고\n\n4\n00:00:12.820 --> 00:00:15.603\n프로젝트를 가장 잘 설명하는 이름으로 저장합니다.\n\n5\n00:00:19.410 --> 00:00:20.820\n도구 모음에서 프로젝트 이름을 선택해\n\n6\n00:00:20.820 --> 00:00:23.463\n프로젝트를 저장할 수도 있습니다.\n\n7\n00:00:25.610 --> 00:00:28.203\n이 방법으로 프로젝트 이름 변경도 가능합니다.\n\n8\n00:00:32.290 --> 00:00:34.420\n프로젝트를 한 번 저장하면\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5는 프로젝트를 계속 저장합니다.\n\n10\n00:00:40.270 --> 00:00:42.240\n다른 프로젝트를 열거나 만들기 전에\n\n11\n00:00:42.240 --> 00:00:44.470\n저장하는 것을 잊었다면\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5는\n\n13\n00:00:47.440 --> 00:00:49.773\n다른 프로젝트를 하기 전에 저장할 것인지 묻습니다.\n\n14\n00:00:51.060 --> 00:00:53.460\n저장하지 않은 프로젝트를 저장하지 않으려면\n\n15\n00:00:53.460 --> 00:00:55.103\n삭제할 수도 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Norėdami pavadinti savo projektą,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\natidarykite bylų meniu ir spustelėkite \"Išsaugoti\".\n\n3\n00:00:09.110 --> 00:00:11.563\nPasirinkite vietą, kurioje išsaugosite savo projektą,\n\n4\n00:00:12.820 --> 00:00:15.603\nir geriausiai Jūsų projektą apibūdinantį pavadinimą.\n\n5\n00:00:19.410 --> 00:00:20.820\nProjektą taip pat galite išsaugoti\n\n6\n00:00:20.820 --> 00:00:23.463\nparankinėje paspausdami ant jo pavadinimo.\n\n7\n00:00:25.610 --> 00:00:28.203\nTokiu būdu galite ir pervadinti savo projektą.\n\n8\n00:00:32.290 --> 00:00:34.420\nKai Jūsų projektas išsaugomas,\n\n9\n00:00:34.420 --> 00:00:38.103\nprograma \"VEXcode V5\" Jūsų projektą saugo visada.\n\n10\n00:00:40.270 --> 00:00:42.240\nJeigu prieš atidarydami arba\n\n11\n00:00:42.240 --> 00:00:44.470\nsukurdami kitą projektą pamirštate išsaugoti,\n\n12\n00:00:44.470 --> 00:00:47.440\nprograma \"VEXcode V5\" paklaus Jūsų, ar norėtumėte išsaugoti\n\n13\n00:00:47.440 --> 00:00:49.773\nprieš pereinant prie kitų projektų.\n\n14\n00:00:51.060 --> 00:00:53.460\nTaip pat galite atmesti savo neišsaugotą projektą,\n\n15\n00:00:53.460 --> 00:00:55.103\njeigu nenorite išsaugoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Lai nosauktu savu projektu,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\natveriet izvēlni “File”, un atlasiet “Save”.\n\n3\n00:00:09.110 --> 00:00:11.563\nAtlasiet vietu, kur saglabāt savu projektu,\n\n4\n00:00:12.820 --> 00:00:15.603\nun izvēlieties nosaukumu, kas vislabāk raksturo jūsu projektu.\n\n5\n00:00:19.410 --> 00:00:20.820\nJūs variet arī saglabāt savu projektu,\n\n6\n00:00:20.820 --> 00:00:23.463\natlasot projekta nosaukumu rīkjoslā.\n\n7\n00:00:25.610 --> 00:00:28.203\nKā arī šādi var arī pārdēvēt savu projektu.\n\n8\n00:00:32.290 --> 00:00:34.420\nKad projekts ir saglabāts,\n\n9\n00:00:34.420 --> 00:00:38.103\nprojekts programmā VEXcode V5 būs vienmēr saglabāts.\n\n10\n00:00:40.270 --> 00:00:42.240\nJa esat aizmirsis saglabāt pirms cita\n\n11\n00:00:42.240 --> 00:00:44.470\nprojekta atvēršanas vai izveidošanas,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 norādīs, vai nevēlaties saglabāt\n\n13\n00:00:47.440 --> 00:00:49.773\nprojektu pirms atvērsiet citu projektu.\n\n14\n00:00:51.060 --> 00:00:53.460\nVarat arī dzēst savu nesaglabāto projektu,\n\n15\n00:00:53.460 --> 00:00:55.103\nja nevēlaties to saglabāt.\n\n","nl":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Om uw project een naam te geven,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nopen het bestandsmenu en selecteer Opslaan.\n\n3\n00:00:09.110 --> 00:00:11.563\nKies een locatie om uw project in op te slaan,\n\n4\n00:00:12.820 --> 00:00:15.603\nen kies een naam die je project het beste beschrijft.\n\n5\n00:00:19.410 --> 00:00:20.820\nU kunt uw project ook opslaan\n\n6\n00:00:20.820 --> 00:00:23.463\ndoor de projectnaam in de werkbalk te selecteren.\n\n7\n00:00:25.610 --> 00:00:28.203\nHiermee kunt u ook uw project hernoemen.\n\n8\n00:00:32.290 --> 00:00:34.420\nZodra uw project in eerste instantie is opgeslagen,\n\n9\n00:00:34.420 --> 00:00:38.103\nbehoudt VEXcode V5 uw project te allen tijde opgeslagen.\n\n10\n00:00:40.270 --> 00:00:42.240\nAls u vergeet op te slaan voor het openen\n\n11\n00:00:42.240 --> 00:00:44.470\nof maakt u een ander project\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 zal vragen of u wilt opslaan\n\n13\n00:00:47.440 --> 00:00:49.773\nvoordat u verder gaat met een ander project.\n\n14\n00:00:51.060 --> 00:00:53.460\nU kunt ook uw niet-opgeslagen project verwijderen\n\n15\n00:00:53.460 --> 00:00:55.103\nals u het niet wilt bewaren.\n\n","pl":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Aby nadać nazwę projektowi,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\notwórz menu pliku i wybierz Zapisz.\n\n3\n00:00:09.110 --> 00:00:11.563\nWybierz lokalizację, w której chcesz zapisać swój projekt\n\n4\n00:00:12.820 --> 00:00:15.603\nwybierz nazwę, która najlepiej opisuje twój projekt.\n\n5\n00:00:19.410 --> 00:00:20.820\nMożesz również zapisać swój projekt\n\n6\n00:00:20.820 --> 00:00:23.463\nwybierając nazwę projektu na pasku narzędzi.\n\n7\n00:00:25.610 --> 00:00:28.203\nPozwoli to również na zmianę nazwy projektu.\n\n8\n00:00:32.290 --> 00:00:34.420\nGdy Twój projekt zostanie początkowo zapisany,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 będzie zawsze zapisywać Twój projekt.\n\n10\n00:00:40.270 --> 00:00:42.240\nJeśli zapomnisz zapisać przed otwarciem\n\n11\n00:00:42.240 --> 00:00:44.470\nlub tworząc inny projekt\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 zapyta czy chcesz go zapisać\n\n13\n00:00:47.440 --> 00:00:49.773\nzanim przejdziesz do innego projektu.\n\n14\n00:00:51.060 --> 00:00:53.460\nMożesz również odrzucić swój niezapisany projekt\n\n15\n00:00:53.460 --> 00:00:55.103\njeśli nie chcesz zapisywać.\n\n","ru":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Чтобы дать имя вашему проекту,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nоткройте меню \"Файл\" и выберите \"Сохранить\".\n\n3\n00:00:09.110 --> 00:00:11.563\nВыберите место сохранения проекта\n\n4\n00:00:12.820 --> 00:00:15.603\nи имя, которое лучше всего описывает содержание проекта.\n\n5\n00:00:19.410 --> 00:00:20.820\nВы также можете сохранить проект,\n\n6\n00:00:20.820 --> 00:00:23.463\nвыбрав имя проекта на панели управления.\n\n7\n00:00:25.610 --> 00:00:28.203\nЭто также позволит переименовать проект.\n\n8\n00:00:32.290 --> 00:00:34.420\nПосле сохранения проекта,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 постоянно сохраняет проект во время работы.\n\n10\n00:00:40.270 --> 00:00:42.240\nЕсли вы забыли сохраниться перед открытием\n\n11\n00:00:42.240 --> 00:00:44.470\nили созданием проекта,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 предложит вам сохранить проект,\n\n13\n00:00:47.440 --> 00:00:49.773\nперед использованием следующего проекта.\n\n14\n00:00:51.060 --> 00:00:53.460\nВы можете отменить изменения в проекте,\n\n15\n00:00:53.460 --> 00:00:55.103\nесли не хотите сохраняться.\n\n","th":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>ในการตั้งชื่อโปรเจ็คของคุณ,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nคุณสามารถเปิดเมนู File และเลือก Save\n\n3\n00:00:09.110 --> 00:00:11.563\nเลือกตำแหน่งเพื่อบันทึกโปรเจ็คของคุณ\n\n4\n00:00:12.820 --> 00:00:15.603\nและเลือกชื่อที่ตรงกับโปรเจ็คของคุณมากที่สุด\n\n5\n00:00:19.410 --> 00:00:20.820\nคุณยังสามารถบันทึกโครงการของคุณ\n\n6\n00:00:20.820 --> 00:00:23.463\nโดยเลือกชื่อโครงการในแถบเครื่องมือ\n\n7\n00:00:25.610 --> 00:00:28.203\nซึ่งจะช่วยให้คุณสามารถเปลี่ยนชื่อโครงการของคุณได้เช่นกัน\n\n8\n00:00:32.290 --> 00:00:34.420\nเมื่อโครงการของคุณได้รับการบันทึกในขั้นต้น\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 จะบันทึกโครงการของคุณไว้ตลอดเวลา\n\n10\n00:00:40.270 --> 00:00:42.240\nหากลืมบันทึกก่อนเปิด\n\n11\n00:00:42.240 --> 00:00:44.470\nหรือสร้างโปรเจ็คอื่น\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 จะถามว่าคุณต้องการบันทึกหรือไม่\n\n13\n00:00:47.440 --> 00:00:49.773\nก่อนที่คุณจะย้ายไปยังโปรเจ็คอื่น\n\n14\n00:00:51.060 --> 00:00:53.460\nคุณยังสามารถยกเลิกโปรเจ็กต์ที่ยังไม่ได้บันทึกของคุณได้\n\n15\n00:00:53.460 --> 00:00:55.103\nหากคุณไม่ต้องการบันทึก\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Щоб назвати проєкт,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nвідкрийте меню \"Файл\" і виберіть \"Зберегти\".\n\n3\n00:00:09.110 --> 00:00:11.563\nВиберіть місце збереження проєкту,\n\n4\n00:00:12.820 --> 00:00:15.603\nі оберіть ім'я, яке найкраще опише проєкт.\n\n5\n00:00:19.410 --> 00:00:20.820\nТакож ви можете зберегти проєкт,\n\n6\n00:00:20.820 --> 00:00:23.463\nобравши ім'я проєкту на панелі інструментів.\n\n7\n00:00:25.610 --> 00:00:28.203\nЦе дасть вам змогу і перейменувати збережений проєкт.\n\n8\n00:00:32.290 --> 00:00:34.420\nЩойно проєкт буде збережено вперше,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 зберігатиме цей проєкт постійно.\n\n10\n00:00:40.270 --> 00:00:42.240\nЯкщо ви забудете зберегти проєкт перед запуском\n\n11\n00:00:42.240 --> 00:00:44.470\nабо створенням іншого проєкту,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 запитає, чи треба зберегти\n\n13\n00:00:47.440 --> 00:00:49.773\nнаявний проєкт перед переходом до нового.\n\n14\n00:00:51.060 --> 00:00:53.460\nВи також можете відхилити незбережений проєкт,\n\n15\n00:00:53.460 --> 00:00:55.103\nякщо не хочете його зберігати.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>Để đặt tên cho dự án của bạn, hãy</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nmở menu Tệp và chọn Lưu.\n\n3\n00:00:09.110 --> 00:00:11.563\nChọn một vị trí để lưu dự án của bạn vào,\n\n4\n00:00:12.820 --> 00:00:15.603\nvà chọn một cái tên mô tả tốt nhất dự án của bạn.\n\n5\n00:00:19.410 --> 00:00:20.820\nBạn cũng có thể lưu dự án của mình\n\n6\n00:00:20.820 --> 00:00:23.463\nbằng cách chọn tên dự án trên thanh công cụ.\n\n7\n00:00:25.610 --> 00:00:28.203\nĐiều này cũng sẽ cho phép bạn đổi tên dự án của mình.\n\n8\n00:00:32.290 --> 00:00:34.420\nSau khi dự án của bạn được lưu lần đầu,\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5 sẽ luôn lưu dự án của bạn.\n\n10\n00:00:40.270 --> 00:00:42.240\nNếu bạn quên lưu trước khi mở\n\n11\n00:00:42.240 --> 00:00:44.470\nhoặc tạo một dự án khác,\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5 sẽ hỏi bạn có muốn lưu không\n\n13\n00:00:47.440 --> 00:00:49.773\ntrước khi bạn chuyển sang các dự án khác nhau của mình.\n\n14\n00:00:51.060 --> 00:00:53.460\nBạn cũng có thể hủy dự án chưa lưu của mình\n\n15\n00:00:53.460 --> 00:00:55.103\nnếu bạn không muốn tiết kiệm.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\ncrwdns96386:0crwdne96386:0\n\n2\n00:00:01.940 --> 00:00:06.033\ncrwdns96388:0crwdne96388:0\n\n3\n00:00:09.110 --> 00:00:11.563\ncrwdns96390:0crwdne96390:0\n\n4\n00:00:12.820 --> 00:00:15.603\ncrwdns96392:0crwdne96392:0\n\n5\n00:00:19.410 --> 00:00:20.820\ncrwdns96394:0crwdne96394:0\n\n6\n00:00:20.820 --> 00:00:23.463\ncrwdns96396:0crwdne96396:0\n\n7\n00:00:25.610 --> 00:00:28.203\ncrwdns96398:0crwdne96398:0\n\n8\n00:00:32.290 --> 00:00:34.420\ncrwdns96400:0crwdne96400:0\n\n9\n00:00:34.420 --> 00:00:38.103\ncrwdns96402:0crwdne96402:0\n\n10\n00:00:40.270 --> 00:00:42.240\ncrwdns96404:0crwdne96404:0\n\n11\n00:00:42.240 --> 00:00:44.470\ncrwdns96406:0crwdne96406:0\n\n12\n00:00:44.470 --> 00:00:47.440\ncrwdns96408:0crwdne96408:0\n\n13\n00:00:47.440 --> 00:00:49.773\ncrwdns96410:0crwdne96410:0\n\n14\n00:00:51.060 --> 00:00:53.460\ncrwdns96412:0crwdne96412:0\n\n15\n00:00:53.460 --> 00:00:55.103\ncrwdns96414:0crwdne96414:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator>欲给您的程序命名，</v>\n\n2\n00:00:01.940 --> 00:00:06.033\n打开“文件”菜单并选择“保存”。\n\n3\n00:00:09.110 --> 00:00:11.563\n选择一个地点以保存您的程序，\n\n4\n00:00:12.820 --> 00:00:15.603\n并选择一个最能描述您项目的名称。\n\n5\n00:00:19.410 --> 00:00:20.820\n您也可以保存您的项目\n\n6\n00:00:20.820 --> 00:00:23.463\n通过选中工具栏的程序名称。\n\n7\n00:00:25.610 --> 00:00:28.203\n这也将允许您重命名程序。\n\n8\n00:00:32.290 --> 00:00:34.420\n一旦您的程序初始保存后，\n\n9\n00:00:34.420 --> 00:00:38.103\nVEXcode V5将保持您的程序随时保存。\n\n10\n00:00:40.270 --> 00:00:42.240\n如果您在打开\n\n11\n00:00:42.240 --> 00:00:44.470\n或者创建一个不同的程序之前忘记保存，\n\n12\n00:00:44.470 --> 00:00:47.440\nVEXcode V5将询问您是否想要\n\n13\n00:00:47.440 --> 00:00:49.773\n在去到不同程序之前时保存。\n\n14\n00:00:51.060 --> 00:00:53.460\n您也可以放弃未保存程序\n\n15\n00:00:53.460 --> 00:00:55.103\n如果您不希望保存的话。\n\n"}},{"thumb":"V5_Tutorial_nameAndSave.jpg","mov":"V5_Blocks_NamingandSavingChromebook_V2","description":"Naming and Saving Your Project (Chrome OS)","filter":"","placeholder":false,"platform":["ChromeOS"],"vimeo":"475941246","proglang":["blocks","python","cpp"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>To give your project a name,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nopen the File menu and select Save.\n\n3\n00:00:09.110 --> 00:00:11.480\nSelect a location to save your project in\n\n4\n00:00:12.820 --> 00:00:15.603\nand choose a name that best describes your project.\n\n5\n00:00:19.400 --> 00:00:20.820\nYou can also save your project\n\n6\n00:00:20.820 --> 00:00:23.463\nby selecting the project name in the toolbar.\n\n7\n00:00:27.120 --> 00:00:29.713\nThis will allow you to rename your project as well.\n\n8\n00:00:33.330 --> 00:00:35.470\nOnce your project is initially saved,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 will keep your project saved at all times.\n\n10\n00:00:40.760 --> 00:00:42.750\nIf you forget to save before opening\n\n11\n00:00:42.750 --> 00:00:44.980\nor creating a different project,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 will ask you if you would like to save\n\n13\n00:00:47.940 --> 00:00:50.273\nbefore you move on to your different projects.\n\n14\n00:00:51.550 --> 00:00:53.960\nYou can also discard your unsaved project\n\n15\n00:00:53.960 --> 00:00:55.563\nif you do not wish to save.\n\n","ar":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>لإعطاء المشروع الخاص بك اسم،</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nافتح قائمة الملفات وحدد \"حفظ\".\n\n3\n00:00:09.110 --> 00:00:11.480\nحدد موقع لحفظ مشروعك\n\n4\n00:00:12.820 --> 00:00:15.603\nواختيار اسم يصف مشروعك بشكل جيد.\n\n5\n00:00:19.400 --> 00:00:20.820\nيمكنك أيضا حفظ مشروعك\n\n6\n00:00:20.820 --> 00:00:23.463\nعن طريق تحديد اسم المشروع في قائمة الأدوات.\n\n7\n00:00:27.120 --> 00:00:29.713\nكذلك, هذا سيسمح لك بإعادة تسمية مشروعك.\n\n8\n00:00:33.330 --> 00:00:35.470\nبمجرد حفظ مشروعك مبدئياً،\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 سيبقي مشروعك محفوظ في جميع الأوقات.\n\n10\n00:00:40.760 --> 00:00:42.750\nإذا نسيت الحفظ قبل الفتح\n\n11\n00:00:42.750 --> 00:00:44.980\nأو إنشاء مشروع مختلف،\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 سيسألك إذا كنت ترغب في الحفظ\n\n13\n00:00:47.940 --> 00:00:50.273\nقبل أن تنتقل إلى مشاريعك المختلفة.\n\n14\n00:00:51.550 --> 00:00:53.960\nيمكنك أيضا تجاهل مشاريعك الغير محفوظة\n\n15\n00:00:53.960 --> 00:00:55.563\nإذا كنت لا ترغب في الحفظ.\n\n","cs":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Pro pojmenování svého projektu</v>\n\n2\n00:00:01.940 --> 00:00:06.033\notevři menu Soubor a vyber Uložit.\n\n3\n00:00:09.110 --> 00:00:11.480\nVyber umístění pro uložení tvého projektu\n\n4\n00:00:12.820 --> 00:00:15.603\na zvol si název, který tvůj projekt nejlépe popisuje.\n\n5\n00:00:19.400 --> 00:00:20.820\nSvůj projekt můžeš také uložit\n\n6\n00:00:20.820 --> 00:00:23.463\nvýběrem názvu projektu v panelu nástrojů.\n\n7\n00:00:27.120 --> 00:00:29.713\nTo ti také umožní přejmenovat svůj projekt.\n\n8\n00:00:33.330 --> 00:00:35.470\nJakmile je tvůj projekt alespoň jednou uložen,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 bude udržovat tvůj projekt uložený pořád.\n\n10\n00:00:40.760 --> 00:00:42.750\nJestliže zapomeneš na uložení před otevřením,\n\n11\n00:00:42.750 --> 00:00:44.980\nnebo vytvořením jiného projektu,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 se zeptá, jestli ho chceš uložit,\n\n13\n00:00:47.940 --> 00:00:50.273\nnež přejdeš na své jiné projekty.\n\n14\n00:00:51.550 --> 00:00:53.960\nNeuložený projekt můžeš také zahodit,\n\n15\n00:00:53.960 --> 00:00:55.563\njestliže si nepřeješ ho uložit.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:09.110 --> 00:00:11.480\nSeleccione una ubicación en la que guardar su proyecto,\n\n4\n00:00:12.820 --> 00:00:15.603\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:19.400 --> 00:00:20.820\nTambién puede guardar su proyecto\n\n6\n00:00:20.820 --> 00:00:23.463\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:27.120 --> 00:00:29.713\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:33.330 --> 00:00:35.470\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:40.760 --> 00:00:42.750\nSi se olvida de guardar antes de abrir\n\n11\n00:00:42.750 --> 00:00:44.980\no crear un proyecto diferente\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 preguntará si desea guardar\n\n13\n00:00:47.940 --> 00:00:50.273\nantes de pasar a otro proyecto.\n\n14\n00:00:51.550 --> 00:00:53.960\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:53.960 --> 00:00:55.563\nsi no desea guardar.\n\n","es":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Para dar un nombre a su proyecto,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nabre el menú Archivo y selecciona Guardar.\n\n3\n00:00:09.110 --> 00:00:11.480\nSeleccione una ubicación en la que guardar su proyecto,\n\n4\n00:00:12.820 --> 00:00:15.603\ny seleccione un nombre que describa mejor su proyecto.\n\n5\n00:00:19.400 --> 00:00:20.820\nTambién puede guardar su proyecto\n\n6\n00:00:20.820 --> 00:00:23.463\nseleccionando el nombre de proyecto en la barra de herramientas.\n\n7\n00:00:27.120 --> 00:00:29.713\nEsto le permitirá renombrar su proyecto.\n\n8\n00:00:33.330 --> 00:00:35.470\nUna vez que el proyecto se ha guardado inicialmente,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 mantendrá su proyecto guardado en todo momento.\n\n10\n00:00:40.760 --> 00:00:42.750\nSi se olvida de guardar antes de abrir\n\n11\n00:00:42.750 --> 00:00:44.980\no crear un proyecto diferente\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 preguntará si desea guardar\n\n13\n00:00:47.940 --> 00:00:50.273\nantes de pasar a otro proyecto.\n\n14\n00:00:51.550 --> 00:00:53.960\nTambién puede descartar su proyecto sin guardar\n\n15\n00:00:53.960 --> 00:00:55.563\nsi no desea guardar.\n\n","fi":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Halutessasi nimetä ohjelmasi</v>\n\n2\n00:00:01.940 --> 00:00:06.033\navaa Tiedosto -valikko ja valitse Tallenna.\n\n3\n00:00:09.110 --> 00:00:11.480\nValitse kansio, mihin tallennat ohjelman\n\n4\n00:00:12.820 --> 00:00:15.603\nja valitse paras ohjelmasi kuvaava nimi.\n\n5\n00:00:19.400 --> 00:00:20.820\nVoit myös nimetä ohjelmasi\n\n6\n00:00:20.820 --> 00:00:23.463\nkirjoittamalla ohjelman nimi työpalkkin nimikenttään.\n\n7\n00:00:27.120 --> 00:00:29.713\nVoit myös uudelleennimetä ohjelmasi työpalkin nimikentästä.\n\n8\n00:00:33.330 --> 00:00:35.470\nKun ohjelma on alussa nimetty\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 tallentaa ohjelmasi jatkuvasti.\n\n10\n00:00:40.760 --> 00:00:42.750\nKun avaat jonkun toisen ohjelman\n\n11\n00:00:42.750 --> 00:00:44.980\ntai luot uuden ohjelman\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 kysyy haluatko tallentaa\n\n13\n00:00:47.940 --> 00:00:50.273\nennen toiseen ohjelmaan siirtymistä.\n\n14\n00:00:51.550 --> 00:00:53.960\nVoit myös hylätä tallennuksen\n\n15\n00:00:53.960 --> 00:00:55.563\njos et halua tallentaa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Pour donner un nom à votre projet,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nouvrez le menu \"Fichier\" et sélectionnez \"Enregistrer\".\n\n3\n00:00:09.110 --> 00:00:11.480\nChoisissez l'emplacement dans lequel enregistrer votre projet\n\n4\n00:00:12.820 --> 00:00:15.603\net choisissez un nom qui décrit le mieux votre projet.\n\n5\n00:00:19.400 --> 00:00:20.820\nVous pouvez également enregistrer votre projet\n\n6\n00:00:20.820 --> 00:00:23.463\nen sélectionnant le nom du projet dans la barre d'outils.\n\n7\n00:00:27.120 --> 00:00:29.713\nCela vous permettra également de renommer votre projet.\n\n8\n00:00:33.330 --> 00:00:35.470\nUne fois le projet enregistré une première fois,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 enregistrera automatiquement les changements apportés à votre projet.\n\n10\n00:00:40.760 --> 00:00:42.750\nSi vous oubliez d'enregistrer votre projet avant d'ouvrir\n\n11\n00:00:42.750 --> 00:00:44.980\nou de créer un autre projet,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 vous demandera si vous souhaitez enregistrer\n\n13\n00:00:47.940 --> 00:00:50.273\navant de continuer avec un autre projet.\n\n14\n00:00:51.550 --> 00:00:53.960\nVous pouvez également ignorer votre projet non sauvegardé\n\n15\n00:00:53.960 --> 00:00:55.563\nsi vous ne souhaitez pas l'enregistrer.\n\n","ko":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>프로젝트에 이름을 붙이려면</v>\n\n2\n00:00:01.940 --> 00:00:06.033\n파일 메뉴에서 '저장하기'를 선택하세요.\n\n3\n00:00:09.110 --> 00:00:11.480\n프로젝트를 저장할 위치를 선택하고\n\n4\n00:00:12.820 --> 00:00:15.603\n프로젝트를 가장 잘 설명하는 이름으로 저장합니다.\n\n5\n00:00:19.400 --> 00:00:20.820\n도구 모음에서 프로젝트 이름을 선택해\n\n6\n00:00:20.820 --> 00:00:23.463\n프로젝트를 저장할 수도 있습니다.\n\n7\n00:00:27.120 --> 00:00:29.713\n이 방법으로 프로젝트 이름 변경도 가능합니다.\n\n8\n00:00:33.330 --> 00:00:35.470\n프로젝트를 한 번 저장하면\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5는 프로젝트를 계속 저장합니다.\n\n10\n00:00:40.760 --> 00:00:42.750\n다른 프로젝트를 열거나 만들기 전에\n\n11\n00:00:42.750 --> 00:00:44.980\n저장하는 것을 잊었다면\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5는\n\n13\n00:00:47.940 --> 00:00:50.273\n다른 프로젝트를 하기 전에 저장할 것인지 묻습니다.\n\n14\n00:00:51.550 --> 00:00:53.960\n저장하지 않은 프로젝트를 저장하지 않으려면\n\n15\n00:00:53.960 --> 00:00:55.563\n삭제할 수도 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Norėdami pavadinti savo projektą,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\natidarykite bylų meniu ir spustelėkite \"Išsaugoti\".\n\n3\n00:00:09.110 --> 00:00:11.480\nPasirinkite vietą, kurioje išsaugosite savo projektą\n\n4\n00:00:12.820 --> 00:00:15.603\nir geriausiai Jūsų projektą apibūdinantį pavadinimą.\n\n5\n00:00:19.400 --> 00:00:20.820\nProjektą taip pat galite išsaugoti\n\n6\n00:00:20.820 --> 00:00:23.463\nparankinėje paspausdami ant jo pavadinimo.\n\n7\n00:00:27.120 --> 00:00:29.713\nTokiu būdu galite ir pervadinti savo projektą.\n\n8\n00:00:33.330 --> 00:00:35.470\nKai Jūsų projektas išsaugomas,\n\n9\n00:00:35.470 --> 00:00:39.143\nprograma \"VEXcode V5\" Jūsų projektą saugo visada.\n\n10\n00:00:40.760 --> 00:00:42.750\nJeigu prieš atidarydami arba\n\n11\n00:00:42.750 --> 00:00:44.980\nsukurdami kitą projektą pamirštate išsaugoti,\n\n12\n00:00:44.980 --> 00:00:47.940\nprograma \"VEXcode V5\" paklaus Jūsų, ar norėtumėte išsaugoti\n\n13\n00:00:47.940 --> 00:00:50.273\nprieš pereinant prie kitų projektų.\n\n14\n00:00:51.550 --> 00:00:53.960\nTaip pat galite atmesti savo neišsaugotą projektą,\n\n15\n00:00:53.960 --> 00:00:55.563\njeigu nenorite išsaugoti.\n\n","lv":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Narrator> Lai nosauktu savu projektu, </v>\n\n2\n00:00:01.940 --> 00:00:06.033\natveriet izvēlni “File” (fails) un atlasiet “Save” (saglabāt).\n\n3\n00:00:09.110 --> 00:00:11.480\nAtlasiet vietu, kur saglabāt savu projektu,\n\n4\n00:00:12.820 --> 00:00:15.603\nun izvēlieties nosaukumu, kas vislabāk raksturo jūsu projektu.\n\n5\n00:00:19.400 --> 00:00:20.820\nJūs variet arī saglabāt savu projektu,\n\n6\n00:00:20.820 --> 00:00:23.463\natlasot projekta nosaukumu rīkjoslā.\n\n7\n00:00:27.120 --> 00:00:29.713\nKā arī šādi var arī pārdēvēt savu projektu.\n\n8\n00:00:33.330 --> 00:00:35.470\nKad projekts ir saglabāts,\n\n9\n00:00:35.470 --> 00:00:39.143\nprojekts programmā VEXcode V5 būs vienmēr saglabāts.\n\n10\n00:00:40.760 --> 00:00:42.750\nJa esat aizmirsis saglabāt pirms cita\n\n11\n00:00:42.750 --> 00:00:44.980\nprojekta atvēršanas vai izveidošanas,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 norādīs, vai nevēlaties saglabāt\n\n13\n00:00:47.940 --> 00:00:50.273\nprojektu pirms atvērsiet citu projektu.\n\n14\n00:00:51.550 --> 00:00:53.960\nVarat arī dzēst savu nesaglabāto projektu,\n\n15\n00:00:53.960 --> 00:00:55.563\nja nevēlaties to saglabāt.\n\n","nl":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Om uw project een naam te geven,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nopen het bestandsmenu en selecteer Opslaan.\n\n3\n00:00:09.110 --> 00:00:11.480\nKies een locatie om uw project in op te slaan\n\n4\n00:00:12.820 --> 00:00:15.603\nen kies een naam die uw project het beste beschrijft.\n\n5\n00:00:19.400 --> 00:00:20.820\nU kunt uw project ook opslaan\n\n6\n00:00:20.820 --> 00:00:23.463\ndoor de projectnaam in de werkbalk te selecteren.\n\n7\n00:00:27.120 --> 00:00:29.713\nHiermee kunt u ook uw project hernoemen.\n\n8\n00:00:33.330 --> 00:00:35.470\nZodra uw project in eerste instantie is opgeslagen,\n\n9\n00:00:35.470 --> 00:00:39.143\nbehoudt VEXcode V5 uw project te allen tijde opgeslagen.\n\n10\n00:00:40.760 --> 00:00:42.750\nAls u vergeet op te slaan voor het openen\n\n11\n00:00:42.750 --> 00:00:44.980\nof maakt u een ander project\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 zal vragen of u wilt opslaan\n\n13\n00:00:47.940 --> 00:00:50.273\nvoordat u verder gaat met een ander project.\n\n14\n00:00:51.550 --> 00:00:53.960\nU kunt ook uw niet-opgeslagen project verwijderen\n\n15\n00:00:53.960 --> 00:00:55.563\nals u het niet wilt bewaren.\n\n","pl":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Aby nadać nazwę projektowi,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\notwórz menu pliku i wybierz Zapisz.\n\n3\n00:00:09.110 --> 00:00:11.480\nWybierz lokalizację, w której chcesz zapisać swój projekt\n\n4\n00:00:12.820 --> 00:00:15.603\nwybierz nazwę, która najlepiej opisuje twój projekt.\n\n5\n00:00:19.400 --> 00:00:20.820\nMożesz również zapisać swój projekt\n\n6\n00:00:20.820 --> 00:00:23.463\nwybierając nazwę projektu na pasku narzędzi.\n\n7\n00:00:27.120 --> 00:00:29.713\nPozwoli to również na zmianę nazwy projektu.\n\n8\n00:00:33.330 --> 00:00:35.470\nGdy Twój projekt zostanie początkowo zapisany,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 będzie zawsze zapisywać Twój projekt.\n\n10\n00:00:40.760 --> 00:00:42.750\nJeśli zapomnisz zapisać przed otwarciem\n\n11\n00:00:42.750 --> 00:00:44.980\nlub tworząc inny projekt\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 zapyta czy chcesz go zapisać\n\n13\n00:00:47.940 --> 00:00:50.273\nzanim przejdziesz do innego projektu.\n\n14\n00:00:51.550 --> 00:00:53.960\nMożesz również odrzucić swój niezapisany projekt\n\n15\n00:00:53.960 --> 00:00:55.563\njeśli nie chcesz zapisywać.\n\n","ru":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Для назначения имени проекта</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nоткройте меню \"Файл\" и выберите \"Сохранить\".\n\n3\n00:00:09.110 --> 00:00:11.480\nВыберите место сохранения файла\n\n4\n00:00:12.820 --> 00:00:15.603\nи имя, которое лучше всего описывает содержание проекта.\n\n5\n00:00:19.400 --> 00:00:20.820\nВы также можете сохранить проект,\n\n6\n00:00:20.820 --> 00:00:23.463\nвыбрав имя проекта на панели управления.\n\n7\n00:00:27.120 --> 00:00:29.713\nЭто также позволит переименовать проект.\n\n8\n00:00:33.330 --> 00:00:35.470\nПосле сохранения проекта,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 постоянно сохраняет проект во время работы.\n\n10\n00:00:40.760 --> 00:00:42.750\nЕсли вы забыли сохраниться перед открытием\n\n11\n00:00:42.750 --> 00:00:44.980\nили созданием проекта,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 предложит вам сохранить проект,\n\n13\n00:00:47.940 --> 00:00:50.273\nперед использованием следующего проекта.\n\n14\n00:00:51.550 --> 00:00:53.960\nВы можете отменить изменения в проекте,\n\n15\n00:00:53.960 --> 00:00:55.563\nесли не хотите сохраняться.\n\n","th":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>ในการตั้งชื่อโปรเจ็คของคุณ,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nคุณสามารถเปิดเมนู File และเลือก Save\n\n3\n00:00:09.110 --> 00:00:11.480\nเลือกตำแหน่งเพื่อบันทึกโปรเจ็คของคุณ\n\n4\n00:00:12.820 --> 00:00:15.603\nและเลือกชื่อที่ตรงกับโปรเจ็คของคุณมากที่สุด\n\n5\n00:00:19.400 --> 00:00:20.820\nคุณยังสามารถบันทึกโครงการของคุณ\n\n6\n00:00:20.820 --> 00:00:23.463\nโดยเลือกชื่อโครงการในแถบเครื่องมือ\n\n7\n00:00:27.120 --> 00:00:29.713\nซึ่งจะช่วยให้คุณสามารถเปลี่ยนชื่อโครงการของคุณได้เช่นกัน\n\n8\n00:00:33.330 --> 00:00:35.470\nเมื่อโครงการของคุณได้รับการบันทึกในขั้นต้น\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 จะบันทึกโครงการของคุณไว้ตลอดเวลา\n\n10\n00:00:40.760 --> 00:00:42.750\nหากลืมบันทึกก่อนเปิด\n\n11\n00:00:42.750 --> 00:00:44.980\nหรือสร้างโปรเจ็คอื่น\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 จะถามว่าคุณต้องการบันทึกหรือไม่\n\n13\n00:00:47.940 --> 00:00:50.273\nก่อนที่คุณจะย้ายไปยังโปรเจ็คอื่น\n\n14\n00:00:51.550 --> 00:00:53.960\nคุณยังสามารถยกเลิกโปรเจ็กต์ที่ยังไม่ได้บันทึกของคุณได้\n\n15\n00:00:53.960 --> 00:00:55.563\nหากคุณไม่ต้องการบันทึก\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Щоб назвати проєкт,</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nвідкрийте меню \"Файл\" і виберіть \"Зберегти\".\n\n3\n00:00:09.110 --> 00:00:11.480\nВиберіть місце збереження проєкту\n\n4\n00:00:12.820 --> 00:00:15.603\nі оберіть ім'я, яке найкраще опише проєкт.\n\n5\n00:00:19.400 --> 00:00:20.820\nТакож ви можете зберегти проєкт,\n\n6\n00:00:20.820 --> 00:00:23.463\nобравши ім'я проєкту на панелі інструментів.\n\n7\n00:00:27.120 --> 00:00:29.713\nЦе дасть вам змогу і перейменувати збережений проєкт.\n\n8\n00:00:33.330 --> 00:00:35.470\nЩойно проєкт буде збережено вперше,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 зберігатиме цей проєкт постійно.\n\n10\n00:00:40.760 --> 00:00:42.750\nЯкщо ви забудете зберегти проєкт перед запуском\n\n11\n00:00:42.750 --> 00:00:44.980\nабо створенням іншого проєкту,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 запитає, чи треба зберегти\n\n13\n00:00:47.940 --> 00:00:50.273\nнаявний проєкт перед переходом до нового.\n\n14\n00:00:51.550 --> 00:00:53.960\nВи також можете відхилити незбережений проєкт,\n\n15\n00:00:53.960 --> 00:00:55.563\nякщо не хочете його зберігати.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>Để đặt tên cho dự án của bạn, hãy</v>\n\n2\n00:00:01.940 --> 00:00:06.033\nmở menu Tệp và chọn Lưu.\n\n3\n00:00:09.110 --> 00:00:11.480\nChọn một vị trí để lưu dự án của bạn vào\n\n4\n00:00:12.820 --> 00:00:15.603\nvà chọn một cái tên mô tả tốt nhất dự án của bạn.\n\n5\n00:00:19.400 --> 00:00:20.820\nBạn cũng có thể lưu dự án của mình\n\n6\n00:00:20.820 --> 00:00:23.463\nbằng cách chọn tên dự án trên thanh công cụ.\n\n7\n00:00:27.120 --> 00:00:29.713\nĐiều này cũng sẽ cho phép bạn đổi tên dự án của mình.\n\n8\n00:00:33.330 --> 00:00:35.470\nSau khi dự án của bạn được lưu lần đầu,\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5 sẽ luôn lưu dự án của bạn.\n\n10\n00:00:40.760 --> 00:00:42.750\nNếu bạn quên lưu trước khi mở\n\n11\n00:00:42.750 --> 00:00:44.980\nhoặc tạo một dự án khác,\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5 sẽ hỏi bạn có muốn lưu không\n\n13\n00:00:47.940 --> 00:00:50.273\ntrước khi bạn chuyển sang các dự án khác nhau của mình.\n\n14\n00:00:51.550 --> 00:00:53.960\nBạn cũng có thể hủy dự án chưa lưu của mình\n\n15\n00:00:53.960 --> 00:00:55.563\nnếu bạn không muốn tiết kiệm.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\ncrwdns96356:0crwdne96356:0\n\n2\n00:00:01.940 --> 00:00:06.033\ncrwdns96358:0crwdne96358:0\n\n3\n00:00:09.110 --> 00:00:11.480\ncrwdns96360:0crwdne96360:0\n\n4\n00:00:12.820 --> 00:00:15.603\ncrwdns96362:0crwdne96362:0\n\n5\n00:00:19.400 --> 00:00:20.820\ncrwdns96364:0crwdne96364:0\n\n6\n00:00:20.820 --> 00:00:23.463\ncrwdns96366:0crwdne96366:0\n\n7\n00:00:27.120 --> 00:00:29.713\ncrwdns96368:0crwdne96368:0\n\n8\n00:00:33.330 --> 00:00:35.470\ncrwdns96370:0crwdne96370:0\n\n9\n00:00:35.470 --> 00:00:39.143\ncrwdns96372:0crwdne96372:0\n\n10\n00:00:40.760 --> 00:00:42.750\ncrwdns96374:0crwdne96374:0\n\n11\n00:00:42.750 --> 00:00:44.980\ncrwdns96376:0crwdne96376:0\n\n12\n00:00:44.980 --> 00:00:47.940\ncrwdns96378:0crwdne96378:0\n\n13\n00:00:47.940 --> 00:00:50.273\ncrwdns96380:0crwdne96380:0\n\n14\n00:00:51.550 --> 00:00:53.960\ncrwdns96382:0crwdne96382:0\n\n15\n00:00:53.960 --> 00:00:55.563\ncrwdns96384:0crwdne96384:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.370 --> 00:00:01.940\n<v Instructor>欲给您的程序命名，</v>\n\n2\n00:00:01.940 --> 00:00:06.033\n打开“文件”菜单并选择“保存”。\n\n3\n00:00:09.110 --> 00:00:11.480\n选择一个位置来保存你的程序\n\n4\n00:00:12.820 --> 00:00:15.603\n并选择一个最能描述您项目的名称。\n\n5\n00:00:19.400 --> 00:00:20.820\n您也可以保存您的项目\n\n6\n00:00:20.820 --> 00:00:23.463\n通过选中工具栏的程序名称。\n\n7\n00:00:27.120 --> 00:00:29.713\n这也将允许您重命名程序。\n\n8\n00:00:33.330 --> 00:00:35.470\n一旦您的程序初始保存后，\n\n9\n00:00:35.470 --> 00:00:39.143\nVEXcode V5将保持您的程序随时保存。\n\n10\n00:00:40.760 --> 00:00:42.750\n如果您在打开\n\n11\n00:00:42.750 --> 00:00:44.980\n或者创建一个不同的程序之前忘记保存，\n\n12\n00:00:44.980 --> 00:00:47.940\nVEXcode V5将询问您是否想要\n\n13\n00:00:47.940 --> 00:00:50.273\n在去到不同程序之前时保存。\n\n14\n00:00:51.550 --> 00:00:53.960\n您也可以放弃未保存程序\n\n15\n00:00:53.960 --> 00:00:55.563\n如果您不希望保存的话。\n\n"}},{"thumb":"V5_Tutorial_updatingFirmware.jpg","mov":"V5_Blocks_UpdatingFirmware_V2","description":"Updating Firmware","filter":"","placeholder":false,"platform":["MacOS","Windows","ChromeOS"],"vimeo":"475901085","proglang":["blocks","python","cpp"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>You can update the firmware of your V5 Brain</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nright inside of VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nFirst, make sure that the V5 Robot Brain is turned on\n\n4\n00:00:09.430 --> 00:00:11.213\nand connected to your computer.\n\n5\n00:00:15.050 --> 00:00:18.280\nOnce the V5 Robot Brain is connected to your computer,\n\n6\n00:00:18.280 --> 00:00:23.113\nthe Brain icon will either turn green or orange.\n\n7\n00:00:24.020 --> 00:00:26.630\nGreen means that the V5 Brain is connected\n\n8\n00:00:26.630 --> 00:00:28.383\nand the firmware is up to date.\n\n9\n00:00:30.250 --> 00:00:32.180\nOrange means that the V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nis connected to your computer,\n\n11\n00:00:33.840 --> 00:00:36.783\nhowever, your robots firmware is not up to date.\n\n12\n00:00:37.889 --> 00:00:41.270\nTo update your robot's firmware open the Brain menu.\n\n13\n00:00:41.270 --> 00:00:43.740\nHere, you will see the name of the Brain,\n\n14\n00:00:43.740 --> 00:00:48.210\nthe version of the VEX OS, and the status of your firmware.\n\n15\n00:00:48.210 --> 00:00:50.610\nSelect Out of Date.\n\n16\n00:00:50.610 --> 00:00:54.400\nWhile the firmware is updating, do not close VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nor disconnect the V5 Brain from your computer.\n\n18\n00:00:58.130 --> 00:01:00.290\nOnce the firmware update is complete,\n\n19\n00:01:00.290 --> 00:01:03.513\nturn your brain off, then back on.\n\n20\n00:01:05.550 --> 00:01:08.070\nWhen the V5 Brain's firmware is updated,\n\n21\n00:01:08.070 --> 00:01:11.130\nit will also update any other V5 component,\n\n22\n00:01:11.130 --> 00:01:13.410\nsuch as a smart motor or the battery\n\n23\n00:01:13.410 --> 00:01:15.823\nonce they're connected to the V5 Brain.\n\n","ar":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>يمكنك تحديث البرنامج الثابت الخاص بك بـعقل V5 ا</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nفي داخل VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nأولاً، تأكد من تشغيل عقل الروبوت V5\n\n4\n00:00:09.430 --> 00:00:11.213\nمتصل بجهاز الكمبيوتر الخاص بك.\n\n5\n00:00:15.050 --> 00:00:18.280\nبمجرد أن يتصل دماغ الروبوت V5 بحاسوبك،\n\n6\n00:00:18.280 --> 00:00:23.113\nرمز العقل سيتحول إما إلى اللون الأخضر أو البرتقالي.\n\n7\n00:00:24.020 --> 00:00:26.630\nالخضراء يعني أن عقل V5 متصل\n\n8\n00:00:26.630 --> 00:00:28.383\nوقد تم تحديث البرامج الثابتة.\n\n9\n00:00:30.250 --> 00:00:32.180\nالبرتقالي يعني أن عقل V5\n\n10\n00:00:32.180 --> 00:00:33.840\nمتصل بجهاز الكمبيوتر الخاص بك,\n\n11\n00:00:33.840 --> 00:00:36.783\nعلى الرغم من ذلك، فإن البرنامج الثابت للروبوتات الخاص بك ليس محدثًا.\n\n12\n00:00:37.889 --> 00:00:41.270\nلتحديث البرنامج الثابت للروبوت الخاص بك قم بفتح قائمة العقل.\n\n13\n00:00:41.270 --> 00:00:43.740\nوهنا، سترون اسم العقل،\n\n14\n00:00:43.740 --> 00:00:48.210\nالإصدار من VEX OS، وحالة البرامج الثابتة الخاصة بك.\n\n15\n00:00:48.210 --> 00:00:50.610\nحدد خارج التاريخ.\n\n16\n00:00:50.610 --> 00:00:54.400\nفي الوقت الذي يتم فيه تحديث البرنامج الثابت، لا تغلق VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nولا تفصل عقل V5 عن جهاز الكمبيوتر الخاص بك.\n\n18\n00:00:58.130 --> 00:01:00.290\nبمجرد اكتمال تحديث البرنامج الثابت،\n\n19\n00:01:00.290 --> 00:01:03.513\nقم بإيقاف العقل، ثم أعد تشغيله.\n\n20\n00:01:05.550 --> 00:01:08.070\nعندما يتم تحديث برنامج دماغ V5،\n\n21\n00:01:08.070 --> 00:01:11.130\nيقوم أيضا بتحديث أي عنصر V5 آخر،\n\n22\n00:01:11.130 --> 00:01:13.410\nمثل المحرك الذكي أو البطارية\n\n23\n00:01:13.410 --> 00:01:15.823\nبمجرد أن تكون متصلة بعقل V5.\n\n","cs":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Aktualizovat firmware tvého V5 Mozku můžeš</v>\n\n2\n00:00:03.190 --> 00:00:05.780\npřímo ve VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nNejprve se ujisti, že je robotický V5 Mozek zapnutý\n\n4\n00:00:09.430 --> 00:00:11.213\na připojený ke tvému počítači.\n\n5\n00:00:15.050 --> 00:00:18.280\nJakmile je robotický V5 Mozek připojený ke tvému počítači,\n\n6\n00:00:18.280 --> 00:00:23.113\nikonka mozku změní barvu buď na zelenou, nebo oranžovou.\n\n7\n00:00:24.020 --> 00:00:26.630\nZelená znamená, že je V5 Mozek připojený\n\n8\n00:00:26.630 --> 00:00:28.383\na firmware je aktuální.\n\n9\n00:00:30.250 --> 00:00:32.180\nOranžová znamená, že je V5 Mozek\n\n10\n00:00:32.180 --> 00:00:33.840\npřipojený ke tvému počítači,\n\n11\n00:00:33.840 --> 00:00:36.783\nale firmware tvého robota není aktuální.\n\n12\n00:00:37.889 --> 00:00:41.270\nPro aktualizaci firmwaru tvého robota otevři menu Mozek.\n\n13\n00:00:41.270 --> 00:00:43.740\nTady uvidíš název Mozku,\n\n14\n00:00:43.740 --> 00:00:48.210\nverzi VEX OS a stav tvého firmwaru.\n\n15\n00:00:48.210 --> 00:00:50.610\nVyber Zastaralý.\n\n16\n00:00:50.610 --> 00:00:54.400\nZatímco se firmware aktualizuje, nezavírej VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\na neodpojuj V5 Mozek od tvého počítače.\n\n18\n00:00:58.130 --> 00:01:00.290\nJakmile je aktualizace firmwaru hotová,\n\n19\n00:01:00.290 --> 00:01:03.513\nvypni a poté znovu zapni svůj Mozek.\n\n20\n00:01:05.550 --> 00:01:08.070\nJakmile je firmware V5 Mozku aktualizovaný,\n\n21\n00:01:08.070 --> 00:01:11.130\naktualizuje také všechny ostatní V5 součástky,\n\n22\n00:01:11.130 --> 00:01:13.410\njako je například chytrý motor nebo baterie,\n\n23\n00:01:13.410 --> 00:01:15.823\njakmile se připojí k V5 Mozku.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Puede actualizar el firmware de su V5 Brain</v>\n\n2\n00:00:03.190 --> 00:00:05.780\ndentro de VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nPrimero, asegúrese de que el V5 Robot Brain está activado\n\n4\n00:00:09.430 --> 00:00:11.213\ny conectado a su computadora.\n\n5\n00:00:15.050 --> 00:00:18.280\nUna vez que el V5 Robot Brain está conectado a su computadora,\n\n6\n00:00:18.280 --> 00:00:23.113\nel icono del V5 Brain se vuelve verde o naranja.\n\n7\n00:00:24.020 --> 00:00:26.630\nVerde significa que el V5 Brain está conectado\n\n8\n00:00:26.630 --> 00:00:28.383\ny el firmware está actualizado.\n\n9\n00:00:30.250 --> 00:00:32.180\nNaranja significa que el V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nestá conectado a su computadora,\n\n11\n00:00:33.840 --> 00:00:36.783\nsin embargo, el firmware de sus robots no está actualizado.\n\n12\n00:00:37.889 --> 00:00:41.270\nPara actualizar el firmware de su robot abra el menú \"Brain\".\n\n13\n00:00:41.270 --> 00:00:43.740\nAquí, verás el nombre del Brain,\n\n14\n00:00:43.740 --> 00:00:48.210\nla versión del VEX OS (sistema operativo), y el estado de su firmware.\n\n15\n00:00:48.210 --> 00:00:50.610\nSeleccionar Fuera de Fecha.\n\n16\n00:00:50.610 --> 00:00:54.400\nMientras el firmware se esté actualizando, no cierre VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\no desconecte el V5 Brain de su computadora.\n\n18\n00:00:58.130 --> 00:01:00.290\nUna vez finalizada la actualización del firmware,\n\n19\n00:01:00.290 --> 00:01:03.513\napague el cerebro y vuelva a encenderlo.\n\n20\n00:01:05.550 --> 00:01:08.070\nCuando se actualiza el firmware de V5 Brain,\n\n21\n00:01:08.070 --> 00:01:11.130\ntambién actualizará cualquier otro componente V5,\n\n22\n00:01:11.130 --> 00:01:13.410\ncomo un motor o la batería\n\n23\n00:01:13.410 --> 00:01:15.823\nuna vez que estén conectados al V5 Brain.\n\n","es":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Puede actualizar el firmware de su V5 Brain</v>\n\n2\n00:00:03.190 --> 00:00:05.780\ndentro de VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nPrimero, asegúrese de que el V5 Robot Brain está activado\n\n4\n00:00:09.430 --> 00:00:11.213\ny conectado a su computadora.\n\n5\n00:00:15.050 --> 00:00:18.280\nUna vez que el V5 Robot Brain está conectado a su computadora,\n\n6\n00:00:18.280 --> 00:00:23.113\nel icono del V5 Brain se vuelve verde o naranja.\n\n7\n00:00:24.020 --> 00:00:26.630\nVerde significa que el V5 Brain está conectado\n\n8\n00:00:26.630 --> 00:00:28.383\ny el firmware está actualizado.\n\n9\n00:00:30.250 --> 00:00:32.180\nNaranja significa que el V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nestá conectado a su computadora,\n\n11\n00:00:33.840 --> 00:00:36.783\nsin embargo, el firmware de sus robots no está actualizado.\n\n12\n00:00:37.889 --> 00:00:41.270\nPara actualizar el firmware de su robot abra el menú \"Brain\".\n\n13\n00:00:41.270 --> 00:00:43.740\nAquí, verás el nombre del Brain,\n\n14\n00:00:43.740 --> 00:00:48.210\nla versión del VEX OS (sistema operativo), y el estado de su firmware.\n\n15\n00:00:48.210 --> 00:00:50.610\nSeleccionar Fuera de Fecha.\n\n16\n00:00:50.610 --> 00:00:54.400\nMientras el firmware se esté actualizando, no cierre VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\no desconecte el V5 Brain de su computadora.\n\n18\n00:00:58.130 --> 00:01:00.290\nUna vez finalizada la actualización del firmware,\n\n19\n00:01:00.290 --> 00:01:03.513\napague el cerebro y vuelva a encenderlo.\n\n20\n00:01:05.550 --> 00:01:08.070\nCuando se actualiza el firmware de V5 Brain,\n\n21\n00:01:08.070 --> 00:01:11.130\ntambién actualizará cualquier otro componente V5,\n\n22\n00:01:11.130 --> 00:01:13.410\ncomo un motor o la batería\n\n23\n00:01:13.410 --> 00:01:15.823\nuna vez que estén conectados al V5 Brain.\n\n","fi":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Voit päivittää V5 Aivojen -käyttöjärjestelmäohjelman</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nsuoraan VEXcode V5 ohjelmasta.\n\n3\n00:00:05.780 --> 00:00:09.430\nLaita virrat V5 robotissa päälle\n\n4\n00:00:09.430 --> 00:00:11.213\nja liitä USB/langaton yhteys tietokoneeseen.\n\n5\n00:00:15.050 --> 00:00:18.280\nKun yhteys on voimassa\n\n6\n00:00:18.280 --> 00:00:23.113\nohjelman Aivot -ikonin valo muuttuu joko vihreäksi tai oransiksi.\n\n7\n00:00:24.020 --> 00:00:26.630\nVihreä valo tarkoittaa että yhteys robotin V5 Aivoihin on kunnossa\n\n8\n00:00:26.630 --> 00:00:28.383\nja varusohjelma on ajantasalla.\n\n9\n00:00:30.250 --> 00:00:32.180\nOransi väri tarkoittaa, että robotin V5 Aivot\n\n10\n00:00:32.180 --> 00:00:33.840\non yhdistetty tietokoneeseen\n\n11\n00:00:33.840 --> 00:00:36.783\nmutta robotin käytössä oleva varusohjelma on vanhentunut.\n\n12\n00:00:37.889 --> 00:00:41.270\nVoit päivittää robotin laiteohjelmiston avaamalla Aivot kuvakkeesta valintakolmion.\n\n13\n00:00:41.270 --> 00:00:43.740\nNäet ikkunassa Aivojen -nimen,\n\n14\n00:00:43.740 --> 00:00:48.210\nVEXOS käyttöjärjestemän version ja tilan.\n\n15\n00:00:48.210 --> 00:00:50.610\nValise kohta Varusohjelman lataus.\n\n16\n00:00:50.610 --> 00:00:54.400\nKun päivitystä robotin aivoihin ladataan, älä sulje VEXcode V5 ohjelmaa\n\n17\n00:00:54.400 --> 00:00:58.130\ntai katkaise yhteyttä V5 Aivoihin tietokoneestasi.\n\n18\n00:00:58.130 --> 00:01:00.290\nKun päivitys on kunnossa\n\n19\n00:01:00.290 --> 00:01:03.513\nsammuta ja käynnistä robotin Aivot uudelleen.\n\n20\n00:01:05.550 --> 00:01:08.070\nKun päivitys on ok\n\n21\n00:01:08.070 --> 00:01:11.130\nsamalla on päivitetty joku muukin V5 komponentti\n\n22\n00:01:11.130 --> 00:01:13.410\nkuten esimerkiksi älymoottori tai akku\n\n23\n00:01:13.410 --> 00:01:15.823\nkun yhteys V5 Aivoihin on taas kunnossa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Vous pouvez mettre à jour le micrologiciel de votre Cerveau V5</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nà l'intérieur même de VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nTout d'abord, assurez-vous que le Cerveau du Robot V5 est activé\n\n4\n00:00:09.430 --> 00:00:11.213\net connecté à votre ordinateur.\n\n5\n00:00:15.050 --> 00:00:18.280\nUne fois que le Cerveau du Robot V5 est connecté à votre ordinateur,\n\n6\n00:00:18.280 --> 00:00:23.113\nl'icône Cerveau deviendra soit verte, soit orange.\n\n7\n00:00:24.020 --> 00:00:26.630\nVert signifie que le Cerveau V5 est connecté\n\n8\n00:00:26.630 --> 00:00:28.383\net que le micrologiciel est à jour.\n\n9\n00:00:30.250 --> 00:00:32.180\nOrange signifie que le Cerveau V5\n\n10\n00:00:32.180 --> 00:00:33.840\nest connecté à votre ordinateur,\n\n11\n00:00:33.840 --> 00:00:36.783\ncependant, le micrologiciel de vos robots n'est pas à jour.\n\n12\n00:00:37.889 --> 00:00:41.270\nPour mettre à jour le micrologiciel de votre robot, ouvrez le menu Cerveau.\n\n13\n00:00:41.270 --> 00:00:43.740\nIci, vous verrez le nom du Cerveau,\n\n14\n00:00:43.740 --> 00:00:48.210\nla version de l'OS VEX et le statut de votre micrologiciel.\n\n15\n00:00:48.210 --> 00:00:50.610\nSélectionnez \"Obsolète\".\n\n16\n00:00:50.610 --> 00:00:54.400\nPendant la mise à jour du micrologiciel, ne fermez pas VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\net ne débranchez pas le Cerveau V5 de votre ordinateur.\n\n18\n00:00:58.130 --> 00:01:00.290\nUne fois la mise à jour du micrologiciel terminée,\n\n19\n00:01:00.290 --> 00:01:03.513\néteignez votre cerveau, puis rallumez-le.\n\n20\n00:01:05.550 --> 00:01:08.070\nQuand le micrologiciel du Cerveau V5 est mis à jour,\n\n21\n00:01:08.070 --> 00:01:11.130\ncela mettra également à jour tout autre composant V5,\n\n22\n00:01:11.130 --> 00:01:13.410\ncomme un moteur intelligent ou la batterie\n\n23\n00:01:13.410 --> 00:01:15.823\nune fois qu'ils sont connectés au Cerveau V5.\n\n","ko":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>VEXcode V5에서 바로 V5 브레인의 펌웨어를</v>\n\n2\n00:00:03.190 --> 00:00:05.780\n업데이트할 수 있습니다.\n\n3\n00:00:05.780 --> 00:00:09.430\n먼저 V5 로봇 브레인이 켜져 있고\n\n4\n00:00:09.430 --> 00:00:11.213\n컴퓨터에 연결되어 있는지 확인하세요.\n\n5\n00:00:15.050 --> 00:00:18.280\nV5 로봇 브레인이 컴퓨터에 연결되면\n\n6\n00:00:18.280 --> 00:00:23.113\n브레인의 아이콘이 녹색 또는 주황색으로 바뀝니다.\n\n7\n00:00:24.020 --> 00:00:26.630\n녹색은 V5 브레인이 컴퓨터에 연결되어 있고\n\n8\n00:00:26.630 --> 00:00:28.383\n펌웨어가 최신 상태임을 의미합니다.\n\n9\n00:00:30.250 --> 00:00:32.180\n주황색은 V5 브레인이\n\n10\n00:00:32.180 --> 00:00:33.840\n컴퓨터에 연결되어 있지만\n\n11\n00:00:33.840 --> 00:00:36.783\n로봇의 펌웨어가 최신 상태가 아님을 의미합니다.\n\n12\n00:00:37.889 --> 00:00:41.270\n로봇의 펌웨어를 업데이트하려면 브레인 메뉴를 엽니다.\n\n13\n00:00:41.270 --> 00:00:43.740\n여기에서 브레인의 이름과\n\n14\n00:00:43.740 --> 00:00:48.210\nVEX OS 버전, 펌웨어 상태 등을 확인할 수 있습니다.\n\n15\n00:00:48.210 --> 00:00:50.610\n\"기간 만료\"를 선택하세요.\n\n16\n00:00:50.610 --> 00:00:54.400\n펌웨어가 업데이트되는 동안 VEXcode V5를 닫거나\n\n17\n00:00:54.400 --> 00:00:58.130\n컴퓨터에서 V5 브레인을 분리하지 마십시오.\n\n18\n00:00:58.130 --> 00:01:00.290\n펌웨어 업데이트가 완료되면\n\n19\n00:01:00.290 --> 00:01:03.513\n브레인을 껐다가 다시 켜십시오.\n\n20\n00:01:05.550 --> 00:01:08.070\nV5 브레인의 펌웨어가 업데이트되면\n\n21\n00:01:08.070 --> 00:01:11.130\n스마트 모터나 배터리 같은\n\n22\n00:01:11.130 --> 00:01:13.410\n다른 V5 구성 요소도\n\n23\n00:01:13.410 --> 00:01:15.823\nV5 브레인과 연결될 때 업데이트됩니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Galite atnaujinti savo \"V5 Brain\" programinę-aparatinę įrangą</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nper programą \"VEXcode V5\".\n\n3\n00:00:05.780 --> 00:00:09.430\nPirmiausia, įsitikinkite, kad \"V5 Robot Brain\" įjungtos\n\n4\n00:00:09.430 --> 00:00:11.213\nir prijunkite prie savo kompiuterio.\n\n5\n00:00:15.050 --> 00:00:18.280\n\"V5 Robot Brain\" prijungę prie savo kompiuterio,\n\n6\n00:00:18.280 --> 00:00:23.113\nsmegenų ikona bus arba žalia, arba oranžinė.\n\n7\n00:00:24.020 --> 00:00:26.630\nŽalia ikona reiškia, kad \"V5 Brain\" yra prijungtos\n\n8\n00:00:26.630 --> 00:00:28.383\nir programinė-aparatinė įranga atnaujinta.\n\n9\n00:00:30.250 --> 00:00:32.180\nOranžinė spalva reiškia, kad \"V5 Brain\"\n\n10\n00:00:32.180 --> 00:00:33.840\nprijungtos prie Jūsų kompiuterio,\n\n11\n00:00:33.840 --> 00:00:36.783\ntačiau, Jūsų roboto programinė-aparatinė įranga nėra atnaujinta.\n\n12\n00:00:37.889 --> 00:00:41.270\nNorėdami atnaujinti savo roboto programinę-aparatinę įrangą, atverkite smegenų meniu.\n\n13\n00:00:41.270 --> 00:00:43.740\nJame matysite smegenų pavadinimą,\n\n14\n00:00:43.740 --> 00:00:48.210\n\"VEX OS\" versiją ir programinės-aparatinės įrangos būklę.\n\n15\n00:00:48.210 --> 00:00:50.610\nPasirinkite \"Negalioja\".\n\n16\n00:00:50.610 --> 00:00:54.400\nKol programinė-aparatinė įranga atnaujinama, neuždarykite programos \"VEXcode V5\"\n\n17\n00:00:54.400 --> 00:00:58.130\narba neatjunkite \"V5 Brain\" nuo savo kompiuterio.\n\n18\n00:00:58.130 --> 00:01:00.290\nBaigę programinės-aparatinės įrangos atnaujinimą,\n\n19\n00:01:00.290 --> 00:01:03.513\nįjunkite ir išjunkite smegenis.\n\n20\n00:01:05.550 --> 00:01:08.070\nAtnaujinant \"V5 Brain\" programinę-aparatinę įrangą,\n\n21\n00:01:08.070 --> 00:01:11.130\nbus atnaujinamas bet koks kitas \"V5\" komponentas,\n\n22\n00:01:11.130 --> 00:01:13.410\npavyzdžiui, išmanusis variklis arba baterija,\n\n23\n00:01:13.410 --> 00:01:15.823\nkai tik jie bus prijungti prie \"V5 Brain\".\n\n","lv":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Variet atjaunināt V5 Brain programmaparatūra</v>\n\n2\n00:00:03.190 --> 00:00:05.780\ntieši, izmantojot VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nVispirms pārliecinieties, vai ir ieslēgts V5 Robot Brain\n\n4\n00:00:09.430 --> 00:00:11.213\nun savienots ar datoru.\n\n5\n00:00:15.050 --> 00:00:18.280\nKad V5 Robot Brain ir pievienots datoram,\n\n6\n00:00:18.280 --> 00:00:23.113\nBrain ikona kļūst vai nu zaļa, vai oranža.\n\n7\n00:00:24.020 --> 00:00:26.630\nZaļš nozīmē, ka ir pieslēgts V5 Brain\n\n8\n00:00:26.630 --> 00:00:28.383\nun programmaparatūra ir atjaunināta.\n\n9\n00:00:30.250 --> 00:00:32.180\nOranžais nozīmē, ka V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nir savienots ar datoru,\n\n11\n00:00:33.840 --> 00:00:36.783\ntomēr jūsu robotu programmaparatūra nav atjaunināta.\n\n12\n00:00:37.889 --> 00:00:41.270\nLai atjauninātu robota programmaparatūru, atveriet izvēlni “Brain”.\n\n13\n00:00:41.270 --> 00:00:43.740\nŠeit atradīsiet Brain nosaukumu,\n\n14\n00:00:43.740 --> 00:00:48.210\nVEX OS versija un jūsu programmaparatūras statuss.\n\n15\n00:00:48.210 --> 00:00:50.610\nAtlasiet “Out of Date”.\n\n16\n00:00:50.610 --> 00:00:54.400\nKamēr programmaparatūra tiek atjaunināta, neaizveriet VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nvai atvienojiet V5 Brain no datora.\n\n18\n00:00:58.130 --> 00:01:00.290\nKad programmaparatūras atjaunināšana ir pabeigta,\n\n19\n00:01:00.290 --> 00:01:03.513\nizslēdziet smadzenes, pēc tam atkal ieslēdziet.\n\n20\n00:01:05.550 --> 00:01:08.070\nKad tiek atjaunināta V5 Brain programmaparatūra,\n\n21\n00:01:08.070 --> 00:01:11.130\ntas atjauninās arī jebkuru citu V5 komponentu,\n\n22\n00:01:11.130 --> 00:01:13.410\npiemēram, viedo motoru vai akumulatoru,\n\n23\n00:01:13.410 --> 00:01:15.823\ntiklīdz viņi ir savienoti ar V5 Brain.\n\n","nl":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor> U kunt de firmware van je V5 Brein </v>\n\n2\n00:00:03.190 --> 00:00:05.780\nrechtstreeks in VEXcode V5 updaten.\n\n3\n00:00:05.780 --> 00:00:09.430\nZorg er eerst voor dat de V5 Robot Brein is ingeschakeld\n\n4\n00:00:09.430 --> 00:00:11.213\nen is aangesloten op uw computer.\n\n5\n00:00:15.050 --> 00:00:18.280\nZodra de V5 Robot Brein op uw computer is aangesloten,\n\n6\n00:00:18.280 --> 00:00:23.113\nwordt het Brein-icoon groen of oranje.\n\n7\n00:00:24.020 --> 00:00:26.630\nGroen betekent dat de V5 Brein is verbonden\n\n8\n00:00:26.630 --> 00:00:28.383\nen de firmware is bijgewerkt.\n\n9\n00:00:30.250 --> 00:00:32.180\nOranje betekent dat de V5 Brein\n\n10\n00:00:32.180 --> 00:00:33.840\nis op uw computer aangesloten,\n\n11\n00:00:33.840 --> 00:00:36.783\nmaar de firmware van uw robot niet bijgewerkt is.\n\n12\n00:00:37.889 --> 00:00:41.270\nOpen het Brein menu om de firmware van uw robot bij te werken.\n\n13\n00:00:41.270 --> 00:00:43.740\nHier ziet u de naam van het Brein,\n\n14\n00:00:43.740 --> 00:00:48.210\nde versie van de VEX OS en de status van uw firmware.\n\n15\n00:00:48.210 --> 00:00:50.610\nSelecteer Verouderd.\n\n16\n00:00:50.610 --> 00:00:54.400\nWanneer de firmware wordt bijgewerkt, mag u VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nniet afsluiten of de V5 Brein niet loskoppelen van uw computer.\n\n18\n00:00:58.130 --> 00:01:00.290\nZodra de firmware update is voltooid,\n\n19\n00:01:00.290 --> 00:01:03.513\nzet uw brein uit en weer aan.\n\n20\n00:01:05.550 --> 00:01:08.070\nWanneer de firmware van de V5 Brein is bijgewerkt,\n\n21\n00:01:08.070 --> 00:01:11.130\nwordt ook elk ander V5 component bijgewerkt,\n\n22\n00:01:11.130 --> 00:01:13.410\nzoals een slimme motor of de batterij,\n\n23\n00:01:13.410 --> 00:01:15.823\nzodra ze zijn aangesloten op de V5 Brein.\n\n","pl":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Możesz zaktualizować oprogramowanie V5</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nz prawej strony kodu VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nNajpierw upewnij się, że robot V5 jest włączony\n\n4\n00:00:09.430 --> 00:00:11.213\ni podłączony do komputera.\n\n5\n00:00:15.050 --> 00:00:18.280\nPo podłączeniu robota V5 do komputera,\n\n6\n00:00:18.280 --> 00:00:23.113\nikona mózgu zmieni się na zieloną lub pomarańczową.\n\n7\n00:00:24.020 --> 00:00:26.630\nZielony oznacza, że V5 Brain jest połączony\n\n8\n00:00:26.630 --> 00:00:28.383\na oprogramowanie jest aktualne.\n\n9\n00:00:30.250 --> 00:00:32.180\nPomarańczowy oznacza, że mózg V5\n\n10\n00:00:32.180 --> 00:00:33.840\njest podłączony do komputera,\n\n11\n00:00:33.840 --> 00:00:36.783\nale oprogramowanie nie jest aktualne.\n\n12\n00:00:37.889 --> 00:00:41.270\nAby zaktualizować oprogramowanie twojego robota, otwórz menu Brain.\n\n13\n00:00:41.270 --> 00:00:43.740\nTutaj zobaczysz nazwę mózgu,\n\n14\n00:00:43.740 --> 00:00:48.210\nwersja VEX OS i status Twojego oprogramowania.\n\n15\n00:00:48.210 --> 00:00:50.610\nWybierz \"nieaktualne\".\n\n16\n00:00:50.610 --> 00:00:54.400\nPodczas aktualizacji oprogramowania nie zamykaj VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nlub odłączaj V5 od komputera.\n\n18\n00:00:58.130 --> 00:01:00.290\nPo zakończeniu aktualizacji,\n\n19\n00:01:00.290 --> 00:01:03.513\nwyłącz mózg, a następnie z powrotem włącz.\n\n20\n00:01:05.550 --> 00:01:08.070\nPo aktualizacji oprogramowania V5 Brain,\n\n21\n00:01:08.070 --> 00:01:11.130\nzaktualizuje się również każdy inny komponent V5,\n\n22\n00:01:11.130 --> 00:01:13.410\ntakie jak inteligentny silnik lub bateria\n\n23\n00:01:13.410 --> 00:01:15.823\nkiedy są połączone z mózgiem V5.\n\n","ru":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Вы можете обновить прошивку вашего контроллера</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nпрям внутри VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nВ первую очередь убедитесь, что контроллер включён\n\n4\n00:00:09.430 --> 00:00:11.213\nи соединён с ПК.\n\n5\n00:00:15.050 --> 00:00:18.280\nПосле подключения робота к ПК,\n\n6\n00:00:18.280 --> 00:00:23.113\nиконка загорится зелёным или оранжевым цветом.\n\n7\n00:00:24.020 --> 00:00:26.630\nЗелёный цвет контроллера означает успешное подключение\n\n8\n00:00:26.630 --> 00:00:28.383\nи уже обновленную прошивку.\n\n9\n00:00:30.250 --> 00:00:32.180\nОранжевый цвет означает, что\n\n10\n00:00:32.180 --> 00:00:33.840\nконтроллер подключён к ПК,\n\n11\n00:00:33.840 --> 00:00:36.783\nоднако, прошивка нуждается в обновлении.\n\n12\n00:00:37.889 --> 00:00:41.270\nДля обновления прошивки, откройте меню контроллера.\n\n13\n00:00:41.270 --> 00:00:43.740\nВ меню отображается имя контроллера,\n\n14\n00:00:43.740 --> 00:00:48.210\nверсия VEX OS и статус прошивки.\n\n15\n00:00:48.210 --> 00:00:50.610\nВыберите обновление.\n\n16\n00:00:50.610 --> 00:00:54.400\nНе закрывайте VEXcode V5 и не отключайте контроллер\n\n17\n00:00:54.400 --> 00:00:58.130\nво время обновления прошивки.\n\n18\n00:00:58.130 --> 00:01:00.290\nПосле завершения обновления прошивки,\n\n19\n00:01:00.290 --> 00:01:03.513\nвыключите и включите ваш контроллер.\n\n20\n00:01:05.550 --> 00:01:08.070\nПри обновления прошивки контроллера,\n\n21\n00:01:08.070 --> 00:01:11.130\nбудут обновлены все устройства,\n\n22\n00:01:11.130 --> 00:01:13.410\nтакие как приводы или аккумулятор,\n\n23\n00:01:13.410 --> 00:01:15.823\nесли они были подключены к контроллеру во время процесса обновления.\n\n","th":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor> คุณสามารถอัปเดตเฟิร์มแวร์ของ V5 Brain </v>\n\n2\n00:00:03.190 --> 00:00:05.780\nได้จากภายใน VEXcode V5\n\n3\n00:00:05.780 --> 00:00:09.430\nขั้นแรกตรวจสอบให้แน่ใจว่า V5 Robot Brain นั้นเปิดอยู่\n\n4\n00:00:09.430 --> 00:00:11.213\nและเชื่อมต่อกับคอมพิวเตอร์ของคุณแล้ว\n\n5\n00:00:15.050 --> 00:00:18.280\nเมื่อ V5 Robot Brain เชื่อมต่อกับคอมพิวเตอร์ของคุณแล้ว\n\n6\n00:00:18.280 --> 00:00:23.113\nไอคอน Brain จะเปลี่ยนเป็นสีเขียวหรือสีส้ม\n\n7\n00:00:24.020 --> 00:00:26.630\nสีเขียวหมายความว่า V5 Brain เชื่อมต่ออยู่\n\n8\n00:00:26.630 --> 00:00:28.383\nและเฟิร์มแวร์เป็นรุ่นล่าสุด\n\n9\n00:00:30.250 --> 00:00:32.180\nสีส้มหมายความว่า V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nเชื่อมต่อกับอุปกรณ์ของคุณ\n\n11\n00:00:33.840 --> 00:00:36.783\nแต่ว่าเฟิร์มแวร์โรบ็อตของคุณยังไม่ใช่เวอร์ชั่นล่าสุด\n\n12\n00:00:37.889 --> 00:00:41.270\nหากต้องการอัปเดตเฟิร์มแวร์ของหุ่นยนต์ให้เปิดเมนู Brain\n\n13\n00:00:41.270 --> 00:00:43.740\nที่นี่คุณจะเห็นชื่อของ Brain\n\n14\n00:00:43.740 --> 00:00:48.210\nเวอร์ชันของ VEX OS และสถานะของเฟิร์มแวร์ของคุณ\n\n15\n00:00:48.210 --> 00:00:50.610\nเลือก Out of Date\n\n16\n00:00:50.610 --> 00:00:54.400\nในขณะที่กำลังอัปเดตเฟิร์มแวร์ห้ามปิด VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nหรือตัดการเชื่อมต่อ V5 Brain จากคอมพิวเตอร์ของคุณ\n\n18\n00:00:58.130 --> 00:01:00.290\nเมื่อการอัปเดตเฟิร์มแวร์เสร็จสมบูรณ์\n\n19\n00:01:00.290 --> 00:01:03.513\nปิด brain ของคุณแล้วเปิดใหม่\n\n20\n00:01:05.550 --> 00:01:08.070\nเมื่อเฟิร์มแวร์ของ V5 Brain ได้รับการอัพเดต\n\n21\n00:01:08.070 --> 00:01:11.130\nมันจะอัปเดตส่วนประกอบ V5 อื่น ๆ\n\n22\n00:01:11.130 --> 00:01:13.410\nเช่นมอเตอร์อัจฉริยะหรือแบตเตอรี่\n\n23\n00:01:13.410 --> 00:01:15.823\nเมื่อเชื่อมต่อกับ V5 Brain\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Ви можете оновити прошивку V5 Brain</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nвсередині VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nДля початку, переконайтеся, що V5 Brain увімкнено\n\n4\n00:00:09.430 --> 00:00:11.213\nі під'єднано до комп'ютера.\n\n5\n00:00:15.050 --> 00:00:18.280\nЩойно V5 Brain приєднається до комп'ютера,\n\n6\n00:00:18.280 --> 00:00:23.113\nзначок Brain у меню стане зеленим або оранжевим.\n\n7\n00:00:24.020 --> 00:00:26.630\nЗелений означає, що V5 Brain під'єднано\n\n8\n00:00:26.630 --> 00:00:28.383\nі прошивка актуальна.\n\n9\n00:00:30.250 --> 00:00:32.180\nОранжевий означає, що V5 Brain\n\n10\n00:00:32.180 --> 00:00:33.840\nпід'єднано до комп'ютера,\n\n11\n00:00:33.840 --> 00:00:36.783\nале прошивка робота застаріла.\n\n12\n00:00:37.889 --> 00:00:41.270\nЩоб оновити прошивку робота, відкрийте меню Brain.\n\n13\n00:00:41.270 --> 00:00:43.740\nТут ви побачите назву ім'я Brain\n\n14\n00:00:43.740 --> 00:00:48.210\nверсію VEX OS і статус вашої прошивки.\n\n15\n00:00:48.210 --> 00:00:50.610\nВиберіть \"Застаріло\".\n\n16\n00:00:50.610 --> 00:00:54.400\nПоки прошивка оновлюється, не закривайте VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nі не від'єднуйте V5 Brain від комп'ютера.\n\n18\n00:00:58.130 --> 00:01:00.290\nПісля закінчення оновлення прошивки\n\n19\n00:01:00.290 --> 00:01:03.513\nвимкніть Brain і увімкніть його знову.\n\n20\n00:01:05.550 --> 00:01:08.070\nКоли прошивка V5 Brain оновиться,\n\n21\n00:01:08.070 --> 00:01:11.130\nвін також оновить інші V5 компоненти,\n\n22\n00:01:11.130 --> 00:01:13.410\nяк-от розумні мотори або акумулятор,\n\n23\n00:01:13.410 --> 00:01:15.823\nщойно вони під'єднаються до V5 Brain.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>Bạn có thể cập nhật chương trình cơ sở của V5 Brain</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nngay bên trong VEXcode V5.\n\n3\n00:00:05.780 --> 00:00:09.430\nTrước tiên, hãy đảm bảo rằng Bộ não Robot V5 đã được bật\n\n4\n00:00:09.430 --> 00:00:11.213\nvà kết nối với máy tính của bạn.\n\n5\n00:00:15.050 --> 00:00:18.280\nSau khi kết nối V5 Robot Brain với máy tính của bạn,\n\n6\n00:00:18.280 --> 00:00:23.113\nbiểu tượng Bộ não sẽ chuyển sang màu xanh lá cây hoặc màu cam.\n\n7\n00:00:24.020 --> 00:00:26.630\nMàu xanh lá cây có nghĩa là V5 Brain đã được kết nối\n\n8\n00:00:26.630 --> 00:00:28.383\nvà phần sụn được cập nhật.\n\n9\n00:00:30.250 --> 00:00:32.180\nMàu cam có nghĩa là Bộ não V5\n\n10\n00:00:32.180 --> 00:00:33.840\nđược kết nối với máy tính của bạn,\n\n11\n00:00:33.840 --> 00:00:36.783\ntuy nhiên, chương trình cơ sở rô bốt của bạn không được cập nhật.\n\n12\n00:00:37.889 --> 00:00:41.270\nĐể cập nhật chương trình cơ sở cho rô-bốt của bạn, hãy mở menu Bộ não.\n\n13\n00:00:41.270 --> 00:00:43.740\nỞ đây, bạn sẽ thấy tên của Brain,\n\n14\n00:00:43.740 --> 00:00:48.210\nphiên bản của VEX OS và trạng thái của chương trình cơ sở của bạn.\n\n15\n00:00:48.210 --> 00:00:50.610\nChọn lỗi thời.\n\n16\n00:00:50.610 --> 00:00:54.400\nTrong khi cập nhật chương trình cơ sở, không đóng VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\nhoặc ngắt kết nối V5 Brain khỏi máy tính của bạn.\n\n18\n00:00:58.130 --> 00:01:00.290\nSau khi cập nhật chương trình cơ sở hoàn tất,\n\n19\n00:01:00.290 --> 00:01:03.513\ntắt não của bạn, sau đó bật lại.\n\n20\n00:01:05.550 --> 00:01:08.070\nKhi chương trình cơ sở của V5 Brain được cập nhật,\n\n21\n00:01:08.070 --> 00:01:11.130\nnó cũng sẽ cập nhật bất kỳ thành phần V5 nào khác,\n\n22\n00:01:11.130 --> 00:01:13.410\nchẳng hạn như một động cơ thông minh hoặc pin\n\n23\n00:01:13.410 --> 00:01:15.823\nkhi chúng được kết nối với V5 Brain.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\ncrwdns96550:0crwdne96550:0\n\n2\n00:00:03.190 --> 00:00:05.780\ncrwdns96552:0crwdne96552:0\n\n3\n00:00:05.780 --> 00:00:09.430\ncrwdns96554:0crwdne96554:0\n\n4\n00:00:09.430 --> 00:00:11.213\ncrwdns96556:0crwdne96556:0\n\n5\n00:00:15.050 --> 00:00:18.280\ncrwdns96558:0crwdne96558:0\n\n6\n00:00:18.280 --> 00:00:23.113\ncrwdns96560:0crwdne96560:0\n\n7\n00:00:24.020 --> 00:00:26.630\ncrwdns96562:0crwdne96562:0\n\n8\n00:00:26.630 --> 00:00:28.383\ncrwdns96564:0crwdne96564:0\n\n9\n00:00:30.250 --> 00:00:32.180\ncrwdns96566:0crwdne96566:0\n\n10\n00:00:32.180 --> 00:00:33.840\ncrwdns96568:0crwdne96568:0\n\n11\n00:00:33.840 --> 00:00:36.783\ncrwdns96570:0crwdne96570:0\n\n12\n00:00:37.889 --> 00:00:41.270\ncrwdns96572:0crwdne96572:0\n\n13\n00:00:41.270 --> 00:00:43.740\ncrwdns96574:0crwdne96574:0\n\n14\n00:00:43.740 --> 00:00:48.210\ncrwdns96576:0crwdne96576:0\n\n15\n00:00:48.210 --> 00:00:50.610\ncrwdns96578:0crwdne96578:0\n\n16\n00:00:50.610 --> 00:00:54.400\ncrwdns96580:0crwdne96580:0\n\n17\n00:00:54.400 --> 00:00:58.130\ncrwdns96582:0crwdne96582:0\n\n18\n00:00:58.130 --> 00:01:00.290\ncrwdns96584:0crwdne96584:0\n\n19\n00:01:00.290 --> 00:01:03.513\ncrwdns96586:0crwdne96586:0\n\n20\n00:01:05.550 --> 00:01:08.070\ncrwdns96588:0crwdne96588:0\n\n21\n00:01:08.070 --> 00:01:11.130\ncrwdns96590:0crwdne96590:0\n\n22\n00:01:11.130 --> 00:01:13.410\ncrwdns96592:0crwdne96592:0\n\n23\n00:01:13.410 --> 00:01:15.823\ncrwdns96594:0crwdne96594:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.400 --> 00:00:03.190\n<v Instructor>您可以就在VEXcode V5中更新</v>\n\n2\n00:00:03.190 --> 00:00:05.780\nV5主控器的固件。\n\n3\n00:00:05.780 --> 00:00:09.430\n首先，确保V5机器人主控器已开启\n\n4\n00:00:09.430 --> 00:00:11.213\n并且已连接至您的电脑。\n\n5\n00:00:15.050 --> 00:00:18.280\n一旦V5机器人主控器已连接到您的电脑，\n\n6\n00:00:18.280 --> 00:00:23.113\n主控器图标将会变为绿色或者橙色。\n\n7\n00:00:24.020 --> 00:00:26.630\n绿色表示V5主控器已连接\n\n8\n00:00:26.630 --> 00:00:28.383\n并且固件是最新的。\n\n9\n00:00:30.250 --> 00:00:32.180\n橙色表示V5主控器\n\n10\n00:00:32.180 --> 00:00:33.840\n已连接到电脑，\n\n11\n00:00:33.840 --> 00:00:36.783\n但是固件不是最新的。\n\n12\n00:00:37.889 --> 00:00:41.270\n欲更新主控器的固件，打开主控器菜单。\n\n13\n00:00:41.270 --> 00:00:43.740\n在这里，您将看到主控器的名称，\n\n14\n00:00:43.740 --> 00:00:48.210\nVEX OS的版本号，以及固件的状态。\n\n15\n00:00:48.210 --> 00:00:50.610\n选择“过期”。\n\n16\n00:00:50.610 --> 00:00:54.400\n当固件正在更新时，不要关闭VEXcode V5\n\n17\n00:00:54.400 --> 00:00:58.130\n或者断开V5主控器与电脑之间的连接。\n\n18\n00:00:58.130 --> 00:01:00.290\n一旦固件更新完成，\n\n19\n00:01:00.290 --> 00:01:03.513\n关闭主控器，然后重新开启。\n\n20\n00:01:05.550 --> 00:01:08.070\n当V5 主控器固件更新后，\n\n21\n00:01:08.070 --> 00:01:11.130\n它将同时更新其他V5元件，\n\n22\n00:01:11.130 --> 00:01:13.410\n比如智能电机或者电池，\n\n23\n00:01:13.410 --> 00:01:15.823\n一旦它们连接到V5主控器时。\n\n"}},{"thumb":"V5_Tutorial_usingExamplesAndTemplates.jpg","mov":"V5_Blocks_ExamplesTemplates_V2","description":"Using Examples and Templates","filter":"","placeholder":false,"vimeo":"475901442","proglang":["blocks"],"progtarget":["physical"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>If you are just getting started</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nand want to explore different robot behaviors,\n\n3\n00:00:04.380 --> 00:00:07.470\nor how different blocks in VEXcode V5 are used,\n\n4\n00:00:07.470 --> 00:00:10.740\nexample projects are a great resource.\n\n5\n00:00:10.740 --> 00:00:12.560\nTo open an example project,\n\n6\n00:00:12.560 --> 00:00:16.363\nselect the File menu and choose Open Examples.\n\n7\n00:00:18.100 --> 00:00:22.010\nHere you'll see icons for many different example projects.\n\n8\n00:00:22.010 --> 00:00:24.700\nEach icon represents a different project,\n\n9\n00:00:24.700 --> 00:00:27.950\nand are colored according to the block categories.\n\n10\n00:00:27.950 --> 00:00:29.940\nYou can also use the filter bar\n\n11\n00:00:29.940 --> 00:00:32.863\nto quickly find a specific type of example.\n\n12\n00:00:35.140 --> 00:00:38.673\nThere is also a special type of example called templates.\n\n13\n00:00:40.300 --> 00:00:42.780\nTemplates are used to create a blank project\n\n14\n00:00:42.780 --> 00:00:45.400\nwith a preset device configuration.\n\n15\n00:00:45.400 --> 00:00:49.000\nIf you are using a standard robot build like the Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nyou can use a template\n\n17\n00:00:50.040 --> 00:00:52.453\nto quickly get started with a new program.\n\n18\n00:00:53.460 --> 00:00:56.663\nTo open any example, select one from the menu.\n\n19\n00:00:59.240 --> 00:01:01.670\nOnce opened, you can add and remove blocks\n\n20\n00:01:01.670 --> 00:01:03.633\nto make the example project your own.\n\n21\n00:01:09.070 --> 00:01:12.243\nSave and download the example to try it on your robot.\n\n","ar":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>إذا كنت بدأت للتو</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nو تريد أن تستكشف سلوكيات روبوت مختلفة،\n\n3\n00:00:04.380 --> 00:00:07.470\nأو كيف يتم استخدام مقاطع مختلفة في VEXcode V5،\n\n4\n00:00:07.470 --> 00:00:10.740\nأمثلة المشاريع هو مورد عظيم.\n\n5\n00:00:10.740 --> 00:00:12.560\nلفتح مثال لمشروع ما،\n\n6\n00:00:12.560 --> 00:00:16.363\nحدد قائمة الملفات واختر أمثلة مفتوحة.\n\n7\n00:00:18.100 --> 00:00:22.010\nهنا سترى رموز للعديد من المشاريع المختلفة.\n\n8\n00:00:22.010 --> 00:00:24.700\nكل رمز يمثل مشروعا مختلفا,\n\n9\n00:00:24.700 --> 00:00:27.950\nوتكون ملونة وفقا لفئات المقاطع.\n\n10\n00:00:27.950 --> 00:00:29.940\nيمكنك أيضًا استخدام شريط التصفية\n\n11\n00:00:29.940 --> 00:00:32.863\nللعثور بسرعة على نوع محدد من الأمثلة.\n\n12\n00:00:35.140 --> 00:00:38.673\nوهناك أيضا نوع خاص من الأمثلة يسمى القوالب.\n\n13\n00:00:40.300 --> 00:00:42.780\nيتم استخدام القوالب لإنشاء مشروع فارغ\n\n14\n00:00:42.780 --> 00:00:45.400\nمع تكوين جهاز معين مسبقا.\n\n15\n00:00:45.400 --> 00:00:49.000\nإذا كنت تستخدم روبوت نموذجي للبناء مثل Clawbot،\n\n16\n00:00:49.000 --> 00:00:50.040\nيمكنك استخدام قالب\n\n17\n00:00:50.040 --> 00:00:52.453\nللبدء بسرعة ببرنامج جديد.\n\n18\n00:00:53.460 --> 00:00:56.663\nلفتح أي مثال، حدد واحد من القائمة.\n\n19\n00:00:59.240 --> 00:01:01.670\nبمجرد فتحه، يمكنك إضافة وإزالة القطع\n\n20\n00:01:01.670 --> 00:01:03.633\nلجعل مثال المشروع خاص بك.\n\n21\n00:01:09.070 --> 00:01:12.243\nإحفظ و حمل المثال لتجربته على الروبوت الخاص بك.\n\n","cs":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Jestliže právě teprve začínáš</v>\n\n2\n00:00:01.950 --> 00:00:04.380\na chceš prozkoumat různá chování robota,\n\n3\n00:00:04.380 --> 00:00:07.470\nnebo jak se používají různé bloky ve VEXcode V5,\n\n4\n00:00:07.470 --> 00:00:10.740\nukázkové příklady jsou skvělým zdrojem.\n\n5\n00:00:10.740 --> 00:00:12.560\nPro otevření ukázkového projektu\n\n6\n00:00:12.560 --> 00:00:16.363\nvyber menu Soubor a zvol Otevřít ukázky.\n\n7\n00:00:18.100 --> 00:00:22.010\nTady uvidíš ikonky pro mnoho různých ukázkových projektů.\n\n8\n00:00:22.010 --> 00:00:24.700\nKaždá ikonka představuje jiný projekt,\n\n9\n00:00:24.700 --> 00:00:27.950\na ikonky mají barvu podle kategorií bloků.\n\n10\n00:00:27.950 --> 00:00:29.940\nMůžeš také použít filtrovací panel\n\n11\n00:00:29.940 --> 00:00:32.863\npro rychlé nalezení konkrétního typu ukázek.\n\n12\n00:00:35.140 --> 00:00:38.673\nExistuje také speciální druh ukázek zvaný Šablony.\n\n13\n00:00:40.300 --> 00:00:42.780\nŠablony se používají ke tvorbě prázdného projektu\n\n14\n00:00:42.780 --> 00:00:45.400\ns předpřipraveným nastavením zařízení.\n\n15\n00:00:45.400 --> 00:00:49.000\nKdyž používáš standardní konstrukci robota, jako je Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nmůžeš použít šablonu\n\n17\n00:00:50.040 --> 00:00:52.453\npro rychlý začátek práce s novým programem.\n\n18\n00:00:53.460 --> 00:00:56.663\nPro otevření nějaké ukázky ji vyber z nabídky.\n\n19\n00:00:59.240 --> 00:01:01.670\nPo otevření ukázky můžeš přidávat a odebírat bloky tak,\n\n20\n00:01:01.670 --> 00:01:03.633\nabys ukázkový projekt upravil podle sebe.\n\n21\n00:01:09.070 --> 00:01:12.243\nUlož a stáhni ukázkový příklad pro vyzkoušení na tvém robotovi.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Si está empezando</v>\n\n2\n00:00:01.950 --> 00:00:04.380\ny desea explorar diferentes comportamientos del robot,\n\n3\n00:00:04.380 --> 00:00:07.470\no cómo se utilizan diferentes bloques en VEXcode V5\n\n4\n00:00:07.470 --> 00:00:10.740\nlos proyectos de ejemplo son un gran recurso.\n\n5\n00:00:10.740 --> 00:00:12.560\nPara abrir un proyecto de ejemplo,\n\n6\n00:00:12.560 --> 00:00:16.363\nseleccione el menú Archivo y elije Abrir Ejemplos.\n\n7\n00:00:18.100 --> 00:00:22.010\nAquí verás iconos para muchos diferentes proyectos de ejemplo.\n\n8\n00:00:22.010 --> 00:00:24.700\nCada icono representa un proyecto diferente,\n\n9\n00:00:24.700 --> 00:00:27.950\ny coloreados de acuerdo a las categorías de bloques.\n\n10\n00:00:27.950 --> 00:00:29.940\nTambién puede usar la barra de filtros para rápidamente\n\n11\n00:00:29.940 --> 00:00:32.863\nencontrar un tipo específico de ejemplo.\n\n12\n00:00:35.140 --> 00:00:38.673\nTambién hay un tipo especial de ejemplos llamados Plantillas.\n\n13\n00:00:40.300 --> 00:00:42.780\nLas Plantillas se utilizan para crear un proyecto en blanco\n\n14\n00:00:42.780 --> 00:00:45.400\ncon una configuración de dispositivo predeterminada.\n\n15\n00:00:45.400 --> 00:00:49.000\nSi está usando una construcción de robot estándar,\n\n16\n00:00:49.000 --> 00:00:50.040\npuede utilizar una plantilla de ejemplo\n\n17\n00:00:50.040 --> 00:00:52.453\npara comenzar rápidamente con un nuevo programa.\n\n18\n00:00:53.460 --> 00:00:56.663\nPara abrir cualquier ejemplo,\nseleccione uno del menú.\n\n19\n00:00:59.240 --> 00:01:01.670\nUna vez abierto, puede añadir y eliminar bloques\n\n20\n00:01:01.670 --> 00:01:03.633\npara hacer el proyecto de ejemplo propio.\n\n21\n00:01:09.070 --> 00:01:12.243\nGuarde y descargue el ejemplo para probarlo en su robot.\n\n","es":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Si está empezando</v>\n\n2\n00:00:01.950 --> 00:00:04.380\ny desea explorar diferentes comportamientos del robot,\n\n3\n00:00:04.380 --> 00:00:07.470\no cómo se utilizan diferentes bloques en VEXcode V5\n\n4\n00:00:07.470 --> 00:00:10.740\nlos proyectos de ejemplo son un gran recurso.\n\n5\n00:00:10.740 --> 00:00:12.560\nPara abrir un proyecto de ejemplo,\n\n6\n00:00:12.560 --> 00:00:16.363\nseleccione el menú Archivo y elije Abrir Ejemplos.\n\n7\n00:00:18.100 --> 00:00:22.010\nAquí verás iconos para muchos diferentes proyectos de ejemplo.\n\n8\n00:00:22.010 --> 00:00:24.700\nCada icono representa un proyecto diferente,\n\n9\n00:00:24.700 --> 00:00:27.950\ny coloreados de acuerdo a las categorías de bloques.\n\n10\n00:00:27.950 --> 00:00:29.940\nTambién puede usar la barra de filtros para rápidamente\n\n11\n00:00:29.940 --> 00:00:32.863\nencontrar un tipo específico de ejemplo.\n\n12\n00:00:35.140 --> 00:00:38.673\nTambién hay un tipo especial de ejemplos llamados Plantillas.\n\n13\n00:00:40.300 --> 00:00:42.780\nLas Plantillas se utilizan para crear un proyecto en blanco\n\n14\n00:00:42.780 --> 00:00:45.400\ncon una configuración de dispositivo predeterminada.\n\n15\n00:00:45.400 --> 00:00:49.000\nSi está usando una construcción de robot estándar,\n\n16\n00:00:49.000 --> 00:00:50.040\npuede utilizar una plantilla de ejemplo\n\n17\n00:00:50.040 --> 00:00:52.453\npara comenzar rápidamente con un nuevo programa.\n\n18\n00:00:53.460 --> 00:00:56.663\nPara abrir cualquier ejemplo,\nseleccione uno del menú.\n\n19\n00:00:59.240 --> 00:01:01.670\nUna vez abierto, puede añadir y eliminar bloques\n\n20\n00:01:01.670 --> 00:01:03.633\npara hacer el proyecto de ejemplo propio.\n\n21\n00:01:09.070 --> 00:01:12.243\nGuarde y descargue el ejemplo para probarlo en su robot.\n\n","fi":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Jos olet vasta aloittelemassa ohjelmointia</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nja haluat tutkia robotin käyttäytymistä\n\n3\n00:00:04.380 --> 00:00:07.470\ntai miten VEXcode V5 blokkeja käytetään\n\n4\n00:00:07.470 --> 00:00:10.740\nlataa esimerkkiohjelmia malliksi.\n\n5\n00:00:10.740 --> 00:00:12.560\nAvataksesi jonkun esimerkkiohjelman\n\n6\n00:00:12.560 --> 00:00:16.363\nvalitse Tiedosto -valikko ja sen alta Avaa Esimerkit.\n\n7\n00:00:18.100 --> 00:00:22.010\nNäet ylhäällä eri kattavuusalueen kuvakkeet esimerkkiohjelmista.\n\n8\n00:00:22.010 --> 00:00:24.700\nJokainen ohjelmakuvake vastaa yhtä esimerkkiohjelmaa\n\n9\n00:00:24.700 --> 00:00:27.950\nja värit ylhäällä ohjelmakategoriaa, mitä ohjelma opettaa.\n\n10\n00:00:27.950 --> 00:00:29.940\nVoit myös siivilöidä alueita valitsemalla yläpalkista sopiva aihealue,\n\n11\n00:00:29.940 --> 00:00:32.863\njotta löydät haluamasi esimerkkityypin ohjelmat.\n\n12\n00:00:35.140 --> 00:00:38.673\nOn myös pelkkiä Mallit -ohjelmia.\n\n13\n00:00:40.300 --> 00:00:42.780\nNäissä voit tehdä tyhjän ohjelman\n\n14\n00:00:42.780 --> 00:00:45.400\ntietyllä laitemäärityksellä.\n\n15\n00:00:45.400 --> 00:00:49.000\nJos käytät standardi robottimallia kuten Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nvoit valita mallin myös siihen,\n\n17\n00:00:50.040 --> 00:00:52.453\nettä pääset nopeasti eteenpäin uudessa ohjelmassasi.\n\n18\n00:00:53.460 --> 00:00:56.663\nHalutessasi avata esimerkin, valitse yksi kuvavalikosta.\n\n19\n00:00:59.240 --> 00:01:01.670\nAvattuasi voit lisätä ja poistaa blokkeja\n\n20\n00:01:01.670 --> 00:01:03.633\ntehdäksesi siitä oman ohjelmaversion.\n\n21\n00:01:09.070 --> 00:01:12.243\nTallenna ja lataa suorittaaksesi sen robotissa.\n\n","fr":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Si vous venez de commencer</v>\n\n2\n00:00:01.950 --> 00:00:04.380\net souhaitez explorer différents comportements de robots,\n\n3\n00:00:04.380 --> 00:00:07.470\nou comment les différents blocs VEXcode V5 sont utilisés,\n\n4\n00:00:07.470 --> 00:00:10.740\nles exemples de projets constituent une ressource précieuse.\n\n5\n00:00:10.740 --> 00:00:12.560\nPour ouvrir un exemple de projet,\n\n6\n00:00:12.560 --> 00:00:16.363\nsélectionnez le menu \"Fichier\" et choisissez \"Ouvrir des exemples\".\n\n7\n00:00:18.100 --> 00:00:22.010\nIci, vous verrez des icônes pour de nombreux exemples de projets.\n\n8\n00:00:22.010 --> 00:00:24.700\nChaque icône représente un projet différent,\n\n9\n00:00:24.700 --> 00:00:27.950\net sont colorés selon les catégories de blocs.\n\n10\n00:00:27.950 --> 00:00:29.940\nVous pouvez également utiliser la barre de filtre\n\n11\n00:00:29.940 --> 00:00:32.863\npour trouver rapidement un type d'exemple spécifique.\n\n12\n00:00:35.140 --> 00:00:38.673\nIl y a aussi un type spécial d'exemples appelés Modèles.\n\n13\n00:00:40.300 --> 00:00:42.780\nLes modèles sont utilisés pour créer un projet vide\n\n14\n00:00:42.780 --> 00:00:45.400\navec une configuration prédéfinie d'appareils.\n\n15\n00:00:45.400 --> 00:00:49.000\nSi vous utilisez une construction standard de robot comme le Robot Pince,\n\n16\n00:00:49.000 --> 00:00:50.040\nvous pouvez utiliser un modèle\n\n17\n00:00:50.040 --> 00:00:52.453\npour commencer rapidement avec un nouveau programme.\n\n18\n00:00:53.460 --> 00:00:56.663\nPour ouvrir un exemple, sélectionnez-en un dans le menu.\n\n19\n00:00:59.240 --> 00:01:01.670\nUne fois ouvert, vous pouvez ajouter et supprimer des blocs\n\n20\n00:01:01.670 --> 00:01:03.633\npour vous approprier l'exemple de projet.\n\n21\n00:01:09.070 --> 00:01:12.243\nEnregistrez et téléchargez l'exemple pour l'essayer sur votre robot.\n\n","ko":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>이제 막 시작했고 </v>\n\n2\n00:00:01.950 --> 00:00:04.380\n로봇의 여러 동작이나\n\n3\n00:00:04.380 --> 00:00:07.470\nVEXcode V5의 다양한 블록 사용법이 궁금하다면\n\n4\n00:00:07.470 --> 00:00:10.740\n예제 프로젝트는 훌륭한 자원입니다.\n\n5\n00:00:10.740 --> 00:00:12.560\n예제 프로젝트를 열려면\n\n6\n00:00:12.560 --> 00:00:16.363\n\"파일\" 메뉴에서 \"예제 열기\"를 선택합니다.\n\n7\n00:00:18.100 --> 00:00:22.010\n여기에는 다양한 예제 프로젝트의 아이콘이 표시됩니다.\n\n8\n00:00:22.010 --> 00:00:24.700\n각 아이콘은 서로 다른 프로젝트를 나타내며\n\n9\n00:00:24.700 --> 00:00:27.950\n블록 카테고리에 따라 색상으로 구분됩니다.\n\n10\n00:00:27.950 --> 00:00:29.940\n필터를 사용하여\n\n11\n00:00:29.940 --> 00:00:32.863\n특정 유형의 예제를 빠르게 찾을 수도 있습니다.\n\n12\n00:00:35.140 --> 00:00:38.673\n템플릿이라는 특수한 형태의 예제도 있습니다.\n\n13\n00:00:40.300 --> 00:00:42.780\n템플릿은 미리 설정된 기기 구성으로\n\n14\n00:00:42.780 --> 00:00:45.400\n빈 프로젝트를 만드는 데 사용됩니다.\n\n15\n00:00:45.400 --> 00:00:49.000\n클로봇과 같은 표준 로봇 빌드를 사용하는 경우\n\n16\n00:00:49.000 --> 00:00:50.040\n템플릿을 사용하여\n\n17\n00:00:50.040 --> 00:00:52.453\n새 프로그램을 빠르게 시작할 수 있습니다.\n\n18\n00:00:53.460 --> 00:00:56.663\n예제를 열려면 메뉴에서 하나를 선택하세요.\n\n19\n00:00:59.240 --> 00:01:01.670\n예제 프로젝트에 블록을 추가하거나 제거하여\n\n20\n00:01:01.670 --> 00:01:03.633\n나만의 것으로 만들 수 있습니다.\n\n21\n00:01:09.070 --> 00:01:12.243\n예제를 저장하고 다운로드하여 로봇에서 사용해 보세요.\n\n","lt":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Jeigu tik pradedate</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nir norite panagrinėti skirtingas roboto funkcijas\n\n3\n00:00:04.380 --> 00:00:07.470\narba kaip naudojami skirtingi blokai programoje \"VEXcode V5\",\n\n4\n00:00:07.470 --> 00:00:10.740\ngalite naudotis pavyzdiniais projektais.\n\n5\n00:00:10.740 --> 00:00:12.560\nNorėdami atverti pavyzdinį projektą,\n\n6\n00:00:12.560 --> 00:00:16.363\npasirinkite bylų meniu ir spustelėkite atverti pavyzdžius.\n\n7\n00:00:18.100 --> 00:00:22.010\nČia matysite daugelio skirtingų pavyzdinių projektų ikonas.\n\n8\n00:00:22.010 --> 00:00:24.700\nKiekviena ikona parodo skirtingą projektą,\n\n9\n00:00:24.700 --> 00:00:27.950\no jų spalvos atitinka blokų kategorijas.\n\n10\n00:00:27.950 --> 00:00:29.940\nNorėdami greitai rasti konkretų pavyzdį,\n\n11\n00:00:29.940 --> 00:00:32.863\ngalite naudoti filtro juostą.\n\n12\n00:00:35.140 --> 00:00:38.673\nTaip pat yra ypatingi pavyzdžiai, vadinami šablonais.\n\n13\n00:00:40.300 --> 00:00:42.780\nŠablonai naudojami tuščiam projektui sukurti\n\n14\n00:00:42.780 --> 00:00:45.400\nsu iš anksto nustatyta prietaiso konfigūracija.\n\n15\n00:00:45.400 --> 00:00:49.000\nJeigu naudojate standartinę roboto sistemą, pavyzdžiui, \"Clawbot\",\n\n16\n00:00:49.000 --> 00:00:50.040\ngalite naudoti šabloną,\n\n17\n00:00:50.040 --> 00:00:52.453\nkad greitai pradėtumėte dirbti nauja programa.\n\n18\n00:00:53.460 --> 00:00:56.663\nBet kokiam pavyzdžiui atverti, pasirinkite pavyzdį iš meniu.\n\n19\n00:00:59.240 --> 00:01:01.670\nAtvėrę pavyzdį, galite pridėti arba šalinti blokus,\n\n20\n00:01:01.670 --> 00:01:03.633\nkad sau pritaikytumėte pavyzdinį projektą.\n\n21\n00:01:09.070 --> 00:01:12.243\nIšsaugokite ir parsisiųskite pavyzdį, kad išbandytumėte su savo robotu.\n\n","lv":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Ja tikai nesen sākāt mācīties</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nun vēlaties izpētīt dažādas robota funkcijas,\n\n3\n00:00:04.380 --> 00:00:07.470\nvai kā tiek izmantoti dažādi VEXcode V5 bloki,\n\n4\n00:00:07.470 --> 00:00:10.740\nparaugu projekti būs lielisks veids, kā to iepazīt.\n\n5\n00:00:10.740 --> 00:00:12.560\nLai atvērtu parauga projektu,\n\n6\n00:00:12.560 --> 00:00:16.363\natlasiet izvēlni “File” (fails), pēc tam “Open Examples” (atvērt paraugus).\n\n7\n00:00:18.100 --> 00:00:22.010\nŠeit būs redzamas ikonas daudziem dažādiem paraugu projektiem.\n\n8\n00:00:22.010 --> 00:00:24.700\nKatra ikona atbilst atšķirīgam projektam,\n\n9\n00:00:24.700 --> 00:00:27.950\nun noteiktām krāsām, kas atbilst bloku kategorijām.\n\n10\n00:00:27.950 --> 00:00:29.940\nVariet izmantot arī filtrēšanas joslu,\n\n11\n00:00:29.940 --> 00:00:32.863\nlai ātri atrastu noteikta veida paraugu.\n\n12\n00:00:35.140 --> 00:00:38.673\nIr arī īpaša veida piemēri ar nosaukumu “Templates”.\n\n13\n00:00:40.300 --> 00:00:42.780\nTās izmanto, lai veidotu tukšu projektu,\n\n14\n00:00:42.780 --> 00:00:45.400\nkurā ir priekšiestatīti ierīces iestatījumi.\n\n15\n00:00:45.400 --> 00:00:49.000\nJa jūs izmantojiet standarta robotu, piemēram, Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nvar izmantot veidni,\n\n17\n00:00:50.040 --> 00:00:52.453\nlai ātri sāktu darbu ar jaunu programmu.\n\n18\n00:00:53.460 --> 00:00:56.663\nLai atvērtu jebkuru piemēru, atlasiet vienu no izvēlnes.\n\n19\n00:00:59.240 --> 00:01:01.670\nPēc atvēršanas variet pievienot un noņemt blokus,\n\n20\n00:01:01.670 --> 00:01:03.633\nlai parauga projektu veidotu pēc saviem ieskatiem.\n\n21\n00:01:09.070 --> 00:01:12.243\nSaglabājiet un lejupielādējiet paraugu, lai izmēģinātu to ar savu robotu.\n\n","nl":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor> Als u net begint </v>\n\n2\n00:00:01.950 --> 00:00:04.380\nen u verschillende robotgedragingen wilt onderzoeken,\n\n3\n00:00:04.380 --> 00:00:07.470\nof hoe verschillende blokken in VEXcode V5 worden gebruikt,\n\n4\n00:00:07.470 --> 00:00:10.740\nzijn voorbeeldprojecten een geweldige hulpbron.\n\n5\n00:00:10.740 --> 00:00:12.560\nOm een voorbeeldproject te openen\n\n6\n00:00:12.560 --> 00:00:16.363\nselecteer het bestandsmenu en kies Open Voorbeelden.\n\n7\n00:00:18.100 --> 00:00:22.010\nHier ziet uw iconen voor veel verschillende voorbeeldprojecten.\n\n8\n00:00:22.010 --> 00:00:24.700\nElk icoon vertegenwoordigt een ander project,\n\n9\n00:00:24.700 --> 00:00:27.950\nen is gekleurd volgens de blok categorieën.\n\n10\n00:00:27.950 --> 00:00:29.940\nU kunt ook de filterbalk gebruiken\n\n11\n00:00:29.940 --> 00:00:32.863\nom snel een bepaald type voorbeeld te vinden.\n\n12\n00:00:35.140 --> 00:00:38.673\nEr is ook een speciaal soort voorbeeld genaamd sjablonen.\n\n13\n00:00:40.300 --> 00:00:42.780\nSjablonen worden gebruikt om een leeg project\n\n14\n00:00:42.780 --> 00:00:45.400\nmet een vooraf ingestelde apparaat configuratie te maken.\n\n15\n00:00:45.400 --> 00:00:49.000\nAls u een standaard robotontwerp zoals de Klauwbot gebruikt,\n\n16\n00:00:49.000 --> 00:00:50.040\nkunt u een sjabloon gebruiken\n\n17\n00:00:50.040 --> 00:00:52.453\nom snel aan de slag te gaan met een nieuw programma.\n\n18\n00:00:53.460 --> 00:00:56.663\nSelecteer een voorbeeld uit het menu om een voorbeeld te openen.\n\n19\n00:00:59.240 --> 00:01:01.670\nEenmaal geopend, kunt u blokken toevoegen en verwijderen\n\n20\n00:01:01.670 --> 00:01:03.633\nom het voorbeeldproject uw eigen te maken.\n\n21\n00:01:09.070 --> 00:01:12.243\nBewaar en download het voorbeeld om het op uw robot te proberen.\n\n","pl":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Jeśli dopiero zaczynasz</v>\n\n2\n00:00:01.950 --> 00:00:04.380\ni chce odkrywać różne zachowania robotów,\n\n3\n00:00:04.380 --> 00:00:07.470\nlub jak używane są różne bloki VEXcode V5,\n\n4\n00:00:07.470 --> 00:00:10.740\nprzyda się wykorzystać przykładowe projekty.\n\n5\n00:00:10.740 --> 00:00:12.560\nAby otworzyć przykładowy projekt,\n\n6\n00:00:12.560 --> 00:00:16.363\nwybierz menu Plik i a następnie Otwórz przykłady.\n\n7\n00:00:18.100 --> 00:00:22.010\nTutaj zobaczysz ikony wielu przykładowych projektów.\n\n8\n00:00:22.010 --> 00:00:24.700\nKażda ikona reprezentuje inny projekt,\n\n9\n00:00:24.700 --> 00:00:27.950\ni są oznaczone kolorami zgodnie z kategoriami bloków.\n\n10\n00:00:27.950 --> 00:00:29.940\nMożesz również użyć paska filtrów\n\n11\n00:00:29.940 --> 00:00:32.863\nby szybko znaleźć konkretny przykład.\n\n12\n00:00:35.140 --> 00:00:38.673\nIstnieje również szczególny rodzaj przykładów zwanych szablonami.\n\n13\n00:00:40.300 --> 00:00:42.780\nSzablony są używane do tworzenia pustego projektu\n\n14\n00:00:42.780 --> 00:00:45.400\nz ustawieniem urządzenia.\n\n15\n00:00:45.400 --> 00:00:49.000\nJeśli używasz standardowego robota jak Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nmożesz użyć przykładowego szablonu\n\n17\n00:00:50.040 --> 00:00:52.453\naby szybko rozpocząć z nowym programem.\n\n18\n00:00:53.460 --> 00:00:56.663\nAby otworzyć dowolny przykład, wybierz jeden z menu.\n\n19\n00:00:59.240 --> 00:01:01.670\nPo otwarciu, możesz dodawać i usuwać bloki\n\n20\n00:01:01.670 --> 00:01:03.633\naby utworzyć własny przykładowy projekt.\n\n21\n00:01:09.070 --> 00:01:12.243\nZapisz i pobierz przykład, aby go wypróbować.\n\n","ru":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Если вы только познакомились</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nс программой и хотите изучить разное поведение робота\n\n3\n00:00:04.380 --> 00:00:07.470\nили использование других блоков,\n\n4\n00:00:07.470 --> 00:00:10.740\nвы можете использовать примеры проектов.\n\n5\n00:00:10.740 --> 00:00:12.560\nДля запуска примера проекта\n\n6\n00:00:12.560 --> 00:00:16.363\nоткройте меню Файл и выберите \"Открыть пример проекта\".\n\n7\n00:00:18.100 --> 00:00:22.010\nЗдесь находится множество иконок примеров проектов.\n\n8\n00:00:22.010 --> 00:00:24.700\nКаждая иконка олицетворяет свой проект\n\n9\n00:00:24.700 --> 00:00:27.950\nи раскрашена, исходя из категории блоков.\n\n10\n00:00:27.950 --> 00:00:29.940\nВы можете использовать фильтр\n\n11\n00:00:29.940 --> 00:00:32.863\nдля быстрого поиска примеров.\n\n12\n00:00:35.140 --> 00:00:38.673\nСуществует один специальный вид примеров под названием шаблон.\n\n13\n00:00:40.300 --> 00:00:42.780\nШаблоны используются для создания пустых проектов\n\n14\n00:00:42.780 --> 00:00:45.400\nс предварительной настройкой устройств.\n\n15\n00:00:45.400 --> 00:00:49.000\nЕсли вы используете стандартную модель робота,\n\n16\n00:00:49.000 --> 00:00:50.040\nвы можете использовать шаблон\n\n17\n00:00:50.040 --> 00:00:52.453\nдля быстрого запуска программы.\n\n18\n00:00:53.460 --> 00:00:56.663\nВыберите проект в меню для открытия.\n\n19\n00:00:59.240 --> 00:01:01.670\nПосле открытия можно добавлять и удалять блоки\n\n20\n00:01:01.670 --> 00:01:03.633\nдля индивидуальной настройки проекта.\n\n21\n00:01:09.070 --> 00:01:12.243\nСохраните и загрузите пример на робота для испытания.\n\n","th":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor> หากคุณเพิ่งเริ่มต้น </v>\n\n2\n00:00:01.950 --> 00:00:04.380\nและต้องการเรียนรู้เพิ่มเติมเกี่ยวกับพฤติกรรมต่างๆของหุ่นยนต์\n\n3\n00:00:04.380 --> 00:00:07.470\nหรือวิธีการใช้บล็อกต่างๆใน VEXcode V5\n\n4\n00:00:07.470 --> 00:00:10.740\nโปรเจ็คตัวอย่างเป็นแหล่งข้อมูลที่ดี\n\n5\n00:00:10.740 --> 00:00:12.560\nในการเปิดโปรเจ็คตัวอย่าง\n\n6\n00:00:12.560 --> 00:00:16.363\nเลือกเมนู File และเลือก Open Examples\n\n7\n00:00:18.100 --> 00:00:22.010\nที่นี่คุณจะเห็นไอคอนสำหรับโปรเจ็คตัวอย่างต่างๆมากมาย\n\n8\n00:00:22.010 --> 00:00:24.700\nแต่ละไอคอนแสดงถึงโปรเจ็คที่แตกต่างกัน\n\n9\n00:00:24.700 --> 00:00:27.950\nและสีใช้แสดงหมวดหมู่บล็อก\n\n10\n00:00:27.950 --> 00:00:29.940\nคุณยังสามารถใช้แถบตัวกรอง\n\n11\n00:00:29.940 --> 00:00:32.863\nเพื่อค้นหาตัวอย่างที่เฉพาะเจาะจงได้อย่างรวดเร็ว\n\n12\n00:00:35.140 --> 00:00:38.673\nนอกจากนี้ยังมีตัวอย่างประเภทพิเศษที่เรียกว่าเทมเพลต\n\n13\n00:00:40.300 --> 00:00:42.780\nเทมเพลตใช้เพื่อสร้างโปรเจ็กต์เปล่า\n\n14\n00:00:42.780 --> 00:00:45.400\nที่มีการกำหนดค่าอุปกรณ์ล่วงหน้าไว้แล้ว\n\n15\n00:00:45.400 --> 00:00:49.000\nหากคุณใช้หุ่นยนต์มาตรฐานเช่น Clawbot\n\n16\n00:00:49.000 --> 00:00:50.040\nคุณสามารถใช้เทมเพลตได้\n\n17\n00:00:50.040 --> 00:00:52.453\nเพื่อเริ่มต้นโปรแกรมใหม่ได้อย่างรวดเร็ว\n\n18\n00:00:53.460 --> 00:00:56.663\nหากต้องการเปิดตัวอย่างใดๆ ให้เลือกจากเมนู\n\n19\n00:00:59.240 --> 00:01:01.670\nเมื่อเปิดโปรเจ็คขึ้นมาแล้วคุณสามารถเพิ่มและลบบล็อกได้\n\n20\n00:01:01.670 --> 00:01:03.633\nเพื่อทำให้โปรเจ็คตัวอย่างกลายเป็นโปรเจ็คของคุณเอง\n\n21\n00:01:09.070 --> 00:01:12.243\nบันทึกและดาวน์โหลดตัวอย่างเพื่อทดลองใช้กับหุ่นยนต์ของคุณ\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Якщо ви початківець</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nі хочете дослідити принципи функціонування роботів,\n\n3\n00:00:04.380 --> 00:00:07.470\nабо способи використання блоків у VEXcode V5,\n\n4\n00:00:07.470 --> 00:00:10.740\nто приклади проєктів - чудовий ресурс.\n\n5\n00:00:10.740 --> 00:00:12.560\nЩоб відкрити приклад проєкту,\n\n6\n00:00:12.560 --> 00:00:16.363\nвиберіть меню \"Файл\" і натисніть \"Відкрити приклади\".\n\n7\n00:00:18.100 --> 00:00:22.010\nТут ви побачите зображення різних прикладів проєктів.\n\n8\n00:00:22.010 --> 00:00:24.700\nКожне зображення є прикладом проєкту,\n\n9\n00:00:24.700 --> 00:00:27.950\nі має колір відповідної категорії.\n\n10\n00:00:27.950 --> 00:00:29.940\nВи можете використати фільтри\n\n11\n00:00:29.940 --> 00:00:32.863\nдля швидкого пошуку певного типу прикладів.\n\n12\n00:00:35.140 --> 00:00:38.673\nТакож є спеціальний тип прикладів - шаблони.\n\n13\n00:00:40.300 --> 00:00:42.780\nШаблони потрібні для створення пустого проєкту\n\n14\n00:00:42.780 --> 00:00:45.400\nз під'єднаними і налаштованими пристроями.\n\n15\n00:00:45.400 --> 00:00:49.000\nЯкщо ви використовуєте стандартну конструкцію робота, як-от клешнебот,\n\n16\n00:00:49.000 --> 00:00:50.040\nможете використати шаблон\n\n17\n00:00:50.040 --> 00:00:52.453\nдля швидкого початку одразу з програми.\n\n18\n00:00:53.460 --> 00:00:56.663\nЩоб відкрити приклад, виберіть його з меню.\n\n19\n00:00:59.240 --> 00:01:01.670\nЩойно відкрили, можете додати або прибрати блоки\n\n20\n00:01:01.670 --> 00:01:03.633\nщоб зробити з прикладу власний проєкт.\n\n21\n00:01:09.070 --> 00:01:12.243\nЗберігайте і завантажуйте проєкти, щоб тестувати їх на роботі.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>Nếu bạn mới bắt đầu</v>\n\n2\n00:00:01.950 --> 00:00:04.380\nvà muốn khám phá các hành vi khác nhau của robot,\n\n3\n00:00:04.380 --> 00:00:07.470\nhoặc cách sử dụng các khối khác nhau trong VEXcode V5,\n\n4\n00:00:07.470 --> 00:00:10.740\ncác dự án ví dụ là một nguồn tài nguyên tuyệt vời.\n\n5\n00:00:10.740 --> 00:00:12.560\nĐể mở một dự án mẫu,\n\n6\n00:00:12.560 --> 00:00:16.363\nchọn menu Tệp và chọn Mở Ví dụ.\n\n7\n00:00:18.100 --> 00:00:22.010\nTại đây, bạn sẽ thấy các biểu tượng cho nhiều dự án mẫu khác nhau.\n\n8\n00:00:22.010 --> 00:00:24.700\nMỗi biểu tượng đại diện cho một dự án khác nhau,\n\n9\n00:00:24.700 --> 00:00:27.950\nvà được tô màu theo các loại khối.\n\n10\n00:00:27.950 --> 00:00:29.940\nBạn cũng có thể sử dụng thanh bộ lọc\n\n11\n00:00:29.940 --> 00:00:32.863\nđể nhanh chóng tìm thấy một loại ví dụ cụ thể.\n\n12\n00:00:35.140 --> 00:00:38.673\nNgoài ra còn có một loại ví dụ đặc biệt được gọi là mẫu.\n\n13\n00:00:40.300 --> 00:00:42.780\nCác mẫu được sử dụng để tạo một dự án trống\n\n14\n00:00:42.780 --> 00:00:45.400\nvới cấu hình thiết bị đặt trước.\n\n15\n00:00:45.400 --> 00:00:49.000\nNếu bạn đang sử dụng một phiên bản rô bốt tiêu chuẩn như Clawbot,\n\n16\n00:00:49.000 --> 00:00:50.040\nbạn có thể sử dụng một mẫu\n\n17\n00:00:50.040 --> 00:00:52.453\nđể nhanh chóng bắt đầu với một chương trình mới.\n\n18\n00:00:53.460 --> 00:00:56.663\nĐể mở bất kỳ ví dụ nào, hãy chọn một ví dụ từ menu.\n\n19\n00:00:59.240 --> 00:01:01.670\nSau khi mở, bạn có thể thêm và xóa các khối\n\n20\n00:01:01.670 --> 00:01:03.633\nđể làm cho dự án ví dụ của riêng bạn.\n\n21\n00:01:09.070 --> 00:01:12.243\nLưu và tải xuống ví dụ để thử trên rô bốt của bạn.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\ncrwdns96108:0crwdne96108:0\n\n2\n00:00:01.950 --> 00:00:04.380\ncrwdns96110:0crwdne96110:0\n\n3\n00:00:04.380 --> 00:00:07.470\ncrwdns96112:0crwdne96112:0\n\n4\n00:00:07.470 --> 00:00:10.740\ncrwdns96114:0crwdne96114:0\n\n5\n00:00:10.740 --> 00:00:12.560\ncrwdns96116:0crwdne96116:0\n\n6\n00:00:12.560 --> 00:00:16.363\ncrwdns96118:0crwdne96118:0\n\n7\n00:00:18.100 --> 00:00:22.010\ncrwdns96120:0crwdne96120:0\n\n8\n00:00:22.010 --> 00:00:24.700\ncrwdns96122:0crwdne96122:0\n\n9\n00:00:24.700 --> 00:00:27.950\ncrwdns96124:0crwdne96124:0\n\n10\n00:00:27.950 --> 00:00:29.940\ncrwdns96126:0crwdne96126:0\n\n11\n00:00:29.940 --> 00:00:32.863\ncrwdns96128:0crwdne96128:0\n\n12\n00:00:35.140 --> 00:00:38.673\ncrwdns96130:0crwdne96130:0\n\n13\n00:00:40.300 --> 00:00:42.780\ncrwdns96132:0crwdne96132:0\n\n14\n00:00:42.780 --> 00:00:45.400\ncrwdns96134:0crwdne96134:0\n\n15\n00:00:45.400 --> 00:00:49.000\ncrwdns96136:0crwdne96136:0\n\n16\n00:00:49.000 --> 00:00:50.040\ncrwdns96138:0crwdne96138:0\n\n17\n00:00:50.040 --> 00:00:52.453\ncrwdns96140:0crwdne96140:0\n\n18\n00:00:53.460 --> 00:00:56.663\ncrwdns96142:0crwdne96142:0\n\n19\n00:00:59.240 --> 00:01:01.670\ncrwdns96144:0crwdne96144:0\n\n20\n00:01:01.670 --> 00:01:03.633\ncrwdns96146:0crwdne96146:0\n\n21\n00:01:09.070 --> 00:01:12.243\ncrwdns96148:0crwdne96148:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.450 --> 00:00:01.950\n<v Instructor>如果您刚开始入门</v>\n\n2\n00:00:01.950 --> 00:00:04.380\n并且想要探究不同的机器人行为，\n\n3\n00:00:04.380 --> 00:00:07.470\n或者不同的指令块如何在VEXcode V5中应用，\n\n4\n00:00:07.470 --> 00:00:10.740\n样例程序是一个很好的资源。\n\n5\n00:00:10.740 --> 00:00:12.560\n欲打开样例程序，\n\n6\n00:00:12.560 --> 00:00:16.363\n选择“文件\"菜单并选中”打开样例“。\n\n7\n00:00:18.100 --> 00:00:22.010\n这里你将看到许多不同样例程序的图标。\n\n8\n00:00:22.010 --> 00:00:24.700\n每个图标代表一个不同的程序,\n\n9\n00:00:24.700 --> 00:00:27.950\n并按照指令块的分类用色彩标识。\n\n10\n00:00:27.950 --> 00:00:29.940\n您也可以使用过滤条\n\n11\n00:00:29.940 --> 00:00:32.863\n来快速查找某一类样例。\n\n12\n00:00:35.140 --> 00:00:38.673\n还有一类特殊的叫做“模板”的样例。\n\n13\n00:00:40.300 --> 00:00:42.780\n“模板”用于创建一个空白的程序\n\n14\n00:00:42.780 --> 00:00:45.400\n且有一组预设好的设备。\n\n15\n00:00:45.400 --> 00:00:49.000\n如果您正在使用一个标准机器人搭建，比如钳爪机器人，\n\n16\n00:00:49.000 --> 00:00:50.040\n您可以使用一个模板\n\n17\n00:00:50.040 --> 00:00:52.453\n来快速的开始一个新程序。\n\n18\n00:00:53.460 --> 00:00:56.663\n欲打一个开样例程序，从菜单里选择。\n\n19\n00:00:59.240 --> 00:01:01.670\n打开以后，你可以添加和删除指令块\n\n20\n00:01:01.670 --> 00:01:03.633\n将样例程序变成你自己的程序。\n\n21\n00:01:09.070 --> 00:01:12.243\n保存并下载样例到机器人上试试看。\n\n"}},{"thumb":"V5_Tutorial_usingHelp.jpg","mov":"V5_Blocks_UsingHelp_V2","description":"Using Help","filter":"","placeholder":false,"vimeo":"475901647","proglang":["blocks"],"progtarget":["physical","virtual"],"cc":{"en":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 contains helpful information about every block.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nFirst, open the Help window\n\n3\n00:00:06.430 --> 00:00:08.653\nby selecting the question mark icon.\n\n4\n00:00:13.960 --> 00:00:16.870\nNext, choose a block you would like to learn more about\n\n5\n00:00:16.870 --> 00:00:17.983\nby selecting it.\n\n6\n00:00:19.640 --> 00:00:21.510\nThe Help window contains information\n\n7\n00:00:21.510 --> 00:00:24.020\nabout how each block can be used.\n\n8\n00:00:24.020 --> 00:00:26.170\nTo find information for a different block,\n\n9\n00:00:26.170 --> 00:00:27.983\nsimply select another block.\n\n10\n00:00:29.180 --> 00:00:31.600\nYou can also find information for different blocks\n\n11\n00:00:31.600 --> 00:00:33.423\ndirectly from the toolbox.\n\n12\n00:00:34.930 --> 00:00:37.883\nTo hide the Help menu, select the arrow icon.\n\n13\n00:00:40.150 --> 00:00:42.503\nYou can open and close Help at any time.\n\n","ar":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->يحتوي على معلومات مفيدة حول كل مقطع.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nأولا، فتح نافذة المساعدة\n\n3\n00:00:06.430 --> 00:00:08.653\nعن طريق تحديد رمز علامة الاستفسارات.\n\n4\n00:00:13.960 --> 00:00:16.870\nبعد ذلك، اختر مقطع ترغب في معرفة المزيد عنه\n\n5\n00:00:16.870 --> 00:00:17.983\nعن طريق اختياره.\n\n6\n00:00:19.640 --> 00:00:21.510\nنافذة المساعدة تحتوي على معلومات\n\n7\n00:00:21.510 --> 00:00:24.020\nحول كيفية استخدام كل مقطع.\n\n8\n00:00:24.020 --> 00:00:26.170\nللعثور على معلومات لمقاطع مختلفة,\n\n9\n00:00:26.170 --> 00:00:27.983\nببساطة اختر مقطع آخر.\n\n10\n00:00:29.180 --> 00:00:31.600\nيمكنك أيضا الحصول على معلومات عن مقاطع مختلفة\n\n11\n00:00:31.600 --> 00:00:33.423\nمباشرة من قائمة الأدوات.\n\n12\n00:00:34.930 --> 00:00:37.883\nلإخفاء قائمة المساعدة، حدد رمز السهم.\n\n13\n00:00:40.150 --> 00:00:42.503\nيمكنك فتح وإغلاق المساعدة في أي وقت.\n\n","cs":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 obsahuje užitečné informace o každém bloku.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nNejprve otevři okno Nápověda\n\n3\n00:00:06.430 --> 00:00:08.653\nvybráním ikonky otazníku.\n\n4\n00:00:13.960 --> 00:00:16.870\nPotom vyber nějaký blok, o kterém se chceš dozvědět více,\n\n5\n00:00:16.870 --> 00:00:17.983\ntím, že ho označíš.\n\n6\n00:00:19.640 --> 00:00:21.510\nOkno Nápověda obsahuje informace\n\n7\n00:00:21.510 --> 00:00:24.020\no tom, jak může být každý blouk použit.\n\n8\n00:00:24.020 --> 00:00:26.170\nPro nalezení informací pro jiný blok,\n\n9\n00:00:26.170 --> 00:00:27.983\njednoduše vyber jiný blok.\n\n10\n00:00:29.180 --> 00:00:31.600\nInformace o různých blocích můžeš také najít\n\n11\n00:00:31.600 --> 00:00:33.423\npřímo z panelu nástrojů.\n\n12\n00:00:34.930 --> 00:00:37.883\nPro skrytí nabídky Nápověda vyber ikonku šipky.\n\n13\n00:00:40.150 --> 00:00:42.503\nNápovědu můžeš kdykoliv otevřít a zavřít.\n\n","es-419":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 contiene información útil sobre cada bloque.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nPrimero, abre la ventana de Ayuda\n\n3\n00:00:06.430 --> 00:00:08.653\nseleccionando el icono de signo de interrogación.\n\n4\n00:00:13.960 --> 00:00:16.870\nA continuación, elige un bloque sobre el que le gustaría aprender más\n\n5\n00:00:16.870 --> 00:00:17.983\nseleccionándolo.\n\n6\n00:00:19.640 --> 00:00:21.510\nLa ventana de Ayuda contiene información\n\n7\n00:00:21.510 --> 00:00:24.020\nacerca de cómo se puede usar cada bloque.\n\n8\n00:00:24.020 --> 00:00:26.170\nPara encontrar información para un bloque diferente,\n\n9\n00:00:26.170 --> 00:00:27.983\nsimplemente seleccione otro bloque.\n\n10\n00:00:29.180 --> 00:00:31.600\nTambién puede encontrar información para diferentes bloques\n\n11\n00:00:31.600 --> 00:00:33.423\ndirectamente desde la caja de herramientas.\n\n12\n00:00:34.930 --> 00:00:37.883\nPara ocultar el menú de Ayuda, seleccione el icono de flecha.\n\n13\n00:00:40.150 --> 00:00:42.503\nPuede abrir y cerrar Ayuda en cualquier momento.\n\n","es":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 contiene información útil sobre cada bloque.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nPrimero, abre la ventana de Ayuda\n\n3\n00:00:06.430 --> 00:00:08.653\nseleccionando el icono de signo de interrogación.\n\n4\n00:00:13.960 --> 00:00:16.870\nA continuación, elige un bloque sobre el que le gustaría aprender más\n\n5\n00:00:16.870 --> 00:00:17.983\nseleccionándolo.\n\n6\n00:00:19.640 --> 00:00:21.510\nLa ventana de Ayuda contiene información\n\n7\n00:00:21.510 --> 00:00:24.020\nacerca de cómo se puede usar cada bloque.\n\n8\n00:00:24.020 --> 00:00:26.170\nPara encontrar información para un bloque diferente,\n\n9\n00:00:26.170 --> 00:00:27.983\nsimplemente seleccione otro bloque.\n\n10\n00:00:29.180 --> 00:00:31.600\nTambién puede encontrar información para diferentes bloques\n\n11\n00:00:31.600 --> 00:00:33.423\ndirectamente desde la caja de herramientas.\n\n12\n00:00:34.930 --> 00:00:37.883\nPara ocultar el menú de Ayuda, seleccione el icono de flecha.\n\n13\n00:00:40.150 --> 00:00:42.503\nPuede abrir y cerrar Ayuda en cualquier momento.\n\n","fi":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v Instructor>VEXcode V5 näyttää ohjeita jokaisesta eri blokista.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nkun avaa Help -ikkunan\n\n3\n00:00:06.430 --> 00:00:08.653\nvalitsemalla Kysymysmerkki -painikkeen.\n\n4\n00:00:13.960 --> 00:00:16.870\nValitse blokki, josta haluat tietää enemmän\n\n5\n00:00:16.870 --> 00:00:17.983\nvalitsemalla se.\n\n6\n00:00:19.640 --> 00:00:21.510\nHelp -ikkuna sisältää\n\n7\n00:00:21.510 --> 00:00:24.020\nopastusta kaikista käytetyistä blokkityypeistä.\n\n8\n00:00:24.020 --> 00:00:26.170\nKun haluat tietää lisää jostain toisesta blokkityypistä\n\n9\n00:00:26.170 --> 00:00:27.983\nyksinkertaisesti valitse se.\n\n10\n00:00:29.180 --> 00:00:31.600\nSaat lisätietoa eri blokkityypeistä\n\n11\n00:00:31.600 --> 00:00:33.423\nsuoraan valitsemalla blokkityyppi myös työkaluista.\n\n12\n00:00:34.930 --> 00:00:37.883\nVoit piilottaa Help-ikkunan valitsemalla ison Nuolenpää oikealle -painikkeen.\n\n13\n00:00:40.150 --> 00:00:42.503\nVoit avata ja sulkea Help-ikkunan milloin tahansa ohjelmaa tehtäessä.\n\n","fr":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 contient des informations utiles sur chaque bloc.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nTout d'abord, ouvrez la fenêtre d'aide\n\n3\n00:00:06.430 --> 00:00:08.653\nen sélectionnant l'icône point d'interrogation.\n\n4\n00:00:13.960 --> 00:00:16.870\nEnsuite, choisissez un bloc sur lequel vous aimeriez en savoir plus\n\n5\n00:00:16.870 --> 00:00:17.983\nen le sélectionnant.\n\n6\n00:00:19.640 --> 00:00:21.510\nLa fenêtre d'aide contient des informations\n\n7\n00:00:21.510 --> 00:00:24.020\nsur la façon dont chaque bloc peut être utilisé.\n\n8\n00:00:24.020 --> 00:00:26.170\nPour trouver des informations sur un autre bloc,\n\n9\n00:00:26.170 --> 00:00:27.983\nsélectionnez simplement cet autre bloc.\n\n10\n00:00:29.180 --> 00:00:31.600\nVous pouvez aussi trouver des informations sur différents blocs\n\n11\n00:00:31.600 --> 00:00:33.423\ndirectement depuis la boîte à outils.\n\n12\n00:00:34.930 --> 00:00:37.883\nPour masquer le menu Aide, sélectionnez l'icône flèche.\n\n13\n00:00:40.150 --> 00:00:42.503\nVous pouvez ouvrir et fermer l'aide à tout moment.\n\n","ko":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5에는 모든 블록에 대한 유용한 정보가 포함되어 있습니다.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\n먼저 물음표 아이콘을 선택하여\n\n3\n00:00:06.430 --> 00:00:08.653\n도움말을 엽니다.\n\n4\n00:00:13.960 --> 00:00:16.870\n그리고 나서 궁금한 블록을 선택해 자세히\n\n5\n00:00:16.870 --> 00:00:17.983\n알아볼 수 있습니다.\n\n6\n00:00:19.640 --> 00:00:21.510\n도움말 창에는\n\n7\n00:00:21.510 --> 00:00:24.020\n각 블록 사용법에 대한 정보가 있습니다.\n\n8\n00:00:24.020 --> 00:00:26.170\n다른 블록에 대한 정보를 찾으려면\n\n9\n00:00:26.170 --> 00:00:27.983\n다른 블록을 선택하면 됩니다.\n\n10\n00:00:29.180 --> 00:00:31.600\n도구 상자에서 여러 블록에 대한\n\n11\n00:00:31.600 --> 00:00:33.423\n정보를 직접 찾을 수도 있습니다.\n\n12\n00:00:34.930 --> 00:00:37.883\n도움말 메뉴를 닫으려면 화살표 아이콘을 선택합니다.\n\n13\n00:00:40.150 --> 00:00:42.503\n언제든지 도움말을 열고 닫을 수 있습니다.\n\n","lt":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->Programoje \"VEXcode V5\" yra naudinga informacija apie kiekvieną bloką.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nPirmiausia, pasirinkdami klaustuko ikoną,\n\n3\n00:00:06.430 --> 00:00:08.653\natverkite langą \"Pagalba\".\n\n4\n00:00:13.960 --> 00:00:16.870\nPo to, pasirinkite bloką, apie kurį\n\n5\n00:00:16.870 --> 00:00:17.983\nnorite sužinoti daugiau.\n\n6\n00:00:19.640 --> 00:00:21.510\nLange \"Pagalba\" yra informacija\n\n7\n00:00:21.510 --> 00:00:24.020\napie tai, kaip galima naudoti kiekvieną bloką.\n\n8\n00:00:24.020 --> 00:00:26.170\nNorėdami rasti informaciją apie kitą bloką,\n\n9\n00:00:26.170 --> 00:00:27.983\npaprasčiausiai jį pasirinkite.\n\n10\n00:00:29.180 --> 00:00:31.600\nInformaciją apie kitus blokus taip pat galite rasti\n\n11\n00:00:31.600 --> 00:00:33.423\ntiesiogiai parankinėje.\n\n12\n00:00:34.930 --> 00:00:37.883\nNorėdami paslėpti meniu \"Pagalba\", spustelėkite rodyklės ikoną.\n\n13\n00:00:40.150 --> 00:00:42.503\nLangą \"Pagalba\" galite atverti ir užverti bet kuriuo metu.\n\n","lv":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 satur noderīgu informāciju par katru bloku.</v> \n\n2\n00:00:04.480 --> 00:00:06.430\nVispirms atveriet logu “Help” (palīdzība),\n\n3\n00:00:06.430 --> 00:00:08.653\nizvēloties jautājuma zīmes ikonu.\n\n4\n00:00:13.960 --> 00:00:16.870\nPēc tam izvēlieties bloku, par kuru vēlaties uzzināt vairāk,\n\n5\n00:00:16.870 --> 00:00:17.983\niezīmējot to.\n\n6\n00:00:19.640 --> 00:00:21.510\nLogs “Help” (palīdzība) satur informāciju\n\n7\n00:00:21.510 --> 00:00:24.020\npar to, kā var izmantot katru bloku.\n\n8\n00:00:24.020 --> 00:00:26.170\nLai atrastu informāciju par citu bloku,\n\n9\n00:00:26.170 --> 00:00:27.983\nvienkārši atlasiet citu bloku.\n\n10\n00:00:29.180 --> 00:00:31.600\nVar atrast arī informāciju par citiem blokiem,\n\n11\n00:00:31.600 --> 00:00:33.423\natlasot tos tieši rīklodziņā.\n\n12\n00:00:34.930 --> 00:00:37.883\nLai paslēptu izvēlni “Help” (palīdzība), atlasiet bultiņas ikonu.\n\n13\n00:00:40.150 --> 00:00:42.503\nPalīdzību var atvērt un aizvērt jebkurā laikā.\n\n","nl":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 bevat nuttige informatie over elk blok.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nOpen eerst het Help-venster\n\n3\n00:00:06.430 --> 00:00:08.653\ndoor het vraagtekenpictogram te selecteren.\n\n4\n00:00:13.960 --> 00:00:16.870\nKies vervolgens een blok waar u meer over wilt weten\n\n5\n00:00:16.870 --> 00:00:17.983\ndoor deze te selecteren.\n\n6\n00:00:19.640 --> 00:00:21.510\nHet Help-venster bevat informatie\n\n7\n00:00:21.510 --> 00:00:24.020\nover hoe elk blok kan worden gebruikt.\n\n8\n00:00:24.020 --> 00:00:26.170\nOm informatie over een ander blok te vinden,\n\n9\n00:00:26.170 --> 00:00:27.983\nselecteert u eenvoudig een ander blok.\n\n10\n00:00:29.180 --> 00:00:31.600\nU kunt ook rechtstreeks vanuit de werkbalk\n\n11\n00:00:31.600 --> 00:00:33.423\ninformatie over verschillende blokken vinden.\n\n12\n00:00:34.930 --> 00:00:37.883\nOm het Help-menu te verbergen, selecteert u het pijlpictogram.\n\n13\n00:00:40.150 --> 00:00:42.503\nU kunt Help op elk gewenst moment openen en sluiten.\n\n","pl":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 zawiera pomocne informacje o każdym bloku.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nNajpierw otwórz okno pomocy\n\n3\n00:00:06.430 --> 00:00:08.653\nwybierając ikonę znaku zapytania.\n\n4\n00:00:13.960 --> 00:00:16.870\nNastępnie wybierz blok, o którym chcesz dowiedzieć się więcej\n\n5\n00:00:16.870 --> 00:00:17.983\npoprzez wybranie go.\n\n6\n00:00:19.640 --> 00:00:21.510\nOkno Pomocy zawiera informacje\n\n7\n00:00:21.510 --> 00:00:24.020\njak każdy blok może być użyty.\n\n8\n00:00:24.020 --> 00:00:26.170\nAby znaleźć informacje dla innego bloku,\n\n9\n00:00:26.170 --> 00:00:27.983\npo prostu wybierz inny blok.\n\n10\n00:00:29.180 --> 00:00:31.600\nMożesz również znaleźć informacje dla różnych bloków\n\n11\n00:00:31.600 --> 00:00:33.423\nbezpośrednio w przyborniku.\n\n12\n00:00:34.930 --> 00:00:37.883\nAby ukryć menu Pomocy, wybierz ikonę strzałki.\n\n13\n00:00:40.150 --> 00:00:42.503\nMożesz otworzyć i zamknąć pomoc w każdej chwili.\n\n","ru":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 содержит полезную информацию о каждом блоке.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nДля начала, откройте меню помощи,\n\n3\n00:00:06.430 --> 00:00:08.653\nвыбрав иконку с вопросом справа.\n\n4\n00:00:13.960 --> 00:00:16.870\nДалее, выберите блок, о котором вы бы хотели узнать больше,\n\n5\n00:00:16.870 --> 00:00:17.983\nнажав на него.\n\n6\n00:00:19.640 --> 00:00:21.510\nОкно справки содержит информацию\n\n7\n00:00:21.510 --> 00:00:24.020\nпро каждый блок инструментария.\n\n8\n00:00:24.020 --> 00:00:26.170\nДля поиска информации о разных блоках\n\n9\n00:00:26.170 --> 00:00:27.983\nпросто выберите другой блок.\n\n10\n00:00:29.180 --> 00:00:31.600\nВы также можете найти информацию о других блоках\n\n11\n00:00:31.600 --> 00:00:33.423\nнапрямую из инструментария.\n\n12\n00:00:34.930 --> 00:00:37.883\nЗакройте меню помощи, нажав на иконку стрелки.\n\n13\n00:00:40.150 --> 00:00:42.503\nВы также можете открыть и закрыть помощь в любое время.\n\n","th":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v -> VEXcode V5 มีข้อมูลที่เป็นประโยชน์ของบล็อกทั้งหมด </v>\n\n2\n00:00:04.480 --> 00:00:06.430\nขั้นแรกให้เปิดหน้าต่าง Help window\n\n3\n00:00:06.430 --> 00:00:08.653\nโดยเลือกไอคอนเครื่องหมายคำถาม\n\n4\n00:00:13.960 --> 00:00:16.870\nจากนั้นเลือกบล็อกที่คุณต้องการเรียนรู้เพิ่มเติม\n\n5\n00:00:16.870 --> 00:00:17.983\nโดยการเลือกนี้\n\n6\n00:00:19.640 --> 00:00:21.510\nHelp window มีข้อมูล\n\n7\n00:00:21.510 --> 00:00:24.020\nเกี่ยวกับวิธีการใช้งานแต่ละบล็อก\n\n8\n00:00:24.020 --> 00:00:26.170\nหากต้องการค้นหาข้อมูลเกี่ยวกับบล็อกอื่น\n\n9\n00:00:26.170 --> 00:00:27.983\nเพียงแค่เลือกบล็อกอื่น\n\n10\n00:00:29.180 --> 00:00:31.600\nคุณยังสามารถค้นหาข้อมูลสำหรับบล็อกต่างๆ\n\n11\n00:00:31.600 --> 00:00:33.423\nได้โดยตรงจากกล่องเครื่องมือ\n\n12\n00:00:34.930 --> 00:00:37.883\nหากต้องการซ่อนเมนู Help ให้เลือกไอคอนลูกศร\n\n13\n00:00:40.150 --> 00:00:42.503\nคุณสามารถเปิดและปิดวิธีใช้ Help เมื่อใดก็ได้\n\n","uk-UA":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 містить корисну інформацію про кожен блок.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nСпочатку, відкрийте вікно допомоги,\n\n3\n00:00:06.430 --> 00:00:08.653\nнатиснувши на зображення знака питання.\n\n4\n00:00:13.960 --> 00:00:16.870\nДалі виберіть блок, про який ви хочете дізнатися більше,\n\n5\n00:00:16.870 --> 00:00:17.983\nнатиснувши на нього.\n\n6\n00:00:19.640 --> 00:00:21.510\nВікно допомоги містить інформацію\n\n7\n00:00:21.510 --> 00:00:24.020\nпро способи використання кожного блока.\n\n8\n00:00:24.020 --> 00:00:26.170\nЩоб глянути інформацію про інший блок,\n\n9\n00:00:26.170 --> 00:00:27.983\nпросто натисніть на інший блок.\n\n10\n00:00:29.180 --> 00:00:31.600\nВи можете знайти інформацію про різні блоки\n\n11\n00:00:31.600 --> 00:00:33.423\nбезпосередньо з набору блоків.\n\n12\n00:00:34.930 --> 00:00:37.883\nЩоб приховати меню допомоги, натисніть на зображення стрілки.\n\n13\n00:00:40.150 --> 00:00:42.503\nВи можете відкрити і закрити допомогу будь-коли.\n\n","vi-VN":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5 chứa thông tin hữu ích về mọi khối.</v>\n\n2\n00:00:04.480 --> 00:00:06.430\nĐầu tiên, hãy mở cửa sổ Trợ giúp\n\n3\n00:00:06.430 --> 00:00:08.653\nbằng cách chọn biểu tượng dấu chấm hỏi.\n\n4\n00:00:13.960 --> 00:00:16.870\nTiếp theo, chọn một khối bạn muốn tìm hiểu thêm về\n\n5\n00:00:16.870 --> 00:00:17.983\nbằng cách chọn nó.\n\n6\n00:00:19.640 --> 00:00:21.510\nCửa sổ Trợ giúp chứa thông tin\n\n7\n00:00:21.510 --> 00:00:24.020\nvề cách mỗi khối có thể được sử dụng.\n\n8\n00:00:24.020 --> 00:00:26.170\nĐể tìm thông tin cho một khối khác,\n\n9\n00:00:26.170 --> 00:00:27.983\nchỉ cần chọn một khối khác.\n\n10\n00:00:29.180 --> 00:00:31.600\nBạn cũng có thể tìm thông tin cho các khối khác nhau\n\n11\n00:00:31.600 --> 00:00:33.423\ntrực tiếp từ hộp công cụ.\n\n12\n00:00:34.930 --> 00:00:37.883\nĐể ẩn menu Trợ giúp, hãy chọn biểu tượng mũi tên.\n\n13\n00:00:40.150 --> 00:00:42.503\nBạn có thể mở và đóng Trợ giúp bất kỳ lúc nào.\n\n","yi-DE":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\ncrwdns96652:0crwdne96652:0\n\n2\n00:00:04.480 --> 00:00:06.430\ncrwdns96654:0crwdne96654:0\n\n3\n00:00:06.430 --> 00:00:08.653\ncrwdns96656:0crwdne96656:0\n\n4\n00:00:13.960 --> 00:00:16.870\ncrwdns96658:0crwdne96658:0\n\n5\n00:00:16.870 --> 00:00:17.983\ncrwdns96660:0crwdne96660:0\n\n6\n00:00:19.640 --> 00:00:21.510\ncrwdns96662:0crwdne96662:0\n\n7\n00:00:21.510 --> 00:00:24.020\ncrwdns96664:0crwdne96664:0\n\n8\n00:00:24.020 --> 00:00:26.170\ncrwdns96666:0crwdne96666:0\n\n9\n00:00:26.170 --> 00:00:27.983\ncrwdns96668:0crwdne96668:0\n\n10\n00:00:29.180 --> 00:00:31.600\ncrwdns96670:0crwdne96670:0\n\n11\n00:00:31.600 --> 00:00:33.423\ncrwdns96672:0crwdne96672:0\n\n12\n00:00:34.930 --> 00:00:37.883\ncrwdns96674:0crwdne96674:0\n\n13\n00:00:40.150 --> 00:00:42.503\ncrwdns96676:0crwdne96676:0\n\n","zh-CN":"WEBVTT\n\n1\n00:00:00.230 --> 00:00:04.480\n<v ->VEXcode V5包含关于每个指令块的有用信息。</v>\n\n2\n00:00:04.480 --> 00:00:06.430\n首先，通过点击问号图标\n\n3\n00:00:06.430 --> 00:00:08.653\n打开“帮助”窗口。\n\n4\n00:00:13.960 --> 00:00:16.870\n接下来，选中一个你想要了解更多的\n\n5\n00:00:16.870 --> 00:00:17.983\n指令块。\n\n6\n00:00:19.640 --> 00:00:21.510\n帮助窗口包含关于\n\n7\n00:00:21.510 --> 00:00:24.020\n每个指令块如何被应用的信息。\n\n8\n00:00:24.020 --> 00:00:26.170\n欲查找另一个不同指令块的信息，\n\n9\n00:00:26.170 --> 00:00:27.983\n只需点击那个指令块。\n\n10\n00:00:29.180 --> 00:00:31.600\n你也可以直接从工具箱\n\n11\n00:00:31.600 --> 00:00:33.423\n查找不同指令块的信息。\n\n12\n00:00:34.930 --> 00:00:37.883\n欲隐藏帮助窗口，点击箭头图标。\n\n13\n00:00:40.150 --> 00:00:42.503\n你可以随时打开和关闭帮助窗口。\n\n"}}]};/* harmony default export */ __webpack_exports__["default"] = (tutorialsDataV5);

